@protocol ArpSIDParameterLike <NSObject>
- (void)setValue:(float)value originator:(AUParameterObserverToken _Nullable)originator;
@end

@protocol ArpSIDParameterTreeLike <NSObject>
- (AUParameterObserverToken)tokenByAddingParameterObserver:(void (^ _Nonnull)(AUParameterAddress addr, AUValue val))observer;
- (void)removeParameterObserver:(AUParameterObserverToken)token;
- (id<ArpSIDParameterLike> _Nullable)parameterWithAddress:(AUParameterAddress)addr;
@end

@protocol ArpSIDPresetLike <NSObject>
@property(nonatomic, readonly) NSInteger number;
@property(nonatomic, readonly, copy) NSString* _Nullable name;
@end

@protocol ArpSIDDebugAdapterLike <NSObject>
- (void)readTelemetry:(ArpSIDTelemetry*)out;
- (void)readTelemetry:(ArpSIDTelemetry*)out includeScopes:(BOOL)includeScopes;
- (void)readTelemetry:(ArpSIDTelemetry*)out includeScopes:(BOOL)includeScopes includeC64Snapshot:(BOOL)includeC64Snapshot;
- (int)readOscilloscope:(float*)buf maxSamples:(int)maxSamples;
- (void)readVCOScope:(float*)vco0 vco1:(float*)vco1 vco2:(float*)vco2;
@optional
/// Fill *out with the 23-field audit-stabilization counter snapshot (GUI thread only).
- (void)readDiagnosticCounters:(ArpSID::GUI::ArpSIDDiagnosticCounterSnapshot*)out;
/// Wire the SIDCORE panel model to the kernel (GUI/main thread only). v550.
- (void)setSidCorePanelModel:(ArpSID::GUI::SidCorePanelModel*)model;
/// Read the current settings model into *out (GUI/main thread only). v551.
- (void)getSettingsModel:(ArpSID::GUI::SettingsPanelModel*)out;
/// Store a sanitized settings model (GUI/main thread only). v551.
- (void)setSettingsModel:(const ArpSID::GUI::SettingsPanelModel*)m;
/// Read the current KIT state blob into *out (GUI/main thread only). v560.
- (void)getKitStateBlob:(ArpSID::GUI::KitStateBlob*)out;
/// Store a sanitized KIT state blob (GUI/main thread only). v560.
- (void)setKitStateBlob:(const ArpSID::GUI::KitStateBlob*)b;
/// Read the current MIX model into *out (GUI/main thread only). v561.
- (void)getMixModel:(ArpSID::GUI::MixPanelModel*)out;
/// Store a sanitized MIX model (GUI/main thread only). v561.
- (void)setMixModel:(const ArpSID::GUI::MixPanelModel*)m;
/// DIGI state is a matched persistence unit; GUI callers may only use the
/// atomic model+sample-bank selectors below. The adapter still implements
/// legacy split selectors as fail-closed compatibility stubs in its private
/// category, but the public GUI/debug protocol deliberately does not expose
/// them as callable capability.
/// Atomically read a matched DIGI model + user-sample bank snapshot.
- (void)getDigiModel:(ArpSID::GUI::DigiPanelModel*)model
      sampleBank:(ArpSID::GUI::DigiSampleBankBlob*)bank;
/// Atomically publish a matched DIGI model + user-sample bank snapshot.
- (void)setDigiModel:(const ArpSID::GUI::DigiPanelModel*)model
      sampleBank:(const ArpSID::GUI::DigiSampleBankBlob*)bank;
/// Decode-pipeline entry: store a mono float sample into a DIGI slot. v596.
- (BOOL)setDigiUserSampleForSlot:(NSInteger)slot
                         samples:(const float*)samples
                      frameCount:(NSUInteger)frameCount
                      sampleRate:(double)sampleRate
                            name:(NSString* _Nullable)name;
/// Runtime DIGI authority mode/rate controls.
- (void)setDigiD418RuntimeMode:(uint8_t)mode rateHz:(uint32_t)rateHz;
- (void)getDigiD418RuntimeMode:(uint8_t*)mode rateHz:(uint32_t*)rateHz;
/// Queue a render-safe DIGI audition pad trigger from the GUI.
- (void)triggerDigiPadSlot:(uint8_t)slot velocity:(uint8_t)velocity;
/// Drain any render-deferred SID-808 bridge factory slot from a non-RT GUI/lifecycle point. v803.
- (BOOL)drainQueuedDrumBridgeSlotLoadNonRealtime;
/// MIDI pad mapping for DIGI. rootNote maps to slot 0; channelFilter 0..15 or 16=OMNI.
- (void)setDigiMidiPadRootNote:(uint8_t)rootNote channelFilter:(uint8_t)channelFilter;
- (void)getDigiMidiPadRootNote:(uint8_t*)rootNote channelFilter:(uint8_t*)channelFilter;
/// Clear DIGI $D418 HUD/counter telemetry without mutating audio state.
- (void)clearDigiD418RuntimeTelemetry;
/// direct 1:1 SID-engine output from AUv2. Bypasses AU mix FX/reverb/limiter/HiFi.
- (void)setPureSid1Q1OutputMode:(BOOL)enabled;
- (BOOL)pureSid1Q1OutputMode;
/// use AU's own pure SID engine stream as a DIGI REC source.
- (BOOL)startPureSid1Q1RecordCapture:(NSUInteger)maxFrames;
- (BOOL)copyAndStopPureSid1Q1RecordCapture:(float*)dst
                                  maxFrames:(NSUInteger)maxFrames
                                 frameCount:(NSUInteger*)frameCount
                                 sampleRate:(double*)sampleRate
                              droppedFrames:(NSUInteger*)droppedFrames;
- (BOOL)pureSid1Q1RecordCaptureStatusFrames:(NSUInteger*)frameCount
                                  sampleRate:(double*)sampleRate
                               droppedFrames:(NSUInteger*)droppedFrames
                                        peak:(float*)peak
                                         rms:(float*)rms;
@end

