// ─── Exact Pepto C64 Palette (sRGB) ──────────────────────────────────────────
#define C64_MAKE(r,g,b) [NSColor colorWithSRGBRed:(r) green:(g) blue:(b) alpha:1]
static __attribute__((unused)) NSColor* c64Black()     {static NSColor*c;if(!c)c=C64_MAKE(0,0,0);return c;}
static NSColor* c64White()     {static NSColor*c;if(!c)c=C64_MAKE(1,1,1);return c;}
static NSColor* c64Red()       {static NSColor*c;if(!c)c=C64_MAKE(.529,.188,.157);return c;}
static NSColor* c64Cyan()      {static NSColor*c;if(!c)c=C64_MAKE(.408,.769,.816);return c;}
static __attribute__((unused)) NSColor* c64Purple()    {static NSColor*c;if(!c)c=C64_MAKE(.573,.216,.573);return c;}
static NSColor* c64Green()     {static NSColor*c;if(!c)c=C64_MAKE(.306,.682,.243);return c;}
static NSColor* c64Blue()      {static NSColor*c;if(!c)c=C64_MAKE(.118,.094,.549);return c;}
static NSColor* c64Yellow()    {static NSColor*c;if(!c)c=C64_MAKE(.886,.886,.314);return c;}
static __attribute__((unused)) NSColor* c64Orange()    {static NSColor*c;if(!c)c=C64_MAKE(.573,.337,.078);return c;}
static NSColor* c64Brown()     {static NSColor*c;if(!c)c=C64_MAKE(.353,.235,.000);return c;}
static NSColor* c64LightRed()  {static NSColor*c;if(!c)c=C64_MAKE(.776,.435,.404);return c;}
static NSColor* c64DkGrey()    {static NSColor*c;if(!c)c=C64_MAKE(.333,.333,.333);return c;}
static NSColor* c64MidGrey()   {static NSColor*c;if(!c)c=C64_MAKE(.533,.533,.533);return c;}
static NSColor* c64LtGreen()   {static NSColor*c;if(!c)c=C64_MAKE(.596,.933,.529);return c;}
static NSColor* c64LtBlue()    {static NSColor*c;if(!c)c=C64_MAKE(.459,.420,.906);return c;}
static __attribute__((unused)) NSColor* c64LtGrey()    {static NSColor*c;if(!c)c=C64_MAKE(.733,.733,.733);return c;}

// Semantic — richer depth palette
static __attribute__((unused)) NSColor* colBG()        {return c64Blue();}
static __attribute__((unused)) NSColor* colBezel()     {return C64_MAKE(.055,.047,.275);}
static NSColor* colBorder()    {return c64LtBlue();}
static NSColor* colTitle()     {return c64Yellow();}
static NSColor* colLabel()     {return c64LtBlue();}
static NSColor* colValue()     {return c64LtGreen();}
static NSColor* colOscBg()     {return C64_MAKE(.01,.025,.01);}
static NSColor* colOscLine()   {return c64LtGreen();}
static NSColor* colMeterGn()   {return c64Green();}
static NSColor* colMeterYl()   {return c64Yellow();}
static NSColor* colMeterRd()   {return c64Red();}
static NSColor* colLEDOn()     {return c64LtGreen();}
static NSColor* colLEDOff()    {return c64Brown();}
static __attribute__((unused)) NSColor* colArpOn()     {return c64Yellow();}
static __attribute__((unused)) NSColor* colArpCur()    {return c64Cyan();}

// Deep panel background — very dark blue-black with subtle radial vignette tint
static NSColor* colPanelDeep() {static NSColor*c;if(!c)c=C64_MAKE(.028,.022,.13);return c;}
// Metallic knob body highlight
static NSColor* colKnobBody()  {static NSColor*c;if(!c)c=C64_MAKE(.12,.10,.38);return c;}
static NSColor* colKnobHi()    {static NSColor*c;if(!c)c=C64_MAKE(.18,.16,.56);return c;}
// Section inner shadow — creates depth illusion
static NSColor* colInnerShadow(){static NSColor*c;if(!c)c=C64_MAKE(0,0,0);return c;}


static NSColor* ArpSIDVoiceColor(int voiceIndex){
    switch(voiceIndex){
        case 0: return c64Cyan();
        case 1: return c64Yellow();
        default:return c64LtGreen();
    }
}
static __attribute__((unused)) NSColor* ArpSIDModeColor(int mode){
    switch(mode){
        case 0: return c64LtGreen();
        case 1: return c64Yellow();
        default:return c64Cyan();
    }
}
static __attribute__((unused)) NSColor* ArpSIDVoiceModeColor(int mode){
    switch(mode){
        case 0: return c64LtGreen();
        case 1: return c64Yellow();
        case 2: return c64Orange();
        default:return c64Cyan();
    }
}
static __attribute__((unused)) NSColor* ArpSIDModelColor(int sidModel){ return sidModel > 0 ? c64LtGreen() : c64Orange(); }
static __attribute__((unused)) NSColor* ArpSIDLaneColor(int lane){
    switch(lane & 3){
        case 0: return c64Cyan();
        case 1: return c64Yellow();
        case 2: return c64Orange();
        default:return c64LtGreen();
    }
}
static NSColor* ArpSIDForensicParamColor(int pid){
    using namespace ArpSID;
    switch(pid){
        case kParamForensicEnable:
        case kParamForensicIntensity:
        case kParamForensicStartupRandom:
        case kParamForensicDigifix8580:
        case kParamForensicRevision:
            return c64LtGreen();
        case kParamForensicTemp:
        case kParamForensicSupply:
        case kParamForensicClockJitterEnable:
        case kParamForensicClockJitter:
        case kParamForensicSupplyRippleEnable:
        case kParamForensicSupplyRipple:
        case kParamForensicThermalDriftEnable:
        case kParamForensicThermalDrift:
            return c64Cyan();
        case kParamForensicVoiceCrosstalkEnable:
        case kParamForensicVoiceCrosstalk:
        case kParamForensicExternalBleedEnable:
        case kParamForensicExternalBleed:
        case kParamForensicEnvelopeTDM:
        case kParamForensicFilterOhmic:
            return c64Yellow();
        case kParamForensicChipSeed:
        case kParamForensicD418Asymmetry:
        case kParamForensicSystemNoise:
        case kParamForensicMotherboard:
        case kParamForensicADCBleed:
        case kParamForensicBusCollision:
        case kParamForensicPOTInput:
            return c64Orange();
        default:
            return nil;
    }
}
static NSColor* ArpSIDRegisterGroupColor(int reg){
    if(reg < 7) return ArpSIDVoiceColor(0);
    if(reg < 14) return ArpSIDVoiceColor(1);
    if(reg < 21) return ArpSIDVoiceColor(2);
    if(reg < 25) return c64Purple();
    return c64Orange();
}
static NSFont* monoF(CGFloat s) {
    NSFont* f=[NSFont fontWithName:@"Menlo" size:s];
    return f ? f : [NSFont monospacedSystemFontOfSize:s weight:NSFontWeightRegular];
}
static NSFont* monoBF(CGFloat s){
    NSFont* f=[NSFont fontWithName:@"Menlo-Bold" size:s];
    return f ? f : [NSFont boldSystemFontOfSize:s];
}

static CGFloat ArpSIDChromeButtonSuggestedWidth(NSString* title, CGFloat fontSize, CGFloat minWidth, CGFloat horizontalPadding){
    if(title.length == 0) return minWidth;
    NSDictionary* attrs=@{NSFontAttributeName:monoBF(fontSize)};
    const CGFloat textW=ceil([title sizeWithAttributes:attrs].width);
    const CGFloat compactPadding=std::max<CGFloat>(12.f, horizontalPadding - 2.f);
    return std::max(minWidth, textW + compactPadding);
}

typedef NS_ENUM(NSInteger, ArpSIDChromeButtonRole){
    ArpSIDChromeButtonRoleNavigation = 0,
    ArpSIDChromeButtonRoleAccent,
    ArpSIDChromeButtonRoleUtility,
    ArpSIDChromeButtonRoleWarning,
    ArpSIDChromeButtonRoleDanger
};

static void ArpSIDStyleChromeButton(NSButton* button, ArpSIDChromeButtonRole role, CGFloat fontSize){
    if(!button) return;
    button.bezelStyle=NSBezelStyleRounded;
    button.font=monoBF(fontSize);
    button.controlSize=(fontSize <= 8.6f) ? NSControlSizeMini : NSControlSizeSmall;
    button.wantsLayer=YES;
    button.layer.cornerRadius=(fontSize <= 8.6f) ? 4.0f : 4.6f;
    button.layer.masksToBounds=NO;
    button.layer.borderWidth=.80f;
    button.layer.shadowOpacity=.14f;
    button.layer.shadowRadius=2.1f;
    button.layer.shadowOffset=CGSizeMake(0.f, -1.0f);
    NSColor* fill=nil;
    NSColor* border=nil;
    NSColor* shadow=nil;
    switch(role){
        case ArpSIDChromeButtonRoleNavigation:
            fill=[colPanelDeep() colorWithAlphaComponent:.94f];
            border=[colBorder() colorWithAlphaComponent:.74f];
            shadow=[c64Blue() colorWithAlphaComponent:.46f];
            break;
        case ArpSIDChromeButtonRoleAccent:
            fill=[c64Yellow() colorWithAlphaComponent:.28f];
            border=[c64Yellow() colorWithAlphaComponent:.78f];
            shadow=[c64Orange() colorWithAlphaComponent:.38f];
            break;
        case ArpSIDChromeButtonRoleWarning:
            fill=[c64Yellow() colorWithAlphaComponent:.24f];
            border=[c64Yellow() colorWithAlphaComponent:.76f];
            shadow=[c64Orange() colorWithAlphaComponent:.36f];
            break;
        case ArpSIDChromeButtonRoleDanger:
            fill=[c64Orange() colorWithAlphaComponent:.24f];
            border=[c64Orange() colorWithAlphaComponent:.74f];
            shadow=[c64Red() colorWithAlphaComponent:.38f];
            break;
        default:
            fill=[c64Cyan() colorWithAlphaComponent:.20f];
            border=[c64Cyan() colorWithAlphaComponent:.70f];
            shadow=[c64Blue() colorWithAlphaComponent:.34f];
            break;
    }
    button.layer.backgroundColor=fill.CGColor;
    button.layer.borderColor=border.CGColor;
    button.layer.shadowColor=shadow.CGColor;
    if([button respondsToSelector:@selector(setBezelColor:)]){
        NSColor* bezel=nil;
        switch(role){
            case ArpSIDChromeButtonRoleNavigation: bezel=[colBorder() colorWithAlphaComponent:.72f]; break;
            case ArpSIDChromeButtonRoleAccent: bezel=[c64Yellow() colorWithAlphaComponent:.84f]; break;
            case ArpSIDChromeButtonRoleWarning: bezel=[c64Yellow() colorWithAlphaComponent:.82f]; break;
            case ArpSIDChromeButtonRoleDanger: bezel=[c64Orange() colorWithAlphaComponent:.82f]; break;
            default: bezel=[c64Cyan() colorWithAlphaComponent:.76f]; break;
        }
        [(id)button setBezelColor:bezel];
    }
    if([button respondsToSelector:@selector(setContentTintColor:)]){
        NSColor* tint=nil;
        switch(role){
            case ArpSIDChromeButtonRoleAccent: tint=colTitle(); break;
            case ArpSIDChromeButtonRoleWarning: tint=[c64Yellow() blendedColorWithFraction:.18f ofColor:c64White()]; break;
            case ArpSIDChromeButtonRoleDanger: tint=[c64Orange() blendedColorWithFraction:.28f ofColor:c64White()]; break;
            case ArpSIDChromeButtonRoleNavigation: tint=[colLabel() colorWithAlphaComponent:.96f]; break;
            default: tint=[colValue() colorWithAlphaComponent:.95f]; break;
        }
        [(id)button setContentTintColor:tint];
    }
}

static NSButton* ArpSIDCreateFixedChromeButton(NSString* title, id target, SEL action, NSRect frame){
    // Logic's AUv2 OOP host runs this while ViewBridge is bootstrapping. Avoid
    // +buttonWithTitle:, which calls sizeToFit and enters macOS' SwiftUI-backed
    // NSButton sizing path before the remote view has settled.
    NSButton* button = [[NSButton alloc] initWithFrame:frame];
    button.title = title ? title : @"";
    button.target = target;
    button.action = action;
    [button setButtonType:NSButtonTypeMomentaryPushIn];
    return button;
}

static void ArpSIDFinalizeControlUX(NSView* root) {
    if (!root) return;
    for (NSView* view in root.subviews) {
        if ([view isKindOfClass:[NSButton class]]) {
            NSButton* button = (NSButton*)view;
            NSString* title = [button.title stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet];
            NSString* semantic = button.toolTip.length ? button.toolTip : title;
            if (semantic.length == 0) semantic = @"ArpSID action";
            if (button.accessibilityLabel.length == 0)
                button.accessibilityLabel = (title.length >= 2 ? title : semantic);
            if (button.accessibilityHelp.length == 0) button.accessibilityHelp = semantic;
            if (button.toolTip.length == 0 && button.action)
                button.toolTip = title.length ? [NSString stringWithFormat:@"%@ action", title]
                                              : NSStringFromSelector(button.action);
        } else if ([view isKindOfClass:[NSPopUpButton class]]) {
            NSPopUpButton* popup = (NSPopUpButton*)view;
            if (popup.accessibilityLabel.length == 0)
                popup.accessibilityLabel = popup.toolTip.length ? popup.toolTip : @"ArpSID selection";
            if (popup.accessibilityHelp.length == 0) popup.accessibilityHelp = popup.toolTip;
        } else if ([view isKindOfClass:[NSTextField class]]) {
            // Logic opens AUv2 editors through AUHostingServiceXPC/ViewBridge. On
            // macOS 15+ AppKit can initialize Writing Tools while laying out even
            // read-only text controls; ArpSID has a dense HUD/panel label tree, so
            // that first-layout soft-link shows up as seconds of host-visible UI
            // stall. These labels are status/readout controls, not prose editors.
            NSTextField* textField = (NSTextField*)view;
            if (@available(macOS 15.2, *)) {
                if ([textField respondsToSelector:@selector(setAllowsWritingTools:)])
                    textField.allowsWritingTools = NO;
            }
            if (@available(macOS 15.4, *)) {
                if ([textField respondsToSelector:@selector(setAllowsWritingToolsAffordance:)])
                    textField.allowsWritingToolsAffordance = NO;
            }
        } else if ([view isKindOfClass:[NSTextView class]]) {
            NSTextView* textView = (NSTextView*)view;
            if (@available(macOS 15.0, *)) {
                textView.writingToolsBehavior = NSWritingToolsBehaviorNone;
                textView.allowedWritingToolsResultOptions = 0;
            }
        } else if ([view isKindOfClass:[NSSlider class]] || [view isKindOfClass:[NSStepper class]]) {
            NSControl* control = (NSControl*)view;
            NSString* semantic = control.toolTip.length ? control.toolTip : control.identifier;
            if (semantic.length == 0) semantic = @"ArpSID realtime parameter";
            if (control.accessibilityLabel.length == 0) control.accessibilityLabel = semantic;
            if (control.accessibilityHelp.length == 0) control.accessibilityHelp = semantic;
        }
        ArpSIDFinalizeControlUX(view);
    }
}

static void ArpSIDSetPanelActiveGlow(NSView* panel, BOOL active) {
    if (!panel) return;
    panel.wantsLayer = YES;
    panel.layer.masksToBounds = NO;
    panel.layer.borderWidth = active ? 1.0f : 0.0f;
    panel.layer.borderColor = active ? [c64Cyan() colorWithAlphaComponent:.34f].CGColor : NSColor.clearColor.CGColor;
    panel.layer.shadowColor = active ? [c64Cyan() colorWithAlphaComponent:.52f].CGColor : NSColor.clearColor.CGColor;
    panel.layer.shadowOpacity = active ? .20f : 0.0f;
    panel.layer.shadowRadius = active ? 10.0f : 0.0f;
    panel.layer.shadowOffset = CGSizeZero;
}

static void ArpSIDConfigureHUDChrome(NSView* view, CGFloat bgAlpha){
    if(!view) return;
    view.wantsLayer=YES;
    view.layer.backgroundColor=[colOscBg() colorWithAlphaComponent:bgAlpha].CGColor;
    view.layer.cornerRadius=3.f;
    view.layer.borderWidth=.6f;
    view.layer.borderColor=[colBorder() colorWithAlphaComponent:.36f].CGColor;
}

static __attribute__((unused)) NSDictionary* ArpSIDAttrLabel(void){ return @{NSForegroundColorAttributeName:[colLabel() colorWithAlphaComponent:.95f],NSFontAttributeName:monoBF(10)}; }
static NSDictionary* ArpSIDAttrValue(void){ return @{NSForegroundColorAttributeName:colValue(),NSFontAttributeName:monoF(10)}; }
static __attribute__((unused)) NSDictionary* ArpSIDAttrValueBF(void){ return @{NSForegroundColorAttributeName:colValue(),NSFontAttributeName:monoBF(10)}; }
static __attribute__((unused)) NSDictionary* ArpSIDAttrTitle(void){ return @{NSForegroundColorAttributeName:colTitle(),NSFontAttributeName:monoBF(10.5f)}; }
