static __attribute__((unused)) void ArpSIDAppendLine(NSMutableAttributedString* s, NSArray<NSArray*>* parts){
    BOOL first = YES;
    for(NSArray* part in parts){
        if(!first) [s appendAttributedString:[[NSAttributedString alloc] initWithString:@"  " attributes:ArpSIDAttrValue()]];
        NSString* text = part.count > 0 ? part[0] : @"";
        NSDictionary* attr = part.count > 1 ? part[1] : ArpSIDAttrValue();
        [s appendAttributedString:[[NSAttributedString alloc] initWithString:text attributes:attr]];
        first = NO;
    }
    [s appendAttributedString:[[NSAttributedString alloc] initWithString:@"\n" attributes:ArpSIDAttrValue()]];
}


static inline float ArpSIDUIClamp01(float v, float fallback = 0.0f) {
    if (!std::isfinite(v)) return fallback;
    return std::clamp(v, 0.0f, 1.0f);
}

static inline float ArpSIDUIClampSigned(float v, float limit = 1.0f) {
    if (!std::isfinite(v)) return 0.0f;
    return std::clamp(v, -limit, limit);
}

static inline double ArpSIDUIFiniteDouble(double v, double fallback = 0.0) {
    return std::isfinite(v) ? v : fallback;
}


static inline CGFloat ArpSIDUIFiniteCGFloat(CGFloat v, CGFloat fallback = 0.0) {
    return std::isfinite((double)v) ? v : fallback;
}

static inline CGRect ArpSIDUIFinitePositiveBounds(CGRect b, CGFloat minW = 1.0, CGFloat minH = 1.0) {
    if (!std::isfinite((double)b.origin.x)) b.origin.x = 0.0;
    if (!std::isfinite((double)b.origin.y)) b.origin.y = 0.0;
    b.size.width = MAX(minW, ArpSIDUIFiniteCGFloat(b.size.width, minW));
    b.size.height = MAX(minH, ArpSIDUIFiniteCGFloat(b.size.height, minH));
    return b;
}

static inline BOOL ArpSIDUIHasDrawableArea(NSView* view) {
    if (!view) return NO;
    if (view.hidden) return NO;
    const NSRect b = view.bounds;
    if (!std::isfinite((double)b.size.width) || !std::isfinite((double)b.size.height)) return NO;
    return b.size.width >= 2.0 && b.size.height >= 2.0;
}

static inline int ArpSIDUIClampInt(int v, int lo, int hi, int fallback) {
    if (v < lo || v > hi) return fallback;
    return v;
}

static inline BOOL ArpSIDSetLabelStringIfNeeded(NSTextField* label, NSString* value) {
    if (!label) return NO;
    NSString* clean = value ? value : @"";
    if ([label.stringValue isEqualToString:clean]) return NO;
    label.stringValue = clean;
    return YES;
}

static inline BOOL ArpSIDSetLabelColorIfNeeded(NSTextField* label, NSColor* color) {
    if (!label || !color) return NO;
    if (label.textColor && [label.textColor isEqual:color]) return NO;
    label.textColor = color;
    return YES;
}

static NSString* ArpSIDMPKMiniTelemetrySummary(const ArpSIDTelemetry& tel) {
    NSMutableArray<NSString*>* parts = [NSMutableArray arrayWithCapacity:9];
    for (int i = 0; i < 8; ++i) {
        const char* label = ArpSID::sidAkaiMpkMiniDefaultKnobLabelByIndex(i);
        const float value = ArpSIDUIClamp01(tel.mpkKnobValue[i]) * 100.0f;
        [parts addObject:[NSString stringWithFormat:@"%s %.0f%%", label, value]];
    }
    if (tel.lastMappedCC >= 0) {
        const char* lastLabel = ArpSID::sidMappedRealtimeCcLabel((uint8_t)std::clamp(tel.lastMappedCC, 0, 127));
        const float lastValue = ArpSIDUIClamp01(tel.lastMappedCCValue) * 100.0f;
        if (lastLabel && lastLabel[0])
            [parts addObject:[NSString stringWithFormat:@"Last %s %.0f%%", lastLabel, lastValue]];
        else
            [parts addObject:[NSString stringWithFormat:@"Last CC%d %.0f%%", tel.lastMappedCC, lastValue]];
    }
    return [parts componentsJoinedByString:@"  "];
}

static NSString* ArpSIDMPKMiniDefaultMapSummaryString(void) {
