// Full topology label including engine for preset/UI display.
// This is distinct from the render-mode label (CLASSIC/SID-REG/DR-SID).
static inline NSString* ArpSIDVoiceTopologyLabel(int renderMode, int voiceMode) {
    if (renderMode == 1) return @"SID-REG";
    if (renderMode == 2) return @"DR-SID";
    // BitPerfect: name by voice topology so users understand "POLY" means
    // multi-voice BitPerfect, NOT a legacy single-SID authentic mode.
    switch (voiceMode) {
        case 1: return @"BP-MONO";
        case 2: return @"BP-LEGATO";
        case 3: return @"BP-UNISON";
        default: return @"BP-POLY";  // explicitly tagged BitPerfect-Poly
    }
}

static inline NSColor* ArpSIDWaveformColor(uint8_t ctrl) {
    if (ctrl & 0x80u) return c64LtBlue();
    if (ctrl & 0x40u) return c64Yellow();
    if (ctrl & 0x20u) return c64LtGreen();
    if (ctrl & 0x10u) return c64Cyan();
    return c64MidGrey();
}


static inline NSString* ArpSIDADSRString(uint8_t ad, uint8_t sr) {
    return [NSString stringWithFormat:@"A%X D%X S%X R%X", (ad >> 4) & 0x0Fu, ad & 0x0Fu, (sr >> 4) & 0x0Fu, sr & 0x0Fu];
}

static inline NSString* ArpSIDFilterModeString(uint8_t modeVol) {
    NSMutableArray<NSString*>* parts=[NSMutableArray array];
    if (modeVol & 0x10u) [parts addObject:@"LP"];
    if (modeVol & 0x20u) [parts addObject:@"BP"];
    if (modeVol & 0x40u) [parts addObject:@"HP"];
    if (modeVol & 0x80u) [parts addObject:@"3OFF"];
    return parts.count ? [parts componentsJoinedByString:@"|"] : @"DIRECT";
}

static inline NSString* ArpSIDRouteString(uint8_t route) {
    NSMutableArray<NSString*>* parts=[NSMutableArray array];
    if (route & 0x01u) [parts addObject:@"V1"];
    if (route & 0x02u) [parts addObject:@"V2"];
    if (route & 0x04u) [parts addObject:@"V3"];
    if (route & 0x08u) [parts addObject:@"EXT"];
    const int res = (int)((route >> 4) & 0x0Fu);
    NSString* src = parts.count ? [parts componentsJoinedByString:@"+"] : @"NONE";
    return [NSString stringWithFormat:@"%@  RES:%X", src, res];
}

static inline NSString* ArpSIDPatchSlotString(int bankSlot, int programNumber) {
    const int slot = std::clamp(bankSlot, 0, ArpSID::kCanonicalFactoryPatchSlotMax) + 1;
    const int prog = std::clamp(programNumber, 0, 127) + 1;
    return [NSString stringWithFormat:@"S%03d / P%03d", slot, prog];
}

static inline NSString* ArpSIDSafeFilenameStem(NSString* name, NSString* fallback) {
    NSString* candidate = (name.length > 0) ? name : fallback;
    if(candidate.length == 0) candidate = @"Patch";
    NSCharacterSet* illegal = [NSCharacterSet characterSetWithCharactersInString:@"/:\\\n\r\t"];
    NSArray<NSString*>* parts = [candidate componentsSeparatedByCharactersInSet:illegal];
    NSString* joined = [[parts filteredArrayUsingPredicate:[NSPredicate predicateWithFormat:@"length > 0"]] componentsJoinedByString:@" "];
    NSString* trimmed = [joined stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceAndNewlineCharacterSet]];
    return (trimmed.length > 0) ? trimmed : @"Patch";
}

static inline NSString* ArpSIDBoolFlagString(BOOL value, NSString* onText, NSString* offText) {
    return value ? onText : offText;
}

