static inline NSString* ArpSIDPercent12String(uint8_t hi, uint8_t lo) {
    const int raw = (((int)hi & 0x0F) << 8) | (int)lo;
    const float pct = std::clamp((float)raw / 4095.0f, 0.0f, 1.0f) * 100.0f;
    return [NSString stringWithFormat:@"%4.1f%%", pct];
}

static inline NSString* ArpSIDPercentNormString(float norm) {
