}

static inline int ArpSIDUIRoundPercent99(float norm) noexcept {
    const float clean = ArpSIDUIClamp01(norm);
    return std::clamp((int)std::lround(clean * 99.0f), 0, 99);
}

static inline CGFloat ArpSIDUIDynamicPanelInset(CGFloat width) noexcept {
