static inline CGFloat ArpSIDUIDynamicSideWidth(CGFloat width) noexcept {
    if (!std::isfinite((double)width) || width <= 0.0) return 74.0;
    return std::clamp<CGFloat>(std::floor(width * 0.0525), 64.0, 112.0);
}

