static NSString* ArpSIDRsidDowngradeReasonsString(uint64_t mask) {
    if (mask == 0u) return @"Downgrades: NONE";
    NSMutableArray<NSString*>* reasons = [NSMutableArray array];
    const auto append = [&](ArpSID::C64::RsidExactnessDowngrade bit, NSString* text) {
        if ((mask & static_cast<uint64_t>(bit)) != 0u) [reasons addObject:text];
    };
    append(ArpSID::C64::RsidExactnessDowngrade::NotRsid, @"NOT_RSID");
    append(ArpSID::C64::RsidExactnessDowngrade::Phi2NotActive, @"PHI2_NOT_ACTIVE");
    append(ArpSID::C64::RsidExactnessDowngrade::FallbackInit, @"FALLBACK_INIT");
    append(ArpSID::C64::RsidExactnessDowngrade::UnsupportedOpcode, @"UNSUPPORTED_OPCODE");
    append(ArpSID::C64::RsidExactnessDowngrade::ApproximateOpcode, @"APPROX_OPCODE");
    append(ArpSID::C64::RsidExactnessDowngrade::VicBusStealApprox, @"VIC_APPROX");
    append(ArpSID::C64::RsidExactnessDowngrade::TimedWriteOverflow, @"WRITE_OVERFLOW");
    append(ArpSID::C64::RsidExactnessDowngrade::DroppedMultiSidWrites, @"DROPPED_MULTI_SID");
    append(ArpSID::C64::RsidExactnessDowngrade::LegacyFallback, @"LEGACY_FALLBACK");
    append(ArpSID::C64::RsidExactnessDowngrade::MissingRealRoms, @"MISSING_REAL_ROMS");
    append(ArpSID::C64::RsidExactnessDowngrade::BasicStartupUnsupported, @"BASIC_UNSUPPORTED");
    append(ArpSID::C64::RsidExactnessDowngrade::CiaModelApprox, @"CIA_APPROX");
    append(ArpSID::C64::RsidExactnessDowngrade::SidReadApprox, @"SID_READ_APPROX");
    append(ArpSID::C64::RsidExactnessDowngrade::RmwSidWrite, @"RMW_SID_WRITE");
    append(ArpSID::C64::RsidExactnessDowngrade::LegacyCpuPlayback, @"LEGACY_CPU");
    append(ArpSID::C64::RsidExactnessDowngrade::SidHoleWrite, @"SID_HOLE_WRITE");
    append(ArpSID::C64::RsidExactnessDowngrade::OpenBusApprox, @"OPEN_BUS_APPROX");
    append(ArpSID::C64::RsidExactnessDowngrade::StrictRsidNotPhi2, @"STRICT_NOT_PHI2");
    append(ArpSID::C64::RsidExactnessDowngrade::RomIdentityUnverified, @"ROM_UNVERIFIED");
    append(ArpSID::C64::RsidExactnessDowngrade::InitBrkSentinel, @"INIT_BRK_SENTINEL");
    append(ArpSID::C64::RsidExactnessDowngrade::InvalidSidChipAccess, @"INVALID_SID_CHIP_ACCESS");
    return [NSString stringWithFormat:@"Downgrades: %@",
            [reasons componentsJoinedByString:@", "]];
}

// audit P1.11: physical-exactness blockers are distinct from the observed
// downgrade ledger above. They describe subsystems that are not declared
// cycle-physical regardless of whether a given tune hits an edge case, so the
// UI must present them separately and must never call a run "EXACT" while any
// blocker bit is set.
static NSString* ArpSIDRsidPhysicalBlockersString(uint64_t mask) {
    if (mask == 0u) return @"Blockers: NONE";
    NSMutableArray<NSString*>* reasons = [NSMutableArray array];
    const auto append = [&](ArpSID::C64::C64PhysicalExactnessBlocker bit, NSString* text) {
        if ((mask & static_cast<uint64_t>(bit)) != 0u) [reasons addObject:text];
    };
    append(ArpSID::C64::C64PhysicalExactnessBlocker::MissingRealRoms, @"MISSING_REAL_ROMS");
    append(ArpSID::C64::C64PhysicalExactnessBlocker::RomIdentityUnverified, @"ROM_UNVERIFIED");
    append(ArpSID::C64::C64PhysicalExactnessBlocker::Cia6526NotCycleExact, @"CIA_NOT_CYCLE_EXACT");
    append(ArpSID::C64::C64PhysicalExactnessBlocker::VicIINotCycleExact, @"VIC_NOT_CYCLE_EXACT");
    append(ArpSID::C64::C64PhysicalExactnessBlocker::SidReadbackModelApprox, @"SID_READBACK_APPROX");
    append(ArpSID::C64::C64PhysicalExactnessBlocker::OpenBusModelApprox, @"OPEN_BUS_MODEL_APPROX");
    append(ArpSID::C64::C64PhysicalExactnessBlocker::SidOpenBusApprox, @"SID_OPEN_BUS_APPROX");
    append(ArpSID::C64::C64PhysicalExactnessBlocker::ColorRamOpenBusApprox, @"COLOR_RAM_OPEN_BUS_APPROX");
    append(ArpSID::C64::C64PhysicalExactnessBlocker::PotXYApprox, @"POTXY_APPROX");
    append(ArpSID::C64::C64PhysicalExactnessBlocker::BasicStartupUnsupported, @"BASIC_STARTUP_UNSUPPORTED");
    append(ArpSID::C64::C64PhysicalExactnessBlocker::PsidCiaCompatibility, @"PSID_CIA_COMPAT");
    append(ArpSID::C64::C64PhysicalExactnessBlocker::LegacyMos6510PlaybackObserved, @"LEGACY_CPU_PLAYBACK");
    append(ArpSID::C64::C64PhysicalExactnessBlocker::LegacyMos6510PathPresent, @"LEGACY_CPU_PATH");
    append(ArpSID::C64::C64PhysicalExactnessBlocker::ObservedDowngradeLedger, @"OBSERVED_DOWNGRADE");
    return [NSString stringWithFormat:@"Blockers: %@",
            [reasons componentsJoinedByString:@", "]];
}

static inline NSString* ArpSIDDigiD418WarningString(uint8_t mode,
                                                     uint32_t blockedByIo,
                                                     uint32_t overflow,
                                                     uint32_t collisions,
                                                     uint32_t timelineResets,
                                                     uint32_t userUnavailable) {
    NSMutableArray<NSString*>* parts=[NSMutableArray array];
    #if defined(ARPSID_ENABLE_LEGACY_FLOAT_DIGI) && ARPSID_ENABLE_LEGACY_FLOAT_DIGI
    if(mode == 2u) [parts addObject:@"LEGACY FLOAT PATH ACTIVE — NOT C64 BUS AUTHENTIC"];
#endif
    if(blockedByIo > 0u) [parts addObject:[NSString stringWithFormat:@"IO BANK BLOCKED %u", (unsigned)blockedByIo]];
    if(overflow > 0u) [parts addObject:[NSString stringWithFormat:@"WRITE QUEUE OVERFLOW %u", (unsigned)overflow]];
    if(collisions > 0u) [parts addObject:[NSString stringWithFormat:@"SAME-PHI2 COLLISIONS %u", (unsigned)collisions]];
    if(timelineResets > 0u) [parts addObject:[NSString stringWithFormat:@"TIMELINE RESETS %u", (unsigned)timelineResets]];
    if(userUnavailable > 0u) [parts addObject:[NSString stringWithFormat:@"USER SAMPLE MISSING %u", (unsigned)userUnavailable]];
    if(parts.count == 0) return (mode == 1u) ? @"OK: fast private $D418 → SID volume DAC (no IO/open-bus)" : @"OK: C64-bus $D418 → SID volume DAC";
    return [parts componentsJoinedByString:@"  •  "];
}

