static inline NSString* ArpSIDUnifiedAudibleAuthorityLabel(ArpSID::ComponentFlavor flavor,
                                                           const ArpSIDTelemetry& tel) {
    const BOOL sid808Visible =
        flavor == ArpSID::ComponentFlavor::Sid808 ||
        tel.sid808BridgeContextActive ||
        ArpSIDUIClamp01(tel.sid808OutputPeak) > 0.001f;
    if (sid808Visible) {
        NSString* kit = (tel.sid808ConfiguredKit >= 0)
            ? [NSString stringWithFormat:@"KIT%03d", tel.sid808ConfiguredKit]
            : @"KIT---";
        NSString* state = tel.sid808SilentActiveSinceLastHit
            ? @"SILENT-ACTIVE"
            : (tel.sid808BridgeReplacedOutput
                ? @"REPL"
                : (tel.sid808BridgeContextActive ? @"FAILOPEN" : @"IDLE"));
        return [NSString stringWithFormat:@"AUTH SID808-BRIDGE %@ HIT%llu V%d PK %@ %@",
                kit,
                (unsigned long long)tel.sid808RoutedHitCount,
                std::max(0, tel.sid808ActiveVoiceCount),
                ArpSIDPercentNormString(tel.sid808OutputPeak),
                state];
    }
    if (tel.c64PsidRuntimeActive || tel.psidActive) return @"AUTH C64-PHI2";
    if (tel.digiPlayingVoices > 0 || ArpSIDUIClamp01(tel.digiOutputPeak) > 0.001f) return @"AUTH D418-DIGI";
    if (tel.drSidMode || tel.renderMode == 2) return @"AUTH DRSID";
    if (tel.renderMode == 1) return @"AUTH SIDREG";
    return @"AUTH BPE";
}

static inline NSString* ArpSIDSidRegisterShortNameForIndex(int idx) {
    static const char* kNames[30]={
        "LO1","HI1","PW1L","PW1H","CR1",
        "A1D1","S1R1",
        "LO2","HI2","PW2L","PW2H","CR2",
        "A2D2","S2R2",
        "LO3","HI3","PW3L","PW3H","CR3",
        "A3D3","S3R3",
        "FCLO","FCHI","FLTV","MVOL",
        "POTX","POTY","OSC3","ENV3","SYS"};
    return [NSString stringWithUTF8String:kNames[std::clamp(idx,0,29)]];
}

static inline NSString* ArpSIDSidRegisterAddressString(int idx) {
    return [NSString stringWithFormat:@"$D4%02X", std::clamp(idx,0,0x1D)];
}

static inline NSString* ArpSIDSidSystemBitsString(uint8_t sys) {
    NSMutableArray<NSString*>* parts=[NSMutableArray array];
    [parts addObject:((sys & 0x01u) != 0u) ? @"NTSC" : @"PAL"];
    [parts addObject:((sys & 0x02u) != 0u) ? @"8580" : @"6581"];
    if((sys & 0x04u) != 0u) [parts addObject:@"ADSR"];
    if((sys & 0x80u) != 0u) [parts addObject:@"FORENSIC"];
    return [parts componentsJoinedByString:@" · "];
}

