static inline bool ArpSIDFactoryDefinitionIsDrumAuthored(const ArpSID::PatchDefinition& def) noexcept {
    return def.usage.role == ArpSID::PatchRole::Drum ||
           def.usage.family == ArpSID::HistoricalFamilyId::DrumKit;
}

// Canonical factory-bank sub-type ranges (see forensic_patch_bank.cpp
// makeGeneralMidiDefinition): 0..79 synth/melodic, 80..119 DrSID grids,
// 120..149 SID-808 kits, 150..179 DIGI 4-bit kits.
static inline BOOL ArpSIDFactorySlotIsSynthType(NSInteger slot)  { return slot >= 0   && slot <= 79;  }
static inline BOOL ArpSIDFactorySlotIsDrSidType(NSInteger slot)  { return slot >= 80  && slot <= 119; }
static inline BOOL ArpSIDFactorySlotIsSid808Type(NSInteger slot) { return slot >= 120 && slot <= 149; }

// ALLOWED = which slots this flavor may legitimately hold/load. DrumMachine
// stays drum-authored, while dedicated SID808 is strict 120..149 so a restored
// DrSID/DIGI drum root cannot put the 808 bridge into a split-brain state.
static inline BOOL ArpSIDFactorySlotAllowedForFlavor(ArpSID::ComponentFlavor flavor, NSInteger slot) {
    const auto& defs = ArpSID::getFactoryPatchDefinitions();
    if (defs.empty()) return slot == 0;
    const NSInteger normalized = std::clamp(slot, (NSInteger)0, (NSInteger)ArpSID::kCanonicalFactoryPatchSlotMax);
    if ((size_t)normalized >= defs.size()) return NO;
    const bool isDrum = ArpSIDFactoryDefinitionIsDrumAuthored(defs[(size_t)normalized]);
    switch (flavor) {
        case ArpSID::ComponentFlavor::Hybrid:
            return YES;
        case ArpSID::ComponentFlavor::Instrument:
            return !isDrum;
        case ArpSID::ComponentFlavor::C64SidPlayer:
            return normalized == 0;
        case ArpSID::ComponentFlavor::Sid808:
            return ArpSIDFactorySlotIsSid808Type(normalized);
        case ArpSID::ComponentFlavor::DrumMachine:
            return isDrum;
        default:
            return YES;
    }
}

// VISIBLE = which slots the patch PICKER shows for this flavor. Strict per-type
// (DrSID→DrSID grids, SID-808→808 kits, Instrument→synth) so e.g. 808 only lists
// 808 kits. Display-only: never drives load/reconciliation, so it cannot reset a
// patch. Always a subset of ALLOWED.
static inline BOOL ArpSIDFactorySlotVisibleForFlavorUI(ArpSID::ComponentFlavor flavor, NSInteger slot) {
    if (!ArpSIDFactorySlotAllowedForFlavor(flavor, slot)) return NO;
    switch (flavor) {
        case ArpSID::ComponentFlavor::DrumMachine:  return ArpSIDFactorySlotIsDrSidType(slot);
        case ArpSID::ComponentFlavor::Sid808:       return ArpSIDFactorySlotIsSid808Type(slot);
        case ArpSID::ComponentFlavor::Instrument:   return ArpSIDFactorySlotIsSynthType(slot);
        case ArpSID::ComponentFlavor::C64SidPlayer: return slot == 0;
        default:                                    return YES;
    }
}

static inline NSInteger ArpSIDStartupFactorySlotForFlavorUI(ArpSID::ComponentFlavor flavor) {
    const auto& defs = ArpSID::getFactoryPatchDefinitions();
    if (flavor == ArpSID::ComponentFlavor::Sid808 && defs.size() > 120u && ArpSIDFactoryDefinitionIsDrumAuthored(defs[120])) {
        return 120;
    }
    if (flavor == ArpSID::ComponentFlavor::C64SidPlayer) return 0;
    if (flavor == ArpSID::ComponentFlavor::Instrument) {
        for (NSInteger slot = 0; slot < (NSInteger)defs.size(); ++slot) {
            if (ArpSIDFactorySlotAllowedForFlavor(flavor, slot)) return slot;
        }
        return 0;
    }
    if (ArpSID::componentFlavorIsDedicatedDrum(flavor)) {
        for (NSInteger slot = 0; slot < (NSInteger)defs.size(); ++slot) {
            if (ArpSIDFactorySlotAllowedForFlavor(flavor, slot)) return slot;
        }
        return 0;
    }
    return 0;
}

static inline void ArpSIDAppendOrderedFactorySlotIfAllowedUI(std::vector<NSInteger>& orderedSlots,
                                                             std::vector<bool>& seenSlots,
                                                             ArpSID::ComponentFlavor flavor,
                                                             NSInteger slot) {
    const NSInteger normalized = std::clamp(slot, (NSInteger)0, (NSInteger)ArpSID::kCanonicalFactoryPatchSlotMax);
    // Display order uses the strict VISIBLE filter (per-type), not the lenient
    // ALLOWED filter, so the picker lists only this flavor's own patch type.
    if (!ArpSIDFactorySlotVisibleForFlavorUI(flavor, normalized)) return;
    if (seenSlots[(size_t)normalized]) return;
    orderedSlots.push_back(normalized);
    seenSlots[(size_t)normalized] = true;
}

static std::vector<NSInteger> ArpSIDFactorySlotOrderForFlavorUI(ArpSID::ComponentFlavor flavor) {
    const auto& defs = ArpSID::getFactoryPatchDefinitions();
    std::vector<NSInteger> orderedSlots;
    orderedSlots.reserve(defs.size());
    std::vector<bool> seenSlots(ArpSID::kFactoryPatchSlotCount, false);
    if (flavor == ArpSID::ComponentFlavor::C64SidPlayer) {
        ArpSIDAppendOrderedFactorySlotIfAllowedUI(orderedSlots, seenSlots, flavor, 0);
        return orderedSlots;
    }
    if (flavor == ArpSID::ComponentFlavor::Sid808) {
        for (NSInteger slot = 120; slot <= 149; ++slot) {
            ArpSIDAppendOrderedFactorySlotIfAllowedUI(orderedSlots, seenSlots, flavor, slot);
        }
        static constexpr NSInteger kSid808LegacyCompatibilitySlots[] = {
            118, 119, 116, 117, 127, 47
        };
        for (NSInteger slot : kSid808LegacyCompatibilitySlots) {
            ArpSIDAppendOrderedFactorySlotIfAllowedUI(orderedSlots, seenSlots, flavor, slot);
        }
    }
    for (NSInteger slot = 0; slot < (NSInteger)defs.size(); ++slot) {
        ArpSIDAppendOrderedFactorySlotIfAllowedUI(orderedSlots, seenSlots, flavor, slot);
    }
#if !defined(NDEBUG)
    std::vector<bool> postSeen(ArpSID::kFactoryPatchSlotCount, false);
    for (NSInteger slot : orderedSlots) {
        if (slot >= 0 && slot < (NSInteger)postSeen.size()) {
            assert(!postSeen[(size_t)slot] && "factory slot UI order must not contain duplicates");
            postSeen[(size_t)slot] = true;
        }
    }
#endif
    return orderedSlots;
}

static inline BOOL ArpSIDFactorySlotIsSid808PriorityUI(NSInteger slot) {
    if (slot >= 120 && slot <= 149) return YES;
    switch (slot) {
        case 118:
        case 119:
        case 116:
        case 117:
        case 127:
        case 47:
            return YES;
        default:
            return NO;
    }
}

static NSString* ArpSIDSid808PriorityBadgeUI(NSInteger slot) {
    switch (slot) {
        case 120: return @"808 CORE";
        case 121: return @"808 DUB";
        case 122: return @"808 ROCK";
        case 123: return @"808 TRK";
        case 124: return @"808 TRACE";
        case 118: return @"808 WIDE";
        case 119: return @"808 CYM";
        case 116: return @"808 TAIKO";
        case 117: return @"808 TOM";
        case 127: return @"808 FX";
        case 47:  return @"808 TIMP";
        default:  return @"KIT";
    }
}

static inline BOOL ArpSIDParamIsBinarySwitch(int pid) {
    using namespace ArpSID;
    switch (pid) {
        case kParamOutputLimiter:
        case kParamForensicEnable:
        case kParamForensicStartupRandom:
        case kParamForensicClockJitterEnable:
        case kParamForensicSupplyRippleEnable:
        case kParamForensicThermalDriftEnable:
        case kParamForensicVoiceCrosstalkEnable:
        case kParamForensicExternalBleedEnable:
        case kParamForensicDigifix8580:
        case kParamSidExternalRcEnable:
        case kParamSidAdsrBug6581:
        case kParamArpEnable:
        case kParamArpLatch:
        case kParamLFOSync:
        case kParamLFO2Sync:
        case kParamLFO3Sync:
        case kParamLFO4Sync:
        case kParamDrSidEnable:
        case kParamVCO1LowFreqMode:
        case kParamVCO2LowFreqMode:
        case kParamVCO3LowFreqMode:
        case kParamVCO1SyncEnable:
        case kParamVCO2SyncEnable:
        case kParamVCO3SyncEnable:
        case kParamVCO1RingModEnable:
        case kParamVCO2RingModEnable:
        case kParamVCO3RingModEnable:
            return YES;
        default:
            return NO;
    }
}

static NSString* ArpSIDParamRangeString(int pid) {
    using namespace ArpSID;
    switch (pid) {
        case kParamSidChipRevision:
            return @"Range: MOS 6581 R2 / R3 / R4 or MOS 8580 R5";
        case kParamDrSidMachineModel:
            return @"Range: SID Drum Core or Analog X0X-8";
        case kParamSidOversamplingFactor:
            return @"Range: 1x / 2x / 4x / 8x internal oversampling";
        case kParamForensicTemp:
            return [NSString stringWithFormat:@"Range: %.1f °C .. %.1f °C",
                    (double)sidForensicTemperatureFromNormalized(0.0f),
                    (double)sidForensicTemperatureFromNormalized(1.0f)];
        case kParamForensicSupply:
            return [NSString stringWithFormat:@"Range: %.2f V .. %.2f V",
                    (double)sidForensicSupplyFromNormalized(0.0f),
                    (double)sidForensicSupplyFromNormalized(1.0f)];
        case kParamForensicChipSeed:
            return [NSString stringWithFormat:@"Range: seed %u .. %u",
                    sidForensicChipSeedFromNormalized(0.0f),
                    sidForensicChipSeedFromNormalized(1.0f)];
        case kParamSeqTempo:
            return [NSString stringWithFormat:@"Range: %.0f .. %.0f BPM", 20.0, 300.0];
        case kParamSeqLength:
        case kParamArpPatternLength:
            return @"Range: 1 .. 32 steps";
        case kParamProgram:
            return @"Range: factory identity mirror slots 1 .. 180";
        case kParamBankSlot:
            return @"Range: factory slots 1 .. 180";
        case kParamMasterTune:
            return @"Range: -100 .. +100 cents";
        default:
            if (ArpSIDParamIsBinarySwitch(pid)) return @"Range: OFF / ON";
            return @"Range: 0 .. 100% normalized control";
    }
}

static NSString* ArpSIDParamDefaultString(int pid) {
    using namespace ArpSID;
    if (pid < 0 || pid >= kNumParams) return @"";
    const float def = defaultNormalizedParamValue(pid);
    switch (pid) {
        case kParamSidChipRevision:
            return [NSString stringWithFormat:@"Default: %s", sidChipRevisionSelectorLabel(def)];
        case kParamDrSidMachineModel:
            return [NSString stringWithFormat:@"Default: %s", drSidMachineModelDisplayName(def)];
        case kParamSidOversamplingFactor:
            return [NSString stringWithFormat:@"Default: %s", sidOversamplingLabel(def)];
        case kParamForensicTemp:
            return [NSString stringWithFormat:@"Default: %.1f °C", (double)sidForensicTemperatureFromNormalized(def)];
        case kParamForensicSupply:
            return [NSString stringWithFormat:@"Default: %.2f V", (double)sidForensicSupplyFromNormalized(def)];
        case kParamForensicChipSeed:
            return [NSString stringWithFormat:@"Default: %u", sidForensicChipSeedFromNormalized(def)];
        case kParamSeqTempo:
            return [NSString stringWithFormat:@"Default: %.1f BPM", ArpSIDSeqTempoBpmForNorm(def)];
        case kParamSeqLength:
        case kParamArpPatternLength:
            return [NSString stringWithFormat:@"Default: %ld steps", (long)std::clamp((NSInteger)lround(def * 31.0f) + 1, (NSInteger)1, (NSInteger)32)];
        case kParamProgram:
        case kParamBankSlot:
            return [NSString stringWithFormat:@"Default: slot %ld", (long)std::clamp((NSInteger)ArpSID::canonicalFactorySlotFromNormalizedBankSlot(def) + 1, (NSInteger)1, (NSInteger)ArpSID::kCanonicalFactoryPatchSlotCount)];
        case kParamMasterTune:
            return [NSString stringWithFormat:@"Default: %+ld cents", (long)lround((def - 0.5f) * 200.0f)];
        default:
            if (ArpSIDParamIsBinarySwitch(pid)) return [NSString stringWithFormat:@"Default: %@", def > 0.5f ? @"ON" : @"OFF"];
            return [NSString stringWithFormat:@"Default: %@", ArpSIDPercentNormString(def)];
    }
}

static NSString* ArpSIDDefaultActionTooltip(NSString* title, NSString* actionName) {
    if ([actionName isEqualToString:@"_bankSavePatch:"]) return @"Save the current live patch as canonical .arpsid binary or JSON-authorable state.";
    if ([actionName isEqualToString:@"_bankLoadPatch:"]) return @"Load a single patch document into the current engine without replacing the whole visible bank grid.";
    if ([actionName isEqualToString:@"_bankSaveBank:"]) return @"Save the displayed v1 user-bank-compatible 128-slot subset as a canonical .arpsidbank file.";
    if ([actionName isEqualToString:@"_bankLoadBank:"]) return @"Load a bank file and repopulate the live slot grid from its imported patches.";
    if ([actionName isEqualToString:@"_bankSavePatchJSON:"]) return @"Export the current patch as JSON for inspection, interchange, or external tooling.";
    if ([actionName isEqualToString:@"_bankSaveBankJSON:"]) return @"Export the displayed bank grid as JSON while preserving authored slot metadata.";
    if ([actionName isEqualToString:@"_bankImportJSON:"]) return @"Import a JSON patch bank and apply its visible slots into the bank browser.";
    if ([actionName isEqualToString:@"_bankSaveClassicFactoryJSON:"]) return @"Export the shipped C64-auth factory library as JSON for offline browsing or diffing.";
    if ([actionName isEqualToString:@"_bankExportAll:"]) return @"Write every visible slot as an individual patch document into one target directory.";
    if ([actionName isEqualToString:@"_bankLoadFactory:"]) return @"Restore the active slot from the built-in authored factory bank.";
    if ([actionName isEqualToString:@"_openMIDIPreferencesFromHUD:"]) return @"Open MIDI device routing and the live MPK/CC monitor configuration.";
    if ([actionName isEqualToString:@"_drumArmDrSid:"]) return @"Arm DrSID / Analog X0X-8 mode from the HUD without changing tabs.";
    if ([actionName isEqualToString:@"_drumApplyMPKMiniMap:"]) return @"Apply the canonical AKAI MPK Mini control map to the current live bridge.";
    if ([actionName isEqualToString:@"_drumPlay:"]) return @"Start the internal drum sequencer or transport-follow playback.";
    if ([actionName isEqualToString:@"_drumStop:"]) return @"Stop the drum sequencer and flush transient held drum state.";
    if ([actionName isEqualToString:@"_drumOpenBank:"]) return @"Jump straight to the BANK tab for factory/user kit browsing and import-export.";
    if ([actionName isEqualToString:@"_c64LoadSidFile:"]) return @"Load a PSID/RSID .sid file into the render-owned C64 SID player runtime via a non-realtime handoff.";
    if ([actionName isEqualToString:@"_c64LoadBootstrap:"] || [actionName isEqualToString:@"_c64LoadProjectionBootstrap:"]) return @"Load a tiny deterministic C64/SIDCORE bootstrap into RAM, set the reset vector, boot it, and start realtime C64/SID-core execution.";
    if ([actionName isEqualToString:@"_c64PrevSubtune:"]) return @"Move to the previous PSID/RSID subtune and reload the cached SID image through the non-realtime handoff.";
    if ([actionName isEqualToString:@"_c64NextSubtune:"]) return @"Move to the next PSID/RSID subtune and reload the cached SID image through the non-realtime handoff.";
    if ([actionName isEqualToString:@"_c64EjectSidFile:"]) return @"Eject the loaded SID file and reset the C64 SID player runtime.";
    if ([actionName isEqualToString:@"_c64UnloadSidFile:"]) return @"Unload the current SID file while leaving the GUI and patch state intact.";
    if ([actionName isEqualToString:@"_c64Boot:"]) return @"Boot the render-owned C64 platform from the visible reset vector without changing the selected patch.";
    if ([actionName isEqualToString:@"_c64Start:"]) return @"Start bounded realtime 6510/CIA/VIC execution used by the SIDCORE/C64 bus mirror.";
    if ([actionName isEqualToString:@"_c64Stop:"]) return @"Stop realtime C64 CPU execution while keeping SIDCORE/C64 bus audio and mirror state intact.";
    if ([actionName isEqualToString:@"_c64Reset:"]) return @"Reset the C64 platform mirror, then boot from reset vector; does not become patch or audio authority.";
    if ([actionName isEqualToString:@"_sidCoreEnableForensicRealtime:"]) return @"Enable the forensic realtime panel controls and push intensity to full for SIDCORE/C64 bus inspection.";
    if ([actionName isEqualToString:@"_sidCoreSet8580Realtime:"]) return @"Switch the audible SID model to MOS 8580 R5 and enable the 8580 digi-fix path.";
    if ([actionName isEqualToString:@"_c64DebugClear:"]) return @"Clear the visible C64 debug event console.";
    if ([actionName isEqualToString:@"_c64DebugFilterAll:"]) return @"Show every C64 debug event category.";
    if ([actionName isEqualToString:@"_c64DebugFilterSid:"]) return @"Filter the C64 debug console to SID register and bus events.";
    if ([actionName isEqualToString:@"_c64DebugFilterMem:"]) return @"Filter the C64 debug console to memory-window change events.";
    if ([actionName isEqualToString:@"_c64DebugFilterCpu:"]) return @"Filter the C64 debug console to CPU, interrupt, and jam events.";
    if ([actionName isEqualToString:@"_c64DebugFilterIo:"]) return @"Filter the C64 debug console to CIA, IEC, tape, and ROM events.";
    if ([actionName isEqualToString:@"_c64DebugCopyVisible:"]) return @"Copy the visible C64 debug console lines to the clipboard.";
    if ([actionName isEqualToString:@"_c64DebugExportVisible:"]) return @"Export the visible C64 debug console lines to a text file.";
    if ([actionName isEqualToString:@"_c64DebugPauseToggle:"]) return @"Pause or resume live C64 debug console ingestion.";
    if ([actionName isEqualToString:@"_drumSaveUserKit:"]) return @"Capture the current drum settings into the user kit library.";
    if ([actionName isEqualToString:@"_drumInitAnalogKit:"]) return @"Reset the current drum model to the authored Analog X0X-8 baseline.";
