static NSString* ArpSIDTabTooltipForMode(NSInteger tab, NSInteger modeIndex, ArpSID::ComponentFlavor flavor) {
    if (flavor == ArpSID::ComponentFlavor::Instrument) {
        switch (tab) {
            case 0: return @"INSTR tab. Dedicated pure-instrument synth surface, scope, filter, and voice overview.";
            case 1: return @"LFO/ARP tab. Motion sources, arp timing, and host/internal sync for the pure instrument.";
            case 2: return @"SIDCORE/C64 own bus telemetry, clock, chip, and mode summaries.";
            case 3: return @"SID REG tab. Live register view, decode, and per-voice SID bus state.";
            case 4: return @"SEQ tab. Global step-sequencer and song-mode surface with swing, accent, and pattern chaining.";
            case 5: return @"FILTER tab. Enlarged filter response, input/output traces, and analog controls.";
            case 6: return @"PERF tab. Macro and shared performance controls for the pure instrument.";
            case 7: return @"FORENSIC tab. Deep analog-domain stress, bus, VCO, and filter diagnostics.";
            case 8: return @"SIDCORE tab. Core chip telemetry, raw register/state, and host/render authority.";
            case 9: return @"INST BANK tab. Instrument-only factory/user slot browser with grouped sub-banks.";
            case 10: return @"OPTS tab. Live utility actions plus auth/clock/output safety controls.";
            case 11: return @"C64 tab. Live C64 clock, CIA timer, SID bus authority, and PSID player state overview.";
            case 12: return @"HI-FI tab. Output-stage controls, reverb mix, limiter, and audio-quality enhancement settings.";
            case 13: return @"DRSID tab. Auxiliary C64 wavetable drum surface available from the instrument flavor.";
            case 14: return @"SETTINGS tab (v544). Audio engine selector, MIDI mapping preset, theme, language, and DrumEngineRouter enable switch.";
            case 15: return @"C64 STATE tab (v581). Live CPU/SID/CIA/memory inspector with PSID map, bus scopes, SIDCORE timeline, and audit counters.";
            case 16: return @"MIX tab (v548). 16-channel mixer with per-channel FX chain (EQ/transient/comp/saturate/bitcrush), send buses, and master limiter.";
            case 17: return @"KIT EDIT tab (v556). Drum-kit editor: 9-class selector + DrSID/SID-808/Digi engine target + user-slot name browser.";
            case 18: return @"DIGI tab (v564). $D418 volume-DAC sample player: 8 active slots, 32-step grid per slot, per-slot tune/start/length/volume/loop/reverse.";
        }
    }
    if (flavor == ArpSID::ComponentFlavor::Sid808) {
        switch (tab) {
            case 0: return @"MAIN tab. Shared synth scope, filter, and voice overview available beside the SID-808 surface.";
            case 1: return @"GROOVE tab. Host/internal sync, modulation, and sequencer timing for the dedicated SID-808 surface.";
