static inline NSInteger ArpSIDFactoryBankGroupForSlot(NSInteger slot) {
    if (slot >= 150 && slot <= 179) return 7;
    if (slot >= 120 && slot <= 149) return 6;
    if (slot >= 80 && slot <= 119) return 5;
    const NSInteger s = std::clamp(slot, (NSInteger)0, (NSInteger)ArpSID::kCanonicalFactoryPatchSlotMax);
    if (s < 16) return 0;
    if (s < 32) return 1;
    if (s < 48) return 2;
    if (s < 64) return 3;
    return 4;
}

static inline NSRange ArpSIDFactoryBankGroupRange(NSInteger group) {
    switch (std::clamp(group, (NSInteger)0, (NSInteger)7)) {
        case 0: return NSMakeRange(0, 16);
        case 1: return NSMakeRange(16, 16);
        case 2: return NSMakeRange(32, 16);
        case 3: return NSMakeRange(48, 16);
        case 4: return NSMakeRange(64, 16);
        case 5: return NSMakeRange(80, 40);
        case 6: return NSMakeRange(120, 30);
        case 7: return NSMakeRange(150, 30);
        default:return NSMakeRange(0, 16);
    }
}

static inline NSString* ArpSIDFactoryBankGroupLabel(NSInteger group) {
    switch (std::clamp(group, (NSInteger)0, (NSInteger)7)) {
        case 0: return @"KEYS";
        case 1: return @"CHRM";
        case 2: return @"BASS";
        case 3: return @"ORCH";
        case 4: return @"LEAD";
        case 5: return @"DRSID";
        case 6: return @"SID808";
        case 7: return @"DIGI";
        default:return @"KEYS";
    }
}

static inline NSColor* ArpSIDFactoryBankGroupColor(NSInteger group) {
    switch (std::clamp(group, (NSInteger)0, (NSInteger)7)) {
        case 0: return c64Cyan();
        case 1: return c64Yellow();
        case 2: return c64LtGreen();
        case 3: return c64LtBlue();
        case 4: return c64Orange();
        case 5: return c64Red();
        case 6: return c64Orange();
        case 7: return c64LtBlue();
        default:return c64Cyan();
    }
}

static inline NSString* ArpSIDFactoryBankGroupTooltip(NSInteger group) {
    switch (std::clamp(group, (NSInteger)0, (NSInteger)7)) {
        case 0: return @"KEYS bank. Slots 0..15: pianos, EPs, clavs, and early keyboard voices.";
        case 1: return @"CHRM bank. Slots 16..31: organs, guitars, plucks, and chromatic timbres.";
        case 2: return @"BASS bank. Slots 32..47: bass, low strings, and low-end authored slot group.";
        case 3: return @"ORCH bank. Slots 48..63: strings, ensemble, brass, and orchestral body slots.";
        case 4: return @"LEAD bank. Slots 64..79: reeds, pipes, synth leads, and focused solo voices.";
        case 5: return @"DRSID bank. Slots 80..119: canonical C64 wavetable/DrSID drum projection slots.";
        case 6: return @"SID808 bank. Slots 120..149: canonical SID-808 analog projection kits.";
        case 7: return @"DIGI bank. Slots 150..179: canonical Digi sample/4-bit drum kits.";
        default:return @"KEYS bank. Slots 0..15: pianos, EPs, clavs, and early keyboard voices.";
    }
}

