static NSString* ArpSIDTooltipForParam(int pid) {
    if (pid < 0 || pid >= ArpSID::kNumParams) return @"";
    const ArpSID::ParamInfo& info = ArpSID::kParamInfos[(size_t)pid];
    NSMutableArray<NSString*>* lines=[NSMutableArray array];
    [lines addObject:[NSString stringWithFormat:@"%@.", [NSString stringWithUTF8String:info.name ? info.name : "Parameter"]]];
    NSString* base=ArpSIDTooltipBaseForParam(pid);
    if(base.length > 0) [lines addObject:base];
    [lines addObject:ArpSIDParamRangeString(pid)];
    [lines addObject:ArpSIDParamDefaultString(pid)];
    [lines addObject:[NSString stringWithFormat:@"Automation: %@", info.automatable ? @"Host-writable realtime parameter" : @"Presentation / utility / mode metadata"]];
    return [lines componentsJoinedByString:@"\n"];
}

static NSString* ArpSIDKnobTooltipForParam(int pid) {
    NSString* parameterHelp=ArpSIDTooltipForParam(pid);
    NSString* interactionHelp=@"Knob: drag vertically or horizontally; Shift-drag/scroll for fine control; arrows adjust; Page Up/Down makes larger changes; Home, Option-click, double-click, or right-click resets.";
    return parameterHelp.length > 0
        ? [NSString stringWithFormat:@"%@\n%@", parameterHelp, interactionHelp]
        : interactionHelp;
}

