// Fix #10 / Section 9: Unified mode/exactness matrix.
// Shows: render path + topology + SID model source + DR-SID mode + RSID exactness.
// Format: "MODE:BP-POLY SID:8580(file) DRSID:Authentic RSID:EXACT"
static NSString* ArpSIDModeExactnessMatrixString(int renderMode,
                                                  int voiceMode,
                                                  int sidModelIs6581,
                                                  bool sidModelFromFile,
                                                  bool videoFromFile,
                                                  bool c64Pal,
                                                  int drSidPlaybackMode,
                                                  uint64_t rsidExact) {
    NSString* topo  = ArpSIDVoiceTopologyLabel(renderMode, voiceMode);
    NSString* model = [NSString stringWithFormat:@"%@%@",
                       sidModelIs6581 ? @"6581" : @"8580",
                       sidModelFromFile ? @"(file)" : @"(UI)"];
    NSString* pal = [NSString stringWithFormat:@"%@%@",
                     c64Pal ? @"PAL" : @"NTSC",
                     videoFromFile ? @"" : @"?"];
    NSString* rsid;
    switch (rsidExact) {
        case 1u: rsid = @"RSID:EXACT";  break;
        case 2u: rsid = @"RSID:PHI2";   break;
        default: rsid = @"RSID:—";       break;
    }
    NSString* drMode = (renderMode == 2)
        ? [NSString stringWithFormat:@"  DRSID:%@", ArpSIDDrSidPlaybackModeLabel(drSidPlaybackMode)]
        : @"";
    return [NSString stringWithFormat:@"MODE:%@  SID:%@  %@%@  %@",
            topo, model, pal, drMode, rsid];
}

static NSString* ArpSIDFlavorRealtimeHUDLine(ArpSID::ComponentFlavor flavor,
                                             const ArpSIDTelemetry& tel,
                                             BOOL scopeLive,
                                             float drumPeak,
                                             float filterInPeak,
                                             float filterOutPeak) {
    const float peak = std::max(ArpSIDUIClamp01(tel.peakL), ArpSIDUIClamp01(tel.peakR));
    const float seqBpm = std::clamp(std::isfinite(tel.seqTempoBpm) ? tel.seqTempoBpm : 120.0f, 20.0f, 400.0f);
    NSString* mode = ArpSIDRealtimeRenderModeLabel(tel.renderMode);
    NSString* scope = scopeLive ? @"SCOPE LIVE" : @"SCOPE IDLE";
    NSString* transport = tel.hostPlaying ? @"PLAY" : @"STOP";
    NSString* authority = ArpSIDUnifiedAudibleAuthorityLabel(flavor, tel);
    switch (flavor) {
        case ArpSID::ComponentFlavor::Instrument:
            return [NSString stringWithFormat:@"Pure Instrument  •  %@  •  %@  •  %@  •  V%d  MIDI %d  •  %@  •  PK %@  •  FILT %@/%@",
                    mode, transport, authority,
                    std::max(0, tel.activeVoices), tel.lastMidiNote, scope,
                    ArpSIDPercentNormString(peak), ArpSIDPercentNormString(filterInPeak), ArpSIDPercentNormString(filterOutPeak)];
        case ArpSID::ComponentFlavor::DrumMachine: {
            // B10: show DR-SID exactness/mode in HUD (Authentic/Clean/Overlay/Wavetable/Legacy).
            NSString* drSidMode = ArpSIDDrSidPlaybackModeLabel(tel.drSidPlaybackMode);
            return [NSString stringWithFormat:@"DrSID Drum Machine  •  %@  •  %@  •  %@  •  STEP %02d  •  %.1f BPM %@  •  %@  •  KIT PK %@  •  OUT %@",
                    transport, drSidMode, authority,
                    std::max(0, tel.seqStep) + 1, seqBpm, ArpSIDTempoSyncShortString(tel.seqFollowHost),
                    scope, ArpSIDPercentNormString(drumPeak), ArpSIDPercentNormString(peak)];
        }
        case ArpSID::ComponentFlavor::Sid808:
            return [NSString stringWithFormat:@"SID-808  •  %@  •  %@  •  X0X STEP %02d  •  %.1f BPM %@  •  %@  •  DRUM %@  •  BRIDGE %@  •  OUT %@",
                    transport, authority,
                    std::max(0, tel.seqStep) + 1, seqBpm, ArpSIDTempoSyncShortString(tel.seqFollowHost),
                    scope, ArpSIDPercentNormString(drumPeak),
                    ArpSIDPercentNormString(tel.sid808OutputPeak), ArpSIDPercentNormString(peak)];
        case ArpSID::ComponentFlavor::Hybrid:
        default:
            return [NSString stringWithFormat:@"ArpSID Classic  •  %@  •  %@  •  %@  •  V%d  MIDI %d  •  %@  •  PK %@  •  FILT %@/%@",
                    mode, transport, authority,
                    std::max(0, tel.activeVoices), tel.lastMidiNote, scope,
                    ArpSIDPercentNormString(peak), ArpSIDPercentNormString(filterInPeak), ArpSIDPercentNormString(filterOutPeak)];
    }
}

static inline int ArpSIDDrumLaneIndexForMidiNote(int note) {
    switch (ArpSID::sidGMDrumClassForNote((uint8_t)std::clamp(note, 0, 127))) {
        case ArpSID::SidGMDrumClass::Kick: return 0;
        case ArpSID::SidGMDrumClass::Snare: return 1;
        case ArpSID::SidGMDrumClass::ClosedHat: return 2;
        case ArpSID::SidGMDrumClass::OpenHat: return 3;
        case ArpSID::SidGMDrumClass::Clap: return 4;
        case ArpSID::SidGMDrumClass::Cowbell: return 5;
        case ArpSID::SidGMDrumClass::Tom: return 6;
        case ArpSID::SidGMDrumClass::Rim:
        default: return 7;
    }
}

static NSString* ArpSIDMatrixControlDisplayName(BOOL drSidMode, int pid) {
    const auto* def = ArpSID::sidParamMatrixRouteDefForControlPid(drSidMode, pid);
    if (!def) return nil;
    const char* base = ArpSID::sidParamMatrixTargetShortName(drSidMode, def->targetPid);
    const BOOL isSource = (def->sourcePid == pid);
    return [NSString stringWithFormat:@"%s %@", base, isSource ? @"Src" : @"Amt"];
}

static NSString* ArpSIDMatrixHUDSummary(BOOL drSidMode) {
    return drSidMode
        ? @"DrSID targets: KickTune KickDec SnrTone SnrSnap HatTune HatDec CowTune TomTune DrmVol"
        : @"Synth targets: VCFCut VCFRes V1Det V1PW V2Det V2PW V3Det V3PW Vol";
}

static __attribute__((unused)) inline int ArpSIDDrumCanonicalMidiNoteForLane(int lane) {
    static const int kNotes[8] = {36, 38, 42, 46, 39, 56, 47, 37};
    return kNotes[std::clamp(lane, 0, 7)];
}

static inline NSString* ArpSIDDrumShortLabelForLane(int lane) {
    static NSString* const kLabels[8] = {@"KICK",@"SNAR",@"CHAT",@"OHAT",@"CLAP",@"CBEL",@"TOM",@"RIM"};
    return kLabels[std::clamp(lane, 0, 7)];
}

// The drum quick-kit shortcut is a fixed 6-segment control. Slots, popup indices
// and labels are hand-authored parallel tables per flavor; deriving every array
// bound from this single constant (with a static_assert per table) prevents the
// classic parallel-array drift where one table gains/loses an entry and the
// stale `idx >= 6` bound then reads out of range or drops a segment.
static constexpr NSInteger kArpSIDDrumQuickKitSegments = 6;

static inline NSInteger ArpSIDDrumKitSlotForFlavorSegment(ArpSID::ComponentFlavor flavor, NSInteger idx) {
    if (flavor == ArpSID::ComponentFlavor::Sid808) {
        static const NSInteger kSlots[kArpSIDDrumQuickKitSegments] = {120, 121, 118, 119, 123, 124};
        static_assert(sizeof(kSlots)/sizeof(kSlots[0]) == (size_t)kArpSIDDrumQuickKitSegments, "SID808 quick-kit slot table size");
        if (idx < 0 || idx >= kArpSIDDrumQuickKitSegments) return -1;
        return kSlots[idx];
    }
    static const NSInteger kSlots[kArpSIDDrumQuickKitSegments] = {47, 116, 117, 118, 119, 127};
    static_assert(sizeof(kSlots)/sizeof(kSlots[0]) == (size_t)kArpSIDDrumQuickKitSegments, "DrSID quick-kit slot table size");
    if (idx < 0 || idx >= kArpSIDDrumQuickKitSegments) return -1;
    return kSlots[idx];
}

static inline NSInteger ArpSIDDrumKitIndexForFlavorSegment(ArpSID::ComponentFlavor flavor, NSInteger idx) {
    if (flavor == ArpSID::ComponentFlavor::Sid808) {
        static const NSInteger kIndices[kArpSIDDrumQuickKitSegments] = {10, 11, 15, 3, 13, 14};
        static_assert(sizeof(kIndices)/sizeof(kIndices[0]) == (size_t)kArpSIDDrumQuickKitSegments, "SID808 quick-kit index table size");
        if (idx < 0 || idx >= kArpSIDDrumQuickKitSegments) return -1;
        return kIndices[idx];
    }
    static const NSInteger kIndices[kArpSIDDrumQuickKitSegments] = {9, 1, 2, 10, 3, 4};
    static_assert(sizeof(kIndices)/sizeof(kIndices[0]) == (size_t)kArpSIDDrumQuickKitSegments, "DrSID quick-kit index table size");
    if (idx < 0 || idx >= kArpSIDDrumQuickKitSegments) return -1;
    return kIndices[idx];
}

static inline NSInteger ArpSIDDrumKitSegmentForFlavorSlot(ArpSID::ComponentFlavor flavor, NSInteger slot) {
    for (NSInteger i = 0; i < kArpSIDDrumQuickKitSegments; ++i)
        if (ArpSIDDrumKitSlotForFlavorSegment(flavor, i) == slot) return i;
    return -1;
}

static inline NSString* ArpSIDDrumQuickKitLabelForFlavorSegment(ArpSID::ComponentFlavor flavor, NSInteger idx) {
    if (flavor == ArpSID::ComponentFlavor::Sid808) {
        static NSString* const kLabels[kArpSIDDrumQuickKitSegments] = {@"808", @"DUB", @"WIDE", @"CYM", @"TRK", @"TRACE"};
        static_assert(sizeof(kLabels)/sizeof(kLabels[0]) == (size_t)kArpSIDDrumQuickKitSegments, "SID808 quick-kit label table size");
        if (idx < 0 || idx >= kArpSIDDrumQuickKitSegments) return @"----";
        return kLabels[idx];
    }
    static NSString* const kLabels[kArpSIDDrumQuickKitSegments] = {@"TIMP", @"TAIKO", @"M-TOM", @"SYNTH", @"RCYM", @"SHOT"};
    static_assert(sizeof(kLabels)/sizeof(kLabels[0]) == (size_t)kArpSIDDrumQuickKitSegments, "DrSID quick-kit label table size");
    if (idx < 0 || idx >= kArpSIDDrumQuickKitSegments) return @"----";
    return kLabels[idx];
}

static inline NSColor* ArpSIDDrumColorForLane(int lane) {
    switch (std::clamp(lane, 0, 7)) {
        case 0: return c64Yellow();
        case 1: return c64LightRed();
        case 2: return c64LtBlue();
        case 3: return c64Cyan();
        case 4: return c64Orange();
        case 5: return c64LtGreen();
        case 6: return c64Green();
        default: return c64White();
    }
}

static inline float ArpSIDCycleDrumAccentVelocity(float currentVel) {
    const float v=ArpSIDUIClamp01(currentVel, 0.85f);
    if(v < 0.60f) return 0.78f;
    if(v < 0.92f) return 1.00f;
    return 0.55f;
}

static inline NSString* ArpSIDDrumVelocityTag(float velocity) {
    const float v=ArpSIDUIClamp01(velocity);
    if(v >= 0.92f) return @"ACC";
    if(v >= 0.66f) return @"MID";
    if(v > 0.01f)  return @"GHO";
    return @"---";
}

struct ArpSIDDrumKitDescriptor {
    NSInteger slot = 0;
    const char* title = "";
    const char* subtitle = "";
    std::array<int, 16> padNotes{};
    std::array<int, 16> patternNotes{};
    std::array<float, 16> patternVelocities{};
    std::array<float, 16> patternGates{};
};

struct ArpSIDDrumKitToneProfile {
    float drumVolume = 0.84f;
    float kickTune = 0.44f;
    float kickDecay = 0.30f;
    float snareTone = 0.55f;
    float snareSnap = 0.70f;
    float hatTune = 0.72f;
    float hatDecay = 0.20f;
    float clapDecay = 0.26f;
    float cowbellTune = 0.74f;
    float cowbellDecay = 0.38f;
    float tomTune = 0.55f;
    // v967: keep the base tom decay in lockstep with the canonical factory
    // DrSID default (applyFactoryDrSidDefaults → kParamDrSidTomDecay 0.44f,
    // bumped in v909). The old 0.30f here made the on-screen "Standard" kit
    // play a shorter tom than the same kit recalled from the host program list.
    float tomDecay = 0.44f;
    float machineModel = 0.0f;
    float accentAmount = 0.68f;
    float outputDrive = 0.18f;
    float hatMetal = 0.62f;
    float clapSpread = 0.54f;
};

struct ArpSIDDrumKitMotionProfile {
    float seqTempo = 0.34f;
    float seqSwing = 0.05f;
    float lfo1Sync = 1.0f;
    float lfo1Rate = 0.18f;
    float lfo1Depth = 0.24f;
    float lfo2Sync = 0.0f;
    float lfo2Rate = 0.12f;
    float lfo2Depth = 0.08f;
};

