static inline NSInteger ArpSIDDrumKitCount(void) {
    return (NSInteger)kArpSIDDrumKits.size();
}

static inline __attribute__((unused)) BOOL ArpSIDDrumKitContainsPadNote(const ArpSIDDrumKitDescriptor* kit, NSInteger note) {
    if (!kit) return NO;
    for (int midi : kit->padNotes) {
        if (midi == note) return YES;
    }
    return NO;
}

static const ArpSIDDrumKitDescriptor* ArpSIDDrumKitAtIndex(NSInteger idx) {
    if (idx < 0 || idx >= ArpSIDDrumKitCount()) return nullptr;
    return &kArpSIDDrumKits[(size_t)idx];
}

static NSString* ArpSIDDrumKitPopupTitleAtIndex(NSInteger idx) {
    const ArpSIDDrumKitDescriptor* kit=ArpSIDDrumKitAtIndex(idx);
    if(!kit) return @"KIT";
    if(kit->slot < 0) return [NSString stringWithFormat:@"USER  ·  %s", kit->title];
    return [NSString stringWithFormat:@"%@  ·  %s  ·  S%03ld",
            ArpSIDSid808PriorityBadgeUI(kit->slot),
            kit->title,
            (long)(kit->slot + 1)];
}

static const ArpSIDDrumKitToneProfile* ArpSIDDrumKitToneProfileAtIndex(NSInteger idx) {
    if (idx < 0 || idx >= ArpSIDDrumKitCount()) return nullptr;
    return &kArpSIDDrumKitToneProfiles[(size_t)idx];
}

static const ArpSIDDrumKitMotionProfile* ArpSIDDrumKitMotionProfileAtIndex(NSInteger idx) {
    if (idx < 0 || idx >= ArpSIDDrumKitCount()) return nullptr;
    return &kArpSIDDrumKitMotionProfiles[(size_t)idx];
}

static NSInteger ArpSIDDrumKitIndexForSlot(NSInteger slot) {
    for (NSInteger i = 0; i < ArpSIDDrumKitCount(); ++i)
        if (kArpSIDDrumKits[(size_t)i].slot == slot) return i;
    return -1;
}

static inline NSString* ArpSIDDrumUserKitLibraryName(void) {
    return @"DrSID Kits";
}

static inline BOOL ArpSIDStringContainsCaseInsensitive(NSString* haystack, NSString* needle) {
    if(!haystack || !needle || haystack.length == 0 || needle.length == 0) return NO;
    return [haystack rangeOfString:needle options:NSCaseInsensitiveSearch].location != NSNotFound;
}

static inline BOOL ArpSIDPatchMetaLooksLikeDrumKit(const ArpSID::ArpSIDFilePatchMeta& meta,
                                                   const ArpSID::SidStateRootV1& root) {
    if (meta.role == (uint8_t)ArpSID::PatchRole::Drum) return YES;
    NSString* category = meta.category[0] ? [NSString stringWithUTF8String:meta.category] : @"";
    NSString* tags = meta.tags[0] ? [NSString stringWithUTF8String:meta.tags] : @"";
    if (ArpSIDStringContainsCaseInsensitive(category, @"drum") ||
        ArpSIDStringContainsCaseInsensitive(category, @"drsid") ||
        ArpSIDStringContainsCaseInsensitive(tags, @"drum") ||
        ArpSIDStringContainsCaseInsensitive(tags, @"drsid") ||
        ArpSIDStringContainsCaseInsensitive(tags, @"gm")) {
        return YES;
    }
    const float drSid = ArpSID::sidStateRootParamValue(root, (int)ArpSID::kParamDrSidEnable);
    const float synth = ArpSID::sidStateRootParamValue(root, (int)ArpSID::kParamSynthModeEnable);
    return drSid > 0.5f && synth <= 0.5f;
}

static inline NSString* ArpSIDDrumUserKitPopupTitleForObj(ArpSIDPatchMetaObj* meta,
                                                          NSString* fallbackName) {
    NSString* base = (meta.name.length > 0) ? meta.name : fallbackName;
    NSString* category = (meta.category.length > 0) ? meta.category : @"DrSID";
    return [NSString stringWithFormat:@"%@  ·  %@", base.length ? base : @"User Kit", category];
}

static inline ArpSIDPatchMetaObj* ArpSIDPatchMetaObjectFromFileMeta(const ArpSID::ArpSIDFilePatchMeta& meta) {
    ArpSIDPatchMetaObj* obj = [[ArpSIDPatchMetaObj alloc] init];
    obj.name = meta.name[0] ? [NSString stringWithUTF8String:meta.name] : @"";
    obj.author = meta.author[0] ? [NSString stringWithUTF8String:meta.author] : @"";
    obj.category = meta.category[0] ? [NSString stringWithUTF8String:meta.category] : @"";
    obj.tags = meta.tags[0] ? [NSString stringWithUTF8String:meta.tags] : @"";
    obj.chipModel = (NSInteger)meta.chip_model;
    obj.clockSystem = (NSInteger)meta.clock_system;
    obj.forensicEnabled = (meta.forensic_en != 0);
    obj.role = (NSInteger)meta.role;
    return obj;
}

static inline void ArpSIDSafeCopyMetaCString(char* dst, size_t dstSize, NSString* value) {
    if (!dst || dstSize == 0) return;
    std::memset(dst, 0, dstSize);
    if (!value.length) return;
    const char* utf8 = value.UTF8String;
    if (!utf8) return;
    std::snprintf(dst, dstSize, "%s", utf8);
}

static inline ArpSID::ArpSIDFilePatchMeta ArpSIDFileMetaFromPatchMetaObj(ArpSIDPatchMetaObj* obj) {
    ArpSID::ArpSIDFilePatchMeta meta{};
    if (!obj) return meta;
    ArpSIDSafeCopyMetaCString(meta.name, sizeof(meta.name), obj.name);
    ArpSIDSafeCopyMetaCString(meta.author, sizeof(meta.author), obj.author);
    ArpSIDSafeCopyMetaCString(meta.category, sizeof(meta.category), obj.category);
    ArpSIDSafeCopyMetaCString(meta.tags, sizeof(meta.tags), obj.tags);
    meta.chip_model = (uint8_t)std::clamp((int)obj.chipModel, 0, 2);
    meta.clock_system = (uint8_t)std::clamp((int)obj.clockSystem, 0, 1);
    meta.forensic_en = obj.forensicEnabled ? 1u : 0u;
    meta.role = (uint8_t)std::clamp((int)obj.role, 0, 255);
    return meta;
}

static inline BOOL ArpSIDPathUsesJSON(NSString* path) {
    return [[path.pathExtension lowercaseString] isEqualToString:@"json"];
}

static inline void ArpSIDCanonicalizePatchRootForPersistence(ArpSID::SidStateRootV1& root,
                                                             const ArpSID::ArpSIDFilePatchMeta& meta) {
    ArpSID::sidCanonicalizeTopLevelRenderModeParams(root);
    if (ArpSIDPatchMetaLooksLikeDrumKit(meta, root)) {
        ArpSID::sidSetStateRootParamValue(root, (int)ArpSID::kParamDrSidEnable, 1.0f);
        ArpSID::sidSetStateRootParamValue(root, (int)ArpSID::kParamSynthModeEnable, 0.0f);
    }
    ArpSID::sidEnsureSemanticParameterEntries(root);
}

static NSDictionary* ArpSIDJSONDictionaryFromFileMeta(const ArpSID::ArpSIDFilePatchMeta& meta) {
    return @{
        @"name": meta.name[0] ? [NSString stringWithUTF8String:meta.name] : @"",
        @"author": meta.author[0] ? [NSString stringWithUTF8String:meta.author] : @"",
        @"category": meta.category[0] ? [NSString stringWithUTF8String:meta.category] : @"",
        @"tags": meta.tags[0] ? [NSString stringWithUTF8String:meta.tags] : @"",
        @"chipModel": @(meta.chip_model),
        @"clockSystem": @(meta.clock_system),
        @"forensicEnabled": @((BOOL)(meta.forensic_en != 0)),
        @"role": @(meta.role)
    };
}

static ArpSID::ArpSIDFilePatchMeta ArpSIDFileMetaFromJSONDictionary(NSDictionary* dict) {
    ArpSID::ArpSIDFilePatchMeta meta{};
    if (![dict isKindOfClass:[NSDictionary class]]) return meta;
    ArpSIDSafeCopyMetaCString(meta.name, sizeof(meta.name), [dict[@"name"] isKindOfClass:[NSString class]] ? dict[@"name"] : @"");
    ArpSIDSafeCopyMetaCString(meta.author, sizeof(meta.author), [dict[@"author"] isKindOfClass:[NSString class]] ? dict[@"author"] : @"");
    ArpSIDSafeCopyMetaCString(meta.category, sizeof(meta.category), [dict[@"category"] isKindOfClass:[NSString class]] ? dict[@"category"] : @"");
    ArpSIDSafeCopyMetaCString(meta.tags, sizeof(meta.tags), [dict[@"tags"] isKindOfClass:[NSString class]] ? dict[@"tags"] : @"");
    meta.chip_model = (uint8_t)std::clamp((int)[dict[@"chipModel"] integerValue], 0, 2);
    meta.clock_system = (uint8_t)std::clamp((int)[dict[@"clockSystem"] integerValue], 0, 1);
    meta.forensic_en = [dict[@"forensicEnabled"] boolValue] ? 1u : 0u;
    meta.role = (uint8_t)std::clamp((int)[dict[@"role"] integerValue], 0, 255);
    return meta;
}

static NSString* ArpSIDBase64StateBlobFromRoot(const ArpSID::SidStateRootV1& rootIn) {
    ArpSID::SidStateRootV1 root = rootIn;
    ArpSID::sanitizePersistentStateRootForSerialization(root);
    const size_t blobCap = ArpSID::encodedSidStateRootBinarySize(root);
    if (blobCap == 0 || blobCap > ArpSID::kFilePatchBlobCap) return nil;
    std::vector<uint8_t> blob(blobCap);
    const size_t blobLen = ArpSID::encodeSidStateRootBinary(root, blob.data(), blobCap);
    if (blobLen == 0 || blobLen > blobCap) return nil;
    NSData* data = [NSData dataWithBytes:blob.data() length:blobLen];
    return [data base64EncodedStringWithOptions:0];
}

static BOOL ArpSIDRootFromBase64StateBlob(NSString* base64,
                                          ArpSID::SidStateRootV1& root,
                                          NSString** errorText) {
    if (![base64 isKindOfClass:[NSString class]] || base64.length == 0) {
        if (errorText) *errorText = @"Missing state blob";
        return NO;
    }
    NSData* data = [[NSData alloc] initWithBase64EncodedString:base64 options:0];
    if (data.length == 0 || data.length > ArpSID::kFilePatchBlobCap) {
        if (errorText) *errorText = @"Invalid or oversized base64 state blob";
        return NO;
    }
    if (!ArpSID::decodeSidStateRootBinary((const uint8_t*)data.bytes, (size_t)data.length, root)) {
        if (errorText) *errorText = @"State blob decode failed";
        return NO;
    }
    return YES;
}

static NSDictionary* ArpSIDJSONPatchDocumentFromRoot(const ArpSID::SidStateRootV1& rootIn,
                                                     const ArpSID::ArpSIDFilePatchMeta& metaIn) {
    ArpSID::SidStateRootV1 root = rootIn;
    ArpSID::ArpSIDFilePatchMeta meta = metaIn;
    ArpSIDCanonicalizePatchRootForPersistence(root, meta);
    NSString* blob = ArpSIDBase64StateBlobFromRoot(root);
    if (blob.length == 0) return nil;
    const BOOL isKit = ArpSIDPatchMetaLooksLikeDrumKit(meta, root);
    const float forensicEnable = ArpSID::sidGetStateRootParamValue(root, (int)ArpSID::kParamForensicEnable);
    const float forensicIntensity = ArpSID::sidGetStateRootParamValue(root, (int)ArpSID::kParamForensicIntensity);
    const float drSidEnable = ArpSID::sidGetStateRootParamValue(root, (int)ArpSID::kParamDrSidEnable);
    const float synthModeEnable = ArpSID::sidGetStateRootParamValue(root, (int)ArpSID::kParamSynthModeEnable);
    return @{
        @"ArpSIDFormat": @"PatchJSON",
        @"ArpSIDVersion": @1,
        @"kind": isKit ? @"DrSIDKit" : @"Patch",
        @"renderMode": @{
            @"drSidEnable": @(drSidEnable),
            @"synthModeEnable": @(synthModeEnable)
        },
        @"forensic": @{
            @"enabled": @((BOOL)(forensicEnable > 0.5f || meta.forensic_en != 0)),
            @"intensity": @(forensicIntensity)
        },
        @"meta": ArpSIDJSONDictionaryFromFileMeta(meta),
        @"stateBlobBase64": blob
    };
}


static BOOL ArpSIDJSONFiniteFloatForKey(NSDictionary* dict, NSString* key, float* out) {
    if (![dict isKindOfClass:[NSDictionary class]] || ![key isKindOfClass:[NSString class]]) return NO;
    id obj = dict[key];
    if (![obj respondsToSelector:@selector(doubleValue)]) return NO;
    const double d = [obj doubleValue];
    if (!std::isfinite(d)) return NO;
    if (out) *out = (float)d;
    return YES;
}

static BOOL ArpSIDJSONCheckStateParamNear(const ArpSID::SidStateRootV1& root, ArpSID::ParamID param, float expected, const char* label, NSString** errorText) {
    const float actual = ArpSID::sidGetStateRootParamValue(root, (int)param);
    if (!std::isfinite(actual) || std::fabs(actual - expected) > 0.0005f) {
        if (errorText) *errorText = [NSString stringWithFormat:@"JSON sidecar mismatch for %s: sidecar %.6f, state %.6f", label ? label : "param", (double)expected, (double)actual];
        return NO;
    }
    return YES;
}

// JSON sidecar mismatch for renderMode.drSidEnable
// JSON sidecar mismatch for forensic.intensity
static BOOL ArpSIDValidateJSONPatchSidecars(NSDictionary* doc, const ArpSID::SidStateRootV1& root, NSString** errorText) {
    NSDictionary* renderMode = [doc[@"renderMode"] isKindOfClass:[NSDictionary class]] ? doc[@"renderMode"] : nil;
    if (renderMode) {
        float dr = 0.0f;
        if (ArpSIDJSONFiniteFloatForKey(renderMode, @"drSidEnable", &dr) && !ArpSIDJSONCheckStateParamNear(root, ArpSID::kParamDrSidEnable, std::clamp(dr, 0.0f, 1.0f), "renderMode.drSidEnable", errorText)) return NO;
        float sm = 0.0f;
        if (ArpSIDJSONFiniteFloatForKey(renderMode, @"synthModeEnable", &sm) && !ArpSIDJSONCheckStateParamNear(root, ArpSID::kParamSynthModeEnable, std::clamp(sm, 0.0f, 1.0f), "renderMode.synthModeEnable", errorText)) return NO;
    }
    NSDictionary* forensic = [doc[@"forensic"] isKindOfClass:[NSDictionary class]] ? doc[@"forensic"] : nil;
    if (forensic) {
        float intensity = 0.0f;
        if (ArpSIDJSONFiniteFloatForKey(forensic, @"intensity", &intensity) && !ArpSIDJSONCheckStateParamNear(root, ArpSID::kParamForensicIntensity, std::clamp(intensity, 0.0f, 1.0f), "forensic.intensity", errorText)) return NO;
        id enabledObj = forensic[@"enabled"];
        if ([enabledObj respondsToSelector:@selector(boolValue)]) {
            const bool expectedOn = [enabledObj boolValue];
            const bool actualOn = ArpSID::sidGetStateRootParamValue(root, (int)ArpSID::kParamForensicEnable) > 0.5f;
            if (actualOn != expectedOn) { if (errorText) *errorText = @"JSON sidecar mismatch for forensic.enabled"; return NO; }
        }
    }
    return YES;
}

static BOOL ArpSIDParseJSONPatchDocument(NSDictionary* doc,
                                         ArpSID::SidStateRootV1& root,
                                         ArpSID::ArpSIDFilePatchMeta& meta,
                                         NSString** errorText) {
    if (![doc isKindOfClass:[NSDictionary class]]) {
        if (errorText) *errorText = @"Top-level JSON object is missing";
        return NO;
    }
    NSString* format = [doc[@"ArpSIDFormat"] isKindOfClass:[NSString class]] ? doc[@"ArpSIDFormat"] : @"";
    if (![format isEqualToString:@"PatchJSON"]) {
        if (errorText) *errorText = @"Not an ArpSID patch JSON file";
        return NO;
    }
    NSNumber* version = [doc[@"ArpSIDVersion"] respondsToSelector:@selector(integerValue)] ? doc[@"ArpSIDVersion"] : nil;
    if (!version || version.integerValue < 1 || version.integerValue > 1) {
        if (errorText) *errorText = @"Unsupported ArpSID patch JSON version";
        return NO;
    }
    NSString* kind = [doc[@"kind"] isKindOfClass:[NSString class]] ? doc[@"kind"] : @"Patch";
    const BOOL isPatchJSON = [kind isEqualToString:@"Patch"];
    const BOOL isDrSidKitJSON = [kind isEqualToString:@"DrSIDKit"];
    if (!isPatchJSON && !isDrSidKitJSON) {
        if (errorText) *errorText = [NSString stringWithFormat:@"Unsupported ArpSID patch JSON kind: %@", kind];
        return NO;
    }
    meta = ArpSIDFileMetaFromJSONDictionary([doc[@"meta"] isKindOfClass:[NSDictionary class]] ? doc[@"meta"] : @{});
    if (!ArpSIDRootFromBase64StateBlob(doc[@"stateBlobBase64"], root, errorText)) return NO;
    if (isDrSidKitJSON) {
        // JSON kind is import authority for DrSID kits. Apply it before sidecar
        // validation so stale blobs from older exports are normalized into a
        // canonical kit instead of failing sidecar validation or importing as a synth.
        meta.role = (uint8_t)ArpSID::PatchRole::Drum;
        if (meta.category[0] == 0) std::snprintf(meta.category, sizeof(meta.category), "%s", "DrSID Kit");
        ArpSID::sidSetStateRootParamValue(root, (int)ArpSID::kParamDrSidEnable, 1.0f);
        ArpSID::sidSetStateRootParamValue(root, (int)ArpSID::kParamSynthModeEnable, 0.0f);
        ArpSID::sidEnsureSemanticParameterEntries(root);
    }
    ArpSIDCanonicalizePatchRootForPersistence(root, meta);
    if (!ArpSIDValidateJSONPatchSidecars(doc, root, errorText)) return NO;
    return YES;
}

static NSDictionary* ArpSIDJSONBankDocumentFromVectors(const std::vector<ArpSID::SidStateRootV1>& patches,
                                                       const std::vector<ArpSID::ArpSIDFilePatchMeta>& metas,
                                                       NSString* bankName) {
    const size_t count = std::min(patches.size(), metas.size());
    NSMutableArray<NSDictionary*>* slots = [NSMutableArray arrayWithCapacity:count];
    for (size_t i = 0; i < count; ++i) {
        NSDictionary* patchDoc = ArpSIDJSONPatchDocumentFromRoot(patches[i], metas[i]);
        if (!patchDoc) continue;
        NSMutableDictionary* slotDoc = [patchDoc mutableCopy];
        slotDoc[@"slot"] = @(i);
        [slots addObject:slotDoc];
    }
    return @{
        @"ArpSIDFormat": @"BankJSON",
        @"ArpSIDVersion": @1,
        @"name": (bankName.length > 0) ? bankName : @"ArpSID Bank",
        @"slots": slots
    };
}

static inline float ArpSIDJSONClamp01(double v, double fallback = 0.0) {
    if (!std::isfinite(v)) v = fallback;
    return std::clamp((float)v, 0.0f, 1.0f);
}

static inline void ArpSIDCopyMetaCString(char* dst, size_t dstSize, NSString* value) {
    if (!dst || dstSize == 0) return;
    dst[0] = 0;
    if (![value isKindOfClass:[NSString class]] || value.length == 0) return;
    std::snprintf(dst, dstSize, "%s", value.UTF8String ? value.UTF8String : "");
}

static float ArpSIDWaveNormFromClassicJSON(NSString* wave) {
    NSString* w = [wave isKindOfClass:[NSString class]] ? wave.lowercaseString : @"";
    if ([w containsString:@"triangle_pulse"] || [w containsString:@"tri_pulse"]) return 0.34f;
    if ([w containsString:@"noise"]) return 1.0f;
    if ([w containsString:@"pulse"]) return 0.42f;
    if ([w containsString:@"saw"]) return 0.22f;
    if ([w containsString:@"triangle"]) return 0.10f;
    return 0.22f;
}

static void ArpSIDApplyClassicJSONVoice(ArpSID::SidStateRootV1& root, NSDictionary* voice, int index) {
    if (![voice isKindOfClass:[NSDictionary class]] || index < 0 || index > 2) return;
    using namespace ArpSID;
    const ParamID wavePid  = (index == 0) ? kParamVCO1Waveform    : (index == 1) ? kParamVCO2Waveform    : kParamVCO3Waveform;
    const ParamID pwPid    = (index == 0) ? kParamVCO1PulseWidth  : (index == 1) ? kParamVCO2PulseWidth  : kParamVCO3PulseWidth;
    const ParamID detPid   = (index == 0) ? kParamVCO1Detune      : (index == 1) ? kParamVCO2Detune      : kParamVCO3Detune;
    const ParamID lvlPid   = (index == 0) ? kParamVCO1Level       : (index == 1) ? kParamVCO2Level       : kParamVCO3Level;
    const ParamID syncPid  = (index == 0) ? kParamVCO1SyncEnable  : (index == 1) ? kParamVCO2SyncEnable  : kParamVCO3SyncEnable;
    const ParamID ringPid  = (index == 0) ? kParamVCO1RingModEnable : (index == 1) ? kParamVCO2RingModEnable : kParamVCO3RingModEnable;
    sidSetStateRootParamValue(root, (int)wavePid, ArpSIDWaveNormFromClassicJSON(voice[@"wave"]));
    id pw = voice[@"pw"];
    if ([pw respondsToSelector:@selector(doubleValue)]) sidSetStateRootParamValue(root, (int)pwPid, ArpSIDJSONClamp01([pw doubleValue] / 4095.0, 0.5));
    id det = voice[@"detune"];
    if ([det respondsToSelector:@selector(doubleValue)]) sidSetStateRootParamValue(root, (int)detPid, ArpSIDJSONClamp01(0.5 + ([det doubleValue] / 48.0), 0.5));
    // Optional per-voice mixer level (0..15, default full). Voices that are not
    // present in the JSON sound are left at 0 (zeroed by the caller before the
    // present voices are applied), so a single-oscillator patch stays clean
    // instead of inheriting the seed slot's helper oscillators.
    id lvl = voice[@"level"];
    const float lvlNorm = [lvl respondsToSelector:@selector(doubleValue)]
        ? ArpSIDJSONClamp01([lvl doubleValue] / 15.0, 1.0)
        : 1.0f;
    sidSetStateRootParamValue(root, (int)lvlPid, lvlNorm);
    if ([voice[@"sync"] respondsToSelector:@selector(boolValue)]) sidSetStateRootParamValue(root, (int)syncPid, [voice[@"sync"] boolValue] ? 1.0f : 0.0f);
    if ([voice[@"ringmod"] respondsToSelector:@selector(boolValue)]) sidSetStateRootParamValue(root, (int)ringPid, [voice[@"ringmod"] boolValue] ? 1.0f : 0.0f);
    id ad = voice[@"ad"];
    id sr = voice[@"sr"];
    if ([ad respondsToSelector:@selector(integerValue)] && [sr respondsToSelector:@selector(integerValue)]) {
        const int adv = std::clamp((int)[ad integerValue], 0, 255);
        const int srv = std::clamp((int)[sr integerValue], 0, 255);
        sidSetStateRootParamValue(root, (int)kParamAttack,  (float)((adv >> 4) & 0x0F) / 15.0f);
        sidSetStateRootParamValue(root, (int)kParamDecay,   (float)( adv       & 0x0F) / 15.0f);
        sidSetStateRootParamValue(root, (int)kParamSustain, (float)((srv >> 4) & 0x0F) / 15.0f);
        sidSetStateRootParamValue(root, (int)kParamRelease, (float)( srv       & 0x0F) / 15.0f);
    }
}

static BOOL ArpSIDParseExternalC64ClassicBankDocument(NSDictionary* doc,
                                                      std::vector<ArpSID::SidStateRootV1>& patches,
                                                      std::vector<ArpSID::ArpSIDFilePatchMeta>& metas,
                                                      NSString** errorText) {
    if (![doc isKindOfClass:[NSDictionary class]]) return NO;
    NSArray* classicPatches = [doc[@"patches"] isKindOfClass:[NSArray class]] ? doc[@"patches"] : nil;
    if (classicPatches.count == 0) return NO;
    patches.clear();
    metas.clear();
    const NSUInteger count = MIN((NSUInteger)ArpSID::kFileBankMaxSlots, classicPatches.count);
    patches.resize((size_t)ArpSID::kFileBankMaxSlots);
    metas.resize((size_t)ArpSID::kFileBankMaxSlots);
    for (NSUInteger i = 0; i < count; ++i) {
        NSDictionary* jp = [classicPatches[i] isKindOfClass:[NSDictionary class]] ? classicPatches[i] : nil;
        if (!jp) continue;
        ArpSID::SidStateRootV1 root = ArpSID::makeFactoryPatchStateRootForSlot((int)i);
        ArpSID::ArpSIDFilePatchMeta meta{};
        NSString* name = [jp[@"name"] isKindOfClass:[NSString class]] ? jp[@"name"] : [NSString stringWithFormat:@"C64_%03lu", (unsigned long)i + 1ul];
        NSString* category = [jp[@"category"] isKindOfClass:[NSString class]] ? jp[@"category"] : @"Imported";
        NSString* chip = [jp[@"chip"] isKindOfClass:[NSString class]] ? jp[@"chip"] : @"6581";
        ArpSIDCopyMetaCString(meta.name, sizeof(meta.name), name);
        ArpSIDCopyMetaCString(meta.author, sizeof(meta.author), @"JSON Import");
        ArpSIDCopyMetaCString(meta.category, sizeof(meta.category), category);
        ArpSIDCopyMetaCString(meta.tags, sizeof(meta.tags), [NSString stringWithFormat:@"%@ %@", chip, @"C64 JSON"]);
        meta.chip_model = [chip containsString:@"8580"] ? 1u : 0u;
        meta.role = [category.lowercaseString containsString:@"drum"] ? (uint8_t)ArpSID::PatchRole::Drum : 0u;
        ArpSID::sidSetStateRootParamValue(root, (int)ArpSID::kParamSidModel, [chip containsString:@"8580"] ? 1.0f : 0.0f);
        ArpSID::sidSetStateRootParamValue(root, (int)ArpSID::kParamMasterVolume, ArpSIDJSONClamp01([jp[@"volume"] respondsToSelector:@selector(doubleValue)] ? [jp[@"volume"] doubleValue] / 15.0 : 1.0, 1.0));
        // Only the oscillators that the JSON sound actually declares should be in
        // the mix. Zero all three first so an unspecified voice stays silent
        // instead of inheriting the factory seed slot's helper oscillator levels.
        ArpSID::sidSetStateRootParamValue(root, (int)ArpSID::kParamVCO1Level, 0.0f);
        ArpSID::sidSetStateRootParamValue(root, (int)ArpSID::kParamVCO2Level, 0.0f);
        ArpSID::sidSetStateRootParamValue(root, (int)ArpSID::kParamVCO3Level, 0.0f);
        ArpSIDApplyClassicJSONVoice(root, jp[@"voice1"], 0);
        ArpSIDApplyClassicJSONVoice(root, jp[@"voice2"], 1);
        ArpSIDApplyClassicJSONVoice(root, jp[@"voice3"], 2);
        NSDictionary* filter = [jp[@"filter"] isKindOfClass:[NSDictionary class]] ? jp[@"filter"] : nil;
        if (filter) {
            if ([filter[@"cutoff"] respondsToSelector:@selector(doubleValue)]) ArpSID::sidSetStateRootParamValue(root, (int)ArpSID::kParamFilterCutoff, ArpSIDJSONClamp01([filter[@"cutoff"] doubleValue] / 16383.0, 0.6));
            if ([filter[@"res"] respondsToSelector:@selector(doubleValue)]) ArpSID::sidSetStateRootParamValue(root, (int)ArpSID::kParamFilterResonance, ArpSIDJSONClamp01([filter[@"res"] doubleValue] / 15.0, 0.2));
            NSString* mode = [filter[@"mode"] isKindOfClass:[NSString class]] ? [filter[@"mode"] lowercaseString] : @"lp";
            float modeNorm = [mode containsString:@"hp"] ? 0.75f : ([mode containsString:@"bp"] ? 0.50f : 0.25f);
            ArpSID::sidSetStateRootParamValue(root, (int)ArpSID::kParamFilterMode, modeNorm);
        }
        NSDictionary* extra = [jp[@"extra"] isKindOfClass:[NSDictionary class]] ? jp[@"extra"] : nil;
        const BOOL drum = [category.lowercaseString containsString:@"drum"] || ([extra[@"drum_mode"] respondsToSelector:@selector(boolValue)] && [extra[@"drum_mode"] boolValue]);
        if (drum) {
            meta.role = (uint8_t)ArpSID::PatchRole::Drum;
            ArpSID::sidSetStateRootParamValue(root, (int)ArpSID::kParamDrSidEnable, 1.0f);
            ArpSID::sidSetStateRootParamValue(root, (int)ArpSID::kParamSynthModeEnable, 0.0f);
        } else {
            // Classic C64 JSON describes a patch with high-level voice/filter
            // params (wave/pw/adsr/filter). Those are audio authority ONLY in
            // BitPerfect render mode (the play engine applies kParamVCO*/kParamFilter*
            // and synthesises per note). The seed slot from
            // makeFactoryPatchStateRootForSlot() is a synthMode/SidRegister patch
            // whose audio authority is the seed slot's $D4xx register image — in
            // that mode the imported high-level params are ignored and the import
            // silently plays the wrong (factory) sound. Force BitPerfect so the
            // imported classic sound actually applies.
            ArpSID::sidSetStateRootParamValue(root, (int)ArpSID::kParamDrSidEnable, 0.0f);
            ArpSID::sidSetStateRootParamValue(root, (int)ArpSID::kParamSynthModeEnable, 0.0f);
        }
        ArpSID::sidCanonicalizeTopLevelRenderModeParams(root);
        ArpSID::sidEnsureSemanticParameterEntries(root);
        patches[(size_t)i] = root;
        metas[(size_t)i] = meta;
    }
    for (NSUInteger i = count; i < (NSUInteger)ArpSID::kFileBankMaxSlots; ++i) {
        patches[(size_t)i] = ArpSID::makeFactoryPatchStateRootForSlot((int)i);
        metas[(size_t)i] = ArpSID::ArpSIDFilePatchMeta{};
    }
    return YES;
}
static BOOL ArpSIDParseJSONBankDocument(NSDictionary* doc,
                                        std::vector<ArpSID::SidStateRootV1>& patches,
                                        std::vector<ArpSID::ArpSIDFilePatchMeta>& metas,
                                        NSString** errorText) {
    if (![doc isKindOfClass:[NSDictionary class]]) {
        if (errorText) *errorText = @"Top-level JSON object is missing";
        return NO;
    }
    NSString* format = [doc[@"ArpSIDFormat"] isKindOfClass:[NSString class]] ? doc[@"ArpSIDFormat"] : @"";
    if (![format isEqualToString:@"BankJSON"]) {
        if (errorText) *errorText = @"Not an ArpSID bank JSON file";
        return NO;
    }
    NSNumber* version = [doc[@"ArpSIDVersion"] respondsToSelector:@selector(integerValue)] ? doc[@"ArpSIDVersion"] : nil;
    if (!version || version.integerValue < 1 || version.integerValue > 1) {
        if (errorText) *errorText = @"Unsupported ArpSID bank JSON version";
        return NO;
    }
    NSArray* slots = [doc[@"slots"] isKindOfClass:[NSArray class]] ? doc[@"slots"] : nil;
    if (slots.count == 0) {
        if (errorText) *errorText = @"Bank JSON contains no slots";
        return NO;
    }
    if (slots.count > ArpSID::kFileBankMaxSlots) {
        if (errorText) *errorText = @"Bank JSON contains more than 128 user-bank v1 slots. Factory slots 128..179 require factory preset/state-root export, not v1 bank JSON.";
        return NO;
    }
    patches.clear();
    metas.clear();
    std::array<uint8_t, ArpSID::kFileBankMaxSlots> seen{};
    for (NSUInteger i = 0; i < slots.count; ++i) {
        NSDictionary* slotDoc = [slots[i] isKindOfClass:[NSDictionary class]] ? slots[i] : nil;
        if (!slotDoc) {
            if (errorText) *errorText = [NSString stringWithFormat:@"Slot entry %lu is not an object", (unsigned long)i];
            return NO;
        }
        NSInteger slot = [slotDoc[@"slot"] respondsToSelector:@selector(integerValue)] ? [slotDoc[@"slot"] integerValue] : (NSInteger)i;
        if (slot < 0 || slot >= ArpSID::kFileBankMaxSlots) {
            if (errorText) *errorText = [NSString stringWithFormat:@"Slot %ld is outside user-bank v1 range 0..127. Factory slots 128..179 require factory preset/state-root export.", (long)slot];
            return NO;
        }
        if (seen[(size_t)slot] != 0u) {
            if (errorText) *errorText = [NSString stringWithFormat:@"Duplicate slot %ld in bank JSON", (long)slot];
            return NO;
        }
        ArpSID::SidStateRootV1 root{};
        ArpSID::ArpSIDFilePatchMeta meta{};
        if (!ArpSIDParseJSONPatchDocument(slotDoc, root, meta, errorText)) return NO;
        if (patches.size() <= (size_t)slot) {
            patches.resize((size_t)slot + 1u);
            metas.resize((size_t)slot + 1u);
        }
        patches[(size_t)slot] = root;
        metas[(size_t)slot] = meta;
        seen[(size_t)slot] = 1u;
    }
    if (patches.empty() || metas.empty()) {
        if (errorText) *errorText = @"Bank JSON produced no usable slots";
        return NO;
    }
    return YES;
}

static BOOL ArpSIDWriteJSONDocumentToURL(NSDictionary* doc, NSURL* url, NSString** errorText) {
    if (!doc || !url) {
        if (errorText) *errorText = @"Missing JSON document or destination";
        return NO;
    }
    NSError* error = nil;
    NSData* data = [NSJSONSerialization dataWithJSONObject:doc options:NSJSONWritingPrettyPrinted error:&error];
    if (!data) {
        if (errorText) *errorText = (error.localizedDescription != nil) ? error.localizedDescription : @"JSON serialization failed";
        return NO;
    }
    if (![data writeToURL:url options:NSDataWritingAtomic error:&error]) {
        if (errorText) *errorText = (error.localizedDescription != nil) ? error.localizedDescription : @"JSON file write failed";
        return NO;
    }
    return YES;
}

static NSDictionary* ArpSIDReadJSONDocumentFromURL(NSURL* url, NSString** errorText) {
    if (!url) {
        if (errorText) *errorText = @"Missing JSON source file";
        return nil;
    }
    NSError* error = nil;
    NSData* data = [NSData dataWithContentsOfURL:url options:0 error:&error];
    if (!data) {
        if (errorText) *errorText = (error.localizedDescription != nil) ? error.localizedDescription : @"Unable to read JSON file";
        return nil;
    }
    static const NSUInteger kMaxArpSIDJSONBytes = 16u * 1024u * 1024u;
    if (data.length == 0 || data.length > kMaxArpSIDJSONBytes) {
        if (errorText) *errorText = @"JSON file is empty or larger than 16 MiB";
        return nil;
    }
    id parsed = [NSJSONSerialization JSONObjectWithData:data options:NSJSONReadingMutableContainers error:&error];
    if (![parsed isKindOfClass:[NSDictionary class]]) {
        if (errorText) *errorText = (error.localizedDescription != nil) ? error.localizedDescription : @"JSON root must be an object";
        return nil;
    }
    return (NSDictionary*)parsed;
}

// Fix-order #35 / v781: bank document load/save helpers are pure file/JSON
// operations and must be callable from worker queues without retaining or
// dereferencing ArpSIDViewController. Earlier async bank import/export blocks
// captured a strong controller (`s`) and then called ObjC instance helpers on
// the background queue. That was lifetime-safe under ARC but still an avoidable
// editor-lifetime extension and an off-main controller method call. Keep the
// worker path controller-free; main-queue blocks weak-load the controller only
// when publishing UI/state results.
static ArpSID::FileBankError ArpSIDSaveBankDocumentToURL_v781(
    NSURL* url,
    const std::vector<ArpSID::SidStateRootV1>& patches,
    const std::vector<ArpSID::ArpSIDFilePatchMeta>& metas,
    NSString* displayName) {
    if (!url) return ArpSID::FileBankError::Unknown;
    if (!ArpSIDPathUsesJSON(url.path)) {
        return ArpSID::ArpSIDFileBank::saveBankToFile(url.path.UTF8String, patches, metas);
    }
    NSDictionary* doc = ArpSIDJSONBankDocumentFromVectors(patches, metas, displayName);
    if (!doc) return ArpSID::FileBankError::BadBlob;
    NSString* errorText = nil;
    return ArpSIDWriteJSONDocumentToURL(doc, url, &errorText)
        ? ArpSID::FileBankError::OK
        : ArpSID::FileBankError::WriteFailed;
}

static ArpSID::FileBankError ArpSIDLoadBankDocumentFromURL_v781(
    NSURL* url,
    std::vector<ArpSID::SidStateRootV1>& patches,
    std::vector<ArpSID::ArpSIDFilePatchMeta>& metas) {
    if (!url) return ArpSID::FileBankError::Unknown;
    if (!ArpSIDPathUsesJSON(url.path)) {
        return ArpSID::ArpSIDFileBank::loadBankFromFile(url.path.UTF8String, patches, metas);
    }
    NSString* errorText = nil;
    NSDictionary* doc = ArpSIDReadJSONDocumentFromURL(url, &errorText);
    if (!doc) return ArpSID::FileBankError::ReadFailed;
    if (ArpSIDParseJSONBankDocument(doc, patches, metas, &errorText)) return ArpSID::FileBankError::OK;
    if (ArpSIDParseExternalC64ClassicBankDocument(doc, patches, metas, &errorText)) return ArpSID::FileBankError::OK;
    return ArpSID::FileBankError::BadBlob;
}

