static BOOL ArpSIDDrumPerformancePadContainsMidiNote(int note) {
    for (int i = 0; i < kArpSIDDrumPerformancePadCount; ++i) {
        if (kArpSIDDrumPerformancePadNotes[i] == note) return YES;
    }
    return NO;
}

static BOOL ArpSIDDrum808RowMatchesMidiNote(NSUInteger row, int note) {
    switch (row) {
        case 0: return note == 35 || note == 36;
        case 1: return note == 38 || note == 40;
        case 2: return note == 39;
        case 3: return note == 42 || note == 44 || note == 46;
        default: return NO;
    }
}

