static const CGFloat kW=1600,kH=940;  // denser native canvas for the standalone/AUv3 host shell
static inline void ArpSIDSetPreferredContentSizeOnMainThread(NSViewController* controller, NSSize size) {
    if (!controller) return;
    if ([NSThread isMainThread]) {
        controller.preferredContentSize = size;
        return;
    }
    dispatch_async(dispatch_get_main_queue(), ^{
        controller.preferredContentSize = size;
    });
}
static const CGFloat kBW=10,kHdrH=48,kTabH=30,kFtrH=42;
// Keep the bottom keyboard/HUD and navigation row clear of host-window edges.
// The navigation row was moved below the panels in v320 but the content origin
// still began directly above the footer, so the row overlapped panel content and
// sat uncomfortably close to the resize/title-safe edge after host scaling.
static const CGFloat kBottomSafeInset=10;
// Reduce every rendered knob consistently while retaining the complete control
// cell as its hit target. The extra breathing room prevents dense sections from
// reading as a wall of dials without making pointer interaction more fiddly.
static constexpr CGFloat kArpSIDKnobVisualScale=0.70f;
// The display link may fire at 120 Hz on modern Macs, but repainting the full
// AppKit editor at that rate can starve first-open interaction. Keep the link as
// the wakeup source, then cadence-limit the heavy telemetry/redraw path.
static constexpr double kArpSIDGuiIdlePollHz_v820 = 8.0;
static constexpr double kArpSIDGuiActivePollHz_v820 = 24.0;

