// MARK: - ArpSIDKnobView (with glow, automation flash, touch-highlight)
// ─────────────────────────────────────────────────────────────────────────────
@interface ArpSIDKnobView : NSView
@property (nonatomic) int   paramID;
@property (nonatomic) float value;
@property (nonatomic) float defaultValue;
@property (nonatomic,copy) NSString *pname, *vstr;
@property (nonatomic,weak) id tgt;
@property (nonatomic)      SEL act;
@property (nonatomic)      BOOL touched;       // true while being dragged
@property (nonatomic)      float glowAmt;      // 0..1 automation/touch glow
-(instancetype)initF:(NSRect)r n:(NSString*)n p:(int)p d:(float)d;
-(void)set:(float)v;
-(void)setAutomated:(float)v;  // called from observer — flashes glow
-(void)setModulatedValue:(float)v activity:(float)activity label:(NSString* _Nullable)label;
@end

@implementation ArpSIDKnobView{
    NSPoint _ds;
    float _dv;
    BOOL _drag;
    float _glowDecay;
    BOOL _hovered;
    NSTrackingArea* _trackingArea;
    float _modulatedValue;
    float _modulationActivity;
    NSString* _modulationLabel;
}

-(instancetype)initF:(NSRect)r n:(NSString*)n p:(int)p d:(float)d{
    self=[super initWithFrame:r];if(!self)return nil;
    _paramID=p;_pname=n;_value=d;_defaultValue=d;_vstr=[NSString stringWithFormat:@"%.3f",d];
    _glowAmt=0;_glowDecay=0;_modulatedValue=d;_modulationActivity=0.f;
    self.focusRingType=NSFocusRingTypeExterior;
    self.toolTip=@"Drag vertically or horizontally. Shift for fine control. Arrow keys adjust, Page Up/Down makes larger changes, and Home/Option-click/double-click/right-click resets.";
    self.accessibilityHelp=self.toolTip;
    return self;}
-(BOOL)isFlipped{return NO;}-(BOOL)acceptsFirstResponder{return YES;}
-(BOOL)acceptsFirstMouse:(NSEvent*)e{(void)e;return YES;}
-(BOOL)isAccessibilityElement{return YES;}
-(NSString*)accessibilityRole{return NSAccessibilitySliderRole;}
-(NSString*)accessibilityLabel{return _pname.length>0?_pname:@"Parameter";}
-(id)accessibilityValue{return @(_value);}
-(id)accessibilityMinValue{return @(0.f);}
-(id)accessibilityMaxValue{return @(1.f);}
-(void)accessibilityIncrement{
    [self set:std::clamp(_value+.01f,0.f,1.f)];_glowAmt=.8f;[self _fire];
}
-(void)accessibilityDecrement{
    [self set:std::clamp(_value-.01f,0.f,1.f)];_glowAmt=.8f;[self _fire];
}
-(void)resetCursorRects{[self addCursorRect:self.bounds cursor:[NSCursor openHandCursor]];}
-(void)updateTrackingAreas{
    [super updateTrackingAreas];
    if(_trackingArea) [self removeTrackingArea:_trackingArea];
    _trackingArea=[[NSTrackingArea alloc]
        initWithRect:self.bounds
             options:NSTrackingMouseEnteredAndExited|NSTrackingActiveAlways|NSTrackingInVisibleRect
               owner:self
            userInfo:nil];
    [self addTrackingArea:_trackingArea];
}
-(void)mouseEntered:(NSEvent*)e{(void)e;_hovered=YES;[self setNeedsDisplay:YES];}
-(void)mouseExited:(NSEvent*)e{(void)e;_hovered=NO;[self setNeedsDisplay:YES];}

-(void)drawRect:(NSRect)dr7{(void)dr7;
    NSRect b=self.bounds;
    const CGFloat cx=b.size.width*.5f;
    const CGFloat r=std::max<CGFloat>(10.f,(MIN(b.size.width,b.size.height)*.5f-6.f)*kArpSIDKnobVisualScale);
    const CGFloat cy=b.size.height*.5f+4;
    NSColor*accentC=ArpSIDForensicParamColor(_paramID);
    NSColor*activeC=_touched?c64Yellow():(accentC?accentC:c64Cyan());
    NSColor*hoverC=_hovered&&!_touched?[activeC blendedColorWithFraction:.35f ofColor:c64White()]:activeC;

    // ── Outer glow ring ───────────────────────────────────────────────────
    if(_glowAmt>0.02f||_touched||_hovered){
        float ga=_touched?0.75f:std::max(_glowAmt,_hovered?0.28f:0.f);
        // Outer diffuse
        [[hoverC colorWithAlphaComponent:ga*.22f] setStroke];
        NSBezierPath*gr2=[NSBezierPath bezierPath];
        [gr2 appendBezierPathWithArcWithCenter:NSMakePoint(cx,cy) radius:r+5 startAngle:0 endAngle:360 clockwise:NO];
        gr2.lineWidth=4.f;[gr2 stroke];
        // Inner ring
        [[hoverC colorWithAlphaComponent:ga*.55f] setStroke];
        NSBezierPath*gr=[NSBezierPath bezierPath];
        [gr appendBezierPathWithArcWithCenter:NSMakePoint(cx,cy) radius:r+2 startAngle:0 endAngle:360 clockwise:NO];
        gr.lineWidth=1.8f;[gr stroke];
    }

    // ── Name label ────────────────────────────────────────────────────────
    NSColor*labelC=_touched?colTitle():(_hovered?[hoverC colorWithAlphaComponent:.96f]:(accentC?[accentC colorWithAlphaComponent:.90f]:colLabel()));
    NSDictionary*la=@{NSForegroundColorAttributeName:labelC,NSFontAttributeName:monoF(8.5)};
    NSString*ns=_pname.length>9?[_pname substringToIndex:9]:_pname;
    NSSize sz=[ns sizeWithAttributes:la];
    [ns drawAtPoint:NSMakePoint(cx-sz.width*.5f,b.size.height-12) withAttributes:la];

    // ── Track arc ─────────────────────────────────────────────────────────
    NSBezierPath*track=[NSBezierPath bezierPath];
    [track appendBezierPathWithArcWithCenter:NSMakePoint(cx,cy) radius:r startAngle:220 endAngle:-40 clockwise:YES];
    track.lineWidth=4; track.lineCapStyle=NSLineCapStyleRound;
    // Track shadow
    [[NSColor colorWithSRGBRed:0 green:0 blue:0 alpha:.5f] setStroke]; [track stroke];
    // Track fill (dark groove)
    [[c64DkGrey() colorWithAlphaComponent:.50f] setStroke]; [track stroke];

    // ── Value arc ─────────────────────────────────────────────────────────
    if(_value>0.001f){
        if(_glowAmt>0.04f||_touched){
            // Bloom under value arc
            NSBezierPath*bloom=[NSBezierPath bezierPath];
            [bloom appendBezierPathWithArcWithCenter:NSMakePoint(cx,cy) radius:r startAngle:220 endAngle:(220-280*(double)_value) clockwise:YES];
            bloom.lineWidth=8; bloom.lineCapStyle=NSLineCapStyleRound;
            [[activeC colorWithAlphaComponent:(_touched?.38f:_glowAmt*.35f)] setStroke];
            [bloom stroke];
        }
        NSBezierPath*varc=[NSBezierPath bezierPath];
        [varc appendBezierPathWithArcWithCenter:NSMakePoint(cx,cy) radius:r startAngle:220 endAngle:(220-280*(double)_value) clockwise:YES];
        varc.lineWidth=4; varc.lineCapStyle=NSLineCapStyleRound;
        [activeC setStroke]; [varc stroke];
        // Bright tip
        double tipA=(220-280*(double)_value)*M_PI/180;
        CGFloat tipX=cx+r*cos(tipA), tipY=cy+r*sin(tipA);
        [[activeC blendedColorWithFraction:.5f ofColor:c64White()] setFill];
        [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(tipX-2.5f,tipY-2.5f,5,5)] fill];
    }

    if(_modulationActivity>0.01f){
        const float mv=ArpSIDUIClamp01(_modulatedValue,_value);
        const double baseA=(220-280*(double)_value)*M_PI/180;
        const double modA=(220-280*(double)mv)*M_PI/180;
        NSColor*modC=[c64Orange() blendedColorWithFraction:.28f ofColor:c64White()];
        NSBezierPath*marc=[NSBezierPath bezierPath];
        [marc appendBezierPathWithArcWithCenter:NSMakePoint(cx,cy) radius:r+7
                                     startAngle:(CGFloat)(baseA*180.0/M_PI)
                                       endAngle:(CGFloat)(modA*180.0/M_PI)
                                      clockwise:(mv<_value)];
        marc.lineWidth=2.2f;
        marc.lineCapStyle=NSLineCapStyleRound;
        [[modC colorWithAlphaComponent:(0.18f+0.50f*_modulationActivity)] setStroke];
        [marc stroke];
        const CGFloat modX=cx+(r+7)*cos(modA), modY=cy+(r+7)*sin(modA);
        [[modC colorWithAlphaComponent:(0.45f+0.45f*_modulationActivity)] setFill];
        [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(modX-2.5f,modY-2.5f,5,5)] fill];
    }

    // ── Knob body — three-layer metallic sphere ───────────────────────────
    const CGFloat br=r-5;
    // Shadow ring
    [[NSColor colorWithSRGBRed:0 green:0 blue:0 alpha:.65f] setFill];
    [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(cx-br-1,cy-br-1,(br+1)*2,(br+1)*2)] fill];
    // Outer body (dark metallic)
    [colKnobBody() setFill];
    [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(cx-br,cy-br,br*2,br*2)] fill];
    // Mid body (lighter centre)
    const float hi=_touched?.28f:.20f;
    [[NSColor colorWithSRGBRed:hi green:hi*.88f blue:hi*2.6f alpha:1] setFill];
    [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(cx-br+2,cy-br+2,br*2-4,br*2-4)] fill];
    // Inner highlight (specular sphere illusion)
    NSGradient* sphereGrad = [[NSGradient alloc]
        initWithColorsAndLocations:
            [NSColor colorWithSRGBRed:.35f green:.30f blue:.90f alpha:1],(CGFloat)0.0,
            colKnobHi(),(CGFloat)0.5,
            [NSColor colorWithSRGBRed:.08f green:.07f blue:.25f alpha:1],(CGFloat)1.0,
            nil];
    NSBezierPath* bodyPath=[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(cx-br+3,cy-br+3,br*2-6,br*2-6)];
    [sphereGrad drawInBezierPath:bodyPath angle:-60];
    // Specular cap (teardrop highlight)
    [[NSColor colorWithSRGBRed:.90f green:.90f blue:1.0f alpha:(_touched?.65f:.40f)] setFill];
    [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(cx-br*.38f,cy+br*.28f,br*.48f,br*.30f)] fill];
    // Secondary micro specular
    [[NSColor colorWithSRGBRed:1 green:1 blue:1 alpha:(_touched?.30f:.18f)] setFill];
    [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(cx+br*.08f,cy+br*.38f,br*.20f,br*.14f)] fill];

    // ── Needle ────────────────────────────────────────────────────────────
    const double na=(220-280*(double)_value)*M_PI/180;
    const CGFloat nx=cx+(br-3)*cos(na), ny=cy+(br-3)*sin(na);
    // Shadow
    [[NSColor colorWithSRGBRed:0 green:0 blue:0 alpha:.45f] setStroke];
    {NSBezierPath*sh=[NSBezierPath bezierPath];
     [sh moveToPoint:NSMakePoint(cx+.7f,cy-.7f)];[sh lineToPoint:NSMakePoint(nx+.7f,ny-.7f)];
     sh.lineWidth=2.2f;sh.lineCapStyle=NSLineCapStyleRound;[sh stroke];}
    // Main needle
    NSColor*needleC=_touched?c64Yellow():(accentC?[accentC blendedColorWithFraction:.4f ofColor:c64White()]:c64White());
    [needleC setStroke];
    NSBezierPath*nd=[NSBezierPath bezierPath];
    [nd moveToPoint:NSMakePoint(cx,cy)];[nd lineToPoint:NSMakePoint(nx,ny)];
    nd.lineWidth=1.8f;nd.lineCapStyle=NSLineCapStyleRound;[nd stroke];
    // Centre boss
    [[NSColor colorWithSRGBRed:0 green:0 blue:0 alpha:.5f] setFill];
    [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(cx-3.5f,cy-3.5f,7,7)] fill];
    [needleC setFill];
    [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(cx-2.5f,cy-2.5f,5,5)] fill];

    // ── Value label ───────────────────────────────────────────────────────
    NSColor*valC=_touched?colTitle():(_hovered?hoverC:(accentC?accentC:colValue()));
    NSDictionary*va=@{NSForegroundColorAttributeName:valC,NSFontAttributeName:monoF(8)};
    NSSize vs=[_vstr sizeWithAttributes:va];
    [_vstr drawAtPoint:NSMakePoint(cx-vs.width*.5f,1) withAttributes:va];}

-(void)set:(float)v{
    const float nv = ArpSIDUIClamp01(v);
    if (fabsf(nv - _value) <= 0.0005f) return;
    _value = nv;
    _vstr=[NSString stringWithFormat:@"%.3f",_value];
    [self setNeedsDisplay:YES];}

-(void)setAutomated:(float)v{
    [self set:v];
    _glowAmt=1.0f;  // full flash; caller should schedule decay timer
    [self setNeedsDisplay:YES];}

-(void)setModulatedValue:(float)v activity:(float)activity label:(NSString* _Nullable)label{
    const float nv=ArpSIDUIClamp01(v,_value);
    const float na=ArpSIDUIClamp01(activity);
    const BOOL changed = (fabsf(_modulatedValue-nv)>0.001f) ||
                         (fabsf(_modulationActivity-na)>0.001f) ||
                         !((_modulationLabel==label)||[_modulationLabel isEqualToString:label]);
    if(!changed) return;
    _modulatedValue=nv;
    _modulationActivity=na;
    _modulationLabel=[label copy];
    [self setNeedsDisplay:YES];
}

// Glow decay — call each display frame
-(void)tickGlow{
    if(_glowAmt>0.005f){_glowAmt*=0.82f;[self setNeedsDisplay:YES];}
    else if(_glowAmt>0){_glowAmt=0;[self setNeedsDisplay:YES];}}

-(void)_fire{if(_tgt&&_act){void(*fn)(id,SEL,id)=(void(*)(id,SEL,id))[_tgt methodForSelector:_act];fn(_tgt,_act,self);}}
-(void)mouseDown:(NSEvent*)e{
    [self.window makeFirstResponder:self];
    if((e.modifierFlags & NSEventModifierFlagOption) != 0 || e.clickCount >= 2){
        [self set:_defaultValue];
        _glowAmt=1.f;
        [self _fire];
        return;
    }
    _ds=[self convertPoint:e.locationInWindow fromView:nil];_dv=_value;_drag=YES;
    _touched=YES;[[NSCursor closedHandCursor] set];[self setNeedsDisplay:YES];}
-(void)mouseDragged:(NSEvent*)e{
    if(!_drag)return;
    NSPoint p=[self convertPoint:e.locationInWindow fromView:nil];
    float sc=(e.modifierFlags&NSEventModifierFlagShift)?.003f:.007f;
    const CGFloat travel=(p.y-_ds.y)+(p.x-_ds.x)*.35f;
    [self set:std::clamp(_dv+(float)travel*sc,0.f,1.f)];[self _fire];}
-(void)mouseUp:(NSEvent*)e{
    (void)e;_drag=NO;_touched=NO;_glowAmt=0.5f;[[NSCursor openHandCursor] set];[self setNeedsDisplay:YES];}
-(void)scrollWheel:(NSEvent*)e{
    float sc=e.hasPreciseScrollingDeltas?.004f:.012f;
    if((e.modifierFlags&NSEventModifierFlagShift)!=0)sc*=.25f;
    [self set:std::clamp(_value+(float)e.deltaY*sc,0.f,1.f)];
    _glowAmt=0.8f;[self _fire];}
-(void)keyDown:(NSEvent*)e{
    const BOOL fine=(e.modifierFlags&NSEventModifierFlagShift)!=0;
    const float step=fine?.002f:.01f;
    float next=_value;
    switch(e.keyCode){
        case 123: case 125: next-=step; break; // left/down
        case 124: case 126: next+=step; break; // right/up
        case 116: next+=fine?.02f:.10f; break; // Page Up
        case 121: next-=fine?.02f:.10f; break; // Page Down
        case 115: next=_defaultValue; break;   // Home
        default: [super keyDown:e]; return;
    }
    [self set:std::clamp(next,0.f,1.f)];
    _glowAmt=.8f;[self _fire];
}
-(void)rightMouseDown:(NSEvent*)e{
    (void)e;  // right-click: reset to default
    if(_paramID>=0&&_paramID<ArpSID::kNumParams)
        [self set:ArpSID::kParamInfos[(size_t)_paramID].defaultNorm];
    _glowAmt=1.f;[self _fire];}
@end

// MARK: - ArpSIDStripView (pitch bend / mod wheel / breath bipolar bar)
// ─────────────────────────────────────────────────────────────────────────────
@interface ArpSIDStripView : NSView
@property (nonatomic) float value;   // 0..1; 0.5 = centre for bipolar
@property (nonatomic) BOOL  bipolar; // YES draws centre-zero bar, NO draws bottom-zero
@property (nonatomic,copy) NSString* label;
@property (nonatomic,strong) NSColor* barColor;
@property (nonatomic,copy) void(^changeBlock)(float);  // called on drag/scroll
-(void)setValue:(float)v;
@end
@implementation ArpSIDStripView {
    void(^_changeBlock)(float);
}
-(instancetype)initWithFrame:(NSRect)r{
    self=[super initWithFrame:r];
    if(self){_value=0.5f;_bipolar=YES;_barColor=c64Cyan();
    self.toolTip=@"Drag to control";} return self;}
-(void)setValue:(float)v{
    float nv=std::clamp(v,0.f,1.f);
    if(fabsf(nv-_value)>0.001f){_value=nv;[self setNeedsDisplay:YES];}}
-(void)mouseDown:(NSEvent*)e{(void)e;[self.window makeFirstResponder:self];}
-(void)mouseDragged:(NSEvent*)e{
    const CGFloat dy=-e.deltaY;
    const float delta=(float)(dy/self.bounds.size.height);
    float nv=std::clamp(_value+delta,0.f,1.f);
    [self setValue:nv];
    if(_changeBlock)_changeBlock(nv);}
-(void)scrollWheel:(NSEvent*)e{
    const float delta=(float)(e.deltaY*0.01f);
    float nv=std::clamp(_value+delta,0.f,1.f);
    [self setValue:nv];
    if(_changeBlock)_changeBlock(nv);}
// v963 accessibility: the strip is an interactive control (drag/scroll) — expose
// it as a slider so assistive tech can announce and read it (knobs already do).
-(BOOL)isAccessibilityElement{return YES;}
-(NSAccessibilityRole)accessibilityRole{return NSAccessibilitySliderRole;}
-(NSString*)accessibilityLabel{return self.label.length ? self.label : @"Performance strip";}
-(id)accessibilityValue{return @(_value);}
-(void)drawRect:(NSRect)_r{(void)_r;
    NSRect b=self.bounds;
    // Background
    [[colOscBg() colorWithAlphaComponent:.9f] setFill];[[NSBezierPath bezierPathWithRoundedRect:b xRadius:2 yRadius:2] fill];
    CGFloat barAreaH=b.size.height-14;  // reserve space for label
    CGFloat barY=b.origin.y+14;
    if(_bipolar){
        // centre = 0.5, draw bar from centre to current value
        CGFloat mid=barY+barAreaH*.5f;
        CGFloat barH=((_value-0.5f)*2.f)*(barAreaH*.5f);
        CGFloat y=barH>=0?mid:mid+barH;
        CGFloat h=std::abs(barH);
        if(h>0.5f){
            NSColor*c=_value>0.55f?c64LtGreen():(_value<0.45f?c64LightRed():c64Cyan());
            [[c colorWithAlphaComponent:.9f] setFill];
            NSRectFill(NSMakeRect(b.origin.x+2,y,b.size.width-4,h));}
        // centre line
        [[c64MidGrey() colorWithAlphaComponent:.5f] setFill];
        NSRectFill(NSMakeRect(b.origin.x+1,mid-.5f,b.size.width-2,1));
    } else {
        CGFloat h=barAreaH*_value;
        NSColor*c=_value>0.75f?c64LightRed():(_value>0.4f?c64LtGreen():c64Cyan());
        [[c colorWithAlphaComponent:.9f] setFill];
        NSRectFill(NSMakeRect(b.origin.x+2,barY,b.size.width-4,h));}
    // Label
    NSDictionary*la=@{NSForegroundColorAttributeName:[colLabel() colorWithAlphaComponent:.7f],NSFontAttributeName:monoF(7.5)};
    NSSize ls=[_label sizeWithAttributes:la];
    [_label drawAtPoint:NSMakePoint(b.origin.x+(b.size.width-ls.width)*.5f,b.origin.y+1) withAttributes:la];
    // Border
    [[colBorder() colorWithAlphaComponent:.4f] setStroke];
    [[NSBezierPath bezierPathWithRoundedRect:NSInsetRect(b,.5f,.5f) xRadius:2 yRadius:2] stroke];}
@end

// ─────────────────────────────────────────────────────────────────────────────
// MARK: - ArpSIDLEDView
// ─────────────────────────────────────────────────────────────────────────────
@interface ArpSIDLEDView : NSView
@property (nonatomic,getter=isOn) BOOL on;@property(nonatomic,copy)NSString*label;@property(nonatomic,strong) NSColor*onColor;
@end
@implementation ArpSIDLEDView
-(instancetype)initWithFrame:(NSRect)r{self=[super initWithFrame:r];if(self)_onColor=colLEDOn();return self;}
-(void)drawRect:(NSRect)_r{(void)_r;
    NSRect b=self.bounds;
    const CGFloat r=MIN(b.size.width,b.size.height)*.42f;
    const CGFloat cx=b.size.width*.5f, cy=b.size.height-r-2;
    NSColor*onC=_onColor?_onColor:colLEDOn();

    if(_on){
        // Outer diffuse halo (largest, most transparent)
        [[onC colorWithAlphaComponent:.10f] setFill];
        [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(cx-r-7,cy-r-7,(r+7)*2,(r+7)*2)] fill];
        // Mid halo
        [[onC colorWithAlphaComponent:.20f] setFill];
        [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(cx-r-4,cy-r-4,(r+4)*2,(r+4)*2)] fill];
        // Inner halo
        [[onC colorWithAlphaComponent:.35f] setFill];
        [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(cx-r-2,cy-r-2,(r+2)*2,(r+2)*2)] fill];
    }

    // LED body — dark bevel ring
    [[colInnerShadow() colorWithAlphaComponent:.6f] setFill];
    [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(cx-r-1,cy-r-1,(r+1)*2,(r+1)*2)] fill];

    // Main fill
    [(_on?onC:colLEDOff()) setFill];
    [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(cx-r,cy-r,r*2,r*2)] fill];

    // Inner depth ring (slightly darker)
    if(_on){
        [[onC colorWithAlphaComponent:.35f] setFill];
        [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(cx-r*.68f,cy-r*.68f,r*1.36f,r*1.36f)] fill];
    }

    // Specular cap — teardrop highlight top-left
    if(_on){
        [[NSColor colorWithSRGBRed:1 green:1 blue:1 alpha:.70f] setFill];
        [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(cx-r*.40f,cy+r*.22f,r*.48f,r*.30f)] fill];
        // Secondary micro-specular dot
        [[NSColor colorWithSRGBRed:1 green:1 blue:1 alpha:.35f] setFill];
        [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(cx+r*.05f,cy+r*.32f,r*.20f,r*.15f)] fill];
    } else {
        // Off state: tiny grey specular
        [[NSColor colorWithSRGBRed:.5f green:.5f blue:.5f alpha:.25f] setFill];
        [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(cx-r*.28f,cy+r*.15f,r*.30f,r*.20f)] fill];
    }

    if(_label.length){
        NSDictionary*a=@{NSForegroundColorAttributeName:[colLabel() colorWithAlphaComponent:(_on?.90f:.55f)],
                         NSFontAttributeName:monoF(7.5)};
        NSSize ls=[_label sizeWithAttributes:a];
        [_label drawAtPoint:NSMakePoint(cx-ls.width*.5f,0) withAttributes:a];
    }
}
-(void)setOn:(BOOL)on{if(_on!=on){_on=on;[self setNeedsDisplay:YES];}}
@end

