// MARK: - ArpSIDDigiNibbleLadderView (standalone $D418 nibble eyecandy)
// ─────────────────────────────────────────────────────────────────────────────
@interface ArpSIDDigiNibbleLadderView : NSView
-(void)updateWithNibble:(uint8_t)nibble
               oldD418:(uint8_t)oldD418
                  d418:(uint8_t)d418
                  peak:(float)peak
              accepted:(BOOL)accepted
             ioVisible:(BOOL)ioVisible
                legacy:(BOOL)legacy
             recording:(BOOL)recording;
@end

@implementation ArpSIDDigiNibbleLadderView {
    uint8_t _nibble;
    uint8_t _oldD418;
    uint8_t _d418;
    float _peak;
    float _spark;
    BOOL _accepted;
    BOOL _ioVisible;
    BOOL _legacy;
    BOOL _recording;
}
-(instancetype)initWithFrame:(NSRect)r {
    self = [super initWithFrame:r];
    if (self) {
        _nibble = 0u; _oldD418 = 0u; _d418 = 0u; _peak = 0.f; _spark = 0.f;
        _accepted = NO; _ioVisible = NO; _legacy = NO; _recording = NO;
        self.wantsLayer = YES;
        self.toolTip = @"DIGI $D418 nibble ladder. Bright bar is the last 4-bit volume-DAC value; top/bottom rails show old/new $D418 bytes and IO/SID accept state. AUTH mode uses C64 IO/open-bus telemetry; FAST is private SID-only.";
    }
    return self;
}
-(void)updateWithNibble:(uint8_t)nibble
               oldD418:(uint8_t)oldD418
                  d418:(uint8_t)d418
                  peak:(float)peak
              accepted:(BOOL)accepted
             ioVisible:(BOOL)ioVisible
                legacy:(BOOL)legacy
             recording:(BOOL)recording {
    const uint8_t nn = (uint8_t)(nibble & 0x0Fu);
    const float np = ArpSIDUIClamp01(peak);
    const BOOL valueChanged = (_nibble != nn) || (_oldD418 != oldD418) || (_d418 != d418) ||
                              (fabsf(_peak - np) > 0.002f) || (_accepted != accepted) ||
                              (_ioVisible != ioVisible) || (_legacy != legacy) || (_recording != recording);

    // the ladder sparkle is visual-only state, so it must decay even
    // when telemetry values are stable. The early-return left the hot
    // bar permanently boosted after the last change because no redraw was
    // scheduled while _spark faded. Keep this GUI-only and allocation-free.
    const float oldSpark = _spark;
    if (_nibble != nn || _d418 != d418) {
        _spark = 1.0f;
    } else if (_spark > 0.004f) {
        _spark *= 0.86f;
    } else {
        _spark = 0.0f;
    }

    if (!valueChanged && fabsf(oldSpark - _spark) <= 0.002f) return;
    _nibble = nn; _oldD418 = oldD418; _d418 = d418; _peak = np;
    _accepted = accepted; _ioVisible = ioVisible; _legacy = legacy; _recording = recording;
    [self setNeedsDisplay:YES];
}
-(void)drawRect:(NSRect)dirtyRect {
    (void)dirtyRect;
    const NSRect b = self.bounds;
    if (b.size.width < 8.0 || b.size.height < 8.0) return;

    [[NSColor colorWithSRGBRed:0.005 green:0.012 blue:0.018 alpha:0.58] setFill];
    [[NSBezierPath bezierPathWithRoundedRect:b xRadius:3.0 yRadius:3.0] fill];

    NSColor* base = _legacy ? c64Orange() : (_accepted ? c64LtGreen() : c64Cyan());
    if (_recording) base = c64Red();
    const CGFloat railAlpha = _legacy ? 0.35 : (_ioVisible ? 0.54 : 0.24);
    [[base colorWithAlphaComponent:railAlpha] setStroke];
    NSBezierPath* rail = [NSBezierPath bezierPath];
    rail.lineWidth = 1.0;
    [rail moveToPoint:NSMakePoint(NSMinX(b) + 3.0, NSMinY(b) + 3.5)];
    [rail lineToPoint:NSMakePoint(NSMaxX(b) - 3.0, NSMinY(b) + 3.5)];
    [rail moveToPoint:NSMakePoint(NSMinX(b) + 3.0, NSMaxY(b) - 3.5)];
    [rail lineToPoint:NSMakePoint(NSMaxX(b) - 3.0, NSMaxY(b) - 3.5)];
    [rail stroke];

    const CGFloat pad = 4.0;
    const CGFloat gap = 1.0;
    const CGFloat usableW = std::max<CGFloat>(1.0, b.size.width - pad * 2.0 - gap * 15.0);
    const CGFloat barW = std::max<CGFloat>(1.0, floor(usableW / 16.0));
    const CGFloat maxH = std::max<CGFloat>(4.0, b.size.height - 10.0);
    for (int i = 0; i < 16; ++i) {
        const CGFloat x = NSMinX(b) + pad + (CGFloat)i * (barW + gap);
        const CGFloat h = 2.0 + maxH * ((CGFloat)(i + 1) / 16.0);
        const CGFloat y = NSMinY(b) + 5.0;
        const BOOL hot = (i == (int)_nibble);
        const CGFloat hotBoost = hot ? (0.42 + (CGFloat)_peak * 0.38 + (CGFloat)_spark * 0.18) : 0.0;
        const CGFloat alpha = std::min<CGFloat>(0.95, (hot ? 0.45 : 0.12) + hotBoost);
        NSColor* c = hot ? base : [base blendedColorWithFraction:0.65 ofColor:c64Blue()];
        [[c colorWithAlphaComponent:alpha] setFill];
        [[NSBezierPath bezierPathWithRoundedRect:NSMakeRect(x, y, barW, h) xRadius:1.2 yRadius:1.2] fill];
    }

    NSString* text = [NSString stringWithFormat:@"$D418 %02X→%02X  N%X%@",
                      (unsigned)_oldD418, (unsigned)_d418, (unsigned)_nibble,
                      _recording ? @"  REC" : (_legacy ? @"  LEG" : @"")];
    NSDictionary* attrs = @{ NSFontAttributeName: monoF(7.0f),
                             NSForegroundColorAttributeName: [[base blendedColorWithFraction:0.20 ofColor:colLabel()] colorWithAlphaComponent:0.84] };
    [text drawAtPoint:NSMakePoint(NSMinX(b) + 5.0, NSMaxY(b) - 10.5) withAttributes:attrs];
}
@end

// MARK: - ArpSIDOscilloscopeView (phosphor CRT waveform display)
// ─────────────────────────────────────────────────────────────────────────────
@interface ArpSIDOscilloscopeView : NSView
@property(nonatomic,strong) NSColor* accentColor;
@property(nonatomic,assign) float forensicActivity;
-(void)updateWithSamples:(const float*)samples count:(int)count;
@end

static NSGradient* ArpSIDScopeVignetteGradient() {
    static NSGradient* gradient = nil;
    static dispatch_once_t onceToken;
    dispatch_once(&onceToken, ^{
        gradient = [[NSGradient alloc]
            initWithColorsAndLocations:
                [NSColor colorWithSRGBRed:0 green:0 blue:0 alpha:.0f], (CGFloat)0.0,
                [NSColor colorWithSRGBRed:0 green:0 blue:0 alpha:.0f], (CGFloat)0.45,
                [NSColor colorWithSRGBRed:0 green:0 blue:0 alpha:.40f], (CGFloat)1.0,
                nil];
    });
    return gradient;
}

@implementation ArpSIDOscilloscopeView{
    float _buf[512]; float _trail[512]; // persistent phosphor trail
    int _n;
    float _peakEnv;
    float _rmsEnv;
    NSColor*_accentColor;
    float _motionPhase;
    float _forensicActivity;
    float _trailDecay;  // per-tick trail fade factor
    BOOL _quiescentDrawn; // idle-redraw suppression: YES once the settled flat frame is on screen
}
-(instancetype)initWithFrame:(NSRect)r{
    self=[super initWithFrame:r];
    if(self){
        memset(_buf,0,sizeof(_buf));
        memset(_trail,0,sizeof(_trail));
        _n=0;_peakEnv=0;_rmsEnv=0;_motionPhase=0.f;_forensicActivity=0.f;_trailDecay=0.f;
    }
    return self;
}
-(void)setForensicActivity:(float)v{
    float nv=ArpSIDUIClamp01(v);
    if(fabsf(nv-_forensicActivity)>0.001f){_forensicActivity=nv;_quiescentDrawn=NO;[self setNeedsDisplay:YES];}
}
-(void)updateWithSamples:(const float*)s count:(int)n{
    // Blend previous buffer into phosphor trail with decay
    const float decay = 0.72f - 0.15f*_forensicActivity; // faster decay with forensic activity
    float trailEnergy=0.f;
    for(int i=0;i<512;++i){
        _trail[i] = _trail[i]*decay + _buf[i]*(1.0f-decay);
        // Snap sub-perceptual residue to exact 0 so the settled state is a stable
        // fixed point (asymptotic decay otherwise never reaches 0 and would force
        // an endless trickle of redraws).
        if(fabsf(_trail[i])<1e-4f) _trail[i]=0.f;
        trailEnergy=std::max(trailEnergy,fabsf(_trail[i]));
    }

    _n=std::clamp(n,0,512);
    static constexpr float kScopeIdleDeadzone = 0.012f;
    BOOL bufHasSignal=NO;
    if(_n<=0||!s){
        memset(_buf,0,sizeof(_buf));
        _n=0; _peakEnv*=0.88f; _rmsEnv*=0.90f;
        // Idle visualizer fix: only advance the sweep while residual envelope
        // energy remains; once decayed to silence, FREEZE the phase so the scope
        // stops drifting when there is no audio data (no MIDI / nothing playing).
        if(_peakEnv>0.012f || _rmsEnv>0.012f) _motionPhase=fmodf(_motionPhase+0.018f,1.f);
    } else {
        float pk=0.f;
        double sumSquares=0.0;
        for(int i=0;i<_n;++i){
            _buf[i]=ArpSIDUIClampSigned(s[i],1.25f);
            pk=std::max(pk,fabsf(_buf[i]));
            sumSquares += (double)_buf[i] * (double)_buf[i];
        }
        // Idle SHAKE fix: a near-silent SID still emits a tiny DC/noise floor, which
        // made the trace shimmer and the sweep beam creep when "idle". Below a small
        // deadzone, treat the block as true silence — snap the displayed trace flat so
        // the scope is perfectly still until there is a real signal (a played note is
        // orders of magnitude above this floor, so musical content is unaffected).
        if(pk < kScopeIdleDeadzone){
            memset(_buf,0,sizeof(_buf));
            pk = 0.f;
            sumSquares = 0.0;
        } else {
            bufHasSignal=YES;
        }
        for(int i=_n;i<512;++i) _buf[i]=0.f;
        _peakEnv=ArpSIDUIClamp01(_peakEnv*.82f+pk*.18f,_peakEnv);
        const float rms=(_n>0)?(float)std::sqrt(sumSquares/(double)_n):0.f;
        _rmsEnv=ArpSIDUIClamp01(_rmsEnv*.84f+rms*.16f,_rmsEnv);
        // The sweep only advances on real signal above the deadzone; with the trace
        // snapped flat and the phase frozen, an idle scope holds completely still.
        const float motionStep=(pk>kScopeIdleDeadzone||_rmsEnv>kScopeIdleDeadzone)?(0.017f+pk*0.011f+_rmsEnv*0.006f):0.0f;
        _motionPhase=fmodf(_motionPhase+motionStep,1.f);
    }
    if(_peakEnv<1e-4f) _peakEnv=0.f;
    if(_rmsEnv<1e-4f) _rmsEnv=0.f;
    // Idle redraw fix: once the live trace, the phosphor trail and the peak/RMS
    // envelopes have ALL settled to silence the rendered frame is identical every
    // tick. Draw that settled frame once, then stop invalidating so an idle editor
    // does no per-frame CoreGraphics work at all.
    const BOOL quiescent = !bufHasSignal && trailEnergy==0.f && _peakEnv==0.f && _rmsEnv==0.f;
    if(!quiescent || !_quiescentDrawn){ [self setNeedsDisplay:YES]; _quiescentDrawn=quiescent; }
}
-(void)drawRect:(NSRect)dr{(void)dr;
    NSRect b=self.bounds;
    const CGFloat W=b.size.width, H=b.size.height;
    const CGFloat ox=b.origin.x, oy=b.origin.y;

    // ── 1. Deep background ────────────────────────────────────────────────
    [[NSColor colorWithSRGBRed:.008f green:.022f blue:.010f alpha:1] setFill];
    [[NSBezierPath bezierPathWithRoundedRect:b xRadius:3 yRadius:3] fill];

    // ── 1b. Bezel glow and rear tube depth ───────────────────────────────
    {
        const CGFloat outerGlow = 0.03f + _peakEnv * 0.06f + _forensicActivity * 0.08f;
        [[(_accentColor?_accentColor:colOscLine()) colorWithAlphaComponent:outerGlow] setFill];
        [[NSBezierPath bezierPathWithRoundedRect:NSInsetRect(b, -3.0f, -2.0f) xRadius:6 yRadius:6] fill];
        [[NSColor colorWithSRGBRed:.00f green:.01f blue:.00f alpha:.92f] setFill];
        [[NSBezierPath bezierPathWithRoundedRect:NSInsetRect(b, 1.0f, 1.0f) xRadius:3 yRadius:3] fill];
    }

    // ── 2. Inner vignette (darker at edges) ───────────────────────────────
    {
        [ArpSIDScopeVignetteGradient()
            drawInBezierPath:[NSBezierPath bezierPathWithRoundedRect:b xRadius:3 yRadius:3]
            relativeCenterPosition:NSMakePoint(0,0)];
    }

    // ── 3. Subtle scanlines (horizontal, 2px repeat) ──────────────────────
    {
        NSBezierPath* sl=[NSBezierPath bezierPath];sl.lineWidth=.5f;
        [[NSColor colorWithSRGBRed:0 green:0 blue:0 alpha:.28f] setStroke];
        for(CGFloat sy=oy+1; sy<oy+H; sy+=2.5f){
            [sl moveToPoint:NSMakePoint(ox,sy)];[sl lineToPoint:NSMakePoint(ox+W,sy)];
        }
        [sl stroke];
    }

    // ── 4. Grid ───────────────────────────────────────────────────────────
    {
        NSBezierPath*grid=[NSBezierPath bezierPath];grid.lineWidth=.35f;
        [[c64DkGrey() colorWithAlphaComponent:.22f] setStroke];
        for(int g=1;g<4;++g){
            CGFloat gy=oy+H*g/4.0;
            [grid moveToPoint:NSMakePoint(ox,gy)];[grid lineToPoint:NSMakePoint(ox+W,gy)];
            CGFloat gx=ox+W*g/4.0;
            [grid moveToPoint:NSMakePoint(gx,oy)];[grid lineToPoint:NSMakePoint(gx,oy+H)];
        }
        [grid stroke];
    }
    // Centre line (brighter)
    {
        [[c64DkGrey() colorWithAlphaComponent:.55f] setStroke];
        NSBezierPath*cl=[NSBezierPath bezierPath];cl.lineWidth=.6f;
        CGFloat mid=oy+H*.5f;
        [cl moveToPoint:NSMakePoint(ox,mid)];[cl lineToPoint:NSMakePoint(ox+W,mid)];
        [cl stroke];
    }

    // ── 5. Phosphor sweep highlight (animated CRT electron beam) ─────────
    {
        const CGFloat sweepW=std::max<CGFloat>(10.f,W*.18f);
        const CGFloat sweepX=ox-sweepW+_motionPhase*(W+sweepW*2.f);
        NSRect sweepR=NSIntersectionRect(b,NSMakeRect(sweepX,oy,sweepW,H));
        if(!NSIsEmptyRect(sweepR)){
            NSColor* swC=(_accentColor?_accentColor:colOscLine());
            const float forensicBoost=0.04f+0.14f*_forensicActivity;
            [[swC colorWithAlphaComponent:(0.04f+0.07f*_peakEnv+forensicBoost)] setFill];
            NSRectFillUsingOperation(sweepR,NSCompositingOperationPlusLighter);
        }
    }

    // ── 5b. Perspective guide mesh / faux 3D tube ────────────────────────
    {
        [[c64LtBlue() colorWithAlphaComponent:(0.05f + _rmsEnv*0.05f + _forensicActivity*0.06f)] setStroke];
        NSBezierPath* mesh=[NSBezierPath bezierPath];
        mesh.lineWidth=.45f;
        for(int g=0; g<5; ++g){
            const CGFloat t=(CGFloat)(g+1)/6.0f;
            const CGFloat inset=4.0f + t*7.0f;
            [mesh moveToPoint:NSMakePoint(ox+inset, oy+2.0f+t*1.4f)];
            [mesh lineToPoint:NSMakePoint(ox+W-inset, oy+2.0f+t*1.4f)];
            [mesh moveToPoint:NSMakePoint(ox+inset, oy+H-2.0f-t*1.4f)];
            [mesh lineToPoint:NSMakePoint(ox+W-inset, oy+H-2.0f-t*1.4f)];
        }
        [mesh stroke];
    }

    if(_n<2) goto border;

    // ── 6. Phosphor trail (previous frame ghost) ──────────────────────────
    {
        NSBezierPath*tp=[NSBezierPath bezierPath];
        for(int i=0;i<_n;++i){
            CGFloat x=ox+W*(float)i/(_n-1);
            CGFloat y=oy+H*(0.5f+_trail[i]*0.47f);
            if(i==0)[tp moveToPoint:NSMakePoint(x,y)]; else[tp lineToPoint:NSMakePoint(x,y)];
        }
        tp.lineWidth=2.8f; tp.lineCapStyle=NSLineCapStyleRound; tp.lineJoinStyle=NSLineJoinStyleRound;
        NSColor* trC=_accentColor?_accentColor:colOscLine();
        [[trC colorWithAlphaComponent:(0.12f+0.10f*_peakEnv)] setStroke];
        [tp stroke];
    }

    // ── 7. Wide bloom pass (outer glow) ───────────────────────────────────
    {
        CGFloat glowA=std::clamp((double)_peakEnv*1.8+0.08,0.0,0.65);
        if(glowA>0.05f){
            NSBezierPath*gp=[NSBezierPath bezierPath];
            for(int i=0;i<_n;++i){
                CGFloat x=ox+W*(float)i/(_n-1);
                CGFloat y=oy+H*(0.5f+_buf[i]*0.47f);
                if(i==0)[gp moveToPoint:NSMakePoint(x,y)]; else[gp lineToPoint:NSMakePoint(x,y)];
            }
            gp.lineWidth=5.5f; gp.lineCapStyle=NSLineCapStyleRound;
            NSColor* bloomC=_accentColor?_accentColor:colOscLine();
            [[bloomC colorWithAlphaComponent:std::min(0.95, glowA*0.55+0.18f*_forensicActivity)] setStroke];
            [gp stroke];
        }
    }

    // ── 7b. Beam shadow under-trace for depth ────────────────────────────
    {
        NSBezierPath*sp=[NSBezierPath bezierPath];
        for(int i=0;i<_n;++i){
            CGFloat x=ox+W*(float)i/(_n-1);
            CGFloat y=oy+H*(0.5f+_buf[i]*0.47f)+1.6f;
            if(i==0)[sp moveToPoint:NSMakePoint(x,y)]; else[sp lineToPoint:NSMakePoint(x,y)];
        }
        sp.lineWidth=2.4f;
        [[NSColor colorWithSRGBRed:0 green:0 blue:0 alpha:(0.12f+0.12f*_peakEnv)] setStroke];
        [sp stroke];
    }

    // ── 8. Mid glow pass ──────────────────────────────────────────────────
    {
        CGFloat glowA=std::clamp((double)_peakEnv*1.4+0.12,0.0,0.80);
        if(glowA>0.08f){
            NSBezierPath*mp=[NSBezierPath bezierPath];
            for(int i=0;i<_n;++i){
                CGFloat x=ox+W*(float)i/(_n-1);
                CGFloat y=oy+H*(0.5f+_buf[i]*0.47f);
                if(i==0)[mp moveToPoint:NSMakePoint(x,y)]; else[mp lineToPoint:NSMakePoint(x,y)];
            }
            mp.lineWidth=2.8f; mp.lineCapStyle=NSLineCapStyleRound;
            NSColor* midC=_accentColor?_accentColor:colOscLine();
            [[midC colorWithAlphaComponent:std::min(0.95, glowA*0.75)] setStroke];
            [mp stroke];
        }
    }

    // ── 9. Main sharp waveform ────────────────────────────────────────────
    {
        NSBezierPath*wp=[NSBezierPath bezierPath];
        for(int i=0;i<_n;++i){
            CGFloat x=ox+W*(float)i/(_n-1);
            CGFloat y=oy+H*(0.5f+_buf[i]*0.47f);
            if(i==0)[wp moveToPoint:NSMakePoint(x,y)]; else[wp lineToPoint:NSMakePoint(x,y)];
        }
        wp.lineWidth=1.2f; wp.lineCapStyle=NSLineCapStyleRound; wp.lineJoinStyle=NSLineJoinStyleRound;
        NSColor*strokeC=_accentColor?_accentColor:colOscLine();
        // Brighten to near-white at high energy
        float hotBlend=std::clamp(_peakEnv*1.2f,0.f,1.f);
        NSColor* hotC=[strokeC blendedColorWithFraction:(CGFloat)hotBlend ofColor:c64White()];
        [(hotC?hotC:strokeC) setStroke];
        [wp stroke];
    }

    // ── 10. Transient sparkle dots ─────────────────────────────────────────
    if(_peakEnv>0.18f || _forensicActivity>0.06f){
        const float sparkAlpha=std::clamp(0.14f+0.22f*_peakEnv+0.18f*_forensicActivity,0.f,1.f);
        NSColor* spC=_accentColor?_accentColor:colOscLine();
        NSColor* spHot=[spC blendedColorWithFraction:.6f ofColor:c64White()];
        [[spHot?spHot:spC colorWithAlphaComponent:sparkAlpha] setFill];
        const int cnt=std::min(5,std::max(1,_n/64));
        for(int si=0;si<cnt;++si){
            int idx=std::clamp((int)lroundf(fmodf(_motionPhase+si*0.19f,1.f)*(_n-1)),0,_n-1);
            CGFloat x=ox+W*(float)idx/(_n-1);
            CGFloat y=oy+H*(0.5f+_buf[idx]*0.47f);
            const float sz=1.8f+1.5f*_peakEnv;
            [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(x-sz,y-sz,sz*2,sz*2)] fill];
        }
    }

    // ── 10b. Telemetry badges ─────────────────────────────────────────────
    {
        NSDictionary* meterAttrs=@{
            NSForegroundColorAttributeName:[c64LtGreen() colorWithAlphaComponent:(0.78f+0.16f*_peakEnv)],
            NSFontAttributeName:monoBF(6.8f)
        };
        NSDictionary* subAttrs=@{
            NSForegroundColorAttributeName:[c64LtBlue() colorWithAlphaComponent:.76f],
            NSFontAttributeName:monoF(6.4f)
        };
        [[NSString stringWithFormat:@"PK %@  RMS %@", ArpSIDPercentNormString(_peakEnv), ArpSIDPercentNormString(_rmsEnv)]
            drawAtPoint:NSMakePoint(ox+5.0f, oy+4.0f) withAttributes:meterAttrs];
        if(_forensicActivity > 0.01f){
            [[NSString stringWithFormat:@"FORENSIC %@", ArpSIDPercentNormString(_forensicActivity)]
                drawAtPoint:NSMakePoint(MAX(ox+5.0f, ox+W-74.0f), oy+4.0f) withAttributes:subAttrs];
        }
    }

    border:
    // ── 11. Border with subtle inner bevel ────────────────────────────────
    [[colBorder() colorWithAlphaComponent:.65f] setStroke];
    NSBezierPath*brd=[NSBezierPath bezierPathWithRoundedRect:NSInsetRect(b,.5f,.5f) xRadius:3 yRadius:3];
    brd.lineWidth=1;[brd stroke];
    // Top-left inner highlight (bevel illusion)
    [[c64LtBlue() colorWithAlphaComponent:.12f] setStroke];
    NSBezierPath*bvl=[NSBezierPath bezierPath]; bvl.lineWidth=.8f;
    [bvl moveToPoint:NSMakePoint(ox+1,oy+H-2)];[bvl lineToPoint:NSMakePoint(ox+W-2,oy+H-2)];
    [bvl moveToPoint:NSMakePoint(ox+1,oy+H-2)];[bvl lineToPoint:NSMakePoint(ox+1,oy+2)];
    [bvl stroke];
}
@end

// ─────────────────────────────────────────────────────────────────────────────
// MARK: - ArpSIDMeterView (stereo VU bars with peak hold)
// ─────────────────────────────────────────────────────────────────────────────
@interface ArpSIDMeterView : NSView
@property(nonatomic,assign) float forensicActivity;
-(void)setLevelL:(float)l rms:(float)rl levelR:(float)r rms:(float)rr;
@end

// ─── ArpSIDArpView — arpeggiator step display ─────────────────────────────────
@interface ArpSIDArpView : NSView
- (void)setCurrentStep:(int)step totalSteps:(int)total arpOn:(BOOL)on;
@end
@implementation ArpSIDArpView {
    int _step, _total; BOOL _arpOn;
}
- (instancetype)initWithFrame:(NSRect)r {
    self=[super initWithFrame:r]; if(self){_step=0;_total=8;_arpOn=NO;} return self; }
- (void)setCurrentStep:(int)s totalSteps:(int)t arpOn:(BOOL)on {
    if(_step==s&&_total==t&&_arpOn==on) return;
    _total=std::max(1,t); _step=std::clamp(s,0,_total-1); _arpOn=on; [self setNeedsDisplay:YES]; }
- (void)drawRect:(NSRect)dr4 { (void)dr4;
    NSRect b=self.bounds;
    [[NSColor colorWithSRGBRed:.012f green:.018f blue:.045f alpha:1] setFill];
    [[NSBezierPath bezierPathWithRoundedRect:b xRadius:3 yRadius:3] fill];
    int n=std::min(_total,32);
    const CGFloat pw=(b.size.width-4)/std::max(1,n), ph=b.size.height-4;
    const float nowT=(float)CFAbsoluteTimeGetCurrent();
    for(int i=0;i<n;++i){
        const NSRect sr=NSMakeRect(b.origin.x+2+i*pw, b.origin.y+2, pw-1, ph);
        const BOOL active=_arpOn&&(i==_step);
        // Trail: previous step fades
        const int trail1=(_step-1+n)%n, trail2=(_step-2+n)%n;
        const BOOL isT1=_arpOn&&(i==trail1)&&n>2;
        const BOOL isT2=_arpOn&&(i==trail2)&&n>4;
        if(active){
            // Outer glow
            [[c64LtGreen() colorWithAlphaComponent:.28f] setFill];
            [[NSBezierPath bezierPathWithRoundedRect:NSInsetRect(sr,-1,-1) xRadius:2 yRadius:2] fill];
            // Main fill
            [c64LtGreen() setFill]; NSRectFill(sr);
            // Bright pulse overlay
            const float pulse=0.45f+0.55f*sinf(nowT*9.0f);
            [[c64White() colorWithAlphaComponent:(0.12f+0.22f*pulse)] setFill];
            NSRectFillUsingOperation(NSInsetRect(sr,1,1),NSCompositingOperationPlusLighter);
            // Top highlight bar
            [[c64White() colorWithAlphaComponent:.35f] setFill];
            NSRectFill(NSMakeRect(sr.origin.x+1,sr.origin.y+sr.size.height-2,sr.size.width-2,1.5f));
        } else if(isT1){
            [[c64Cyan() colorWithAlphaComponent:.42f] setFill]; NSRectFill(sr);
            [[c64White() colorWithAlphaComponent:.08f] setFill];
            NSRectFill(NSMakeRect(sr.origin.x,sr.origin.y+sr.size.height-1.5f,sr.size.width,1.5f));
        } else if(isT2){
            [[c64LtBlue() colorWithAlphaComponent:.22f] setFill]; NSRectFill(sr);
        } else {
            // Inactive step — subtle depth gradient
            [[c64DkGrey() colorWithAlphaComponent:.35f] setFill]; NSRectFill(sr);
            if(i%4==0){
                // Beat marker — slightly brighter
                [[c64DkGrey() colorWithAlphaComponent:.55f] setFill];
                NSRectFill(NSMakeRect(sr.origin.x,sr.origin.y+sr.size.height-1.5f,sr.size.width,1.5f));
            }
        }
    }
    [[colBorder() colorWithAlphaComponent:.55f] setStroke];
    [[NSBezierPath bezierPathWithRoundedRect:NSInsetRect(b,.5,.5) xRadius:3 yRadius:3] stroke]; }
@end

// ─── ArpSIDStripView mouse drag (pitchbend/mod wheel/breath interactive) ───────
// Add mouse handling to existing ArpSIDStripView by extending it with a block
// NOTE: ArpSIDStripView already defined above; we add action via _knobChg pattern
// Strip views get drag-to-control: vertical drag adjusts value, sends changeBlock

@implementation ArpSIDMeterView{
    float _pkL,_pkR,_rmsL,_rmsR;
    float _holdL,_holdR;       // peak hold bar positions [0..1]
    float _holdTimerL,_holdTimerR;  // frames until hold starts falling
    float _glossPhase;
    float _forensicActivity;
    NSRect _cachedTickBounds;
    NSBezierPath* _cachedTickPath;
    NSImage* _cachedScaleImage;
    BOOL _quiescentDrawn; // idle-redraw suppression: YES once the settled silent frame is on screen
}

- (void)_rebuildMeterTickCacheIfNeeded:(NSRect)b {
    if (_cachedTickPath && _cachedScaleImage && NSEqualRects(_cachedTickBounds, b)) return;
    _cachedTickBounds = b;
    _cachedTickPath = [NSBezierPath bezierPath];
    const CGFloat h = b.size.height;
    static const float kTicks[] = {0.f, .06f, .13f, .25f, .50f, .71f, 1.f};
    static const char* kTickL[] = {"-∞","-24","-18","-12","-6","-3","0"};
    static NSDictionary* ta=nil; if(!ta) ta=@{NSForegroundColorAttributeName:[colLabel() colorWithAlphaComponent:.50f],NSFontAttributeName:monoF(5.6f)};
    for (int i = 0; i < 7; ++i) {
        const CGFloat ty = b.origin.y + h * kTicks[i];
        [_cachedTickPath moveToPoint:NSMakePoint(NSMinX(b), ty)];
        [_cachedTickPath lineToPoint:NSMakePoint(NSMaxX(b), ty)];
    }
    _cachedTickPath.lineWidth = .5f;

    _cachedScaleImage = [[NSImage alloc] initWithSize:b.size];
    [_cachedScaleImage lockFocus];
    [[c64DkGrey() colorWithAlphaComponent:.35f] setStroke];
    NSAffineTransform* tx=[NSAffineTransform transform];
    [tx translateXBy:-b.origin.x yBy:-b.origin.y];
    [tx concat];
    [_cachedTickPath stroke];
    
    for(int i=0;i<7;++i){
        CGFloat ty = h * kTicks[i];
        NSString*ts=[NSString stringWithUTF8String:kTickL[i]];
        [ts drawAtPoint:NSMakePoint(1,ty+1) withAttributes:ta];
    }
    [_cachedScaleImage unlockFocus];
}
-(void)setForensicActivity:(float)v{float nv=ArpSIDUIClamp01(v); if(fabsf(nv-_forensicActivity)>0.001f){_forensicActivity=nv;_quiescentDrawn=NO;[self setNeedsDisplay:YES];}}
-(void)setLevelL:(float)l rms:(float)rl levelR:(float)r rms:(float)rr{
    _pkL=ArpSIDUIClamp01(l);
    _pkR=ArpSIDUIClamp01(r);
    _rmsL=ArpSIDUIClamp01(rl);
    _rmsR=ArpSIDUIClamp01(rr);
    if(_pkL>=_holdL){_holdL=_pkL;_holdTimerL=40;}else if(--_holdTimerL<=0)_holdL=std::max(0.f,_holdL-.008f);
    if(_pkR>=_holdR){_holdR=_pkR;_holdTimerR=40;}else if(--_holdTimerR<=0)_holdR=std::max(0.f,_holdR-.008f);
    _holdL=ArpSIDUIClamp01(_holdL);
    _holdR=ArpSIDUIClamp01(_holdR);
    // Idle visualizer fix: don't animate the meter gloss sweep when silent. The
    // constant baseline term used to drift even at zero level; gate it on actual
    // level / forensic activity so an idle meter sits still.
    const float glossStep=(_pkL>0.0008f||_pkR>0.0008f||_forensicActivity>0.004f)
        ?(0.017f+std::max(_pkL,_pkR)*0.015f+_forensicActivity*0.02f):0.0f;
    _glossPhase=fmodf(_glossPhase+glossStep,1.f);
    // Snap the falling peak-hold bars to exact rest so silence is a stable fixed
    // point, then suppress the redraw once the settled silent frame is on screen.
    if(_holdL<1e-4f) _holdL=0.f;
    if(_holdR<1e-4f) _holdR=0.f;
    const BOOL quiescent = _pkL<1e-4f && _pkR<1e-4f && _rmsL<1e-4f && _rmsR<1e-4f
                        && _holdL==0.f && _holdR==0.f && glossStep==0.0f;
    if(!quiescent || !_quiescentDrawn){ [self setNeedsDisplay:YES]; _quiescentDrawn=quiescent; }}
-(void)drawRect:(NSRect)dr2{(void)dr2;
    NSRect b=self.bounds;
    [[NSColor colorWithSRGBRed:.008f green:.012f blue:.025f alpha:1] setFill];
    [[NSBezierPath bezierPathWithRoundedRect:b xRadius:3 yRadius:3] fill];
    const CGFloat topLegendH=7.f;
    const CGFloat bottomLegendH=8.f;
    NSRect meterRect=NSInsetRect(b,2.0f,0.0f);
    meterRect.origin.y += bottomLegendH;
    meterRect.size.height -= (topLegendH + bottomLegendH);
    if(meterRect.size.height < 12.f) meterRect=NSInsetRect(b,2.0f,2.0f);
    const CGFloat h=meterRect.size.height;
    [self _rebuildMeterTickCacheIfNeeded:meterRect];
    [_cachedScaleImage drawInRect:meterRect];
    void(^drawBar)(CGFloat,CGFloat,float,float,float)=^(CGFloat x,CGFloat w,float pk,float rms,float hold){
        const int segCount=24;
        const CGFloat segH=h/segCount, segGap=1.2f, segFill=segH-segGap;
        const int litSegs=(int)(pk*segCount);
        for(int seg=0;seg<segCount;++seg){
            const float segNorm=(float)seg/segCount;
            const CGFloat sy=meterRect.origin.y+seg*segH;
            const NSRect sr=NSMakeRect(x,sy,w,segFill);
            NSColor*segC=(segNorm>.71f)?colMeterRd():(segNorm>.50f?colMeterYl():colMeterGn());
            if(seg<litSegs){
                [segC setFill]; NSRectFill(sr);
                [[c64White() colorWithAlphaComponent:.15f] setFill];
                NSRectFill(NSMakeRect(x,sy+segFill-1.2f,w,1.2f));
                if(segNorm<=rms){[[segC colorWithAlphaComponent:.28f] setFill];
                    NSRectFillUsingOperation(sr,NSCompositingOperationPlusLighter);}
            } else {
                [[c64DkGrey() colorWithAlphaComponent:.20f] setFill]; NSRectFill(sr);
            }
        }
        if(hold>0.01f){
            [[c64White() colorWithAlphaComponent:.88f] setFill];
            const CGFloat hy=meterRect.origin.y+h*hold;
            NSBezierPath*d=[NSBezierPath bezierPath];
            [d moveToPoint:NSMakePoint(x+w*.5f,hy+3)];[d lineToPoint:NSMakePoint(x+w-1,hy)];
            [d lineToPoint:NSMakePoint(x+w*.5f,hy-3)];[d lineToPoint:NSMakePoint(x+1,hy)];
            [d closePath];[d fill];}
    };
    drawBar(meterRect.origin.x,meterRect.size.width*0.5f-1.0f,_pkL,_rmsL,_holdL);
    drawBar(meterRect.origin.x+meterRect.size.width*0.5f+2.0f,meterRect.size.width*0.5f-2.0f,_pkR,_rmsR,_holdR);
    const CGFloat glossW=std::max<CGFloat>(7.f,b.size.width*.20f);
    const CGFloat glossX=meterRect.origin.x-glossW+_glossPhase*(meterRect.size.width+glossW*2.f);
    NSRect glossR=NSIntersectionRect(meterRect,NSMakeRect(glossX,meterRect.origin.y,glossW,meterRect.size.height));
    if(!NSIsEmptyRect(glossR)){
        [[c64White() colorWithAlphaComponent:(0.03f+0.07f*std::max(_pkL,_pkR)+0.10f*_forensicActivity)] setFill];
        NSRectFillUsingOperation(glossR,NSCompositingOperationPlusLighter);}
    [[c64White() colorWithAlphaComponent:.05f] setFill];
    NSRectFill(NSMakeRect(b.origin.x+1,NSMaxY(meterRect)-2.0f,b.size.width-2,1.5f));
    NSDictionary* legend=@{NSForegroundColorAttributeName:[colTitle() colorWithAlphaComponent:.86f],NSFontAttributeName:monoBF(5.8f)};
    NSDictionary* leftAttr=@{NSForegroundColorAttributeName:[colMeterGn() blendedColorWithFraction:(CGFloat)std::clamp(_pkL,0.f,1.f)*0.45f ofColor:c64White()],NSFontAttributeName:monoBF(5.8f)};
    NSDictionary* rightAttr=@{NSForegroundColorAttributeName:[colMeterYl() blendedColorWithFraction:(CGFloat)std::clamp(_pkR,0.f,1.f)*0.35f ofColor:c64White()],NSFontAttributeName:monoBF(5.8f)};
    [@"PK / RMS" drawAtPoint:NSMakePoint(b.origin.x+4,NSMaxY(b)-7.0f) withAttributes:legend];
    [[NSString stringWithFormat:@"L%02d",(int)lroundf(_pkL*99.0f)] drawAtPoint:NSMakePoint(b.origin.x+4,b.origin.y+1.0f) withAttributes:leftAttr];
    [[NSString stringWithFormat:@"R%02d",(int)lroundf(_pkR*99.0f)] drawAtPoint:NSMakePoint(NSMidX(b)+2.0f,b.origin.y+1.0f) withAttributes:rightAttr];
    [[colBorder() colorWithAlphaComponent:.62f] setStroke];
    [[NSBezierPath bezierPathWithRoundedRect:NSInsetRect(b,.5f,.5f) xRadius:3 yRadius:3] stroke];}
@end


// ─────────────────────────────────────────────────────────────────────────────
// MARK: - ArpSIDFilterResponseView (live filter curve + scope overlay)
// ─────────────────────────────────────────────────────────────────────────────
@interface ArpSIDFilterResponseView : NSView
@property(nonatomic,strong) NSColor* accentColor;
@property(nonatomic,assign) float forensicActivity;
@property(nonatomic,assign) BOOL emphasizeScopes;
- (void)updateWithCutoff:(float)cutoff
               resonance:(float)resonance
                 modeVol:(uint8_t)modeVol
                   drive:(float)drive
               envAmount:(float)envAmount
               lfoAmount:(float)lfoAmount
                keyTrack:(float)keyTrack
                envLevel:(float)envLevel
                lfoValue:(float)lfoValue
              inputScope:(const float*)inputScope
             outputScope:(const float*)outputScope
                   count:(int)count
                 playing:(BOOL)playing;
@end

@implementation ArpSIDFilterResponseView {
    float _cutoff, _resonance, _drive, _envAmount, _lfoAmount, _keyTrack, _envLevel, _lfoValue;
    uint8_t _modeVol;
    BOOL _playing;
    float _inputScope[256];
    float _outputScope[256];
    int _scopeCount;
    NSColor* _accentColor;
    float _forensicActivity;
    BOOL _emphasizeScopes;
    float _scopeEnergy;
    float _motionPhase;
    BOOL _quiescentDrawn; // idle-redraw suppression: YES once the settled frame is on screen
}

-(instancetype)initWithFrame:(NSRect)r{
    self=[super initWithFrame:r];
    if(self){
        memset(_inputScope,0,sizeof(_inputScope));
        memset(_outputScope,0,sizeof(_outputScope));
        _accentColor=c64Cyan();
        _forensicActivity=0.f;
        _emphasizeScopes=NO;
        _scopeEnergy=0.f;
        _motionPhase=0.f;
    }
    return self;
}
-(NSView*)hitTest:(NSPoint)point{(void)point;return nil;}
- (void)setAccentColor:(NSColor*)accentColor{
    NSColor* next = accentColor ? [accentColor colorUsingColorSpace:[NSColorSpace genericRGBColorSpace]] : c64Cyan();
    if((_accentColor == next) || [_accentColor isEqual:next]) return;
    _accentColor = next;
    _quiescentDrawn=NO;
    [self setNeedsDisplay:YES];
}
- (NSColor*)accentColor{return _accentColor;}
- (void)setForensicActivity:(float)forensicActivity{
    const float nv=ArpSIDUIClamp01(forensicActivity);
    if(fabsf(nv-_forensicActivity)>0.001f){_forensicActivity=nv;_quiescentDrawn=NO;[self setNeedsDisplay:YES];}
}
- (float)forensicActivity{return _forensicActivity;}
- (void)setEmphasizeScopes:(BOOL)emphasizeScopes{
    if(_emphasizeScopes!=emphasizeScopes){_emphasizeScopes=emphasizeScopes;_quiescentDrawn=NO;[self setNeedsDisplay:YES];}
}
- (BOOL)emphasizeScopes{return _emphasizeScopes;}
- (void)updateWithCutoff:(float)cutoff
               resonance:(float)resonance
                 modeVol:(uint8_t)modeVol
                   drive:(float)drive
               envAmount:(float)envAmount
               lfoAmount:(float)lfoAmount
                keyTrack:(float)keyTrack
                envLevel:(float)envLevel
                lfoValue:(float)lfoValue
              inputScope:(const float*)inputScope
             outputScope:(const float*)outputScope
                   count:(int)count
                 playing:(BOOL)playing
{
    const float nCutoff=ArpSIDUIClamp01(cutoff);
    const float nResonance=ArpSIDUIClamp01(resonance);
    const float nDrive=ArpSIDUIClamp01(drive);
    const float nEnvAmount=ArpSIDUIClamp01(envAmount);
    const float nLfoAmount=ArpSIDUIClamp01(lfoAmount);
    const float nKeyTrack=ArpSIDUIClamp01(keyTrack);
    const float nEnvLevel=ArpSIDUIClamp01(envLevel);
    const float nLfoValue=ArpSIDUIClampSigned(lfoValue);
    // The drawn filter curve depends on these scalars, so a change to any of them
    // must force a redraw even when the live scopes are idle/flat.
    const BOOL scalarsChanged =
        fabsf(nCutoff-_cutoff)>1e-4f || fabsf(nResonance-_resonance)>1e-4f ||
        fabsf(nDrive-_drive)>1e-4f || fabsf(nEnvAmount-_envAmount)>1e-4f ||
        fabsf(nLfoAmount-_lfoAmount)>1e-4f || fabsf(nKeyTrack-_keyTrack)>1e-4f ||
        fabsf(nEnvLevel-_envLevel)>1e-4f || fabsf(nLfoValue-_lfoValue)>1e-4f ||
        _modeVol!=modeVol || _playing!=playing;
    _cutoff=nCutoff;
    _resonance=nResonance;
    _drive=nDrive;
    _envAmount=nEnvAmount;
    _lfoAmount=nLfoAmount;
    _keyTrack=nKeyTrack;
    _envLevel=nEnvLevel;
    _lfoValue=nLfoValue;
    _modeVol=modeVol;
    _playing=playing;
    _scopeCount=std::clamp(count,0,256);
    if(inputScope&&_scopeCount>0) memcpy(_inputScope,inputScope,(size_t)_scopeCount*sizeof(float)); else memset(_inputScope,0,sizeof(_inputScope));
    if(outputScope&&_scopeCount>0) memcpy(_outputScope,outputScope,(size_t)_scopeCount*sizeof(float)); else memset(_outputScope,0,sizeof(_outputScope));
    float scopePk=0.f;
    for(int i=0;i<_scopeCount;++i){
        scopePk=std::max(scopePk,fabsf(_inputScope[i]));
        scopePk=std::max(scopePk,fabsf(_outputScope[i]));
    }
    // Idle SHAKE fix: below a small deadzone the filter trace is just DC/noise —
    // snap both traces flat so the panel is perfectly still until real signal.
    static constexpr float kFilterScopeIdleDeadzone = 0.012f;
    BOOL scopeHasSignal=YES;
    if(scopePk < kFilterScopeIdleDeadzone){
        memset(_inputScope,0,sizeof(_inputScope));
        memset(_outputScope,0,sizeof(_outputScope));
        scopePk=0.f;
        scopeHasSignal=NO;
    }
    _scopeEnergy=ArpSIDUIClamp01(_scopeEnergy*0.78f + scopePk*0.22f);
    // Idle SHAKE fix: the sweep advances ONLY on real scope energy (above the
    // deadzone) or forensic mode — NOT on transport-playing, so a rolling-but-
    // silent transport no longer creeps the beam. With the traces deadzoned flat
    // and the phase frozen, an idle filter trace is completely still.
    const float motionStep=(_scopeEnergy>kFilterScopeIdleDeadzone || _forensicActivity>0.012f)
        ? (0.010f + _scopeEnergy*0.014f + _forensicActivity*0.018f) : 0.0f;
    _motionPhase=fmodf(_motionPhase + motionStep, 1.0f);
    if(_scopeEnergy<1e-4f) _scopeEnergy=0.f;
    // Idle redraw fix: when the scalars are unchanged, the scopes have settled flat
    // and the sweep phase is frozen, the rendered frame is identical every tick.
    // Draw the settled frame once, then stop invalidating.
    const BOOL quiescent = !scopeHasSignal && _scopeEnergy==0.f && motionStep==0.0f;
    if(scalarsChanged || !quiescent || !_quiescentDrawn){ [self setNeedsDisplay:YES]; }
    _quiescentDrawn=quiescent;
}
-(void)drawRect:(NSRect)dirtyRect{(void)dirtyRect;
    NSRect b=NSInsetRect(self.bounds,2,3);
    if(NSIsEmptyRect(b)) return;
    NSColor* accent=[(_accentColor ? _accentColor : c64Cyan()) colorUsingColorSpace:[NSColorSpace genericRGBColorSpace]];
    NSColor* inputColor=[[accent blendedColorWithFraction:0.68f ofColor:c64LtBlue()] colorUsingColorSpace:[NSColorSpace genericRGBColorSpace]];
    NSColor* outputColor=[[accent blendedColorWithFraction:0.38f ofColor:c64LtGreen()] colorUsingColorSpace:[NSColorSpace genericRGBColorSpace]];
    const CGFloat activityGlow = 0.05f + _forensicActivity * (_emphasizeScopes ? 0.22f : 0.14f);

    NSGradient* bg=[[NSGradient alloc] initWithColorsAndLocations:
                    ArpSIDRGB(0.01,0.02,0.05,0.94), 0.0,
                    [[accent blendedColorWithFraction:0.90f ofColor:ArpSIDRGB(0.03,0.06,0.10,1.0)] colorWithAlphaComponent:(0.22f + activityGlow*0.35f)], 0.48,
                    ArpSIDRGB(0.01,0.018,0.04,0.96), 1.0,
                    nil];
    [bg drawInBezierPath:[NSBezierPath bezierPathWithRoundedRect:b xRadius:4 yRadius:4] angle:90.0];
    for(int layer=0; layer<3; ++layer){
        const CGFloat inset=3.0f + (CGFloat)layer*4.0f;
        const CGFloat alpha=(0.020f + activityGlow*0.08f) * (1.0f - (CGFloat)layer*0.22f);
        [[accent colorWithAlphaComponent:alpha] setStroke];
        NSBezierPath* ring=[NSBezierPath bezierPathWithRoundedRect:NSInsetRect(b, inset, inset*0.8f) xRadius:7.0f+layer*2.0f yRadius:7.0f+layer*2.0f];
        ring.lineWidth=0.7f;
        [ring stroke];
    }
    if(_forensicActivity > 0.001f){
        [[accent colorWithAlphaComponent:(0.03f + _forensicActivity*0.08f)] setFill];
        [[NSBezierPath bezierPathWithRoundedRect:NSInsetRect(b, 4.0f, 4.0f) xRadius:8.0f yRadius:8.0f] fill];
    }

    const CGFloat W=b.size.width, H=b.size.height;
    const CGFloat midY=b.origin.y+H*0.52f;
    const CGFloat cutoffX=b.origin.x+W*(0.04f+_cutoff*0.92f);
    const float envShift=(_envLevel-0.5f)*_envAmount*0.45f;
    const float lfoShift=_lfoValue*_lfoAmount*0.35f;
    const float modCutoff=ArpSIDUIClamp01(_cutoff+envShift+lfoShift,_cutoff);
    const CGFloat modX=b.origin.x+W*(0.04f+modCutoff*0.92f);
    const BOOL lp=(_modeVol & 0x10u)!=0u;
    const BOOL bp=(_modeVol & 0x20u)!=0u;
    const BOOL hp=(_modeVol & 0x40u)!=0u;
    const BOOL direct=!lp&&!bp&&!hp;

    [[inputColor colorWithAlphaComponent:(0.08f + activityGlow*0.35f)] setStroke];
    for(int i=1;i<5;++i){
        CGFloat gx=b.origin.x+W*(CGFloat)i/5.f;
        NSBezierPath*p=[NSBezierPath bezierPath];
        [p moveToPoint:NSMakePoint(gx,b.origin.y+1)];
        [p lineToPoint:NSMakePoint(gx,b.origin.y+H-1)];
        p.lineWidth=.5f; [p stroke];
    }
    [[inputColor colorWithAlphaComponent:(0.12f + activityGlow*0.28f)] setStroke];
    NSBezierPath*mid=[NSBezierPath bezierPath];
    [mid moveToPoint:NSMakePoint(b.origin.x,midY)];
    [mid lineToPoint:NSMakePoint(b.origin.x+W,midY)];
    mid.lineWidth=.5f; [mid stroke];

    {
        [[c64White() colorWithAlphaComponent:(0.010f + _scopeEnergy*0.03f + _forensicActivity*0.03f)] setStroke];
        NSBezierPath* scan=[NSBezierPath bezierPath];
        scan.lineWidth=.45f;
        for(int i=0;i<5;++i){
            const CGFloat t=(CGFloat)i/4.0f;
            const CGFloat py=b.origin.y+H*(0.18f+t*0.16f);
            const CGFloat skew=3.0f + t*6.0f;
            [scan moveToPoint:NSMakePoint(b.origin.x+6.0f+skew, py)];
            [scan lineToPoint:NSMakePoint(b.origin.x+W-6.0f-skew, py)];
        }
        [scan stroke];
    }

    const CGFloat modBandX=MIN(cutoffX,modX);
    const CGFloat modBandW=MAX(1.5f,fabs(modX-cutoffX));
    [[accent colorWithAlphaComponent:(0.05f + _scopeEnergy*0.08f + activityGlow*0.24f)] setFill];
    NSRectFillUsingOperation(NSMakeRect(modBandX,b.origin.y+5,modBandW,H-10),NSCompositingOperationPlusLighter);

    NSBezierPath*curve=[NSBezierPath bezierPath];
    const float fc=std::clamp(0.05f+modCutoff*0.90f,0.05f,0.95f);
    const float q=0.12f+_resonance*0.88f;
    const float bandWidth=0.18f-(q*0.11f);
    for(int i=0;i<96;++i){
        const float x=(float)i/95.f;
        const float d=std::max(0.02f,fabsf(x-fc));
        const float lpResp=1.0f/(1.0f+powf(std::max(0.02f,x)/fc,2.0f+q*6.0f));
        const float hpResp=1.0f-lpResp;
        const float bpResp=expf(-(d*d)/(std::max(0.0006f,bandWidth*bandWidth)));
        float resp=direct?0.75f:0.0f;
        if(lp) resp=std::max(resp,lpResp);
        if(hp) resp=std::max(resp,hpResp);
        if(bp) resp=std::max(resp,bpResp*(0.35f+q*0.75f));
        const float peak=expf(-(d*d)/(std::max(0.0002f,bandWidth*bandWidth*0.30f)))*q*0.35f;
        resp=std::clamp(resp+peak,0.0f,1.15f);
        const CGFloat px=b.origin.x+x*W;
        const CGFloat py=b.origin.y+H*(0.10f+resp*0.76f);
        if(i==0) [curve moveToPoint:NSMakePoint(px,py)];
        else [curve lineToPoint:NSMakePoint(px,py)];
    }
    curve.lineWidth=2.0f+_drive*1.8f;
    [[accent colorWithAlphaComponent:(0.10f+_drive*0.18f+activityGlow*0.20f)] setStroke];
    [curve stroke];
    [[outputColor colorWithAlphaComponent:(0.52f+activityGlow*0.36f)] setStroke];
    curve.lineWidth=1.2f; [curve stroke];

    if(_scopeCount>8){
        NSBezierPath*inPath=[NSBezierPath bezierPath];
        NSBezierPath*outPath=[NSBezierPath bezierPath];
        for(int i=0;i<_scopeCount;++i){
            const float t=(float)i/(float)(_scopeCount-1);
            const CGFloat px=b.origin.x+t*W;
            const CGFloat pyIn=midY+_inputScope[i]*(H*0.16f);
            const CGFloat pyOut=midY+_outputScope[i]*(H*0.20f);
            if(i==0){ [inPath moveToPoint:NSMakePoint(px,pyIn)]; [outPath moveToPoint:NSMakePoint(px,pyOut)]; }
            else { [inPath lineToPoint:NSMakePoint(px,pyIn)]; [outPath lineToPoint:NSMakePoint(px,pyOut)]; }
        }
        [[inputColor colorWithAlphaComponent:(0.10f + (_emphasizeScopes ? 0.10f : 0.03f) + activityGlow*0.12f)] setStroke];
        inPath.lineWidth=_emphasizeScopes ? 1.4f : 0.8f; [inPath stroke];
        [[NSColor colorWithSRGBRed:0 green:0 blue:0 alpha:(0.10f + _scopeEnergy*0.10f)] setStroke];
        NSAffineTransform* shadowShift=[NSAffineTransform transform];
        [shadowShift translateXBy:0.0f yBy:-1.6f];
        NSBezierPath* outShadow=[outPath copy];
        [outShadow transformUsingAffineTransform:shadowShift];
        outShadow.lineWidth=_emphasizeScopes ? 2.8f : 1.6f;
        [outShadow stroke];
        [[outputColor colorWithAlphaComponent:(_playing?.42f:.24f) + (_emphasizeScopes ? 0.16f : 0.06f) + activityGlow*0.18f] setStroke];
        outPath.lineWidth=_emphasizeScopes ? 1.8f : 1.0f; [outPath stroke];
        if(_emphasizeScopes){
            [[outputColor colorWithAlphaComponent:(0.05f + activityGlow*0.08f + _scopeEnergy*0.10f)] setStroke];
            outPath.lineWidth=3.6f; [outPath stroke];
        }
    }

    {
        const CGFloat beamX = b.origin.x - 20.0f + _motionPhase * (W + 40.0f);
        NSRect beamRect = NSIntersectionRect(b, NSMakeRect(beamX, b.origin.y+4.0f, std::max<CGFloat>(18.0f, W*0.11f), H-8.0f));
        if(!NSIsEmptyRect(beamRect)){
            [[accent colorWithAlphaComponent:(0.03f + _scopeEnergy*0.05f + activityGlow*0.12f)] setFill];
            NSRectFillUsingOperation(beamRect, NSCompositingOperationPlusLighter);
        }
    }

    [[accent colorWithAlphaComponent:(0.18f + activityGlow*0.40f)] setFill];
    NSRectFill(NSMakeRect(cutoffX-1.0f,b.origin.y+4,2.0f,H-8));
    [[c64White() colorWithAlphaComponent:(_playing?.26f:.14f) + activityGlow*0.24f] setFill];
    NSRectFill(NSMakeRect(modX-0.8f,b.origin.y+2,1.6f,H-4));

    NSDictionary*attr=@{NSForegroundColorAttributeName:[colLabel() colorWithAlphaComponent:.72f],NSFontAttributeName:monoF(7.0f)};
    NSString*modeStr=ArpSIDFilterModeString(_modeVol);
    NSString*desc=[NSString stringWithFormat:@"%@  CUT %@  RES %@  DRV %@  ENV %@  LFO %@  KEY %@",
                   modeStr, ArpSIDPercentNormString(_cutoff), ArpSIDPercentNormString(_resonance),
                   ArpSIDPercentNormString(_drive), ArpSIDPercentNormString(_envAmount),
                   ArpSIDPercentNormString(_lfoAmount), ArpSIDPercentNormString(_keyTrack)];
    [desc drawAtPoint:NSMakePoint(b.origin.x+4,b.origin.y+3) withAttributes:attr];
    NSDictionary*legend=@{NSForegroundColorAttributeName:[accent colorWithAlphaComponent:.86f],NSFontAttributeName:monoBF(6.6f)};
    [[NSString stringWithFormat:@"IN  OUT  MOD %@",
       (_forensicActivity > 0.02f ? ArpSIDPercentNormString(_forensicActivity) : @"")] drawAtPoint:NSMakePoint(NSMaxX(b)-88.0f,b.origin.y+3) withAttributes:legend];
    [[colBorder() colorWithAlphaComponent:.58f] setStroke];
    [[NSBezierPath bezierPathWithRoundedRect:NSInsetRect(b,0.5f,0.5f) xRadius:4.0f yRadius:4.0f] stroke];
}
@end

// ─────────────────────────────────────────────────────────────────────────────
// MARK: - ArpSIDLFOWaveView (animated LFO monitor)
// ─────────────────────────────────────────────────────────────────────────────
@interface ArpSIDLFOWaveView : NSView
@property(nonatomic,strong) NSColor* accentColor;
- (void)updatePhase:(float)phase
              value:(float)value
              depth:(float)depth
              shape:(float)shape
               sync:(BOOL)sync
               rate:(float)rate
               beat:(double)beat
            playing:(BOOL)playing;
@end

static inline float ArpSIDDisplayLfoWave(int shapeIndex, float t) {
    t = t - floorf(t);
    switch (shapeIndex) {
        case 0: return sinf(t * (float)(2.0 * M_PI));
        case 1: return t < 0.5f ? (4.0f * t - 1.0f) : (3.0f - 4.0f * t);
        case 2: return 2.0f * t - 1.0f;
        case 3: return 1.0f - 2.0f * t;
        case 4: return t < 0.5f ? 1.0f : -1.0f;
        case 5: {
            const int seg = (int)floorf(t * 8.0f);
            const uint32_t seed = 0x9E3779B9u ^ (uint32_t)(seg * 1103515245u + 12345u);
            return ((float)(seed & 1023u) / 511.5f) - 1.0f;
        }
        case 6: {
            const int seg = (int)floorf(t * 8.0f);
            const float local = t * 8.0f - (float)seg;
            const uint32_t seedA = 0xA511E9B3u ^ (uint32_t)(seg * 1664525u + 1013904223u);
            const uint32_t seedB = 0x63D83595u ^ (uint32_t)((seg + 1) * 1664525u + 1013904223u);
            const float a = ((float)(seedA & 1023u) / 511.5f) - 1.0f;
            const float b = ((float)(seedB & 1023u) / 511.5f) - 1.0f;
            return a + (b - a) * local;
        }
        default: return 0.0f;
    }
}

@implementation ArpSIDLFOWaveView {
    float _phase, _value, _depth, _shape, _rate;
    double _beat;
    BOOL _sync, _playing;
}
-(instancetype)initWithFrame:(NSRect)r{ self=[super initWithFrame:r]; if(self){ _accentColor=c64Cyan(); } return self; }
-(NSView*)hitTest:(NSPoint)point{(void)point;return nil;}
- (void)updatePhase:(float)phase
              value:(float)value
              depth:(float)depth
              shape:(float)shape
               sync:(BOOL)sync
               rate:(float)rate
               beat:(double)beat
            playing:(BOOL)playing
{
    _phase=ArpSIDUIClamp01(phase);
    _value=ArpSIDUIClampSigned(value);
    _depth=ArpSIDUIClamp01(depth);
    _shape=ArpSIDUIClamp01(shape);
    _sync=sync;
    _rate=ArpSIDUIClamp01(rate);
    _beat=ArpSIDUIFiniteDouble(beat,0.0);
    _playing=playing;
    [self setNeedsDisplay:YES];
}
-(void)drawRect:(NSRect)dirtyRect{(void)dirtyRect;
    NSRect b=NSInsetRect(self.bounds,3,4);
    if(NSIsEmptyRect(b)) return;
    NSColor*accent=_accentColor ? _accentColor : c64Cyan();
    [[accent colorWithAlphaComponent:.06f] setFill];
    [[NSBezierPath bezierPathWithRoundedRect:b xRadius:4 yRadius:4] fill];
    [[accent colorWithAlphaComponent:.10f] setStroke];
    for(int i=1;i<4;++i){
        const CGFloat gx=b.origin.x+b.size.width*(CGFloat)i/4.f;
        NSBezierPath*p=[NSBezierPath bezierPath];
        [p moveToPoint:NSMakePoint(gx,b.origin.y+1)];
        [p lineToPoint:NSMakePoint(gx,b.origin.y+b.size.height-1)];
        p.lineWidth=.5f; [p stroke];
    }
    if(_sync){
        const CGFloat beatFrac=(CGFloat)fmod(std::max(0.0,_beat),1.0);
        [[c64White() colorWithAlphaComponent:(_playing?.15f:.08f)] setFill];
        NSRectFill(NSMakeRect(b.origin.x,b.origin.y+b.size.height-2,b.size.width*beatFrac,2));
    }
    const int shapeIdx=std::clamp((int)lroundf(_shape*6.0f),0,6);
    const float amp=0.18f+0.78f*_depth;
    const CGFloat midY=b.origin.y+b.size.height*0.5f;
    NSBezierPath*path=[NSBezierPath bezierPath];
    for(int i=0;i<80;++i){
        const float x=(float)i/79.f;
        const float sample=ArpSIDDisplayLfoWave(shapeIdx,x+_phase)*amp;
        const CGFloat px=b.origin.x+x*b.size.width;
        const CGFloat py=midY+sample*(b.size.height*0.38f);
        if(i==0) [path moveToPoint:NSMakePoint(px,py)];
        else [path lineToPoint:NSMakePoint(px,py)];
    }
    [[accent colorWithAlphaComponent:.18f+_depth*.18f] setStroke];
    path.lineWidth=2.6f; [path stroke];
    [[accent colorWithAlphaComponent:.88f] setStroke];
    path.lineWidth=1.2f; [path stroke];

    const CGFloat currentX=b.origin.x+_phase*b.size.width;
    const CGFloat currentY=midY+_value*(b.size.height*0.38f);
    [[c64White() colorWithAlphaComponent:.20f] setFill];
    NSRectFill(NSMakeRect(currentX-0.75f,b.origin.y+3,1.5f,b.size.height-6));
    [[accent blendedColorWithFraction:.45f ofColor:c64White()] setFill];
    [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(currentX-3,currentY-3,6,6)] fill];

    NSDictionary*attr=@{NSForegroundColorAttributeName:[accent colorWithAlphaComponent:.78f],NSFontAttributeName:monoF(7.0f)};
    NSString*label=[NSString stringWithFormat:@"%@  %@  %@", _sync?@"SYNC":@"FREE", ArpSIDPercentNormString(_depth), ArpSIDPercentNormString(_rate)];
    [label drawAtPoint:NSMakePoint(b.origin.x+4,b.origin.y+3) withAttributes:attr];
}
@end

// ─────────────────────────────────────────────────────────────────────────────
// MARK: - ArpSIDSeqStepView (sequencer playhead strip)
// ─────────────────────────────────────────────────────────────────────────────
@interface ArpSIDSeqStepView : NSView
- (void)setCurrentStep:(int)step
            totalSteps:(int)total
               enabled:(BOOL)enabled
                 swing:(float)swing
              drumMode:(BOOL)drumMode
             stepNotes:(const uint8_t*)stepNotes
             stepGates:(const float*)stepGates;
@end

@implementation ArpSIDSeqStepView {
    int _step, _total;
    BOOL _enabled;
    BOOL _drumMode;
    float _swing;
    uint8_t _stepNotes[32];
    float _stepGates[32];
}
-(instancetype)initWithFrame:(NSRect)r{ self=[super initWithFrame:r]; if(self){ _step=0; _total=16; _enabled=NO; _swing=0.f; } return self; }
-(NSView*)hitTest:(NSPoint)point{(void)point;return nil;}
- (void)setCurrentStep:(int)step
            totalSteps:(int)total
               enabled:(BOOL)enabled
                 swing:(float)swing
              drumMode:(BOOL)drumMode
             stepNotes:(const uint8_t*)stepNotes
             stepGates:(const float*)stepGates
{
    _step=std::max(0,step);
    _total=std::max(1,total);
    _enabled=enabled;
    _drumMode=drumMode;
    _swing=ArpSIDUIClamp01(swing);
    memset(_stepNotes,0,sizeof(_stepNotes));
    memset(_stepGates,0,sizeof(_stepGates));
    if(stepNotes) memcpy(_stepNotes, stepNotes, sizeof(_stepNotes));
    if(stepGates) memcpy(_stepGates, stepGates, sizeof(_stepGates));
    [self setNeedsDisplay:YES];
}
-(void)drawRect:(NSRect)dirtyRect{(void)dirtyRect;
    NSRect b=self.bounds;
    [[NSColor colorWithSRGBRed:.01f green:.015f blue:.03f alpha:.65f] setFill];
    [[NSBezierPath bezierPathWithRoundedRect:b xRadius:3 yRadius:3] fill];
    const int n=std::min(_total,32);
    const CGFloat pw=(b.size.width-4)/std::max(1,n);
    for(int i=0;i<n;++i){
        const BOOL active=_enabled && i==(_step % std::max(1,_total));
        const BOOL odd=(i&1)!=0;
        const NSRect cell=NSMakeRect(b.origin.x+2+i*pw,b.origin.y+2,pw-1,b.size.height-4);
        const float gate=std::clamp(_stepGates[i],0.f,1.f);
        const BOOL programmed=gate>0.01f;
        NSColor*laneColor=_drumMode?ArpSIDDrumColorForLane(ArpSIDDrumLaneIndexForMidiNote((int)_stepNotes[i])):(odd?c64LtBlue():c64Cyan());
        NSColor*base=programmed?[laneColor colorWithAlphaComponent:(0.10f+_swing*0.14f)]:((odd?[c64LtBlue() colorWithAlphaComponent:(0.07f+_swing*0.10f)]:[c64Cyan() colorWithAlphaComponent:.05f]));
        [base setFill]; NSRectFill(cell);
        if(programmed && _drumMode){
            [[laneColor colorWithAlphaComponent:.26f] setFill];
            NSRectFill(NSInsetRect(cell,1,2));
        }
        if(active){
            [[c64Yellow() colorWithAlphaComponent:.18f] setFill];
            NSRectFill(NSInsetRect(cell,-1,-1));
            [[(_drumMode ? laneColor : c64LtGreen()) colorWithAlphaComponent:.95f] setFill];
            NSRectFill(cell);
        }
    }
    [[colBorder() colorWithAlphaComponent:.45f] setStroke];
    [[NSBezierPath bezierPathWithRoundedRect:NSInsetRect(b,.5f,.5f) xRadius:3 yRadius:3] stroke];
}
@end

// ─────────────────────────────────────────────────────────────────────────────
// MARK: - ArpSIDDrumPadGridView (playable DrSID pad matrix)
// ─────────────────────────────────────────────────────────────────────────────
@interface ArpSIDDrumPadGridView : NSView
@property(nonatomic,copy) void(^triggerBlock)(int midiNote, uint8_t velocity);
- (void)configurePadNotes:(const int*)notes count:(int)count;
- (void)updateLevels:(const float*)levels count:(int)count enabled:(BOOL)enabled lastNote:(int)lastNote selectedNote:(int)selectedNote;
- (void)updateGMNoteLevels:(const float*)levels count:(int)count enabled:(BOOL)enabled lastNote:(int)lastNote selectedNote:(int)selectedNote;
@end

@implementation ArpSIDDrumPadGridView {
    float _levels[8];
    float _gmNoteLevels[47];
    int _padNotes[16];
    int _padCount;
    BOOL _enabled;
    int _lastNote;
    int _selectedNote;
    NSInteger _hoverIndex;
    NSTrackingArea* _trackingArea;
}
// v963 accessibility: announce the pad grid to assistive tech (previously invisible).
-(BOOL)isAccessibilityElement{return YES;}
-(NSAccessibilityRole)accessibilityRole{return NSAccessibilityGroupRole;}
-(NSString*)accessibilityLabel{return @"Drum performance pads. Click a pad to audition its GM drum; upper half plays louder, Shift accents, Option plays a ghost note.";}
-(instancetype)initWithFrame:(NSRect)r{
    self=[super initWithFrame:r];
    if(self){
        memset(_levels,0,sizeof(_levels));
        memset(_gmNoteLevels,0,sizeof(_gmNoteLevels));
        memset(_padNotes,0,sizeof(_padNotes));
        _padCount=16;
        _enabled=NO;
        _lastNote=-1;
        _selectedNote=-1;
        _hoverIndex=-1;
        const ArpSIDDrumKitDescriptor* kit=ArpSIDDrumKitAtIndex(0);
        if(kit) [self configurePadNotes:kit->padNotes.data() count:(int)kit->padNotes.size()];
    }
    return self;
}
-(BOOL)isFlipped{return NO;}
-(BOOL)acceptsFirstMouse:(NSEvent*)e{(void)e;return YES;}
-(void)updateTrackingAreas{
    [super updateTrackingAreas];
    if(_trackingArea) [self removeTrackingArea:_trackingArea];
    _trackingArea=[[NSTrackingArea alloc] initWithRect:self.bounds
                                               options:NSTrackingMouseMoved|NSTrackingMouseEnteredAndExited|NSTrackingActiveAlways|NSTrackingInVisibleRect
                                                 owner:self
                                              userInfo:nil];
    [self addTrackingArea:_trackingArea];
}
-(void)configurePadNotes:(const int*)notes count:(int)count{
    memset(_padNotes,0,sizeof(_padNotes));
    _padCount=std::clamp(count,1,16);
    if(notes && _padCount>0) memcpy(_padNotes, notes, (size_t)_padCount*sizeof(int));
    [self setNeedsDisplay:YES];
}
-(NSInteger)_padIndexForPoint:(NSPoint)pt{
    NSRect b=NSInsetRect(self.bounds,4,4);
    if(!NSPointInRect(pt,b)) return -1;
    const NSInteger cols=4;
    const NSInteger rows=std::max<NSInteger>(1, (_padCount + cols - 1) / cols);
    const CGFloat cellW=(b.size.width-6)/4.0f;
    const CGFloat cellH=(b.size.height-(CGFloat)(rows-1)*2.0f)/(CGFloat)rows;
    const NSInteger col=std::clamp((NSInteger)((pt.x-b.origin.x)/std::max<CGFloat>(1.0,cellW+2.0)),(NSInteger)0,cols-1);
    const CGFloat relY=pt.y-b.origin.y;
    NSInteger row=(NSInteger)((relY)/std::max<CGFloat>(1.0,cellH+2.0));
    row=std::clamp((NSInteger)(rows-1-row),(NSInteger)0,rows-1);
    const NSInteger idx=row*cols+col;
    return (idx>=0&&idx<_padCount)?idx:-1;
}
-(void)mouseMoved:(NSEvent*)e{ _hoverIndex=[self _padIndexForPoint:[self convertPoint:e.locationInWindow fromView:nil]]; [self setNeedsDisplay:YES]; }
-(void)mouseExited:(NSEvent*)e{ (void)e; _hoverIndex=-1; [self setNeedsDisplay:YES]; }
-(void)mouseDown:(NSEvent*)e{
    const NSPoint pt=[self convertPoint:e.locationInWindow fromView:nil];
    const NSInteger idx=[self _padIndexForPoint:pt];
    if(idx<0 || idx>=_padCount || !_enabled) return;
    NSRect b=NSInsetRect(self.bounds,4,4);
    const NSInteger cols=4;
    const NSInteger rows=std::max<NSInteger>(1, (_padCount + cols - 1) / cols);
    const CGFloat cellW=(b.size.width-6)/4.0f;
    const CGFloat cellH=(b.size.height-(CGFloat)(rows-1)*2.0f)/(CGFloat)rows;
    const NSInteger row=idx/cols, col=idx%cols;
    const NSRect cell=NSMakeRect(b.origin.x+col*(cellW+2.0f),
                                 b.origin.y+(rows-1-row)*(cellH+2.0f),
                                 cellW, cellH);
    _lastNote=_padNotes[idx];
    _selectedNote=_lastNote;
    uint8_t velocity=112;
    const NSEventModifierFlags mods=e.modifierFlags;
    if((mods & NSEventModifierFlagShift) != 0){
        velocity=127;
    } else if((mods & NSEventModifierFlagOption) != 0){
        velocity=72;
    } else {
        const float yNorm=std::clamp((float)((pt.y-cell.origin.y)/std::max<CGFloat>(1.0, cell.size.height)), 0.0f, 1.0f);
        velocity=(uint8_t)std::clamp((int)lround((0.40f + 0.60f*yNorm) * 127.0f), 36, 127);
    }
    if(self.triggerBlock) self.triggerBlock(_lastNote, velocity);
    [self setNeedsDisplay:YES];
}
- (void)updateLevels:(const float*)levels count:(int)count enabled:(BOOL)enabled lastNote:(int)lastNote selectedNote:(int)selectedNote{
    memset(_levels,0,sizeof(_levels));
    const int n=std::min(8,std::max(0,count));
    if(levels&&n>0) memcpy(_levels,levels,(size_t)n*sizeof(float));
    _enabled=enabled;
    _lastNote=lastNote;
    _selectedNote=selectedNote;
    [self setNeedsDisplay:YES];
}
- (void)updateGMNoteLevels:(const float*)levels count:(int)count enabled:(BOOL)enabled lastNote:(int)lastNote selectedNote:(int)selectedNote{
    memset(_gmNoteLevels,0,sizeof(_gmNoteLevels));
    const int n=std::min(47,std::max(0,count));
    if(levels&&n>0) memcpy(_gmNoteLevels,levels,(size_t)n*sizeof(float));
    _enabled=enabled;
    _lastNote=lastNote;
    _selectedNote=selectedNote;
    [self setNeedsDisplay:YES];
}
-(void)drawRect:(NSRect)dirtyRect{(void)dirtyRect;
    NSRect b=NSInsetRect(self.bounds,4,4);
    if(NSIsEmptyRect(b)) return;
    const NSInteger cols=4;
    const NSInteger rows=std::max<NSInteger>(1, (_padCount + cols - 1) / cols);
    const CGFloat cellW=(b.size.width-6)/4.0f;
    const CGFloat cellH=(b.size.height-(CGFloat)(rows-1)*2.0f)/(CGFloat)rows;
    for(NSInteger idx=0; idx<_padCount; ++idx){
        const NSInteger row=idx/cols, col=idx%cols;
        const NSRect cell=NSMakeRect(b.origin.x+col*(cellW+2.0f),
                                     b.origin.y+(rows-1-row)*(cellH+2.0f),
                                     cellW, cellH);
        const int midi=_padNotes[idx];
        const int lane=ArpSIDDrumLaneIndexForMidiNote(midi);
        const BOOL focused=(_lastNote==midi);
        const BOOL selected=(_selectedNote==midi);
        const BOOL hovered=(_hoverIndex==idx);
        const int gmIdx=(midi>=35&&midi<=81)?(midi-35):-1;
        const float exactLevel=(gmIdx>=0&&gmIdx<47)?_gmNoteLevels[gmIdx]:0.0f;
        const float level=std::clamp(std::max(exactLevel,_levels[lane]*0.35f),0.f,1.f);
        NSColor*laneColor=ArpSIDDrumColorForLane(lane);
        [(_enabled?[laneColor colorWithAlphaComponent:(0.08f+0.18f*level)]:[c64DkGrey() colorWithAlphaComponent:.14f]) setFill];
        [[NSBezierPath bezierPathWithRoundedRect:cell xRadius:5 yRadius:5] fill];
        if(focused||hovered||selected){
            const CGFloat glow=focused?0.30f:(selected?0.22f:0.18f);
            [[laneColor colorWithAlphaComponent:glow] setFill];
            [[NSBezierPath bezierPathWithRoundedRect:NSInsetRect(cell,-1,-1) xRadius:6 yRadius:6] fill];
        }
        const NSRect meter=NSMakeRect(cell.origin.x+4, cell.origin.y+4, std::max<CGFloat>(2.0f,(cell.size.width-8)*level), 4);
        [[laneColor colorWithAlphaComponent:(_enabled?0.88f:0.25f)] setFill];
        [[NSBezierPath bezierPathWithRoundedRect:meter xRadius:2 yRadius:2] fill];
        NSDictionary*nameAttr=@{NSForegroundColorAttributeName:(_enabled?laneColor:[colLabel() colorWithAlphaComponent:.55f]),NSFontAttributeName:monoBF(7.5f)};
        NSDictionary*subAttr=@{NSForegroundColorAttributeName:[colLabel() colorWithAlphaComponent:.72f],NSFontAttributeName:monoF(7)};
        NSDictionary*noteAttr=@{NSForegroundColorAttributeName:[colValue() colorWithAlphaComponent:.86f],NSFontAttributeName:monoF(6.5f)};
        [ArpSIDDrumPerformancePadTitle(midi) drawAtPoint:NSMakePoint(cell.origin.x+6,cell.origin.y+cell.size.height-14) withAttributes:nameAttr];
        [[NSString stringWithFormat:@"MIDI %d", midi] drawAtPoint:NSMakePoint(cell.origin.x+6,cell.origin.y+16) withAttributes:subAttr];
        [ArpSIDNoteNameString(midi) drawAtPoint:NSMakePoint(cell.origin.x+6,cell.origin.y+7) withAttributes:noteAttr];
    }
    [[colBorder() colorWithAlphaComponent:.40f] setStroke];
    [[NSBezierPath bezierPathWithRoundedRect:NSInsetRect(self.bounds,.5f,.5f) xRadius:4 yRadius:4] stroke];
}
@end

// ─────────────────────────────────────────────────────────────────────────────
// MARK: - ArpSIDDrumStepEditorView (interactive 16-step DrSID note editor)
// ─────────────────────────────────────────────────────────────────────────────
@interface ArpSIDDrumStepEditorView : NSView
@property(nonatomic,copy) void(^stepTapBlock)(NSInteger stepIndex, NSEventModifierFlags modifiers);
- (void)updateNotes:(const uint8_t*)notes
         velocities:(const float*)velocities
             gates:(const float*)gates
       currentStep:(int)currentStep
      selectedNote:(int)selectedNote
           enabled:(BOOL)enabled;
@end

@implementation ArpSIDDrumStepEditorView {
    uint8_t _notes[16];
    float _velocities[16];
    float _gates[16];
    int _currentStep;
    int _selectedNote;
    BOOL _enabled;
    NSInteger _hoverStep;
    NSTrackingArea* _trackingArea;
}
-(instancetype)initWithFrame:(NSRect)r{
    self=[super initWithFrame:r];
    if(self){
        memset(_notes,0,sizeof(_notes));
        memset(_velocities,0,sizeof(_velocities));
        memset(_gates,0,sizeof(_gates));
        _currentStep=-1;
        _selectedNote=-1;
        _enabled=NO;
        _hoverStep=-1;
    }
    return self;
}
-(BOOL)acceptsFirstMouse:(NSEvent*)e{(void)e;return YES;}
-(void)updateTrackingAreas{
    [super updateTrackingAreas];
    if(_trackingArea) [self removeTrackingArea:_trackingArea];
    _trackingArea=[[NSTrackingArea alloc] initWithRect:self.bounds
                                               options:NSTrackingMouseMoved|NSTrackingMouseEnteredAndExited|NSTrackingActiveAlways|NSTrackingInVisibleRect
                                                 owner:self
                                              userInfo:nil];
    [self addTrackingArea:_trackingArea];
}
-(NSInteger)_stepIndexForPoint:(NSPoint)pt{
    NSRect b=NSInsetRect(self.bounds,4,4);
    if(!NSPointInRect(pt,b)) return -1;
    const CGFloat cellW=(b.size.width-15.0f)/16.0f;
    const NSInteger idx=(NSInteger)((pt.x-b.origin.x)/std::max<CGFloat>(1.0f,cellW+1.0f));
    return std::clamp<NSInteger>(idx,0,15);
}
-(void)mouseMoved:(NSEvent*)e{ _hoverStep=[self _stepIndexForPoint:[self convertPoint:e.locationInWindow fromView:nil]]; [self setNeedsDisplay:YES]; }
-(void)mouseExited:(NSEvent*)e{ (void)e; _hoverStep=-1; [self setNeedsDisplay:YES]; }
-(void)mouseDown:(NSEvent*)e{
    const NSInteger idx=[self _stepIndexForPoint:[self convertPoint:e.locationInWindow fromView:nil]];
    if(idx<0 || idx>=16 || !self.stepTapBlock) return;
    self.stepTapBlock(idx, e.modifierFlags);
}
- (void)updateNotes:(const uint8_t*)notes
         velocities:(const float*)velocities
             gates:(const float*)gates
       currentStep:(int)currentStep
      selectedNote:(int)selectedNote
           enabled:(BOOL)enabled
{
    memset(_notes,0,sizeof(_notes));
    memset(_velocities,0,sizeof(_velocities));
    memset(_gates,0,sizeof(_gates));
    if(notes) memcpy(_notes, notes, sizeof(_notes));
    if(velocities) memcpy(_velocities, velocities, sizeof(_velocities));
    if(gates) memcpy(_gates, gates, sizeof(_gates));
    _currentStep=currentStep;
    _selectedNote=selectedNote;
    _enabled=enabled;
    [self setNeedsDisplay:YES];
}
-(void)drawRect:(NSRect)dirtyRect{(void)dirtyRect;
    NSRect b=NSInsetRect(self.bounds,4,4);
    if(NSIsEmptyRect(b)) return;
    const CGFloat cellW=(b.size.width-15.0f)/16.0f;
    for(NSInteger i=0;i<16;++i){
        const NSRect cell=NSMakeRect(b.origin.x+i*(cellW+1.0f), b.origin.y, cellW, b.size.height);
        const float gate=std::clamp(_gates[i],0.f,1.f);
        const float velocity=std::clamp(_velocities[i],0.f,1.f);
        const BOOL active=gate>0.01f;
        const int midi=(int)_notes[i];
        const int lane=ArpSIDDrumLaneIndexForMidiNote(midi);
        NSColor* laneColor=ArpSIDDrumColorForLane(lane);
        const BOOL isCurrent=(i==_currentStep);
        const BOOL hovered=(i==_hoverStep);
        const BOOL matchesSelected=(active && midi==_selectedNote && _selectedNote>=0);
        NSColor* fill=active?[laneColor colorWithAlphaComponent:(0.08f+gate*0.10f+velocity*0.16f)]:[ArpSIDRGB(0.07,0.09,0.14,0.80) colorWithAlphaComponent:1.0f];
        [fill setFill];
        [[NSBezierPath bezierPathWithRoundedRect:cell xRadius:3 yRadius:3] fill];
        if(isCurrent || hovered || matchesSelected){
            const CGFloat glow=isCurrent?0.30f:(matchesSelected?0.20f:0.14f);
            [[laneColor colorWithAlphaComponent:glow] setFill];
            [[NSBezierPath bezierPathWithRoundedRect:NSInsetRect(cell,-1,-1) xRadius:4 yRadius:4] fill];
        }
        if(active){
            const CGFloat velH=std::max<CGFloat>(2.0f,(cell.size.height-18.0f)*velocity);
            [[laneColor colorWithAlphaComponent:(_enabled?0.86f:0.30f)] setFill];
            [[NSBezierPath bezierPathWithRoundedRect:NSMakeRect(cell.origin.x+2, cell.origin.y+6, 3, velH) xRadius:1.5f yRadius:1.5f] fill];
            const CGFloat gateW=std::max<CGFloat>(2.0f,(cell.size.width-10.0f)*gate);
            [[laneColor colorWithAlphaComponent:0.70f] setFill];
            [[NSBezierPath bezierPathWithRoundedRect:NSMakeRect(cell.origin.x+6, cell.origin.y+2, gateW, 2.5f) xRadius:1.0f yRadius:1.0f] fill];
        }
        NSDictionary* stepAttr=@{NSForegroundColorAttributeName:[colLabel() colorWithAlphaComponent:.68f],NSFontAttributeName:monoF(6.2f)};
        NSDictionary* noteAttr=@{NSForegroundColorAttributeName:(active?[laneColor colorWithAlphaComponent:.96f]:[colLabel() colorWithAlphaComponent:.55f]),NSFontAttributeName:monoBF(6.4f)};
        NSDictionary* gateAttr=@{NSForegroundColorAttributeName:[colValue() colorWithAlphaComponent:.76f],NSFontAttributeName:monoF(5.4f)};
        NSDictionary* velAttr=@{NSForegroundColorAttributeName:[laneColor colorWithAlphaComponent:.82f],NSFontAttributeName:monoF(5.6f)};
        [[NSString stringWithFormat:@"%ld",(long)(i+1)] drawAtPoint:NSMakePoint(cell.origin.x+2,cell.origin.y+cell.size.height-9) withAttributes:stepAttr];
        if(active) [ArpSIDDrumVelocityTag(velocity) drawAtPoint:NSMakePoint(cell.origin.x+cell.size.width-14,cell.origin.y+cell.size.height-9) withAttributes:velAttr];
        NSString* noteLabel=active?ArpSIDGMDrumShortName(midi):@"--";
        [noteLabel drawAtPoint:NSMakePoint(cell.origin.x+7,cell.origin.y+cell.size.height*0.47f-4) withAttributes:noteAttr];
        NSString* gateLabel=active?[NSString stringWithFormat:@"%02d/%02d",(int)lroundf(velocity*99.0f),(int)lroundf(gate*99.0f)]:@"";
        [gateLabel drawAtPoint:NSMakePoint(cell.origin.x+7,cell.origin.y+5) withAttributes:gateAttr];
    }
    [[colBorder() colorWithAlphaComponent:.42f] setStroke];
    [[NSBezierPath bezierPathWithRoundedRect:NSInsetRect(self.bounds,.5f,.5f) xRadius:4 yRadius:4] stroke];
}
@end

// ─────────────────────────────────────────────────────────────────────────────
// MARK: - ArpSIDDrumPatternGridView (808-style 4-lane pattern editor)
// ─────────────────────────────────────────────────────────────────────────────
@interface ArpSIDDrumPatternGridView : NSView
@property(nonatomic,copy) void(^stepTapBlock)(NSInteger row, NSInteger stepIndex, NSEventModifierFlags modifiers);
- (void)updateNotes:(const uint8_t*)notes
         velocities:(const float*)velocities
             gates:(const float*)gates
       currentStep:(int)currentStep
            enabled:(BOOL)enabled;
@end

@implementation ArpSIDDrumPatternGridView{
    uint8_t _notes[16];
    float _velocities[16];
    float _gates[16];
    int _currentStep;
    BOOL _enabled;
    NSInteger _hoverRow;
    NSInteger _hoverStep;
    NSTrackingArea* _trackingArea;
}
-(instancetype)initWithFrame:(NSRect)r{
    self=[super initWithFrame:r];
    if(self){
        memset(_notes,0,sizeof(_notes));
        memset(_velocities,0,sizeof(_velocities));
        memset(_gates,0,sizeof(_gates));
        _currentStep=-1;
        _enabled=NO;
        _hoverRow=-1;
        _hoverStep=-1;
    }
    return self;
}
-(BOOL)acceptsFirstMouse:(NSEvent*)e{(void)e;return YES;}
-(void)updateTrackingAreas{
    [super updateTrackingAreas];
    if(_trackingArea) [self removeTrackingArea:_trackingArea];
    _trackingArea=[[NSTrackingArea alloc] initWithRect:self.bounds
                                               options:NSTrackingMouseMoved|NSTrackingMouseEnteredAndExited|NSTrackingActiveAlways|NSTrackingInVisibleRect
                                                 owner:self
                                              userInfo:nil];
    [self addTrackingArea:_trackingArea];
}
-(BOOL)_hitGridAtPoint:(NSPoint)pt row:(NSInteger*)outRow step:(NSInteger*)outStep{
    const NSRect b=NSInsetRect(self.bounds,8.f,6.f);
    const CGFloat labelW=28.f;
    const CGFloat cellGap=7.f;
    const CGFloat rowGap=10.f;
    const CGFloat gridX=b.origin.x+labelW+8.f;
    const CGFloat gridW=std::max<CGFloat>(80.f,b.size.width-labelW-8.f);
    const CGFloat cellW=(gridW-cellGap*15.f)/16.f;
    const CGFloat cellH=(b.size.height-rowGap*3.f)/4.f;
    if(cellW <= 2.f || cellH <= 2.f) return NO;
    for(NSInteger row=0; row<4; ++row){
        const CGFloat y=b.origin.y + (3-row) * (cellH + rowGap);
        for(NSInteger step=0; step<16; ++step){
            const CGFloat x=gridX + step * (cellW + cellGap);
            const NSRect cell=NSMakeRect(x,y,cellW,cellH);
            if(NSPointInRect(pt, cell)){
                if(outRow) *outRow=row;
                if(outStep) *outStep=step;
                return YES;
            }
        }
    }
    return NO;
}
-(void)mouseMoved:(NSEvent*)e{
    NSInteger row=-1, step=-1;
    [self _hitGridAtPoint:[self convertPoint:e.locationInWindow fromView:nil] row:&row step:&step];
    _hoverRow=row;
    _hoverStep=step;
    [self setNeedsDisplay:YES];
}
-(void)mouseExited:(NSEvent*)e{
    (void)e;
    _hoverRow=-1;
    _hoverStep=-1;
    [self setNeedsDisplay:YES];
}
-(void)mouseDown:(NSEvent*)e{
    if(!self.stepTapBlock) return;
    NSInteger row=-1, step=-1;
    if(![self _hitGridAtPoint:[self convertPoint:e.locationInWindow fromView:nil] row:&row step:&step]) return;
    self.stepTapBlock(row, step, e.modifierFlags);
}
- (void)updateNotes:(const uint8_t*)notes
         velocities:(const float*)velocities
             gates:(const float*)gates
       currentStep:(int)currentStep
            enabled:(BOOL)enabled
{
    memset(_notes,0,sizeof(_notes));
    memset(_velocities,0,sizeof(_velocities));
    memset(_gates,0,sizeof(_gates));
    if(notes) memcpy(_notes, notes, sizeof(_notes));
    if(velocities) memcpy(_velocities, velocities, sizeof(_velocities));
    if(gates) memcpy(_gates, gates, sizeof(_gates));
    _currentStep=currentStep;
    _enabled=enabled;
    [self setNeedsDisplay:YES];
}
-(void)drawRect:(NSRect)dirtyRect{(void)dirtyRect;
    const NSRect b=NSInsetRect(self.bounds,8.f,6.f);
    const CGFloat labelW=28.f;
    const CGFloat cellGap=7.f;
    const CGFloat rowGap=10.f;
    const CGFloat gridX=b.origin.x+labelW+8.f;
    const CGFloat gridW=std::max<CGFloat>(80.f,b.size.width-labelW-8.f);
    const CGFloat cellW=(gridW-cellGap*15.f)/16.f;
    const CGFloat cellH=(b.size.height-rowGap*3.f)/4.f;
    if(cellW <= 2.f || cellH <= 2.f) return;
    NSDictionary* rowAttr=@{NSForegroundColorAttributeName:[colLabel() colorWithAlphaComponent:.78f],NSFontAttributeName:monoBF(11.f)};
    for(NSInteger row=0; row<4; ++row){
        NSColor* rowColor=ArpSIDDrum808RowColor((NSUInteger)row);
        const CGFloat y=b.origin.y + (3-row) * (cellH + rowGap);
        [[ArpSIDDrum808RowLabel((NSUInteger)row) copy] drawAtPoint:NSMakePoint(b.origin.x,y+cellH*0.36f) withAttributes:rowAttr];
        for(NSInteger step=0; step<16; ++step){
            const CGFloat x=gridX + step * (cellW + cellGap);
            const NSRect cell=NSMakeRect(x,y,cellW,cellH);
            const BOOL isCurrent=(_enabled && step == _currentStep);
            const BOOL hovered=(row == _hoverRow && step == _hoverStep);
            const BOOL active=_gates[step] > 0.01f && ArpSIDDrum808RowMatchesMidiNote((NSUInteger)row, (int)_notes[step]);
            const float vel=ArpSIDUIClamp01(_velocities[step], active ? 0.84f : 0.0f);
            [[NSColor colorWithSRGBRed:0.18f green:0.20f blue:0.25f alpha:0.92f] setFill];
            [[NSBezierPath bezierPathWithRoundedRect:cell xRadius:5.f yRadius:5.f] fill];
            if(active){
                [[rowColor colorWithAlphaComponent:(0.18f + vel*0.34f)] setFill];
                [[NSBezierPath bezierPathWithRoundedRect:NSInsetRect(cell,1.0f,1.0f) xRadius:4.f yRadius:4.f] fill];
                const CGFloat laneW=std::max<CGFloat>(3.f,(cell.size.width-8.f)*std::clamp(_gates[step],0.f,1.f));
                [[rowColor colorWithAlphaComponent:.96f] setFill];
                [[NSBezierPath bezierPathWithRoundedRect:NSMakeRect(cell.origin.x+4.f,cell.origin.y+3.5f,laneW,3.f) xRadius:1.5f yRadius:1.5f] fill];
            }
            if(hovered || isCurrent){
                const CGFloat glow=isCurrent ? 0.34f : 0.18f;
                [[rowColor colorWithAlphaComponent:glow] setFill];
                [[NSBezierPath bezierPathWithRoundedRect:NSInsetRect(cell,-1.f,-1.f) xRadius:6.f yRadius:6.f] fill];
            }
            [[rowColor colorWithAlphaComponent:(active ? 0.92f : 0.32f)] setStroke];
            NSBezierPath* border=[NSBezierPath bezierPathWithRoundedRect:NSInsetRect(cell,.5f,.5f) xRadius:5.f yRadius:5.f];
            border.lineWidth=active ? 1.3f : 0.9f;
            [border stroke];
        }
    }
}
@end

// ─────────────────────────────────────────────────────────────────────────────
// MARK: - ArpSIDDrumBusMeterView (horizontal 808-style output strip)
// ─────────────────────────────────────────────────────────────────────────────
@interface ArpSIDDrumBusMeterView : NSView
- (void)setLeftLevel:(float)left rightLevel:(float)right drumLevel:(float)drum;
@end

@implementation ArpSIDDrumBusMeterView{
    float _leftLevel;
    float _rightLevel;
    float _drumLevel;
}
-(void)setLeftLevel:(float)left rightLevel:(float)right drumLevel:(float)drum{
    _leftLevel=ArpSIDUIClamp01(left);
    _rightLevel=ArpSIDUIClamp01(right);
    _drumLevel=ArpSIDUIClamp01(drum);
    [self setNeedsDisplay:YES];
}
-(void)drawRect:(NSRect)dirtyRect{(void)dirtyRect;
    const NSRect b=self.bounds;
    [[NSColor colorWithSRGBRed:0.06f green:0.07f blue:0.10f alpha:0.96f] setFill];
    [[NSBezierPath bezierPathWithRoundedRect:b xRadius:4.f yRadius:4.f] fill];
    const CGFloat level=std::clamp(std::max({_leftLevel,_rightLevel,_drumLevel}),0.f,1.f);
    const NSInteger segmentCount=28;
    const CGFloat pad=4.f;
    const CGFloat gap=2.f;
    const CGFloat segW=(b.size.width-pad*2-gap*(segmentCount-1))/segmentCount;
    const CGFloat segH=b.size.height-pad*2;
    const NSInteger lit=(NSInteger)lround(level * (float)segmentCount);
    for(NSInteger i=0;i<segmentCount;++i){
        const CGFloat x=b.origin.x+pad+i*(segW+gap);
        const NSRect seg=NSMakeRect(x,b.origin.y+pad,segW,segH);
        NSColor* c=(i<18)?c64LtGreen():((i<24)?c64Yellow():c64Red());
        const BOOL on=i<lit;
        [[(on ? [c colorWithAlphaComponent:.96f] : [c colorWithAlphaComponent:.14f]) copy] setFill];
        [[NSBezierPath bezierPathWithRoundedRect:seg xRadius:2.f yRadius:2.f] fill];
    }
    [[colBorder() colorWithAlphaComponent:.30f] setStroke];
    [[NSBezierPath bezierPathWithRoundedRect:NSInsetRect(b,.5f,.5f) xRadius:4.f yRadius:4.f] stroke];
}
@end

// ─────────────────────────────────────────────────────────────────────────────
// MARK: - ArpSIDTransportView (BPM + bar:beat + play indicator)
// ─────────────────────────────────────────────────────────────────────────────
@interface ArpSIDTransportView : NSView
-(void)setTempo:(double)bpm beat:(double)beat playing:(BOOL)playing;
@end
@implementation ArpSIDTransportView{double _bpm;double _beat;BOOL _playing;}
-(instancetype)initWithFrame:(NSRect)r{self=[super initWithFrame:r];_bpm=120;return self;}
-(void)setTempo:(double)bpm beat:(double)beat playing:(BOOL)playing{
    double nbpm=ArpSIDUIFiniteDouble(bpm,120.0);
    if(nbpm<1.0||nbpm>1000.0)nbpm=120.0;
    const double nbeat=std::max(0.0,ArpSIDUIFiniteDouble(beat,0.0));
    // Idle redraw fix: the readout is static for a fixed (bpm,beat,playing). The
    // playing pulse rings advance with the beat, which only moves while the host
    // transport runs — so skip the redraw when nothing changed and a stopped
    // transport holds completely still.
    if(nbpm==_bpm && nbeat==_beat && playing==_playing) return;
    _bpm=nbpm;_beat=nbeat;_playing=playing;
    [self setNeedsDisplay:YES];}
-(void)drawRect:(NSRect)dr3{(void)dr3;
    NSRect b=self.bounds;
    const CGFloat cx2=b.origin.x+14, cy2=b.origin.y+b.size.height*.5f;
    // Deep background
    [[NSColor colorWithSRGBRed:.022f green:.018f blue:.065f alpha:1] setFill];
    [[NSBezierPath bezierPathWithRoundedRect:b xRadius:3 yRadius:3] fill];
    // Play indicator — concentric pulse rings when playing
    NSColor*dotC=_playing?c64LtGreen():c64LtBlue();
    if(_playing){
        const float t=(float)fmod(CFAbsoluteTimeGetCurrent()*2.4,1.0);
        // outer pulse ring
        [[dotC colorWithAlphaComponent:(0.10f*(1.f-t))] setFill];
        [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(cx2-12-t*5,cy2-12-t*5,(24+t*10),(24+t*10))] fill];
        // mid halo
        [[dotC colorWithAlphaComponent:.22f] setFill];
        [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(cx2-10,cy2-10,20,20)] fill];
    }
    // Dark bevel ring around dot
    [[NSColor colorWithSRGBRed:0 green:0 blue:0 alpha:.5f] setFill];
    [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(cx2-7,cy2-7,14,14)] fill];
    // Main dot
    [dotC setFill];
    [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(cx2-6,cy2-6,12,12)] fill];
    // Specular
    [[NSColor colorWithSRGBRed:1 green:1 blue:1 alpha:(_playing?.55f:.20f)] setFill];
    [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(cx2-3,cy2+1,4,3)] fill];
    // BPM — large, glowing when playing
    NSColor*bpmC=_playing?[colTitle() blendedColorWithFraction:.15f ofColor:c64White()]:colTitle();
    NSDictionary*ba=@{NSForegroundColorAttributeName:bpmC,NSFontAttributeName:monoBF(18)};
    NSString*bs=[NSString stringWithFormat:@"%5.1f",_bpm];
    NSSize bsz=[bs sizeWithAttributes:ba];
    const CGFloat bpmX=b.origin.x+28;
    if(_playing){
        // BPM glow
        NSDictionary*bglow=@{NSForegroundColorAttributeName:[bpmC colorWithAlphaComponent:.25f],NSFontAttributeName:monoBF(18)};
        [bs drawAtPoint:NSMakePoint(bpmX-1,b.origin.y+(b.size.height-bsz.height)*.5f-1) withAttributes:bglow];
    }
    [bs drawAtPoint:NSMakePoint(bpmX,b.origin.y+(b.size.height-bsz.height)*.5f) withAttributes:ba];
    NSDictionary*la=@{NSForegroundColorAttributeName:[colLabel() colorWithAlphaComponent:.65f],NSFontAttributeName:monoF(8)};
    [@"BPM" drawAtPoint:NSMakePoint(bpmX,b.origin.y+3) withAttributes:la];
    // Beat progress bar — thin strip at top, showing beat within bar
    const double beatInBar=fmod(_beat,4.0);
    const CGFloat beatFrac=(CGFloat)(beatInBar/4.0);
    const CGFloat stripY=b.origin.y+b.size.height-3;
    [[dotC colorWithAlphaComponent:.18f] setFill];
    NSRectFill(NSMakeRect(b.origin.x+1,stripY,b.size.width-2,2));
    [[dotC colorWithAlphaComponent:.75f] setFill];
    NSRectFill(NSMakeRect(b.origin.x+1,stripY,(b.size.width-2)*beatFrac,2));
    // Bar:beat
    int bar2=(int)(_beat/4)+1; int bt2=(int)(beatInBar)+1;
    NSDictionary*bba=@{NSForegroundColorAttributeName:colValue(),NSFontAttributeName:monoBF(13)};
    NSString*bbs=[NSString stringWithFormat:@"%3d:%d",bar2,bt2];
    NSSize bbsz=[bbs sizeWithAttributes:bba];
    const CGFloat bbX=b.origin.x+b.size.width-bbsz.width-6;
    [bbs drawAtPoint:NSMakePoint(bbX,b.origin.y+(b.size.height-bbsz.height)*.5f) withAttributes:bba];
    NSDictionary*bbla=@{NSForegroundColorAttributeName:[colLabel() colorWithAlphaComponent:.65f],NSFontAttributeName:monoF(8)};
    [@"BAR:BEAT" drawAtPoint:NSMakePoint(bbX,b.origin.y+3) withAttributes:bbla];
    [[colBorder() colorWithAlphaComponent:.55f] setStroke];
    [[NSBezierPath bezierPathWithRoundedRect:NSInsetRect(b,.5f,.5f) xRadius:3 yRadius:3] stroke];}
@end

// ─────────────────────────────────────────────────────────────────────────────
// MARK: - ArpSIDVoiceView (3 voice cells with note name)
// ─────────────────────────────────────────────────────────────────────────────
@interface ArpSIDVoiceView : NSView
-(void)setVoiceCount:(int)n lastNote:(int)note;
-(void)setTokenCount:(int)count tokens:(const ArpSIDTokenTelemetry*)tokens activeVoices:(int)activeVoices lastNote:(int)note;
@end
@implementation ArpSIDVoiceView{
    int _vc;
    int _note;
    int _tokenCount;
    int _activeVoices;
    ArpSIDTokenTelemetry _tokens[8];
}
-(instancetype)initWithFrame:(NSRect)r{self=[super initWithFrame:r];_vc=0;_note=-1;return self;}
-(void)setVoiceCount:(int)n lastNote:(int)note{
    const int nvc=ArpSIDUIClampInt(n,0,8,0);
    const int nnote=ArpSIDUIClampInt(note,-1,127,-1);
    if(nvc==_vc && nnote==_note) return;
    _vc=nvc;
    _note=nnote;
    [self setNeedsDisplay:YES];}
-(void)setTokenCount:(int)count tokens:(const ArpSIDTokenTelemetry*)tokens activeVoices:(int)activeVoices lastNote:(int)note{
    const int nTokenCount=std::clamp(count,0,64);
    const int nActiveVoices=ArpSIDUIClampInt(activeVoices,0,8,0);
    const int nNote=ArpSIDUIClampInt(note,-1,127,-1);
    ArpSIDTokenTelemetry nTokens[8];
    memset(nTokens,0,sizeof(nTokens));
    if(tokens){
        const int copyCount=std::min(8,nTokenCount);
        memcpy(nTokens,tokens,(size_t)copyCount*sizeof(ArpSIDTokenTelemetry));
    }
    const BOOL changed = (nTokenCount!=_tokenCount) || (nActiveVoices!=_activeVoices) ||
                         (nNote!=_note) || (memcmp(nTokens,_tokens,sizeof(_tokens))!=0);
    _tokenCount=nTokenCount;
    _activeVoices=nActiveVoices;
    _note=nNote;
    memcpy(_tokens,nTokens,sizeof(_tokens));
    // Redraw on any change; also keep the per-token glow animating smoothly while
    // tokens are present (the cells pulse via wall-clock in drawRect). With no
    // tokens the panel is static, so an idle voice view holds still.
    if(changed || _tokenCount>0){ [self setNeedsDisplay:YES]; }
}
-(void)drawRect:(NSRect)dr6{(void)dr6;
    NSRect b=self.bounds;
    [[NSColor colorWithSRGBRed:.010f green:.015f blue:.040f alpha:1] setFill];
    [[NSBezierPath bezierPathWithRoundedRect:b xRadius:3 yRadius:3] fill];
    const float nowT=(float)CFAbsoluteTimeGetCurrent();
    NSDictionary*topAttr=@{NSForegroundColorAttributeName:[colLabel() colorWithAlphaComponent:.72f],NSFontAttributeName:monoF(7)};
    NSString*header=[NSString stringWithFormat:@"TOK %d  SID %d  NOTE %@", _tokenCount, _activeVoices, ArpSIDNoteNameString(_note)];
    [header drawAtPoint:NSMakePoint(b.origin.x+6,b.origin.y+b.size.height-10) withAttributes:topAttr];

    if(_tokenCount>0){
        const int cells=8;
        const int cols=(b.size.width>150.f)?4:std::max(1,std::min(cells,_tokenCount));
        const int rows=(cells+cols-1)/cols;
        const CGFloat pad=4.f;
        const CGFloat topPad=14.f;
        const CGFloat cellW=(b.size.width-pad*2-(cols-1)*2.f)/cols;
        const CGFloat cellH=(b.size.height-topPad-pad-(rows-1)*2.f)/rows;
        for(int i=0;i<cells;++i){
            const int row=i/cols, col=i%cols;
            const NSRect cell=NSMakeRect(b.origin.x+pad+col*(cellW+2.f),
                                         b.origin.y+pad+(rows-1-row)*(cellH+2.f),
                                         cellW,cellH);
            const BOOL active=i<std::min(8,_tokenCount)&&_tokens[i].token!=0;
            const BOOL sustained=active&&((_tokens[i].flags&0x01u)!=0u);
            const BOOL sostenuto=active&&((_tokens[i].flags&0x02u)!=0u);
            const BOOL focused=active&&((_tokens[i].flags&0x04u)!=0u);
            NSColor*base=focused?c64Yellow():(sustained?c64Orange():(sostenuto?c64LightRed():c64LtGreen()));
            [(active?[base colorWithAlphaComponent:.14f]:[c64DkGrey() colorWithAlphaComponent:.10f]) setFill];
            [[NSBezierPath bezierPathWithRoundedRect:cell xRadius:3 yRadius:3] fill];
            if(active){
                const float pulse=0.45f+0.55f*sinf(nowT*6.0f+i*0.7f);
                [[base colorWithAlphaComponent:(0.10f+0.12f*pulse)] setFill];
                [[NSBezierPath bezierPathWithRoundedRect:NSInsetRect(cell,-1,-1) xRadius:4 yRadius:4] fill];
                const CGFloat vx=cell.origin.x+3;
                const CGFloat vy=cell.origin.y+3;
                const CGFloat vh=(cell.size.height-10)*_tokens[i].velocity;
                [[base colorWithAlphaComponent:.70f] setFill];
                NSRectFill(NSMakeRect(vx,vy,3,vh));
                if(_tokens[i].polyPressure>0.02f){
                    [[c64Cyan() colorWithAlphaComponent:.65f] setFill];
                    NSRectFill(NSMakeRect(cell.origin.x+cell.size.width-6,vy,2,(cell.size.height-10)*_tokens[i].polyPressure));
                }
                NSDictionary*na=@{NSForegroundColorAttributeName:base,NSFontAttributeName:monoBF(8)};
                NSString*nn=ArpSIDNoteNameString((int)_tokens[i].note);
                [nn drawAtPoint:NSMakePoint(cell.origin.x+8,cell.origin.y+cell.size.height-12) withAttributes:na];
                NSDictionary*ca=@{NSForegroundColorAttributeName:[base colorWithAlphaComponent:.78f],NSFontAttributeName:monoF(6.5f)};
                NSString*info=[NSString stringWithFormat:@"CH%d %@", (int)_tokens[i].channel+1, focused?@"FOCUS":(sustained?@"SUS":(sostenuto?@"SOST":@"LIVE"))];
                [info drawAtPoint:NSMakePoint(cell.origin.x+8,cell.origin.y+3) withAttributes:ca];
            }
            [[colBorder() colorWithAlphaComponent:(active?.28f:.18f)] setStroke];
            [[NSBezierPath bezierPathWithRoundedRect:NSInsetRect(cell,.5f,.5f) xRadius:3 yRadius:3] stroke];
        }
    } else {
        const CGFloat cw=b.size.width/3.f;
        static NSColor* kVoiceColors[3] = {nil,nil,nil};
        if(!kVoiceColors[0]){
            kVoiceColors[0]=c64Cyan(); kVoiceColors[1]=c64Yellow(); kVoiceColors[2]=c64LtGreen();
        }
        for(int i=0;i<3;++i){
            const BOOL active=(i<_vc);
            const NSRect cell=NSMakeRect(b.origin.x+i*cw+1,b.origin.y+1,cw-2,b.size.height-14);
            NSColor* vc=kVoiceColors[i];
            [(active?[vc colorWithAlphaComponent:.12f]:[c64DkGrey() colorWithAlphaComponent:.12f]) setFill];
            [[NSBezierPath bezierPathWithRoundedRect:cell xRadius:3 yRadius:3] fill];
            if(active){
                const float barH=cell.size.height*.28f;
                const float phase=fmodf(nowT*3.5f+i*1.1f,1.f);
                for(int b2=0;b2<4;++b2){
                    const float bH=barH*(0.3f+0.7f*fabsf(sinf((float)(b2)*0.9f+phase*6.28f)));
                    const CGFloat bx=cell.origin.x+3+b2*(cell.size.width-6)/4.f;
                    const CGFloat bw=(cell.size.width-6)/4.f-1;
                    [[vc colorWithAlphaComponent:.55f] setFill];
                    NSRectFill(NSMakeRect(bx,cell.origin.y+4,bw,bH));
                }
            }
            NSDictionary*a=@{NSForegroundColorAttributeName:vc,NSFontAttributeName:monoBF(9)};
            NSString*nn=(i==0&&active)?ArpSIDNoteNameString(_note):@"";
            if(nn.length) [nn drawAtPoint:NSMakePoint(cell.origin.x+8,cell.origin.y+3) withAttributes:a];
        }
    }
    [[colBorder() colorWithAlphaComponent:.55f] setStroke];
    [[NSBezierPath bezierPathWithRoundedRect:NSInsetRect(b,.5f,.5f) xRadius:3 yRadius:3] stroke];}
@end

// ─────────────────────────────────────────────────────────────────────────────
// MARK: - ArpSIDSidRegView (live hex readout of SID registers)
// ─────────────────────────────────────────────────────────────────────────────
@interface ArpSIDSidRegView : NSView
@property (nonatomic, copy) void(^writeCallback)(int reg, uint8_t val);
-(void)updateRegisters:(const uint8_t*)regs count:(int)n;
-(int)selectedRegisterIndex;
@end
@implementation ArpSIDSidRegView{
    uint8_t _r[30];int _n;uint8_t _prev[30];
    int _sel;          // selected cell index (-1=none)
    NSString*_hexEntry;// accumulates hex keypresses
    void (^_writeCB)(int reg, uint8_t val);
}
@synthesize writeCallback=_writeCB;
-(instancetype)initWithFrame:(NSRect)r{
    self=[super initWithFrame:r];
    memset(_r,0,sizeof _r);memset(_prev,0,sizeof _prev);_n=30;_sel=-1;_hexEntry=@"";
    return self;}
-(void)updateRegisters:(const uint8_t*)regs count:(int)n{
    bool changed=false;for(int i=0;i<n&&i<30;++i)if(regs[i]!=_r[i]){_prev[i]=_r[i];_r[i]=regs[i];changed=true;}
    if(changed)[self setNeedsDisplay:YES];}
-(BOOL)acceptsFirstResponder{return YES;}
-(int)selectedRegisterIndex{return _sel;}
-(void)drawRect:(NSRect)_r2{(void)_r2;
    NSRect b=self.bounds;[colOscBg() setFill];[[NSBezierPath bezierPathWithRect:b] fill];
    const int cols=7,rows=5;
    const CGFloat headerH=14.f,footerH=22.f;
    CGFloat cw=b.size.width/cols,ch=(b.size.height-headerH-footerH)/rows;
    // Header row
    NSDictionary*ha=@{NSForegroundColorAttributeName:[c64LtBlue() colorWithAlphaComponent:.9f],NSFontAttributeName:monoBF(7.5)};
    [@"$D4xx  VCO1──────────────  VCO2──────────────  VCO3──────────  FILT───  MISC" drawAtPoint:NSMakePoint(b.origin.x+2,b.origin.y+b.size.height-12) withAttributes:ha];
    for(int i=0;i<_n&&i<30;++i){
        int col=i%cols,row=i/cols;
        CGFloat cx=b.origin.x+col*cw,cy=b.origin.y+footerH+(rows-1-row)*ch;
        NSRect cell=NSMakeRect(cx+1,cy+1,cw-2,ch-2);
        BOOL changed=(_r[i]!=_prev[i]);
        // flash ring on change + per-group colour
        NSColor*cellBg=changed?[ArpSIDRegisterGroupColor(i) colorWithAlphaComponent:.28f]:[c64DkGrey() colorWithAlphaComponent:.12f];
        [cellBg setFill];
        [[NSBezierPath bezierPathWithRoundedRect:cell xRadius:2 yRadius:2] fill];
        if(changed){
            // Outer glow
            [[ArpSIDRegisterGroupColor(i) colorWithAlphaComponent:.20f] setFill];
            [[NSBezierPath bezierPathWithRoundedRect:NSInsetRect(cell,-1.5f,-1.5f) xRadius:3 yRadius:3] fill];
            // Bright border
            [[ArpSIDRegisterGroupColor(i) colorWithAlphaComponent:.75f] setStroke];
            NSBezierPath*hlt=[NSBezierPath bezierPathWithRoundedRect:cell xRadius:2 yRadius:2];
            hlt.lineWidth=1.2f;[hlt stroke];
        }
        NSColor*groupC = ArpSIDRegisterGroupColor(i);
        NSDictionary*na=@{NSForegroundColorAttributeName:[groupC colorWithAlphaComponent:.85f],NSFontAttributeName:monoF(7)};
        NSString*nm=ArpSIDSidRegisterShortNameForIndex(i);
        NSSize nsz=[nm sizeWithAttributes:na];
        [nm drawAtPoint:NSMakePoint(cx+(cw-nsz.width)*.5f,cy+ch-9) withAttributes:na];
        NSDictionary*va=@{NSForegroundColorAttributeName:changed?c64LtGreen():groupC,NSFontAttributeName:monoBF(8.5)};
        NSString*hx=[NSString stringWithFormat:@"%02X",_r[i]];
        NSSize hsz=[hx sizeWithAttributes:va];
        [hx drawAtPoint:NSMakePoint(cx+(cw-hsz.width)*.5f,cy+2) withAttributes:va];}
    // Selection highlight
    if(_sel>=0&&_sel<30){
        int col=_sel%cols,row=_sel/cols;
        CGFloat cx=b.origin.x+col*cw,cy=b.origin.y+footerH+(rows-1-row)*ch;
        [[ArpSIDRegisterGroupColor(_sel) colorWithAlphaComponent:.75f] setStroke];
        NSBezierPath*sel=[NSBezierPath bezierPathWithRoundedRect:NSMakeRect(cx+1,cy+1,cw-2,ch-2) xRadius:2 yRadius:2];
        sel.lineWidth=1.5f;[sel stroke];
    }
    // Bit-field decoder row (bottom strip)
    const NSRect footerRect=NSMakeRect(b.origin.x+1,b.origin.y+1,b.size.width-2,footerH-1);
    [[c64Black() colorWithAlphaComponent:.20f] setFill];
    [[NSBezierPath bezierPathWithRoundedRect:footerRect xRadius:2 yRadius:2] fill];
    NSString*status=@"CLICK = select / write  •  HEX = direct register value  •  ARROWS or SCROLL = nudge";
    NSString*bits=@"Filter, SYS and live probe registers decode in realtime here.";
    NSColor*statusColor=[colLabel() colorWithAlphaComponent:.80f];
    if(_sel>=0&&_sel<30){
        uint8_t v=_r[_sel];
        status=[NSString stringWithFormat:@"%@ %@  $%02X / %3d%@",
                ArpSIDSidRegisterAddressString(_sel),
                ArpSIDSidRegisterShortNameForIndex(_sel),
                v, v,
                _hexEntry.length ? [NSString stringWithFormat:@"  EDIT %@", _hexEntry] : @""];
        statusColor=ArpSIDRegisterGroupColor(_sel);
        // Control register decoding (offset 4, 11, 18)
        if(_sel==4||_sel==11||_sel==18){
            bits=[NSString stringWithFormat:@"TRI:%d SAW:%d PLS:%d NSE:%d TST:%d RNG:%d SYN:%d GT:%d",
                (v>>4)&1,(v>>5)&1,(v>>6)&1,(v>>7)&1,(v>>3)&1,(v>>2)&1,(v>>1)&1,v&1];
        } else if(_sel==23){// FLTV
            bits=[NSString stringWithFormat:@"RES:%d V1:%d V2:%d V3:%d EXT:%d",
                (v>>4)&0xF,(v>>0)&1,(v>>1)&1,(v>>2)&1,(v>>3)&1];
        } else if(_sel==24){// MVOL
            bits=[NSString stringWithFormat:@"LP:%d BP:%d HP:%d V3OFF:%d VOL:%d",
                (v>>4)&1,(v>>5)&1,(v>>6)&1,(v>>7)&1,v&0xF];
        } else if(_sel==25 || _sel==26){
            bits=[NSString stringWithFormat:@"%@ live paddle input = %02X", _sel==25 ? @"POTX" : @"POTY", v];
        } else if(_sel==27){
            bits=[NSString stringWithFormat:@"OSC3 live probe = %02X  (%@)", v, ArpSIDVoiceStateSummary(_r[18])];
        } else if(_sel==28){
            bits=[NSString stringWithFormat:@"ENV3 live probe = %02X  (%@)", v, ArpSIDADSRString(_r[19], _r[20])];
        } else if(_sel==29){
            bits=[NSString stringWithFormat:@"SYS %02X  %@", v, ArpSIDSidSystemBitsString(v)];
        } else {
            bits=[NSString stringWithFormat:@"$%02X = %3d = %%%d%d%d%d%d%d%d%d",
                v,v,(v>>7)&1,(v>>6)&1,(v>>5)&1,(v>>4)&1,(v>>3)&1,(v>>2)&1,(v>>1)&1,v&1];
        }
    }
    NSDictionary*sa=@{NSForegroundColorAttributeName:[statusColor colorWithAlphaComponent:.92f],NSFontAttributeName:monoBF(7.0f)};
    NSDictionary*ba=@{NSForegroundColorAttributeName:(_sel>=0&&_sel<30)?ArpSIDRegisterGroupColor(_sel):[colLabel() colorWithAlphaComponent:.70f],NSFontAttributeName:monoF(7.0f)};
    [status drawAtPoint:NSMakePoint(b.origin.x+4,b.origin.y+11) withAttributes:sa];
    [bits drawAtPoint:NSMakePoint(b.origin.x+4,b.origin.y+2) withAttributes:ba];
    [[colBorder() colorWithAlphaComponent:.5f] setStroke];
    [[NSBezierPath bezierPathWithRect:NSInsetRect(b,.5f,.5f)] stroke];}

// ── Hit testing ──────────────────────────────────────────────────────────────
-(int)_regIndexAtPoint:(NSPoint)pt{
    NSRect b=self.bounds;const int cols=7;
    const CGFloat headerH=14.f,footerH=22.f;
    const CGFloat gridTop=b.size.height-headerH;
    CGFloat cw=b.size.width/cols,ch=(b.size.height-headerH-footerH)/5;
    if(pt.y>gridTop || pt.y<footerH)return -1;
    int col=(int)(pt.x/cw),row=(int)((gridTop-pt.y)/ch);
    if(col<0||col>=cols||row<0||row>=5)return -1;
    int idx=row*cols+col;
    return(idx<30)?idx:-1;}

-(void)mouseDown:(NSEvent*)e{
    NSPoint pt=[self convertPoint:e.locationInWindow fromView:nil];
    int idx=[self _regIndexAtPoint:pt];
    if(idx != _sel) _hexEntry = @"";
    _sel=idx;[self setNeedsDisplay:YES];
    if(idx>=0)[self becomeFirstResponder];}

-(void)scrollWheel:(NSEvent*)e{
    if(_sel<0||!_writeCB)return;
    int delta=(int)e.deltaY;
    int newVal=std::clamp((int)_r[_sel]+delta,0,255);
    _writeCB(_sel,(uint8_t)newVal);}

-(void)keyDown:(NSEvent*)e{
    if(_sel<0)return;
    NSString*chars=(e.charactersIgnoringModifiers != nil) ? e.charactersIgnoringModifiers : @"";
    if(chars.length==0)return;
    unichar c=[chars characterAtIndex:0];
    if(c==0x1B){
        _hexEntry=@"";
        [self setNeedsDisplay:YES];
        return;
    }
    if(c==NSUpArrowFunctionKey||c==NSDownArrowFunctionKey){
        if(!_writeCB)return;
        int delta=(c==NSUpArrowFunctionKey)?1:-1;
        int newVal=std::clamp((int)_r[_sel]+delta,0,255);
        _writeCB(_sel,(uint8_t)newVal);
        _hexEntry=@"";
    } else if(c==NSLeftArrowFunctionKey){
        _sel=std::max(0,_sel-1);_hexEntry=@"";[self setNeedsDisplay:YES];
    } else if(c==NSRightArrowFunctionKey){
        _sel=std::min(29,_sel+1);_hexEntry=@"";[self setNeedsDisplay:YES];
    } else if(c==NSTabCharacter||c=='\t'){
        _sel=(_sel+1)%30;_hexEntry=@"";[self setNeedsDisplay:YES];
    } else {
        NSCharacterSet*hcs=[NSCharacterSet characterSetWithCharactersInString:@"0123456789ABCDEFabcdef"];
        if([chars rangeOfCharacterFromSet:[hcs invertedSet]].location!=NSNotFound){
            _hexEntry=@"";
            [self setNeedsDisplay:YES];
            NSBeep();
            return;
        }
        NSString*next=[[_hexEntry stringByAppendingString:[chars uppercaseString]]
                       stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceCharacterSet]];
        if(next.length==0){
            _hexEntry=@"";
            [self setNeedsDisplay:YES];
            return;
        }
        if(next.length>2){
            _hexEntry=@"";
            [self setNeedsDisplay:YES];
            NSBeep();
            return;
        }
        unsigned value=0;
        NSScanner* scanner=[NSScanner scannerWithString:next];
        if(![scanner scanHexInt:&value] || !scanner.isAtEnd || value>0xFFu){
            _hexEntry=@"";
            [self setNeedsDisplay:YES];
            NSBeep();
            return;
        }
        _hexEntry=next;
        if(_hexEntry.length==2){
            if(_writeCB)_writeCB(_sel,(uint8_t)value);
            _hexEntry=@"";
        }
        [self setNeedsDisplay:YES];
    }
}
@end

// ─────────────────────────────────────────────────────────────────────────────
// MARK: - ArpSIDSidCoreTimelineView_v547
// Custom NSView that renders the v545 SidCorePanelModel data:
// * Top half: scrolling register-write timeline (last N events)
// * Bottom half: per-voice live snapshot (freq/PW/waveform/gate)
// Drains the model's ring on every redraw; the redraw is driven by the
// host's CVDisplayLink (existing infrastructure that already publishes a
// 60 Hz tick to refresh other scopes).
// ─────────────────────────────────────────────────────────────────────────────
@interface ArpSIDSidCoreTimelineView_v547 : NSView
- (instancetype)initWithFrame:(NSRect)frame
                        model:(ArpSID::GUI::SidCorePanelModel*)model;
- (void)refresh;
@end

@implementation ArpSIDSidCoreTimelineView_v547 {
    ArpSID::GUI::SidCorePanelModel* _model;
    std::array<ArpSID::GUI::SidCoreRegisterWriteEvent, 64> _displayRing;
    std::size_t _displayCount;
    ArpSID::GUI::SidCoreLiveSnapshot _liveSnap;
}

- (instancetype)initWithFrame:(NSRect)frame
                        model:(ArpSID::GUI::SidCorePanelModel*)model
{
    self = [super initWithFrame:frame];
    if (self) {
        _model = model;
        _displayCount = 0;
        _liveSnap = {};
        self.wantsLayer = YES;
        self.layer.backgroundColor = [c64Black() colorWithAlphaComponent:0.85f].CGColor;
    }
    return self;
}

- (void)refresh {
    if (!_model) { [self setNeedsDisplay:YES]; return; }
    // Drain up to kCapacity events from the model into our local display
    // ring. Each call accumulates into the tail and trims the head if
    // we'd exceed kDisplayCapacity. Audit-correct: GUI-side ring, no
    // shared state with the audio thread beyond the atomic-snapshot read.
    constexpr std::size_t kDisplayCapacity = 64;
    std::array<ArpSID::GUI::SidCoreRegisterWriteEvent, 32> chunk{};
    bool overflowed = false;
    const std::size_t drained = _model->drainRegisterWrites(chunk.data(), chunk.size(), &overflowed);
    if (drained > 0) {
        // Shift existing entries down to make room for new ones.
        if (_displayCount + drained > kDisplayCapacity) {
            const std::size_t excess = (_displayCount + drained) - kDisplayCapacity;
            for (std::size_t i = 0; i + excess < _displayCount; ++i) {
                _displayRing[i] = _displayRing[i + excess];
            }
            _displayCount -= excess;
        }
        for (std::size_t i = 0; i < drained; ++i) {
            _displayRing[_displayCount + i] = chunk[i];
        }
        _displayCount += drained;
        if (_displayCount > kDisplayCapacity) _displayCount = kDisplayCapacity;
    }
    _model->peekLiveSnapshot(_liveSnap);
    [self setNeedsDisplay:YES];
}

- (void)drawRect:(NSRect)dirtyRect {
    (void)dirtyRect;
    const NSRect b = self.bounds;
    const CGFloat W = b.size.width;
    const CGFloat H = b.size.height;
    if (W < 80.0f || H < 80.0f) return;

    // ── Background grid ────────────────────────────────────────────────
    [[c64Black() colorWithAlphaComponent:0.92f] setFill];
    NSRectFill(b);
    [[c64Cyan() colorWithAlphaComponent:0.08f] setStroke];
    NSBezierPath* grid = [NSBezierPath bezierPath];
    grid.lineWidth = 0.5f;
    for (CGFloat x = 0; x < W; x += 32.0f) {
        [grid moveToPoint:NSMakePoint(x, 0)];
        [grid lineToPoint:NSMakePoint(x, H)];
    }
    for (CGFloat y = 0; y < H; y += 32.0f) {
        [grid moveToPoint:NSMakePoint(0, y)];
        [grid lineToPoint:NSMakePoint(W, y)];
    }
    [grid stroke];

    // Layout: top 60% = register-write timeline, bottom 40% = voice snapshot.
    const CGFloat timelineH = std::max<CGFloat>(80.0f, H * 0.60f);
    const CGFloat snapH = H - timelineH;
    const CGFloat timelineY = snapH;

    // ── Register-write timeline ────────────────────────────────────────
    // Headline label.
    NSDictionary* hdrAttrs = @{
        NSFontAttributeName: monoBF(11.0f),
        NSForegroundColorAttributeName: colTitle()
    };
    [@"REGISTER WRITE TIMELINE  (most recent → bottom)"
        drawAtPoint:NSMakePoint(8.0f, timelineY + timelineH - 16.0f)
     withAttributes:hdrAttrs];

    // Each event = one horizontal row. Most-recent at the bottom.
    if (_displayCount > 0) {
        const CGFloat rowH = std::max<CGFloat>(10.0f,
            (timelineH - 24.0f) / static_cast<CGFloat>(_displayCount));
        for (std::size_t i = 0; i < _displayCount; ++i) {
            const auto& ev = _displayRing[i];
            const CGFloat rowY = timelineY + timelineH - 22.0f - (i + 1) * rowH;
            // Voice color
            NSColor* col = c64LtGreen();
            if (ev.voiceHint == 0) col = c64Cyan();
            else if (ev.voiceHint == 1) col = c64Yellow();
            else if (ev.voiceHint == 2) col = c64LtGreen();
            const float alpha = 0.30f + 0.55f *
                (static_cast<float>(i) / static_cast<float>(_displayCount));
            [[col colorWithAlphaComponent:alpha] setFill];
            NSRectFill(NSMakeRect(8.0f, rowY, W - 16.0f, rowH - 1.0f));

            // Format: "[cycle] $D4xx = 0xVV (flags)"
            char rowText[128];
            std::snprintf(rowText, sizeof(rowText),
                "[%llu] $D4%02X = 0x%02X  v%d  flg=0x%02X",
                static_cast<unsigned long long>(ev.sidCycleStamp),
                static_cast<unsigned>(ev.registerIndex & 0xFF),
                static_cast<unsigned>(ev.value),
                static_cast<int>(ev.voiceHint),
                static_cast<unsigned>(ev.flags));
            NSDictionary* attrs = @{
                NSFontAttributeName: monoBF(9.0f),
                NSForegroundColorAttributeName: c64Black()
            };
            [[NSString stringWithUTF8String:rowText]
                drawAtPoint:NSMakePoint(14.0f, rowY + 1.0f) withAttributes:attrs];
        }
    } else {
        NSDictionary* dimAttrs = @{
            NSFontAttributeName: monoBF(10.0f),
            NSForegroundColorAttributeName: [colLabel() colorWithAlphaComponent:0.40f]
        };
        [@"(no register writes drained yet — kernel feed wire-up pending)"
            drawAtPoint:NSMakePoint(14.0f, timelineY + timelineH / 2.0f)
         withAttributes:dimAttrs];
    }

    // ── Live snapshot (per-voice) ──────────────────────────────────────
    [@"LIVE VOICE SNAPSHOT  (freq / pw / waveform / gate)"
        drawAtPoint:NSMakePoint(8.0f, snapH - 16.0f)
     withAttributes:hdrAttrs];

    const CGFloat voiceColW = (W - 16.0f) / 3.0f;
    for (int vi = 0; vi < 3; ++vi) {
        const CGFloat vx = 8.0f + vi * voiceColW;
        char buf[128];
        std::snprintf(buf, sizeof(buf),
            "V%d  freq=$%04X\npw=$%04X\nwave=$%02X  AD=$%02X\nSR=$%02X",
            vi + 1,
            static_cast<unsigned>(_liveSnap.voiceFrequency[vi]),
            static_cast<unsigned>(_liveSnap.voicePulseWidth[vi]),
            static_cast<unsigned>(_liveSnap.voiceWaveform[vi]),
            static_cast<unsigned>(_liveSnap.voiceAD[vi]),
            static_cast<unsigned>(_liveSnap.voiceSR[vi]));
        NSColor* voiceColor = (vi == 0) ? c64Cyan() : (vi == 1) ? c64Yellow() : c64LtGreen();
        NSDictionary* voiceAttrs = @{
            NSFontAttributeName: monoBF(10.0f),
            NSForegroundColorAttributeName: voiceColor
        };
        // Multi-line draw: split on \n.
        NSString* full = [NSString stringWithUTF8String:buf];
        NSArray<NSString*>* lines = [full componentsSeparatedByString:@"\n"];
        for (NSUInteger li = 0; li < lines.count; ++li) {
            [lines[li] drawAtPoint:NSMakePoint(vx, snapH - 36.0f - li * 14.0f)
                    withAttributes:voiceAttrs];
        }
    }

    // ── Filter row ─────────────────────────────────────────────────────
    char filterBuf[160];
    std::snprintf(filterBuf, sizeof(filterBuf),
        "FILTER  cutoff=$%04X  resRoute=$%02X  modeVol=$%02X",
        static_cast<unsigned>(_liveSnap.filterCutoff),
        static_cast<unsigned>(_liveSnap.filterResRoute),
        static_cast<unsigned>(_liveSnap.filterModeVolume));
    NSDictionary* filterAttrs = @{
        NSFontAttributeName: monoBF(10.0f),
        NSForegroundColorAttributeName: [colTitle() colorWithAlphaComponent:0.90f]
    };
    [[NSString stringWithUTF8String:filterBuf]
        drawAtPoint:NSMakePoint(8.0f, 4.0f) withAttributes:filterAttrs];
}

@end


// ─────────────────────────────────────────────────────────────────────────────
// MARK: - ArpSIDPanel (titled section box)
// ─────────────────────────────────────────────────────────────────────────────
@interface ArpSIDPanel:NSView-(instancetype)init:(NSRect)r t:(NSString*)t;@end
@implementation ArpSIDPanel{NSString*_t;}
-(instancetype)init:(NSRect)r t:(NSString*)t{self=[super initWithFrame:r];if(self)_t=[t copy];return self;}
-(void)drawRect:(NSRect)dr5{(void)dr5;
    NSRect b=self.bounds;
    const CGFloat W=b.size.width, H=b.size.height, ox=b.origin.x, oy=b.origin.y;
    NSBezierPath*panelPath=[NSBezierPath bezierPathWithRoundedRect:NSInsetRect(b,1,1) xRadius:4 yRadius:4];
    NSGradient*panelShell=[[NSGradient alloc] initWithColorsAndLocations:
                           ArpSIDRGB(0.11,0.12,0.20,0.98), 0.0,
                           ArpSIDRGB(0.17,0.18,0.27,0.98), 0.42,
                           ArpSIDRGB(0.08,0.09,0.15,0.98), 1.0,
                           nil];
    [panelShell drawInBezierPath:panelPath angle:90.0f];
    [[colPanelDeep() colorWithAlphaComponent:.68f] setFill];
    [panelPath fill];
    [[c64LtBlue() colorWithAlphaComponent:.035f] setFill];
    NSRectFill(NSMakeRect(ox+2, oy+H*0.46f, W-4, std::max<CGFloat>(10.0f, H*0.18f)));
    [[c64Black() colorWithAlphaComponent:.16f] setFill];
    NSRectFill(NSMakeRect(ox+2, oy+2, W-4, std::max<CGFloat>(6.0f, H*0.12f)));
    // Inner shadow — top and left edges darker
    [[colInnerShadow() colorWithAlphaComponent:.35f] setStroke];
    NSBezierPath*inSh=[NSBezierPath bezierPath]; inSh.lineWidth=1.5f;
    [inSh moveToPoint:NSMakePoint(ox+4,oy+H-2)];[inSh lineToPoint:NSMakePoint(ox+W-4,oy+H-2)];
    [inSh moveToPoint:NSMakePoint(ox+2,oy+H-4)];[inSh lineToPoint:NSMakePoint(ox+2,oy+4)];
    [inSh stroke];
    // Outer border with top highlight bevel
    [[colBorder() colorWithAlphaComponent:.52f] setStroke];
    NSBezierPath*bo=[NSBezierPath bezierPathWithRoundedRect:NSInsetRect(b,.5f,.5f) xRadius:4 yRadius:4];
    bo.lineWidth=1;[bo stroke];
    // Corner ornaments — small diamond/cross at each corner
    auto drawCorner=[&](CGFloat cx,CGFloat cy){
        [[colBorder() colorWithAlphaComponent:.70f] setFill];
        NSBezierPath*d=[NSBezierPath bezierPath];
        [d moveToPoint:NSMakePoint(cx,cy+3.5f)];[d lineToPoint:NSMakePoint(cx+3.5f,cy)];
        [d lineToPoint:NSMakePoint(cx,cy-3.5f)];[d lineToPoint:NSMakePoint(cx-3.5f,cy)];
        [d closePath];[d fill];
    };
    drawCorner(ox+7, oy+H-7);
    drawCorner(ox+W-7, oy+H-7);
    drawCorner(ox+7, oy+7);
    drawCorner(ox+W-7, oy+7);
    // Title bar background
    NSRect tb=NSMakeRect(ox,oy+H-18,W,18);
    [[colBorder() colorWithAlphaComponent:.22f] setFill];
    NSBezierPath*tp=[NSBezierPath bezierPath];
    [tp moveToPoint:NSMakePoint(NSMinX(tb)+4,NSMinY(tb))];
    [tp lineToPoint:NSMakePoint(NSMaxX(tb)-4,NSMinY(tb))];
    [tp appendBezierPathWithArcWithCenter:NSMakePoint(NSMaxX(tb)-4,NSMaxY(tb)-4) radius:4 startAngle:0 endAngle:90 clockwise:NO];
    [tp appendBezierPathWithArcWithCenter:NSMakePoint(NSMinX(tb)+4,NSMaxY(tb)-4) radius:4 startAngle:90 endAngle:180 clockwise:NO];
    [tp closePath];[tp fill];
    [[c64LtBlue() colorWithAlphaComponent:.09f] setFill];
    NSRectFill(NSMakeRect(NSMinX(tb)+6, NSMaxY(tb)-6, std::max<CGFloat>(8.0f, W-12), 2.0f));
    [[c64Yellow() colorWithAlphaComponent:.05f] setFill];
    NSRectFill(NSMakeRect(NSMinX(tb)+10, NSMinY(tb)+2, std::max<CGFloat>(8.0f, W-20), 1.0f));
    // Title bar bottom separator line
    [[colBorder() colorWithAlphaComponent:.45f] setStroke];
    NSBezierPath*sep=[NSBezierPath bezierPath]; sep.lineWidth=.7f;
    [sep moveToPoint:NSMakePoint(ox+12,oy+H-18)];[sep lineToPoint:NSMakePoint(ox+W-12,oy+H-18)];
    [sep stroke];
    // Title text with subtle glow
    NSDictionary*a=@{NSForegroundColorAttributeName:colTitle(),NSFontAttributeName:monoBF(9)};
    NSSize ts=[_t sizeWithAttributes:a];
    const CGFloat tx=(W-ts.width)*.5f;
    // Glow pass
    NSDictionary*ag=@{NSForegroundColorAttributeName:[colTitle() colorWithAlphaComponent:.22f],NSFontAttributeName:monoBF(9)};
    [_t drawAtPoint:NSMakePoint(tx-1,H-15) withAttributes:ag];
    [_t drawAtPoint:NSMakePoint(tx+1,H-15) withAttributes:ag];
    // Main title
    [_t drawAtPoint:NSMakePoint(tx,H-14) withAttributes:a];}

@end

// ─────────────────────────────────────────────────────────────────────────────
// MARK: - ArpSIDDigiSamplePreviewView_v262 (GPU-composited $D418 preview)
// ─────────────────────────────────────────────────────────────────────────────
// active-slot sample preview. The expensive operation is bounded path
// generation on the GUI thread when the slot changes; the steady-state display is
// Core Animation / Metal-GPU composited through layer-backed CAShapeLayer objects.
// Nothing here runs on the audio thread and it never touches the DSP render path.
@interface ArpSIDDigiSamplePreviewView_v262 : NSView
@property(nonatomic, readonly) BOOL gpuAccelerated;
-(void)updateWithClip:(const ArpSID::GUI::DigiUserSampleClip&)clip
                 slot:(std::uint8_t)slot
          pendingMono:(const std::vector<float>&)pendingMono
    pendingSampleRate:(double)pendingSampleRate
              pending:(BOOL)pending
               status:(NSString*)status;
@end

@implementation ArpSIDDigiSamplePreviewView_v262 {
    CAGradientLayer* _backLayer;
    CAShapeLayer* _gridLayer;
    CAShapeLayer* _zeroLineLayer;
    CAShapeLayer* _fillLayer;
    CAShapeLayer* _waveLayer;
    CAShapeLayer* _glowLayer;
    CALayer* _levelBackLayer;
    CALayer* _levelLayer;
    CALayer* _statusPillLayer;
    CALayer* _cursorLayer;
    CALayer* _meterAvgLayer;
    CALayer* _dcBiasLayer;       // DC/bias indicator, catches bad $D418 centering visually.
    CALayer* _headroomLayer;     // remaining headroom bar, makes clipping/normalization obvious.
    CAShapeLayer* _rulerLayer;
    CAShapeLayer* _sparkLayer;
    CATextLayer* _textLayer;
    CATextLayer* _subTextLayer;
    CATextLayer* _rightTextLayer;
    BOOL _gpuAccelerated;
    std::uint64_t _lastPreviewFingerprint_v264;
    NSSize _lastPreviewSize_v264;
}
@synthesize gpuAccelerated = _gpuAccelerated;

-(instancetype)initWithFrame:(NSRect)frame {
    self = [super initWithFrame:frame];
    if (!self) return nil;
    self.wantsLayer = YES;
    _gpuAccelerated = (MTLCreateSystemDefaultDevice() != nil);
    _lastPreviewFingerprint_v264 = 0;
    _lastPreviewSize_v264 = NSZeroSize;

    _backLayer = [CAGradientLayer layer];
    _backLayer.startPoint = CGPointMake(0.0, 0.0);
    _backLayer.endPoint = CGPointMake(1.0, 1.0);
    _backLayer.colors = @[
        (id)[c64Black() colorWithAlphaComponent:0.76f].CGColor,
        (id)[c64Blue() colorWithAlphaComponent:0.34f].CGColor,
        (id)[c64Black() colorWithAlphaComponent:0.62f].CGColor
    ];
    _backLayer.cornerRadius = 3.0;
    _backLayer.borderWidth = 1.0;
    _backLayer.borderColor = [colBorder() colorWithAlphaComponent:0.58f].CGColor;
    [self.layer addSublayer:_backLayer];

    _gridLayer = [CAShapeLayer layer];
    _gridLayer.strokeColor = [c64LtBlue() colorWithAlphaComponent:0.13f].CGColor;
    _gridLayer.fillColor = NSColor.clearColor.CGColor;
    _gridLayer.lineWidth = 0.55f;
    [self.layer addSublayer:_gridLayer];

    _zeroLineLayer = [CAShapeLayer layer];
    _zeroLineLayer.strokeColor = [c64White() colorWithAlphaComponent:0.18f].CGColor;
    _zeroLineLayer.fillColor = NSColor.clearColor.CGColor;
    _zeroLineLayer.lineWidth = 0.75f;
    [self.layer addSublayer:_zeroLineLayer];

    _fillLayer = [CAShapeLayer layer];
    _fillLayer.fillColor = [c64LtGreen() colorWithAlphaComponent:0.10f].CGColor;
    [self.layer addSublayer:_fillLayer];

    _glowLayer = [CAShapeLayer layer];
    _glowLayer.fillColor = NSColor.clearColor.CGColor;
    _glowLayer.strokeColor = [c64LtGreen() colorWithAlphaComponent:0.23f].CGColor;
    _glowLayer.lineWidth = 4.0f;
    _glowLayer.lineJoin = kCALineJoinRound;
    _glowLayer.lineCap = kCALineCapRound;
    [self.layer addSublayer:_glowLayer];

    _waveLayer = [CAShapeLayer layer];
    _waveLayer.fillColor = NSColor.clearColor.CGColor;
    _waveLayer.strokeColor = c64LtGreen().CGColor;
    _waveLayer.lineWidth = 1.15f;
    _waveLayer.lineJoin = kCALineJoinRound;
    _waveLayer.lineCap = kCALineCapRound;
    [self.layer addSublayer:_waveLayer];

    _levelBackLayer = [CALayer layer];
    _levelBackLayer.backgroundColor = [c64Black() colorWithAlphaComponent:0.42f].CGColor;
    _levelBackLayer.cornerRadius = 1.5f;
    [self.layer addSublayer:_levelBackLayer];

    _levelLayer = [CALayer layer];
    _levelLayer.backgroundColor = c64LtGreen().CGColor;
    _levelLayer.cornerRadius = 1.5f;
    [self.layer addSublayer:_levelLayer];

    _statusPillLayer = [CALayer layer];
    _statusPillLayer.backgroundColor = [c64LtGreen() colorWithAlphaComponent:0.20f].CGColor;
    _statusPillLayer.borderColor = [c64LtGreen() colorWithAlphaComponent:0.55f].CGColor;
