    _glowLayer.frame = b;
    _waveLayer.frame = b;
    _levelBackLayer.frame = CGRectMake(5.0, 3.0, std::max<CGFloat>(1.0, b.size.width - 10.0), 3.0);
    _meterAvgLayer.frame = CGRectMake(5.0, 7.0, 1.0, 2.0);
    _headroomLayer.frame = CGRectMake(5.0, 10.0, std::max<CGFloat>(1.0, b.size.width - 10.0), 1.0);
    _dcBiasLayer.frame = CGRectMake(std::max<CGFloat>(5.0, b.size.width * 0.5 - 0.5), 10.0, 1.0, 5.0);
    _cursorLayer.frame = CGRectMake(5.0, 15.0, 1.5, std::max<CGFloat>(4.0, b.size.height - 24.0));
    _rulerLayer.frame = b;
    _sparkLayer.frame = b;
    _textLayer.frame = CGRectMake(7.0, std::max<CGFloat>(2.0, b.size.height - 13.0), std::max<CGFloat>(1.0, b.size.width - 54.0), 10.0);
    _subTextLayer.frame = CGRectMake(7.0, 7.0, std::max<CGFloat>(1.0, b.size.width - 14.0), 8.0);
    _rightTextLayer.frame = CGRectMake(std::max<CGFloat>(5.0, b.size.width - 98.0), 7.0, 92.0, 8.0);
    _statusPillLayer.frame = CGRectMake(std::max<CGFloat>(5.0, b.size.width - 40.0), std::max<CGFloat>(3.0, b.size.height - 14.0), 34.0, 10.0);
    [self _rebuildStaticGrid_v264];
    [CATransaction commit];
}

-(void)_rebuildStaticGrid_v264 {
    const CGFloat w = std::max<CGFloat>(1.0, self.bounds.size.width);
    const CGFloat h = std::max<CGFloat>(1.0, self.bounds.size.height);
    const CGFloat topPad = 14.0;
    const CGFloat botPad = 8.0;
    const CGFloat drawH = std::max<CGFloat>(4.0, h - topPad - botPad);
    const CGFloat midY = botPad + drawH * 0.5;

    CGMutablePathRef grid = CGPathCreateMutable();
    for (int i = 1; i < 4; ++i) {
        const CGFloat y = botPad + drawH * ((CGFloat)i / 4.0f);
        CGPathMoveToPoint(grid, nullptr, 5.0, y);
        CGPathAddLineToPoint(grid, nullptr, w - 5.0, y);
    }
    for (int i = 1; i < 8; ++i) {
        const CGFloat x = 5.0 + (w - 10.0) * ((CGFloat)i / 8.0f);
        CGPathMoveToPoint(grid, nullptr, x, botPad);
        CGPathAddLineToPoint(grid, nullptr, x, botPad + drawH);
    }
    _gridLayer.path = grid;
    CGPathRelease(grid);

    CGMutablePathRef zero = CGPathCreateMutable();
    CGPathMoveToPoint(zero, nullptr, 5.0, midY);
    CGPathAddLineToPoint(zero, nullptr, w - 5.0, midY);
    _zeroLineLayer.path = zero;
    CGPathRelease(zero);

    CGMutablePathRef ruler = CGPathCreateMutable();
    for (int i = 0; i <= 4; ++i) {
        const CGFloat x = 5.0 + (w - 10.0) * ((CGFloat)i / 4.0f);
        CGPathMoveToPoint(ruler, nullptr, x, botPad + drawH + 1.0);
        CGPathAddLineToPoint(ruler, nullptr, x, botPad + drawH + ((i == 0 || i == 4) ? 5.0 : 3.0));
    }
    _rulerLayer.path = ruler;
    CGPathRelease(ruler);
}

-(void)updateWithClip:(const ArpSID::GUI::DigiUserSampleClip&)clip
                 slot:(std::uint8_t)slot
          pendingMono:(const std::vector<float>&)pendingMono
    pendingSampleRate:(double)pendingSampleRate
              pending:(BOOL)pending
               status:(NSString*)status {
    // polished GPU/layer HUD preview with avg/peak/headroom meters.
    // this view is a canonical $D418 4-bit visualizer, not a raw
    // PCM oscilloscope. Pending REC TAKE is snapped through digiFloatToD418Nibble
    // before drawing; committed clips are recovered through digiPcm8ToD418Nibble.
    // Both paths draw the same unsigned 0..15 SID volume-DAC ladder around the
    // practical silence midpoint 0x08. Host-rate duration is only metadata.
    // Rendering is GUI-thread CoreAnimation/Metal-composited only: no audio-thread
    // work, no DSP mutation, no sample-bank write. See
    // TECHNICAL_D418_CANONICAL_4BIT_NIBBLE_SPEC.md.
    const BOOL hasPendingTake_v264 = pending && !pendingMono.empty();
    const BOOL hasStoredClip_v264 = ArpSID::GUI::digiUserSampleClipIsWellFormed(clip) &&
                                    ArpSID::GUI::digiUserSampleClipIsPresent(clip);
    const BOOL present = hasPendingTake_v264 || hasStoredClip_v264;
    const uint32_t n = hasPendingTake_v264
        ? (uint32_t)std::min<std::size_t>(pendingMono.size(), (std::size_t)std::numeric_limits<uint32_t>::max())
        : (hasStoredClip_v264 ? clip.frameCount : 0u);
    const double rate = hasPendingTake_v264
        ? ((std::isfinite(pendingSampleRate) && pendingSampleRate > 1.0) ? pendingSampleRate : 48000.0)
        : (double)ArpSID::GUI::kDigiUserSampleCanonicalRateHz;
    const CGFloat w = std::max<CGFloat>(1.0, self.bounds.size.width);
    const CGFloat h = std::max<CGFloat>(1.0, self.bounds.size.height);
    const CGFloat topPad = 14.0;
    const CGFloat botPad = 8.0;
    const CGFloat drawH = std::max<CGFloat>(4.0, h - topPad - botPad);
    const CGFloat midY = botPad + drawH * 0.5;
    const uint32_t columns = (uint32_t)std::clamp<int>((int)std::floor(w - 10.0), 24, 640);

    std::uint64_t fp = 1469598103934665603ull;
    auto mixfp = [&](std::uint64_t v) { fp ^= v; fp *= 1099511628211ull; };
    mixfp(slot); mixfp((std::uint64_t)n); mixfp(hasPendingTake_v264 ? 0x54414B455F563237ull : 0x443431385F563237ull);
    mixfp((std::uint64_t)std::llround(rate)); mixfp((std::uint64_t)std::llround(w * 10.0)); mixfp((std::uint64_t)std::llround(h * 10.0));
    // status text participates in the preview fingerprint, so HUD labels
    // refresh even when the waveform data/size did not change.
    if (status.length > 0) {
        for (NSUInteger si = 0; si < status.length; ++si) mixfp((std::uint64_t)[status characterAtIndex:si]);
    }
    if (hasPendingTake_v264) {
        const uint32_t stride = std::max<uint32_t>(1u, n / 96u);
        for (uint32_t i = 0; i < n; i += stride) {
            float x = pendingMono[i];
            if (!std::isfinite(x)) x = 0.0f;
            const std::uint8_t q = ArpSID::GUI::digiFloatToD418Nibble(std::clamp(x, -1.0f, 1.0f)) & 0x0Fu;
            mixfp((std::uint64_t)q);
        }
    } else if (hasStoredClip_v264) {
        mixfp(clip.sourceHash); mixfp(clip.handle); mixfp(clip.flags);
        const uint32_t stride = std::max<uint32_t>(1u, n / 96u);
        for (uint32_t i = 0; i < n; i += stride) mixfp((std::uint64_t)(ArpSID::GUI::digiPcm8ToD418Nibble(clip.pcm[i]) & 0x0Fu));
    }

    if (fp == _lastPreviewFingerprint_v264 && NSEqualSizes(_lastPreviewSize_v264, self.bounds.size)) {
        return;
    }

    CGMutablePathRef wave = CGPathCreateMutable();
    CGMutablePathRef fill = CGPathCreateMutable();
    CGMutablePathRef sparks = CGPathCreateMutable();
    float peak_v264 = 0.0f;
    float avgAbs_v264 = 0.0f;
    float dcAvg_v266 = 0.0f;
    uint32_t dcCount_v266 = 0u;
    if (present && n > 0u) {
        for (uint32_t c = 0; c < columns; ++c) {
            const uint32_t a = (uint32_t)(((uint64_t)c * n) / columns);
            const uint32_t b = std::max<uint32_t>(a + 1u, (uint32_t)(((uint64_t)(c + 1u) * n) / columns));
            float lo =  1.0f;
            float hi = -1.0f;
            float accAbs = 0.0f;
            uint32_t accN = 0;
            for (uint32_t i = a; i < std::min<uint32_t>(b, n); ++i) {
                float v = 0.0f;
                if (hasPendingTake_v264) {
                    float src_v273 = pendingMono[i];
                    if (!std::isfinite(src_v273)) src_v273 = 0.0f;
                    // REC preview intentionally shows the post-quantization
                    // $D418 result. Do not draw raw host PCM here.
                    const float q = (float)(ArpSID::GUI::digiFloatToD418Nibble(std::clamp(src_v273, -1.0f, 1.0f)) & 0x0Fu);
                    v = std::clamp((q - 7.5f) / 7.5f, -1.0f, 1.0f);
                } else {
                    // Committed storage is displayed through the canonical helper;
                    // 0x08 is the practical unsigned 4-bit silence midpoint.
                    const float q = (float)(ArpSID::GUI::digiPcm8ToD418Nibble(clip.pcm[i]) & 0x0Fu);
                    v = std::clamp((q - 7.5f) / 7.5f, -1.0f, 1.0f);
                }
                lo = std::min(lo, v);
                hi = std::max(hi, v);
                const float av = std::abs(v);
                peak_v264 = std::max(peak_v264, av);
                accAbs += av;
                dcAvg_v266 += v;
                ++dcCount_v266;
                ++accN;
            }
            if (accN) avgAbs_v264 += accAbs / (float)accN;
            const CGFloat x = 5.0 + ((CGFloat)c / (CGFloat)std::max<uint32_t>(1u, columns - 1u)) * std::max<CGFloat>(1.0, w - 10.0);
            const CGFloat yLo = midY - (CGFloat)lo * drawH * 0.46;
            const CGFloat yHi = midY - (CGFloat)hi * drawH * 0.46;
            if ((hi - lo) > 1.38f && (c % 5u) == 0u) {
                CGPathAddEllipseInRect(sparks, nullptr, CGRectMake(x - 1.1, std::min(yLo, yHi) - 1.1, 2.2, 2.2));
            }
            if (c == 0) CGPathMoveToPoint(wave, nullptr, x, yLo); else CGPathAddLineToPoint(wave, nullptr, x, yLo);
            CGPathAddLineToPoint(wave, nullptr, x, yHi);
            if (c == 0) CGPathMoveToPoint(fill, nullptr, x, midY);
            CGPathAddLineToPoint(fill, nullptr, x, yHi);
        }
        avgAbs_v264 /= (float)std::max<uint32_t>(1u, columns);
        if (dcCount_v266 > 0u) dcAvg_v266 /= (float)dcCount_v266;
        CGPathAddLineToPoint(fill, nullptr, w - 5.0, midY);
        CGPathCloseSubpath(fill);
    }

    NSString* acc = _gpuAccelerated ? @"GPU" : @"LAYER";
    NSString* title = nil;
    NSString* sub = nil;
    NSColor* accent = hasPendingTake_v264 ? c64Yellow() : (present ? c64LtGreen() : c64Orange());
    if (hasPendingTake_v264) {
        title = [NSString stringWithFormat:@"S%u  TAKE→4BIT  %.2fs  pk %.0f%%  %@",
                 (unsigned)slot + 1u,
                 (double)n / rate,
                 (double)std::round(peak_v264 * 100.0f),
                 acc];
        sub = [NSString stringWithFormat:@"host %.0f Hz  %u frames  visualized as $D418 nibbles  avg %.0f%%  dc %+0.0f%%  KEEP",
               rate, (unsigned)n, (double)std::round(avgAbs_v264 * 100.0f),
               (double)std::round(dcAvg_v266 * 100.0f)];
    } else if (hasStoredClip_v264) {
        title = [NSString stringWithFormat:@"S%u  %@  %.2fs  pk %.0f%%  %@",
                 (unsigned)slot + 1u,
                 status.length ? status : @"$D418",
                 (double)n / (double)ArpSID::GUI::kDigiUserSampleCanonicalRateHz,
                 (double)std::round(peak_v264 * 100.0f),
                 acc];
        const BOOL nearMax_v266 = (n >= (uint32_t)ArpSID::GUI::kDigiUserSampleMaxFrames);
        sub = [NSString stringWithFormat:@"canonical 8 kHz $D418  %u nibbles%@  avg %.0f%%  dc %+0.0f%%",
               (unsigned)n, nearMax_v266 ? @" MAX" : @"",
               (double)std::round(avgAbs_v264 * 100.0f),
               (double)std::round(dcAvg_v266 * 100.0f)];
    } else {
        title = [NSString stringWithFormat:@"S%u  EMPTY  %@", (unsigned)slot + 1u, acc];
        sub = @"drop/import/record audio to fill this slot";
    }

    [CATransaction begin];
    [CATransaction setDisableActions:YES];
    _waveLayer.path = wave;
    _glowLayer.path = wave;
    _fillLayer.path = fill;
    _sparkLayer.path = sparks;
    _waveLayer.strokeColor = accent.CGColor;
    _glowLayer.strokeColor = [accent colorWithAlphaComponent:present ? 0.24f : 0.08f].CGColor;
    _fillLayer.fillColor = present ? [accent colorWithAlphaComponent:hasPendingTake_v264 ? 0.11f : 0.13f].CGColor : NSColor.clearColor.CGColor;
    _levelLayer.hidden = !present;
    _levelBackLayer.hidden = !present;
    _meterAvgLayer.hidden = !present;
    _headroomLayer.hidden = !present;
    _dcBiasLayer.hidden = !present;
    _cursorLayer.hidden = !present;
    _sparkLayer.hidden = !present;
    _levelLayer.backgroundColor = accent.CGColor;
    _meterAvgLayer.backgroundColor = [c64Cyan() colorWithAlphaComponent:0.54f].CGColor;
    _levelLayer.frame = CGRectMake(5.0, 3.0, std::max<CGFloat>(1.0, (w - 10.0) * (CGFloat)std::clamp(peak_v264, 0.0f, 1.0f)), 3.0);
    _meterAvgLayer.frame = CGRectMake(5.0, 7.0, std::max<CGFloat>(1.0, (w - 10.0) * (CGFloat)std::clamp(avgAbs_v264, 0.0f, 1.0f)), 2.0);
    const CGFloat headroomW_v266 = (w - 10.0) * (CGFloat)std::clamp(1.0f - peak_v264, 0.0f, 1.0f);
    _headroomLayer.frame = CGRectMake(w - 5.0 - std::max<CGFloat>(1.0, headroomW_v266), 10.0, std::max<CGFloat>(1.0, headroomW_v266), 1.0);
    _headroomLayer.backgroundColor = [(peak_v264 > 0.985f ? c64Red() : c64White()) colorWithAlphaComponent:(peak_v264 > 0.985f ? 0.62f : 0.18f)].CGColor;
    const CGFloat dcX_v266 = 5.0 + (w - 10.0) * (CGFloat)std::clamp((dcAvg_v266 * 0.5f) + 0.5f, 0.0f, 1.0f);
    _dcBiasLayer.frame = CGRectMake(dcX_v266 - 0.75, 10.0, 1.5, 5.0);
    _dcBiasLayer.backgroundColor = [(std::fabs(dcAvg_v266) > 0.20f ? c64Red() : c64Yellow()) colorWithAlphaComponent:0.58f].CGColor;
    const CGFloat cursorX = present ? (5.0 + (w - 10.0) * (CGFloat)std::fmod((double)(fp & 0xFFFFu) / 65535.0, 1.0)) : 5.0;
    _cursorLayer.frame = CGRectMake(cursorX, 15.0, 1.5, std::max<CGFloat>(4.0, h - 24.0));
    _statusPillLayer.backgroundColor = [accent colorWithAlphaComponent:0.18f].CGColor;
    _statusPillLayer.borderColor = [accent colorWithAlphaComponent:0.55f].CGColor;
    _textLayer.string = title;
    _textLayer.foregroundColor = [accent colorWithAlphaComponent:present ? 0.92f : 0.76f].CGColor;
    _subTextLayer.string = sub;
    _subTextLayer.foregroundColor = present ? [c64Cyan() colorWithAlphaComponent:0.76f].CGColor : [colLabel() colorWithAlphaComponent:0.62f].CGColor;
    NSString* rightTelemetry_v267 = present ? [NSString stringWithFormat:@"P%02.0f A%02.0f D%+03.0f",
                                      (double)std::round(peak_v264 * 99.0f),
                                      (double)std::round(avgAbs_v264 * 99.0f),
                                      (double)std::round(dcAvg_v266 * 99.0f)] : @"READY";
    _rightTextLayer.string = rightTelemetry_v267;
    _rightTextLayer.foregroundColor = present ? [c64Yellow() colorWithAlphaComponent:0.70f].CGColor : [colLabel() colorWithAlphaComponent:0.55f].CGColor;
    self.toolTip = [NSString stringWithFormat:@"DIGI sample preview: %@ — %@ — %@",
                    title ? title : @"slot",
                    sub ? sub : @"no source",
                    rightTelemetry_v267 ? rightTelemetry_v267 : @"READY"];
    self.accessibilityLabel = self.toolTip;
    [CATransaction commit];
    _lastPreviewFingerprint_v264 = fp;
    _lastPreviewSize_v264 = self.bounds.size;
    CGPathRelease(wave);
    CGPathRelease(fill);
    CGPathRelease(sparks);
}
@end

