@interface ArpSIDDigiDropView : NSView <NSDraggingDestination>
@property(nonatomic, weak) id digiDropOwner;
@end
@implementation ArpSIDDigiDropView
-(instancetype)initWithFrame:(NSRect)frame {
    self = [super initWithFrame:frame];
    if (self) [self registerForDraggedTypes:@[ NSPasteboardTypeFileURL ]];
    return self;
}
-(NSDragOperation)draggingEntered:(id<NSDraggingInfo>)sender {
    NSPasteboard* pb = sender.draggingPasteboard;
    NSArray<NSURL*>* urls = [pb readObjectsForClasses:@[ NSURL.class ] options:@{ NSPasteboardURLReadingFileURLsOnlyKey: @YES }];
    return urls.count > 0 ? NSDragOperationCopy : NSDragOperationNone;
}
-(BOOL)performDragOperation:(id<NSDraggingInfo>)sender {
    NSPasteboard* pb = sender.draggingPasteboard;
    NSArray<NSURL*>* urls = [pb readObjectsForClasses:@[ NSURL.class ] options:@{ NSPasteboardURLReadingFileURLsOnlyKey: @YES }];
    if (urls.count == 0 || !self.digiDropOwner) return NO;
    SEL sel = @selector(_digiImportDraggedFileURL_v200_:);
    if (![self.digiDropOwner respondsToSelector:sel]) return NO;
    BOOL (*msg)(id, SEL, NSURL*) = (BOOL (*)(id, SEL, NSURL*))objc_msgSend;
    return msg(self.digiDropOwner, sel, urls.firstObject);
}
@end

