@implementation ArpSIDEditorView {
    CAGradientLayer* _ambientAuroraLayer;
    CAGradientLayer* _rasterBeamLayer;
    CAShapeLayer* _edgePulseLayer;
    BOOL _eyeCandyLayersBuilt;
    BOOL _eyeIdleApplied;     // YES once the static idle backdrop frame has been committed
    CGFloat _lastEyeCandyA;   // last applied activity (for idle-skip comparison)
    CGFloat _lastEyeCandyF;   // last applied forensic activity
}
// Background: deep C64 blue with scanlines and radial vignette. Lightweight
// aurora/raster layers above it are advanced only by the controller's
// coalesced display-link tick; there are no independent timers or CA loops.
-(BOOL)isOpaque{return YES;}
-(void)_ensureEyeCandyLayers{
    if(self.lifecycleOwner && ![self.lifecycleOwner editorRootMayInstallEyeCandy_v834]) return;
    if(_eyeCandyLayersBuilt || !self.layer) return;
    NSDictionary* noActions=@{@"position":NSNull.null, @"bounds":NSNull.null,
                              @"frame":NSNull.null, @"opacity":NSNull.null,
                              @"transform":NSNull.null, @"path":NSNull.null,
                              @"strokeColor":NSNull.null};
    _ambientAuroraLayer=[CAGradientLayer layer];
    _ambientAuroraLayer.actions=noActions;
    _ambientAuroraLayer.startPoint=CGPointMake(0.0,0.2);
    _ambientAuroraLayer.endPoint=CGPointMake(1.0,0.8);
    _ambientAuroraLayer.colors=@[
        (id)[c64Cyan() colorWithAlphaComponent:0.0].CGColor,
        (id)[c64Cyan() colorWithAlphaComponent:0.14].CGColor,
        (id)[c64Red() colorWithAlphaComponent:0.07].CGColor,
        (id)[c64LtBlue() colorWithAlphaComponent:0.0].CGColor
    ];
    _ambientAuroraLayer.locations=@[@0.0,@0.34,@0.68,@1.0];
    [self.layer insertSublayer:_ambientAuroraLayer atIndex:0];

    _rasterBeamLayer=[CAGradientLayer layer];
    _rasterBeamLayer.actions=noActions;
    _rasterBeamLayer.startPoint=CGPointMake(0.0,0.5);
    _rasterBeamLayer.endPoint=CGPointMake(1.0,0.5);
    _rasterBeamLayer.colors=@[
        (id)[NSColor clearColor].CGColor,
        (id)[c64LtGreen() colorWithAlphaComponent:0.18].CGColor,
        (id)[c64Cyan() colorWithAlphaComponent:0.34].CGColor,
        (id)[NSColor clearColor].CGColor
    ];
    _rasterBeamLayer.locations=@[@0.0,@0.35,@0.52,@1.0];
    [self.layer insertSublayer:_rasterBeamLayer atIndex:1];

    _edgePulseLayer=[CAShapeLayer layer];
    _edgePulseLayer.actions=noActions;
    _edgePulseLayer.fillColor=nil;
    _edgePulseLayer.lineWidth=1.0;
    _edgePulseLayer.shadowOffset=CGSizeZero;
    [self.layer insertSublayer:_edgePulseLayer atIndex:2];
    _eyeCandyLayersBuilt=YES;
    [self _layoutEyeCandyLayers];
}
-(void)_layoutEyeCandyLayers{
    if(!_eyeCandyLayersBuilt) return;
    const CGRect b=NSRectToCGRect(self.bounds);
    _ambientAuroraLayer.frame=CGRectInset(b,-CGRectGetWidth(b)*0.18,-CGRectGetHeight(b)*0.10);
    _edgePulseLayer.frame=b;
    CGPathRef edgePath=CGPathCreateWithRoundedRect(CGRectInset(b,2.5,2.5),9.0,9.0,nullptr);
    _edgePulseLayer.path=edgePath;
    CGPathRelease(edgePath);
}
-(void)layout{
    [super layout];
    [self _ensureEyeCandyLayers];
    [self _layoutEyeCandyLayers];
}
-(void)viewDidMoveToWindow{
    [super viewDidMoveToWindow];
    [self _ensureEyeCandyLayers];
    if(self.window) [self.lifecycleOwner editorRootViewDidAttachToWindow_v821];
    else [self.lifecycleOwner editorRootViewDidDetachFromWindow_v821];
}
-(void)updateVsyncEyeCandyWithPhase:(double)phase
                            activity:(float)activity
                    forensicActivity:(float)forensicActivity
                             playing:(BOOL)playing{
    [self _ensureEyeCandyLayers];
    if(!_eyeCandyLayersBuilt || self.hidden || !self.window) return;
    const CGFloat a=ArpSIDUIClamp01(activity);
    const CGFloat f=ArpSIDUIClamp01(forensicActivity);
    const CGFloat p=(CGFloat)std::fmod(std::max(0.0,phase),1.0);
    // Idle visualizer fix: the background aurora + raster beam previously MOVED
    // every vsync tick (their position is driven by the wall-clock phase) and only
    // scaled OPACITY with activity — so the whole editor background drifted and
    // swept with no audio data. Gate the MOTION on activity too: when idle (no
    // meter/forensic activity and not playing) freeze the motion phase so the
    // background is static, and hide the raster beam entirely.
    const bool active=(a>0.01f)||(f>0.01f)||playing;
    // Idle redraw fix: when there is no activity the motion phase is frozen (pm=0)
    // and the layer values depend only on (a,f). Once an idle frame has been applied
    // with the same a/f, re-assigning identical CALayer properties every tick still
    // schedules a CoreAnimation commit for nothing — skip it so the editor backdrop
    // is genuinely static when idle.
    if(!active && _eyeIdleApplied &&
       std::fabs(a-_lastEyeCandyA)<0.0008 && std::fabs(f-_lastEyeCandyF)<0.0008){
        return;
    }
    _lastEyeCandyA=a; _lastEyeCandyF=f; _eyeIdleApplied=!active;
    const CGFloat pm=active?p:0.0;   // motion phase — frozen when idle
    const CGRect b=NSRectToCGRect(self.bounds);
    [CATransaction begin];
    [CATransaction setDisableActions:YES];
    _ambientAuroraLayer.opacity=(float)(0.20+0.34*a+0.18*f);
    _ambientAuroraLayer.transform=CATransform3DMakeTranslation(
        (pm-0.5)*CGRectGetWidth(b)*0.30,
        std::sin(pm*6.28318530718)*CGRectGetHeight(b)*0.035,
        0.0);
    const CGFloat beamW=std::max<CGFloat>(56.0,CGRectGetWidth(b)*0.11);
    const CGFloat beamX=CGRectGetMinX(b)-beamW+pm*(CGRectGetWidth(b)+beamW*2.0);
    _rasterBeamLayer.frame=CGRectMake(beamX,CGRectGetMinY(b),beamW,CGRectGetHeight(b));
    _rasterBeamLayer.opacity=(float)(active?((playing?0.10:0.035)+0.24*a+0.16*f):0.0);
    const CGFloat pulse=0.5+0.5*std::sin(pm*6.28318530718);
    _edgePulseLayer.strokeColor=[(f>0.20?c64Yellow():c64Cyan())
        colorWithAlphaComponent:0.08+0.18*a+0.12*f+0.05*pulse].CGColor;
    _edgePulseLayer.shadowColor=_edgePulseLayer.strokeColor;
    _edgePulseLayer.shadowOpacity=(float)(0.08+0.30*a+0.18*f);
    _edgePulseLayer.shadowRadius=3.0+10.0*a+6.0*f;
    [CATransaction commit];
}
-(void)drawRect:(NSRect)dr{(void)dr;
    if(self.lifecycleOwner && ![self.lifecycleOwner editorRootMayInstallEyeCandy_v834]){
        [NSColor.blackColor setFill];
        NSRectFill(self.bounds);
        return;
    }
    NSRect b=self.bounds;
    const CGFloat W=b.size.width, H=b.size.height;
    NSGradient*base=[[NSGradient alloc]
        initWithColorsAndLocations:
            [NSColor colorWithSRGBRed:.034f green:.030f blue:.140f alpha:1],(CGFloat)0.0,
            [NSColor colorWithSRGBRed:.052f green:.046f blue:.185f alpha:1],(CGFloat)0.50,
            [NSColor colorWithSRGBRed:.018f green:.015f blue:.075f alpha:1],(CGFloat)1.0,
            nil];
    [base drawInRect:b angle:90.0f];
    // 2. Radial vignette — darker at all four edges
    {
        NSGradient*vig=[[NSGradient alloc]
            initWithColorsAndLocations:
                [NSColor colorWithSRGBRed:.055f green:.044f blue:.200f alpha:1],(CGFloat)0.0,
                [NSColor colorWithSRGBRed:.028f green:.022f blue:.110f alpha:1],(CGFloat)0.60,
                [NSColor colorWithSRGBRed:.008f green:.006f blue:.040f alpha:1],(CGFloat)1.0,
                nil];
        [vig drawInRect:b relativeCenterPosition:NSMakePoint(0,0)];
    }
    [[c64Cyan() colorWithAlphaComponent:.05f] setFill];
    [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(-W*0.18f, H*0.48f, W*0.72f, H*0.62f)] fill];
    [[c64Red() colorWithAlphaComponent:.030f] setFill];
    [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(W*0.46f, -H*0.08f, W*0.58f, H*0.52f)] fill];
    // 3. Scanlines (every 2.5px, very subtle)
    {
        [[NSColor colorWithSRGBRed:0 green:0 blue:0 alpha:.10f] setFill];
        for(CGFloat sy=b.origin.y; sy<b.origin.y+H; sy+=2.5f)
            NSRectFill(NSMakeRect(b.origin.x,sy,W,1.0f));
    }
    // 4. Subtle vertical stripe texture (adds depth)
    {
        [[NSColor colorWithSRGBRed:1 green:1 blue:1 alpha:.012f] setFill];
        for(CGFloat sx=b.origin.x; sx<b.origin.x+W; sx+=4.0f)
            NSRectFill(NSMakeRect(sx,b.origin.y,1.0f,H));
    }
    {
        [[c64LtBlue() colorWithAlphaComponent:.022f] setFill];
        for(CGFloat sy=b.origin.y+14.0f; sy<b.origin.y+H; sy+=28.0f)
            NSRectFill(NSMakeRect(b.origin.x+6.0f,sy,W-12.0f,3.0f));
    }
    // 5. Top edge highlight (gives a bezel-like top)
    [[NSColor colorWithSRGBRed:.25f green:.20f blue:.70f alpha:.18f] setFill];
    NSRectFill(NSMakeRect(b.origin.x,b.origin.y+H-2,W,2));
    // 6. Bottom shadow
    [[NSColor colorWithSRGBRed:0 green:0 blue:0 alpha:.25f] setFill];
    NSRectFill(NSMakeRect(b.origin.x,b.origin.y,W,2));
}
-(NSView*)hitTest:(NSPoint)pt{
    return [super hitTest:pt];
}
-(BOOL)performKeyEquivalent:(NSEvent*)event{
    const NSEventModifierFlags mods = (event.modifierFlags & NSEventModifierFlagDeviceIndependentFlagsMask);
    const BOOL hasCommand = (mods & NSEventModifierFlagCommand) != 0;
    const BOOL onlyCommandChord = (mods & ~(NSEventModifierFlagCommand | NSEventModifierFlagShift)) == 0;
    if(hasCommand && onlyCommandChord){
        NSString* chars = (event.charactersIgnoringModifiers != nil) ? event.charactersIgnoringModifiers : @"";
        if(chars.length == 1){
            unichar c = [chars characterAtIndex:0];
            NSInteger idx = -1;
            switch(c){
                case '1': idx = 0; break;
                case '2': idx = 1; break;
                case '3': idx = 3; break;
                case '4': idx = 4; break;
                case '5': idx = 5; break;
                case '6': idx = 6; break;
                case '7': idx = 7; break;
                case '8': idx = 8; break;
                case '9': idx = 9; break;
                case '0': idx = 10; break;
                case 'f': idx = 5; break;
                case 'F': idx = 5; break;
                default: break;
            }
            if(idx >= 0){
                [[NSNotificationCenter defaultCenter] postNotificationName:ArpSIDSelectTabNotification
                                                                    object:self
                                                                  userInfo:@{ @"tabIndex": @(idx) }];
                return YES;
            }
            if(c == NSUpArrowFunctionKey){
                [[NSNotificationCenter defaultCenter] postNotificationName:ArpSIDPianoOctaveUpNotification object:self];
                return YES;
            }
            if(c == NSDownArrowFunctionKey){
                [[NSNotificationCenter defaultCenter] postNotificationName:ArpSIDPianoOctaveDownNotification object:self];
                return YES;
            }
        }
    }
    return [super performKeyEquivalent:event];
}
@end

@interface ArpSIDSegmentedToolTipControl : NSSegmentedControl <NSViewToolTipOwner>
@property(nonatomic,copy) NSArray<NSString*>* segmentToolTips;
// v823: last bar width the per-segment widths were fitted to (see
// ArpSIDFitVisibleTabBarWidths_v320). 0 forces a re-fit on the next pass.
@property(nonatomic,assign) CGFloat tabFitLastAvailable_v823;
@end

@implementation ArpSIDSegmentedToolTipControl {
    // v823: cache so the tooltip rects are only rebuilt when the control size
    // actually changes — see _refreshSegmentToolTips for why this matters on
    // macOS 26's SwiftUI-backed NSSegmentedControl.
    NSSize _lastTooltipBounds_v823_;
    BOOL _tooltipRectInstalled_v823_;
}
- (void)setSegmentToolTips:(NSArray<NSString*>*)segmentToolTips{
    if ((_segmentToolTips == segmentToolTips) ||
        [_segmentToolTips isEqualToArray:segmentToolTips]) return;
    _segmentToolTips=[segmentToolTips copy];
    // expose the tab ring as a discoverable control for VoiceOver and
    // host accessibility inspectors. The per-segment tooltip array remains the
    // pointer-hover source; this summary is intentionally compact and stable.
    self.accessibilityLabel = @"ArpSID tab navigation";
    self.accessibilityHelp = [_segmentToolTips componentsJoinedByString:@"  |  "];
    _lastTooltipBounds_v823_ = NSZeroSize;  // force a rebuild for the new tip set
    [self _refreshSegmentToolTips];
}
- (void)layout{
    [super layout];
    [self _refreshSegmentToolTips];
}
- (void)viewDidMoveToWindow{
    [super viewDidMoveToWindow];
    [self _refreshSegmentToolTips];
}
- (void)_refreshSegmentToolTips{
    // PERF (v823): -layout runs this every pass. The previous implementation looped
    // calling -widthForSegment: for every segment and rebuilt per-segment tooltip
    // rects on each call. On macOS 26 NSSegmentedControl is implemented on top of
    // SwiftUI/AttributeGraph, so -widthForSegment: forces a full geometry recompute;
    // doing it for all segments inside the layout pass (×many segmented controls,
    // ×17 tab segments) re-enters layout and pegs the main thread for seconds when
    // the editor is laid out at a host's large out-of-process container size — which
    // Logic reports as "this AU may make the system unstable". Install ONE full-bounds
    // tooltip rect and resolve the segment from the hover point on demand instead, and
    // only rebuild when the size actually changes. No -widthForSegment: in layout.
    const NSSize sz = self.bounds.size;
    if (_tooltipRectInstalled_v823_ && NSEqualSizes(sz, _lastTooltipBounds_v823_)) return;
    _lastTooltipBounds_v823_ = sz;
    [self removeAllToolTips];
    if (sz.width > 0.0 && sz.height > 0.0 && self.segmentCount > 0) {
        [self addToolTipRect:self.bounds owner:self userData:NULL];
        _tooltipRectInstalled_v823_ = YES;
    } else {
        _tooltipRectInstalled_v823_ = NO;
    }
}
- (NSString*)view:(NSView*)view stringForToolTip:(NSToolTipTag)tag point:(NSPoint)point userData:(void*)userData{
    (void)view;(void)tag;(void)userData;
    // Resolve which segment the pointer is over only now (on hover) — not during
    // layout. -widthForSegment: here is fine: it runs at most once per hover.
    NSInteger idx = -1;
    const NSInteger n = self.segmentCount;
    if (n > 0) {
        const CGFloat fallbackW = floor(NSWidth(self.bounds) / (CGFloat)n);
        CGFloat x = 0.0f;
        for (NSInteger i = 0; i < n; ++i) {
            CGFloat w = [self widthForSegment:i];
            if (w <= 0.0f) w = fallbackW;
            if (point.x >= x && point.x < x + w) { idx = i; break; }
            x += w;
        }
        if (idx < 0) idx = n - 1;  // clamp past the last segment edge
    }
    if(idx >= 0 && idx < (NSInteger)_segmentToolTips.count){
        NSString* tip=_segmentToolTips[(NSUInteger)idx];
        if(tip.length > 0) return tip;
    }
    return self.toolTip ? self.toolTip : @"";
}
@end

#if defined(ARPSID_AUV2_COMPONENT)
// v835: the AUv2 out-of-process editor is built SYNCHRONOUSLY in -loadView, exactly like
// the known-good pass353 baseline. The v826-v834 "defer the editor build until the remote
// view attaches" path is permanently DISABLED here because it was the regression that made
// Logic appear to hang when opening the AUv2 editor:
//   * inside AUHostingServiceXPC it installed a black boot cover and rebuilt the real
//     editor only after ArpSIDAuv2OOPEditorBuildDelaySeconds (which had been bumped to
//     7.5s) — a guaranteed multi-second black/frozen window on every editor open; and
//   * -_finishDeferredAuv2EditorBuild_v831_ required both an attached NSWindow and a
//     completed first-paint fence, otherwise it rescheduled the same delay forever, so a
//     host that never satisfied those preconditions left a permanently black editor.
// _deferAuv2OOPEditorBuild_v831 is assigned from this function at exactly one site
// (-loadView); returning NO makes that flag always NO, which collapses every defer/fence
// guard downstream to the pass353 synchronous build path. The delay constant is kept (it is
// still referenced by the now-unreachable scheduler) but neutered to 0 so the dead path can
// never reintroduce a user-visible stall even if a future change re-enables deferral.
static constexpr NSTimeInterval ArpSIDAuv2OOPEditorBuildDelaySeconds_v834 = 0.0;

static BOOL ArpSIDShouldDeferAuv2OOPBootstrap_v831(void) {
    // Always build the AUv2 editor synchronously (pass353 behavior). See note above.
    return NO;
}
#else
// v909: non-AUv2 wrappers (VST3 cocoa bridge, AUv3) share this translation
// unit, and the (unreachable) deferred-editor scheduler still references both
// symbols. Keep the same neutered definitions so every wrapper compiles and
// behaves identically: no deferral, zero delay.
static constexpr NSTimeInterval ArpSIDAuv2OOPEditorBuildDelaySeconds_v834 = 0.0;

static BOOL ArpSIDShouldDeferAuv2OOPBootstrap_v831(void) {
    return NO;
}
#endif

