    if(!self.layer) return;
    self.layer.borderColor=[(_hovering ? c64Yellow() : colBorder()) colorWithAlphaComponent:(_hovering ? .56f : .35f)].CGColor;
    self.layer.backgroundColor=[colOscBg() colorWithAlphaComponent:(_hovering ? .72f : .62f)].CGColor;
