// Per-tab brand accent + label so the persistent header badge identifies the
// active tab/function (a custom logo per tab). Uses the canonical per-tab HUD
// label from tab_architecture.h and a distinct accent colour per tab.
static NSColor* ArpSIDTabBrandAccent(NSInteger tab) {
    switch (static_cast<ArpSID::GUI::ArpSIDTab>(tab)) {
        case ArpSID::GUI::ArpSIDTab::Main:         return c64Cyan();
        case ArpSID::GUI::ArpSIDTab::LfoArp:       return c64LtGreen();
        case ArpSID::GUI::ArpSIDTab::SidRegisters: return c64Yellow();
        case ArpSID::GUI::ArpSIDTab::Sequencer:    return c64Orange();
        case ArpSID::GUI::ArpSIDTab::DrSid:        return c64LightRed();
        case ArpSID::GUI::ArpSIDTab::Filter:       return c64LtBlue();
        case ArpSID::GUI::ArpSIDTab::Macro:        return c64Purple();
        case ArpSID::GUI::ArpSIDTab::Forensic:     return c64Red();
        case ArpSID::GUI::ArpSIDTab::SidCore:      return c64Cyan();
        case ArpSID::GUI::ArpSIDTab::C64:          return c64LtBlue();
        case ArpSID::GUI::ArpSIDTab::HiFi:         return c64White();
        case ArpSID::GUI::ArpSIDTab::Bank:         return c64Yellow();
        case ArpSID::GUI::ArpSIDTab::Options:      return c64LtGreen();
        case ArpSID::GUI::ArpSIDTab::Settings:     return c64White();
        case ArpSID::GUI::ArpSIDTab::Mix:          return c64Orange();
        case ArpSID::GUI::ArpSIDTab::Kit:          return c64LightRed();
        case ArpSID::GUI::ArpSIDTab::Digi:         return c64Cyan();
        default:                                   return c64LtBlue();
    }
}
static NSString* ArpSIDTabBrandLabel(NSInteger tab) {
    const char* l = ArpSID::GUI::tabSpec(static_cast<ArpSID::GUI::ArpSIDTab>(tab)).hudLabel;
    return (l && l[0]) ? [NSString stringWithUTF8String:l] : @"";
}

// Bespoke per-tab vector glyph. Each tab/function gets a distinct little icon
// drawn in the tab's accent colour inside the header brand badge. Kept to simple
// NSBezierPath primitives so it stays crisp at ~9 px.
static void ArpSIDDrawTabGlyph(NSInteger tab, NSRect g, NSColor* color) {
    [color set];
    const CGFloat x=NSMinX(g), y=NSMinY(g), w=NSWidth(g), h=NSHeight(g);
    const CGFloat cx=NSMidX(g), cy=NSMidY(g);
    NSBezierPath* p=[NSBezierPath bezierPath];
    p.lineWidth=1.0f; p.lineJoinStyle=NSLineJoinStyleRound; p.lineCapStyle=NSLineCapStyleRound;
    auto rect=[&](CGFloat rx,CGFloat ry,CGFloat rw,CGFloat rh){ return NSMakeRect(x+rx*w, y+ry*h, rw*w, rh*h); };
    auto dot=[&](CGFloat dx,CGFloat dy,CGFloat r){ [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(x+dx*w-r, y+dy*h-r, r*2, r*2)] fill]; };
    switch (static_cast<ArpSID::GUI::ArpSIDTab>(tab)) {
        case ArpSID::GUI::ArpSIDTab::Main: { // sine wave
            for(int i=0;i<=12;++i){ CGFloat t=(CGFloat)i/12.0f; NSPoint pt=NSMakePoint(x+w*t, cy+std::sin(t*6.2831853f)*h*0.34f); if(i==0)[p moveToPoint:pt]; else [p lineToPoint:pt]; }
            [p stroke]; break; }
        case ArpSID::GUI::ArpSIDTab::LfoArp: { // stepped arp stairs
            [p moveToPoint:NSMakePoint(x, y+h*0.15f)];
            [p lineToPoint:NSMakePoint(x+w*0.34f, y+h*0.15f)]; [p lineToPoint:NSMakePoint(x+w*0.34f, y+h*0.5f)];
            [p lineToPoint:NSMakePoint(x+w*0.67f, y+h*0.5f)];  [p lineToPoint:NSMakePoint(x+w*0.67f, y+h*0.85f)];
            [p lineToPoint:NSMakePoint(x+w, y+h*0.85f)]; [p stroke]; break; }
        case ArpSID::GUI::ArpSIDTab::SidRegisters: { // 3x2 register grid
            for(int r=0;r<2;++r) for(int c=0;c<3;++c) [[NSBezierPath bezierPathWithRect:rect(0.04f+c*0.33f, 0.08f+r*0.48f, 0.26f, 0.36f)] stroke];
            break; }
        case ArpSID::GUI::ArpSIDTab::Sequencer: { // step row (2 filled, 2 open)
            for(int c=0;c<4;++c){ NSRect s=rect(0.02f+c*0.25f, 0.30f, 0.20f, 0.40f); if(c==0||c==2) NSRectFill(s); else [[NSBezierPath bezierPathWithRect:s] stroke]; }
            break; }
        case ArpSID::GUI::ArpSIDTab::DrSid: { // drum head + stick
            [[NSBezierPath bezierPathWithOvalInRect:rect(0.06f,0.10f,0.62f,0.62f)] stroke];
            [p moveToPoint:NSMakePoint(x+w*0.55f, y+h*0.55f)]; [p lineToPoint:NSMakePoint(x+w*0.95f, y+h*0.95f)]; [p stroke]; break; }
        case ArpSID::GUI::ArpSIDTab::Filter: { // low-pass slope
            [p moveToPoint:NSMakePoint(x, y+h*0.72f)]; [p lineToPoint:NSMakePoint(x+w*0.45f, y+h*0.72f)];
            [p curveToPoint:NSMakePoint(x+w, y+h*0.12f) controlPoint1:NSMakePoint(x+w*0.72f, y+h*0.72f) controlPoint2:NSMakePoint(x+w*0.72f, y+h*0.12f)];
            [p stroke]; break; }
        case ArpSID::GUI::ArpSIDTab::Macro: { // knob + pointer
            [[NSBezierPath bezierPathWithOvalInRect:rect(0.12f,0.12f,0.76f,0.76f)] stroke];
            [p moveToPoint:NSMakePoint(cx,cy)]; [p lineToPoint:NSMakePoint(x+w*0.78f, y+h*0.82f)]; [p stroke]; break; }
        case ArpSID::GUI::ArpSIDTab::Forensic: { // magnifier
            [[NSBezierPath bezierPathWithOvalInRect:rect(0.06f,0.30f,0.56f,0.56f)] stroke];
            [p moveToPoint:NSMakePoint(x+w*0.60f, y+h*0.36f)]; [p lineToPoint:NSMakePoint(x+w*0.98f, y+h*0.02f)]; p.lineWidth=1.4f; [p stroke]; break; }
        case ArpSID::GUI::ArpSIDTab::SidCore: { // IC chip + pins
            [[NSBezierPath bezierPathWithRect:rect(0.22f,0.20f,0.56f,0.60f)] stroke];
            for(int i=0;i<3;++i){ CGFloat py=y+h*(0.28f+i*0.22f); [NSBezierPath strokeLineFromPoint:NSMakePoint(x+w*0.06f,py) toPoint:NSMakePoint(x+w*0.22f,py)]; [NSBezierPath strokeLineFromPoint:NSMakePoint(x+w*0.78f,py) toPoint:NSMakePoint(x+w*0.94f,py)]; }
            break; }
        case ArpSID::GUI::ArpSIDTab::C64: { // breadbin computer
            [[NSBezierPath bezierPathWithRect:rect(0.06f,0.18f,0.88f,0.56f)] stroke];
            [NSBezierPath strokeLineFromPoint:NSMakePoint(x+w*0.18f,y+h*0.56f) toPoint:NSMakePoint(x+w*0.82f,y+h*0.56f)];
            break; }
        case ArpSID::GUI::ArpSIDTab::HiFi: { // speaker
            [[NSBezierPath bezierPathWithRect:rect(0.12f,0.10f,0.50f,0.80f)] stroke];
            [[NSBezierPath bezierPathWithOvalInRect:rect(0.20f,0.30f,0.34f,0.40f)] stroke]; break; }
        case ArpSID::GUI::ArpSIDTab::Bank: { // stacked cards
            for(int i=0;i<3;++i) [[NSBezierPath bezierPathWithRect:rect(0.06f+i*0.10f, 0.12f+i*0.20f, 0.62f, 0.24f)] stroke];
            break; }
        case ArpSID::GUI::ArpSIDTab::Options: { // gear
            [[NSBezierPath bezierPathWithOvalInRect:rect(0.24f,0.24f,0.52f,0.52f)] stroke];
            for(int i=0;i<6;++i){ CGFloat a=i*(6.2831853f/6.0f); [NSBezierPath strokeLineFromPoint:NSMakePoint(cx+std::cos(a)*w*0.30f, cy+std::sin(a)*h*0.30f) toPoint:NSMakePoint(cx+std::cos(a)*w*0.46f, cy+std::sin(a)*h*0.46f)]; }
            break; }
        case ArpSID::GUI::ArpSIDTab::Settings: { // sliders (horizontal)
            for(int i=0;i<3;++i){ CGFloat py=y+h*(0.22f+i*0.28f); [NSBezierPath strokeLineFromPoint:NSMakePoint(x+w*0.06f,py) toPoint:NSMakePoint(x+w*0.94f,py)]; dot(0.30f+i*0.22f, 0.22f+i*0.28f, 1.4f); }
            break; }
        case ArpSID::GUI::ArpSIDTab::Mix: { // faders (vertical)
            for(int i=0;i<3;++i){ CGFloat px=x+w*(0.22f+i*0.28f); [NSBezierPath strokeLineFromPoint:NSMakePoint(px,y+h*0.08f) toPoint:NSMakePoint(px,y+h*0.92f)]; dot(0.22f+i*0.28f, 0.30f+i*0.20f, 1.4f); }
            break; }
        case ArpSID::GUI::ArpSIDTab::Kit: { // 2x2 pad grid
            for(int r=0;r<2;++r) for(int c=0;c<2;++c) [[NSBezierPath bezierPathWithRoundedRect:rect(0.10f+c*0.44f, 0.10f+r*0.44f, 0.34f, 0.34f) xRadius:1.0f yRadius:1.0f] stroke];
            break; }
        case ArpSID::GUI::ArpSIDTab::Digi: { // 4-bit stair waveform
            const CGFloat lv[6]={0.30f,0.70f,0.50f,0.85f,0.40f,0.60f};
            [p moveToPoint:NSMakePoint(x, y+h*lv[0])];
            for(int i=0;i<6;++i){ CGFloat px=x+w*(i/6.0f); [p lineToPoint:NSMakePoint(px, y+h*lv[i])]; [p lineToPoint:NSMakePoint(x+w*((i+1)/6.0f), y+h*lv[i])]; }
            [p stroke]; break; }
        default: { [[NSBezierPath bezierPathWithOvalInRect:rect(0.2f,0.2f,0.6f,0.6f)] stroke]; break; }
    }
}

@interface ArpSIDC64LogoView : NSView
@property(nonatomic,assign) float activity;
@property(nonatomic,assign) float forensicActivity;
@property(nonatomic,assign) double beat;
@property(nonatomic,assign) BOOL transportPlaying;
@property(nonatomic,assign) NSInteger currentTab; // ArpSIDTab of the active tab
@end
@implementation ArpSIDC64LogoView
{
    float _activity;
    float _forensicActivity;
    double _beat;
    BOOL _transportPlaying;
    NSInteger _currentTab;
    BOOL _haveTab;
}
-(void)setCurrentTab:(NSInteger)currentTab{
    if(!_haveTab || _currentTab!=currentTab){ _currentTab=currentTab; _haveTab=YES; [self setNeedsDisplay:YES]; }
}
-(void)setActivity:(float)activity{
    const float nv=ArpSIDUIClamp01(activity);
    if(fabsf(nv-_activity)>0.001f){_activity=nv;[self setNeedsDisplay:YES];}
}
-(void)setForensicActivity:(float)forensicActivity{
    const float nv=ArpSIDUIClamp01(forensicActivity);
    if(fabsf(nv-_forensicActivity)>0.001f){_forensicActivity=nv;[self setNeedsDisplay:YES];}
}
-(void)setBeat:(double)beat{
    // Idle visualizer fix: the badge animation no longer reads the host beat, so a
    // rolling-but-silent transport must NOT force redraws here. Storing the value
    // is harmless; the redraw (and thus any motion) is driven by setActivity only.
    _beat=std::max(0.0, ArpSIDUIFiniteDouble(beat,0.0));
}
-(void)setTransportPlaying:(BOOL)transportPlaying{
    if(_transportPlaying!=transportPlaying){_transportPlaying=transportPlaying;[self setNeedsDisplay:YES];}
}
-(void)drawRect:(NSRect)dirtyRect{
    (void)dirtyRect;
    const NSRect b = NSInsetRect(self.bounds, 1.0f, 1.0f);
    // Idle visualizer fix: the badge's raster bar / wave / rails are positioned by
    // `phase`. It used to include `_beat * 0.17` (the HOST TRANSPORT beat), so a
    // rolling-but-silent transport made the bar sweep continuously with no audio
    // data — the "smooth continuous drift from the start". Drive `phase` only from
    // real audio level (and forensic mode): both are 0 when silent, so the badge
    // holds still with no data and reacts only to actual sound; it also settles
    // smoothly as the level decays (no snap) because nothing keeps advancing.
    const CGFloat phase = (CGFloat)std::fmod(_activity * 0.6 + _forensicActivity * 0.4, 1.0);
    [[c64LtBlue() colorWithAlphaComponent:(0.03f + _activity*0.04f + _forensicActivity*0.06f)] setFill];
    [[NSBezierPath bezierPathWithRoundedRect:NSInsetRect(b, -2.0f, -2.0f) xRadius:10.0f yRadius:10.0f] fill];
    NSBezierPath* badgePath=[NSBezierPath bezierPathWithRoundedRect:b xRadius:8.0f yRadius:8.0f];
    NSGradient* shell=[[NSGradient alloc] initWithColorsAndLocations:
                       ArpSIDRGB(0.05,0.04,0.14,0.98), 0.0,
                       ArpSIDRGB(0.10,0.08,0.24,0.98), 0.55,
                       ArpSIDRGB(0.04,0.03,0.11,0.98), 1.0,
                       nil];
    [shell drawInBezierPath:badgePath angle:90.0];
    [[ArpSIDRGB(0.08,0.06,0.20,0.98) colorWithAlphaComponent:.30f] setFill];
    [badgePath fill];
    [[c64LtBlue() colorWithAlphaComponent:.42f] setStroke];
    [badgePath setLineWidth:1.0f];
    [badgePath stroke];
    [[c64Cyan() colorWithAlphaComponent:(0.04f + _activity*0.08f + _forensicActivity*0.08f)] setFill];
    [[NSBezierPath bezierPathWithRoundedRect:NSInsetRect(b, -2.0f, -2.0f) xRadius:10.0f yRadius:10.0f] fill];
    NSRect inner = NSInsetRect(b, 4.0f, 4.0f);
    NSBezierPath* innerPath=[NSBezierPath bezierPathWithRoundedRect:inner xRadius:6.0f yRadius:6.0f];
    NSGradient* innerBg=[[NSGradient alloc] initWithColorsAndLocations:
                         ArpSIDRGB(0.08,0.09,0.22,0.94), 0.0,
                         ArpSIDRGB(0.12,0.12,0.30,0.95), 0.6,
                         ArpSIDRGB(0.06,0.06,0.18,0.96), 1.0,
                         nil];
    [innerBg drawInBezierPath:innerPath angle:90.0];
    const CGFloat rasterX = NSMinX(inner) + 34.0f + phase * std::max<CGFloat>(8.0f, NSWidth(inner) - 50.0f);
    [[c64LtBlue() colorWithAlphaComponent:(0.03f + _activity*0.08f + _forensicActivity*0.06f)] setFill];
    [[NSBezierPath bezierPathWithRoundedRect:NSMakeRect(rasterX, NSMinY(inner)+5.0f, 12.0f, NSHeight(inner)-10.0f) xRadius:5.0f yRadius:5.0f] fill];
    [[c64Yellow() colorWithAlphaComponent:(0.16f + _activity*0.14f + _forensicActivity*0.08f)] setStroke];
    NSBezierPath*trace=[NSBezierPath bezierPath];
    trace.lineWidth=1.2f;
    const CGFloat traceStartX=NSMinX(inner)+34.0f;
    const CGFloat traceWidth=std::max<CGFloat>(18.0f, NSWidth(inner)-44.0f);
    const CGFloat traceAmp=2.0f + _activity*4.8f + _forensicActivity*3.0f;
    for(int i=0;i<16;++i){
        const CGFloat t=(CGFloat)i/15.0f;
        const CGFloat tx=traceStartX + traceWidth*t;
        const CGFloat ty=NSMidY(inner) + std::sin(phase*6.28318530718f + t*9.0f)*traceAmp;
        if(i==0)[trace moveToPoint:NSMakePoint(tx, ty)];
        else [trace lineToPoint:NSMakePoint(tx, ty)];
    }
    [trace stroke];
    [[c64White() colorWithAlphaComponent:(0.02f + _activity*0.03f)] setStroke];
    for(CGFloat y=NSMinY(inner)+4.0f; y<NSMaxY(inner)-2.0f; y+=4.0f){
        [NSBezierPath strokeLineFromPoint:NSMakePoint(NSMinX(inner)+34.0f, y)
                                  toPoint:NSMakePoint(NSMaxX(inner)-7.0f, y)];
    }
    [[ArpSIDRGB(1.0,1.0,1.0,0.06) colorWithAlphaComponent:.06f] setFill];
    NSRectFill(NSMakeRect(NSMinX(inner)+1.0f, NSMaxY(inner)-7.0f, NSWidth(inner)-2.0f, 4.0f));
    [[c64Black() colorWithAlphaComponent:.22f] setFill];
    NSRectFill(NSMakeRect(NSMinX(inner)+2.0f, NSMinY(inner)+2.0f, NSWidth(inner)-4.0f, 4.0f));
    [[c64Red() colorWithAlphaComponent:.94f] setFill];
    NSRectFill(NSMakeRect(NSMinX(b)+7.0f, NSMinY(b)+7.0f, 8.5f, NSHeight(b)-14.0f));
    [[c64Cyan() colorWithAlphaComponent:.92f] setFill];
    NSRectFill(NSMakeRect(NSMinX(b)+17.5f, NSMinY(b)+7.0f, 8.5f, NSHeight(b)-14.0f));
    [[c64Yellow() colorWithAlphaComponent:.32f] setFill];
    NSRectFill(NSMakeRect(NSMinX(b)+29.0f, NSMinY(b)+9.0f, 2.0f, NSHeight(b)-18.0f));
    for(int rail=0; rail<4; ++rail){
        const CGFloat rx=NSMinX(inner)+6.0f+(CGFloat)rail*6.5f;
        const CGFloat amp=3.0f + _activity*5.0f + _forensicActivity*3.0f;
        const CGFloat y=NSMidY(inner)+sinf((phase*6.28318530718f)+(CGFloat)rail*0.75f)*amp;
        [[(rail&1)?c64Yellow():c64LtGreen() colorWithAlphaComponent:(0.18f+_activity*0.22f)] setFill];
        [[NSBezierPath bezierPathWithRoundedRect:NSMakeRect(rx, y-4.0f, 2.5f, 8.0f) xRadius:1.25f yRadius:1.25f] fill];
    }
    for(int i=0;i<4;++i){
        const CGFloat y=NSMinY(inner)+8.0f+(CGFloat)i*5.0f;
        const CGFloat alpha=0.06f + _activity*0.06f + ((i==((int)floor(phase*4.0f)%4)) ? 0.06f : 0.0f);
        [[ArpSIDRGB(0.40,0.74,1.0,alpha) colorWithAlphaComponent:alpha] setFill];
        NSBezierPath* stripe=[NSBezierPath bezierPath];
        [stripe moveToPoint:NSMakePoint(NSMinX(inner)+33.0f, y)];
        [stripe lineToPoint:NSMakePoint(NSMaxX(inner)-8.0f, y)];
        [stripe lineToPoint:NSMakePoint(NSMaxX(inner)-12.0f, y+2.0f)];
        [stripe lineToPoint:NSMakePoint(NSMinX(inner)+29.0f, y+2.0f)];
        [stripe closePath];
        [stripe fill];
    }
    NSDictionary* badgeAttrs = @{
        NSForegroundColorAttributeName:[c64White() colorWithAlphaComponent:(0.92f+_activity*0.06f)],
        NSFontAttributeName:monoBF(12.5f)
    };
    [@"C64" drawAtPoint:NSMakePoint(NSMinX(b)+35.0f, NSMidY(b)-7.5f) withAttributes:badgeAttrs];
    NSDictionary* subAttrs = @{
        NSForegroundColorAttributeName:[c64Yellow() colorWithAlphaComponent:(.72f+_activity*0.18f)],
        NSFontAttributeName:monoBF(6.4f)
    };
    [(_transportPlaying ? @"SID LIVE" : @"SID") drawAtPoint:NSMakePoint(NSMinX(b)+36.0f, NSMinY(b)+8.0f) withAttributes:subAttrs];
    NSDictionary* readyAttrs = @{
        NSForegroundColorAttributeName:[c64LtGreen() colorWithAlphaComponent:(.66f+_activity*0.24f+_forensicActivity*0.10f)],
        NSFontAttributeName:monoF(5.8f)
    };
    [(_transportPlaying ? @"READY. RUN" : @"READY.") drawAtPoint:NSMakePoint(NSMinX(b)+35.5f, NSMinY(b)+3.0f) withAttributes:readyAttrs];
    NSDictionary* chipAttrs = @{
        NSForegroundColorAttributeName:[c64LtBlue() colorWithAlphaComponent:(0.50f+_activity*0.16f+_forensicActivity*0.08f)],
        NSFontAttributeName:monoF(5.2f)
    };
    [@"6510 • SID • VIC" drawAtPoint:NSMakePoint(NSMaxX(inner)-54.0f, NSMinY(b)+3.2f) withAttributes:chipAttrs];
    [[c64LtBlue() colorWithAlphaComponent:(0.08f+_activity*0.16f)] setFill];
    NSRectFill(NSMakeRect(NSMinX(inner)+33.0f + phase*22.0f, NSMaxY(inner)-8.0f, 10.0f, 2.5f));
    // Per-tab brand: accent tick + the active tab's HUD label at the top-right,
    // so the header badge doubles as a per-tab/function logo that recolours and
    // relabels as the user moves between tabs.
    if(_haveTab){
        NSColor* accent=ArpSIDTabBrandAccent(_currentTab);
        NSString* tlabel=ArpSIDTabBrandLabel(_currentTab);
        NSDictionary* tabAttrs=@{
            NSForegroundColorAttributeName:[accent colorWithAlphaComponent:0.96f],
            NSFontAttributeName:monoBF(6.6f)
        };
        const NSSize sz=[tlabel sizeWithAttributes:tabAttrs];
        [[accent colorWithAlphaComponent:0.90f] setFill];
        NSRectFill(NSMakeRect(NSMaxX(inner)-sz.width-9.0f, NSMaxY(inner)-9.5f, 3.0f, 6.5f));
        [tlabel drawAtPoint:NSMakePoint(NSMaxX(inner)-sz.width-4.0f, NSMaxY(inner)-10.0f) withAttributes:tabAttrs];
        // Bespoke per-tab glyph just left of the accent tick.
        const NSRect gbox=NSMakeRect(NSMaxX(inner)-sz.width-20.0f, NSMaxY(inner)-12.0f, 9.0f, 9.0f);
        ArpSIDDrawTabGlyph(_currentTab, gbox, [accent colorWithAlphaComponent:0.95f]);
    }
}
@end


@interface ArpSIDPianoView : NSView
@property (nonatomic, copy) void(^noteOn)(int midiNote);
@property (nonatomic, copy) void(^noteOff)(int midiNote);
@property (nonatomic, assign) NSInteger octaveOffset;
-(void)cancelHeldNote;
@end
@implementation ArpSIDPianoView{
    int _heldRawNote;
    int _heldFinalNote;
    int _lastRawNote;
    int _highlightFinalNote;
    NSInteger _octaveOffset;
    NSTrackingArea* _exitTrackingArea;
}
// v963 accessibility: announce the piano to assistive tech (previously invisible).
-(BOOL)isAccessibilityElement{return YES;}
-(NSAccessibilityRole)accessibilityRole{return NSAccessibilityGroupRole;}
-(NSString*)accessibilityLabel{return @"Piano keyboard. Click keys to play; drag to glide. Command-Up and Command-Down shift the octave.";}
static const int kPianoBase = 48;  // C3
static const int kPianoKeyCount = 25;
static const int kPianoWhiteCount = 15;
static const CGFloat kPianoBlackKeyWidth = 0.62f;
static const CGFloat kPianoBlackKeyHeight = 0.62f;
static const CGFloat kPianoBlackKeyRearPlacement = 0.38f;
static const BOOL kIsBlack[12]={NO,YES,NO,YES,NO,NO,YES,NO,YES,NO,YES,NO};
-(instancetype)initWithFrame:(NSRect)r{
    self=[super initWithFrame:r];
    if(self){
        _heldRawNote=-1;
        _heldFinalNote=-1;
        _lastRawNote=-1;
        _highlightFinalNote=-1;
        _octaveOffset=0;
    }
    return self;
}
-(BOOL)resignFirstResponder{
    [self _releaseHeldNote];
    _highlightFinalNote=-1;
    [self setNeedsDisplay:YES];
    return [super resignFirstResponder];
}
-(BOOL)acceptsFirstResponder{return YES;}
-(void)viewDidMoveToWindow{
    [super viewDidMoveToWindow];
    NSNotificationCenter* nc=[NSNotificationCenter defaultCenter];
    [nc removeObserver:self name:NSWindowDidResignKeyNotification object:nil];
    [nc removeObserver:self name:NSWindowWillCloseNotification object:nil];
    [nc removeObserver:self name:NSApplicationDidResignActiveNotification object:nil];
    if(self.window){
        [nc addObserver:self selector:@selector(_pianoLifecycleRelease:)
                   name:NSWindowDidResignKeyNotification object:self.window];
        [nc addObserver:self selector:@selector(_pianoLifecycleRelease:)
                   name:NSWindowWillCloseNotification object:self.window];
        [nc addObserver:self selector:@selector(_pianoLifecycleRelease:)
                   name:NSApplicationDidResignActiveNotification object:NSApp];
    } else {
        [self _releaseHeldNote];
    }
}
-(void)viewWillMoveToWindow:(NSWindow*)newWindow{
    if(!newWindow) [self _releaseHeldNote];
    [super viewWillMoveToWindow:newWindow];
}
-(void)updateTrackingAreas{
    [super updateTrackingAreas];
    if(_exitTrackingArea) [self removeTrackingArea:_exitTrackingArea];
    _exitTrackingArea=[[NSTrackingArea alloc]
        initWithRect:NSZeroRect
             options:NSTrackingMouseEnteredAndExited|NSTrackingActiveAlways|NSTrackingInVisibleRect
               owner:self
            userInfo:nil];
    [self addTrackingArea:_exitTrackingArea];
}
-(void)_pianoLifecycleRelease:(NSNotification*)note{
    (void)note;
    [self cancelHeldNote];
}
-(void)mouseExited:(NSEvent*)event{
    (void)event;
    // A pointer leaving the transformed/scaled footer is an explicit release
    // boundary. This prevents a lost mouse-up outside the host view from
    // leaving a physical SID gate high.
    [self cancelHeldNote];
}
-(void)cancelOperation:(id)sender{
    (void)sender;
    [self cancelHeldNote];
}
-(void)dealloc{
    [[NSNotificationCenter defaultCenter] removeObserver:self];
}
-(void)setOctaveOffset:(NSInteger)octaveOffset{
    const NSInteger clamped=std::clamp((int)octaveOffset,-2,2);
    if(_octaveOffset==clamped) return;
    [self _releaseHeldNote];
    _octaveOffset=clamped;
    [self setNeedsDisplay:YES];
}
-(void)setHighlightNote:(int)n{
    if(_highlightFinalNote==n) return;
    _highlightFinalNote=n;
    [self setNeedsDisplay:YES];
}
-(int)_whiteCountBeforeKeyIndex:(int)keyIndex{
    int count=0;
    for(int i=0;i<keyIndex && i<kPianoKeyCount;++i) if(!kIsBlack[i%12]) ++count;
    return count;
}
-(int)_whiteSlotForRawNote:(int)rawNote{
    const int keyIndex=rawNote-kPianoBase;
    if(keyIndex<0 || keyIndex>=kPianoKeyCount || kIsBlack[keyIndex%12]) return -1;
    return [self _whiteCountBeforeKeyIndex:keyIndex];
}
-(NSRect)_whiteRectForRawNote:(int)rawNote{
    const NSRect b=self.bounds;
    const int whiteSlot=[self _whiteSlotForRawNote:rawNote];
    if(whiteSlot<0) return NSZeroRect;
    const CGFloat ww=(kPianoWhiteCount>0) ? (b.size.width/(CGFloat)kPianoWhiteCount) : b.size.width;
    return NSMakeRect(whiteSlot*ww,0.0f,ww-1.0f,b.size.height);
}
-(NSRect)_blackRectForRawNote:(int)rawNote{
    const int keyIndex=rawNote-kPianoBase;
    if(keyIndex<0 || keyIndex>=kPianoKeyCount || !kIsBlack[keyIndex%12]) return NSZeroRect;
    const NSRect b=self.bounds;
    const CGFloat ww=(kPianoWhiteCount>0) ? (b.size.width/(CGFloat)kPianoWhiteCount) : b.size.width;
    const int whitesBefore=[self _whiteCountBeforeKeyIndex:keyIndex];
    const CGFloat width=ww*kPianoBlackKeyWidth;
    const CGFloat height=b.size.height*kPianoBlackKeyHeight;
    const CGFloat x=(whitesBefore*ww) - width*0.5f;
    const CGFloat y=b.size.height*kPianoBlackKeyRearPlacement;
    return NSMakeRect(x,y,width,height);
}
-(int)_finalMidiForRawNote:(int)rawNote{
    return std::clamp(rawNote + (int)_octaveOffset*12, 0, 127);
}
-(int)_rawHighlightNote{
    if(_highlightFinalNote < 0) return -1;
    const int raw=_highlightFinalNote - (int)_octaveOffset*12;
    if(raw < kPianoBase || raw >= (kPianoBase + kPianoKeyCount)) return -1;
    return raw;
}
-(void)_releaseHeldNote{
    if(_heldFinalNote>=0 && self.noteOff) self.noteOff(_heldFinalNote);
    _heldRawNote=-1;
    _heldFinalNote=-1;
    _lastRawNote=-1;
}
-(void)cancelHeldNote{
    [self _releaseHeldNote];
    [self setNeedsDisplay:YES];
}
-(void)_engageRawNote:(int)rawNote{
    if(rawNote < kPianoBase || rawNote >= (kPianoBase + kPianoKeyCount)) return;
    const int finalNote=[self _finalMidiForRawNote:rawNote];
    if(_heldFinalNote==finalNote){
        _heldRawNote=rawNote;
        _lastRawNote=rawNote;
        [self setNeedsDisplay:YES];
        return;
    }
    if(_heldFinalNote>=0 && _heldFinalNote!=finalNote) [self _releaseHeldNote];
    _heldRawNote=rawNote;
    _heldFinalNote=finalNote;
    _lastRawNote=rawNote;
    [self setNeedsDisplay:YES];
    if(self.noteOn) self.noteOn(finalNote);
}
-(int)_noteAtPoint:(NSPoint)pt{
    for(int keyIndex=0;keyIndex<kPianoKeyCount;++keyIndex){
        if(!kIsBlack[keyIndex%12]) continue;
        const int rawNote=kPianoBase+keyIndex;
        if(NSPointInRect(pt,[self _blackRectForRawNote:rawNote])) return rawNote;
    }
    for(int keyIndex=0;keyIndex<kPianoKeyCount;++keyIndex){
        if(kIsBlack[keyIndex%12]) continue;
        const int rawNote=kPianoBase+keyIndex;
        if(NSPointInRect(pt,[self _whiteRectForRawNote:rawNote])) return rawNote;
    }
    return -1;}
-(void)drawRect:(NSRect)dirty{(void)dirty;
    NSRect b=self.bounds;
    const int highlightRaw=[self _rawHighlightNote];
    [[ArpSIDRGB(0.12,0.09,0.20,0.82) colorWithAlphaComponent:.88f] setFill];
    NSRectFill(b);
    [[c64Red() colorWithAlphaComponent:.88f] setFill];
    NSRectFill(NSMakeRect(b.origin.x, b.origin.y + b.size.height*(kPianoBlackKeyRearPlacement-0.05f), b.size.width, 2.0f));
    // Draw white keys
    for(int keyIndex=0;keyIndex<kPianoKeyCount;++keyIndex){
        if(kIsBlack[keyIndex%12]) continue;
        const int note=kPianoBase+keyIndex;
        const NSRect kr=[self _whiteRectForRawNote:note];
        const BOOL pressed=(note==_heldRawNote);
        const BOOL lit=(note==highlightRaw);
        NSColor*fill=pressed?c64LtGreen():(lit?[c64LtGreen() colorWithAlphaComponent:.4f]:
            [NSColor colorWithSRGBRed:.9f green:.88f blue:.82f alpha:1]);
        [fill setFill];[[NSBezierPath bezierPathWithRoundedRect:kr xRadius:1 yRadius:1] fill];
        [[colBorder() colorWithAlphaComponent:.5f] setStroke];
        [[NSBezierPath bezierPathWithRoundedRect:kr xRadius:1 yRadius:1] stroke];
        // C note label
        if(keyIndex%12==0){NSDictionary*la=@{NSForegroundColorAttributeName:colOscBg(),
            NSFontAttributeName:monoF(6.f)};
            NSString*ln=[NSString stringWithFormat:@"C%d",note/12-1];
            [ln drawAtPoint:NSMakePoint(NSMinX(kr)+2.0f,3.0f) withAttributes:la];}
    }
    // Draw black keys on top
    for(int keyIndex=0;keyIndex<kPianoKeyCount;++keyIndex){
        if(!kIsBlack[keyIndex%12]) continue;
        const int note=kPianoBase+keyIndex;
        const NSRect kr=[self _blackRectForRawNote:note];
        const BOOL pressed=(note==_heldRawNote);
        const BOOL lit=(note==highlightRaw);
        NSColor*fill=pressed?c64LtGreen():(lit?[c64LtGreen() colorWithAlphaComponent:.5f]:colOscBg());
        [fill setFill];[[NSBezierPath bezierPathWithRoundedRect:kr xRadius:1 yRadius:1] fill];
        [[colBorder() colorWithAlphaComponent:.6f] setStroke];
        [[NSBezierPath bezierPathWithRoundedRect:kr xRadius:1 yRadius:1] stroke];
    }
}
-(void)mouseDown:(NSEvent*)e{
    [self.window makeFirstResponder:self];
    NSPoint pt=[self convertPoint:e.locationInWindow fromView:nil];
    const int rawNote=[self _noteAtPoint:pt];
    if(rawNote>=0) [self _engageRawNote:rawNote];
    else [self _releaseHeldNote];
    [self setNeedsDisplay:YES];
}
-(void)mouseDragged:(NSEvent*)e{
    NSPoint pt=[self convertPoint:e.locationInWindow fromView:nil];
    const int rawNote=[self _noteAtPoint:pt];
    if(rawNote==_lastRawNote) return;
    if(rawNote<0){
        [self _releaseHeldNote];
        [self setNeedsDisplay:YES];
        return;
    }
    [self _engageRawNote:rawNote];
}
-(void)mouseUp:(NSEvent*)e{(void)e;
    [self cancelHeldNote];
}
@end


// Dedicated vector branding for the two drum products. Drawing this in AppKit
// keeps the artwork crisp at every host scale and avoids stale bitmap assets.
@interface ArpSIDDrumBrandView : NSView
@property(nonatomic) NSInteger brandKind; // 0 = DrSID, 1 = SID-808
@end
@implementation ArpSIDDrumBrandView
-(BOOL)isOpaque{return NO;}
-(void)setBrandKind:(NSInteger)brandKind{
    NSInteger clean=(brandKind==1)?1:0;
    if(_brandKind==clean) return;
    _brandKind=clean;
    [self setNeedsDisplay:YES];
}
-(void)drawRect:(NSRect)dirty{
    (void)dirty;
    NSRect b=NSInsetRect(self.bounds,1.0,1.0);
    const BOOL is808=(self.brandKind==1);
    NSColor* accent=is808?c64Orange():c64Cyan();
    NSColor* accent2=is808?c64Red():c64LtGreen();
    NSBezierPath* shell=[NSBezierPath bezierPathWithRoundedRect:b xRadius:8 yRadius:8];
    NSGradient* bg=[[NSGradient alloc] initWithColors:@[
        [colPanelDeep() colorWithAlphaComponent:.98f],
        [accent colorWithAlphaComponent:.20f],
        [c64Black() colorWithAlphaComponent:.96f]]];
    [bg drawInBezierPath:shell angle:0.0];
    [[accent colorWithAlphaComponent:.78f] setStroke];
    shell.lineWidth=1.4f;
    [shell stroke];

    const CGFloat railY=NSMinY(b)+7.0f;
    for(int i=0;i<8;++i){
        const CGFloat x=NSMinX(b)+10.0f+(CGFloat)i*13.0f;
        NSColor* c=(i&1)?accent2:accent;
        [c setFill];
        [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(x,railY,5.0f,5.0f)] fill];
    }
    if(is808){
        [[accent colorWithAlphaComponent:.24f] setFill];
        for(int i=0;i<8;++i){
            const CGFloat x=NSMaxX(b)-126.0f+(CGFloat)i*14.0f;
            NSRect step=NSMakeRect(x,NSMinY(b)+18.0f,10.0f,9.0f+(i%3)*3.0f);
            [[NSBezierPath bezierPathWithRoundedRect:step xRadius:2 yRadius:2] fill];
        }
    } else {
        [[accent colorWithAlphaComponent:.22f] setStroke];
        NSBezierPath* wave=[NSBezierPath bezierPath];
        for(int i=0;i<28;++i){
            const CGFloat x=NSMaxX(b)-180.0f+(CGFloat)i*6.0f;
            const CGFloat y=NSMidY(b)-8.0f+std::sin((CGFloat)i*.82f)*7.0f;
            if(i==0)[wave moveToPoint:NSMakePoint(x,y)];else[wave lineToPoint:NSMakePoint(x,y)];
        }
        wave.lineWidth=1.5f;
        [wave stroke];
    }

    NSString* title=is808?@"SID•808":@"DrSID";
    NSString* sub=is808?@"ANALOG X0X-8 / SID DRUM MACHINE":@"REGISTER-WAVETABLE SID DRUM CORE";
    NSDictionary* titleAttrs=@{
        NSForegroundColorAttributeName:is808?c64Orange():c64White(),
        NSFontAttributeName:monoBF(is808?25.0f:27.0f),
        NSKernAttributeName:@(-1.0f)
    };
    NSDictionary* subAttrs=@{
        NSForegroundColorAttributeName:[accent2 colorWithAlphaComponent:.92f],
        NSFontAttributeName:monoBF(8.2f)
    };
    [title drawAtPoint:NSMakePoint(NSMinX(b)+14.0f,NSMaxY(b)-35.0f) withAttributes:titleAttrs];
    [sub drawAtPoint:NSMakePoint(NSMinX(b)+15.0f,NSMinY(b)+9.0f) withAttributes:subAttrs];
}
@end






// MTKView-backed SIDCORE backdrop using CoreAnimation sublayers above CAMetalLayer.
// The audio thread never touches Metal/UI: all GPU work is driven by MTKViewDelegate.
@interface ArpSIDSidCoreMetalBackdropView : MTKView <MTKViewDelegate> {
@private
    ArpSIDTelemetry _telemetry;
    float _forensicActivity;
    float _forensicIntensity;
    BOOL _forensicEnabled;
    BOOL _layersBuilt;
    BOOL _hasMetalDevice;
    BOOL _tearingDown;
    BOOL _vsyncPayloadDirty;
    BOOL _vsyncDriven;
    id<MTLCommandQueue> _commandQueue;
    id<MTLLibrary> _shaderLibrary;
    id<MTLRenderPipelineState> _pipelineState;
    id<MTLBuffer> _uniformBuffers[3];
    uint32_t _uniformWriteIndex;
    NSInteger _surfaceKind; // 0=SIDCORE, 1=C64 SID-bus
    NSTimeInterval _lastSidCoreRedrawTime;
    NSTimeInterval _lastSidCoreVsyncTime;
    uint64_t _sidCoreVsyncFrameCounter;
    // Idle visualizer fix: the SID-core Metal shader animates off a continuously
    // advancing time (wall-clock `now`) and frame counter. To stop it drifting
    // when there is no SID/audio activity, drive the shader animation from these
    // ACTIVITY-GATED accumulators instead — they only advance while the surface is
    // actually doing something (audible voices, gates, bus traffic, forensic mode).
    NSTimeInterval _sidCoreAnimTime;     // accumulated only while active
    uint64_t       _sidCoreAnimFrame;    // frame pulses only while active
    // Idle-redraw fix (v822): the shader's only non-telemetry input is the
    // activity-gated animation clock above. When it is frozen AND no telemetry/
    // forensic change has armed a wake, every presented frame is identical — count
    // those frozen frames and self-pause the MTKView so it stops re-rendering
    // identical pixels at vsync. _lastTelemetrySnapshot suppresses the per-poll
    // re-arm when the incoming telemetry has not actually changed.
    uint32_t       _sidCoreStaticFrames;
    ArpSIDTelemetry _lastTelemetrySnapshot;
    BOOL           _hasLastTelemetrySnapshot;
    CAShapeLayer* _gridLayer;
    CAShapeLayer* _voiceLayer[3];
    CAShapeLayer* _gateLayer[3];
    CAShapeLayer* _openBusLayer;
    CATextLayer* _legendLayer;
}
- (void)updateWithTelemetry:(const ArpSIDTelemetry&)telemetry;
- (void)setForensicActivity:(float)activity intensity:(float)intensity enabled:(BOOL)enabled;
- (void)configureAsC64SidBusSurface;
- (void)prepareForTeardown;
- (void)resumeAfterHostAttach;
- (void)_ensureLayers;
- (BOOL)_sidCoreIsActuallyVisibleForVsync;
- (void)_sidCoreMarkPayloadDirtyAndArmVsync;
- (void)_buildShaderPipelineIfPossibleWithDevice:(id<MTLDevice>)device;
@end

static inline CGColorRef ArpSIDCreateCGColor(CGFloat r, CGFloat g, CGFloat b, CGFloat a) {
    return CGColorCreateGenericRGB(ArpSIDUIFiniteCGFloat(r), ArpSIDUIFiniteCGFloat(g), ArpSIDUIFiniteCGFloat(b), ArpSIDUIFiniteCGFloat(a, 1.0));
}
static inline void ArpSIDAssignLayerColor(CAShapeLayer* layer, CGFloat r, CGFloat g, CGFloat b, CGFloat a) {
    if (!layer) return;
    CGColorRef c = ArpSIDCreateCGColor(r,g,b,a);
    layer.strokeColor = c;
    CGColorRelease(c);
}
static inline void ArpSIDAssignLayerFill(CALayer* layer, CGFloat r, CGFloat g, CGFloat b, CGFloat a) {
    if (!layer) return;
    CGColorRef c = ArpSIDCreateCGColor(r,g,b,a);
    layer.backgroundColor = c;
    CGColorRelease(c);
}
static inline void ArpSIDDisableImplicitLayerActions(CALayer* layer) {
    if (!layer) return;
    layer.actions = @{ @"path": [NSNull null], @"position": [NSNull null], @"bounds": [NSNull null], @"frame": [NSNull null], @"opacity": [NSNull null], @"backgroundColor": [NSNull null], @"strokeColor": [NSNull null], @"fillColor": [NSNull null], @"shadowOpacity": [NSNull null], @"shadowRadius": [NSNull null] };
}
static CGPathRef ArpSIDCreateSidCoreGridPath(CGRect b) {
    b = ArpSIDUIFinitePositiveBounds(b);
    CGMutablePathRef path = CGPathCreateMutable();
    const CGFloat w = b.size.width;
    const CGFloat h = b.size.height;
    for (int gy = 0; gy < 8; ++gy) {
        const CGFloat y = floor(h * (CGFloat)gy / 7.0) + 0.5;
        CGPathMoveToPoint(path, nullptr, 0.0, y);
        CGPathAddLineToPoint(path, nullptr, w, y);
    }
    for (int gx = 0; gx < 16; ++gx) {
        const CGFloat x = floor(w * (CGFloat)gx / 15.0) + 0.5;
        CGPathMoveToPoint(path, nullptr, x, 0.0);
        CGPathAddLineToPoint(path, nullptr, x, h);
    }
    return path;
}
static CGPathRef ArpSIDCreateSidCoreWavePath(CGRect b, const float* samples, int voice, float peak) {
    b = ArpSIDUIFinitePositiveBounds(b);
    CGMutablePathRef path = CGPathCreateMutable();
    const CGFloat w = b.size.width;
    const CGFloat h = b.size.height;
    voice = std::clamp(voice, 0, 2);
    const CGFloat yBase = h * (0.22 + 0.28 * (2 - voice));
    const CGFloat amp = h * (0.105 + ArpSIDUIClamp01(peak) * 0.035);
    for (int i = 0; i < 256; ++i) {
        const CGFloat x = (CGFloat)i / 255.0 * w;
        const float raw = samples ? samples[i] : 0.0f;
        const float sample = std::isfinite(raw) ? std::clamp(raw, -1.2f, 1.2f) : 0.0f;
        const CGFloat y = yBase + (CGFloat)sample * amp;
        if (i == 0) CGPathMoveToPoint(path, nullptr, x, y);
        else CGPathAddLineToPoint(path, nullptr, x, y);
    }
    return path;
}
static CGPathRef ArpSIDCreateSidCoreGatePath(CGRect b, const uint8_t* regs, int voice) {
    b = ArpSIDUIFinitePositiveBounds(b);
    CGMutablePathRef path = CGPathCreateMutable();
    const CGFloat w = b.size.width;
    const CGFloat h = b.size.height;
    voice = std::clamp(voice, 0, 2);
    const int ctrlIndex = voice == 0 ? 4 : (voice == 1 ? 11 : 18);
    const BOOL gate = regs ? ((regs[ctrlIndex] & 0x01u) != 0) : NO;
    const CGFloat y = h * (0.13 + 0.28 * (2 - voice));
    const CGFloat barW = gate ? w * 0.92 : w * 0.28;
    const CGFloat x0 = w * 0.04;
    CGPathAddRoundedRect(path, nullptr, CGRectMake(x0, y, barW, 4.0), 2.0, 2.0);
    return path;
}
static CGPathRef ArpSIDCreateSidCoreOpenBusPath(CGRect b,
                                                uint8_t openBus,
                                                uint8_t lastRead,
                                                uint8_t lastSidReg,
                                                uint8_t lastSidValue,
                                                const float* openScope,
                                                const float* sidScope,
                                                uint32_t scopeWritePos,
                                                int scopeCount,
                                                float forensic) {
    b = ArpSIDUIFinitePositiveBounds(b);
    forensic = ArpSIDUIClamp01(forensic);
    CGMutablePathRef path = CGPathCreateMutable();
    const CGFloat w = b.size.width;
    const CGFloat h = b.size.height;
    scopeCount = std::clamp(scopeCount, 0, 128);
    if (openScope && sidScope && scopeCount > 2) {
        const uint32_t mask = (scopeCount == 128) ? 127u : 0u;
        for (int lane = 0; lane < 2; ++lane) {
            const float* src = lane == 0 ? openScope : sidScope;
            const CGFloat baseY = h * (lane == 0 ? 0.78 : 0.66);
            const CGFloat amp = h * (0.045 + forensic * 0.030);
            for (int i = 0; i < scopeCount; ++i) {
                const uint32_t idx = mask ? ((scopeWritePos + (uint32_t)i) & mask)
                                          : (uint32_t)std::min(i, scopeCount - 1);
                const CGFloat x = w * (0.04 + 0.92 * ((CGFloat)i / (CGFloat)std::max(1, scopeCount - 1)));
                const CGFloat y = baseY - amp * (CGFloat)std::clamp(src[idx], -1.0f, 1.0f);
                if (i == 0) CGPathMoveToPoint(path, nullptr, x, y);
                else CGPathAddLineToPoint(path, nullptr, x, y);
                if ((i & 15) == 0) {
                    const CGFloat dot = 2.0 + forensic * 2.0;
                    CGPathAddEllipseInRect(path, nullptr, CGRectMake(x - dot * 0.5, y - dot * 0.5, dot, dot));
                }
            }
        }
    }
    // Bottom bit-row: improved to be a FAITHFUL open-bus readout instead of a
    // decorative hash. The lower row shows the actual 8 open-bus bits (bit 0 at
    // left), so a lit dot == that bus line is high; the thin upper row shows the
    // last-read byte's bits for comparison (open bus vs. what the CPU latched).
    // Lit-dot size is modulated by the last SID value so active traffic reads as
    // brighter/larger without losing the bit-accurate meaning.
    const CGFloat valGain = 0.5f + 0.5f * ((CGFloat)lastSidValue / 255.0);
    for (int bit = 0; bit < 8; ++bit) {
        const CGFloat x = w * (0.08 + 0.105 * bit);
        // Open-bus bit (primary row) — the real D-line state, not a hash.
        const BOOL busOn = ((openBus >> bit) & 1u) != 0;
        const CGFloat busY = h * (0.88 + (busOn ? 0.045 : -0.012) + forensic * 0.018 * ((bit & 1) ? 1 : -1));
        const CGFloat busDot = busOn ? (5.5 + 3.0 * valGain) : 4.0;
        CGPathAddEllipseInRect(path, nullptr, CGRectMake(x, busY, busDot, busDot));
        // Last-read bit (secondary thin row, slightly above) for open-bus vs. latched contrast.
        const BOOL rdOn = ((lastRead >> bit) & 1u) != 0;
        const CGFloat rdY = h * (0.985);
        const CGFloat rdDot = rdOn ? 3.0 : 1.6;
        CGPathAddEllipseInRect(path, nullptr, CGRectMake(x + 1.0, rdY, rdDot, rdDot));
    }
    (void)lastSidReg;
    return path;
}

static NSString* ArpSIDMatrixBarString(float value, BOOL gateOn) {
    value = ArpSIDUIClamp01(value);
    const int lit = std::clamp((int)lrintf(value * 16.0f), 0, 16);
    NSMutableString* out = [NSMutableString stringWithCapacity:24];
    for (int i = 0; i < 16; ++i) [out appendString:(i < lit ? @"█" : @"·")];
    [out appendString:(gateOn ? @" G" : @" -")];
    return out;
}
static NSString* ArpSIDDisasmLineString(NSString* prefix, uint16_t pc, const char* line, BOOL current) {
    NSString* body = (line && line[0]) ? [NSString stringWithUTF8String:line] : @"---";
    return [NSString stringWithFormat:@"%@ %@%04X  %@", prefix ? prefix : @"", current ? @"▶" : @" ", (unsigned)pc, body];
}


static NSString* const kArpSIDSidCoreMetalShaderSourceV385 = @"#include <metal_stdlib>\n"
@"using namespace metal;\n"
@"struct VSOut { float4 pos [[position]]; float2 uv; };\n"
@"struct SidCoreUniforms { float time; float peak; float forensic; float gates; float openBus; float sidReg; float sidValue; float surfaceKind; float env0; float env1; float env2; float framePulse; float hue; float busHeat; float voiceSpread; float rainbow; float pcLo; float rasterPhase; float irqHeat; float scopeEnergy; float latencyPulse; float lowLatencyMode; float blackBus; float gpuBoost; float loaderFlicker; float backscreenFlicker; float gpuLatencyFrame; float cyclePhase; float meshDensity; float loaderMode; float colourCycle; float crtCurve; float busDepth; float sparkle; float dmaBurst; float badline; float loaderBorderPhase; float databusGhost; float phosphorPersistence; float chipHeat; float busDecayMask; float spriteDma; float vicBeamX; };\n"
@"vertex VSOut sidcore_vtx(uint vid [[vertex_id]]) {\n"
@"    float2 p[4] = { float2(-1.0,-1.0), float2(1.0,-1.0), float2(-1.0,1.0), float2(1.0,1.0) };\n"
@"    VSOut o; o.pos = float4(p[vid], 0.0, 1.0); o.uv = p[vid] * 0.5 + 0.5; return o;\n"
@"}\n"
@"static float3 hsv2rgb(float3 c) {\n"
@"    float3 p = abs(fract(c.xxx + float3(0.0, 2.0/3.0, 1.0/3.0)) * 6.0 - 3.0);\n"
@"    return c.z * mix(float3(1.0), saturate(p - 1.0), c.y);\n"
@"}\n"
@"static float lineField(float2 uv, float y, float width, float energy) {\n"
@"    return smoothstep(width, 0.0, abs(uv.y - y)) * (0.12 + energy * 0.88);\n"
@"}\n"
@"static float matrixRain(float2 uv, float t, float seed, float energy) {\n"
@"    float col = floor(uv.x * 44.0);\n"
@"    float lane = fract(sin(col * 12.9898 + seed * 78.233) * 43758.5453);\n"
@"    float head = fract(t * (0.08 + 0.32 * lane + 0.22 * energy) + lane);\n"
@"    float d = abs(fract(uv.y + head) - 0.5);\n"
@"    float glyph = step(fract(uv.y * 42.0 + lane * 17.0), 0.38 + 0.32 * energy);\n"
@"    float stripe = smoothstep(0.52, 0.02, d) * glyph;\n"
@"    float bit = fmod(floor(seed / pow(2.0, fmod(col, 8.0))), 2.0);\n"
@"    return stripe * (0.05 + bit * 0.18 + energy * 0.18);\n"
@"}\n"
@"static float phosphorTriad(float2 uv, float t, float energy) {\n"
@"    float tri = abs(fract((uv.x + uv.y*0.15 + t*0.006) * 96.0) - 0.5);\n"
@"    return smoothstep(0.50, 0.05, tri) * (0.018 + energy * 0.075);\n"
@"}\n"
@"static float cpuTrace(float2 uv, float pcLo, float rasterPhase, float irqHeat) {\n"
@"    float scanY = fract(pcLo * 0.0039215686 + rasterPhase * 0.37);\n"
@"    float pcBeam = smoothstep(0.018, 0.0, abs(uv.y - scanY));\n"
@"    float rasterBeam = smoothstep(0.012, 0.0, abs(uv.x - fract(rasterPhase + uv.y*0.21)));\n"
@"    return pcBeam * (0.12 + irqHeat*0.32) + rasterBeam * (0.05 + irqHeat*0.18);\n"
@"}\n"
@"static float busBitLane(float2 uv, float byteValue) {\n"
@"    float v = 0.0;\n"
@"    for (int i=0;i<8;i++) {\n"
@"        float x = (float(i)+0.5)/8.0;\n"
@"        float bit = fmod(floor(byteValue / pow(2.0, float(i))), 2.0);\n"
@"        v += smoothstep(0.022,0.0,abs(uv.x-x)) * (0.018 + bit*0.14);\n"
@"    }\n"
@"    return v;\n"
@"}\n"
@"static float tessellatedMesh(float2 uv, float t, float density, float heat, float depth) {\n"
@"    float2 centered = uv - 0.5;\n"
@"    float warp = sin(centered.x*11.0 + t*0.42) * cos(centered.y*13.0 - t*0.37);\n"
@"    float2 p = uv + centered * warp * (0.015 + depth*0.045);\n"
@"    float d = max(12.0, density);\n"
@"    float gx = abs(fract(p.x*d)-0.5);\n"
@"    float gy = abs(fract(p.y*d*0.62)-0.5);\n"
@"    float grid = smoothstep(0.030, 0.0, min(gx,gy));\n"
@"    float diag = smoothstep(0.020, 0.0, abs(fract((p.x+p.y+warp*0.05)*d*0.36)-0.5));\n"
@"    float horizon = pow(saturate(1.0 - abs(centered.y)*1.85), 2.0);\n"
@"    return (grid*0.85 + diag*0.35) * (0.025 + heat*0.11 + depth*0.07) * (0.35 + horizon);\n"
@"}\n"
@"static float c64LoaderScreen(float2 uv, float t, float mode, float openBus, float sidValue, float sparkle) {\n"
@"    float2 cell = floor(uv * float2(40.0, 25.0));\n"
@"    float rnd = fract(sin(dot(cell + floor(t*18.0), float2(12.9898,78.233))) * 43758.5453);\n"
@"    float charBox = step(fract(uv.x*40.0),0.82) * step(fract(uv.y*25.0),0.78);\n"
@"    float borderX = smoothstep(0.060,0.0,min(uv.x,1.0-uv.x));\n"
@"    float borderY = smoothstep(0.080,0.0,min(uv.y,1.0-uv.y));\n"
@"    float border = max(borderX,borderY);\n"
@"    float bars = smoothstep(0.018,0.0,abs(fract(uv.y*12.5 + t*0.22 + openBus*0.0039)-0.5));\n"
@"    float flash = smoothstep(0.92,1.0,sin(t*9.0 + sidValue*0.05)*0.5+0.5);\n"
@"    return mode * (charBox*rnd*(0.030+sparkle*0.075) + border*(0.08+flash*0.18) + bars*(0.020+sparkle*0.060));\n"
@"}\n"
@"static float c64LoaderBorder(float2 uv, float phase, float heat) {\n"
@"    float edge = max(smoothstep(0.070,0.0,min(uv.x,1.0-uv.x)), smoothstep(0.085,0.0,min(uv.y,1.0-uv.y)));\n"
@"    float band = smoothstep(0.018,0.0,abs(fract((uv.x+uv.y)*14.0 + phase)-0.5));\n"
@"    return edge * (0.10 + heat*0.22) + band * edge * (0.04 + heat*0.16);\n"
@"}\n"
@"static float databusGhost(float2 uv, float t, float byteValue, float ghost) {\n"
@"    float v = 0.0;\n"
@"    for (int i=0;i<8;i++) { float bit=fmod(floor(byteValue/pow(2.0,float(i))),2.0); float y=(float(i)+0.5)/8.0; v += smoothstep(0.020,0.0,abs(uv.y-y-fract(t*0.015+float(i)*0.071)*0.035))*bit; }\n"
@"    return v * (0.035 + ghost*0.18);\n"
@"}\n"
@"static float3 vicRasterBeam(float2 uv, float rasterPhase, float beamX, float sprite, float persistence) {\n"
@"    float ry = 1.0 - rasterPhase;\n"                                        // VIC line 0 at the top
@"    float line = smoothstep(0.008, 0.0, abs(uv.y - ry));\n"                 // live scanline
@"    float trail = smoothstep(0.20, 0.0, clamp(uv.y - ry, 0.0, 1.0));\n"     // phosphor persistence above the beam (just scanned)
@"    float spot = smoothstep(0.026, 0.0, distance(uv, float2(beamX, ry)));\n"// flying spot at the current VIC cycle
@"    float3 beamCol = float3(0.42, 1.0, 0.68);\n"
@"    return beamCol * line * (0.16 + persistence*0.14)\n"
@"         + beamCol * trail * (0.04 + persistence*0.06)\n"
@"         + float3(1.0, 1.0, 0.86) * spot * (0.40 + sprite*0.60);\n"
@"}\n"
@"static float3 openBusDecayLanes(float2 uv, float byteValue, float decayMask) {\n"
@"    if (uv.y > 0.13) return float3(0.0);\n"                                 // bottom status strip only
@"    float3 acc = float3(0.0);\n"
@"    for (int i=0;i<8;i++) {\n"
@"        float x = (float(i)+0.5)/8.0;\n"
@"        float bit     = fmod(floor(byteValue/pow(2.0,float(i))),2.0);\n"    // open-bus bit value
@"        float charged = fmod(floor(decayMask/pow(2.0,float(i))),2.0);\n"    // still driven vs DRAM-leaked
@"        float lane = smoothstep(0.016,0.0,abs(uv.x-x)) * smoothstep(0.13,0.0,uv.y);\n"
@"        acc += lane * bit * mix(float3(0.52,0.28,0.03), float3(0.07,1.0,0.30), charged);\n"
@"    }\n"
@"    return acc * 0.90;\n"
@"}\n"
@"fragment float4 sidcore_frag(VSOut in [[stage_in]], constant SidCoreUniforms& u [[buffer(0)]]) {\n"
@"    float2 uv = in.uv;\n"
@"    float t = u.time;\n"
@"    float3 env = saturate(float3(u.env0, u.env1, u.env2));\n"
@"    float envSum = saturate((env.x + env.y + env.z) * 0.3333333);\n"
@"    float envMax = max(env.x, max(env.y, env.z));\n"
@"    float busPhase = u.openBus * 0.0245436926 + u.sidReg * 0.049087385 + u.sidValue * 0.012271846 + u.framePulse * 0.00009;\n"
@"    float busMode = step(0.5, u.surfaceKind);\n"
@"    float busHeat = saturate(u.busHeat);\n"
@"    float mesh = tessellatedMesh(uv, t, u.meshDensity, saturate(busHeat + envMax*0.35 + u.scopeEnergy*0.25), saturate(u.busDepth));\n"
@"    float loaderScreen = c64LoaderScreen(uv, t, saturate(u.loaderMode), u.openBus, u.sidValue, saturate(u.sparkle));\n"
@"    float loaderBorder = c64LoaderBorder(uv, u.loaderBorderPhase, saturate(u.busHeat + u.dmaBurst + u.badline));\n"
@"    float busGhost = databusGhost(uv, t, u.sidValue + u.openBus, saturate(u.databusGhost));\n"
@"    float forensic = saturate(u.forensic);\n"
@"    float rainbow = saturate(u.rainbow);\n"
@"    float matrix = matrixRain(uv, t, u.openBus + u.sidValue + u.pcLo + 1.0, saturate(envSum + busHeat + u.scopeEnergy*0.35));\n"
@"    float fineGrid = (step(fract(uv.x*64.0), 0.006) + step(fract(uv.y*32.0), 0.010)) * (0.012 + u.peak * 0.028);\n"
@"    float mainGrid = (step(fract(uv.x*8.0), 0.020) + step(fract(uv.y*6.0), 0.026)) * (0.040 + forensic * 0.050);\n"
@"    float zWarp = sin((uv.x - 0.5) * 13.0 + t * 0.44 + busPhase) * cos((uv.y - 0.5) * 11.0 - t * 0.31);\n"
@"    float tunnel = 0.10 / max(0.070, distance(uv + float2(zWarp * 0.023, -zWarp * 0.016), float2(0.5 + 0.07*sin(t*0.37 + u.rasterPhase), 0.52 + 0.05*cos(t*0.31 + u.pcLo*0.01))));\n"
@"    float v1 = lineField(uv, 0.74 + 0.040*sin(t*1.07 + busPhase), 0.027, env.x);\n"
@"    float v2 = lineField(uv, 0.53 + 0.040*sin(t*1.23 + busPhase*0.77), 0.026, env.y);\n"
@"    float v3 = lineField(uv, 0.32 + 0.040*sin(t*1.41 + busPhase*0.55), 0.025, env.z);\n"
@"    float hueBase = fract(u.hue + t*0.015 + busHeat*0.20 + forensic*0.12);\n"
@"    float3 r1 = hsv2rgb(float3(fract(hueBase + 0.00), 0.92, 1.00));\n"
@"    float3 r2 = hsv2rgb(float3(fract(hueBase + 0.33), 0.90, 1.00));\n"
@"    float3 r3 = hsv2rgb(float3(fract(hueBase + 0.66), 0.90, 1.00));\n"
@"    float3 matrixGreen = float3(0.02, 1.00, 0.24);\n"
@"    float3 voiceCol = mix(matrixGreen, r1, rainbow) * v1 * (0.70 + env.x*0.90) + mix(float3(0.00,0.90,0.52), r2, rainbow) * v2 * (0.70 + env.y*0.90) + mix(float3(0.35,1.00,0.08), r3, rainbow) * v3 * (0.70 + env.z*0.90);\n"
@"    float laneGlow = smoothstep(0.030,0.0,abs(uv.y-(0.74+u.voiceSpread*0.025)))*env.x + smoothstep(0.030,0.0,abs(uv.y-0.53))*env.y + smoothstep(0.030,0.0,abs(uv.y-(0.32-u.voiceSpread*0.025)))*env.z;\n"
@"    float bitLanes = busBitLane(uv, u.openBus) + 0.65 * busBitLane(float2(uv.y, uv.x), u.sidValue);\n"
@"    float3 busRainbow = hsv2rgb(float3(fract(hueBase + uv.x*0.22 + uv.y*0.12), 0.95, 1.0));\n"
@"    float cpu = cpuTrace(uv, u.pcLo, u.rasterPhase, u.irqHeat);\n"
@"    float phosphor = phosphorTriad(uv, t, saturate(envMax + busHeat + forensic));\n"
@"    float3 busCol = mix(float3(0.04,1.0,0.28), busRainbow, 0.72 + rainbow*0.28) * (matrix*1.8 + bitLanes + busHeat*0.18 + forensic*0.07 + cpu);\n"
@"    float3 sidCol = float3(0.001,0.017,0.006) + matrixGreen * matrix * (0.55 + envSum*0.45) + voiceCol*(0.52 + forensic*0.28) + laneGlow*mix(matrixGreen, busRainbow, rainbow)*(0.20+envSum*0.55);\n"
@"    float busCenter = pow(saturate(1.0 - distance(uv, float2(0.5,0.52))*1.8), 2.4);\n"
@"    float edgeCircuit = smoothstep(0.020, 0.0, abs(fract((uv.x + uv.y*0.35 + t*0.010) * 18.0) - 0.5)) * (0.018 + busHeat*0.055);\n"
@"    float3 blackBusBase = float3(0.000,0.000,0.000) + matrixGreen * matrix * 0.085 + busRainbow * busCenter * (0.030 + busHeat*0.110) + matrixGreen * edgeCircuit * 1.4;\n"
@"    float3 meshCol = mix(float3(0.00,0.85,0.22), hsv2rgb(float3(fract(u.colourCycle + uv.x*0.35 + uv.y*0.20), 0.94, 1.0)), saturate(u.rainbow));\n"
@"    float3 loaderCol = mix(float3(0.02,0.95,0.18), hsv2rgb(float3(fract(u.colourCycle + t*0.03 + u.loaderBorderPhase*0.07), 0.88, 1.0)), 0.62) * (loaderScreen + loaderBorder*0.72);\n"
@"    float3 col = mix(sidCol + meshCol*mesh*(0.42+envMax*0.38), mix(float3(0.004,0.020,0.007) + busCol*0.90 + voiceCol*0.16 + meshCol*mesh*(0.95+u.gpuBoost*0.25), blackBusBase + busCol*(0.62 + u.gpuBoost*0.24) + voiceCol*0.20 + meshCol*mesh*(0.16+u.busDepth*0.12) + loaderCol*0.55, saturate(u.blackBus)), busMode);\n"
@"    float gateRibbon = smoothstep(0.19, 0.0, abs(uv.y - (0.16 + 0.15*saturate(u.gates))));\n"
@"    col += mix(matrixGreen, busRainbow, rainbow) * gateRibbon * (0.08 + forensic*0.26 + envMax*0.18);\n"
@"    col += float3(fineGrid + mainGrid + tunnel*(0.015 + u.peak*0.035 + envSum*0.030)) * (1.0 - busMode*0.86);\n"
@"    col += busRainbow * pow(saturate(1.0 - distance(uv, float2(0.5))), 2.2) * (0.04 + envMax*0.09 + busHeat*0.10 + u.scopeEnergy*0.08);\n"
@"    col += mix(matrixGreen, busRainbow, rainbow) * cpu * (0.15 + u.irqHeat*0.55);\n"
@"    col += float3(phosphor*0.55, phosphor*(0.90+rainbow*0.55), phosphor*(0.35+rainbow*0.90)) * (0.70 + u.phosphorPersistence*0.75) * (1.0 - busMode*0.62);\n"
@"    col += busRainbow * busGhost * (0.28 + u.databusGhost*0.55) + matrixGreen * u.badline * 0.035 + busRainbow * u.dmaBurst * 0.030;\n"
@"    // v385: authentic VIC-II raster beam + open-bus DRAM-decay + badline DMA band,\n"
@"    // driven by real emulator telemetry (rasterPhase/vicBeamX/badline/spriteDma/decayMask).\n"
@"    if (busMode > 0.5) {\n"
@"        float ry = 1.0 - u.rasterPhase;\n"
@"        float badBand = smoothstep(0.05, 0.0, abs(uv.y - ry)) * saturate(u.badline);\n"
@"        col += vicRasterBeam(uv, u.rasterPhase, saturate(u.vicBeamX), saturate(u.spriteDma), saturate(u.phosphorPersistence));\n"
@"        col += openBusDecayLanes(uv, u.openBus, u.busDecayMask);\n"
@"        col += float3(0.26, 0.66, 0.15) * badBand * 0.16;\n"
@"    }\n"
@"    float scan = 0.020 * sin(uv.y * 1180.0 + t * 2.9 + busPhase);\n"
@"    float vignette = smoothstep(1.02, 0.12, distance(uv, float2(0.5)));\n"
@"    float latencyBeam = smoothstep(0.010, 0.0, abs(uv.x - fract(u.latencyPulse * 0.017 + t * (0.18 + u.lowLatencyMode*0.22))));\n"
@"    float3 fastGlow = hsv2rgb(float3(fract(hueBase + 0.44 + u.latencyPulse*0.0007), 0.94, 1.0));\n"
@"    col += fastGlow * latencyBeam * (0.035 + envMax*0.11 + busHeat*0.09 + u.lowLatencyMode*0.05);\n"
@"    float rainbowSweep = smoothstep(0.020, 0.0, abs(fract(uv.x + uv.y*0.18 + t*0.085 + u.sidReg*0.0039) - 0.5));\n"
@"    col += hsv2rgb(float3(fract(hueBase + uv.x + t*0.035), 0.92, 1.0)) * rainbowSweep * (0.006 + u.gpuBoost*0.024 + envMax*0.020 + busHeat*0.018);\n"
@"    float back = saturate(u.backscreenFlicker);\n"
@"    float cell = step(fract(uv.x*40.0),0.50) * step(fract(uv.y*25.0),0.50);\n"
@"    float luma = fract(sin(dot(floor(uv*float2(40.0,25.0))+floor(t*18.0), float2(12.9898,78.233))) * 43758.5453);\n"
@"    float loadFlash = smoothstep(0.88,1.0,sin(t*7.5 + u.openBus*0.071)*0.5+0.5) * u.loaderFlicker;\n"
@"    float gpuFrameBeam = smoothstep(0.012, 0.0, abs(uv.x - fract(u.gpuLatencyFrame * 0.013 + uv.y * 0.19))) * (0.035 + u.lowLatencyMode * 0.060);\n"
@"    float cycleRibbon = smoothstep(0.018, 0.0, abs(uv.y - fract(u.cyclePhase + uv.x * 0.31))) * (0.025 + busHeat * 0.075);\n"
@"    float rasterFlicker = (0.16 + 0.84*luma) * cell * back * (0.045 + 0.10*loadFlash);\n"
@"    col = mix(col, col + float3(0.02,0.34,0.055)*rasterFlicker + busRainbow*loadFlash*(0.035+back*0.055), saturate(busMode + back));\n"
@"    col += float3(0.20, 0.95, 1.0) * gpuFrameBeam;\n"
@"    col += float3(0.18, 1.0, 0.38) * cycleRibbon;\n"
@"    col = (col + scan) * vignette * (0.82 + u.peak*0.28 + envSum*0.28 + forensic*0.20 + busHeat*0.10 + loadFlash*0.10);\n"
@"    float crt = 1.0 - saturate(u.crtCurve) * pow(distance(uv,float2(0.5))*1.15, 2.0);\n"
@"    col *= crt;\n"
@"    // Open-bus GPU 'godlike realistic black' grade (bus surface only): crush the\n"
@"    // residual fill toward true black with a black-point gamma so the background\n"
@"    // reads BLACK, then lift highlights so only real bus data glows; a gentle\n"
@"    // filmic shoulder + chromatic bloom on the bright data gives a realistic CRT\n"
@"    // look instead of a flat green wash.\n"
@"    if (busMode > 0.5) {\n"
@"        float3 graded = pow(saturate(col), float3(1.95)) * 1.5;        // black point + highlight lift\n"
@"        float lum = dot(graded, float3(0.299, 0.587, 0.114));\n"
@"        float3 bloom = graded * smoothstep(0.35, 1.0, lum) * 0.55;     // bloom only on bright data\n"
@"        graded += bloom * float3(0.85, 1.0, 0.92);                     // subtle green-biased glow\n"
@"        graded = graded / (graded + 0.85) * 1.85;                      // filmic shoulder (Reinhard-ish)\n"
@"        col = graded;\n"
@"    }\n"
@"    return float4(saturate(col), 1.0);\n"
@"}\n";

struct ArpSIDSidCoreMetalUniformsV385 {
    float time;
    float peak;
    float forensic;
    float gates;
    float openBus;
    float sidReg;
    float sidValue;
    float surfaceKind;
    float env0;
    float env1;
    float env2;
    float framePulse;
    float hue;
    float busHeat;
    float voiceSpread;
    float rainbow;
    float pcLo;
    float rasterPhase;
    float irqHeat;
    float scopeEnergy;
    float latencyPulse;
    float lowLatencyMode;
    float blackBus;
    float gpuBoost;
    float loaderFlicker;
    float backscreenFlicker;
    float gpuLatencyFrame;
    float cyclePhase;
    float meshDensity;
    float loaderMode;
    float colourCycle;
    float crtCurve;
    float busDepth;
    float sparkle;
    float dmaBurst;
    float badline;
    float loaderBorderPhase;
    float databusGhost;
    float phosphorPersistence;
    float chipHeat;
    float busDecayMask;  // v385: real c64OpenBusDecayMask (per-bit DRAM charge)
    float spriteDma;     // v385: real c64VicSpriteDma
    float vicBeamX;      // v385: real VIC within-line beam column (c64VicCycle/63)
};

// Audio/render path must never touch Metal/AppKit/CoreAnimation; this shader is GUI-only.

@implementation ArpSIDSidCoreMetalBackdropView
- (instancetype)initWithFrame:(NSRect)frameRect {
    self = [super initWithFrame:frameRect];
    if (self) {
        _hasMetalDevice = NO;
        _tearingDown = NO;
        _vsyncPayloadDirty = YES;
        _vsyncDriven = NO;
        _surfaceKind = 0;
        _lastSidCoreRedrawTime = 0.0;
        _lastSidCoreVsyncTime = 0.0;
        _sidCoreVsyncFrameCounter = 0;
        _sidCoreAnimTime = 0.0;
        _sidCoreAnimFrame = 0;
        _sidCoreStaticFrames = 0u;
        _hasLastTelemetrySnapshot = NO;
        self.delegate = nil;
        // Metal-backed SIDCORE is driven by MTKView's display-synchronized draw callback,
        // not by random NSTimer jitter. CoreAnimation fallback stays explicit-dirty only.
        self.paused = YES;
        self.enableSetNeedsDisplay = YES;
        self.framebufferOnly = YES;
        self.autoResizeDrawable = YES;
        self.presentsWithTransaction = NO; // Present on MTK VSync, not CA transaction, for minimum display latency.
        self.sampleCount = 1;             // No MSAA resolve cost on the scope/shader surface.
        self.wantsLayer = YES;
        self.layer.masksToBounds = YES;
        self.layer.cornerRadius = 10.0;
        self.toolTip = @"SIDCORE safe standby surface: Metal arms after the host attaches the AU view to a window.";
        self.preferredFramesPerSecond = 120; // VSync target; MTKView clamps to the actual Mac/display cadence.
        std::memset(&_telemetry, 0, sizeof(_telemetry));
        _forensicActivity = 0.f; _forensicIntensity = 0.f; _forensicEnabled = NO;
        _layersBuilt = NO;
        [self _ensureLayers];
    }
    return self;
}
- (void)configureAsC64SidBusSurface {
    _surfaceKind = 1;
    self.toolTip = @"C64 SID-bus Matrix/Rainbow/Phosphor Metal shader: PHI2/open-bus/SID-write/PC/raster energy with VSync and realtime snapshot authority.";
    [self _sidCoreMarkPayloadDirtyAndArmVsync];
}
- (void)viewDidMoveToWindow {
    [super viewDidMoveToWindow];
    if (self.window) [self resumeAfterHostAttach];
    else self.paused = YES;
}
- (void)prepareForTeardown {
    _tearingDown = YES;
    _vsyncPayloadDirty = NO;
    self.paused = YES;
    self.delegate = nil;
    for (int i=0;i<3;++i) _uniformBuffers[i] = nil;
    _commandQueue = nil;
    _shaderLibrary = nil;
    _pipelineState = nil;
    _gridLayer = nil;
    _openBusLayer = nil;
    _legendLayer = nil;
    for (int i=0;i<3;++i) { _voiceLayer[i] = nil; _gateLayer[i] = nil; }
    _layersBuilt = NO;
}
- (void)resumeAfterHostAttach {
    if (!self.window) { self.paused = YES; return; }
    _tearingDown = NO;
    _vsyncPayloadDirty = YES;
    id<MTLDevice> device = self.device ? self.device : MTLCreateSystemDefaultDevice();
    if (device && self.device != device) self.device = device;
    _hasMetalDevice = (device != nil);
    _vsyncDriven = _hasMetalDevice;
    self.delegate = _hasMetalDevice ? self : nil;
    self.enableSetNeedsDisplay = !_hasMetalDevice;
    self.preferredFramesPerSecond = 120;
    self.toolTip = _hasMetalDevice ? @"SIDCORE Matrix/Rainbow/Phosphor Metal shader: VSync up to 120 Hz; low-latency direct drawable presentation; C64 open-bus mode, GPU mesh, loader flicker, rainbow bloom, SID bus, CPU PC beam, gates, shimmer, voice glow, live VCO overlay." : @"SIDCORE safe fallback surface: Metal device unavailable; CoreAnimation overlay active.";
    if (_hasMetalDevice && (!_commandQueue || !_pipelineState))
        [self _buildShaderPipelineIfPossibleWithDevice:device];
    if (_hasMetalDevice) {
        for (int i=0;i<3;++i)
            if (!_uniformBuffers[i])
                _uniformBuffers[i]=[device newBufferWithLength:sizeof(ArpSIDSidCoreMetalUniformsV385)
                                                       options:MTLResourceStorageModeShared];
    }
    _layersBuilt = NO;
    [self _ensureLayers];
    self.paused = !_hasMetalDevice || ![self _sidCoreIsActuallyVisibleForVsync];
    [self _sidCoreMarkPayloadDirtyAndArmVsync];
}
- (void)dealloc {
    [self prepareForTeardown];
}
- (BOOL)isOpaque { return YES; }
- (void)_buildShaderPipelineIfPossibleWithDevice:(id<MTLDevice>)device {
    if (!device) return;
    NSError* error = nil;
    _commandQueue = [device newCommandQueue];
    _shaderLibrary = [device newLibraryWithSource:kArpSIDSidCoreMetalShaderSourceV385 options:nil error:&error];
    if (!_shaderLibrary || error) { _pipelineState = nil; return; }
    id<MTLFunction> vertex = [_shaderLibrary newFunctionWithName:@"sidcore_vtx"];
    id<MTLFunction> fragment = [_shaderLibrary newFunctionWithName:@"sidcore_frag"];
    if (!vertex || !fragment) return;
    MTLRenderPipelineDescriptor* desc = [[MTLRenderPipelineDescriptor alloc] init];
    desc.vertexFunction = vertex;
    desc.fragmentFunction = fragment;
    desc.colorAttachments[0].pixelFormat = MTLPixelFormatBGRA8Unorm;
    _pipelineState = [device newRenderPipelineStateWithDescriptor:desc error:&error];
    if (error) _pipelineState = nil;
}
- (BOOL)_sidCoreMayTouchLayers {
    if (_tearingDown) return NO;
    if (!self.layer) return NO;
    return ArpSIDUIHasDrawableArea(self);
}
- (void)_sanitizeTelemetryInPlace {
    _telemetry.peakL = ArpSIDUIClamp01(_telemetry.peakL);
    _telemetry.peakR = ArpSIDUIClamp01(_telemetry.peakR);
    _telemetry.rmsL = ArpSIDUIClamp01(_telemetry.rmsL);
    _telemetry.rmsR = ArpSIDUIClamp01(_telemetry.rmsR);
    for (int v = 0; v < 3; ++v) {
        _telemetry.voiceEnvLevel[v] = ArpSIDUIClamp01(_telemetry.voiceEnvLevel[v]);
        for (int i = 0; i < 256; ++i) _telemetry.vcoScope[v][i] = ArpSIDUIClampSigned(_telemetry.vcoScope[v][i], 1.2f);
    }
    for (int i = 0; i < 128; ++i) {
        _telemetry.c64OpenBusScope[i] = ArpSIDUIClampSigned(_telemetry.c64OpenBusScope[i]);
        _telemetry.c64SidBusScope[i] = ArpSIDUIClampSigned(_telemetry.c64SidBusScope[i]);
        _telemetry.c64SidRegScope[i] = ArpSIDUIClampSigned(_telemetry.c64SidRegScope[i]);
        _telemetry.c64SidValueScope[i] = ArpSIDUIClampSigned(_telemetry.c64SidValueScope[i]);
        _telemetry.c64SidWritePulseScope[i] = ArpSIDUIClampSigned(_telemetry.c64SidWritePulseScope[i]);
        _telemetry.c64Phi2Scope[i] = ArpSIDUIClampSigned(_telemetry.c64Phi2Scope[i]);
        _telemetry.c64IrqDmaScope[i] = ArpSIDUIClampSigned(_telemetry.c64IrqDmaScope[i]);
        _telemetry.c64ChipScope[i] = ArpSIDUIClampSigned(_telemetry.c64ChipScope[i]);
    }
}
- (void)_ensureLayers {
    if (_tearingDown || _layersBuilt || !self.layer) return;
    ArpSIDAssignLayerFill(self.layer, 0.000, 0.020, 0.006, 1.0);
    _gridLayer = [CAShapeLayer layer];
    _gridLayer.fillColor = nil; _gridLayer.lineWidth = 1.0; _gridLayer.opacity = 0.42;
    ArpSIDAssignLayerColor(_gridLayer, 0.02, 1.00, 0.26, 0.32);
    ArpSIDDisableImplicitLayerActions(_gridLayer);
    [self.layer addSublayer:_gridLayer];
    const CGFloat cols[3][3] = {{0.02,1.00,0.26},{0.00,0.92,0.62},{0.78,0.20,1.00}};
    for (int i = 0; i < 3; ++i) {
        _voiceLayer[i] = [CAShapeLayer layer];
        _voiceLayer[i].fillColor = nil;
        _voiceLayer[i].lineWidth = (i == 0) ? 2.6 : 2.1;
        _voiceLayer[i].lineJoin = kCALineJoinRound;
        _voiceLayer[i].lineCap = kCALineCapRound;
        ArpSIDAssignLayerColor(_voiceLayer[i], cols[i][0], cols[i][1], cols[i][2], 0.62);
        ArpSIDDisableImplicitLayerActions(_voiceLayer[i]);
        [self.layer addSublayer:_voiceLayer[i]];
        _gateLayer[i] = [CAShapeLayer layer];
        ArpSIDAssignLayerFill(_gateLayer[i], cols[i][0], cols[i][1], cols[i][2], 0.33);
        _gateLayer[i].strokeColor = nil;
        ArpSIDDisableImplicitLayerActions(_gateLayer[i]);
        [self.layer addSublayer:_gateLayer[i]];
    }
    _openBusLayer = [CAShapeLayer layer];
    ArpSIDAssignLayerFill(_openBusLayer, 0.18, 1.00, 0.32, 0.34);
    ArpSIDAssignLayerColor(_openBusLayer, 0.20, 1.00, 0.40, 0.48);
    _openBusLayer.lineCap = kCALineCapRound;
    _openBusLayer.lineJoin = kCALineJoinRound;
    _openBusLayer.lineWidth = 1.2;
    ArpSIDDisableImplicitLayerActions(_openBusLayer);
    [self.layer addSublayer:_openBusLayer];
    _legendLayer = [CATextLayer layer];
    _legendLayer.contentsScale = (NSScreen.mainScreen.backingScaleFactor > 0.0 ? NSScreen.mainScreen.backingScaleFactor : 2.0);
    _legendLayer.fontSize = 10.0;
    _legendLayer.alignmentMode = kCAAlignmentLeft;
    _legendLayer.truncationMode = kCATruncationEnd;
    CGColorRef text = ArpSIDCreateCGColor(0.52,1.0,0.62,0.88);
    _legendLayer.foregroundColor = text; CGColorRelease(text);
    ArpSIDDisableImplicitLayerActions(_legendLayer);
    [self.layer addSublayer:_legendLayer];
    _layersBuilt = YES;
}
- (void)layout {
    [super layout];
    [self _ensureLayers];
    [self _updateLayerGeometry];
}
- (void)_updateLayerGeometry {
    if (!_layersBuilt || _tearingDown) return;
    const CGRect b = ArpSIDUIFinitePositiveBounds(NSRectToCGRect(self.bounds));
    _gridLayer.frame = b;
    CGPathRef grid = ArpSIDCreateSidCoreGridPath(b);
    _gridLayer.path = grid; CGPathRelease(grid);
    for (int i = 0; i < 3; ++i) { _voiceLayer[i].frame = b; _gateLayer[i].frame = b; }
    _openBusLayer.frame = b;
    _legendLayer.frame = CGRectMake(10, 7, MAX((CGFloat)40.0, b.size.width - 20), 18);
}
- (void)_refreshLayerPayload {
    if (![self _sidCoreMayTouchLayers]) return;
    [self _ensureLayers];
    [self _updateLayerGeometry];
    if (!_layersBuilt) return;
    const CGRect b = ArpSIDUIFinitePositiveBounds(NSRectToCGRect(self.bounds));
    const float peak = ArpSIDUIClamp01((_telemetry.peakL + _telemetry.peakR) * 0.5f);
    const float forensic = ArpSIDUIClamp01(_forensicEnabled ? std::max(_forensicActivity, _forensicIntensity * 0.55f) : 0.0f);
    ArpSIDAssignLayerFill(self.layer, 0.000 + forensic * 0.016, 0.016 + peak * 0.040, 0.006 + forensic * 0.018, 1.0);
    const CGFloat cols[3][3] = {{0.02,1.00,0.26},{0.00,0.92,0.62},{0.78,0.20,1.00}};
    for (int voice = 0; voice < 3; ++voice) {
        const float env = ArpSIDUIClamp01(_telemetry.voiceEnvLevel[voice]);
        const int ctrlIndex = voice == 0 ? 4 : (voice == 1 ? 11 : 18);
        const BOOL gateOn = (_telemetry.sidRegs[ctrlIndex] & 0x01u) != 0;
        const float voiceGlow = ArpSIDUIClamp01(env * 0.72f + (gateOn ? 0.22f : 0.0f) + peak * 0.18f + forensic * 0.28f);
        CGPathRef wave = ArpSIDCreateSidCoreWavePath(b, _telemetry.vcoScope[voice], voice, std::max(peak, voiceGlow));
        _voiceLayer[voice].path = wave; CGPathRelease(wave);
        ArpSIDAssignLayerColor(_voiceLayer[voice], cols[voice][0], cols[voice][1], cols[voice][2], 0.34 + voiceGlow * 0.54);
        _voiceLayer[voice].lineWidth = 1.8 + voiceGlow * 2.2;
        _voiceLayer[voice].shadowColor = _voiceLayer[voice].strokeColor;
        _voiceLayer[voice].shadowOpacity = 0.10f + voiceGlow * 0.58f;
        _voiceLayer[voice].shadowRadius = 4.0f + voiceGlow * 18.0f;
        _voiceLayer[voice].shadowOffset = CGSizeZero;
        CGPathRef gate = ArpSIDCreateSidCoreGatePath(b, _telemetry.sidRegs, voice);
        _gateLayer[voice].path = gate; CGPathRelease(gate);
        ArpSIDAssignLayerFill(_gateLayer[voice], cols[voice][0], cols[voice][1], cols[voice][2], gateOn ? (0.36 + voiceGlow * 0.46) : (0.08 + voiceGlow * 0.12));
        _gateLayer[voice].shadowColor = _voiceLayer[voice].strokeColor;
        _gateLayer[voice].shadowOpacity = gateOn ? (0.22f + voiceGlow * 0.48f) : 0.04f;
        _gateLayer[voice].shadowRadius = gateOn ? (5.0f + voiceGlow * 14.0f) : 2.0f;
        _gateLayer[voice].shadowOffset = CGSizeZero;
    }
    CGPathRef bus = ArpSIDCreateSidCoreOpenBusPath(b,
                                                   _telemetry.c64OpenBus,
                                                   _telemetry.c64LastRead,
                                                   _telemetry.c64LastSidReg,
                                                   _telemetry.c64LastSidValue,
                                                   _telemetry.c64OpenBusScope,
                                                   _telemetry.c64SidBusScope,
                                                   _telemetry.c64BusScopeWritePos,
                                                   128,
                                                   forensic);
    _openBusLayer.path = bus; CGPathRelease(bus);
    ArpSIDAssignLayerFill(_openBusLayer, 0.16, 1.0, 0.32, 0.25 + forensic * 0.36);
    ArpSIDAssignLayerColor(_openBusLayer, 0.18, 1.00, 0.42, 0.52 + forensic * 0.32);
    _openBusLayer.lineWidth = 1.3 + forensic * 1.6;
    _openBusLayer.shadowColor = _openBusLayer.backgroundColor;
    _openBusLayer.shadowOpacity = 0.20f + forensic * 0.42f;
    _openBusLayer.shadowRadius = 4.0f + forensic * 12.0f;
    _openBusLayer.shadowOffset = CGSizeZero;
    _legendLayer.string = [NSString stringWithFormat:@"MATRIX SIDCORE · %@ · decoded REG/VALUE/WRITE/PHI2/IRQ lanes · VEnv %.0f/%.0f/%.0f · Gates %c%c%c · OpenBus %02X read %02X · SID $D4%02X=%02X",
                           ArpSIDC64AuthorityLabel(_telemetry),
                           _telemetry.voiceEnvLevel[0]*99.0f, _telemetry.voiceEnvLevel[1]*99.0f, _telemetry.voiceEnvLevel[2]*99.0f,
                           (_telemetry.sidRegs[4]&1)?'G':'-', (_telemetry.sidRegs[11]&1)?'G':'-', (_telemetry.sidRegs[18]&1)?'G':'-',
                           _telemetry.c64OpenBus, _telemetry.c64LastRead, _telemetry.c64LastSidReg, _telemetry.c64LastSidValue];
}
- (BOOL)_sidCoreIsActuallyVisibleForVsync {
    if (_tearingDown || !self.window || self.hidden || self.alphaValue <= 0.001) return NO;
    if (!ArpSIDUIHasDrawableArea(self)) return NO;
    if (self.window.occlusionState != 0 && ((self.window.occlusionState & NSWindowOcclusionStateVisible) == 0)) return NO;
    return YES;
}
- (void)_sidCoreMarkPayloadDirtyAndArmVsync {
    if (_tearingDown) return;
    _vsyncPayloadDirty = YES;
    // A real change armed this wake: give the surface a fresh settle window before it
    // is allowed to self-pause again in drawInMTKView.
    _sidCoreStaticFrames = 0u;
    if (_hasMetalDevice) {
        const BOOL visible = [self _sidCoreIsActuallyVisibleForVsync];
        self.paused = !visible;
        // If currently hidden/occluded, do not spin Metal. The next visible telemetry tick rearms it.
        return;
    }
    if (![self _sidCoreMayTouchLayers]) return;
    const NSTimeInterval now = [NSDate timeIntervalSinceReferenceDate];
    // CoreAnimation fallback remains bounded and jitter-tolerant; Metal path uses VSync.
    if (_lastSidCoreRedrawTime > 0.0 && (now - _lastSidCoreRedrawTime) < (1.0 / 120.0)) return;
    _lastSidCoreRedrawTime = now;
    _vsyncPayloadDirty = NO;
    [CATransaction begin];
    [CATransaction setDisableActions:YES];
    [self _refreshLayerPayload];
    [CATransaction commit];
}
- (void)updateWithTelemetry:(const ArpSIDTelemetry&)telemetry {
    if (_tearingDown) return;
    _telemetry = telemetry;
    [self _sanitizeTelemetryInPlace];
    // Idle-redraw fix: only wake the Metal vsync loop when the sanitized telemetry
    // actually differs from what is already on screen. At idle (no audio / notes /
    // transport motion) the telemetry is byte-stable, so this leaves the surface
    // paused instead of re-arming it every poll tick. A spurious wake (e.g. padding
    // noise) is harmless — the static-frame gate in drawInMTKView re-pauses it.
    if (_hasLastTelemetrySnapshot &&
        memcmp(&_telemetry, &_lastTelemetrySnapshot, sizeof(ArpSIDTelemetry)) == 0) {
        return;
    }
    _lastTelemetrySnapshot = _telemetry;
    _hasLastTelemetrySnapshot = YES;
    [self _sidCoreMarkPayloadDirtyAndArmVsync];
}
- (void)setForensicActivity:(float)activity intensity:(float)intensity enabled:(BOOL)enabled {
    if (_tearingDown) return;
    const float a = ArpSIDUIClamp01(activity);
    const float i = ArpSIDUIClamp01(intensity);
    // Idle-redraw fix: this is called every poll tick for all surfaces; only re-arm
    // the vsync loop when the forensic state actually changes so an idle surface is
    // not unpaused 8-24×/s for identical values.
    if (a == _forensicActivity && i == _forensicIntensity && enabled == _forensicEnabled) return;
    _forensicActivity = a;
    _forensicIntensity = i;
    _forensicEnabled = enabled;
    [self _sidCoreMarkPayloadDirtyAndArmVsync];
}
- (void)drawInMTKView:(MTKView *)view {
    (void)view;
    if (_tearingDown || !_hasMetalDevice) return;
    if (![self _sidCoreIsActuallyVisibleForVsync]) { self.paused = YES; return; }
    const NSTimeInterval now = [NSDate timeIntervalSinceReferenceDate];
    // Idle visualizer fix: frame delta since the previous vsync, used to advance
    // the activity-gated animation clock below (clamped to absorb stalls).
    const NSTimeInterval sidCoreVsyncDt = (_lastSidCoreVsyncTime > 0.0)
        ? std::clamp(now - _lastSidCoreVsyncTime, 0.0, 0.1) : 0.0;
    _lastSidCoreVsyncTime = now;
    ++_sidCoreVsyncFrameCounter;
    id<CAMetalDrawable> drawable = self.currentDrawable;
    MTLRenderPassDescriptor* pass = self.currentRenderPassDescriptor;
    if (_commandQueue && _pipelineState && drawable && pass) {
        const float peak = ArpSIDUIClamp01((_telemetry.peakL + _telemetry.peakR) * 0.5f);
        const float forensic = ArpSIDUIClamp01(_forensicEnabled ? std::max(_forensicActivity, _forensicIntensity * 0.55f) : 0.0f);
        float gates = 0.0f;
        gates += (_telemetry.sidRegs[4] & 0x01u) ? 0.15f : 0.0f;
        gates += (_telemetry.sidRegs[11] & 0x01u) ? 0.35f : 0.0f;
        gates += (_telemetry.sidRegs[18] & 0x01u) ? 0.50f : 0.0f;
        const float env0 = ArpSIDUIClamp01(_telemetry.voiceEnvLevel[0]);
        const float env1 = ArpSIDUIClamp01(_telemetry.voiceEnvLevel[1]);
        const float env2 = ArpSIDUIClamp01(_telemetry.voiceEnvLevel[2]);
        const float envMax = std::max(env0, std::max(env1, env2));
        const float envMin = std::min(env0, std::min(env1, env2));
        float busScopeHeat = 0.0f;
        for (int i = 0; i < 128; i += 8) {
            busScopeHeat += std::fabs(std::clamp(_telemetry.c64OpenBusScope[i], -1.0f, 1.0f));
            busScopeHeat += std::fabs(std::clamp(_telemetry.c64SidBusScope[i], -1.0f, 1.0f));
            busScopeHeat += 0.5f * std::fabs(std::clamp(_telemetry.c64SidWritePulseScope[i], -1.0f, 1.0f));
            busScopeHeat += 0.25f * std::fabs(std::clamp(_telemetry.c64IrqDmaScope[i], -1.0f, 1.0f));
        }
        busScopeHeat = ArpSIDUIClamp01(busScopeHeat * (1.0f / 44.0f));
        const float busHeat = ArpSIDUIClamp01(((float)_telemetry.c64OpenBus + (float)_telemetry.c64LastSidValue) / 510.0f * 0.62f + busScopeHeat * 0.38f);
        const float hue = ArpSIDUIClamp01((_surfaceKind ? busHeat : envMax) * 0.74f + forensic * 0.26f);
        // Idle visualizer fix: only advance the shader animation clock while the
        // surface is REALLY doing something in real time. Critically, the activity
        // test must use signals that are zero at idle — NOT retained state. peak
        // (audio output) and envMax (live voice envelope levels) fall to zero with
        // no notes; forensic is an explicit user diagnostic mode. We deliberately
        // EXCLUDE busHeat, busScopeHeat and the SID gate bits: those stay non-zero
        // for any loaded patch (retained register/bus values), which previously
        // held this gate permanently open and let the surface drift "from the
        // start". A static bus has magnitude but no motion, so it must not count.
        const float sidCoreActivity = std::max({peak, envMax, forensic});
        if (sidCoreActivity > 0.012f) { _sidCoreAnimTime += sidCoreVsyncDt; ++_sidCoreAnimFrame; }
        const float animNow = (float)std::fmod(_sidCoreAnimTime, 10000.0);
        ArpSIDSidCoreMetalUniformsV385 uniforms = {
            animNow, peak, forensic, gates,
            (float)_telemetry.c64OpenBus, (float)_telemetry.c64LastSidReg, (float)_telemetry.c64LastSidValue, (float)_surfaceKind,
            env0, env1, env2,
            (float)(_sidCoreAnimFrame & 0xFFFFFFu),
            hue, busHeat, ArpSIDUIClamp01(envMax - envMin), ArpSIDUIClamp01(envMax * 0.65f + busHeat * 0.25f + forensic * 0.35f),
            (float)(_telemetry.c64CpuPc & 0x00FFu), ArpSIDUIClamp01(((float)_telemetry.c64VicRaster + (float)_telemetry.c64VicCycle / 64.0f) / 312.0f),
            ArpSIDUIClamp01(((float)_telemetry.c64Cia1Irq + (float)_telemetry.c64Cia2Irq) / 510.0f), ArpSIDUIClamp01(peak * 0.45f + envMax * 0.30f + busHeat * 0.25f + busScopeHeat * 0.35f),
            (float)(_sidCoreAnimFrame & 0xFFFFu), 1.0f, _surfaceKind ? 1.0f : 0.0f, 1.0f,
            (_surfaceKind ? 1.0f : ArpSIDUIClamp01(0.18f + ((_telemetry.psidActive || _telemetry.psidTitle[0]) ? 0.10f : 0.28f))),  // open-bus GPU: full black background
            ArpSIDUIClamp01(_surfaceKind ? 1.0f : 0.32f),
            (float)(_sidCoreAnimFrame & 0xFFFFu),
            ArpSIDUIClamp01(((float)_telemetry.c64VicCycle / 64.0f) + ((float)(_telemetry.c64LastSidReg & 0x1Fu) / 31.0f) * 0.25f),
            _surfaceKind ? 48.0f : 36.0f,
            _surfaceKind ? 1.0f : 0.45f,
            std::fmod((float)_sidCoreAnimTime * 0.035f + hue + busHeat * 0.22f, 1.0f),
            _surfaceKind ? 0.42f : 0.22f,
            ArpSIDUIClamp01((_surfaceKind ? 0.70f : 0.36f) + busHeat * 0.24f + envMax * 0.16f),
            ArpSIDUIClamp01(envMax * 0.50f + busHeat * 0.45f + forensic * 0.35f + peak * 0.20f),
            ArpSIDUIClamp01(((float)_telemetry.c64VicCycle / 63.0f) + busHeat * 0.20f),
            ArpSIDUIClamp01((_telemetry.c64VicBadline ? 0.90f : 0.10f) + envMax * 0.15f),  // v385: real VIC badline, not raster%8 approximation
            std::fmod((float)_sidCoreAnimTime * 0.19f + (float)(_telemetry.c64OpenBus & 0x0Fu) * 0.03125f, 1.0f),
            ArpSIDUIClamp01(busHeat * 0.70f + forensic * 0.25f + peak * 0.20f),
            ArpSIDUIClamp01(0.35f + envMax * 0.35f + busHeat * 0.20f + forensic * 0.25f),
            ArpSIDUIClamp01(envMax * 0.55f + busHeat * 0.35f + peak * 0.25f),
            (float)_telemetry.c64OpenBusDecayMask,                                  // v385: per-bit open-bus DRAM charge
            _telemetry.c64VicSpriteDma ? 1.0f : 0.0f,                              // v385: sprite DMA burst
            ArpSIDUIClamp01((float)_telemetry.c64VicCycle / 63.0f)                  // v385: VIC within-line beam column
        };
        id<MTLCommandBuffer> cb = [_commandQueue commandBuffer];
        id<MTLRenderCommandEncoder> enc = cb ? [cb renderCommandEncoderWithDescriptor:pass] : nil;
        if (enc) {
            [enc setRenderPipelineState:_pipelineState];
            id<MTLBuffer> ub = _uniformBuffers[_uniformWriteIndex % 3u];
            _uniformWriteIndex = (_uniformWriteIndex + 1u) % 3u;
            if (ub && [ub length] >= sizeof(uniforms)) {
                std::memcpy([ub contents], &uniforms, sizeof(uniforms));
                [enc setFragmentBuffer:ub offset:0 atIndex:0];
            } else {
                [enc setFragmentBytes:&uniforms length:sizeof(uniforms) atIndex:0];
            }
            [enc drawPrimitives:MTLPrimitiveTypeTriangleStrip vertexStart:0 vertexCount:4];
            [enc endEncoding];
            [cb presentDrawable:drawable];
            [cb commit];
        }
        // Idle-redraw fix: the activity-gated animation clock is the only render
        // input that advances without an explicit telemetry/forensic wake. While it
        // is frozen the just-presented frame is final, so after a couple of settled
        // frames pause the MTKView — it stops re-rendering identical pixels at vsync
        // until the next real change re-arms it via _sidCoreMarkPayloadDirtyAndArmVsync.
        if (sidCoreActivity > 0.012f) {
            _sidCoreStaticFrames = 0u;
        } else {
            if (_sidCoreStaticFrames < 0xFFFFFFFFu) ++_sidCoreStaticFrames;
            if (_sidCoreStaticFrames >= 2u) self.paused = YES;
        }
    }
    if (!_vsyncPayloadDirty) return;
    _vsyncPayloadDirty = NO;
    _lastSidCoreRedrawTime = now;
    [CATransaction begin];
    [CATransaction setDisableActions:YES];
    [self _refreshLayerPayload];
    [CATransaction commit];
}
- (void)mtkView:(MTKView *)view drawableSizeWillChange:(CGSize)size { (void)view; (void)size; if (_tearingDown) return; [self _updateLayerGeometry];
    // Idle-redraw fix: the surface may be self-paused (static content). A resize
    // recreates the drawable at the new size, which would otherwise present stale/
    // blank pixels until the next telemetry change — re-arm one render at the new size.
    [self _sidCoreMarkPayloadDirtyAndArmVsync];
}
@end

// v962: the SIDCORE popout window class that _sidCoreTogglePopout's comment and
// the window title ("Cmd-F fullscreen") always promised but was never written —
// the popout used a plain NSWindow, so ⌘F did nothing. The popout is our own
// key window (not the host's plugin window), so owning ⌘F here is safe and
// cannot shadow a host shortcut.
@interface ArpSIDSidCorePopoutWindow : NSWindow
@end

@implementation ArpSIDSidCorePopoutWindow
- (BOOL)canBecomeKeyWindow { return YES; }
- (BOOL)performKeyEquivalent:(NSEvent*)event {
    const NSEventModifierFlags mods = (event.modifierFlags & NSEventModifierFlagDeviceIndependentFlagsMask);
    const BOOL commandOnly = ((mods & NSEventModifierFlagCommand) != 0) &&
                             ((mods & ~(NSEventModifierFlagCommand | NSEventModifierFlagShift)) == 0);
    NSString* chars = (event.charactersIgnoringModifiers != nil) ? event.charactersIgnoringModifiers : @"";
    if (commandOnly && chars.length == 1) {
        const unichar c = [chars characterAtIndex:0];
        if (c == 'f' || c == 'F') {
            [self toggleFullScreen:nil];
            return YES;
        }
        if (c == 'w' || c == 'W') {  // standard close chord for a utility window
            [self performClose:nil];
            return YES;
        }
    }
    return [super performKeyEquivalent:event];
}
@end

// Vector-based SIDCORE control visualizer layered over the Metal backdrop.
@interface ArpSIDSidCoreVectorView : NSView {
@private
    ArpSIDTelemetry _telemetry;
    float _forensicActivity;
    float _forensicIntensity;
    BOOL _forensicEnabled;
}
- (void)updateWithTelemetry:(const ArpSIDTelemetry&)telemetry;
- (void)setForensicActivity:(float)activity intensity:(float)intensity enabled:(BOOL)enabled;
@end

static inline CGFloat ArpSIDClamp01(CGFloat v) {
    if (!std::isfinite((double)v)) return 0.0;
    return std::min<CGFloat>(1.0, std::max<CGFloat>(0.0, v));
}
static inline NSColor* ArpSIDRGB(CGFloat r, CGFloat g, CGFloat b, CGFloat a) {
    return [NSColor colorWithSRGBRed:r green:g blue:b alpha:a];
}
static inline void ArpSIDFillRoundedRect3D(NSRect r, NSColor* base, CGFloat radius) {
    NSColor* convertedBase = [base colorUsingColorSpace:[NSColorSpace genericRGBColorSpace]];
    if (convertedBase) base = convertedBase;
    NSBezierPath* path = [NSBezierPath bezierPathWithRoundedRect:r xRadius:radius yRadius:radius];
    NSGradient* grad = [[NSGradient alloc] initWithColorsAndLocations:
                        [[base blendedColorWithFraction:0.40 ofColor:[NSColor whiteColor]] colorWithAlphaComponent:0.98], 0.0,
                        [base colorWithAlphaComponent:0.96], 0.28,
                        [[base blendedColorWithFraction:0.22 ofColor:[NSColor blackColor]] colorWithAlphaComponent:0.95], 1.0,
                        nil];
    [[NSGraphicsContext currentContext] saveGraphicsState];
    [path addClip];
    [grad drawInRect:r angle:90.0];
    [[NSGraphicsContext currentContext] restoreGraphicsState];
    [[ArpSIDRGB(1,1,1,0.16) colorUsingColorSpace:[NSColorSpace genericRGBColorSpace]] setStroke];
    [path setLineWidth:1.0];
    [path stroke];
    NSRect gloss = NSMakeRect(NSMinX(r)+2.0, NSMaxY(r)-MAX(6.0, r.size.height*0.24), MAX(4.0, r.size.width*0.24), MAX(4.0, r.size.height*0.18));
    [[NSColor colorWithWhite:1.0 alpha:0.18] setFill];
    [[NSBezierPath bezierPathWithRoundedRect:gloss xRadius:3 yRadius:3] fill];
}
static inline void ArpSIDDrawPill(NSRect r, NSString* text, NSColor* base, BOOL active) {
    NSColor* c = active ? base : [ArpSIDRGB(0.20, 0.23, 0.30, 0.92) colorUsingColorSpace:[NSColorSpace genericRGBColorSpace]];
    ArpSIDFillRoundedRect3D(r, c, 7.0);
    NSDictionary* attrs = @{ NSForegroundColorAttributeName: active ? [NSColor whiteColor] : ArpSIDRGB(0.64,0.70,0.80,0.92), NSFontAttributeName: monoBF(8.0) };
    NSSize ts = [text sizeWithAttributes:attrs];
    [text drawAtPoint:NSMakePoint(NSMidX(r)-ts.width*0.5, NSMidY(r)-ts.height*0.5-0.5) withAttributes:attrs];
}
static inline void ArpSIDDrawCubeBar(NSRect r, NSColor* c, CGFloat amount) {
    amount = ArpSIDClamp01(amount);
    const CGFloat h = MAX(4.0, r.size.height * amount);
    NSRect body = NSMakeRect(r.origin.x, r.origin.y, r.size.width, h);
    ArpSIDFillRoundedRect3D(body, c, 5.0);
    NSBezierPath* shadow = [NSBezierPath bezierPathWithRoundedRect:NSInsetRect(body, -3.0, -3.0) xRadius:8 yRadius:8];
    [[c colorWithAlphaComponent:0.08 + amount * 0.08] setFill];
    [shadow fill];
}

// SIDCORE waveform scopes are Metal/overlay-owned. Do not reintroduce CPU NSBezierPath wave-strip drawing here;
// hidden/duplicate scope drawing causes extra GUI work and stale background scopes.
static inline NSString* ArpSIDWaveName(uint8_t ctrl) {
    if (ctrl & 0x80u) return @"NOISE";
    if ((ctrl & 0x70u) == 0x70u) return @"TRI+SAW+PULSE";
    if ((ctrl & 0x60u) == 0x60u) return @"SAW+PULSE";
    if ((ctrl & 0x50u) == 0x50u) return @"TRI+PULSE";
    if ((ctrl & 0x30u) == 0x30u) return @"TRI+SAW";
    if (ctrl & 0x40u) return @"PULSE";
    if (ctrl & 0x20u) return @"SAW";
    if (ctrl & 0x10u) return @"TRIANGLE";
    return @"IDLE";
}

@implementation ArpSIDSidCoreVectorView

- (instancetype)initWithFrame:(NSRect)frameRect {
    self = [super initWithFrame:frameRect];
    if (self) {
        self.wantsLayer = YES;
        std::memset(&_telemetry, 0, sizeof(_telemetry));
        _forensicActivity = 0.f; _forensicIntensity = 0.f; _forensicEnabled = NO;
    }
    return self;
}

- (BOOL)isOpaque { return NO; }

- (void)updateWithTelemetry:(const ArpSIDTelemetry&)telemetry {
    _telemetry = telemetry;
    [self setNeedsDisplay:YES];
}
- (void)setForensicActivity:(float)activity intensity:(float)intensity enabled:(BOOL)enabled {
    const float a = ArpSIDClamp01(activity);
    const float i = ArpSIDClamp01(intensity);
    if(fabsf(a-_forensicActivity)>0.001f || fabsf(i-_forensicIntensity)>0.001f || _forensicEnabled!=enabled){
        _forensicActivity=a; _forensicIntensity=i; _forensicEnabled=enabled;
        [self setNeedsDisplay:YES];
    }
}

- (void)drawRect:(NSRect)dirtyRect {
    (void)dirtyRect;
    const NSRect b = self.bounds;
    const CGFloat w = MAX(1.0, b.size.width);
    const CGFloat h = MAX(1.0, b.size.height);

    const float peak = ArpSIDUIClamp01((_telemetry.peakL + _telemetry.peakR) * 0.5f);
    const float rms  = ArpSIDUIClamp01((_telemetry.rmsL  + _telemetry.rmsR)  * 0.5f);
    const float beat = (float)ArpSIDUIFiniteDouble(_telemetry.hostBeat, 0.0);
    const CGFloat phase = (CGFloat)std::fmod(beat * 22.0f, 1.0f);
    const uint8_t* regs = _telemetry.sidRegs;

    NSGradient* bg = [[NSGradient alloc] initWithColorsAndLocations:
                      ArpSIDRGB(0.025,0.030,0.060,0.72), 0.0,
                      ArpSIDRGB(0.040,0.060,0.120,0.58), 0.35,
                      ArpSIDRGB(0.020,0.022,0.050,0.64), 1.0,
                      nil];
    [bg drawInRect:b angle:90.0];
    if (_forensicEnabled && _forensicActivity > 0.001f) {
        const CGFloat haloA = 0.04 + _forensicActivity * (0.10 + 0.08 * _forensicIntensity);
        NSColor* forensicColor = ArpSIDRGB(1.00,0.70,0.22,haloA);
        [forensicColor setFill];
        [[NSBezierPath bezierPathWithRoundedRect:NSInsetRect(b, 6.0, 6.0) xRadius:18 yRadius:18] fill];
    }

    for (NSInteger i = 0; i < (NSInteger)h; i += 4) {
        const CGFloat a = (i % 8 == 0) ? 0.028 : 0.012;
        [[NSColor colorWithWhite:1.0 alpha:a] setFill];
        NSRectFill(NSMakeRect(0.0, (CGFloat)i, w, 1.0));
    }
    for (NSInteger x = 0; x < (NSInteger)w; x += 18) {
        [[NSColor colorWithWhite:1.0 alpha:0.015] setFill];
        NSRectFill(NSMakeRect((CGFloat)x, 0.0, 1.0, h));
    }

    for (int s = 0; s < 28; ++s) {
        const CGFloat ft = (CGFloat)s / 28.0;
        const CGFloat px = std::fmod((phase * 1.4 + ft * 0.731) * w * 1.23, w);
        const CGFloat py = std::fmod((phase * 0.8 + ft * 1.193) * h * 1.11, h);
        const CGFloat rr = 0.8 + std::fmod(ft * 11.0 + phase * 6.0, 1.0) * 1.5;
        NSRect dot = NSMakeRect(px - rr * 0.5, py - rr * 0.5, rr, rr);
        const CGFloat forensicDust = (_forensicEnabled ? (_forensicActivity * 0.10 + _forensicIntensity * 0.06) : 0.0);
        [[ArpSIDRGB(0.45 + forensicDust,0.88,1.00 - forensicDust * 0.6,0.06 + ft * 0.06 + peak * 0.07 + forensicDust) colorUsingColorSpace:[NSColorSpace genericRGBColorSpace]] setFill];
        [[NSBezierPath bezierPathWithOvalInRect:dot] fill];
    }

    NSDictionary* hudAttrs = @{ NSForegroundColorAttributeName: [NSColor colorWithWhite:1.0 alpha:0.86], NSFontAttributeName: monoBF(10.5) };
    NSDictionary* subAttrs = @{ NSForegroundColorAttributeName: ArpSIDRGB(0.62,0.90,1.00,0.82), NSFontAttributeName: monoF(10) };
    NSDictionary* labelAttrs = @{ NSForegroundColorAttributeName: ArpSIDRGB(0.80,0.86,0.96,0.88), NSFontAttributeName: monoBF(8.5) };
    [@"SID LIVE 3D REGISTER SURFACE" drawAtPoint:NSMakePoint(12.0, h - 20.0) withAttributes:hudAttrs];
    NSString* metrics = [NSString stringWithFormat:@"PEAK %.2f   RMS %.2f   MODE %@   MODEL %@", peak, rms, ArpSIDRenderModeString(_telemetry.renderMode), (_telemetry.sidModel==0?@"6581":@"8580")];
    [metrics drawAtPoint:NSMakePoint(12.0, h - 36.0) withAttributes:subAttrs];

    const CGFloat topHUDH = 46.0;
    const CGFloat filterPanelW = MIN(160.0, w * 0.24);
    const CGFloat margin = 12.0;
    const CGFloat contentY = margin;
    const CGFloat contentH = h - topHUDH - margin * 2.0;
    const CGFloat voiceAreaW = w - filterPanelW - margin * 3.0;
    const CGFloat cardGap = 10.0;
    const CGFloat cardW = MAX(120.0, (voiceAreaW - cardGap * 2.0) / 3.0);
    const CGFloat cardH = contentH;

    for (int i = 0; i < 3; ++i) {
        const int base = i * 7;
        const int ctrlIdx = base + 4;
        const uint16_t freq = (uint16_t)(((uint16_t)regs[base + 1] << 8) | regs[base + 0]);
        const uint16_t pw = (uint16_t)((((uint16_t)regs[base + 3] & 0x0Fu) << 8) | regs[base + 2]);
        const uint8_t ad = regs[base + 5];
        const uint8_t sr = regs[base + 6];
        const uint8_t ctrl = regs[ctrlIdx];
        const BOOL active = (_telemetry.vcoActiveMask & (1u << i)) != 0;
        NSColor* vc = [ArpSIDWaveformColor(ctrl) colorUsingColorSpace:[NSColorSpace genericRGBColorSpace]];
        if (!vc) vc = c64LtBlue();
        NSRect card = NSMakeRect(margin + i * (cardW + cardGap), contentY, cardW, cardH);

        for (int glow = 3; glow >= 1; --glow) {
            NSRect halo = NSInsetRect(card, -(CGFloat)glow * 3.0, -(CGFloat)glow * 2.0);
            [[vc colorWithAlphaComponent:(active ? 0.05 : 0.02) + peak * 0.03] setFill];
            [[NSBezierPath bezierPathWithRoundedRect:halo xRadius:12 + glow * 2 yRadius:12 + glow * 2] fill];
        }
        ArpSIDFillRoundedRect3D(card, ArpSIDRGB(0.09,0.11,0.18,0.96), 12.0);

        NSRect titleBand = NSMakeRect(NSMinX(card)+8.0, NSMaxY(card)-30.0, cardW-16.0, 22.0);
        ArpSIDFillRoundedRect3D(titleBand, vc, 8.0);
        NSDictionary* titleAttrs = @{ NSForegroundColorAttributeName:[NSColor whiteColor], NSFontAttributeName:monoBF(10.5) };
        NSString* title = [NSString stringWithFormat:@"VOICE %d  %@", i+1, active ? @"LIVE" : @"IDLE"];
        [title drawAtPoint:NSMakePoint(NSMinX(titleBand)+8.0, NSMinY(titleBand)+4.0) withAttributes:titleAttrs];

        NSDictionary* valueAttrs = @{ NSForegroundColorAttributeName:[NSColor colorWithWhite:1.0 alpha:0.88], NSFontAttributeName:monoBF(9.0) };
        [ArpSIDWaveName(ctrl) drawAtPoint:NSMakePoint(NSMinX(card)+12.0, NSMaxY(card)-52.0) withAttributes:@{NSForegroundColorAttributeName:vc, NSFontAttributeName:monoBF(9.5)}];

        // Waveform display is owned by the top rack; no duplicate scope here.
        const CGFloat waveY = NSMaxY(card) - 132.0;
        const CGFloat envGlow = ArpSIDClamp01((CGFloat)_telemetry.voiceEnvLevel[i]);
        NSRect laneRect = NSMakeRect(NSMinX(card)+12.0, waveY, cardW-24.0, 24.0);
        ArpSIDFillRoundedRect3D(laneRect, ArpSIDRGB(0.045,0.060,0.105,0.92), 8.0);
        NSRect laneFill = NSInsetRect(laneRect, 3.0, 3.0);
        laneFill.size.width = MAX(5.0, laneFill.size.width * MAX(envGlow, active ? 0.10 : 0.035));
        ArpSIDFillRoundedRect3D(laneFill, vc, 7.0);
        [[vc colorWithAlphaComponent:0.06 + envGlow * 0.14 + (active ? 0.05 : 0.0)] setFill];
        [[NSBezierPath bezierPathWithRoundedRect:NSInsetRect(laneRect, -5.0, -4.0) xRadius:14 yRadius:14] fill];

        const CGFloat barBaseY = NSMinY(card) + 72.0;
        const CGFloat barZoneH = MAX(34.0, waveY - barBaseY - 10.0);
        const CGFloat barW = 20.0;
        const CGFloat barGap = 11.0;
        const CGFloat barX0 = NSMinX(card) + 14.0;
        const CGFloat freqNorm = ArpSIDClamp01((CGFloat)freq / 65535.0);
        const CGFloat pwNorm = ArpSIDClamp01((CGFloat)pw / 4095.0);
        const CGFloat aNorm = ((CGFloat)((ad >> 4) & 0x0Fu)) / 15.0;
        const CGFloat dNorm = ((CGFloat)(ad & 0x0Fu)) / 15.0;
        const CGFloat sNorm = ((CGFloat)((sr >> 4) & 0x0Fu)) / 15.0;
        const CGFloat rNorm = ((CGFloat)(sr & 0x0Fu)) / 15.0;
        struct Bar { const char* label; CGFloat v; NSColor* c; } bars[] = {
            {"F", freqNorm, vc},
            {"P", pwNorm, ArpSIDRGB(1.00,0.80,0.28,1.0)},
            {"A", aNorm, ArpSIDRGB(0.35,0.95,0.55,1.0)},
            {"D", dNorm, ArpSIDRGB(0.30,0.78,1.00,1.0)},
            {"S", sNorm, ArpSIDRGB(1.00,0.46,0.82,1.0)},
            {"R", rNorm, ArpSIDRGB(1.00,0.56,0.36,1.0)},
        };
        for (int bi = 0; bi < 6; ++bi) {
            const CGFloat bx = barX0 + bi * (barW + barGap);
            NSRect slot = NSMakeRect(bx, barBaseY, barW, barZoneH);
            ArpSIDFillRoundedRect3D(slot, ArpSIDRGB(0.06,0.08,0.13,0.92), 6.0);
            NSRect fill = NSInsetRect(slot, 3.0, 3.0);
            ArpSIDDrawCubeBar(fill, bars[bi].c, bars[bi].v);
            NSString* lab = [NSString stringWithUTF8String:bars[bi].label];
            NSSize ts = [lab sizeWithAttributes:labelAttrs];
            [lab drawAtPoint:NSMakePoint(NSMidX(slot)-ts.width*0.5, NSMinY(card)+56.0) withAttributes:labelAttrs];
        }

        const CGFloat pillsX = NSMinX(card) + 12.0;
        const CGFloat pillsY = NSMinY(card) + 16.0;
        const CGFloat pillW = (cardW - 32.0) / 3.0;
        const CGFloat pillH = 16.0;
        ArpSIDDrawPill(NSMakeRect(pillsX + 0.0*(pillW+4.0), pillsY + pillH + 4.0, pillW, pillH), @"TRI", c64Cyan(), (ctrl & 0x10u) != 0u);
        ArpSIDDrawPill(NSMakeRect(pillsX + 1.0*(pillW+4.0), pillsY + pillH + 4.0, pillW, pillH), @"SAW", c64LtGreen(), (ctrl & 0x20u) != 0u);
        ArpSIDDrawPill(NSMakeRect(pillsX + 2.0*(pillW+4.0), pillsY + pillH + 4.0, pillW, pillH), @"PULSE", c64Yellow(), (ctrl & 0x40u) != 0u);
        ArpSIDDrawPill(NSMakeRect(pillsX + 0.0*(pillW+4.0), pillsY, pillW, pillH), @"NOISE", c64LtBlue(), (ctrl & 0x80u) != 0u);
        ArpSIDDrawPill(NSMakeRect(pillsX + 1.0*(pillW+4.0), pillsY, pillW, pillH), @"SYNC", ArpSIDRGB(0.55,1.0,0.80,1.0), (ctrl & 0x02u) != 0u);
        ArpSIDDrawPill(NSMakeRect(pillsX + 2.0*(pillW+4.0), pillsY, pillW, pillH), ((ctrl & 0x04u) ? @"RING" : ((ctrl & 0x08u)? @"TEST" : @"GATE")),
                       ((ctrl & 0x04u) ? ArpSIDRGB(1.0,0.58,0.72,1.0) : ((ctrl & 0x08u) ? ArpSIDRGB(1.0,0.60,0.30,1.0) : ArpSIDRGB(0.58,1.0,0.52,1.0))),
                       ((ctrl & 0x04u) || (ctrl & 0x08u) || (ctrl & 0x01u)) != 0u);

        NSString* freqText = [NSString stringWithFormat:@"FREQ %04X", (unsigned)freq];
        NSString* pwText = [NSString stringWithFormat:@"PW %03X", (unsigned)pw];
        [freqText drawAtPoint:NSMakePoint(NSMinX(card)+12.0, NSMaxY(card)-68.0) withAttributes:valueAttrs];
        [pwText drawAtPoint:NSMakePoint(NSMinX(card)+12.0, NSMaxY(card)-82.0) withAttributes:valueAttrs];
        [[NSString stringWithFormat:@"%@", ArpSIDADSRString(ad, sr)] drawAtPoint:NSMakePoint(NSMinX(card)+12.0, NSMaxY(card)-96.0) withAttributes:valueAttrs];
    }

    const CGFloat filterX = margin * 2.0 + cardW * 3.0 + cardGap * 2.0;
    NSRect filterPanel = NSMakeRect(filterX, contentY, filterPanelW, cardH);
    ArpSIDFillRoundedRect3D(filterPanel, ArpSIDRGB(0.09,0.10,0.16,0.96), 12.0);
    const CGFloat cutoff = std::clamp((((CGFloat)(regs[22] & 0x07u) * 256.0) + (CGFloat)regs[21]) / 2047.0, 0.0, 1.0);
    const CGFloat res = std::clamp(((CGFloat)(regs[23] >> 4) / 15.0), 0.0, 1.0);
    const CGFloat vol = std::clamp((CGFloat)(regs[24] & 0x0Fu) / 15.0, 0.0, 1.0);
    const NSString* filterMode = ArpSIDFilterModeString(regs[24]);
    [@"FILTER / MIX" drawAtPoint:NSMakePoint(NSMinX(filterPanel)+12.0, NSMaxY(filterPanel)-20.0) withAttributes:hudAttrs];
    [filterMode drawAtPoint:NSMakePoint(NSMinX(filterPanel)+12.0, NSMaxY(filterPanel)-36.0) withAttributes:@{NSForegroundColorAttributeName:ArpSIDRGB(1.00,0.86,0.32,0.92), NSFontAttributeName:monoBF(10)}];

    const CGFloat gaugeW = filterPanelW - 24.0;
    const CGFloat gaugeX = NSMinX(filterPanel) + 12.0;
    const CGFloat gaugeTop = NSMaxY(filterPanel) - 76.0;
    struct Gauge { NSString* label; CGFloat v; NSColor* c; } gauges[] = {
        {@"CUTOFF", cutoff, ArpSIDRGB(0.34,0.88,1.00,1.0)},
        {@"RES",    res,    ArpSIDRGB(1.00,0.76,0.26,1.0)},
        {@"VOL",    vol,    ArpSIDRGB(0.58,1.00,0.52,1.0)},
    };
    for (int gi = 0; gi < 3; ++gi) {
        const CGFloat gy = gaugeTop - gi * 48.0;
        [gauges[gi].label drawAtPoint:NSMakePoint(gaugeX, gy + 18.0) withAttributes:labelAttrs];
        NSRect slot = NSMakeRect(gaugeX, gy, gaugeW, 14.0);
        ArpSIDFillRoundedRect3D(slot, ArpSIDRGB(0.06,0.08,0.13,0.94), 7.0);
        NSRect fill = NSInsetRect(slot, 2.0, 2.0);
        fill.size.width = MAX(4.0, fill.size.width * gauges[gi].v);
        ArpSIDFillRoundedRect3D(fill, gauges[gi].c, 6.0);
    }

    const CGFloat stageY = NSMinY(filterPanel) + 54.0;
    NSRect stage = NSMakeRect(gaugeX, stageY, gaugeW, 84.0);
    ArpSIDFillRoundedRect3D(stage, ArpSIDRGB(0.06,0.08,0.13,0.94), 10.0);
    const CGFloat speakerW = gaugeW * (0.18 + cutoff * 0.18);
    const CGFloat speakerH = 16.0 + res * 26.0 + peak * 8.0;
    for (int i = 0; i < 3; ++i) {
        const CGFloat sx = NSMidX(stage) + ((CGFloat)i - 1.0) * (speakerW + 10.0) * 0.72 - speakerW * 0.5;
        const CGFloat sy = NSMidY(stage) - speakerH * 0.5 + std::sin((phase + i * 0.21) * 6.28318530718) * 3.0;
        ArpSIDFillRoundedRect3D(NSMakeRect(sx, sy, speakerW, speakerH), ArpSIDRGB(1.0,0.88,0.30,0.85), 5.0);
    }

    NSDictionary* regAttrs = @{ NSForegroundColorAttributeName:ArpSIDRGB(0.75,0.88,1.00,0.88), NSFontAttributeName:monoBF(9.0) };
    [[NSString stringWithFormat:@"FC %02X %02X", regs[21], regs[22]] drawAtPoint:NSMakePoint(gaugeX, NSMinY(filterPanel)+32.0) withAttributes:regAttrs];
    [[NSString stringWithFormat:@"RES/FLT %02X", regs[23]] drawAtPoint:NSMakePoint(gaugeX, NSMinY(filterPanel)+20.0) withAttributes:regAttrs];
    [[NSString stringWithFormat:@"MODE/VOL %02X", regs[24]] drawAtPoint:NSMakePoint(gaugeX, NSMinY(filterPanel)+8.0) withAttributes:regAttrs];
}
@end

// One persisted tab identity is shared by the model contract and Cocoa runtime.
using ArpSIDTab = ArpSID::GUI::ArpSIDTab;
static constexpr ArpSIDTab ArpSIDTabMain = ArpSIDTab::Main;
static constexpr ArpSIDTab ArpSIDTabLfoArp = ArpSIDTab::LfoArp;
static constexpr ArpSIDTab ArpSIDTabSidProjection = ArpSIDTab::LegacySidProjection;
static constexpr ArpSIDTab ArpSIDTabSidReg = ArpSIDTab::SidRegisters;
static constexpr ArpSIDTab ArpSIDTabSeq = ArpSIDTab::Sequencer;
static constexpr ArpSIDTab ArpSIDTabFilter = ArpSIDTab::Filter;
static constexpr ArpSIDTab ArpSIDTabMacro = ArpSIDTab::Macro;
static constexpr ArpSIDTab ArpSIDTabForensic = ArpSIDTab::Forensic;
static constexpr ArpSIDTab ArpSIDTabSidCore = ArpSIDTab::SidCore;
static constexpr ArpSIDTab ArpSIDTabBank = ArpSIDTab::Bank;
static constexpr ArpSIDTab ArpSIDTabOptions = ArpSIDTab::Options;
static constexpr ArpSIDTab ArpSIDTabC64 = ArpSIDTab::C64;
static constexpr ArpSIDTab ArpSIDTabHiFi = ArpSIDTab::HiFi;
static constexpr ArpSIDTab ArpSIDTabDrsid = ArpSIDTab::DrSid;
static constexpr ArpSIDTab ArpSIDTabSettingsV544 = ArpSIDTab::Settings;
static constexpr ArpSIDTab ArpSIDTabC64StateV544 = ArpSIDTab::C64State;
static constexpr ArpSIDTab ArpSIDTabMixV547 = ArpSIDTab::Mix;
static constexpr ArpSIDTab ArpSIDTabKitV555 = ArpSIDTab::Kit;
static constexpr ArpSIDTab ArpSIDTabDigiV563 = ArpSIDTab::Digi;

// Visible-tab arrays. keeps one canonical, deterministic production
// ring and flavor aliases that intentionally point at the same tab order. This
// visible ring is never from a stale hard-coded bootstrap table. It removes
// the remaining split-brain risk from four copy/pasted 18-entry arrays:
// a future tab insertion now has one authority and compile-time guards prove
// there are no duplicate visible tabs and that the legacy SID projection tab is
// never exposed in the segmented UI.
static constexpr const auto& kArpSIDProductionVisibleTabs_v269 =
    ArpSID::GUI::kProductionVisibleTabs;

template <size_t N>
static NSInteger ArpSIDVisibleTabSegmentInSet(const std::array<ArpSIDTab, N>& tabs, ArpSIDTab tab) {
    for (size_t i = 0; i < N; ++i) {
        if (tabs[i] == tab) return (NSInteger)i;
    }
    return -1;
}

static const auto& ArpSIDVisibleTabSetForFlavor_v269(ArpSID::ComponentFlavor flavor) noexcept {
    (void)flavor;
    return kArpSIDProductionVisibleTabs_v269;
}

static NSInteger ArpSIDVisibleTabCountForFlavor(ArpSID::ComponentFlavor flavor) {
    return (NSInteger)ArpSIDVisibleTabSetForFlavor_v269(flavor).size();
}

static ArpSIDTab ArpSIDVisibleTabForFlavorAtIndex(ArpSID::ComponentFlavor flavor, NSInteger index) {
    const auto& tabs = ArpSIDVisibleTabSetForFlavor_v269(flavor);
    return tabs[(size_t)std::clamp(index, (NSInteger)0, (NSInteger)tabs.size() - 1)];
}

static NSInteger ArpSIDVisibleTabSegmentForFlavor(ArpSID::ComponentFlavor flavor, ArpSIDTab tab) {
    return ArpSIDVisibleTabSegmentInSet(ArpSIDVisibleTabSetForFlavor_v269(flavor), tab);
}

static ArpSIDTab ArpSIDCanonicalVisibleTabForFlavor(ArpSID::ComponentFlavor flavor, ArpSIDTab requested) {
    if (ArpSIDVisibleTabSegmentForFlavor(flavor, requested) >= 0) return requested;
    // Stable persisted IDs remain accepted after their visible surfaces retire.
    // The old projection tab maps to SIDCORE; the removed C64 diagnostics tab
    // maps to the main C64 player/cockpit instead of dumping restored projects
    // onto an unrelated flavor default.
    if (requested == ArpSIDTabSidProjection) return ArpSIDTabSidCore;
    if (requested == ArpSIDTabC64StateV544) return ArpSIDTabC64;
    switch (flavor) {
        case ArpSID::ComponentFlavor::Instrument:
            return ArpSIDTabMain;
        case ArpSID::ComponentFlavor::DrumMachine:
        case ArpSID::ComponentFlavor::Sid808:
            return ArpSIDTabSeq;
        case ArpSID::ComponentFlavor::Hybrid:
        default:
            return ArpSIDTabMain;
    }
}

static NSString* ArpSIDTabBarTooltipForFlavor(ArpSID::ComponentFlavor flavor) {
    switch (flavor) {
        case ArpSID::ComponentFlavor::Instrument:
            return @"Pure Instrument navigation. All production tabs stay visible; the instrument flavor still owns the audio defaults.";
        case ArpSID::ComponentFlavor::DrumMachine:
            return @"Drum Machine navigation. KIT, MOD, SID bus, filter, forensic, bank, and options stay in the dedicated drum ring.";
        case ArpSID::ComponentFlavor::Sid808:
            return @"SID-808 navigation. All production tabs stay visible; the SID-808 flavor still owns the audio defaults.";
        case ArpSID::ComponentFlavor::Hybrid:
        default:
            return @"ArpSID Classic navigation. Classic, SID register, DrSID aux, SIDCORE/C64, forensic, bank, and options tabs stay available.";
    }
}


// single source of truth for the segmented tab bar. Earlier builds
// bootstrapped the bar with an obsolete 11-segment table and then relied on a
// later chrome refresh to expand it to the real production ring; that
// created transient duplicate labels and stale tooltips in embedded hosts.
static CGFloat ArpSIDTabSegmentWidthForLabel_v269(NSString* label) {
    const NSUInteger len = label.length;
    if (len <= 7u) return 58.0;
    if (len <= 10u) return 70.0;
    if (len <= 13u) return 82.0;
    return 94.0;
}

static void ArpSIDSetTabSegmentWidthIfChanged_v321(NSSegmentedControl* tabBar,
                                                    NSInteger segment,
                                                    CGFloat desiredWidth) {
    const CGFloat currentWidth = [tabBar widthForSegment:segment];
    if (!std::isfinite((double)currentWidth) ||
        fabs(currentWidth - desiredWidth) > 0.5f) {
        [tabBar setWidth:desiredWidth forSegment:segment];
    }
}

static void ArpSIDFitVisibleTabBarWidths_v320(NSSegmentedControl* tabBar) {
    if (!tabBar || tabBar.segmentCount <= 0) return;
    const CGFloat available = NSWidth(tabBar.bounds);
    if (!(available > 0.0f)) return;
    // PERF (v823): -layout/-viewDidLayout runs this on every pass. Each
    // -widthForSegment:/-setWidth:forSegment: below drives a SwiftUI/AttributeGraph
    // relayout on macOS 26, and those results feed straight back into layout — so
    // re-fitting on every pass churns the main thread for seconds when the editor is
    // laid out at a host's large out-of-process container size (Logic then reports
    // the AU as making the system unstable). Re-fit only when the bar width actually
    // changes; ArpSIDConfigureVisibleTabBar_v268 zeroes the cache when labels change.
    if ([tabBar isKindOfClass:[ArpSIDSegmentedToolTipControl class]]) {
        ArpSIDSegmentedToolTipControl* c = (ArpSIDSegmentedToolTipControl*)tabBar;
        if (c.tabFitLastAvailable_v823 > 0.0f &&
            fabs((double)c.tabFitLastAvailable_v823 - (double)available) <= 0.5) return;
        c.tabFitLastAvailable_v823 = available;
    }
    CGFloat naturalTotal = 0.0f;
    for (NSInteger seg = 0; seg < tabBar.segmentCount; ++seg) {
        naturalTotal += ArpSIDTabSegmentWidthForLabel_v269([tabBar labelForSegment:seg]);
    }
    if (!(naturalTotal > 0.0f)) return;
    const CGFloat scale = std::min<CGFloat>(1.0f, available / naturalTotal);
    for (NSInteger seg = 0; seg < tabBar.segmentCount; ++seg) {
        const CGFloat natural = ArpSIDTabSegmentWidthForLabel_v269([tabBar labelForSegment:seg]);
        const CGFloat desired = std::max<CGFloat>(36.0f, floor(natural * scale));
        ArpSIDSetTabSegmentWidthIfChanged_v321(tabBar, seg, desired);
    }
}

static void ArpSIDConfigureVisibleTabBar_v268(NSSegmentedControl* tabBar,
                                               ArpSID::ComponentFlavor flavor,
                                               NSInteger modeIndex) {
    if (!tabBar) return;
    const NSInteger visibleTabCount = ArpSIDVisibleTabCountForFlavor(flavor);
    BOOL tabGeometryChanged_v823 = NO;
    if (tabBar.segmentCount != visibleTabCount) {
        tabBar.segmentCount = visibleTabCount;
        tabGeometryChanged_v823 = YES;
    }
    tabBar.toolTip = ArpSIDTabBarTooltipForFlavor(flavor);
    tabBar.accessibilityLabel = @"ArpSID tab navigation";
    tabBar.accessibilityHelp = tabBar.toolTip;
    NSMutableArray<NSString*>* tabTips = [NSMutableArray arrayWithCapacity:(NSUInteger)visibleTabCount];
    NSMutableArray<NSString*>* tabA11y = [NSMutableArray arrayWithCapacity:(NSUInteger)visibleTabCount];
    for (NSInteger seg = 0; seg < visibleTabCount; ++seg) {
        const ArpSIDTab tab = ArpSIDVisibleTabForFlavorAtIndex(flavor, seg);
        NSString* label = ArpSIDTabLabelForMode((NSInteger)tab, modeIndex, flavor);
        NSString* tip = ArpSIDTabTooltipForMode((NSInteger)tab, modeIndex, flavor);
        if (![[tabBar labelForSegment:seg] isEqualToString:label]) {
            [tabBar setLabel:label forSegment:seg];
            tabGeometryChanged_v823 = YES;
        }
        if (![tabBar isEnabledForSegment:seg])
            [tabBar setEnabled:YES forSegment:seg];
        [tabTips addObject:(tip.length > 0 ? tip : @"Navigation tab")];
        [tabA11y addObject:[NSString stringWithFormat:@"%ld:%@", (long)(seg + 1), label]];
    }
    // Labels/segment count change natural widths. Do not reset this on ordinary
    // chrome refreshes: Logic's out-of-process AU view can call this path during
    // layout/poll churn, and forcing a re-fit re-enters NSSegmentedControl's
    // SwiftUI-backed geometry engine.
    if (tabGeometryChanged_v823 && [tabBar isKindOfClass:[ArpSIDSegmentedToolTipControl class]])
        ((ArpSIDSegmentedToolTipControl*)tabBar).tabFitLastAvailable_v823 = 0.0f;
    ArpSIDFitVisibleTabBarWidths_v320(tabBar);
    tabBar.accessibilityValue = [tabA11y componentsJoinedByString:@", "];
    if ([tabBar isKindOfClass:[ArpSIDSegmentedToolTipControl class]]) {
        [(ArpSIDSegmentedToolTipControl*)tabBar setSegmentToolTips:tabTips];
    }
}

// DIGI conversion mode must be declared before the Objective-C
// class-extension ivar block. AUv2 compiles ArpSIDViewController.mm as one
// translation unit; declaring this enum near the late DIGI helper functions
// made the _digiConvertMode_v199_ ivar an unknown type during real AUv2 builds.
enum class ArpSIDDigiConvertMode_v199 : std::uint8_t {
    Linear = 0u,
    Loud = 1u,
    MuLaw = 2u,
    Dither = 3u,
};

