// audit P0-11: the CVDisplayLink output callback fires on a high-priority CoreVideo
// thread and previously received `(__bridge void*)self` — a RAW, unretained
// controller pointer. If a callback was in flight while the controller tore down,
// it dereferenced freed memory (use-after-free). Instead the callback context is a
// heap box that holds a ZEROING __weak reference to the controller. The box is
// owned via a retained raw pointer (_displayLinkCtx) and released only after the
// link is stopped and released. The callback weak-loads the controller: ARC returns
// nil once the controller has begun deallocating, so the callback can never touch a
// freed controller.
@interface ArpSIDDisplayLinkContext : NSObject
@property (atomic, weak) ArpSIDViewController* controller;
@end
@implementation ArpSIDDisplayLinkContext
@end

// audit #31: AudioQueue input callbacks are C callbacks on CoreAudio-owned
// threads. Keep the same weak-box lifetime pattern as CVDisplayLink: the
// callback weak-loads a controller and therefore never dereferences a freed
// ArpSIDViewController even if REC/MON teardown races with callback entry.
@interface ArpSIDDigiAQControllerContext : NSObject
@property (atomic, weak) ArpSIDViewController* controller;
@end
@implementation ArpSIDDigiAQControllerContext
@end

static void ArpSIDReleaseRetainedObjCContext_v777(void*& ctx) noexcept {
    if (!ctx) return;
    id __unused released = (__bridge_transfer id)ctx;
    ctx = nullptr;
}

static ArpSIDViewController* ArpSIDDigiAQControllerFromContext_v777(void* ctx) noexcept {
    ArpSIDDigiAQControllerContext* box = (__bridge ArpSIDDigiAQControllerContext*)ctx;
    if (!box) return nil;
    return box.controller;
}

static CVReturn ArpSIDVCDisplayLinkCallback(CVDisplayLinkRef __unused link,
                                            const CVTimeStamp* __unused now,
                                            const CVTimeStamp* __unused output,
                                            CVOptionFlags __unused flagsIn,
                                            CVOptionFlags* __unused flagsOut,
                                            void* ctx) {
    ArpSIDDisplayLinkContext* box = (__bridge ArpSIDDisplayLinkContext*)ctx;
    if (!box) return kCVReturnSuccess;
    // Zeroing-weak load: a strong local that is non-nil ONLY if the controller is
    // still alive (and now retained for the duration of this callback).
    ArpSIDViewController* vc = box.controller;
    if (!vc) return kCVReturnSuccess;
    if ([vc _isControllerTearingDown_v277_] || [vc _isEditorRuntimePaused_v322_])
        return kCVReturnSuccess;
    // v822: if this link is free-running (no real display timing, e.g. a headless
    // out-of-process AU host), detect the super-display firing rate and hand the
    // editor over to a bounded main-thread timer instead of spinning this IO thread.
    if ([vc _displayLinkTickIsFreeRunning_v822_]) return kCVReturnSuccess;
    // Backpressure: skip this vsync tick if the previous _poll has not yet run on
    // the main thread. This bounds the main queue to a single pending poll so a
    // stalled/busy main thread drops frames cleanly instead of building a backlog.
    if (![vc _tryBeginPollTick_v246_]) return kCVReturnSuccess;
    __weak ArpSIDViewController* weakForDispatch = vc;
    dispatch_async(dispatch_get_main_queue(), ^{
        ArpSIDViewController* strongForDispatch = weakForDispatch;
        if (!strongForDispatch) return;
        @try {
            if (![strongForDispatch _isControllerTearingDown_v277_] &&
                ![strongForDispatch _isEditorRuntimePaused_v322_]) {
                [strongForDispatch _poll];
            }
        } @finally {
            [strongForDispatch _endPollTick_v246_];
        }
    });
    return kCVReturnSuccess;
}

