- (void)_surfaceDisconnectedStateForAction:(NSString*)action {
    NSString* const label = action.length ? action : @"operation";
    NSString* const msg = [NSString stringWithFormat:@"AU disconnected — %@ skipped", label];
    if (_presentationHUDLabel) ArpSIDSetLabelStringIfNeeded(_presentationHUDLabel, msg);
    if (_digiRuntimeHUDLabel) ArpSIDSetLabelStringIfNeeded(_digiRuntimeHUDLabel, @"DIGI offline — AU bridge disconnected");
    if (_drumHUDLabel) ArpSIDSetLabelStringIfNeeded(_drumHUDLabel, @"DrSID offline — AU bridge disconnected");
    if (_bankHeaderLabel) _bankHeaderLabel.toolTip = msg;
}

- (BOOL)_requireBridgeForAction:(NSString*)action {
    if (_au) return YES;
    [self _surfaceDisconnectedStateForAction:action];
    return NO;
}

- (void)_digiAuditAndRepairSampleBankForUIReason:(NSString*)reason {
    const bool bankWasWellFormed = ArpSID::GUI::digiSampleBankIsWellFormed(_digiSampleBank_v596_);
    const bool modelWasWellFormed = ArpSID::GUI::digiPanelIsWellFormed(_digiModel_v563_);
    ArpSID::GUI::sanitizeDigiSampleBankBlob(_digiSampleBank_v596_);
    ArpSID::GUI::sanitizeDigiPanelModel(_digiModel_v563_);
    ArpSID::GUI::digiRepairUserSampleReferences(_digiModel_v563_, _digiSampleBank_v596_);
    const bool repaired = !bankWasWellFormed || !modelWasWellFormed;
    if (repaired && _digiRuntimeHUDLabel) {
        NSString* const why = reason.length ? reason : @"DIGI state";
        ArpSIDSetLabelStringIfNeeded(_digiRuntimeHUDLabel,
            [NSString stringWithFormat:@"DIGI repaired %@ — corrupted sample bank/model sanitized", why]);
        _digiRuntimeHUDLabel.toolTip = @"The imported/restored DIGI state was not well-formed. ArpSID sanitized the sample bank/model, repaired missing user-sample handles, and published only the repaired state.";
    }
}

