-(void)setAudioUnit:(AUAudioUnit*)au{[self _connectBridgeInternal:(id<ArpSIDUIBridgeLike>)au];}
-(void)connectAudioUnit:(AUAudioUnit*)au{
    if(au) ARPSID_UI_LOG(@"[ArpSIDVC] connectAudioUnit:%@", au);
    else ARPSID_UI_LOG(@"[ArpSIDVC] connectAudioUnit deferred (AU not ready yet)");
    [self _connectBridgeInternal:(id<ArpSIDUIBridgeLike>)au];
    if(au && self.isViewLoaded) [self.view setNeedsDisplay:YES];
}

-(void)connectBridge:(id)bridge{
