        if (adapter2 && [adapter2 respondsToSelector:@selector(getKitStateBlob:)]) {
            [self _pullKitStateFromAdapter_v560_];
        }
        if (adapter2 && [adapter2 respondsToSelector:@selector(getMixModel:)]) {
