}

-(void)loadView{
    ARPSID_UI_LOG(@"[ArpSIDVC] loadView begin");
    _ev=[[ArpSIDEditorView alloc]initWithFrame:NSMakeRect(0,0,kW,kH)];
    _ev.lifecycleOwner=self;
    _ev.wantsLayer=YES;
    _ev.layer.backgroundColor = NSColor.blackColor.CGColor;
    _ev.autoresizingMask=NSViewWidthSizable|NSViewHeightSizable;
    self.view=_ev;
    ArpSIDSetPreferredContentSizeOnMainThread(self, NSMakeSize(kW,kH));
    if(!_knobs) _knobs=[NSMutableArray array];
    if(!_knobMap) _knobMap=[NSMutableDictionary dictionary];
#if defined(ARPSID_AUV2_COMPONENT)
    _deferAuv2OOPEditorBuild_v831 = ArpSIDShouldDeferAuv2OOPBootstrap_v831();
    if(_deferAuv2OOPEditorBuild_v831 && !_built){
        [self _installAuv2BootstrapBootCover_v831_];
        [self _scheduleDeferredAuv2EditorBuild_v831_];
    } else if(!_built) {
        [self _buildUI];
        _built=YES;
    }
#else
    if(!_built){ [self _buildUI]; _built=YES; }
#endif
    ARPSID_UI_LOG(@"[ArpSIDVC] loadView end view=%@ built=%d", self.view, (int)_built);
}

