-(void)viewDidLoad{
    ARPSID_UI_LOG(@"[ArpSIDVC] viewDidLoad begin");
    [super viewDidLoad];
    if(!_built){
#if defined(ARPSID_AUV2_COMPONENT)
        if(_deferAuv2OOPEditorBuild_v831) {
            [self _installAuv2BootstrapBootCover_v831_];
            [self _scheduleDeferredAuv2EditorBuild_v831_];
        }
        else { [self _buildUI]; _built=YES; }
#else
        [self _buildUI];_built=YES;
#endif
    }
    [self _registerCoreNotificationObservers_v322_];
    // NOTE: the /247 experiment that fully STOPPED the
    // CVDisplayLink on NSWindowDidChangeOcclusionState/Miniaturize was reverted.
    // Several AU hosts embed the plugin view in a window that never posts a
    // reliable "visible again" notification, so the link could stop and never
    // restart — freezing the whole UI (C64 SID player readout, scopes, meters)
    // and reading as "player stopped working". The cheap, self-correcting
    // occlusion early-return inside _poll (which re-evaluates every vsync and
    // resumes automatically) plus the _pollInFlight coalescing gate give the same
    // idle savings without the permanent-freeze hazard, so no occlusion observers
    // are registered here.
    ARPSID_UI_LOG(@"[ArpSIDVC] viewDidLoad end built=%d knobs=%lu", (int)_built, (unsigned long)_knobs.count);
}
-(void)viewDidLayout{
    [super viewDidLayout];
    NSRect b=self.view.bounds;
    ARPSID_UI_LOG(@"[ArpSIDVC] viewDidLayout bounds=%@", NSStringFromRect(b));
    if(b.size.width<100||b.size.height<100){ ARPSID_UI_LOG(@"[ArpSIDVC] viewDidLayout skipped tiny bounds"); return; }
    const CGFloat sx=b.size.width/kW, sy=b.size.height/kH;
    if(!std::isfinite((float)sx)||!std::isfinite((float)sy)) return;
    CGFloat s = MIN(MAX(MIN(sx,sy), 0.25), 4.0);
    if(!CGPointEqualToPoint(_ev.layer.anchorPoint,CGPointMake(0,0)))
        _ev.layer.anchorPoint=CGPointMake(0,0);
    if(!CGPointEqualToPoint(_ev.layer.position,CGPointMake(0,0)))
        _ev.layer.position=CGPointMake(0,0);
    NSScreen* screen = (self.view.window.screen != nil) ? self.view.window.screen : NSScreen.mainScreen;
    const CGFloat backingScale = screen ? screen.backingScaleFactor : 1.0;
    _ev.layer.contentsScale = backingScale;
    _ev.layer.shouldRasterize = (s < 1.0);
    _ev.layer.rasterizationScale = backingScale;
    if(!_hasLastEditorScale || fabs(_lastEditorScale - s) > 0.001){
        _ev.layer.transform=CATransform3DMakeScale(s,s,1.0);
        _lastEditorScale=s;
        _hasLastEditorScale=YES;
    }
    const NSRect integralFrame=NSIntegralRect(_ev.frame);
    if(!NSEqualRects(_ev.frame,integralFrame)) _ev.frame=integralFrame;
    [self _layoutEmbeddedNavigation];
    if(_built) [self _layoutMainChromeControls];
    [self _scheduleDeferredAuv2EditorBuild_v831_];
    // v828: AUv2 remote hosts can attach the NSRemoteView to a window after
    // viewDidAppear. Re-arm the delayed release here; the helper still yields
    // before it constructs any queued heavy tab.
    if(!_firstEditorPaintCompleted_v826 && self.view.window)
        [self _scheduleFirstPaintFenceRelease_v827_];
    ARPSID_UI_LOG(@"[ArpSIDVC] applied GUI scale=%f", s);
}

