-(void)_storeCachedParamValue:(int)pid value:(float)value{
    if(pid < 0 || pid >= (int)ArpSID::kNumParams) return;
    const float clean = ArpSIDUIClamp01(value, ArpSID::defaultNormalizedParamValue(pid));
    _paramCache[(size_t)pid].store(clean, std::memory_order_relaxed);
    _paramCacheValid[(size_t)pid].store(1u, std::memory_order_relaxed);
}

-(float)_cachedParamValue:(int)pid defaultCenter:(float)center{
    if(pid < 0 || pid >= (int)ArpSID::kNumParams) return ArpSIDUIClamp01(center, center);
    // Program/BankSlot are sticky preset readback values. Never serve
    // them from the UI cache; cache can contain stale GM/program slot 0 echoes.
    if(pid == ArpSID::kParamBankSlot || pid == ArpSID::kParamProgram){
        id<ArpSIDUIBridgeLike> au=_au;
        const float fetched = au ? [au getParameterValue:pid] : center;
        [self _storeCachedParamValue:pid value:fetched];
        return ArpSIDUIClamp01(fetched, center);
    }
    if(_paramCacheValid[(size_t)pid].load(std::memory_order_relaxed) == 0u){
        id<ArpSIDUIBridgeLike> au=_au;
        const float fetched = au ? [au getParameterValue:pid] : ArpSID::defaultNormalizedParamValue(pid);
        [self _storeCachedParamValue:pid value:fetched];
    }
    return ArpSIDUIClamp01(_paramCache[(size_t)pid].load(std::memory_order_relaxed), center);
}

-(void)_primeParameterCacheFromBridge:(id<ArpSIDUIBridgeLike>)bridge{
    if(!bridge) return;
    for(int pid=0; pid < (int)ArpSID::kNumParams; ++pid){
        [self _storeCachedParamValue:pid value:[bridge getParameterValue:pid]];
    }
}

