-(void)_sidCoreTogglePopout:(id)sender{
    (void)sender;
    if(_sidCorePopoutWindow && _sidCorePopoutWindow.visible) {
        [self _removeSidCorePopoutObservers_v279_];
        if ((_sidCorePopoutWindow.styleMask & NSWindowStyleMaskFullScreen) != 0) {
            [_sidCorePopoutWindow toggleFullScreen:nil];
        }
        if (_sidCorePopoutMetalView) [_sidCorePopoutMetalView prepareForTeardown];
        [_sidCorePopoutWindow orderOut:nil];
        _sidCorePopoutWindow.contentView = nil;
        _sidCorePopoutWindow = nil;
        _sidCorePopoutMetalView = nil;
        [_sidCorePopoutButton setTitle:@"⤢ POP OUT"];
        return;
    }
    // Initial size: target ~80% of the visible screen so the SIDCORE 3D
    // matrix has real estate. The window is fully resizable and can be
    // toggled to true fullscreen via Cmd-F (ArpSIDSidCorePopoutWindow
    // performKeyEquivalent — v962: the subclass now actually exists) or the
    // standard green traffic-light button.
    NSScreen* targetScreen = self.view.window.screen ? self.view.window.screen : NSScreen.mainScreen;
    const NSRect screenFrame = targetScreen ? targetScreen.visibleFrame : NSMakeRect(0,0,1440,900);
    const CGFloat initW = std::max<CGFloat>(900, NSWidth(screenFrame)  * 0.80);
    const CGFloat initH = std::max<CGFloat>(620, NSHeight(screenFrame) * 0.80);
    const NSUInteger styleMask = NSWindowStyleMaskTitled | NSWindowStyleMaskResizable |
                                 NSWindowStyleMaskClosable | NSWindowStyleMaskMiniaturizable;
    NSRect contentRect = NSMakeRect(0, 0, initW, initH);
    _sidCorePopoutWindow = [[ArpSIDSidCorePopoutWindow alloc] initWithContentRect:contentRect styleMask:styleMask
                                                                          backing:NSBackingStoreBuffered defer:NO];
    _sidCorePopoutWindow.title = @"ArpSID · SIDCORE Matrix 3D · OpenBus (Cmd-F fullscreen)";
    _sidCorePopoutWindow.collectionBehavior = NSWindowCollectionBehaviorFullScreenPrimary |
                                              NSWindowCollectionBehaviorFullScreenAllowsTiling;
    _sidCorePopoutWindow.contentMinSize = NSMakeSize(480, 320);
    _sidCorePopoutWindow.backgroundColor = [NSColor blackColor];
    _sidCorePopoutWindow.releasedWhenClosed = NO;
    // Hide title-bar chrome in fullscreen so the SIDCORE matrix fills the
    // screen edge-to-edge without a translucent bar at the top.
    _sidCorePopoutWindow.titlebarAppearsTransparent = YES;
    _sidCorePopoutMetalView = [[ArpSIDSidCoreMetalBackdropView alloc] initWithFrame:NSMakeRect(0,0,contentRect.size.width,contentRect.size.height)];
    _sidCorePopoutMetalView.autoresizingMask = NSViewWidthSizable | NSViewHeightSizable;
    [_sidCorePopoutWindow.contentView addSubview:_sidCorePopoutMetalView];
    // Centre on screen containing the plugin window, or main screen as fallback.
    if (targetScreen) {
        NSRect wf = _sidCorePopoutWindow.frame;
        NSPoint origin = NSMakePoint(NSMidX(screenFrame) - wf.size.width * 0.5,
                                     NSMidY(screenFrame) - wf.size.height * 0.5);
        [_sidCorePopoutWindow setFrameOrigin:origin];
    }
    // Track fullscreen transitions with explicit observer tokens.
    // Block-based observers are retained by NSNotificationCenter until their
    // token is removed; storing/removing tokens avoids leaks and zombie UI
    // callbacks after AU unload/window close.
    [self _removeSidCorePopoutObservers_v279_];
    __weak ArpSIDViewController* weakSelf = self;
    _sidCorePopoutEnterFullScreenObserver_v278 = [[NSNotificationCenter defaultCenter] addObserverForName:NSWindowDidEnterFullScreenNotification
                                                                                                    object:_sidCorePopoutWindow
                                                                                                     queue:[NSOperationQueue mainQueue]
                                                                                                usingBlock:^(NSNotification* note){
        (void)note;
        ArpSIDViewController* s = weakSelf;
        if (!s) return;
        if (s->_controllerTearingDown_v277_.load(std::memory_order_acquire)) return;
        if (!s->_sidCorePopoutWindow) return;
        s->_sidCorePopoutWindow.contentMinSize = NSMakeSize(1, 1);
        [s->_sidCorePopoutButton setTitle:@"✕ EXIT FS"];
    }];
    _sidCorePopoutExitFullScreenObserver_v278 = [[NSNotificationCenter defaultCenter] addObserverForName:NSWindowDidExitFullScreenNotification
                                                                                                   object:_sidCorePopoutWindow
                                                                                                    queue:[NSOperationQueue mainQueue]
                                                                                               usingBlock:^(NSNotification* note){
        (void)note;
        ArpSIDViewController* s = weakSelf;
        if (!s) return;
        if (s->_controllerTearingDown_v277_.load(std::memory_order_acquire)) return;
        if (!s->_sidCorePopoutWindow) return;
        s->_sidCorePopoutWindow.contentMinSize = NSMakeSize(480, 320);
        [s->_sidCorePopoutButton setTitle:@"✕ CLOSE OUT"];
    }];
    [_sidCorePopoutWindow makeKeyAndOrderFront:nil];
    [_sidCorePopoutButton setTitle:@"✕ CLOSE OUT"];
}

// Toggle the SIDCORE popout window between standard and fullscreen modes.
// Bound from a keyboard accelerator and/or a menu item; safe to call from
// the main thread at any time. If the popout isn't visible yet it opens
// the popout and immediately fullscreens it.
