// createAudioUnitWithComponentDescription: — AUAudioUnitFactory protocol method.
//
// AUv3 standalone host / AUv3 extension path:
// Called by the AUv3 framework when the VC acts as its own factory.
// Creates a fresh ArpSIDAudioUnit, stores it as _au, and returns it.
//
// AUv2 component path:
// The ArpSIDAUv2CocoaViewFactory already obtained the ArpSIDAudioUnit via
// +[AUAudioUnit audioUnitForAudioUnit:] and passed it to connectAudioUnit:.
// Calling this method again here would create a SECOND, completely independent
// DSP engine with its own kernel, voice state, and parameter tree — the two
// engines would immediately diverge and produce incorrect audio.
// Return the already-connected AU instance (or nil if none yet) so the
// AUAudioUnitFactory protocol is satisfied without spawning a second engine.
//
// VST3 Cocoa bridge path:
// No AU needed. Return nil.
#if defined(ARPSID_AUV2_COMPONENT)
-(AUAudioUnit*)createAudioUnitWithComponentDescription:(AudioComponentDescription)d error:(NSError*__autoreleasing*)e{
    (void)d;
    if (e) *e = nil;
    // Return the already-connected instance set by connectAudioUnit:/setAudioUnit:.
    // If somehow called before connection (should not happen under normal AUv2 host
    // operation), return nil rather than spawning a second independent engine.
    return (AUAudioUnit*)_au;
}
#elif defined(ARPSID_VST_COCOA_BRIDGE)
-(AUAudioUnit*)createAudioUnitWithComponentDescription:(AudioComponentDescription)d error:(NSError*__autoreleasing*)e{
    (void)d;
    if (e) *e = nil;
    return nil;
}
#else
-(AUAudioUnit*)createAudioUnitWithComponentDescription:(AudioComponentDescription)d error:(NSError*__autoreleasing*)e{
    ArpSIDAudioUnit* created = [[ArpSIDAudioUnit alloc] initWithComponentDescription:d options:0 error:e];
    _au = (id<ArpSIDUIBridgeLike>)created;
    self.audioUnit = created;
    return created;
}
#endif


-(void)_layoutEmbeddedNavigation{
    if(!_built||!self.view) return;
    NSView* root=self.view;
    const CGFloat sl=kBW;
    const CGFloat rootW=std::max((CGFloat)kW, root.bounds.size.width);
    const CGFloat btnW=24.f;
    const CGFloat gap=4.f;

    // Dedicated navigation lane above the raised footer. It no longer overlays
    // the bottom edge of tab content.
    const CGFloat navY=kBW+kBottomSafeInset+kFtrH+4.f;
    const CGFloat rowLeft=sl+4.f;
    const CGFloat rowRight=rootW-kBW-4.f;
    const CGFloat voiceW=188.f;
    const CGFloat arpW=220.f;
    const CGFloat transpW=136.f;
    const CGFloat clusterW=transpW+gap+arpW+gap+voiceW;
    const CGFloat transportX=rowRight-clusterW;
    const CGFloat tabPrevX=rowLeft;
    const CGFloat tabBarX=tabPrevX+btnW+gap;
    const CGFloat tabNextX=transportX-btnW-gap;
    const CGFloat minTabW=220.f;
    CGFloat tabBarW=tabNextX-gap-tabBarX;
    if(tabBarW<minTabW){
        tabBarW=minTabW;
    }
    if(tabBarX+tabBarW+gap+btnW > transportX-gap){
        tabBarW=MAX(160.f, transportX-gap-btnW-gap-tabBarX);
    }

    if(_tabPrev) _tabPrev.frame=NSMakeRect(tabPrevX,navY,btnW,20.f);
    if(_tabBar)  _tabBar.frame =NSMakeRect(tabBarX,navY,tabBarW,22.f);
    if(_tabBar)  ArpSIDFitVisibleTabBarWidths_v320(_tabBar);
    if(_tabNext) _tabNext.frame=NSMakeRect(tabBarX+tabBarW+gap,navY,btnW,20.f);

    const CGFloat dispH=22.f, dispY=navY;
    if(_transpView) _transpView.frame=NSMakeRect(transportX,dispY,transpW,dispH);
    if(_arpStepView) _arpStepView.frame=NSMakeRect(transportX+transpW+gap,dispY,arpW,dispH);
    if(_voiceView) _voiceView.frame=NSMakeRect(transportX+transpW+gap+arpW+gap,dispY,voiceW,dispH);

    if(_tabPrev && _tabPrev.superview!=root)
        [root addSubview:_tabPrev positioned:NSWindowAbove relativeTo:nil];
    if(_tabBar && _tabBar.superview!=root)
        [root addSubview:_tabBar positioned:NSWindowAbove relativeTo:nil];
    if(_tabNext && _tabNext.superview!=root)
        [root addSubview:_tabNext positioned:NSWindowAbove relativeTo:nil];
}

-(void)_syncNavigationState{
    if(_tabBar){
        NSInteger sel=ArpSIDVisibleTabSegmentForFlavor(_componentFlavor, _tab);
        if(sel<0||sel>=_tabBar.segmentCount) sel=0;
        if(_tabBar.selectedSegment != sel) _tabBar.selectedSegment=sel;
    }
    if(_tabPrev) _tabPrev.enabled=YES;
    if(_tabNext) _tabNext.enabled=YES;
    [self.view setNeedsDisplay:YES];
}

-(void)_rewireEmbeddedVSTInteractiveControls{
    if(_embeddedVSTControlsRewired) return;
