    if(_tabPrev){ _tabPrev.target=self; _tabPrev.action=@selector(_prevTab:); _tabPrev.enabled=YES; }
    if(_tabNext){ _tabNext.target=self; _tabNext.action=@selector(_nextTab:); _tabNext.enabled=YES; }
    if(_modelPop){ _modelPop.target=self; _modelPop.action=@selector(_modelChg:); _modelPop.enabled=YES; }
