-(void)_resyncEmbeddedVSTState{
    if(![self _requireBridgeForAction:[NSString stringWithUTF8String:__func__]]) return;
    [self _refreshPresets];
    if(_tabBar){
        NSInteger sel=_tabBar.selectedSegment;
        if(sel<0||sel>=_tabBar.segmentCount) sel=ArpSIDVisibleTabSegmentForFlavor(_componentFlavor, _tab);
        if(sel<0||sel>=_tabBar.segmentCount) sel=0;
        _tabBar.selectedSegment=sel;
        [self _showTab:ArpSIDVisibleTabForFlavorAtIndex(_componentFlavor, sel)];
    }
    [self _refreshPatchAndModeFromBridgeState];
    if(_tabPrev) _tabPrev.enabled=YES;
    if(_tabNext) _tabNext.enabled=YES;
    [self _layoutEmbeddedNavigation];
    [self _mountMainChromeControls];
    [self _syncComponentFlavorFromBridge:_au];
    [self _syncNavigationState];
}

-(void)prepareForEmbeddedVSTPresentation{
    if(!_built){ [self loadView]; if(!_built){ [self _buildUI]; _built=YES; } }
    [self _resumeReusableEditorRuntime_v322_];
    _embeddedVSTControlsRewired = NO;
    ArpSIDSetPreferredContentSizeOnMainThread(self, NSMakeSize(kW,kH));
    if(!self.view.superview || NSWidth(self.view.bounds)<100.0 || NSHeight(self.view.bounds)<100.0)
        self.view.frame=NSMakeRect(0,0,kW,kH);
    [self _rewireEmbeddedVSTInteractiveControls];
    [self _mountMainChromeControls];
    [self _layoutEmbeddedNavigation];
    if(_tabBar){
        NSInteger sel=_tabBar.selectedSegment;
        if(sel<0||sel>=_tabBar.segmentCount) sel=ArpSIDVisibleTabSegmentForFlavor(_componentFlavor, _tab);
        if(sel<0||sel>=_tabBar.segmentCount) sel=0;
        _tabBar.selectedSegment=sel;
        [self _showTab:ArpSIDVisibleTabForFlavorAtIndex(_componentFlavor, sel)];
    } else {
        [self _showTab:_tab];
    }
    [self _resyncEmbeddedVSTState];
    [self.view setNeedsLayout:YES];
    [self.view setNeedsDisplay:YES];
    [self _startTimer];
    __weak ArpSIDViewController* weakSelf_v792 = self;
    dispatch_async(dispatch_get_main_queue(), ^{
        ArpSIDViewController* strongSelf_v792 = weakSelf_v792;
        if(!strongSelf_v792) return;
        NSWindow* w=strongSelf_v792.view.window;
        if(w){
            [strongSelf_v792 _prepareWindowForUserFullscreen];
            [w recalculateKeyViewLoop];
            NSView* first=[strongSelf_v792 embeddedVSTPreferredFirstResponder];
            if(!first) first=strongSelf_v792.view;
            [w makeFirstResponder:first];
        }
    });
}

-(NSView*)embeddedVSTPreferredFirstResponder{
    if(_tabBar) return _tabBar;
    if(_presetPop) return _presetPop;
    return self.view;
}

-(void)embeddedVSTHostDidResize{
    if(!_built) return;
    [self _layoutEmbeddedNavigation];
    [self.view setNeedsLayout:YES];
    [self.view setNeedsDisplay:YES];
}

