    // migration panel may also consume the same snapshot in test/debug builds.
    if ((wantsC64Tab || wantsC64StateTab)
        && [adapter respondsToSelector:@selector(readDiagnosticCounters:)]) {
        ArpSID::GUI::ArpSIDDiagnosticCounterSnapshot snap{};
        [(id<ArpSIDDebugAdapterLike>)adapter readDiagnosticCounters:&snap];
        if (wantsC64StateTab && _c64DiagValueLabels_v549_.count == 55) {
            static constexpr NSUInteger kC64DiagValueCount_v302 = 55u;
            const uint64_t vals[kC64DiagValueCount_v302] = {
                snap.renderEpoch, snap.notifyCallbackViolationCount,
                snap.renderDrainTimeoutCount, snap.splitBrainDiagnosticCount,
                snap.scratchUnderCapacityCountAuv2, snap.pendingEventsDrainDroppedCount,
                snap.ingressFallbackEdgeOverflowCount, snap.zeroCycleSampleCount,
                snap.outputStageNoiseSampleCount, snap.filterAbsClampHitCount,
                snap.stateRestoreOverlayAuthenticCount, snap.stateRestoreOverlayAnalogCount,
                snap.invalidClockFrequencyRejectCount, snap.preNotifyFailureCount,
                snap.hostBufferScratchAttachCount, snap.renderScratchEpochAuv3,
                snap.scratchUnderCapacityCountAuv3, snap.c64PsidVideoStandardFallbackCount,
                snap.c64PsidRenderHandoffCount, snap.activityMutexRtViolations,
                snap.stateMutexRtViolations, snap.propListenerMutexRtViolations,
                snap.closeWaitMutexRtViolations, snap.bridgeDivertedRenderCount,
                snap.rsidStrictStatusCode, snap.rsidPlaybackModeCode,
                snap.rsidExactnessDowngradeMask, snap.rsidExactPlaybackActive,
                snap.phi2ApproximateOpcodeTotal, snap.phi2UnsupportedOpcodeTotal,
                snap.initBrkSentinelCount, snap.sidReadApproximationCount,
                snap.sidOpenBusReadCount, snap.invalidSidChipReadCount,
                snap.invalidSidChipWriteCount, snap.sidHoleWriteCount,
                snap.rmwSidWriteCount,
                snap.c64CallbackLastBlockMicros, snap.c64CallbackMaxBlockMicros,
                snap.c64CallbackOverrunCount,
                snap.c64PreC64LastBlockMicros, snap.c64PreC64MaxBlockMicros,
                snap.c64RenderLastBlockMicros, snap.c64RenderMaxBlockMicros,
                snap.c64RenderOverrunCount,
                snap.c64PostC64LastBlockMicros, snap.c64PostC64MaxBlockMicros,
                snap.c64TelemetryLastBlockMicros, snap.c64TelemetryMaxBlockMicros,
                snap.c64MaxHostGapMicros, snap.c64MaxCatchupCycles,
                snap.c64MaxContinuousCatchupCycles, snap.c64MaxCiaCatchupCycles,
                snap.c64MaxVbiCatchupCycles, snap.c64LastPassiveDebtCycles,
            };
            static_assert(sizeof(vals) / sizeof(vals[0]) == kC64DiagValueCount_v302,
                          "C64 diagnostic value array must match C64 STATE label count");
            for (NSUInteger i = 0; i < kC64DiagValueCount_v302; ++i) {
                _c64DiagValueLabels_v549_[i].stringValue =
                    [NSString stringWithFormat:@"%llu", (unsigned long long)vals[i]];
            }
        }

        NSString* badgeText = nil;
        NSColor* badgeColor = nil;
        // audit P1.11: present the four claims as DISTINCT facts and never collapse
        // them. "EXACT" is only used when there are zero physical-exactness blockers
        // AND an empty downgrade ledger (status code 1). Otherwise strict PHI2 is
        // active but physical exactness is explicitly reported as BLOCKED.
        switch (snap.rsidStrictStatusCode) {
            case 1u:
                badgeText  = @"● STRICT PHI2: active · DOWNGRADES: none · PHYSICAL EXACT: yes";
                badgeColor = [NSColor colorWithSRGBRed:0.2f green:0.9f blue:0.4f alpha:1.0f];
                break;
            case 2u:
                badgeText  = @"● STRICT PHI2: active · PHYSICAL EXACT: blocked";
                badgeColor = [NSColor colorWithSRGBRed:1.0f green:0.75f blue:0.1f alpha:1.0f];
                break;
            default:
                badgeText = snap.rsidPlaybackModeCode == 2u
                    ? @"● COMPATIBLE · NOT STRICT"
                    : @"● STRICT PATH INACTIVE";
                badgeColor = [[self _themeLabel_v552_] colorWithAlphaComponent:0.55f];
                break;
        }
        NSString* reasons = ArpSIDRsidDowngradeReasonsString(
            snap.rsidExactnessDowngradeMask);
        // audit P1.11: surface the concrete physical-exactness blockers (CIA/VIC/
        // SID-readback/ROM-identity/open-bus/legacy-path) so the user can see WHY a
        // strict-PHI2 run is not physically exact, instead of inferring it.
        NSString* blockers = ArpSIDRsidPhysicalBlockersString(
            snap.rsidPhysicalBlockerMask);
        NSString* counts = [NSString stringWithFormat:
            @"SID READ APPROX %llu · SID OPEN BUS %llu · INVALID CHIP R/W %llu/%llu · SID HOLE %llu · RMW %llu · INIT BRK %llu",
            (unsigned long long)snap.sidReadApproximationCount,
            (unsigned long long)snap.sidOpenBusReadCount,
            (unsigned long long)snap.invalidSidChipReadCount,
            (unsigned long long)snap.invalidSidChipWriteCount,
            (unsigned long long)snap.sidHoleWriteCount,
            (unsigned long long)snap.rmwSidWriteCount,
            (unsigned long long)snap.initBrkSentinelCount];
        // audit P1.11: tooltip carries both the observed downgrade ledger AND the
        // physical-exactness blockers so neither claim is hidden behind the other.
        NSString* reasonsAndBlockers = [NSString stringWithFormat:@"%@\n%@", reasons, blockers];
        if (_rsidExactBadge_v605_) {
            _rsidExactBadge_v605_.stringValue = badgeText;
            _rsidExactBadge_v605_.textColor = badgeColor;
            _rsidExactBadge_v605_.toolTip = reasonsAndBlockers;
        }
        if (_c64ExactnessBadge_v683_) {
            _c64ExactnessBadge_v683_.stringValue = badgeText;
            _c64ExactnessBadge_v683_.textColor = badgeColor;
            _c64ExactnessBadge_v683_.toolTip = reasonsAndBlockers;
        }
        NSColor* reasonColor = (snap.rsidExactnessDowngradeMask != 0u || snap.rsidPhysicalBlockerMask != 0u)
                ? [NSColor colorWithSRGBRed:1.0f green:0.72f blue:0.22f alpha:0.92f]
                : [[self _themeValue_v552_] colorWithAlphaComponent:0.80f];
        if (_rsidExactReasons_v683_) {
            _rsidExactReasons_v683_.stringValue = reasonsAndBlockers;
            _rsidExactReasons_v683_.textColor = reasonColor;
        }
        if (_c64ExactnessReasons_v683_) {
            _c64ExactnessReasons_v683_.stringValue = reasonsAndBlockers;
            _c64ExactnessReasons_v683_.textColor = reasonColor;
        }
        // v840: always-visible render-path stall readout (the choppiness is a
        // periodic render stall, not emulation compute — these localize it).
        NSString* perf = [NSString stringWithFormat:
            @"CALL µs %llu/%llu · PRE/C64/POST/TEL %llu/%llu/%llu/%llu · OVERRUNS %llu/%llu · HOST GAP MAX %llu µs · CATCHUP cont/CIA/VBI %llu/%llu/%llu · DEBT %llu cyc",
            (unsigned long long)snap.c64CallbackLastBlockMicros,
            (unsigned long long)snap.c64CallbackMaxBlockMicros,
            (unsigned long long)snap.c64PreC64LastBlockMicros,
            (unsigned long long)snap.c64RenderLastBlockMicros,
            (unsigned long long)snap.c64PostC64LastBlockMicros,
            (unsigned long long)snap.c64TelemetryLastBlockMicros,
            (unsigned long long)snap.c64CallbackOverrunCount,
            (unsigned long long)snap.c64RenderOverrunCount,
            (unsigned long long)snap.c64MaxHostGapMicros,
            (unsigned long long)snap.c64MaxContinuousCatchupCycles,
            (unsigned long long)snap.c64MaxCiaCatchupCycles,
            (unsigned long long)snap.c64MaxVbiCatchupCycles,
            (unsigned long long)snap.c64LastPassiveDebtCycles];
        if (_c64ExactnessCounters_v683_)
            _c64ExactnessCounters_v683_.stringValue =
                [NSString stringWithFormat:@"%@\n%@", counts, perf];
    }
    // v550: Drain the SIDCORE register-write ring and trigger a redraw of the
