    if (wantsSidCoreViz && _sidCoreTimelineView_v547_) {
        [_sidCoreTimelineView_v547_ refresh];
    }
    if (wantsC64StateTab && _c64StateSidCoreTimelineView_v581_) {
        [_c64StateSidCoreTimelineView_v581_ refresh];
    }
    const float arpRateNorm=[self _cachedParamValue:ArpSID::kParamArpRate defaultCenter:ArpSID::defaultNormalizedParamValue(ArpSID::kParamArpRate)];
    if(arpRateNorm > 0.005f) _lastInternalArpRateNorm=arpRateNorm;
    const float seqTempoNorm=[self _cachedParamValue:ArpSID::kParamSeqTempo defaultCenter:ArpSID::defaultNormalizedParamValue(ArpSID::kParamSeqTempo)];
    if(seqTempoNorm > 0.005f) _lastInternalSeqTempoNorm=seqTempoNorm;
    if(_arpSyncSeg){
        const NSInteger syncIdx=ArpSIDSyncSegmentIndex(tel.arpFollowHost || arpRateNorm <= 0.005f);
        if(_arpSyncSeg.selectedSegment != syncIdx) _arpSyncSeg.selectedSegment=syncIdx;
    }
    if(_seqSyncSeg){
        const NSInteger syncIdx=ArpSIDSyncSegmentIndex(tel.seqFollowHost || seqTempoNorm <= 0.005f);
        if(_seqSyncSeg.selectedSegment != syncIdx) _seqSyncSeg.selectedSegment=syncIdx;
    }
    int n=0;
    if(wantsMainScope || wantsDrSidUI || wantsDrsidPanelUI || wantsDigiUI){
        n=std::min((int)tel.mainOscScopeCount, 512);
        if(n>0){
            for(int i=0;i<n;++i) _oscBuf[i]=ArpSIDUIClampSigned(tel.mainOscScope[i]);
        } else {
            n=[adapter readOscilloscope:_oscBuf maxSamples:512];
        }
        if(n<=0){
            memset(_oscBuf,0,sizeof(_oscBuf));
            n=0;
        }
    }

    const float peakL = ArpSIDUIClamp01(tel.peakL);
    const float peakR = ArpSIDUIClamp01(tel.peakR);
    const float rmsL  = ArpSIDUIClamp01(tel.rmsL);
    const float rmsR  = ArpSIDUIClamp01(tel.rmsR);
    const float forensicActivity = ArpSIDUIClamp01(tel.forensicActivity);
    const float forensicIntensity = ArpSIDUIClamp01(tel.forensicIntensity);
    const BOOL forensicEnabled = tel.forensicEnabled;
    const int activeVoices = ArpSIDUIClampInt(tel.activeVoices,0,8,0);
    const int lastMidiNote = ArpSIDUIClampInt(tel.lastMidiNote,-1,127,-1);
    double hostTempo = ArpSIDUIFiniteDouble(tel.hostTempo,120.0);
    if(hostTempo < 1.0 || hostTempo > 1000.0) hostTempo = 120.0;
    const double hostBeat = std::max(0.0, ArpSIDUIFiniteDouble(tel.hostBeat,0.0));
    const float filterCutoff=ArpSIDUIClamp01(tel.mpkKnobValue[0]);
    const float filterRes=ArpSIDUIClamp01(tel.mpkKnobValue[1]);
    const float filterDrive=ArpSIDUIClamp01(tel.mpkKnobValue[2]);
    const float filterEnv=ArpSIDUIClamp01(tel.mpkKnobValue[3]);
    const float filterLFO=ArpSIDUIClamp01(tel.mpkKnobValue[4]);
    const float mpkVol=ArpSIDUIClamp01(tel.mpkKnobValue[5]);
    const float mpkReverb=ArpSIDUIClamp01(tel.mpkKnobValue[6]);
    const float mpkForensic=ArpSIDUIClamp01(tel.mpkKnobValue[7]);
    const float visualActivity=std::max({peakL,peakR,rmsL,rmsR,ArpSIDUIClamp01(tel.digiOutputPeak)});
    const float visualForensic=forensicEnabled
