                         forensicActivity:visualForensic
                                  playing:tel.hostPlaying];
    }
    const float filterKey=[self _cachedParamValue:ArpSID::kParamFilterKeyTrack defaultCenter:0.0f];
    float filterInPeak=0.f, filterOutPeak=0.f;
    if(wantsScopeData && (wantsFilterUI || wantsForensicScopes || wantsSidCoreViz || _presentationHUDLabel)){
        for(int i=0;i<256;++i){
            filterInPeak=std::max(filterInPeak, fabsf(ArpSIDUIClampSigned(tel.filterScopeIn[i])));
            filterOutPeak=std::max(filterOutPeak, fabsf(ArpSIDUIClampSigned(tel.filterScopeOut[i])));
        }
    }
    if(_oscView) _oscView.forensicActivity = forensicActivity;
    if(_meterView) _meterView.forensicActivity = forensicActivity;
    if(_filterView) _filterView.forensicActivity = forensicActivity;
    if(_filterDetailView) _filterDetailView.forensicActivity = forensicActivity;
    if(_forensicFilterView) _forensicFilterView.forensicActivity = forensicActivity;
    if(_sidCoreMetalBackdropView) [_sidCoreMetalBackdropView setForensicActivity:forensicActivity intensity:forensicIntensity enabled:forensicEnabled];
    if(_sidCorePopoutMetalView) [_sidCorePopoutMetalView setForensicActivity:forensicActivity intensity:forensicIntensity enabled:forensicEnabled];
    if(_c64BusMetalBackdropView) [_c64BusMetalBackdropView setForensicActivity:forensicActivity intensity:forensicIntensity enabled:forensicEnabled];
    if(_sidCoreVectorView) [_sidCoreVectorView setForensicActivity:forensicActivity intensity:forensicIntensity enabled:forensicEnabled];
    if(_vco1Scope) _vco1Scope.forensicActivity = forensicActivity;
    if(_vco2Scope) _vco2Scope.forensicActivity = forensicActivity;
    if(_vco3Scope) _vco3Scope.forensicActivity = forensicActivity;
    if(_coreVco1Scope) _coreVco1Scope.forensicActivity = forensicActivity;
    if(_coreVco2Scope) _coreVco2Scope.forensicActivity = forensicActivity;
    if(_coreVco3Scope) _coreVco3Scope.forensicActivity = forensicActivity;
    if(_sidCoreTopVco1Scope) _sidCoreTopVco1Scope.forensicActivity = forensicActivity;
    if(_sidCoreTopVco2Scope) _sidCoreTopVco2Scope.forensicActivity = forensicActivity;
    if(_sidCoreTopVco3Scope) _sidCoreTopVco3Scope.forensicActivity = forensicActivity;
    for (int i = 0; i < 8; ++i) if (_coreVoiceScopes[i]) _coreVoiceScopes[i].forensicActivity = forensicActivity;
    if(_c64BadgeView){
        _c64BadgeView.activity = std::max({peakL, peakR, rmsL, rmsR});
        _c64BadgeView.forensicActivity = forensicEnabled ? std::max(forensicActivity, forensicIntensity * 0.65f) : 0.0f;
        _c64BadgeView.beat = hostBeat;
        _c64BadgeView.transportPlaying = tel.hostPlaying;
    }
    if(_ccHubLabel){
        ArpSIDSetLabelStringIfNeeded(_ccHubLabel, ArpSIDMPKMiniTelemetrySummary(tel));
        const float ccGlow = std::max({filterCutoff, filterRes, filterDrive, filterEnv, filterLFO, mpkVol, mpkReverb, mpkForensic, forensicActivity});
        ArpSIDSetLabelColorIfNeeded(_ccHubLabel, [[c64Cyan() blendedColorWithFraction:(CGFloat)(0.20f + 0.55f*ccGlow) ofColor:c64Yellow()] colorWithAlphaComponent:.74f + .20f*ccGlow]);
    }
    const BOOL drSidOn=(tel.drSidMode || [self _effectiveModeIndexFromTelemetry:&tel] == 2);
    const BOOL drumUiEnabled = YES;
    float drumPeak = 0.0f;
    for(int i=0;i<8;++i) drumPeak = std::max(drumPeak, ArpSIDUIClamp01(tel.drumLevel[i]));
    drumPeak = std::max(drumPeak, ArpSIDUIClamp01(tel.sid808OutputPeak));
    NSString* audibleAuthority = ArpSIDUnifiedAudibleAuthorityLabel(_componentFlavor, tel);
    if(_presentationHUDLabel){
        ArpSIDSetLabelStringIfNeeded(_presentationHUDLabel,
                                     ArpSIDFlavorRealtimeHUDLine(_componentFlavor,
                                                                 tel,
                                                                 wantsScopeData,
                                                                 drumPeak,
                                                                 filterInPeak,
                                                                 filterOutPeak));
        const float hudGlow = std::clamp(std::max({peakL, peakR, drumPeak, filterOutPeak, forensicActivity}), 0.0f, 1.0f);
        ArpSIDSetLabelColorIfNeeded(_presentationHUDLabel,
                                    [[colTitle() blendedColorWithFraction:(CGFloat)(0.12f + hudGlow * 0.42f)
                                                                  ofColor:c64Cyan()] colorWithAlphaComponent:(0.82f + hudGlow * 0.14f)]);
        // Fix #10: Update the HUD tooltip with the full mode/exactness matrix so
        // hovering the HUD shows render mode + voice topology + SID model + RSID state.
        const int voiceModeIdx = ArpSIDUIClampInt(tel.voiceMode, 0, 3, 0);
        const int sidIs6581 = [self _cachedParamValue:ArpSID::kParamSidChipRevision
                                        defaultCenter:ArpSID::defaultNormalizedParamValue(ArpSID::kParamSidChipRevision)] < 0.5f ? 0 : 1;
        NSString* matrixStr = ArpSIDModeExactnessMatrixString(
            ArpSIDUIClampInt(tel.renderMode, 0, 2, 0),
            voiceModeIdx,
            sidIs6581,
            tel.c64SidModelFromFile,
            tel.c64VideoFromFile,
            tel.c64Pal,
            tel.drSidPlaybackMode,
            _c64DiagValueLabels_v549_.count >= 25
                ? (uint64_t)[_c64DiagValueLabels_v549_[24].stringValue longLongValue]
                : 0u);
        _presentationHUDLabel.toolTip = matrixStr;
    }
    uint8_t seqNotes[32]{}; float seqVelocities[32]{}; float seqGates[32]{};
    if(wantsDrSidUI){
        for(int step=0; step<32; ++step){
            const int base=(int)ArpSID::kParamSeqStep1Note + step*3;
            seqNotes[step]=(uint8_t)std::clamp((int)lround([self _cachedParamValue:base defaultCenter:ArpSID::defaultNormalizedParamValue(base)]*127.0f),0,127);
            seqVelocities[step]=[self _cachedParamValue:base+1 defaultCenter:ArpSID::defaultNormalizedParamValue(base+1)];
            seqGates[step]=[self _cachedParamValue:base+2 defaultCenter:ArpSID::defaultNormalizedParamValue(base+2)];
        }
    }

    if(_oscView){ if(wantsMainScope) [_oscView updateWithSamples:_oscBuf count:n]; else [_oscView updateWithSamples:nullptr count:0]; }
    if(_drumScopeView){
        if(wantsDrSidUI){
            _drumScopeView.forensicActivity = forensicActivity * 0.35f + drumPeak * 0.65f;
            [_drumScopeView updateWithSamples:_oscBuf count:n];
        } else {
            [_drumScopeView updateWithSamples:nullptr count:0];
        }
    }
    if(_drsidPanelScopeView){
        if(wantsDrsidPanelUI){
            _drsidPanelScopeView.forensicActivity = forensicActivity * 0.45f + drumPeak * 0.55f;
            [_drsidPanelScopeView updateWithSamples:_oscBuf count:n];
        } else {
            [_drsidPanelScopeView updateWithSamples:nullptr count:0];
        }
    }
    if(_digiScopeView){
        if(wantsDigiUI){
            const float digiPeak = ArpSIDUIClamp01(tel.digiOutputPeak);
            _digiScopeView.forensicActivity = forensicActivity * 0.30f + digiPeak * 0.70f;
            [_digiScopeView updateWithSamples:tel.digiScope count:128];
        } else {
            [_digiScopeView updateWithSamples:nullptr count:0];
        }
    }
    if(_digiNibbleLadderView_v179_){
        if(wantsDigiUI){
            [_digiNibbleLadderView_v179_ updateWithNibble:tel.digiD418LastNibble
                                                  oldD418:tel.digiD418LastOldD418
                                                     d418:tel.digiD418LastD418
                                                     peak:ArpSIDUIClamp01(tel.digiOutputPeak)
                                                 accepted:(tel.digiD418LastSidAccepted != 0u)
                                                ioVisible:(tel.digiD418LastIoVisible != 0u)
                                                   legacy:(tel.digiAuthMode == 2u)
                                                recording:_digiRecordActive_v158_.load(std::memory_order_acquire)];
        } else {
            [_digiNibbleLadderView_v179_ updateWithNibble:0u oldD418:0u d418:0u peak:0.f accepted:NO ioVisible:NO legacy:NO recording:NO];
        }
    }
    [_meterView setLevelL:peakL rms:rmsL levelR:peakR rms:rmsR];
    if(_drumBusMeterView) [_drumBusMeterView setLeftLevel:peakL rightLevel:peakR drumLevel:drumPeak];
    if(_drumOutputDbLabel){
        const float meterPeak=std::max({peakL, peakR, drumPeak});
        const float db=(meterPeak > 1.0e-5f) ? (20.0f * log10f(meterPeak)) : -96.0f;
        ArpSIDSetLabelStringIfNeeded(_drumOutputDbLabel, [NSString stringWithFormat:@"%+.1f dB", db]);
    }
    if(wantsSidCoreViz) [self _updateSidCoreWithTelemetry:tel];
    if(_sidCoreMetalBackdropView && wantsSidCoreViz) [_sidCoreMetalBackdropView updateWithTelemetry:tel];
    if(_sidCorePopoutMetalView) [_sidCorePopoutMetalView updateWithTelemetry:tel];
    if(_c64BusMetalBackdropView && (wantsC64Tab || wantsC64StateTab)) [_c64BusMetalBackdropView updateWithTelemetry:tel];
    if(_sidCoreVectorView && wantsSidCoreViz) [_sidCoreVectorView updateWithTelemetry:tel];

    int arpLen=(int)std::clamp([self _cachedParamValue:ArpSID::kParamArpPatternLength defaultCenter:0.0f]*32+1,1.f,32.f);
    BOOL arpOn=[self _effectiveArpAuthorityEnabledForModeIndex:[self _effectiveModeIndexFromTelemetry:&tel]];
    [_arpStepView setCurrentStep:std::max(0,tel.arpStep) totalSteps:arpLen arpOn:arpOn];
    [_transpView setTempo:hostTempo beat:hostBeat playing:tel.hostPlaying];
    [_voiceView setVoiceCount:activeVoices lastNote:lastMidiNote];
    [_voiceView setTokenCount:tel.activeTokenCount tokens:tel.tokens activeVoices:activeVoices lastNote:lastMidiNote];
    if(wantsSidRegScopes) [_sidRegLive updateRegisters:tel.sidRegs count:30];
    if(wantsSidRegScopes) [self _updateSidRegisterStatusWithTelemetry:tel];

    [_pbView setValue:[self _cachedParamValue:(int)ArpSID::kParamHostCtrlPitchBendBase defaultCenter:0.5f]];
    [_mwView setValue:[self _cachedParamValue:(int)ArpSID::kParamHostCtrlModWheelBase defaultCenter:0.0f]];
    [_breathView setValue:[self _cachedParamValue:(int)ArpSID::kParamHostCtrlBreathBase defaultCenter:0.0f]];
    if(_atView)[_atView setValue:[self _cachedParamValue:(int)ArpSID::kParamHostCtrlChannelPressureBase defaultCenter:0.0f]];

    const float* vcoScope0 = tel.vcoScope[0];
    const float* vcoScope1 = tel.vcoScope[1];
    const float* vcoScope2 = tel.vcoScope[2];
    if (_vco1Scope) [_vco1Scope updateWithSamples:(wantsForensicScopes ? vcoScope0 : nullptr) count:(wantsForensicScopes ? 256 : 0)];
    if (_vco2Scope) [_vco2Scope updateWithSamples:(wantsForensicScopes ? vcoScope1 : nullptr) count:(wantsForensicScopes ? 256 : 0)];
    if (_vco3Scope) [_vco3Scope updateWithSamples:(wantsForensicScopes ? vcoScope2 : nullptr) count:(wantsForensicScopes ? 256 : 0)];
    const BOOL wantsCoreScopes = wantsSidRegScopes || wantsOptionsUI || wantsC64Tab || wantsC64StateTab;
    const BOOL wantsBpePolyVoiceScopes = wantsCoreScopes && !tel.psidActive;
    if (_coreVco1Scope) [_coreVco1Scope updateWithSamples:(wantsCoreScopes ? vcoScope0 : nullptr) count:(wantsCoreScopes ? 256 : 0)];
    if (_coreVco2Scope) [_coreVco2Scope updateWithSamples:(wantsCoreScopes ? vcoScope1 : nullptr) count:(wantsCoreScopes ? 256 : 0)];
    if (_coreVco3Scope) [_coreVco3Scope updateWithSamples:(wantsCoreScopes ? vcoScope2 : nullptr) count:(wantsCoreScopes ? 256 : 0)];
    if (_sidCoreTopVco1Scope) { _sidCoreTopVco1Scope.accentColor = [c64Cyan() blendedColorWithFraction:(CGFloat)(0.18 + 0.72 * ArpSIDUIClamp01(tel.voiceEnvLevel[0])) ofColor:c64White()]; [_sidCoreTopVco1Scope updateWithSamples:(wantsSidCoreViz ? vcoScope0 : nullptr) count:(wantsSidCoreViz ? 256 : 0)]; }
    if (_sidCoreTopVco2Scope) { _sidCoreTopVco2Scope.accentColor = [c64Yellow() blendedColorWithFraction:(CGFloat)(0.18 + 0.72 * ArpSIDUIClamp01(tel.voiceEnvLevel[1])) ofColor:c64White()]; [_sidCoreTopVco2Scope updateWithSamples:(wantsSidCoreViz ? vcoScope1 : nullptr) count:(wantsSidCoreViz ? 256 : 0)]; }
    if (_sidCoreTopVco3Scope) { _sidCoreTopVco3Scope.accentColor = [c64LtGreen() blendedColorWithFraction:(CGFloat)(0.18 + 0.72 * ArpSIDUIClamp01(tel.voiceEnvLevel[2])) ofColor:c64White()]; [_sidCoreTopVco3Scope updateWithSamples:(wantsSidCoreViz ? vcoScope2 : nullptr) count:(wantsSidCoreViz ? 256 : 0)]; }
    for (int i = 0; i < 8; ++i) {
        if (_coreVoiceScopes[i]) [_coreVoiceScopes[i] updateWithSamples:(wantsBpePolyVoiceScopes ? tel.voiceScope[i] : nullptr) count:(wantsBpePolyVoiceScopes ? 256 : 0)];
    }
    if(drSidOn && lastMidiNote >= 0) _selectedDrumMidiNote = lastMidiNote;
    if(wantsDrSidUI){
        [self _syncDrumKitPopupToBankSlotIfKnown:tel.bankSlot];
        [self _refreshDrumKitPresentationIfNeededForBankSlot:tel.bankSlot];
