                        (unsigned)tel.digiTriggerCount,
                        ArpSIDPercentNormString(digiPeak),
                        userNote]);
                ArpSIDSetLabelColorIfNeeded(_digiRuntimeHUDLabel,
                    [[c64LtGreen() blendedColorWithFraction:(CGFloat)(0.16f + digiPeak * 0.50f)
                                                    ofColor:colLabel()] colorWithAlphaComponent:(0.72f + digiPeak * 0.22f)]);
            }
            _digiRuntimeHUDLabel.toolTip = @"Compact DIGI live state. Detailed D418 route/counters/warnings are shown below the scope.";
        }
        if(_digiSeqLED) _digiSeqLED.on = tel.seqEnabled;
        if(_digiPlayLED) _digiPlayLED.on = digiVoices > 0 || digiPeak > 0.01f;
        if(_digiRtLED) _digiRtLED.on = digiPeak > 0.01f || tel.hostPlaying;
    }
    if(_drumKitSeg && (wantsDrSidUI || (_tab==ArpSIDTabBank) || drSidOn)) {
        const NSInteger segIdx = ArpSIDDrumKitSegmentForFlavorSlot(_componentFlavor, tel.bankSlot);
        if(segIdx >= 0 && _drumKitSeg.selectedSegment != segIdx) _drumKitSeg.selectedSegment = segIdx;
    }
    if(_drumPatternView && wantsDrSidUI){
        uint8_t pageNotes[16]{};
        float pageVelocities[16]{};
        float pageGates[16]{};
        const NSInteger start=std::clamp(_drumSeqPage, (NSInteger)0, (NSInteger)1) * 16;
        for(NSInteger i=0;i<16;++i){
            pageNotes[i]=seqNotes[start+i];
            pageVelocities[i]=seqVelocities[start+i];
            pageGates[i]=seqGates[start+i];
        }
        const int currentRelative=(tel.seqStep >= start && tel.seqStep < start + 16) ? (tel.seqStep - (int)start) : -1;
        [_drumPatternView updateNotes:pageNotes velocities:pageVelocities gates:pageGates currentStep:currentRelative enabled:drumUiEnabled];
    } else if(_drumPatternView){
        uint8_t pageNotes[16]{}; float pageVelocities[16]{}; float pageGates[16]{};
        [_drumPatternView updateNotes:pageNotes velocities:pageVelocities gates:pageGates currentStep:-1 enabled:NO];
    }
    if(_drumStepEditView && wantsDrSidUI){
        uint8_t pageNotes[16]{};
        float pageVelocities[16]{};
        float pageGates[16]{};
        const NSInteger start=std::clamp(_drumSeqPage, (NSInteger)0, (NSInteger)1) * 16;
        for(NSInteger i=0;i<16;++i){
            pageNotes[i] = seqNotes[start + i];
            pageVelocities[i] = seqVelocities[start + i];
            pageGates[i] = seqGates[start + i];
        }
        const int currentRelative = (tel.seqStep >= start && tel.seqStep < start + 16) ? (tel.seqStep - (int)start) : -1;
        [_drumStepEditView updateNotes:pageNotes
                            velocities:pageVelocities
                                 gates:pageGates
                           currentStep:currentRelative
                          selectedNote:_selectedDrumMidiNote
                               enabled:drumUiEnabled];
    }

    if(_filterView && wantsMainScope){
        [_filterView updateWithCutoff:filterCutoff
                            resonance:filterRes
                              modeVol:tel.sidRegs[24]
                                drive:filterDrive
                            envAmount:filterEnv
                            lfoAmount:filterLFO
                             keyTrack:filterKey
                             envLevel:tel.env1Level
                             lfoValue:tel.lfoValue[0]
                           inputScope:tel.filterScopeIn
                          outputScope:tel.filterScopeOut
                                count:256
                              playing:tel.hostPlaying];
    } else if(_filterView){
        [_filterView updateWithCutoff:0.f resonance:0.f modeVol:0u drive:0.f envAmount:0.f lfoAmount:0.f keyTrack:0.f envLevel:0.f lfoValue:0.f inputScope:nullptr outputScope:nullptr count:0 playing:NO];
    }
    if(_filterDetailView && wantsFilterUI){
        [_filterDetailView updateWithCutoff:filterCutoff
                                  resonance:filterRes
                                    modeVol:tel.sidRegs[24]
                                      drive:filterDrive
                                  envAmount:filterEnv
                                  lfoAmount:filterLFO
                                   keyTrack:filterKey
                                   envLevel:tel.env1Level
                                   lfoValue:tel.lfoValue[0]
                                 inputScope:tel.filterScopeIn
                                outputScope:tel.filterScopeOut
                                      count:256
                                    playing:tel.hostPlaying];
    } else if(_filterDetailView){
        [_filterDetailView updateWithCutoff:0.f resonance:0.f modeVol:0u drive:0.f envAmount:0.f lfoAmount:0.f keyTrack:0.f envLevel:0.f lfoValue:0.f inputScope:nullptr outputScope:nullptr count:0 playing:NO];
    }
    if(_forensicFilterView && wantsForensicScopes){
        [_forensicFilterView updateWithCutoff:filterCutoff
                                    resonance:filterRes
                                      modeVol:tel.sidRegs[24]
                                        drive:filterDrive
                                    envAmount:filterEnv
                                    lfoAmount:filterLFO
                                     keyTrack:filterKey
                                     envLevel:tel.env1Level
                                     lfoValue:tel.lfoValue[0]
                                   inputScope:tel.filterScopeIn
                                  outputScope:tel.filterScopeOut
                                        count:256
                                      playing:(tel.hostPlaying || forensicEnabled)];
    } else if(_forensicFilterView){
        [_forensicFilterView updateWithCutoff:0.f resonance:0.f modeVol:0u drive:0.f envAmount:0.f lfoAmount:0.f keyTrack:0.f envLevel:0.f lfoValue:0.f inputScope:nullptr outputScope:nullptr count:0 playing:NO];
    }
    if(_filterHUDLabel){
        if(wantsFilterUI){
            const float chipRevisionNorm=[self _cachedParamValue:ArpSID::kParamSidChipRevision defaultCenter:ArpSID::sidChipRevisionIndexToNormalized(ArpSID::kSidChipRevisionDefaultIndex)];
            ArpSIDSetLabelStringIfNeeded(_filterHUDLabel,
                [NSString stringWithFormat:@"%@  •  %@  •  CUT %@  RES %@  DRV %@  ENV %@  LFO %@  KEY %@  •  IN %@  OUT %@",
                    [NSString stringWithUTF8String:ArpSID::sidChipRevisionSelectorLabel(chipRevisionNorm)],
                    ArpSIDFilterModeString(tel.sidRegs[24]),
                    ArpSIDPercentNormString(filterCutoff),
                    ArpSIDPercentNormString(filterRes),
                    ArpSIDPercentNormString(filterDrive),
                    ArpSIDPercentNormString(filterEnv),
                    ArpSIDPercentNormString(filterLFO),
                    ArpSIDPercentNormString(filterKey),
                    ArpSIDPercentNormString(filterInPeak),
                    ArpSIDPercentNormString(filterOutPeak)]);
            ArpSIDSetLabelColorIfNeeded(_filterHUDLabel, [[c64Yellow() blendedColorWithFraction:(CGFloat)(0.18f + 0.52f*std::max({filterRes, filterDrive, filterOutPeak, forensicActivity})) ofColor:c64White()] colorWithAlphaComponent:.78f]);
        } else {
            ArpSIDSetLabelStringIfNeeded(_filterHUDLabel, @"");
        }
    }
    if(wantsForensicScopes){
        // Read static analogue params for row 1 (not in telemetry struct)
        const float fTempNorm=[self _cachedParamValue:ArpSID::kParamForensicTemp defaultCenter:ArpSID::defaultNormalizedParamValue(ArpSID::kParamForensicTemp)];
        const float fSupplyNorm=[self _cachedParamValue:ArpSID::kParamForensicSupply defaultCenter:ArpSID::defaultNormalizedParamValue(ArpSID::kParamForensicSupply)];
        const float fRevNorm=[self _cachedParamValue:ArpSID::kParamForensicRevision defaultCenter:ArpSID::defaultNormalizedParamValue(ArpSID::kParamForensicRevision)];
        const float fTempC=(float)ArpSID::sidForensicTemperatureFromNormalized(fTempNorm);
        const float fVoltage=(float)ArpSID::sidForensicSupplyFromNormalized(fSupplyNorm);
        const uint8_t fRev=ArpSID::sidForensicRevisionFromNormalized(fRevNorm);
        const char* fRevLabel=ArpSID::sidForensicRevisionLabel(fRev);
        // derive peak analogue stress level for row 2-4 colour blends
        const float clkPeak=std::max({ArpSIDUIClamp01(tel.forensicClockJitter),ArpSIDUIClamp01(tel.forensicSupplyRipple),ArpSIDUIClamp01(tel.forensicThermalDrift),ArpSIDUIClamp01(tel.forensicEnvelopeTDM)});
        const float vfPeak=std::max({ArpSIDUIClamp01(tel.forensicVoiceCrosstalk),ArpSIDUIClamp01(tel.forensicExternalBleed),ArpSIDUIClamp01(tel.forensicFilterOhmic),ArpSIDUIClamp01(tel.forensicMotherboard)});
        const float busPeak=std::max({ArpSIDUIClamp01(tel.forensicSystemNoise),ArpSIDUIClamp01(tel.forensicD418Asymmetry),ArpSIDUIClamp01(tel.forensicADCBleed),ArpSIDUIClamp01(tel.forensicBusCollision),ArpSIDUIClamp01(tel.forensicPotInput)});
        // Row 1 — STATUS
        if(_forensicHUDRow1){
            ArpSIDSetLabelStringIfNeeded(_forensicHUDRow1,
                [NSString stringWithFormat:@"◈ FORENSIC %@  ACT %@  INT %@  T %.1f°C  VCC %.2fV  %s  DIGIFIX %@  IN %@  OUT %@  VOICES %d",
                    ArpSIDOnOffString(forensicEnabled),
                    ArpSIDPercentNormString(forensicActivity),
                    ArpSIDPercentNormString(forensicIntensity),
                    (double)fTempC, (double)fVoltage,
                    fRevLabel,
                    ArpSIDOnOffString(tel.forensicDigifix8580),
                    ArpSIDPercentNormString(filterInPeak),
                    ArpSIDPercentNormString(filterOutPeak),
                    activeVoices]);
            ArpSIDSetLabelColorIfNeeded(_forensicHUDRow1, [[c64Orange() blendedColorWithFraction:(CGFloat)(0.12f+0.68f*std::max(forensicActivity,forensicIntensity)) ofColor:c64White()] colorWithAlphaComponent:.84f]);
        }
        // Row 2 — CLOCK / SUPPLY
        if(_forensicHUDRow2){
            ArpSIDSetLabelStringIfNeeded(_forensicHUDRow2,
                [NSString stringWithFormat:@"CLOCK  JITTER %@  RIPPLE %@  DRIFT %@  ENVTDM %@",
                    ArpSIDPercentNormString(tel.forensicClockJitter),
                    ArpSIDPercentNormString(tel.forensicSupplyRipple),
                    ArpSIDPercentNormString(tel.forensicThermalDrift),
                    ArpSIDPercentNormString(tel.forensicEnvelopeTDM)]);
            ArpSIDSetLabelColorIfNeeded(_forensicHUDRow2, [[c64Cyan() blendedColorWithFraction:(CGFloat)(0.10f+0.72f*clkPeak) ofColor:c64White()] colorWithAlphaComponent:.78f]);
        }
        // Row 3 — VOICE / FILTER
        if(_forensicHUDRow3){
            ArpSIDSetLabelStringIfNeeded(_forensicHUDRow3,
                [NSString stringWithFormat:@"VOICE  CROSSTALK %@  BLEED %@  OHMIC %@  MOTHERBOARD %@",
                    ArpSIDPercentNormString(tel.forensicVoiceCrosstalk),
                    ArpSIDPercentNormString(tel.forensicExternalBleed),
                    ArpSIDPercentNormString(tel.forensicFilterOhmic),
                    ArpSIDPercentNormString(tel.forensicMotherboard)]);
            ArpSIDSetLabelColorIfNeeded(_forensicHUDRow3, [[c64LtGreen() blendedColorWithFraction:(CGFloat)(0.10f+0.72f*vfPeak) ofColor:c64White()] colorWithAlphaComponent:.78f]);
        }
        // Row 4 — ADC / BUS / BOARD
        if(_forensicScopeHUDLabel){
            ArpSIDSetLabelStringIfNeeded(_forensicScopeHUDLabel,
                [NSString stringWithFormat:@"BUS  NOISE %@  D418 %@  ADC %@  COLLISION %@  POT %@",
                    ArpSIDPercentNormString(tel.forensicSystemNoise),
                    ArpSIDPercentNormString(tel.forensicD418Asymmetry),
                    ArpSIDPercentNormString(tel.forensicADCBleed),
                    ArpSIDPercentNormString(tel.forensicBusCollision),
                    ArpSIDPercentNormString(tel.forensicPotInput)]);
            ArpSIDSetLabelColorIfNeeded(_forensicScopeHUDLabel, [[c64Yellow() blendedColorWithFraction:(CGFloat)(0.10f+0.72f*busPeak) ofColor:c64White()] colorWithAlphaComponent:.78f]);
        }
    } else {
        if(_forensicHUDRow1) ArpSIDSetLabelStringIfNeeded(_forensicHUDRow1, @"");
        if(_forensicHUDRow2) ArpSIDSetLabelStringIfNeeded(_forensicHUDRow2, @"");
        if(_forensicHUDRow3) ArpSIDSetLabelStringIfNeeded(_forensicHUDRow3, @"");
        if(_forensicScopeHUDLabel) ArpSIDSetLabelStringIfNeeded(_forensicScopeHUDLabel, @"");
    }
    if(_optionsHUDLabel && wantsOptionsUI){
        const float chipRevisionNorm=[self _cachedParamValue:ArpSID::kParamSidChipRevision defaultCenter:ArpSID::sidChipRevisionIndexToNormalized(ArpSID::kSidChipRevisionDefaultIndex)];
        const BOOL uiNtsc=[self _cachedParamValue:ArpSID::kParamSidClockSystem defaultCenter:ArpSID::defaultNormalizedParamValue(ArpSID::kParamSidClockSystem)]>0.5f;
        const BOOL ntsc=ArpSIDTelemetryNtsc(tel, uiNtsc);
        NSString* uiModel=[NSString stringWithUTF8String:ArpSID::sidChipRevisionSelectorLabel(chipRevisionNorm)];
        NSString* authorityModel=ArpSIDTelemetrySidModelLabel(tel, uiModel);
        const BOOL extRc=[self _cachedParamValue:ArpSID::kParamSidExternalRcEnable defaultCenter:ArpSID::defaultNormalizedParamValue(ArpSID::kParamSidExternalRcEnable)]>0.5f;
        const float oversamplingNorm=[self _cachedParamValue:ArpSID::kParamSidOversamplingFactor defaultCenter:ArpSID::defaultNormalizedParamValue(ArpSID::kParamSidOversamplingFactor)];
        const BOOL adsrBug=[self _cachedParamValue:ArpSID::kParamSidAdsrBug6581 defaultCenter:ArpSID::defaultNormalizedParamValue(ArpSID::kParamSidAdsrBug6581)]>0.5f;
        const float drumVolume=ArpSIDUIClamp01(tel.drumVolume, ArpSID::defaultNormalizedParamValue(ArpSID::kParamDrSidVolume));
        const float drumModelNorm=ArpSIDUIClamp01(tel.drumMachineModel, ArpSID::defaultNormalizedParamValue(ArpSID::kParamDrSidMachineModel));
        const float drumAccent=ArpSIDUIClamp01(tel.drumAccentAmount, ArpSID::defaultNormalizedParamValue(ArpSID::kParamDrSidAccentAmount));
        const float drumDrive=ArpSIDUIClamp01(tel.drumOutputDrive, ArpSID::defaultNormalizedParamValue(ArpSID::kParamDrSidOutputDrive));
        const BOOL limiterOn=[self _cachedParamValue:ArpSID::kParamOutputLimiter defaultCenter:ArpSID::defaultNormalizedParamValue(ArpSID::kParamOutputLimiter)]>0.5f;
        const float reverbMix=[self _cachedParamValue:ArpSID::kParamReverbMix defaultCenter:ArpSID::defaultNormalizedParamValue(ArpSID::kParamReverbMix)];
        static const int kOversamplingFactorMap[4]={1,2,4,8};
        const int oversamplingIndex=std::clamp((int)lround(oversamplingNorm*3.0f),0,3);
        ArpSIDSetLabelStringIfNeeded(_optionsHUDLabel,
            [NSString stringWithFormat:@"%@  •  %@  •  %@  •  %@  •  RC %@  •  OS x%d  •  ADSR %@  •  ARP %@  •  SEQ %@  •  %@  •  VOL %@  •  ACC %@  •  DRV %@  •  LIM %@  •  RVB %@  •  OCT %+ld  •  PK %@",
                [NSString stringWithFormat:@"%@ PHI2 %llu SID $%02X=%02X", ArpSIDC64AuthorityLabel(tel), (unsigned long long)tel.c64Phi2Cycle, (unsigned)tel.c64LastSidReg, (unsigned)tel.c64LastSidValue],
                [NSString stringWithUTF8String:ArpSID::componentFlavorDisplayName(_componentFlavor)],
                authorityModel,
                ntsc ? @"NTSC" : @"PAL",
                extRc ? @"ON" : @"OFF",
                kOversamplingFactorMap[oversamplingIndex],
                adsrBug ? @"BUG" : @"CLEAN",
                ArpSIDTempoSyncShortString(tel.arpFollowHost || arpRateNorm <= 0.005f),
                ArpSIDTempoSyncShortString(tel.seqFollowHost || seqTempoNorm <= 0.005f),
                [NSString stringWithUTF8String:ArpSID::drSidMachineModelDisplayName(drumModelNorm)],
                ArpSIDPercentNormString(drumVolume),
                ArpSIDPercentNormString(drumAccent),
                ArpSIDPercentNormString(drumDrive),
                limiterOn ? @"ON" : @"OFF",
                ArpSIDPercentNormString(reverbMix),
                (long)_pianoOctaveOffset,
                ArpSIDPercentNormString(drumPeak)]);
        const float hudGlow=std::clamp(drumPeak * 0.55f + (limiterOn ? 0.10f : 0.0f) + (extRc ? 0.08f : 0.0f), 0.0f, 1.0f);
        ArpSIDSetLabelColorIfNeeded(_optionsHUDLabel, [[c64Yellow() blendedColorWithFraction:(CGFloat)(0.22f + hudGlow*0.48f)
                                                                                      ofColor:c64Cyan()] colorWithAlphaComponent:(0.72f + hudGlow*0.18f)]);
    }
    static const int lfoRateP[]={ArpSID::kParamLFORate,ArpSID::kParamLFO2Rate,ArpSID::kParamLFO3Rate,ArpSID::kParamLFO4Rate};
    static const int lfoDepthP[]={ArpSID::kParamLFODepth,ArpSID::kParamLFO2Depth,ArpSID::kParamLFO3Depth,ArpSID::kParamLFO4Depth};
    static const int lfoShapeP[]={ArpSID::kParamLFOShape,ArpSID::kParamLFO2Shape,ArpSID::kParamLFO3Shape,ArpSID::kParamLFO4Shape};
    static const int lfoSyncP[]={ArpSID::kParamLFOSync,ArpSID::kParamLFO2Sync,ArpSID::kParamLFO3Sync,ArpSID::kParamLFO4Sync};
    if(wantsLfoUI){
        for(int i=0;i<4;++i){
            if(_lfoWaveView[i]){
                [_lfoWaveView[i] updatePhase:tel.lfoPhase[i]
                                       value:tel.lfoValue[i]
                                       depth:[self _cachedParamValue:lfoDepthP[i] defaultCenter:ArpSID::defaultNormalizedParamValue(lfoDepthP[i])]
                                       shape:[self _cachedParamValue:lfoShapeP[i] defaultCenter:ArpSID::defaultNormalizedParamValue(lfoShapeP[i])]
                                        sync:([self _cachedParamValue:lfoSyncP[i] defaultCenter:ArpSID::defaultNormalizedParamValue(lfoSyncP[i])]>0.5f)
                                        rate:[self _cachedParamValue:lfoRateP[i] defaultCenter:ArpSID::defaultNormalizedParamValue(lfoRateP[i])]
                                        beat:hostBeat
                                     playing:tel.hostPlaying];
            }
        }
    }
    if(_seqStepView && wantsDrSidUI){
        const int seqLen=std::max(1,(int)lround([self _cachedParamValue:ArpSID::kParamSeqLength defaultCenter:0.0f]*31.0f)+1);
        const BOOL seqOn=tel.seqEnabled;
        [_seqStepView setCurrentStep:tel.seqStep
                          totalSteps:seqLen
                             enabled:seqOn
                               swing:[self _cachedParamValue:ArpSID::kParamSeqSwing defaultCenter:0.0f]
                            drumMode:drSidOn
                           stepNotes:seqNotes
                           stepGates:seqGates];
    }
    if(wantsDrSidUI){
        for(ArpSIDKnobView*kv in _drum808Knobs){
            [kv set:[self _cachedParamValue:kv.paramID defaultCenter:kv.defaultValue]];
        }
    }
    if([self _tabNeedsRealtimeKnobOverlays:_tab]) {
        [self _refreshKnobRealtimeOverlaysWithTelemetry:tel];
    }
    // Mode-oscillation fix: drive the mode popup from the SAME authoritative
    // (bridge-param) source as _syncPatchAndModePresentation (which is also called
    // below). Previously this used the &tel telemetry snapshot while the
    // presentation path used the param source, so the two writers could disagree
    // and overwrite each other every tick (CLASSIC<->SID REG flicker). Both now
    // resolve identically via _effectiveModeIndexFromTelemetry:nullptr.
    const NSInteger modeIdx = [self _effectiveModeIndexFromTelemetry:nullptr];
    const bool isApplyingPreset = _isApplyingPreset.load(std::memory_order_acquire);
    // Sync the quick family popup from the audible SID selector so the header,
    // SIDCORE/C64 HUD and analogue panels always agree on the active chip.
    if(!isApplyingPreset && _modelPop&&_au){float chipRevision=[self _cachedParamValue:ArpSID::kParamSidChipRevision defaultCenter:ArpSID::sidChipRevisionIndexToNormalized(ArpSID::kSidChipRevisionDefaultIndex)];
        NSInteger idx=ArpSIDQuickModelPopupIndexForChipRevisionNorm(chipRevision);
        if(_modelPop.indexOfSelectedItem!=idx)[_modelPop selectItemAtIndex:idx];}
    if(!isApplyingPreset){
        if(_needsDeferredPresetUISync.exchange(false, std::memory_order_acq_rel)) {
            // GUI-only AU mirror refresh. This intentionally performs reads only:
            // no setParameterValue:, no preset apply, and no StateRoot/kernel restore.
            // It mirrors the final AUv2 host-retained writable parameter surface,
            // including transient controls such as VirtualNote/VirtualGate.
            [self _primeParameterCacheFromBridge:au];
            [self _refreshPresets];
            [self _refreshPatchAndModeFromBridgeState];
            [self _applyCurrentBridgeStateToKnobs];
            [self _syncPatchAndModePresentation];
        } else {
            if(_modePop && _modePop.indexOfSelectedItem != modeIdx) [_modePop selectItemAtIndex:modeIdx];
            [self _syncPresetAndSlotSelectionWithProgram:tel.programNumber
                                                bankSlot:tel.bankSlot
                                              presetName:[self _currentPresetDisplayName]];
            [self _syncPatchAndModePresentation];
        }
    }

    // ── Piano keyboard highlight ────────────────────────────────────────
    // Clear the lit-key highlight when nothing is sounding; otherwise the last
    // played note (often a middle key) stays visually lit and looks "stuck".
    if(_pianoView){
        [_pianoView setHighlightNote:(activeVoices > 0 ? lastMidiNote : -1)];
    }

    // ── LED states ────────────────────────────────────────────────────────
    BOOL midiActive = (activeVoices>0);
    _midiLED.on = midiActive;
    _midiActLED.on = midiActive;
    _sidLED.on=(_tab==ArpSIDTabSidReg||tel.activeVoices>0);
    _arpLED.on=arpOn&&tel.activeVoices>0;
    // Forensic-active: LED turns amber
    if(_au){BOOL forensicOn=[self _cachedParamValue:ArpSID::kParamForensicEnable defaultCenter:0.0f]>0.5f;
        _sidLED.onColor=forensicOn?c64Yellow():c64LtGreen();}
    // DrSID LED flicker on drum hit
    if(_au && drSidOn)
        _arpLED.onColor=c64Red();
    // Bank tab: keep slot highlight in sync with current bankSlot param
    if(!isApplyingPreset && _tab==ArpSIDTabBank && _pBank && _au){
        // Live-bank export reads the AU sticky preset authority.
        const float stickyBankNorm = _au ? [_au getParameterValue:ArpSID::kParamBankSlot] : [self _cachedParamValue:ArpSID::kParamBankSlot defaultCenter:ArpSID::canonicalNormalizedBankSlotValue(0)];
        const int curSlot=ArpSID::canonicalFactorySlotFromNormalizedBankSlot(stickyBankNorm);
        if(curSlot!=_lastObservedBankSlot){
            _lastObservedBankSlot=curSlot;
            [self _bankUpdateSlotHighlight:curSlot panel:_pBank];
        }
    }}

-(void)_applyRealtimeNormalizedParam:(int)pid value:(float)value defaultCenter:(float)center{
    id<ArpSIDUIBridgeLike> au=_au;
    if(!au) return;
    if(pid < 0 || pid >= (int)ArpSID::kNumParams) return;
    const float v = ArpSIDUIClamp01(value, center);
    [self _storeCachedParamValue:pid value:v];
    id<ArpSIDParameterLike> p=[au.parameterTree parameterWithAddress:(AUParameterAddress)pid];
    if(p) [p setValue:v originator:_tok];
    else  [au setParameterValue:v forID:pid];
}

-(const ArpSIDDrumKitDescriptor*)_selectedDrumKitDescriptor{
    NSInteger idx=_drumKitPop ? _drumKitPop.indexOfSelectedItem : 0;
    if(idx < 0) idx = 0;
    const ArpSIDDrumKitDescriptor* kit=ArpSIDDrumKitAtIndex(idx);
    return kit ? kit : ArpSIDDrumKitAtIndex(0);
}

-(NSInteger)_selectedDrumKitIndex{
    NSInteger idx=_drumKitPop ? _drumKitPop.indexOfSelectedItem : 0;
    return std::clamp(idx, (NSInteger)0, ArpSIDDrumKitCount() - 1);
}

-(NSString*)_drumUserKitDirectoryPath{
    NSString* base=[ArpSIDFileBankBridge defaultUserBankDirectory];
    NSString* dir=[base stringByAppendingPathComponent:ArpSIDDrumUserKitLibraryName()];
    ArpSID::ArpSIDFileBank::ensureDirectoryExists(dir.UTF8String);
    return dir;
}

-(NSURL*)_selectedDrumUserKitURL{
    NSInteger idx=_drumUserKitPop ? _drumUserKitPop.indexOfSelectedItem : -1;
    if(idx < 0 || idx >= (NSInteger)_drumUserKitURLs.count) return nil;
    return _drumUserKitURLs[(NSUInteger)idx];
}

-(ArpSIDPatchMetaObj*)_selectedDrumUserKitMeta{
    NSInteger idx=_drumUserKitPop ? _drumUserKitPop.indexOfSelectedItem : -1;
    if(idx < 0 || idx >= (NSInteger)_drumUserKitMetas.count) return nil;
    return _drumUserKitMetas[(NSUInteger)idx];
}

-(void)_refreshDrumUserKitMetaLabel{
    if(!_drumUserKitMetaLabel) return;
    const NSUInteger count=_drumUserKitURLs.count;
    if(count == 0){
        ArpSIDSetLabelStringIfNeeded(_drumUserKitMetaLabel, @"USER BANK EMPTY  •  Save the live DrSID kit or import a .arpsidbank / .json drum library.");
        return;
    }
    NSURL* url=[self _selectedDrumUserKitURL];
    ArpSIDPatchMetaObj* meta=[self _selectedDrumUserKitMeta];
    NSString* status=(_loadedDrumUserKitURL && url && [_loadedDrumUserKitURL.path isEqualToString:url.path]) ? @"LOADED" : @"READY";
    NSString* author=(meta.author.length>0) ? meta.author : @"User";
    NSString* category=(meta.category.length>0) ? meta.category : @"DrSID Kit";
    NSString* tail=(meta.tags.length>0) ? [NSString stringWithFormat:@"  •  %@", meta.tags] : @"";
    ArpSIDSetLabelStringIfNeeded(_drumUserKitMetaLabel, [NSString stringWithFormat:@"USER %@  •  %@  •  %@  •  %lu kits%@",
                                                         status, author, category, (unsigned long)count, tail]);
}

-(void)_reloadDrumUserKitLibrarySelectingPath:(NSString* _Nullable)selectedPath{
    NSString* dir=[self _drumUserKitDirectoryPath];
    NSURL* dirURL=[NSURL fileURLWithPath:dir isDirectory:YES];
    NSFileManager* fm=[NSFileManager defaultManager];
    NSArray<NSURL*>* urls=[fm contentsOfDirectoryAtURL:dirURL
                            includingPropertiesForKeys:@[NSURLNameKey]
                                               options:NSDirectoryEnumerationSkipsHiddenFiles
                                                 error:nil];
    urls=[urls sortedArrayUsingComparator:^NSComparisonResult(NSURL* a, NSURL* b){
        return [a.lastPathComponent localizedStandardCompare:b.lastPathComponent];
    }];

    NSMutableArray<NSURL*>* drumURLs=[NSMutableArray array];
    NSMutableArray<ArpSIDPatchMetaObj*>* drumMetas=[NSMutableArray array];
    for(NSURL* url in urls){
        ArpSID::SidStateRootV1 root{};
        ArpSID::ArpSIDFilePatchMeta meta{};
        const NSString* ext=url.pathExtension.lowercaseString;
        if([ext isEqualToString:@"json"]){
            NSString* errorText=nil;
            NSDictionary* doc=ArpSIDReadJSONDocumentFromURL(url, &errorText);
            if(!doc || !ArpSIDParseJSONPatchDocument(doc, root, meta, &errorText)) continue;
        } else {
            if(![ext isEqualToString:@"arpsid"]) continue;
            if(ArpSID::ArpSIDFileBank::loadPatchFromFile(url.path.UTF8String, root, meta) != ArpSID::FileBankError::OK) continue;
        }
        if(!ArpSIDPatchMetaLooksLikeDrumKit(meta, root)) continue;
        [drumURLs addObject:url];
        [drumMetas addObject:ArpSIDPatchMetaObjectFromFileMeta(meta)];
    }

    _drumUserKitURLs=[drumURLs copy];
    _drumUserKitMetas=[drumMetas copy];
    if(_drumUserKitPop){
        [_drumUserKitPop removeAllItems];
        if(_drumUserKitURLs.count == 0){
            [_drumUserKitPop addItemWithTitle:@"No Saved User Kits"];
            _drumUserKitPop.enabled=NO;
        } else {
            for(NSUInteger i=0;i<_drumUserKitURLs.count;++i){
                NSURL* url=_drumUserKitURLs[i];
                ArpSIDPatchMetaObj* meta=_drumUserKitMetas[i];
                NSString* title=ArpSIDDrumUserKitPopupTitleForObj(meta, url.URLByDeletingPathExtension.lastPathComponent);
                [_drumUserKitPop addItemWithTitle:title];
            }
            _drumUserKitPop.enabled=YES;
            NSInteger selectIdx=0;
            NSString* preferred=selectedPath ? selectedPath : _loadedDrumUserKitURL.path;
            if(preferred.length){
                NSInteger found=NSNotFound;
                for(NSUInteger i=0;i<_drumUserKitURLs.count;++i){
                    if([_drumUserKitURLs[i].path isEqualToString:preferred]){ found=(NSInteger)i; break; }
                }
                if(found != NSNotFound) selectIdx=found;
            }
            [_drumUserKitPop selectItemAtIndex:std::clamp(selectIdx, (NSInteger)0, (NSInteger)_drumUserKitURLs.count - 1)];
        }
    }
    [self _refreshDrumUserKitMetaLabel];
}

-(void)_reloadDrumUserKitLibrary{
    [self _reloadDrumUserKitLibrarySelectingPath:_loadedDrumUserKitURL.path];
}

-(void)_syncDrumKitPopupToBankSlotIfKnown:(NSInteger)slot{
    if(!_drumKitPop) return;
    const ArpSIDDrumKitDescriptor* current=[self _selectedDrumKitDescriptor];
    if(current && current->slot == slot) return;
    const NSInteger idx=ArpSIDDrumKitIndexForSlot(slot);
    if(idx >= 0 && _drumKitPop.indexOfSelectedItem != idx) {
        [_drumKitPop selectItemAtIndex:idx];
    }
}

-(void)_refreshDrumQuickKitChrome{
    if(!_drumKitSeg) return;
    _drumKitSeg.segmentCount=6;
    for(NSInteger i=0;i<6;++i){
        [_drumKitSeg setLabel:ArpSIDDrumQuickKitLabelForFlavorSegment(_componentFlavor, i) forSegment:i];
    }
    _drumKitSeg.toolTip=(_componentFlavor == ArpSID::ComponentFlavor::Sid808)
        ? @"Quick SID-808 kit families: curated drum-authored kits centered on the Analog X0X-8 baseline and SIDCORE/C64 bus checks."
        : @"Quick authored DrSID kits: loads the matching GM drum-role factory preset.";
    [(ArpSIDSegmentedToolTipControl*)_drumKitSeg setSegmentToolTips:ArpSIDDrumQuickKitSegmentTooltipsForFlavor(_componentFlavor)];
    const ArpSIDDrumKitDescriptor* kit=[self _selectedDrumKitDescriptor];
    const NSInteger segIdx=ArpSIDDrumKitSegmentForFlavorSlot(_componentFlavor, kit ? kit->slot : -1);
    _drumKitSeg.selectedSegment=segIdx;
    if(_drumKitPop){
        for(NSInteger i=0;i<_drumKitPop.numberOfItems && i<ArpSIDDrumKitCount();++i){
            NSString* title=ArpSIDDrumKitPopupTitleAtIndex(i);
            if(![[_drumKitPop itemAtIndex:i].title isEqualToString:title]){
                [[_drumKitPop itemAtIndex:i] setTitle:title];
            }
        }
        _drumKitPop.toolTip=(_componentFlavor == ArpSID::ComponentFlavor::Sid808)
            ? @"Select the active SID-808 kit family. The dedicated flavor keeps the Analog X0X-8 model forced while the shared DrSID core renders the sound."
            : @"Select the active DrSID / Analog X0X-8 kit while keeping the 12-pad performance layout fixed.";
    }
}

-(void)_refreshDrumKitPresentationIfNeededForBankSlot:(NSInteger)slot{
    const NSInteger kitIdx=[self _selectedDrumKitIndex];
    if(_lastPresentedDrumKitIndex == kitIdx &&
       _lastPresentedDrumKitSlot == slot &&
       _lastPresentedDrumSeqPage == _drumSeqPage &&
       _lastPresentedDrumMidiNote == _selectedDrumMidiNote) {
        return;
    }
    [self _refreshDrumKitPresentation];
}

-(void)_refreshDrumKitPresentation{
    const ArpSIDDrumKitDescriptor* kit=[self _selectedDrumKitDescriptor];
    const NSInteger kitIdx=[self _selectedDrumKitIndex];
    if(_selectedDrumMidiNote < 0 || !ArpSIDDrumPerformancePadContainsMidiNote(_selectedDrumMidiNote))
        _selectedDrumMidiNote = kArpSIDDrumPerformancePadNotes[0];
    if(_drumPadView && _lastConfiguredDrumKitIndex != kitIdx) {
        [_drumPadView configurePadNotes:kArpSIDDrumPerformancePadNotes count:kArpSIDDrumPerformancePadCount];
        _lastConfiguredDrumKitIndex = kitIdx;
    }
    if(_drumKitSeg){
        const NSInteger segIdx=ArpSIDDrumKitSegmentForFlavorSlot(_componentFlavor, kit ? kit->slot : -1);
        if(segIdx >= 0 && _drumKitSeg.selectedSegment != segIdx) _drumKitSeg.selectedSegment = segIdx;
    }
    if(_drumSeqPageSeg && _drumSeqPageSeg.selectedSegment != _drumSeqPage) {
        _drumSeqPageSeg.selectedSegment = _drumSeqPage;
    }
    if(_drumKitInfoLabel && kit){
        NSString* noteInfo=ArpSIDGMDrumName(_selectedDrumMidiNote >= 0 ? _selectedDrumMidiNote : kit->padNotes[0]);
        NSString* padInfo=ArpSIDDrumPerformancePadTitle(_selectedDrumMidiNote >= 0 ? _selectedDrumMidiNote : kit->padNotes[0]);
        NSString* pageInfo=_drumSeqPage == 0 ? @"PAGE 1-16" : @"PAGE 17-32";
        const ArpSIDDrumKitMotionProfile* motion=ArpSIDDrumKitMotionProfileAtIndex(kitIdx);
        const float bpm = motion ? (40.0f + motion->seqTempo * 240.0f) : 120.0f;
        NSString* slotInfo = kit->slot >= 0 ? [NSString stringWithFormat:@"S%03ld", (long)kit->slot + 1] : @"USER";
        if(_componentFlavor == ArpSID::ComponentFlavor::Sid808){
            ArpSIDSetLabelStringIfNeeded(_drumKitInfoLabel, [NSString stringWithFormat:@"808 %@  •  %s  •  %s  •  %@  •  %.0f BPM  •  PAD %@ / %@  •  SIDCORE",
                                                             slotInfo,
                                                             kit->title,
                                                             kit->subtitle,
                                                             pageInfo,
                                                             bpm,
                                                             padInfo,
                                                             noteInfo]);
        } else {
            ArpSIDSetLabelStringIfNeeded(_drumKitInfoLabel, [NSString stringWithFormat:@"%@  •  %s  •  %s  •  %@  •  %.0f BPM  •  PAD %@ / %@",
                                                             slotInfo,
                                                             kit->title,
                                                             kit->subtitle,
                                                             pageInfo,
                                                             bpm,
                                                             padInfo,
                                                             noteInfo]);
        }
    }
    _lastPresentedDrumKitIndex = kitIdx;
    _lastPresentedDrumKitSlot = kit ? (NSInteger)kit->slot : -1;
    _lastPresentedDrumSeqPage = _drumSeqPage;
    _lastPresentedDrumMidiNote = _selectedDrumMidiNote;
    [self _refreshDrumUserKitMetaLabel];
}

-(void)_applySelectedDrumKitRealtimeSetup{
    if(![self _requireBridgeForAction:[NSString stringWithUTF8String:__func__]]) return;
    const NSInteger idx=[self _selectedDrumKitIndex];
    const ArpSIDDrumKitToneProfile* tone=ArpSIDDrumKitToneProfileAtIndex(idx);
    const ArpSIDDrumKitMotionProfile* motion=ArpSIDDrumKitMotionProfileAtIndex(idx);
    if(!tone || !motion) return;
    [self _applyModeSelectionIndex:2];
    [self _applyRealtimeNormalizedParam:(int)ArpSID::kParamDrSidVolume value:tone->drumVolume defaultCenter:0.84f];
    [self _applyRealtimeNormalizedParam:(int)ArpSID::kParamDrSidKickTune value:tone->kickTune defaultCenter:0.44f];
    [self _applyRealtimeNormalizedParam:(int)ArpSID::kParamDrSidKickDecay value:tone->kickDecay defaultCenter:0.30f];
    [self _applyRealtimeNormalizedParam:(int)ArpSID::kParamDrSidSnareTone value:tone->snareTone defaultCenter:0.55f];
    [self _applyRealtimeNormalizedParam:(int)ArpSID::kParamDrSidSnareSnap value:tone->snareSnap defaultCenter:0.70f];
    [self _applyRealtimeNormalizedParam:(int)ArpSID::kParamDrSidHatTune value:tone->hatTune defaultCenter:0.72f];
    [self _applyRealtimeNormalizedParam:(int)ArpSID::kParamDrSidHatDecay value:tone->hatDecay defaultCenter:0.20f];
    [self _applyRealtimeNormalizedParam:(int)ArpSID::kParamDrSidClapDecay value:tone->clapDecay defaultCenter:0.26f];
    [self _applyRealtimeNormalizedParam:(int)ArpSID::kParamDrSidCowbellTune value:tone->cowbellTune defaultCenter:0.74f];
    [self _applyRealtimeNormalizedParam:(int)ArpSID::kParamDrSidCowbellDecay value:tone->cowbellDecay defaultCenter:0.38f];
    [self _applyRealtimeNormalizedParam:(int)ArpSID::kParamDrSidTomTune value:tone->tomTune defaultCenter:0.55f];
    [self _applyRealtimeNormalizedParam:(int)ArpSID::kParamDrSidTomDecay value:tone->tomDecay defaultCenter:0.30f];
    [self _applyRealtimeNormalizedParam:(int)ArpSID::kParamDrSidMachineModel value:tone->machineModel defaultCenter:0.0f];
    [self _applyRealtimeNormalizedParam:(int)ArpSID::kParamDrSidAccentAmount value:tone->accentAmount defaultCenter:0.68f];
    [self _applyRealtimeNormalizedParam:(int)ArpSID::kParamDrSidOutputDrive value:tone->outputDrive defaultCenter:0.18f];
    [self _applyRealtimeNormalizedParam:(int)ArpSID::kParamDrSidHatMetal value:tone->hatMetal defaultCenter:0.62f];
    [self _applyRealtimeNormalizedParam:(int)ArpSID::kParamDrSidClapSpread value:tone->clapSpread defaultCenter:0.54f];
    [self _applyRealtimeNormalizedParam:(int)ArpSID::kParamSeqTempo value:motion->seqTempo defaultCenter:0.34f];
    [self _applyRealtimeNormalizedParam:(int)ArpSID::kParamSeqSwing value:motion->seqSwing defaultCenter:0.05f];
    [self _applyRealtimeNormalizedParam:(int)ArpSID::kParamLFOSync value:motion->lfo1Sync defaultCenter:1.0f];
    [self _applyRealtimeNormalizedParam:(int)ArpSID::kParamLFORate value:motion->lfo1Rate defaultCenter:0.18f];
    [self _applyRealtimeNormalizedParam:(int)ArpSID::kParamLFODepth value:motion->lfo1Depth defaultCenter:0.24f];
    [self _applyRealtimeNormalizedParam:(int)ArpSID::kParamLFO2Sync value:motion->lfo2Sync defaultCenter:0.0f];
    [self _applyRealtimeNormalizedParam:(int)ArpSID::kParamLFO2Rate value:motion->lfo2Rate defaultCenter:0.12f];
    [self _applyRealtimeNormalizedParam:(int)ArpSID::kParamLFO2Depth value:motion->lfo2Depth defaultCenter:0.08f];
    _needsDeferredPresetUISync.store(true, std::memory_order_release);
}

-(void)_queueApplySelectedDrumKitRealtimeSetup{
    const NSUInteger serial=++_drumKitSetupSerial;
    __weak ArpSIDViewController* weakSelf=self;
    dispatch_async(dispatch_get_main_queue(), ^{
        ArpSIDViewController* strongSelf=weakSelf;
        if(!strongSelf) return;
        if(serial != strongSelf->_drumKitSetupSerial) return;
        [strongSelf _applySelectedDrumKitRealtimeSetup];
    });
}

-(NSInteger)_currentBankSlotFromBridgeOrCache{
    if(_currentStateBackedByLoadedBank && _currentLoadedBankSlot >= 0){
        return std::clamp(_currentLoadedBankSlot, (NSInteger)0, (NSInteger)ArpSID::kCanonicalFactoryPatchSlotMax);
    }
    const float bankNorm = _au ? [_au getParameterValue:ArpSID::kParamBankSlot]
                               : [self _cachedParamValue:ArpSID::kParamBankSlot defaultCenter:ArpSID::canonicalNormalizedBankSlotValue(0)];
    return (NSInteger)ArpSID::canonicalFactorySlotFromNormalizedBankSlot(bankNorm);
}

-(void)_deferFactoryDrumKitApplyForSlot:(NSInteger)slot applyRealtimeProfile:(BOOL)applyRealtimeProfile{
    if(!_au) return;
    // v967: GUI-only quick kits (e.g. "Standard") carry slot -1 and have no
    // backing factory patch. The old guard returned here for slot < 0, so
    // selecting such a kit applied nothing to audio yet still reported
    // "Loaded DrSID kit …". Apply the curated realtime tone/motion profile for
    // those kits; only the factory-patch load is skipped when no slot backs it.
    const BOOL hasFactorySlot = (slot >= 0 && slot <= ArpSID::kCanonicalFactoryPatchSlotMax);
    if(!hasFactorySlot && !applyRealtimeProfile) return; // nothing to apply
    const NSUInteger serial=++_drumKitSetupSerial;
    __weak ArpSIDViewController* weakSelf=self;
    dispatch_async(dispatch_get_main_queue(), ^{
        ArpSIDViewController* strongSelf=weakSelf;
        if(!strongSelf) return;
        if(serial != strongSelf->_drumKitSetupSerial) return;
        if(hasFactorySlot) [strongSelf _applyPatchSelectionNumber:slot];
        if(applyRealtimeProfile) [strongSelf _applySelectedDrumKitRealtimeSetup];
        [strongSelf _refreshPatchAndModeFromBridgeState];
        [strongSelf _refreshDrumKitPresentation];
        strongSelf->_needsDeferredPresetUISync.store(true, std::memory_order_release);
    });
}

-(void)_syncDedicatedDrumKitSelectionWithFlavorDefaults:(BOOL)repairAudioState{
    if(!_drumKitPop) return;
    if(!ArpSID::componentFlavorIsDedicatedDrum(_componentFlavor)) return;
    if(_loadedDrumUserKitURL){
        [self _refreshDrumQuickKitChrome];
        [self _refreshDrumKitPresentation];
        return;
    }
    const NSInteger currentBankSlot=[self _currentBankSlotFromBridgeOrCache];
    NSInteger desiredSlot=currentBankSlot;
    if(!ArpSIDFactorySlotAllowedForFlavor(_componentFlavor, desiredSlot) ||
       ArpSIDDrumKitIndexForSlot(desiredSlot) < 0) {
        desiredSlot=ArpSIDStartupFactorySlotForFlavorUI(_componentFlavor);
    }
    const NSInteger desiredKitIdx=ArpSIDDrumKitIndexForSlot(desiredSlot);
    if(desiredKitIdx >= 0 && _drumKitPop.indexOfSelectedItem != desiredKitIdx) {
        [_drumKitPop selectItemAtIndex:desiredKitIdx];
    } else {
        [self _syncDrumKitPopupToBankSlotIfKnown:desiredSlot];
    }
    const ArpSIDDrumKitDescriptor* kit=[self _selectedDrumKitDescriptor];
    if(kit && !kit->padNotes.empty()) _selectedDrumMidiNote = kit->padNotes[0];
    [self _refreshDrumQuickKitChrome];
    [self _refreshDrumKitPresentation];
    if(repairAudioState && !_currentStateBackedByLoadedBank && currentBankSlot != desiredSlot && desiredKitIdx >= 0){
        [self _deferFactoryDrumKitApplyForSlot:desiredSlot applyRealtimeProfile:YES];
    }
}

-(void)_loadDrumUserKitURL:(NSURL*)url announce:(BOOL)announce{
    if(!_au || !url) return;
    [self _releasePendingDrumAuditionNow];
    ArpSIDDSPKernelAdapter* adapter=nil;
    if([_au respondsToSelector:@selector(kernelAdapter)]) adapter=[_au performSelector:@selector(kernelAdapter)];
    ArpSIDPatchMetaObj* metaOut=nil;
    const ArpSIDFileBankResult res=[self _loadPatchDocumentFromURL:url adapter:adapter metaOut:&metaOut];
    if(res == ArpSIDFileBankResultOK){
        [self _markCurrentStateAsExternalPatch];
        _loadedDrumUserKitURL=url;
        _lastConfiguredDrumKitIndex=-1;
        _needsDeferredPresetUISync.store(true, std::memory_order_release);
        [self _reloadDrumUserKitLibrarySelectingPath:url.path];
        [self _refreshDrumKitPresentation];
        [self _applyCurrentBridgeStateToKnobs];
        [self _poll];
        if(announce && _pBank){
            NSString* name=(metaOut.name.length>0) ? metaOut.name : url.URLByDeletingPathExtension.lastPathComponent;
            [self _bankSetStatus:[NSString stringWithFormat:@"Loaded user DrSID kit ← %@", name] panel:_pBank];
        }
    } else if(_pBank){
        [self _bankSetStatus:[NSString stringWithFormat:@"User kit load failed: %@",
                              [ArpSIDFileBankBridge stringForResult:res]]
                       panel:_pBank];
    }
}

-(void)_drumUserKitPopChg:(id)sender{
    (void)sender;
    NSURL* url=[self _selectedDrumUserKitURL];
    if(!url) return;
    [self _loadDrumUserKitURL:url announce:YES];
}

-(void)_drumSaveUserKit:(id)sender{
    (void)sender;
    if(!_au){
        if(_pBank) [self _bankSetStatus:@"No AU connected." panel:_pBank];
        return;
    }
    NSSavePanel* sp=[NSSavePanel savePanel];
    arpsidSetPanelTypes(sp, @[@"arpsid", @"json"]);
    NSString* selectedName=[self _selectedDrumUserKitURL].URLByDeletingPathExtension.lastPathComponent;
    NSString* presetName=[self _currentPresetDisplayName];
    NSString* defaultName=(selectedName.length>0) ? selectedName : [NSString stringWithFormat:@"%@ Kit", presetName];
    sp.nameFieldStringValue=[defaultName stringByAppendingPathExtension:@"arpsid"];
    sp.directoryURL=[NSURL fileURLWithPath:[self _drumUserKitDirectoryPath] isDirectory:YES];
    ArpSIDViewController* __weak ws=self;
    void(^handler)(NSModalResponse)=^(NSModalResponse r){
        ArpSIDViewController* s=ws;
        if(!s||!s->_au||r!=NSModalResponseOK||!sp.URL) return;
        NSURL* kitURL = [sp.URL copy];
        NSString* kitFileName = [kitURL.lastPathComponent copy];
        NSString* patchStem = [kitURL.URLByDeletingPathExtension.lastPathComponent copy];
        ArpSIDFileBankBridge* bridge=[[ArpSIDFileBankBridge alloc] init];
        ArpSIDDSPKernelAdapter* adapter=nil;
        if([s->_au respondsToSelector:@selector(kernelAdapter)]) adapter=[s->_au performSelector:@selector(kernelAdapter)];
        ArpSIDPatchMetaObj* meta=[bridge metaFromKernel:adapter
                                                   name:patchStem
                                                 author:@"User"
                                               category:@"DrSID Kit"];
        ArpSIDPatchMetaObj* existing=[s _selectedDrumUserKitMeta];
        if(existing){
            if(existing.author.length>0) meta.author=existing.author;
            if(existing.tags.length>0) meta.tags=existing.tags;
        }
        meta.role=(NSInteger)ArpSID::PatchRole::Drum;
        if(meta.tags.length == 0) meta.tags=@"drsid gm drumkit midi";
        const ArpSIDFileBankResult res=[s _saveDrumKitDocumentToURL:kitURL adapter:adapter meta:meta];
        NSString* msg=(res==ArpSIDFileBankResultOK)
            ? [NSString stringWithFormat:@"Saved user DrSID kit → %@", kitFileName]
            : [NSString stringWithFormat:@"User kit save failed: %@", [ArpSIDFileBankBridge stringForResult:res]];
        dispatch_async(dispatch_get_main_queue(), ^{
            ArpSIDViewController* ss = ws; if(!ss) return;
            if(res==ArpSIDFileBankResultOK){
                ss->_loadedDrumUserKitURL=kitURL;
                [ss _reloadDrumUserKitLibrarySelectingPath:kitURL.path];
            }
            if(ss->_pBank) [ss _bankSetStatus:msg panel:ss->_pBank];
        });
    };
    NSWindow* win=self.view.window ? self.view.window : NSApp.keyWindow;
    if(win) [sp beginSheetModalForWindow:win completionHandler:handler];
    else    handler([sp runModal]);
}

-(void)_drumRefreshUserKitLibrary:(id)sender{
    (void)sender;
    [self _reloadDrumUserKitLibrary];
    if(_pBank){
        [self _bankSetStatus:[NSString stringWithFormat:@"Refreshed DrSID user kit library  (%lu kits)",
                              (unsigned long)_drumUserKitURLs.count]
                       panel:_pBank];
    }
}

-(void)_drumExportUserKitBank:(id)sender{
    (void)sender;
    NSSavePanel* sp=[NSSavePanel savePanel];
    arpsidSetPanelTypes(sp, @[@"arpsidbank", @"json"]);
    sp.nameFieldStringValue=@"DrSID_User_Kits.arpsidbank";
    sp.directoryURL=[NSURL fileURLWithPath:[ArpSIDFileBankBridge defaultUserBankDirectory] isDirectory:YES];
    ArpSIDViewController* __weak ws=self;
    void(^handler)(NSModalResponse)=^(NSModalResponse r){
        ArpSIDViewController* s=ws;
        if(!s||r!=NSModalResponseOK||!sp.URL) return;
        NSURL* exportURL = [sp.URL copy];
        NSString* exportFileName = [exportURL.lastPathComponent copy];
        NSArray<NSURL*>* capture=[s->_drumUserKitURLs copy];
        if(capture.count == 0){
            if(s->_pBank) [s _bankSetStatus:@"No saved DrSID user kits to export." panel:s->_pBank];
            return;
        }
        dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
            std::vector<ArpSID::SidStateRootV1> patches;
            std::vector<ArpSID::ArpSIDFilePatchMeta> metas;
            patches.reserve(capture.count);
            metas.reserve(capture.count);
            for(NSURL* url in capture){
                ArpSID::SidStateRootV1 root{};
                ArpSID::ArpSIDFilePatchMeta meta{};
                if(ArpSIDPathUsesJSON(url.path)){
                    NSString* errorText=nil;
                    NSDictionary* doc=ArpSIDReadJSONDocumentFromURL(url, &errorText);
                    if(!doc || !ArpSIDParseJSONPatchDocument(doc, root, meta, &errorText)) continue;
                } else if(ArpSID::ArpSIDFileBank::loadPatchFromFile(url.path.UTF8String, root, meta) != ArpSID::FileBankError::OK) {
                    continue;
                }
                if(!ArpSIDPatchMetaLooksLikeDrumKit(meta, root)) continue;
                ArpSID::sidSetStateRootParamValue(root, (int)ArpSID::kParamDrSidEnable, 1.0f);
                ArpSID::sidSetStateRootParamValue(root, (int)ArpSID::kParamSynthModeEnable, 0.0f);
                ArpSID::sidEnsureSemanticParameterEntries(root);
                patches.push_back(root);
                metas.push_back(meta);
            }
            const NSUInteger exportedCount=(NSUInteger)patches.size();
            const auto err=patches.empty()
                ? ArpSID::FileBankError::BadBlob
                : ArpSIDSaveBankDocumentToURL_v781(exportURL, patches, metas, @"DrSID User Kits");
            dispatch_async(dispatch_get_main_queue(), ^{
                ArpSIDViewController* strongSelf=ws;
                if(!strongSelf || !strongSelf->_pBank) return;
                if(err == ArpSID::FileBankError::OK){
                    [strongSelf _bankSetStatus:[NSString stringWithFormat:@"Exported %lu DrSID user kits → %@",
                                                (unsigned long)exportedCount, exportFileName]
                                         panel:strongSelf->_pBank];
                } else {
                    [strongSelf _bankSetStatus:[NSString stringWithFormat:@"DrSID bank export failed: %s",
                                                ArpSID::fileBankErrorString(err)]
                                         panel:strongSelf->_pBank];
                }
            });
        });
    };
    NSWindow* win=self.view.window ? self.view.window : NSApp.keyWindow;
    if(win) [sp beginSheetModalForWindow:win completionHandler:handler];
    else    handler([sp runModal]);
}

-(void)_drumImportUserKitBank:(id)sender{
    (void)sender;
    NSOpenPanel* op=[NSOpenPanel openPanel];
    arpsidSetPanelTypes(op, @[@"arpsidbank", @"json"]);
    op.directoryURL=[NSURL fileURLWithPath:[ArpSIDFileBankBridge defaultUserBankDirectory] isDirectory:YES];
    ArpSIDViewController* __weak ws=self;
    void(^handler)(NSModalResponse)=^(NSModalResponse r){
        ArpSIDViewController* s=ws;
        if(!s||r!=NSModalResponseOK||!op.URL) return;
        NSURL* importURL = [op.URL copy];
        NSString* importFileName = [importURL.lastPathComponent copy];
        NSString* kitDir=[s _drumUserKitDirectoryPath];
        dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
            std::vector<ArpSID::SidStateRootV1> patches;
            std::vector<ArpSID::ArpSIDFilePatchMeta> metas;
            const auto err=ArpSIDLoadBankDocumentFromURL_v781(importURL, patches, metas);
            NSUInteger imported=0;
            NSString* firstImportedPath=nil;
            if(err == ArpSID::FileBankError::OK){
                const std::string kitDirStr=kitDir.UTF8String;
                ArpSID::ArpSIDFileBank::ensureDirectoryExists(kitDirStr);
                for(size_t i=0;i<patches.size() && i<metas.size();++i){
                    auto meta=metas[i];
                    if(!ArpSIDPatchMetaLooksLikeDrumKit(meta, patches[i])) continue;
                    meta.role=(uint8_t)ArpSID::PatchRole::Drum;
                    ArpSID::SidStateRootV1 root=patches[i];
                    ArpSID::sidSetStateRootParamValue(root, (int)ArpSID::kParamDrSidEnable, 1.0f);
                    ArpSID::sidSetStateRootParamValue(root, (int)ArpSID::kParamSynthModeEnable, 0.0f);
                    ArpSID::sidEnsureSemanticParameterEntries(root);
                    std::string base=ArpSID::ArpSIDFileBank::sanitizeFilename(meta.name[0] ? meta.name : "DrSID_Kit");
                    if(base.empty()) base="DrSID_Kit";
                    std::string candidate=ArpSID::ArpSIDFileBank::joinPath(kitDirStr, base + std::string(ArpSID::ArpSIDFileBank::kPatchExt));
                    int suffix=2;
                    while(ArpSID::ArpSIDFileBank::fileExists(candidate)){
                        candidate=ArpSID::ArpSIDFileBank::joinPath(
                            kitDirStr, base + "_" + std::to_string(suffix++) + std::string(ArpSID::ArpSIDFileBank::kPatchExt));
                    }
                    if(ArpSID::ArpSIDFileBank::savePatchToFile(candidate, root, meta) != ArpSID::FileBankError::OK) continue;
                    ++imported;
                    if(!firstImportedPath) firstImportedPath=[NSString stringWithUTF8String:candidate.c_str()];
                }
            }
            dispatch_async(dispatch_get_main_queue(), ^{
                ArpSIDViewController* strongSelf=ws;
                if(!strongSelf) return;
                if(err == ArpSID::FileBankError::OK && imported > 0){
                    strongSelf->_loadedDrumUserKitURL=firstImportedPath.length ? [NSURL fileURLWithPath:firstImportedPath] : strongSelf->_loadedDrumUserKitURL;
                    [strongSelf _reloadDrumUserKitLibrarySelectingPath:firstImportedPath];
                    if(strongSelf->_pBank){
                        [strongSelf _bankSetStatus:[NSString stringWithFormat:@"Imported %lu DrSID kits ← %@",
                                                    (unsigned long)imported, importFileName]
                                             panel:strongSelf->_pBank];
                    }
                } else if(strongSelf->_pBank){
                    NSString* msg=(err != ArpSID::FileBankError::OK)
                        ? [NSString stringWithFormat:@"DrSID bank import failed: %s", ArpSID::fileBankErrorString(err)]
                        : @"No drum-role kits found in bank.";
                    [strongSelf _bankSetStatus:msg panel:strongSelf->_pBank];
                }
            });
        });
    };
    NSWindow* win=self.view.window ? self.view.window : NSApp.keyWindow;
    if(win) [op beginSheetModalForWindow:win completionHandler:handler];
    else    handler([op runModal]);
}

-(void)_setSequencerStep:(NSInteger)step note:(int)note velocity:(float)velocity gate:(float)gate{
    if(!_au || step < 0 || step >= 32) return;
    const int base=(int)ArpSID::kParamSeqStep1Note + (int)step*3;
    [self _applyRealtimeNormalizedParam:base value:std::clamp((float)note / 127.0f, 0.0f, 1.0f) defaultCenter:60.0f/127.0f];
    [self _applyRealtimeNormalizedParam:base+1 value:std::clamp(std::isfinite(velocity) ? velocity : 0.85f, 0.0f, 1.0f) defaultCenter:0.75f];
    [self _applyRealtimeNormalizedParam:base+2 value:std::clamp(std::isfinite(gate) ? gate : 1.0f, 0.0f, 1.0f) defaultCenter:1.0f];
    _needsDeferredPresetUISync.store(true, std::memory_order_release);
}

-(void)_clearDrumSeqPage:(NSInteger)page{
    const NSInteger start=std::clamp(page, (NSInteger)0, (NSInteger)1) * 16;
    for(NSInteger i=0;i<16;++i){
        const NSInteger step=start+i;
        const int base=(int)ArpSID::kParamSeqStep1Note + (int)step*3;
        const int fallbackNote=(_selectedDrumMidiNote >= 0) ? _selectedDrumMidiNote : 36;
        [self _applyRealtimeNormalizedParam:base value:std::clamp((float)fallbackNote / 127.0f, 0.0f, 1.0f) defaultCenter:60.0f/127.0f];
        [self _applyRealtimeNormalizedParam:base+1 value:0.0f defaultCenter:0.75f];
        [self _applyRealtimeNormalizedParam:base+2 value:0.0f defaultCenter:1.0f];
    }
    _needsDeferredPresetUISync.store(true, std::memory_order_release);
}

-(void)_stampSelectedDrumKitPatternToCurrentPage{
    const ArpSIDDrumKitDescriptor* kit=[self _selectedDrumKitDescriptor];
    if(!_au || !kit) return;
    const NSInteger start=std::clamp(_drumSeqPage, (NSInteger)0, (NSInteger)1) * 16;
    const int currentSeqSteps=std::clamp((int)lround(ArpSIDUIClamp01([_au getParameterValue:ArpSID::kParamSeqLength]) * 31.0f) + 1, 1, 32);
    const int targetSeqSteps=std::max(currentSeqSteps, (int)start + 16);
    const float seqLenNorm=(float)(targetSeqSteps - 1) / 31.0f;
    [self _applyModeSelectionIndex:2];
    [self _applyRealtimeNormalizedParam:ArpSID::kParamSeqEnable value:1.0f defaultCenter:0.0f];
    [self _applyRealtimeNormalizedParam:ArpSID::kParamSeqLength value:seqLenNorm defaultCenter:15.0f/31.0f];
    for(NSInteger i=0;i<16;++i){
        [self _setSequencerStep:start+i
                           note:kit->patternNotes[(size_t)i]
                       velocity:kit->patternVelocities[(size_t)i]
                           gate:kit->patternGates[(size_t)i]];
    }
    if(_pBank){
        [self _bankSetStatus:[NSString stringWithFormat:@"Stamped DrSID kit %s into steps %ld-%ld",
                              kit->title, (long)(start+1), (long)(start+16)]
                       panel:_pBank];
    }
}

-(void)_sendDrumMidiNoteOff:(int)midiNote{
    if(!_au || midiNote < 0) return;
    const uint8_t data[3] = {0x89u, (uint8_t)std::clamp(midiNote,0,127), 0u};
    [_au injectMIDIBytes:data length:3];
}

-(void)_releasePendingDrumAuditionNow{
    if(_pendingDrumAuditionNote >= 0){
        [self _sendDrumMidiNoteOff:_pendingDrumAuditionNote];
        _pendingDrumAuditionNote = -1;
    }
}

-(void)_drumKitPopChg:(id)sender{
    (void)sender;
    const ArpSIDDrumKitDescriptor* kit=[self _selectedDrumKitDescriptor];
    if(kit && !kit->padNotes.empty()) _selectedDrumMidiNote = kit->padNotes[0];
    [self _releasePendingDrumAuditionNow];
    [self _refreshDrumKitPresentation];
    if(!_au || !kit) return;
    [self _deferFactoryDrumKitApplyForSlot:(NSInteger)kit->slot applyRealtimeProfile:YES];
    if(_pBank){
        [self _bankUpdateSlotHighlight:(int)kit->slot panel:_pBank];
        [self _bankSetStatus:[NSString stringWithFormat:@"Loaded DrSID kit %s  –  %@",
                              kit->title,
                              ArpSIDGMDrumName(_selectedDrumMidiNote)]
                       panel:_pBank];
    }
    if(_drumKitSeg) _drumKitSeg.selectedSegment = ArpSIDDrumKitSegmentForFlavorSlot(_componentFlavor, kit->slot);
}

-(void)_drumArmDrSid:(id)sender{
    (void)sender;
    [self _applyModeSelectionIndex:2];
    [self _applyRealtimeNormalizedParam:(int)ArpSID::kParamDrSidEnable value:1.0f defaultCenter:0.0f];
    [self _applyRealtimeNormalizedParam:(int)ArpSID::kParamSynthModeEnable value:0.0f defaultCenter:0.0f];
    [self _applySelectedDrumKitRealtimeSetup];
    [self _refreshDrumKitPresentation];
    [self _poll];
}

-(void)_drumApplyMPKMiniMap:(id)sender{
    (void)sender;
    if(_ccHubLabel){
        _ccHubLabel.stringValue=ArpSIDMPKMiniDefaultMapSummaryString();
        _ccHubLabel.textColor=c64Yellow();
    }
    // Re-project all canonical MPK mini destinations so DSP, render telemetry,
    // and the GUI hub immediately agree after patch load/import/host restore,
    // even before the physical controller sends its first CC.
    for(int i=0;i<8;++i){
        const ArpSID::ParamID pid=ArpSID::sidAkaiMpkMiniDefaultKnobParamByIndex(i);
        if(pid>=0 && pid<ArpSID::kNumParams){
            const float fallback=ArpSID::defaultNormalizedParamValue((int)pid);
            [self _applyRealtimeNormalizedParam:(int)pid
                                          value:[self _cachedParamValue:(int)pid defaultCenter:fallback]
                                  defaultCenter:fallback];
        }
    }
    [self _poll];
}

-(void)_drumKitStamp:(id)sender{
    (void)sender;
    [self _stampSelectedDrumKitPatternToCurrentPage];
    [self _refreshDrumKitPresentation];
    [self _poll];
}

-(void)_drumKitClear:(id)sender{
    (void)sender;
    [self _clearDrumSeqPage:_drumSeqPage];
    if(_pBank){
        const NSInteger start=_drumSeqPage * 16;
        [self _bankSetStatus:[NSString stringWithFormat:@"Cleared DrSID steps %ld-%ld",
                              (long)(start + 1), (long)(start + 16)]
                       panel:_pBank];
    }
    [self _poll];
}

-(void)_drumSeqPageChg:(id)sender{
    NSSegmentedControl* seg=(NSSegmentedControl*)sender;
    _drumSeqPage = std::clamp((NSInteger)seg.selectedSegment, (NSInteger)0, (NSInteger)1);
    [self _refreshDrumKitPresentation];
    [self _poll];
}

-(void)_auditionDrumMidiNote:(int)midiNote velocity:(uint8_t)velocity{
    if(![self _requireBridgeForAction:[NSString stringWithUTF8String:__func__]]) return;
    [self _applyModeSelectionIndex:2];
    [self _releasePendingDrumAuditionNow];
    const uint8_t data[3] = {0x99u, (uint8_t)std::clamp(midiNote,0,127), velocity};
    [_au injectMIDIBytes:data length:3];
    _pendingDrumAuditionNote = std::clamp(midiNote, 0, 127);
    const NSUInteger serial = ++_drumAuditionSerial;
    __weak ArpSIDViewController* weakSelf=self;
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)(0.14 * NSEC_PER_SEC)), dispatch_get_main_queue(), ^{
        ArpSIDViewController* selfRef=weakSelf;
        if(!selfRef) return;
        if(selfRef->_controllerTearingDown_v277_.load(std::memory_order_acquire)) return;
        if(selfRef->_drumAuditionSerial != serial) return;
        if(selfRef->_pendingDrumAuditionNote != midiNote) return;
        if(!selfRef->_au) return;
        [selfRef _sendDrumMidiNoteOff:midiNote];
        selfRef->_pendingDrumAuditionNote = -1;
    });
}

-(void)_handleDrumStepTap:(NSInteger)stepIndex modifiers:(NSEventModifierFlags)modifiers{
    if(!_au || stepIndex < 0 || stepIndex >= 16) return;
    [self _applyModeSelectionIndex:2];
    [self _applyRealtimeNormalizedParam:ArpSID::kParamSeqEnable value:1.0f defaultCenter:0.0f];
    const NSInteger absoluteStep=std::clamp(_drumSeqPage, (NSInteger)0, (NSInteger)1) * 16 + stepIndex;
    const int base=(int)ArpSID::kParamSeqStep1Note + (int)absoluteStep*3;
    const int currentNote=std::clamp((int)lround(ArpSIDUIClamp01([_au getParameterValue:base]) * 127.0f), 0, 127);
    const float currentVel=ArpSIDUIClamp01([_au getParameterValue:base+1], 0.85f);
    const float currentGate=ArpSIDUIClamp01([_au getParameterValue:base+2]);
    if((modifiers & NSEventModifierFlagOption) != 0){
        [self _setSequencerStep:absoluteStep note:currentNote velocity:0.0f gate:0.0f];
        return;
    }

    int targetNote=_selectedDrumMidiNote >= 0 ? _selectedDrumMidiNote : currentNote;
    if(targetNote < 0){
        const ArpSIDDrumKitDescriptor* kit=[self _selectedDrumKitDescriptor];
        targetNote = kit ? kit->padNotes[0] : 36;
    }
    _selectedDrumMidiNote=targetNote;

    float targetVelocity=currentVel > 0.01f ? currentVel : 0.85f;
    float targetGate=currentGate > 0.01f ? currentGate : 1.0f;
    if((modifiers & NSEventModifierFlagShift) != 0){
        targetVelocity = ArpSIDCycleDrumAccentVelocity(currentVel);
        targetGate = currentGate > 0.01f ? currentGate : 1.0f;
    } else if(currentGate > 0.01f && currentNote == targetNote){
        targetGate = currentGate >= 0.99f ? 0.78f : 1.0f;
    } else {
        targetGate = 1.0f;
    }
    [self _setSequencerStep:absoluteStep note:targetNote velocity:targetVelocity gate:targetGate];
    [self _auditionDrumMidiNote:targetNote velocity:(uint8_t)std::clamp((int)lround(targetVelocity * 127.0f), 1, 127)];
    [self _refreshDrumKitPresentation];
}

-(void)_handleDrumPatternLane:(NSInteger)lane stepIndex:(NSInteger)stepIndex modifiers:(NSEventModifierFlags)modifiers{
    if(!_au || lane < 0 || lane >= 4 || stepIndex < 0 || stepIndex >= 16) return;
    [self _applyModeSelectionIndex:2];
    [self _applyRealtimeNormalizedParam:ArpSID::kParamSeqEnable value:1.0f defaultCenter:0.0f];
    const NSInteger absoluteStep=std::clamp(_drumSeqPage, (NSInteger)0, (NSInteger)1) * 16 + stepIndex;
    const int base=(int)ArpSID::kParamSeqStep1Note + (int)absoluteStep*3;
    const int rowNote=ArpSIDDrum808PrimaryNoteForRow((NSUInteger)lane);
    const int currentNote=std::clamp((int)lround(ArpSIDUIClamp01([_au getParameterValue:base]) * 127.0f), 0, 127);
    const float currentVel=ArpSIDUIClamp01([_au getParameterValue:base+1], 0.84f);
    const float currentGate=ArpSIDUIClamp01([_au getParameterValue:base+2]);
    if((modifiers & NSEventModifierFlagOption) != 0){
        [self _setSequencerStep:absoluteStep note:rowNote velocity:0.0f gate:0.0f];
        [self _refreshDrumKitPresentation];
        return;
    }
    _selectedDrumMidiNote=rowNote;
    float targetVelocity=currentVel > 0.01f ? currentVel : (lane == 0 ? 1.0f : 0.84f);
    float targetGate=1.0f;
    if((modifiers & NSEventModifierFlagShift) != 0){
        targetVelocity=ArpSIDCycleDrumAccentVelocity(currentVel);
    } else if(currentGate > 0.01f && ArpSIDDrum808RowMatchesMidiNote((NSUInteger)lane, currentNote)){
        targetGate=currentGate >= 0.99f ? 0.78f : 1.0f;
    }
    [self _setSequencerStep:absoluteStep note:rowNote velocity:targetVelocity gate:targetGate];
    [self _auditionDrumMidiNote:rowNote velocity:(uint8_t)std::clamp((int)lround(targetVelocity * 127.0f), 1, 127)];
    [self _refreshDrumKitPresentation];
}

-(void)_drumPlay:(id)sender{
    (void)sender;
    [self _drumArmDrSid:nil];
    [self _applyRealtimeNormalizedParam:ArpSID::kParamSeqEnable value:1.0f defaultCenter:0.0f];
    [self _poll];
}

-(void)_drumStop:(id)sender{
    (void)sender;
    [self _applyRealtimeNormalizedParam:ArpSID::kParamSeqEnable value:0.0f defaultCenter:0.0f];
    [self _releasePendingDrumAuditionNow];
    [self _poll];
}

-(void)_drumOpenBank:(id)sender{
    (void)sender;
    if(!_tabBar) return;
    _tabBar.selectedSegment=ArpSIDVisibleTabSegmentForFlavor(_componentFlavor, ArpSIDTabBank);
    [self _tabChg:_tabBar];
}

-(void)_drumInitAnalogKit:(id)sender{
    (void)sender;
    const NSInteger kitIdx=ArpSIDDrumKitIndexForSlot(120);
    if(kitIdx >= 0 && _drumKitPop && _drumKitPop.indexOfSelectedItem != kitIdx) {
        [_drumKitPop selectItemAtIndex:kitIdx];
    }
    _drumSeqPage=0;
    if(_drumSeqPageSeg) _drumSeqPageSeg.selectedSegment=0;
    [self _drumKitPopChg:nil];
    [self _stampSelectedDrumKitPatternToCurrentPage];
    [self _refreshDrumKitPresentation];
    [self _poll];
}

-(ArpSIDKnobView*)_knobForParamID:(int)pid{
    return _knobMap[@(pid)];
}

-(float)_modSourceBipolarValue:(ArpSID::SidModSource)src telemetry:(const ArpSIDTelemetry&)tel{
    using namespace ArpSID;
    const float noteNorm=std::clamp((float)ArpSIDUIClampInt(tel.lastMidiNote,0,127,60)/127.0f,0.0f,1.0f);
    const float keyFollow=std::clamp(((float)ArpSIDUIClampInt(tel.lastMidiNote,0,127,60)-60.0f)/48.0f,-1.0f,1.0f);
    switch(src){
        case SidModSource::LFO1: return ArpSIDUIClampSigned(tel.lfoValue[0]);
        case SidModSource::LFO2: return ArpSIDUIClampSigned(tel.lfoValue[1]);
        case SidModSource::LFO3: return ArpSIDUIClampSigned(tel.lfoValue[2]);
        case SidModSource::LFO4: return ArpSIDUIClampSigned(tel.lfoValue[3]);
        case SidModSource::Velocity: return std::clamp(tel.lastNoteVelocity*2.0f-1.0f,-1.0f,1.0f);
        case SidModSource::NoteNumber: return noteNorm*2.0f-1.0f;
        case SidModSource::KeyFollow: return keyFollow;
        case SidModSource::ModWheel: return std::clamp(tel.modWheelNorm*2.0f-1.0f,-1.0f,1.0f);
        case SidModSource::PitchBend: return ArpSIDUIClampSigned(tel.focusedPitchBend);
        case SidModSource::AfterTouch: return std::clamp(tel.focusedChannelPressure*2.0f-1.0f,-1.0f,1.0f);
        case SidModSource::PolyPressure: return std::clamp(tel.focusedPolyPressure*2.0f-1.0f,-1.0f,1.0f);
        case SidModSource::Random: return ArpSIDUIClampSigned(tel.randomValue);
        case SidModSource::Macro1: return std::clamp([self _cachedParamValue:ArpSID::kParamMacro1 defaultCenter:0.0f]*2.0f-1.0f,-1.0f,1.0f);
        case SidModSource::Macro2: return std::clamp([self _cachedParamValue:ArpSID::kParamMacro2 defaultCenter:0.0f]*2.0f-1.0f,-1.0f,1.0f);
        case SidModSource::Macro3: return std::clamp([self _cachedParamValue:ArpSID::kParamMacro3 defaultCenter:0.0f]*2.0f-1.0f,-1.0f,1.0f);
        case SidModSource::Macro4: return std::clamp([self _cachedParamValue:ArpSID::kParamMacro4 defaultCenter:0.0f]*2.0f-1.0f,-1.0f,1.0f);
        case SidModSource::Macro5: return std::clamp([self _cachedParamValue:ArpSID::kParamMacro5 defaultCenter:0.0f]*2.0f-1.0f,-1.0f,1.0f);
        case SidModSource::Macro6: return std::clamp([self _cachedParamValue:ArpSID::kParamMacro6 defaultCenter:0.0f]*2.0f-1.0f,-1.0f,1.0f);
        case SidModSource::Macro7: return std::clamp([self _cachedParamValue:ArpSID::kParamMacro7 defaultCenter:0.0f]*2.0f-1.0f,-1.0f,1.0f);
        case SidModSource::Macro8: return std::clamp([self _cachedParamValue:ArpSID::kParamMacro8 defaultCenter:0.0f]*2.0f-1.0f,-1.0f,1.0f);
        case SidModSource::Env1: return std::clamp(tel.env1Level*2.0f-1.0f,-1.0f,1.0f);
        case SidModSource::None:
        default: return 0.0f;
    }
}

-(void)_applyModOverlayForParam:(int)pid liveValue:(float)liveValue activity:(float)activity label:(NSString*)label{
    ArpSIDKnobView*kv=[self _knobForParamID:pid];
    if(!kv) return;
    [kv setModulatedValue:liveValue activity:activity label:label];
}

-(void)_refreshMatrixPresentationForDrSidMode:(BOOL)drSidMode{
    static const int matrixPids[] = {
        ArpSID::kParamModVCFCutoffSource, ArpSID::kParamModVCFCutoffDepth,
        ArpSID::kParamModVCFResonanceSource, ArpSID::kParamModVCFResonanceDepth,
        ArpSID::kParamModVCO1FreqSource, ArpSID::kParamModVCO1FreqDepth,
        ArpSID::kParamModVCO1PWSource, ArpSID::kParamModVCO1PWDepth,
        ArpSID::kParamModVCO2FreqSource, ArpSID::kParamModVCO2FreqDepth,
        ArpSID::kParamModVCO2PWSource, ArpSID::kParamModVCO2PWDepth,
        ArpSID::kParamModVCO3FreqSource, ArpSID::kParamModVCO3FreqDepth,
        ArpSID::kParamModVCO3PWSource, ArpSID::kParamModVCO3PWDepth,
        ArpSID::kParamModMasterVolumeSource, ArpSID::kParamModMasterVolumeDepth
    };
    if(_matrixHUDLabel) _matrixHUDLabel.stringValue=ArpSIDMatrixHUDSummary(drSidMode);
    if(_matrixLabelsDrSidMode==drSidMode) return;
    _matrixLabelsDrSidMode=drSidMode;
    for(int pid : matrixPids){
        ArpSIDKnobView*kv=[self _knobForParamID:pid];
        if(!kv) continue;
        NSString*display=ArpSIDMatrixControlDisplayName(drSidMode, pid);
        if(display.length>0) kv.pname=display;
        else {
            const ArpSID::ParamInfo&info=ArpSID::kParamInfos[(size_t)pid];
            kv.pname=[NSString stringWithUTF8String:info.name];
        }
        [kv setNeedsDisplay:YES];
    }
}

-(void)_refreshKnobRealtimeOverlaysWithTelemetry:(const ArpSIDTelemetry&)tel{
    using namespace ArpSID;
    if(![self _requireBridgeForAction:[NSString stringWithUTF8String:__func__]]) return;
    for(ArpSIDKnobView*kv in _knobs){
        [kv tickGlow];
        [kv setModulatedValue:kv.value activity:0.f label:nil];
    }

    const auto applyMatrix = ^(int targetPID, int sourcePID, int depthPID, float scale) {
        const float base=[self _cachedParamValue:targetPID defaultCenter:ArpSID::defaultNormalizedParamValue(targetPID)];
        const SidModSource src=decodeSidModSourceFromNormalizedUi([self _cachedParamValue:sourcePID defaultCenter:ArpSID::defaultNormalizedParamValue(sourcePID)]);
        const float depth=[self _cachedParamValue:depthPID defaultCenter:ArpSID::defaultNormalizedParamValue(depthPID)];
        if(src==SidModSource::None || depth<0.001f){
            [self _applyModOverlayForParam:targetPID liveValue:base activity:0.f label:nil];
            return;
        }
        const float srcVal=[self _modSourceBipolarValue:src telemetry:tel];
        const float delta=srcVal*depth*scale;
        [self _applyModOverlayForParam:targetPID
                             liveValue:ArpSIDUIClamp01(base+delta,base)
                              activity:ArpSIDUIClamp01(fabsf(delta)*2.6f)
                                 label:ArpSIDModSourceShortString(src)];
    };

    const BOOL drSidOn=[self _effectiveModeIndexFromTelemetry:&tel] == 2;
    if(drSidOn){
        [self _refreshMatrixPresentationForDrSidMode:YES];
        for(const auto& route : ArpSID::kDrSidParamMatrixRouteDefs)
            applyMatrix(route.targetPid, route.sourcePid, route.depthPid, route.depthScale);
        return;
    }
    [self _refreshMatrixPresentationForDrSidMode:NO];

    const float cutoffBase=[self _cachedParamValue:ArpSID::kParamFilterCutoff defaultCenter:0.5f];
    const float envAmt=[self _cachedParamValue:ArpSID::kParamFilterEnvAmount defaultCenter:0.0f];
    const float lfoAmt=[self _cachedParamValue:ArpSID::kParamFilterLFOAmount defaultCenter:0.0f];
    const SidModSource cutoffSrc=decodeSidModSourceFromNormalizedUi([self _cachedParamValue:ArpSID::kParamModVCFCutoffSource defaultCenter:0.0f]);
    const float cutoffDepth=[self _cachedParamValue:ArpSID::kParamModVCFCutoffDepth defaultCenter:0.0f];
    const float envDelta=(tel.env1Level-0.5f)*envAmt*0.40f;
    const float lfoDelta=ArpSIDUIClampSigned(tel.lfoValue[0])*lfoAmt*0.28f;
    const float matrixDelta=((cutoffSrc!=SidModSource::None)?[self _modSourceBipolarValue:cutoffSrc telemetry:tel]*cutoffDepth*0.35f:0.0f);
    NSString*cutLabel=(envAmt>0.001f||lfoAmt>0.001f||cutoffDepth>0.001f)?[NSString stringWithFormat:@"ENV/LFO %@", ArpSIDModSourceShortString(cutoffSrc)]:nil;
    [self _applyModOverlayForParam:ArpSID::kParamFilterCutoff
                         liveValue:ArpSIDUIClamp01(cutoffBase+envDelta+lfoDelta+matrixDelta,cutoffBase)
                          activity:ArpSIDUIClamp01((fabsf(envDelta)+fabsf(lfoDelta)+fabsf(matrixDelta))*2.2f)
                             label:cutLabel];

    for(const auto& route : ArpSID::kSynthParamMatrixRouteDefs)
        applyMatrix(route.targetPid, route.sourcePid, route.depthPid, route.depthScale);
}

// ─── Connect AU ───────────────────────────────────────────────────────────────
// connectAudioUnit: / connectAU: — wire AU model to existing controls.
// The UI must already be built before this is called (viewDidLoad has run).
// This method must NOT build UI, access self.view, or call _buildUI.
-(void)_connectBridgeInternal:(id<ArpSIDUIBridgeLike>)bridge{
    if (bridge) _controllerTearingDown_v277_.store(false, std::memory_order_release);
    [self _stopTimer];
    [self _removeBridgeObserver];
    _au=nil;
    [self _invalidateBridgeCaches];
    // Clear rewired flag so _rewireEmbeddedVSTInteractiveControls runs again on re-connect.
    // Swapping AU instances or reloading presets leaves controls bound to stale targets otherwise.
    _embeddedVSTControlsRewired = NO;
    _au=bridge;
    if(!_au){
        [self _syncComponentFlavorFromBridge:nil];
        [self _surfaceDisconnectedStateForAction:@"bridge connect"];
        if(self.isViewLoaded) [self.view setNeedsDisplay:YES];
        return;
    }
    _observedParameterTree=_au.parameterTree;
    // Under AUv2 the CocoaView factory never calls updatePresentationContext:,
    // so the HUD would fall back to "AUv3 Visual Host" indefinitely.
    // Set a correct context string now — it can be overridden later if the host
    // or standalone app calls updatePresentationContext: explicitly.
#if defined(ARPSID_AUV2_COMPONENT)
    if (!_presentationContextLine.length || ArpSIDAUv2PresentationContextIsDefaultFallback(_presentationContextLine)) {
        _presentationContextLine = [ArpSIDAUv2FlavorPresentationContextLine(_componentFlavor) copy];
        [self _applyPresentationHUD];
    }
#endif
    // Sync knob values from UI bridge state (dispatch so knobs definitely exist)
    id<ArpSIDUIBridgeLike> a=bridge;
    ArpSIDViewController*__weak ws=self;
    dispatch_async(dispatch_get_main_queue(),^{
        ArpSIDViewController*s=ws;if(!s || !s->_au || s->_au!=a)return;
        if(s->_controllerTearingDown_v277_.load(std::memory_order_acquire)) return;
        [s _primeParameterCacheFromBridge:a];
        [s _syncComponentFlavorFromBridge:a];
#if defined(ARPSID_AUV2_COMPONENT)
        if(s->_deferAuv2OOPEditorBuild_v831 && !s->_built){
            id adapter2 = [a debugAdapter];
            if (adapter2 && [adapter2 respondsToSelector:@selector(setSidCorePanelModel:)]) {
                [(id<ArpSIDDebugAdapterLike>)adapter2
                    setSidCorePanelModel:&s->_sidCoreModel_v547_];
            }
            s->_needsDeferredPresetUISync.store(true, std::memory_order_release);
            [s _scheduleDeferredAuv2EditorBuild_v831_];
            return;
        }
#endif
        for(ArpSIDKnobView*kv in s->_knobs)[kv set:[s _cachedParamValue:kv.paramID defaultCenter:kv.defaultValue]];
        [s _rewireEmbeddedVSTInteractiveControls];
        [s _resyncEmbeddedVSTState];
        // Sync strip views
        if(s->_pbView)  [s->_pbView   setValue:[s _cachedParamValue:(int)ArpSID::kParamHostCtrlPitchBendBase defaultCenter:0.5f]];
        if(s->_mwView)  [s->_mwView   setValue:[s _cachedParamValue:(int)ArpSID::kParamHostCtrlModWheelBase defaultCenter:0.0f]];
        if(s->_breathView)[s->_breathView setValue:[s _cachedParamValue:(int)ArpSID::kParamHostCtrlBreathBase defaultCenter:0.0f]];
        if(s->_atView)  [s->_atView   setValue:[s _cachedParamValue:(int)ArpSID::kParamHostCtrlChannelPressureBase defaultCenter:0.0f]];
        [s _applyCurrentBridgeStateToKnobs];
        s->_needsDeferredPresetUISync.store(true, std::memory_order_release);
        // v550: Wire the SIDCORE panel model so the kernel publishes register
        // writes into the view's data model starting from the next render block.
        id adapter2 = [a debugAdapter];
        if (adapter2 && [adapter2 respondsToSelector:@selector(setSidCorePanelModel:)]) {
            [(id<ArpSIDDebugAdapterLike>)adapter2
                setSidCorePanelModel:&s->_sidCoreModel_v547_];
        }
        // v551: Pull persisted settings from the adapter and apply to the
        // SETTINGS tab controls so a restored project is immediately visible.
        if (adapter2 && [adapter2 respondsToSelector:@selector(getSettingsModel:)]) {
            ArpSID::GUI::SettingsPanelModel restored{};
            [(id<ArpSIDDebugAdapterLike>)adapter2 getSettingsModel:&restored];
            s->_settingsModel_v544_ = restored;
            [s _applySettingsModelToSettingsPanel_v551_];
        }
        // v560: Pull persisted KIT state from the adapter and refresh KIT tab.
        if (adapter2 && [adapter2 respondsToSelector:@selector(getKitStateBlob:)]) {
            [s _pullKitStateFromAdapter_v560_];
        }
        // v561: Pull persisted MIX model from the adapter and rebuild MIX tab.
        if (adapter2 && [adapter2 respondsToSelector:@selector(getMixModel:)]) {
            [s _pullMixStateFromAdapter_v561_];
        }
        // v565/v596: Pull persisted DIGI model + sample-bank as one atomic
        // snapshot and refresh DIGI tab. Do not probe the legacy split getter
        // here: that would silently skip atomic-capable adapters only checking
        // the old selector contract.
        if (adapter2 && [adapter2 respondsToSelector:@selector(getDigiModel:sampleBank:)]) {
            [s _pullDigiStateFromAdapter_v565_];
        }
    });
    // Register parameter observer for automation read-back
    _tok=[_observedParameterTree tokenByAddingParameterObserver:^(AUParameterAddress addr,AUValue val){
        const int pid = (int)addr;
        ArpSIDViewController* s = ws;
        if (s && s->_controllerTearingDown_v277_.load(std::memory_order_acquire)) return;
        if (s) {
            // audit P0-12: NEVER call back into the AU bridge (e.g. getParameterValue)
            // from inside this observer block — AUParameter observers can fire on the
            // render/automation thread, and re-entering the AU there risks
            // re-entrancy/priority inversion/blocking. Just cache the observed value.
            // Program/BankSlot observer values can be stale adapter/tree echoes, but
            // they are presentation params (below) so the deferred MAIN-THREAD sync
            // re-reads them authoritatively through the bridge
            // (_primeParameterCacheFromBridge) — that is the only place a bridge read
            // is safe.
            [s _storeCachedParamValue:pid value:val];
        }
        const bool presentationParam =
            pid == ArpSID::kParamProgram ||
            pid == ArpSID::kParamBankSlot ||
            pid == ArpSID::kParamSynthModeEnable ||
            pid == ArpSID::kParamDrSidEnable ||
            pid == ArpSID::kParamVoiceMode ||
            pid == ArpSID::kParamArpEnable ||
            pid == ArpSID::kParamArpMode ||
            pid == ArpSID::kParamArpRate ||
            pid == ArpSID::kParamArpPatternLength ||
            pid == ArpSID::kParamArpSwing ||
            pid == ArpSID::kParamSeqEnable ||
            pid == ArpSID::kParamSeqTempo ||
            pid == ArpSID::kParamSeqSwing ||
            pid == ArpSID::kParamSeqMode ||
            pid == ArpSID::kParamSeqLength ||
            pid == ArpSID::kParamAttack ||
            pid == ArpSID::kParamDecay ||
            pid == ArpSID::kParamSustain ||
            pid == ArpSID::kParamRelease ||
            pid == ArpSID::kParamFilterCutoff ||
            pid == ArpSID::kParamFilterResonance ||
            pid == ArpSID::kParamFilterMode;
        if (presentationParam) {
            if (s) s->_needsDeferredPresetUISync.store(true, std::memory_order_release);
            return;
        }
        dispatch_async(dispatch_get_main_queue(),^{
            ArpSIDViewController*s=ws;if(!s || !s->_au)return;
            if(s->_controllerTearingDown_v277_.load(std::memory_order_acquire)) return;
            if(s->_isApplyingPreset.load(std::memory_order_acquire)) {
                s->_needsDeferredPresetUISync.store(true, std::memory_order_release);
                return;
            }
            for(ArpSIDKnobView*kv in s->_knobs)
                if((AUParameterAddress)kv.paramID==addr){[kv setAutomated:val];break;}
            if (pid >= (int)ArpSID::kParamHostCtrlModWheelBase &&
                pid <  (int)ArpSID::kParamHostCtrlModWheelBase + 16) {
                if(s->_mwView) [s->_mwView setValue:ArpSIDUIClamp01(val)];
            } else if (pid >= (int)ArpSID::kParamHostCtrlBreathBase &&
                       pid <  (int)ArpSID::kParamHostCtrlBreathBase + 16) {
                if(s->_breathView) [s->_breathView setValue:ArpSIDUIClamp01(val)];
            } else if (pid >= (int)ArpSID::kParamHostCtrlChannelPressureBase &&
                       pid <  (int)ArpSID::kParamHostCtrlChannelPressureBase + 16) {
                if(s->_atView) [s->_atView setValue:ArpSIDUIClamp01(val)];
            } else if (pid >= (int)ArpSID::kParamHostCtrlPitchBendBase &&
                       pid <  (int)ArpSID::kParamHostCtrlPitchBendBase + 16) {
                if(s->_pbView) [s->_pbView setValue:ArpSIDUIClamp01(val, 0.5f)];
            }
        });
    }];
}

// ─── View Config ──────────────────────────────────────────────────────────────
-(NSArray<AUAudioUnitViewConfiguration*>*)supportedViewConfigurations:(NSArray<AUAudioUnitViewConfiguration*>*)availableConfigurations {
    NSMutableArray<AUAudioUnitViewConfiguration*>* ok = [NSMutableArray array];
    for (AUAudioUnitViewConfiguration* cfg in availableConfigurations)
        if (cfg.width >= 640 && cfg.height >= 400) [ok addObject:cfg];
    return ok.count ? ok : availableConfigurations;
}
-(BOOL)selectViewConfiguration:(AUAudioUnitViewConfiguration*)configuration {
    if (!configuration) return YES;
    CGFloat w = MAX(kW, (CGFloat)configuration.width);
    CGFloat h = MAX(kH, (CGFloat)configuration.height);
    ArpSIDSetPreferredContentSizeOnMainThread(self, NSMakeSize(w, h));
    if (self.view) { self.view.frame = NSMakeRect(0,0,w,h); [self.view setNeedsDisplay:YES]; }
    return YES;
}

// ─── Presentation HUD ─────────────────────────────────────────────────────────
-(void)updatePresentationContext:(NSString*)contextLine{
    _presentationContextLine = contextLine.length ? [contextLine copy] : nil;
    [self _applyPresentationHUD];
}

-(void)selectPresentationTabIndex:(NSInteger)index{
    // v586: upper bound raised from ArpSIDTabHiFi (12) to ArpSIDTabDigiV563 (18)
    // so that View menu and external callers can reach all visible tabs.
    NSInteger clamped = MAX(0, MIN((NSInteger)ArpSIDTabDigiV563, index));
    const ArpSIDTab requested = (ArpSIDTab)clamped;
    const ArpSIDTab visible = ArpSIDCanonicalVisibleTabForFlavor(_componentFlavor, requested);
    if(_tabBar){
        _tabBar.selectedSegment = ArpSIDVisibleTabSegmentForFlavor(_componentFlavor, visible);
    }
    [self _showTab:visible];
}

-(void)_applyPresentationHUD{
    if(!_presentationHUDLabel) return;
#if defined(ARPSID_AUV2_COMPONENT)
    NSString* line = _presentationContextLine.length ? _presentationContextLine : ArpSIDAUv2FlavorDefaultHUDLine(_componentFlavor);
    NSString* flavorLabel = ArpSIDComponentFlavorUILabel(_componentFlavor);
    if([line rangeOfString:flavorLabel].location == NSNotFound){
        line = [NSString stringWithFormat:@"%@  •  %@", line, flavorLabel];
    }
#elif defined(ARPSID_VST_COCOA_BRIDGE)
    static NSString* const kDefaultHUD = @"VST3 Host";
    NSString* line = _presentationContextLine.length ? _presentationContextLine : kDefaultHUD;
#else
    static NSString* const kDefaultHUD = @"AUv3 Visual Host";
    NSString* line = _presentationContextLine.length ? _presentationContextLine : kDefaultHUD;
#endif
    ArpSIDSetLabelStringIfNeeded(_presentationHUDLabel, line);
    ArpSIDSetLabelColorIfNeeded(_presentationHUDLabel, [colTitle() colorWithAlphaComponent:.90f]);
    [_presentationHUDLabel setNeedsDisplay:YES];
}

-(void)_applyVersionLabel{
    if(!_ver) return;
#if defined(ARPSID_AUV2_COMPONENT)
    NSString* label=[NSString stringWithFormat:@"Uber Sound Solutions ● ArpSID v%s ● AUv2 ● %@",
                     ARPSID_PLUGIN_VERSION,
                     ArpSIDComponentFlavorUILabel(_componentFlavor)];
#elif defined(ARPSID_VST_COCOA_BRIDGE)
    NSString* label=[NSString stringWithFormat:@"Uber Sound Solutions ● ArpSID v%s ● VST3",
                     ARPSID_PLUGIN_VERSION];
#else
    NSString* label=[NSString stringWithFormat:@"Uber Sound Solutions ● ArpSID v%s ● AUv3",
                     ARPSID_PLUGIN_VERSION];
#endif
    ArpSIDSetLabelStringIfNeeded(_ver, label);
}

-(void)_syncComponentFlavorFromBridge:(id<ArpSIDUIBridgeLike>)bridge{
    ArpSID::ComponentFlavor flavor=ArpSID::ComponentFlavor::Hybrid;
    if(bridge && [bridge respondsToSelector:@selector(componentFlavor)]){
        const NSInteger raw=[bridge componentFlavor];
        flavor=ArpSID::componentFlavorFromRaw((int)raw);
    }
    _componentFlavor=flavor;
    if(_drumBrandView){
        _drumBrandView.brandKind =
            (flavor == ArpSID::ComponentFlavor::Sid808) ? 1 : 0;
        _drumBrandView.toolTip=ArpSIDDrumSurfaceSubtitleForFlavor(flavor);
    }
    // The auxiliary DRSID tab is always the register-wavetable DrSID engine,
    // including inside the SID-808 product.
    if(_drsidBrandView) _drsidBrandView.brandKind = 0;
#if defined(ARPSID_AUV2_COMPONENT)
    if (ArpSIDAUv2PresentationContextIsDefaultFallback(_presentationContextLine)) {
        _presentationContextLine = [ArpSIDAUv2FlavorPresentationContextLine(flavor) copy];
    }
#endif
    if(!_modePop) return;
    if(_modePop.numberOfItems >= 3){
        [[_modePop itemAtIndex:0] setEnabled:!ArpSID::componentFlavorIsDedicatedDrum(flavor)];
        [[_modePop itemAtIndex:1] setEnabled:!ArpSID::componentFlavorIsDedicatedDrum(flavor)];
        [[_modePop itemAtIndex:2] setEnabled:ArpSID::componentFlavorAllowsDrSid(flavor)];
    }
    if(ArpSID::componentFlavorIsC64SidPlayer(flavor)){
        _modePop.enabled=NO;
        _modePop.toolTip=@"Dedicated C64 SID Player flavor. Render mode is locked to the PSID/RSID player runtime; synth and DrSID modes are disabled.";
        if(_modePop.indexOfSelectedItem != 0) [_modePop selectItemAtIndex:0];
    } else if(ArpSID::componentFlavorIsDedicatedDrum(flavor)){
        _modePop.enabled=NO;
        _modePop.toolTip=(flavor == ArpSID::ComponentFlavor::Sid808)
            ? @"Dedicated SID-808 flavor. Render mode is locked to DR SID, the Analog X0X-8 model is forced, and preset browsing is filtered to drum-authored kits."
            : @"Dedicated DrSID drum-machine flavor. Render mode is locked to DR SID and factory presets are filtered to authored drum kits.";
        if(_modePop.indexOfSelectedItem != 2) [_modePop selectItemAtIndex:2];
        if(_au) [self _applyModeSelectionIndex:2];
    } else {
        _modePop.enabled=(flavor != ArpSID::ComponentFlavor::Instrument);
        _modePop.toolTip=(flavor == ArpSID::ComponentFlavor::Instrument)
            ? @"Pure instrument flavor. Render mode is locked to SYNTH / SID REG; CLASSIC is BitPerfect SID-player mode, not the playable synth."
            : @"Select CLASSIC SID Player / BitPerfect, SYNTH / SID REG, or DR SID Drums render mode.";
        if(flavor == ArpSID::ComponentFlavor::Instrument){
            // v927: Instrument flavor must not infer mode from a stale GUI cache.
            // It is a playable Synth/SID-register instrument, so force SID REG.
            if(_modePop.indexOfSelectedItem != 1) [_modePop selectItemAtIndex:1];
            if(_au) [self _applyModeSelectionIndex:1];
        }
    }
    [self _applyVersionLabel];
    [self _applyPresentationHUD];
    [self _refreshDrumQuickKitChrome];
    [self _syncDedicatedDrumKitSelectionWithFlavorDefaults:YES];
    [self _refreshBankSlotLabels];
    const ArpSIDTab visibleTab = ArpSIDCanonicalVisibleTabForFlavor(flavor, _tab);
    if(visibleTab != _tab) [self _showTab:visibleTab];
    else [self _refreshModeAdaptiveChrome];
}

-(void)_applyArpSyncModeHost:(BOOL)host{
    if(![self _requireBridgeForAction:[NSString stringWithUTF8String:__func__]]) return;
    const float current=[self _cachedParamValue:ArpSID::kParamArpRate defaultCenter:ArpSID::defaultNormalizedParamValue(ArpSID::kParamArpRate)];
    if(current > 0.005f) _lastInternalArpRateNorm=current;
    float target=host ? 0.0f : _lastInternalArpRateNorm;
    if(!host && target <= 0.005f) target=std::max(0.05f, ArpSID::defaultNormalizedParamValue(ArpSID::kParamArpRate));
    [self _applyRealtimeNormalizedParam:(int)ArpSID::kParamArpRate value:target defaultCenter:ArpSID::defaultNormalizedParamValue(ArpSID::kParamArpRate)];
    if(_arpSyncSeg) _arpSyncSeg.selectedSegment=ArpSIDSyncSegmentIndex(host);
    _needsDeferredPresetUISync.store(true, std::memory_order_release);
}

-(void)_applySeqSyncModeHost:(BOOL)host{
    if(![self _requireBridgeForAction:[NSString stringWithUTF8String:__func__]]) return;
    const float current=[self _cachedParamValue:ArpSID::kParamSeqTempo defaultCenter:ArpSID::defaultNormalizedParamValue(ArpSID::kParamSeqTempo)];
    if(current > 0.005f) _lastInternalSeqTempoNorm=current;
    float target=host ? 0.0f : _lastInternalSeqTempoNorm;
    if(!host && target <= 0.005f) target=std::max(0.05f, ArpSID::defaultNormalizedParamValue(ArpSID::kParamSeqTempo));
    [self _applyRealtimeNormalizedParam:(int)ArpSID::kParamSeqTempo value:target defaultCenter:ArpSID::defaultNormalizedParamValue(ArpSID::kParamSeqTempo)];
    if(_seqSyncSeg) _seqSyncSeg.selectedSegment=ArpSIDSyncSegmentIndex(host);
    _needsDeferredPresetUISync.store(true, std::memory_order_release);
}

-(void)_arpSyncChg:(id)sender{
    NSSegmentedControl* seg=(NSSegmentedControl*)sender;
    [self _applyArpSyncModeHost:(seg.selectedSegment == 0)];
}

-(void)_seqSyncChg:(id)sender{
    NSSegmentedControl* seg=(NSSegmentedControl*)sender;
    [self _applySeqSyncModeHost:(seg.selectedSegment == 0)];
}

-(NSInteger)_effectiveModeIndexFromTelemetry:(const ArpSIDTelemetry*)tel{
    if(ArpSID::componentFlavorIsDedicatedDrum(_componentFlavor)) return 2;
    if(_componentFlavor == ArpSID::ComponentFlavor::Instrument) {
        // v931: Pure Instrument's visible/effective mode is locked to the
        // playable SYNTH / SID REG surface even while telemetry or AU caches are
        // cold/stale. Returning CLASSIC here can steer deferred UI/tab sync back
        // toward BitPerfect immediately after _applyModeSelectionIndex(1).
        return 1;
    }
    if(tel){
        if(tel->drSidMode) return 2;
        if(tel->synthMode) return 1;
        return 0;
    }
    if(!_au) return 0;
    // Mode-oscillation fix: read the AUTHORITATIVE bridge parameter values, not the
    // GUI's _cachedParamValue mirror. The render-thread telemetry (tel->synthMode,
    // used by the other popup writer) is derived from the runtime resolver
    // sidResolveRenderModeFromLiveParams() over the live AU params. The GUI cache
    // can lag the AU after a patch load, so the two popup writers (the telemetry
    // refresh and _syncPatchAndModePresentation) would compute DIFFERENT modes and
    // overwrite each other every timer tick — the visible CLASSIC<->SID REG flicker
    // with no MIDI input. Reading the bridge here makes this nullptr/param path
    // agree with the telemetry path, so both writers converge on one mode.
    // (getParameterValue mirrors the same sticky AU authority used for kParamBankSlot.)
    const float synth=[_au getParameterValue:ArpSID::kParamSynthModeEnable];
    const float dr=[_au getParameterValue:ArpSID::kParamDrSidEnable];
    return (_componentFlavor != ArpSID::ComponentFlavor::Instrument && dr>0.5f)?2:((synth>0.5f)?1:0);
}

-(void)_markCurrentStateAsLoadedBankSlot:(NSInteger)slot{
    _currentStateBackedByLoadedBank = _hasLoadedBankCache;
    _currentLoadedBankSlot = _currentStateBackedByLoadedBank ? std::clamp(slot, (NSInteger)0, (NSInteger)ArpSID::kFileBankMaxSlots - 1) : -1;
    _loadedDrumUserKitURL = nil;
}

-(void)_markCurrentStateAsExternalPatch{
    _currentStateBackedByLoadedBank = NO;
    _currentLoadedBankSlot = -1;
}

-(void)_seedLoadedBankCacheWithFactoryDefaults{
    const auto& defs = ArpSID::getFactoryPatchDefinitions();
    for(NSInteger slot = 0; slot < (NSInteger)ArpSID::kFileBankMaxSlots; ++slot){
        _loadedBankRoots[(size_t)slot] = ArpSID::makeFactoryPatchStateRootForSlot((int)slot);
        if((size_t)slot < defs.size()) _loadedBankMetas[(size_t)slot] = ArpSID::ArpSIDFileBank::metaFromDefinition(defs[(size_t)slot]);
        else _loadedBankMetas[(size_t)slot] = ArpSID::ArpSIDFilePatchMeta{};
    }
}

-(NSString*)_factoryDisplayNameForSlot:(NSInteger)slot{
    const NSInteger clamped = std::clamp(slot, (NSInteger)0, (NSInteger)ArpSID::kCanonicalFactoryPatchSlotMax);
    const auto& defs = ArpSID::getFactoryPatchDefinitions();
    if((size_t)clamped < defs.size()){
        NSString* name = [NSString stringWithUTF8String:defs[(size_t)clamped].displayName.c_str()];
        if(name.length > 0) return name;
    }
    return [NSString stringWithFormat:@"Factory Patch %03ld", (long)(clamped + 1)];
}

-(NSString*)_loadedBankDisplayNameForSlot:(NSInteger)slot{
    if(!_hasLoadedBankCache) return [self _factoryDisplayNameForSlot:slot];
    const NSInteger clamped = std::clamp(slot, (NSInteger)0, (NSInteger)ArpSID::kFileBankMaxSlots - 1);
    const auto& meta = _loadedBankMetas[(size_t)clamped];
    if(meta.name[0]){
        NSString* name = [NSString stringWithUTF8String:meta.name];
        if(name.length > 0) return name;
    }
    return [self _factoryDisplayNameForSlot:clamped];
}

-(NSString*)_bankSlotTooltipForSlot:(NSInteger)slot{
    const NSInteger clamped = std::clamp(slot, (NSInteger)0, (NSInteger)ArpSID::kCanonicalFactoryPatchSlotMax);
    NSMutableArray<NSString*>* lines=[NSMutableArray array];
    [lines addObject:[NSString stringWithFormat:@"S%03ld  •  %@",
                      (long)(clamped + 1),
                      _hasLoadedBankCache ? [self _loadedBankDisplayNameForSlot:clamped] : [self _factoryDisplayNameForSlot:clamped]]];
    [lines addObject:[NSString stringWithFormat:@"Group: %@", ArpSIDFactoryBankGroupTooltip(ArpSIDFactoryBankGroupForSlot(clamped))]];
    if(!ArpSIDFactorySlotAllowedForFlavor(_componentFlavor, clamped)){
        NSString* flavorLabel = ArpSIDComponentFlavorUILabel(_componentFlavor);
        [lines addObject:[NSString stringWithFormat:@"%@ flavor does not expose this slot. Use an allowed slot family in this dedicated module.", flavorLabel]];
        return [lines componentsJoinedByString:@"\n"];
    }
    if(_hasLoadedBankCache){
        const auto& meta = _loadedBankMetas[(size_t)clamped];
        NSMutableArray<NSString*>* metaParts=[NSMutableArray array];
        if(meta.category[0]) [metaParts addObject:[NSString stringWithFormat:@"Category %@", [NSString stringWithUTF8String:meta.category]]];
        if(meta.author[0]) [metaParts addObject:[NSString stringWithFormat:@"Author %@", [NSString stringWithUTF8String:meta.author]]];
        if(meta.tags[0]) [metaParts addObject:[NSString stringWithFormat:@"Tags %@", [NSString stringWithUTF8String:meta.tags]]];
        if(metaParts.count > 0) [lines addObject:[metaParts componentsJoinedByString:@"  •  "]];
        [lines addObject:[NSString stringWithFormat:@"Role %d  •  Chip %s  •  Clock %@  •  Forensic %@",
                          (int)meta.role,
                          meta.chip_model == 0 ? "6581" : (meta.chip_model == 1 ? "8580" : "portable"),
                          meta.clock_system == 1 ? @"NTSC" : @"PAL",
                          meta.forensic_en ? @"ON" : @"OFF"]];
        [lines addObject:@"Loaded-bank slot metadata. Click to audition or load this slot into the live engine."];
        return [lines componentsJoinedByString:@"\n"];
    }
    const ArpSID::PatchDefinition* def = ArpSID::getFactoryPatchDefinition((int)clamped);
    if(def){
        if(!def->description.empty()) [lines addObject:[NSString stringWithUTF8String:def->description.c_str()]];
        if(ArpSIDFactorySlotIsSid808PriorityUI(clamped)){
            [lines addObject:[NSString stringWithFormat:@"%@ priority drum slot. Curated first in the dedicated SID-808 module.",
                              ArpSIDSid808PriorityBadgeUI(clamped)]];
        }
        [lines addObject:[NSString stringWithFormat:@"Role %s  •  Family %s  •  Bias %s  •  Auth %s",
                          ArpSID::toString(def->usage.role),
                          ArpSID::toString(def->usage.family),
                          ArpSID::toString(def->usage.bias),
                          ArpSID::toString(def->usage.authenticity)]];
        [lines addObject:[NSString stringWithFormat:@"Chip %s  •  Clock %s  •  MIDI %d..%d (pref %d..%d)",
                          ArpSID::toString(def->staticState.chip),
                          ArpSID::toString(def->staticState.clock),
                          def->usage.validMidiMin, def->usage.validMidiMax,
                          def->usage.preferredMidiMin, def->usage.preferredMidiMax]];
        [lines addObject:[NSString stringWithFormat:@"Start %s  •  Pitch %s  •  Pulse %s  •  Filter %s",
                          ArpSID::toString(def->start.id),
                          ArpSID::toString(def->motion.pitchMotion),
                          ArpSID::toString(def->motion.pulseMotion),
                          ArpSID::toString(def->motion.filterMotion)]];
    } else {
        [lines addObject:@"Factory slot metadata unavailable. Click to load the slot into the live engine."];
    }
    return [lines componentsJoinedByString:@"\n"];
}

- (void)_syncFactoryBankSegmentForSlot:(NSInteger)slot{
    if(!_factoryBankSeg) return;
    const NSInteger group=ArpSIDFactoryBankGroupForSlot(slot);
    if(_factoryBankSeg.selectedSegment != group) _factoryBankSeg.selectedSegment=group;
}

-(void)_refreshBankSlotLabels{
    if(!_pBank) return;
    for(NSInteger slot = 0; slot <= (NSInteger)ArpSID::kCanonicalFactoryPatchSlotMax; ++slot){
        NSString* ident = [NSString stringWithFormat:@"slotName%ld", (long)slot];
        NSTextField* lbl = (NSTextField*)arpsidViewWithIdentifier(_pBank, ident);
        if(!lbl) continue;
        const BOOL allowed = ArpSIDFactorySlotAllowedForFlavor(_componentFlavor, slot);
        const BOOL loadedUserBankSlot = _hasLoadedBankCache && slot >= 0 && slot < (NSInteger)ArpSID::kFileBankMaxSlots;
        lbl.stringValue = loadedUserBankSlot ? [self _loadedBankDisplayNameForSlot:slot]
                                             : [self _factoryDisplayNameForSlot:slot];
        lbl.textColor = allowed
            ? [NSColor colorWithSRGBRed:.85 green:.85 blue:.85 alpha:1.0]
            : [NSColor colorWithSRGBRed:.50 green:.50 blue:.50 alpha:.78];
        NSButton* cell=nil;
        if([lbl.superview isKindOfClass:[NSButton class]]) cell=(NSButton*)lbl.superview;
        if(cell){
            cell.toolTip=[self _bankSlotTooltipForSlot:slot];
            cell.enabled = allowed;
            cell.alphaValue = allowed ? 1.0 : 0.44;
        }
    }
    [self _bankUpdateSlotHighlight:(int)[self _currentBankSlotFromBridgeOrCache] panel:_pBank];
    [self _refreshPresets];
}

-(void)_clearLoadedBankCache{
    _hasLoadedBankCache = NO;
    _loadedBankDisplayName = nil;
    [self _markCurrentStateAsExternalPatch];
    [self _refreshBankSlotLabels];
}

-(void)_cacheLoadedBankPatches:(const std::vector<ArpSID::SidStateRootV1>&)patches
                          metas:(const std::vector<ArpSID::ArpSIDFilePatchMeta>&)metas
                     sourceName:(NSString*)sourceName{
    [self _seedLoadedBankCacheWithFactoryDefaults];
    const size_t count = std::min({ patches.size(), metas.size(), (size_t)ArpSID::kFileBankMaxSlots });
    for(size_t i = 0; i < count; ++i){
        ArpSID::SidStateRootV1 root = patches[i];
        ArpSID::ArpSIDFilePatchMeta meta = metas[i];
        const BOOL metaEmpty = !(meta.name[0] || meta.author[0] || meta.category[0] || meta.tags[0] ||
                                 meta.chip_model || meta.clock_system || meta.forensic_en || meta.role);
        if(metaEmpty && !root.valid()) continue;
        ArpSID::sidCanonicalizeTopLevelRenderModeParams(root);
        if (ArpSIDPatchMetaLooksLikeDrumKit(meta, root)) {
            ArpSID::sidSetStateRootParamValue(root, (int)ArpSID::kParamDrSidEnable, 1.0f);
            ArpSID::sidSetStateRootParamValue(root, (int)ArpSID::kParamSynthModeEnable, 0.0f);
        }
        ArpSID::sidEnsureSemanticParameterEntries(root);
        _loadedBankRoots[i] = root;
        _loadedBankMetas[i] = meta;
    }
    _hasLoadedBankCache = YES;
    _loadedBankDisplayName = [sourceName copy];
    [self _refreshBankSlotLabels];
}

-(void)_collectDisplayedBankRoots:(std::vector<ArpSID::SidStateRootV1>&)roots
                            metas:(std::vector<ArpSID::ArpSIDFilePatchMeta>&)metas
                  includeLiveSlot:(BOOL)includeLiveSlot{
    roots.resize((size_t)ArpSID::kFileBankMaxSlots);
    metas.resize((size_t)ArpSID::kFileBankMaxSlots);
    if(_hasLoadedBankCache){
        for(size_t i = 0; i < (size_t)ArpSID::kFileBankMaxSlots; ++i){
            roots[i] = _loadedBankRoots[i];
            metas[i] = _loadedBankMetas[i];
        }
    } else {
        const auto& defs = ArpSID::getFactoryPatchDefinitions();
        for(NSInteger slot = 0; slot < (NSInteger)ArpSID::kFileBankMaxSlots; ++slot){
            roots[(size_t)slot] = ArpSID::makeFactoryPatchStateRootForSlot((int)slot);
            metas[(size_t)slot] = ((size_t)slot < defs.size())
                ? ArpSID::ArpSIDFileBank::metaFromDefinition(defs[(size_t)slot])
                : ArpSID::ArpSIDFilePatchMeta{};
        }
    }
    if(!includeLiveSlot || !_au) return;
    ArpSIDDSPKernelAdapter* adapter=nil;
    if([_au respondsToSelector:@selector(kernelAdapter)]) adapter=[_au performSelector:@selector(kernelAdapter)];
    ArpSID::ArpSIDDSPKernel* kernel = adapter ? [adapter kernelPtr] : nullptr;
    if(!kernel) return;
    ArpSID::SidStateRootV1 liveRoot{};
    kernel->buildSerializableStateRootFromShadow(liveRoot);
    ArpSIDFileBankBridge* bridge=[[ArpSIDFileBankBridge alloc] init];
    ArpSIDPatchMetaObj* liveMetaObj=[bridge metaFromKernel:adapter
                                                     name:[self _currentPresetDisplayName]
                                                   author:@"User"
                                                 category:@""];
    // Live-bank export must use sticky AU preset authority, never the local UI
    // cache. The cache can contain stale host mirror data after transport replay.
    const float stickyBankNorm = _au ? [_au getParameterValue:ArpSID::kParamBankSlot]
                                     : ArpSID::canonicalNormalizedBankSlotValue(0);
    const NSInteger factorySlot = (NSInteger)ArpSID::canonicalFactorySlotFromNormalizedBankSlot(stickyBankNorm);
    if (factorySlot < 0 || factorySlot >= (NSInteger)ArpSID::kFileBankMaxSlots) {
        // v1 .arpsidbank files are 128 user-bank slots. Extended factory
        // slots 128..179 must not alias into legacy slot 127.
        return;
    }
    ArpSID::sidCanonicalizeTopLevelRenderModeParams(liveRoot);
    const ArpSID::ArpSIDFilePatchMeta liveMeta = ArpSIDFileMetaFromPatchMetaObj(liveMetaObj);
    if (ArpSIDPatchMetaLooksLikeDrumKit(liveMeta, liveRoot)) {
        ArpSID::sidSetStateRootParamValue(liveRoot, (int)ArpSID::kParamDrSidEnable, 1.0f);
        ArpSID::sidSetStateRootParamValue(liveRoot, (int)ArpSID::kParamSynthModeEnable, 0.0f);
    }
    ArpSID::sidEnsureSemanticParameterEntries(liveRoot);
    roots[(size_t)factorySlot] = liveRoot;
    metas[(size_t)factorySlot] = liveMeta;
}

-(void)_applyLoadedBankSlot:(NSInteger)slot{
    if(!_au || !_hasLoadedBankCache) return;
    ArpSIDDSPKernelAdapter* adapter=nil;
    if([_au respondsToSelector:@selector(kernelAdapter)]) adapter=[_au performSelector:@selector(kernelAdapter)];
    ArpSID::ArpSIDDSPKernel* kernel = adapter ? [adapter kernelPtr] : nullptr;
    if(!kernel) return;
    NSInteger clamped = std::clamp(slot, (NSInteger)0, (NSInteger)ArpSID::kFileBankMaxSlots - 1);
    if(!ArpSIDFactorySlotAllowedForFlavor(_componentFlavor, clamped)){
        clamped = ArpSIDStartupFactorySlotForFlavorUI(_componentFlavor);
    }
    kernel->schedulePendingStateRestore(_loadedBankRoots[(size_t)clamped]);
    [self _markCurrentStateAsLoadedBankSlot:clamped];
    [self _refreshDrumUserKitMetaLabel];
    _needsDeferredPresetUISync.store(true, std::memory_order_release);
    [self _refreshBankSlotLabels];
}

-(NSString*)_displayNameForEffectiveBankSlot:(NSInteger)slot{
    const NSInteger clamped = std::clamp(slot, (NSInteger)0, (NSInteger)ArpSID::kCanonicalFactoryPatchSlotMax);
    if(_currentStateBackedByLoadedBank && _hasLoadedBankCache && _currentLoadedBankSlot == clamped) {
        return [self _loadedBankDisplayNameForSlot:clamped];
    }
    return [self _factoryDisplayNameForSlot:clamped];
}

-(NSString*)_currentPresetDisplayName{
    if(_currentStateBackedByLoadedBank && _hasLoadedBankCache && _currentLoadedBankSlot >= 0){
        return [self _loadedBankDisplayNameForSlot:_currentLoadedBankSlot];
    }
    if(_loadedDrumUserKitURL){
        NSString* userKitName = _loadedDrumUserKitURL.URLByDeletingPathExtension.lastPathComponent;
        return (userKitName.length > 0) ? userKitName : @"User Kit";
    }
    id<ArpSIDUIBridgeLike> au=_au;
    if(au){
        // Preset display must use public AU sticky readback, not an old
        // local cache entry that may have been populated by host/GM Program
        // metadata before the sticky authority was established.
        const float bankNorm = ArpSIDUIClamp01([au getParameterValue:ArpSID::kParamBankSlot]);
        const NSInteger slot = (NSInteger)ArpSID::canonicalFactorySlotFromNormalizedBankSlot(bankNorm);
        return [self _displayNameForEffectiveBankSlot:slot];
    }
    if(_presetPop && _presetPop.indexOfSelectedItem > 0) return _presetPop.selectedItem.title;
    return @"Live";
}

-(ArpSIDDSPKernelAdapter*)_currentKernelAdapter{
    if(![_au respondsToSelector:@selector(kernelAdapter)]) return nil;
    return [_au performSelector:@selector(kernelAdapter)];
}

-(void)_refreshModeAdaptiveChrome{
    const NSInteger modeIndex = [self _effectiveModeIndexFromTelemetry:nullptr];
    if(_tabBar){
        ArpSIDConfigureVisibleTabBar_v268(_tabBar, _componentFlavor, modeIndex);
    }
    if(_modePop){
        const BOOL showModePop = !ArpSID::componentFlavorIsDedicatedDrum(_componentFlavor);
        _modePop.hidden = !showModePop;
        _modePop.alphaValue = showModePop ? 1.0 : 0.0;
    }
    if(_playModeSeg){
        const BOOL showPlayMode = (modeIndex != 2) && !ArpSID::componentFlavorIsDedicatedDrum(_componentFlavor);
        _playModeSeg.hidden = !showPlayMode;
        _playModeSeg.enabled = showPlayMode;
        _playModeSeg.alphaValue = showPlayMode ? 1.0 : 0.52;
        _playModeSeg.toolTip = showPlayMode
            ? @"Poly / mono / legato / unison playback policy"
            : @"DrSID runs GM-style drum triggering and does not use synth voice-mode selection";
    }
    if(_presetPop){
        if(_componentFlavor == ArpSID::ComponentFlavor::Sid808){
            _presetPop.toolTip = @"SID-808 kit picker. Only drum-authored kits stay visible here, with the Analog X0X-8 model forced by the dedicated flavor.";
        } else if(_componentFlavor == ArpSID::ComponentFlavor::DrumMachine){
            _presetPop.toolTip = @"Drum-machine kit picker. Drum-authored kits stay visible here and the BANK tab exposes grouped kit browsing.";
        } else if(_componentFlavor == ArpSID::ComponentFlavor::Instrument){
            _presetPop.toolTip = @"Pure-instrument preset picker. Drum-authored kits are filtered out in this module.";
        } else {
            _presetPop.toolTip = @"Factory patch / kit picker. The BANK tab exposes grouped sub-banks, slot descriptions, import/export actions, and flavor-filtered kit visibility.";
        }
    }
    if(_drumKitSeg) _drumKitSeg.hidden = (modeIndex != 2);
    if(_tabPrev && _tabNext && _tabBar.segmentCount > 0){
        const NSInteger tabCount=_tabBar.segmentCount;
        NSInteger currentSeg=ArpSIDVisibleTabSegmentForFlavor(_componentFlavor, _tab);
        if(currentSeg < 0) currentSeg = 0;
        const NSInteger prev=(currentSeg + tabCount - 1) % tabCount;
        const NSInteger next=(currentSeg + 1) % tabCount;
        const ArpSIDTab prevTab=ArpSIDVisibleTabForFlavorAtIndex(_componentFlavor, prev);
        const ArpSIDTab nextTab=ArpSIDVisibleTabForFlavorAtIndex(_componentFlavor, next);
        _tabPrev.toolTip=[NSString stringWithFormat:@"Previous tab: %@", ArpSIDTabLabelForMode((NSInteger)prevTab, modeIndex, _componentFlavor)];
        _tabNext.toolTip=[NSString stringWithFormat:@"Next tab: %@", ArpSIDTabLabelForMode((NSInteger)nextTab, modeIndex, _componentFlavor)];
    }
    if(_bankHeaderLabel){
        if(_componentFlavor == ArpSID::ComponentFlavor::Instrument){
            _bankHeaderLabel.stringValue = @"PURE INSTRUMENT PATCH / BANK  ■  Load & Save  ■  .ARPSID / .ARPSIDBANK / .JSON  ■  MPK CC HUB";
        } else if(_componentFlavor == ArpSID::ComponentFlavor::Sid808){
            _bankHeaderLabel.stringValue = @"SID-808 KIT / BANK  ■  Analog X0X-8 Focus  ■  .ARPSID / .ARPSIDBANK / .JSON";
        } else if(modeIndex == 2 || _componentFlavor == ArpSID::ComponentFlavor::DrumMachine){
            _bankHeaderLabel.stringValue = @"DRUM MACHINE KIT / BANK  ■  Load & Save  ■  .ARPSID / .ARPSIDBANK / .JSON";
        } else {
            _bankHeaderLabel.stringValue = @"HYBRID PATCH / BANK  ■  Load & Save  ■  .ARPSID / .ARPSIDBANK / .JSON  ■  MPK CC HUB";
        }
    }
    [self _layoutMainChromeControls];
}

-(ArpSIDFileBankResult)_savePatchDocumentToURL:(NSURL*)url
                                       adapter:(ArpSIDDSPKernelAdapter*)adapter
                                          meta:(ArpSIDPatchMetaObj*)meta{
    if(!url || !adapter || !meta) return ArpSIDFileBankResultUnknown;
    if(!ArpSIDPathUsesJSON(url.path)){
        ArpSIDFileBankBridge* bridge=[[ArpSIDFileBankBridge alloc]init];
        return [bridge savePatchToFile:url.path adapter:adapter meta:meta];
    }
    ArpSID::ArpSIDDSPKernel* kernel=[adapter kernelPtr];
    if(!kernel) return ArpSIDFileBankResultUnknown;
    ArpSID::SidStateRootV1 root{};
    kernel->buildSerializableStateRootFromShadow(root);
    const ArpSID::ArpSIDFilePatchMeta fileMeta = ArpSIDFileMetaFromPatchMetaObj(meta);
    NSDictionary* doc = ArpSIDJSONPatchDocumentFromRoot(root, fileMeta);
    if(!doc) return ArpSIDFileBankResultBadBlob;
    NSString* errorText=nil;
    return ArpSIDWriteJSONDocumentToURL(doc, url, &errorText) ? ArpSIDFileBankResultOK : ArpSIDFileBankResultWriteFailed;
}

// v968: a user "DrSID kit" is a drum-role patch by construction. This save
// normalizes the serialized document into DrSID mode (DrSidEnable=1,
// SynthMode=0) regardless of the transient live render mode, exactly like the
// import/export bank paths do per patch. Without this, a kit saved while the
// engine happened to be in another render mode was stamped role=Drum (so it
// showed in the drum library) yet loaded back without entering DrSID mode.
// Unlike _savePatchDocumentToURL this always goes through the state-root path
// (for both .arpsid and .json) so the normalization applies to both formats.
-(ArpSIDFileBankResult)_saveDrumKitDocumentToURL:(NSURL*)url
                                          adapter:(ArpSIDDSPKernelAdapter*)adapter
                                             meta:(ArpSIDPatchMetaObj*)meta{
    if(!url || !adapter || !meta) return ArpSIDFileBankResultUnknown;
    ArpSID::ArpSIDDSPKernel* kernel=[adapter kernelPtr];
    if(!kernel) return ArpSIDFileBankResultUnknown;
    ArpSID::SidStateRootV1 root{};
    kernel->buildSerializableStateRootFromShadow(root);
    ArpSID::sidSetStateRootParamValue(root, (int)ArpSID::kParamDrSidEnable, 1.0f);
    ArpSID::sidSetStateRootParamValue(root, (int)ArpSID::kParamSynthModeEnable, 0.0f);
    ArpSID::sidEnsureSemanticParameterEntries(root);
    const ArpSID::ArpSIDFilePatchMeta fileMeta = ArpSIDFileMetaFromPatchMetaObj(meta);
    if(ArpSIDPathUsesJSON(url.path)){
        NSDictionary* doc = ArpSIDJSONPatchDocumentFromRoot(root, fileMeta);
        if(!doc) return ArpSIDFileBankResultBadBlob;
        NSString* errorText=nil;
        return ArpSIDWriteJSONDocumentToURL(doc, url, &errorText) ? ArpSIDFileBankResultOK : ArpSIDFileBankResultWriteFailed;
    }
    return (ArpSID::ArpSIDFileBank::savePatchToFile(std::string(url.path.UTF8String), root, fileMeta) == ArpSID::FileBankError::OK)
        ? ArpSIDFileBankResultOK : ArpSIDFileBankResultWriteFailed;
}

-(ArpSIDFileBankResult)_loadPatchDocumentFromURL:(NSURL*)url
                                         adapter:(ArpSIDDSPKernelAdapter*)adapter
                                         metaOut:(ArpSIDPatchMetaObj* _Nullable __autoreleasing * _Nullable)metaOut{
    if(!url || !adapter) return ArpSIDFileBankResultUnknown;
    if(!ArpSIDPathUsesJSON(url.path)){
        ArpSIDFileBankBridge* bridge=[[ArpSIDFileBankBridge alloc]init];
        return [bridge loadPatchFromFile:url.path adapter:adapter metaOut:metaOut];
    }
    ArpSID::ArpSIDDSPKernel* kernel=[adapter kernelPtr];
    if(!kernel) return ArpSIDFileBankResultUnknown;
    NSString* errorText=nil;
    NSDictionary* doc = ArpSIDReadJSONDocumentFromURL(url, &errorText);
    if(!doc) return ArpSIDFileBankResultReadFailed;
    ArpSID::SidStateRootV1 root{};
    ArpSID::ArpSIDFilePatchMeta meta{};
    if(!ArpSIDParseJSONPatchDocument(doc, root, meta, &errorText)) return ArpSIDFileBankResultBadFormat;
    kernel->schedulePendingStateRestore(root);
    if(metaOut) *metaOut = ArpSIDPatchMetaObjectFromFileMeta(meta);
    return ArpSIDFileBankResultOK;
}

-(ArpSID::FileBankError)_saveBankDocumentToURL:(NSURL*)url
                                        patches:(const std::vector<ArpSID::SidStateRootV1>&)patches
                                          metas:(const std::vector<ArpSID::ArpSIDFilePatchMeta>&)metas
                                    displayName:(NSString*)displayName{
    return ArpSIDSaveBankDocumentToURL_v781(url, patches, metas, displayName);
}

-(ArpSID::FileBankError)_loadBankDocumentFromURL:(NSURL*)url
                                         patches:(std::vector<ArpSID::SidStateRootV1>&)patches
                                           metas:(std::vector<ArpSID::ArpSIDFilePatchMeta>&)metas{
    return ArpSIDLoadBankDocumentFromURL_v781(url, patches, metas);
}

-(void)_syncPresetAndSlotSelectionWithProgram:(NSInteger)program bankSlot:(NSInteger)bankSlot presetName:(NSString* _Nullable)presetName{
    (void)program;
    const NSInteger clampedProgram = std::clamp(bankSlot, (NSInteger)0, (NSInteger)ArpSID::kCanonicalFactoryPatchSlotMax);
    NSString* leadText = ArpSIDPresetPickerLeadTextForFlavor(_componentFlavor, [self _effectiveModeIndexFromTelemetry:nullptr]);
    if(_presetPop){
        NSInteger pidx = [_presetPop indexOfItemWithTag:clampedProgram];
        if(pidx >= 0){
            if(_presetPop.indexOfSelectedItem != pidx) [_presetPop selectItemAtIndex:pidx];
        } else if(_presetPop.numberOfItems > 0){
            NSString* title = presetName.length ? [NSString stringWithFormat:@"%@  %@", leadText, presetName] : [NSString stringWithFormat:@"%@  P%03ld", leadText, (long)(clampedProgram + 1)];
            if(![title isEqualToString:_presetPop.itemArray.firstObject.title]) {
                [_presetPop.itemArray.firstObject setTitle:title];
            }
            if(_presetPop.indexOfSelectedItem != 0) [_presetPop selectItemAtIndex:0];
        }
    }
}

-(void)_refreshPatchAndModeFromBridgeState{
    id<ArpSIDUIBridgeLike> au=_au;
    if(!au) return;
    const float bankNorm = ArpSIDUIClamp01([au getParameterValue:ArpSID::kParamBankSlot]);
    const float voiceModeNorm = ArpSIDUIClamp01([au getParameterValue:ArpSID::kParamVoiceMode]);
    const NSInteger bankSlot = (NSInteger)ArpSID::canonicalFactorySlotFromNormalizedBankSlot(bankNorm);
    const NSInteger program = bankSlot;
    const NSInteger modeIndex = [self _effectiveModeIndexFromTelemetry:nullptr];
    const NSInteger voiceMode = MAX(0, MIN(3, (NSInteger)lround(voiceModeNorm * 3.0f)));
    [self _refreshModeAdaptiveChrome];
    [self _syncPresetAndSlotSelectionWithProgram:program bankSlot:bankSlot presetName:[self _currentPresetDisplayName]];
    if(_modePop && _modePop.indexOfSelectedItem != modeIndex) [_modePop selectItemAtIndex:modeIndex];
    if(_playModeSeg && _playModeSeg.selectedSegment != voiceMode) _playModeSeg.selectedSegment = voiceMode;
}

-(void)_applyCurrentBridgeStateToKnobs{
    if(![self _requireBridgeForAction:[NSString stringWithUTF8String:__func__]]) return;
    for(ArpSIDKnobView*kv in _knobs) {
        const float v = [self _cachedParamValue:kv.paramID defaultCenter:kv.defaultValue];
        [kv set:v];
    }
}

-(NSView*)_ensureContentPanelForTab_v825:(ArpSIDTab)tab{
    NSRect cr = _panelContentRect_v552_;
    if(cr.size.width < 8.f || cr.size.height < 8.f){
        const CGFloat sl=kBW,sb=kBW,sw=kW-kBW*2;
        const CGFloat footerBaseY=sb+kBottomSafeInset;
        const CGFloat contentBaseY=footerBaseY+kFtrH+kTabH;
        const CGFloat ch=kH-kBW-kHdrH-contentBaseY;
        cr = NSMakeRect(sl,contentBaseY,sw,ch);
        _panelContentRect_v552_ = cr;
    }

    NSView* panel = nil;
    BOOL created = NO;
    const ArpSIDTab visible = ArpSIDCanonicalVisibleTabForFlavor(_componentFlavor, tab);

#define ARPSID_ENSURE_PANEL_V825(slot, builder) \
    do { \
        if(!(slot)){ (slot) = [self builder:cr]; created = YES; } \
        panel = (slot); \
    } while(0)

    switch(visible){
        case ArpSIDTabLfoArp: ARPSID_ENSURE_PANEL_V825(_pLfo, _lfoPanel); break;
        case ArpSIDTabSidProjection:
        case ArpSIDTabSidCore: ARPSID_ENSURE_PANEL_V825(_pCore, _sidCorePanel); break;
        case ArpSIDTabSidReg: ARPSID_ENSURE_PANEL_V825(_pSid, _sidRegPanel); break;
        case ArpSIDTabSeq: ARPSID_ENSURE_PANEL_V825(_pSeq, _seqPanel); break;
        case ArpSIDTabDrsid: ARPSID_ENSURE_PANEL_V825(_pDrsid, _drsidPanel); break;
        case ArpSIDTabFilter: ARPSID_ENSURE_PANEL_V825(_pFilter, _filterPanel); break;
        case ArpSIDTabMacro: ARPSID_ENSURE_PANEL_V825(_pMacro, _macroPanel); break;
        case ArpSIDTabForensic: ARPSID_ENSURE_PANEL_V825(_pFor, _forensicPanel); break;
        case ArpSIDTabC64:
        case ArpSIDTabC64StateV544: ARPSID_ENSURE_PANEL_V825(_pC64, _c64Panel); break;
        case ArpSIDTabHiFi: ARPSID_ENSURE_PANEL_V825(_pHiFi, _hiFiPanel); break;
        case ArpSIDTabBank: ARPSID_ENSURE_PANEL_V825(_pBank, _bankPanel); break;
        case ArpSIDTabOptions: ARPSID_ENSURE_PANEL_V825(_pOpts, _optionsPanel); break;
        case ArpSIDTabSettingsV544: ARPSID_ENSURE_PANEL_V825(_pSettingsV544, _settingsPanel_v544_); break;
        case ArpSIDTabMixV547:
            if(_mixPanelNeedsDeferredRebuild_v824 && _pMixV547){
                [self _rebuildMixPanelFromModel_v824];
                _mixPanelNeedsDeferredRebuild_v824 = NO;
            }
            if(!_pMixV547){
                _pMixV547 = [self _mixPanel_v547_:cr];
                _mixPanelNeedsDeferredRebuild_v824 = NO;
                created = YES;
            }
            panel = _pMixV547;
            break;
        case ArpSIDTabKitV555: ARPSID_ENSURE_PANEL_V825(_pKitV555, _kitPanel_v555_); break;
        case ArpSIDTabDigiV563: ARPSID_ENSURE_PANEL_V825(_pDigiV563, _digiPanel_v563_); break;
        case ArpSIDTabMain:
        default: ARPSID_ENSURE_PANEL_V825(_pMain, _mainPanel); break;
    }

#undef ARPSID_ENSURE_PANEL_V825

    if(created && panel){
        panel.hidden = YES;
        ArpSIDFinalizeControlUX(panel);
        if(panel == _pBank) [self _refreshBankSlotLabels];
        if(panel == _pSettingsV544) [self _applySettingsModelToSettingsPanel_v551_];
        if(panel == _pDigiV563){
            [self _digiRefreshSlotControls_v563_];
            [self _digiRefreshStepGrid_v563_];
        }
        if(panel == _pSeq || panel == _pDrsid){
            [self _refreshDrumQuickKitChrome];
            [self _refreshDrumKitPresentation];
        }
    }
    return panel ? panel : _pMain;
}

-(NSView*)_activeChromeHostPanel{
#if defined(ARPSID_AUV2_COMPONENT)
    if(_deferAuv2OOPEditorBuild_v831 && !_built) return nil;
#endif
    NSView* panel = [self _ensureContentPanelForTab_v825:_tab];
    return panel ? panel : _pMain;
}

-(void)_forEachContentPanel_v824:(void (^)(NSView* panel))block{
    if(!block) return;
    NSView* panels[] = {_pMain,_pLfo,_pFor,_pSid,_pSeq,_pDrsid,_pFilter,_pMacro,
                        _pCore,_pC64,_pHiFi,_pBank,_pOpts,_pSettingsV544,
                        _pMixV547,_pKitV555,_pDigiV563};
    for(NSView* panel : panels)
        if(panel) block(panel);
}

-(void)_attachOnlyActiveContentPanel_v824{
    NSView* root = self.view;
    if(!root) return;
#if defined(ARPSID_AUV2_COMPONENT)
    if(_deferAuv2OOPEditorBuild_v831 && !_built) return;
#endif
    NSView* active = [self _activeChromeHostPanel];
    [self _forEachContentPanel_v824:^(NSView* panel) {
        const BOOL panelIsActive = (panel == active);
        panel.hidden = !panelIsActive;
        if(panelIsActive){
            if(panel.superview != root){
                [panel removeFromSuperview];
                [root addSubview:panel positioned:NSWindowBelow relativeTo:nil];
            }
        } else if(panel.superview == root) {
            [panel removeFromSuperview];
        }
    }];
}

-(BOOL)_editorChromeIsMounted_v831_{
    return self.view && _tabBar && _tabBar.superview == self.view;
}

-(void)_discardUnmountedBootstrapPanelState_v831_{
    if(_built || [self _editorChromeIsMounted_v831_]) return;
    [self _forEachContentPanel_v824:^(NSView* panel) {
        [panel removeFromSuperview];
    }];
    _pMain = _pLfo = _pFor = _pSid = _pSeq = _pDrsid = _pFilter = _pMacro = nil;
    _pCore = _pC64 = _pHiFi = _pBank = _pOpts = nil;
    _pSettingsV544 = _pC64StateV544 = _pMixV547 = _pKitV555 = _pDigiV563 = nil;
    _pKitStepEdView_v558_ = _pKitVoiceEdView_v558_ = _pKitAssignEdView_v559_ = nil;
    [_knobs removeAllObjects];
    [_knobMap removeAllObjects];
    [_drum808Knobs removeAllObjects];
}

-(void)_rebuildMixPanelFromModel_v824{
    NSRect frame = _pMixV547 ? _pMixV547.frame : _panelContentRect_v552_;
    if(frame.size.width < 8.f || frame.size.height < 8.f)
        frame = _panelContentRect_v552_;
    NSView* parent = _pMixV547 ? _pMixV547.superview : nil;
    if(_pMixV547) [_pMixV547 removeFromSuperview];
    _pMixV547 = [self _mixPanel_v547_:frame];
    _pMixV547.hidden = (_tab != ArpSIDTabMixV547);
    ArpSIDFinalizeControlUX(_pMixV547);
    if(parent) [parent addSubview:_pMixV547 positioned:NSWindowBelow relativeTo:nil];
}

-(void)_layoutMainChromeControls{
#if defined(ARPSID_AUV2_COMPONENT)
    if(_deferAuv2OOPEditorBuild_v831 && !_built) return;
#endif
    NSView* host=[self _activeChromeHostPanel];
    if(!host) return;
    const CGFloat x=10.f;
    const CGFloat y=host.bounds.size.height-24.f;
    const CGFloat gap=4.f;
    const CGFloat modelW=ArpSID::componentFlavorIsDedicatedDrum(_componentFlavor)
        ? (_componentFlavor == ArpSID::ComponentFlavor::Sid808 ? 158.f : 150.f)
        : 138.f;
    const CGFloat modeW=98.f;
    const CGFloat playModeW=276.f;
    const BOOL showModePop = (_modePop && !_modePop.hidden);
    const BOOL showPlayMode = (_playModeSeg && !_playModeSeg.hidden);
    if(_modelPop) _modelPop.frame=NSMakeRect(x,y,modelW,18.f);
    CGFloat rightX=host.bounds.size.width-10.f;
    if(_playModeSeg){
        _playModeSeg.hidden = !showPlayMode;
        if(showPlayMode){
            rightX -= playModeW;
            _playModeSeg.frame=NSMakeRect(rightX,y-1.f,playModeW,20.f);
            rightX -= gap;
        }
    }
    if(_modePop){
        _modePop.hidden = !showModePop;
        if(showModePop){
            rightX -= modeW;
            _modePop.frame=NSMakeRect(rightX,y,modeW,18.f);
            rightX -= gap;
        }
    }
    if(_presetPop){
        const CGFloat presetX=x+modelW+gap;
        const CGFloat presetW=std::max(220.0, (double)(rightX - presetX));
        _presetPop.frame=NSMakeRect(presetX,y,presetW,18.f);
    }
}

-(void)_mountMainChromeControls{
#if defined(ARPSID_AUV2_COMPONENT)
    if(_deferAuv2OOPEditorBuild_v831 && !_built) return;
#endif
    NSView* host=[self _activeChromeHostPanel];
    if(!host) return;
    [self _layoutMainChromeControls];
    for(id obj in @[(id)(_modelPop ? _modelPop : NSNull.null),
                     (id)(_presetPop ? _presetPop : NSNull.null),
                     (id)(_modePop ? _modePop : NSNull.null),
                     (id)(_playModeSeg ? _playModeSeg : NSNull.null)]){
        if(obj == NSNull.null) continue;
        NSView* v = (NSView*)obj;
        if(v.superview != host) [v removeFromSuperview];
        if(v.superview != host) [host addSubview:v];
    }
}

-(void)_applyModelSelectionIndex:(NSInteger)idx{
    if(![self _requireBridgeForAction:[NSString stringWithUTF8String:__func__]]) return;
    idx = MAX(0, MIN(3, idx));
    const float revisionNorm = ArpSIDQuickModelChipRevisionNorm(idx, 0.0f);
    const float familyNorm = idx >= 3 ? 1.0f : 0.0f;
    [self _applyRealtimeNormalizedParam:(int)ArpSID::kParamSidChipRevision value:revisionNorm
                          defaultCenter:ArpSID::sidChipRevisionIndexToNormalized(ArpSID::kSidChipRevisionDefaultIndex)];
    [self _applyRealtimeNormalizedParam:(int)ArpSID::kParamSidModel value:familyNorm
                          defaultCenter:1.0f];
    _needsDeferredPresetUISync.store(true, std::memory_order_release);
}

-(void)_applyModeSelectionIndex:(NSInteger)idx{
    if(![self _requireBridgeForAction:[NSString stringWithUTF8String:__func__]]) return;
    if(ArpSID::componentFlavorIsDedicatedDrum(_componentFlavor)) {
        idx = 2;
    } else if(_componentFlavor == ArpSID::ComponentFlavor::Instrument) {
        // v930: Pure Instrument is always the playable SYNTH / SID REG surface.
        // Never remap a DrSID request to CLASSIC/BitPerfect through stale UI state.
        idx = 1;
    } else {
        idx = MAX(0, MIN(2, idx));
    }
    const BOOL modeIsClassic = (idx == 0);
    const BOOL modeIsSynth = (idx == 1);
    const BOOL modeIsDrSid = (idx == 2);
    const float synth = modeIsSynth ? 1.f : 0.f;
    const float drsid = modeIsDrSid ? 1.f : 0.f;
    // v950: the mode popup selects structural note authority. ARP is always
    // cleared on mode selection, but DrSID/SID808 owns SEQ as drum-pattern
    // transport after v949; re-selecting DrSID must not stop a running pattern.
    (void)modeIsClassic;
    const float arp = 0.f;
    const float seq = modeIsDrSid
        ? [self _cachedParamValue:ArpSID::kParamSeqEnable defaultCenter:0.0f]
        : 0.f;
    [self _storeCachedParamValue:ArpSID::kParamSynthModeEnable value:synth];
    [self _storeCachedParamValue:ArpSID::kParamDrSidEnable value:drsid];
    [self _storeCachedParamValue:ArpSID::kParamArpEnable value:arp];
    [self _storeCachedParamValue:ArpSID::kParamSeqEnable value:seq];
    id<ArpSIDParameterLike> synthParam=[_au.parameterTree parameterWithAddress:(AUParameterAddress)ArpSID::kParamSynthModeEnable];
    id<ArpSIDParameterLike> drsidParam=[_au.parameterTree parameterWithAddress:(AUParameterAddress)ArpSID::kParamDrSidEnable];
    id<ArpSIDParameterLike> arpParam=[_au.parameterTree parameterWithAddress:(AUParameterAddress)ArpSID::kParamArpEnable];
    id<ArpSIDParameterLike> seqParam=[_au.parameterTree parameterWithAddress:(AUParameterAddress)ArpSID::kParamSeqEnable];
    if(synthParam) [synthParam setValue:synth originator:_tok]; else [_au setParameterValue:synth forID:ArpSID::kParamSynthModeEnable];
    if(drsidParam) [drsidParam setValue:drsid originator:_tok]; else [_au setParameterValue:drsid forID:ArpSID::kParamDrSidEnable];
    if(arpParam) [arpParam setValue:arp originator:_tok]; else [_au setParameterValue:arp forID:ArpSID::kParamArpEnable];
    if(seqParam) [seqParam setValue:seq originator:_tok]; else [_au setParameterValue:seq forID:ArpSID::kParamSeqEnable];
    if(_modePop && _modePop.indexOfSelectedItem != idx) [_modePop selectItemAtIndex:idx];
}


-(void)_applyPlayModeSelectionIndex:(NSInteger)idx{
    if(![self _requireBridgeForAction:[NSString stringWithUTF8String:__func__]]) return;
    idx = MAX(0, MIN(3, idx));
    const float v = (float)idx / 3.0f;
    [self _storeCachedParamValue:ArpSID::kParamVoiceMode value:v];
    id<ArpSIDParameterLike> p=[_au.parameterTree parameterWithAddress:(AUParameterAddress)ArpSID::kParamVoiceMode];
    if(p) [p setValue:v originator:_tok];
    else [_au setParameterValue:v forID:ArpSID::kParamVoiceMode];
}

-(void)_applyPatchSelectionNumber:(NSInteger)tag{
    if(![self _requireBridgeForAction:[NSString stringWithUTF8String:__func__]]) return;
    if(tag < 0 || tag > ArpSID::kCanonicalFactoryPatchSlotMax) return;
    [self _markCurrentStateAsExternalPatch];
    _loadedDrumUserKitURL=nil;
    [self _refreshDrumUserKitMetaLabel];

    const bool wasAlreadyApplying = _isApplyingPreset.exchange(true, std::memory_order_acq_rel);
    if(wasAlreadyApplying) return;

    _lastObservedModeIndex = -1;
    _lastObservedProgram = -1;
    _lastObservedBankSlot = -1;
    _lastFactoryPresetCount = -1;
    _needsDeferredPresetUISync.store(true, std::memory_order_release);

    @try {
        const auto& defs = ArpSID::getFactoryPatchDefinitions();
        if ((size_t)tag < defs.size()) {
            NSString* resolvedName = [NSString stringWithUTF8String:defs[(size_t)tag].displayName.c_str()];
            (void)resolvedName;
        }
        if([_au respondsToSelector:@selector(applyUserFactoryPresetNumber:)]){
            const BOOL ok = [_au applyUserFactoryPresetNumber:tag];
            if(!ok){ _isApplyingPreset.store(false, std::memory_order_release); return; }
            [self _storeCachedParamValue:ArpSID::kParamBankSlot value:[_au getParameterValue:ArpSID::kParamBankSlot]];
            [self _storeCachedParamValue:ArpSID::kParamProgram value:[_au getParameterValue:ArpSID::kParamProgram]];
            _needsDeferredPresetUISync.store(true, std::memory_order_release);
            _isApplyingPreset.store(false, std::memory_order_release);
            return;
        }
        // GUI/user preset selection must use the explicit sticky-authority API.
        // Falling back to setCurrentPreset: re-enters the ambiguous host preset
        // path, so fail closed instead of selecting via BankSlot/currentPreset.
        _isApplyingPreset.store(false, std::memory_order_release);
        return;
    } @catch (NSException*) {
        _isApplyingPreset.store(false, std::memory_order_release);
    }
}

-(void)_deferPatchSelectionNumber:(NSInteger)tag{
    if(tag < 0 || tag > ArpSID::kCanonicalFactoryPatchSlotMax) return;
    __weak ArpSIDViewController* weakSelf=self;
    // UI-driven preset changes must not run inside AppKit control tracking.
    // Defer to the next main-runloop turn so popup/button mouse-up cleanup has
    // fully completed before AU/KVO/property notifications fan back into UI.
    dispatch_async(dispatch_get_main_queue(), ^{
        ArpSIDViewController* strongSelf=weakSelf;
        if(!strongSelf) return;
        [strongSelf _applyPatchSelectionNumber:tag];
    });
}


-(void)_playModeChg:(id)sender{
    NSSegmentedControl* seg=(NSSegmentedControl*)sender;
    [self _applyPlayModeSelectionIndex:seg.selectedSegment];
    _needsDeferredPresetUISync.store(true, std::memory_order_release);
}

// ─── MIDI HUD ─────────────────────────────────────────────────────────────────
// (updateMIDIStatus: defined in (MIDIStatus) category below)

-(void)_openMIDIPreferencesFromHUD:(NSNotification*)note{
    (void)note;
    if([NSApp sendAction:@selector(showMIDIPreferences:) to:nil from:self]) return;
    if([NSApp sendAction:@selector(showMIDIDeviceSelector:) to:nil from:self]) return;
    if([NSApp sendAction:@selector(openMIDIPreferences:) to:nil from:self]) return;
    if([NSApp sendAction:@selector(openMIDIDeviceSelector:) to:nil from:self]) return;
    [[NSNotificationCenter defaultCenter] postNotificationName:@"ArpSIDOpenMIDIPreferences"
                                                        object:self
                                                      userInfo:_midiHUD ? @{ @"sourceView": _midiHUD } : nil];
    NSBeep();
}

-(void)_handleSelectTabNotification:(NSNotification*)note{
    NSNumber* idxNum = note.userInfo[@"tabIndex"];
    if(!idxNum) return;
    NSInteger idx = MAX(0, MIN((NSInteger)ArpSIDTabDigiV563, idxNum.integerValue));
    const ArpSIDTab requested=static_cast<ArpSIDTab>(idx);
    const ArpSIDTab visible=ArpSIDCanonicalVisibleTabForFlavor(_componentFlavor, requested);
    if(_tabBar){
        const NSInteger seg=ArpSIDVisibleTabSegmentForFlavor(_componentFlavor, visible);
        if(seg >= 0 && seg < _tabBar.segmentCount) _tabBar.selectedSegment = seg;
    }
    [self _showTab:visible];
}

-(void)updateMIDIStatus:(NSString*)statusLine activity:(BOOL)active{
    if(![NSThread isMainThread]){
        NSString* s=[statusLine copy];
        __weak ArpSIDViewController* weakSelf = self;
        dispatch_async(dispatch_get_main_queue(), ^{
            ArpSIDViewController* strongSelf = weakSelf;
            if(!strongSelf) return;
            if(strongSelf->_controllerTearingDown_v277_.load(std::memory_order_acquire)) return;
            [strongSelf updateMIDIStatus:s activity:active];
        });
        return;
    }
    if(!_midiHUDLabel)return;
    ArpSIDSetLabelStringIfNeeded(_midiHUDLabel, statusLine ? statusLine : @"No MIDI input");
    ArpSIDSetLabelColorIfNeeded(_midiHUDLabel, active
        ? c64LtGreen()
        : [colLabel() colorWithAlphaComponent:.8f]);
    _midiActLED.on = active;
    [_midiHUD setNeedsDisplay:YES];}
