    _presentationHUDLabel.textColor = [colTitle() colorWithAlphaComponent:.90f];
    _presentationHUDLabel.lineBreakMode = NSLineBreakByTruncatingTail;
    [presentationHUD addSubview:_presentationHUDLabel];
    [self _applyPresentationHUD];

    // ── On-screen piano keyboard (footer centre) ────────────────────────
    _c64BadgeView=[[ArpSIDC64LogoView alloc]initWithFrame:NSMakeRect(presX+presW+8,presY,90,presH)];
    _c64BadgeView.toolTip=@"C64 heritage badge for the realtime SID/DrSID footer strip, now with live transport, output, and forensic-status motion.";
    [root addSubview:_c64BadgeView];

    CGFloat pianoX=NSMaxX(_c64BadgeView.frame)+14,pianoY=footerBaseY+2,pianoW=kW-kBW*2-(NSMaxX(_c64BadgeView.frame)+14)-310-18,pianoH=kFtrH-4;
    _pianoView=[[ArpSIDPianoView alloc]initWithFrame:NSMakeRect(pianoX,pianoY,pianoW,pianoH)];
    _pianoView.toolTip=@"MPK25-style 25-key keybed: C3 to C5. Click / drag to play, with direct black-key hit-test and ⌘↑/↓ octave shift.";
    _pianoView.octaveOffset=_pianoOctaveOffset;
    // Octave shift buttons flanking the piano
    NSButton*octDn=ArpSIDCreateFixedChromeButton(@"▼", self, @selector(_octaveDown:),
                                                 NSMakeRect(pianoX-16,pianoY,16,pianoH));
    ArpSIDStyleChromeButton(octDn, ArpSIDChromeButtonRoleUtility, 7.2f);
    octDn.toolTip=@"Shift the on-screen MPK25 keybed down one octave (⌘↓)";
    [root addSubview:octDn];
    NSButton*octUp=ArpSIDCreateFixedChromeButton(@"▲", self, @selector(_octaveUp:),
                                                 NSMakeRect(pianoX+pianoW,pianoY,16,pianoH));
    ArpSIDStyleChromeButton(octUp, ArpSIDChromeButtonRoleUtility, 7.2f);
    octUp.toolTip=@"Shift the on-screen MPK25 keybed up one octave (⌘↑)";
    [root addSubview:octUp];
    __weak ArpSIDViewController*wkSelf=self;
    _pianoView.noteOn=^(int note){
        ArpSIDViewController*s=wkSelf;if(!s||!s->_au)return;
        const uint8_t data[3] = {0x90, (uint8_t)std::clamp(note, 0, 127), 100};
        if(s->_au)[s->_au injectMIDIBytes:data length:3];
    };
    _pianoView.noteOff=^(int note){
        ArpSIDViewController*s=wkSelf;if(!s||!s->_au)return;
        const uint8_t data[3] = {0x80, (uint8_t)std::clamp(note,0,127), 0};
        if(s->_au)[s->_au injectMIDIBytes:data length:3];
    };
    [root addSubview:_pianoView];

    // ── MIDI HUD strip (right side of footer) ─────────────────────────────
    // Shows the name of the connected MIDI keyboard + activity LED
    CGFloat hudX = kW-kBW-310, hudY = footerBaseY+2, hudW = 304, hudH = kFtrH-4;
    _midiHUD = [[ArpSIDMIDIHUDView alloc] initWithFrame:NSMakeRect(hudX,hudY,hudW,hudH)];
    ArpSIDConfigureHUDChrome(_midiHUD, .62f);
    _midiHUD.toolTip = @"Click to open MIDI device selector and monitor the live CC mapping strip";
    _midiHUD.clickAction = ^{
        [[NSNotificationCenter defaultCenter] postNotificationName:ArpSIDRequestOpenMIDIPreferencesNotification object:nil];
    };
    [root addSubview:_midiHUD];
    NSTextField* midiCaption=[NSTextField labelWithString:@"MIDI INPUT"];
    midiCaption.frame=NSMakeRect(34,hudH-11,hudW-40,8);
    midiCaption.font=monoBF(6.4f);
    midiCaption.textColor=[c64Cyan() colorWithAlphaComponent:.70f];
    [_midiHUD addSubview:midiCaption];

    // Activity LED inside HUD
    _midiActLED = [[ArpSIDLEDView alloc] initWithFrame:NSMakeRect(6,7,24,24)];
    _midiActLED.onColor = c64LtGreen();
    _midiActLED.label = @"";
    _midiActLED.on = NO;
    [_midiHUD addSubview:_midiActLED];

    // Status label inside HUD
    _midiHUDLabel = [NSTextField labelWithString:@"No MIDI input"];
    _midiHUDLabel.frame = NSMakeRect(34, 16, hudW-40, 10);
    _midiHUDLabel.font = monoBF(8.3f);
    _midiHUDLabel.textColor = [colLabel() colorWithAlphaComponent:.8f];
    _midiHUDLabel.lineBreakMode = NSLineBreakByTruncatingTail;
    [_midiHUD addSubview:_midiHUDLabel];

    _ccHubLabel = [NSTextField labelWithString:ArpSIDMPKMiniDefaultMapSummaryString()];
    _ccHubLabel.frame = NSMakeRect(34, 4, hudW-38, 9);
    _ccHubLabel.font = monoF(7.0f);
    _ccHubLabel.textColor = [c64Cyan() colorWithAlphaComponent:.72f];
    _ccHubLabel.lineBreakMode = NSLineBreakByTruncatingTail;
    _ccHubLabel.toolTip = ArpSIDMPKMiniDefaultMapSummaryString();
    [_midiHUD addSubview:_ccHubLabel];
    [self _applyPresentationHUD];

    // ── Tab content panels ────────────────────────────────────────────────
    NSRect cr=NSMakeRect(sl,contentBaseY,sw,ch);
    _panelContentRect_v552_ = cr;  // v552: stored for theme-rebuild
    // Build the MAIN panel for first paint only. Logic's AUv2 remote-view host
    // times out if we synchronously construct every dense tab during bootstrap;
    // _showTab lazily creates the selected panel on first use.
    _pMain=[self _mainPanel:cr];
    ArpSIDFinalizeControlUX(_pMain);
    // SETTINGS remains visible. The duplicate C64 STATE diagnostic surface was
    // retired in v320; persisted ID 15 migrates to the main C64 cockpit.
    _pC64StateV544 = nil;
    [self _mountMainChromeControls];
    [self _layoutEmbeddedNavigation];
    [self _syncNavigationState];
    ArpSIDFinalizeControlUX(root);
    [self _showTab:_tab];}

// ─── Panel builders ───────────────────────────────────────────────────────────
-(NSView*)_mainPanel:(NSRect)r{
    NSView*v=[[NSView alloc]initWithFrame:r];v.wantsLayer=YES;
    const CGFloat p=6,h4=(r.size.height-p*2-9)/4;
    [self _sect:v t:@"◈ MASTER" f:NSMakeRect(p,r.size.height-p-h4,r.size.width-p*2,h4-3)
     pids:@[@(ArpSID::kParamMasterVolume),@(ArpSID::kParamMasterTune),@(ArpSID::kParamPortamentoTime),
            @(ArpSID::kParamVoiceMode),@(ArpSID::kParamVoiceSpread)]];
    CGFloat vw=(r.size.width-p*4)/3;
    for(int i=0;i<3;++i){
        NSArray*ps=i==0?@[@(ArpSID::kParamVCO1Waveform),@(ArpSID::kParamVCO1PulseWidth),@(ArpSID::kParamVCO1PWMDepth),
                              @(ArpSID::kParamVCO1Detune),@(ArpSID::kParamVCO1Level),@(ArpSID::kParamVCO1LowFreqMode),
                              @(ArpSID::kParamVCO1SyncEnable),@(ArpSID::kParamVCO1RingModEnable)]:
                    i==1?@[@(ArpSID::kParamVCO2Waveform),@(ArpSID::kParamVCO2PulseWidth),@(ArpSID::kParamVCO2PWMDepth),
                              @(ArpSID::kParamVCO2Detune),@(ArpSID::kParamVCO2Level),@(ArpSID::kParamVCO2LowFreqMode),
                              @(ArpSID::kParamVCO2SyncEnable),@(ArpSID::kParamVCO2RingModEnable)]:
                         @[@(ArpSID::kParamVCO3Waveform),@(ArpSID::kParamVCO3PulseWidth),@(ArpSID::kParamVCO3PWMDepth),
                              @(ArpSID::kParamVCO3Detune),@(ArpSID::kParamVCO3Level),@(ArpSID::kParamVCO3LowFreqMode),
                              @(ArpSID::kParamVCO3SyncEnable),@(ArpSID::kParamVCO3RingModEnable)];
        [self _sect:v t:[@[@"◈ VCO 1",@"◈ VCO 2",@"◈ VCO 3"][i] copy]
             f:NSMakeRect(p+i*(vw+p),r.size.height-p*2-h4*2+3,vw,h4-3) pids:ps];}
    CGFloat fw=r.size.width*.57f-p*1.5f;
    ArpSIDPanel*filterPanel=[[ArpSIDPanel alloc] init:NSMakeRect(p,r.size.height-p*3-h4*3+6,fw,h4-3) t:@"◈ FILTER TRACE"];
    [v addSubview:filterPanel];
    _filterView=[[ArpSIDFilterResponseView alloc] initWithFrame:NSMakeRect(8,22,filterPanel.bounds.size.width-16,filterPanel.bounds.size.height-36)];
    _filterView.autoresizingMask=NSViewWidthSizable|NSViewHeightSizable;
    _filterView.accentColor=c64Cyan();
    _filterView.toolTip=@"Live filter response, sweep, and signal trace";
    [filterPanel addSubview:_filterView];
    NSTextField*filterHint=[NSTextField labelWithString:@"Full filter controls and extended scope overlays now live on the dedicated FILTER tab (⌘F)."];
    filterHint.frame=NSMakeRect(8,8,filterPanel.bounds.size.width-16,10);
    filterHint.autoresizingMask=NSViewWidthSizable|NSViewMaxYMargin;
    filterHint.font=monoF(7.0f);
    filterHint.textColor=[c64Cyan() colorWithAlphaComponent:.74f];
    [filterPanel addSubview:filterHint];
    [self _sect:v t:@"◈ ADSR" f:NSMakeRect(p+fw+p,r.size.height-p*3-h4*3+6,r.size.width-fw-p*3,h4-3)
     pids:@[@(ArpSID::kParamAttack),@(ArpSID::kParamDecay),@(ArpSID::kParamSustain),@(ArpSID::kParamRelease)]];
    [self _sect:v t:@"◈ OUTPUT / FX" f:NSMakeRect(p,p+2,r.size.width-p*2,h4-5)
     pids:@[@(ArpSID::kParamOutputLimiter),@(ArpSID::kParamLimiterThreshold),@(ArpSID::kParamLimiterAttack),@(ArpSID::kParamLimiterRelease),@(ArpSID::kParamReverbMix)]];
    return v;}

-(NSView*)_lfoPanel:(NSRect)r{
    NSView*v=[[NSView alloc]initWithFrame:r];v.wantsLayer=YES;
    const CGFloat p=6,hh=(r.size.height-p*3)*.5f,lw=(r.size.width-p*5)/4;
    static const int lR[]={ArpSID::kParamLFORate,ArpSID::kParamLFO2Rate,ArpSID::kParamLFO3Rate,ArpSID::kParamLFO4Rate};
    static const int lD[]={ArpSID::kParamLFODepth,ArpSID::kParamLFO2Depth,ArpSID::kParamLFO3Depth,ArpSID::kParamLFO4Depth};
    static const int lS[]={ArpSID::kParamLFOShape,ArpSID::kParamLFO2Shape,ArpSID::kParamLFO3Shape,ArpSID::kParamLFO4Shape};
    static const int lY[]={ArpSID::kParamLFOSync,ArpSID::kParamLFO2Sync,ArpSID::kParamLFO3Sync,ArpSID::kParamLFO4Sync};
    for(int i=0;i<4;++i){
        ArpSIDPanel*pan=[self _sectPanel:v t:[NSString stringWithFormat:@"◈ LFO %d",i+1]
             f:NSMakeRect(p+i*(lw+p),r.size.height-p-hh,lw,hh)
             pids:@[@(lR[i]),@(lD[i]),@(lS[i]),@(lY[i])]];
        _lfoWaveView[i]=[[ArpSIDLFOWaveView alloc] initWithFrame:NSMakeRect(8,22,pan.bounds.size.width-16,pan.bounds.size.height-30)];
        _lfoWaveView[i].autoresizingMask=NSViewWidthSizable|NSViewHeightSizable;
        _lfoWaveView[i].accentColor=ArpSIDVoiceColor(i);
        _lfoWaveView[i].toolTip=@"Realtime LFO waveform, depth, sync, and phase";
        [pan addSubview:_lfoWaveView[i]];
    }
    ArpSIDPanel* arpPanel=[self _sectPanel:v t:@"◈ ARPEGGIATOR" f:NSMakeRect(p,p,r.size.width-p*2,hh)
     pids:@[@(ArpSID::kParamArpEnable),@(ArpSID::kParamArpMode),@(ArpSID::kParamArpRate),
            @(ArpSID::kParamArpOctaves),@(ArpSID::kParamArpSwing),@(ArpSID::kParamArpGate),
            @(ArpSID::kParamArpHold),@(ArpSID::kParamArpLatch),@(ArpSID::kParamArpTranspose),@(ArpSID::kParamArpRandom),
            @(ArpSID::kParamArpPatternLength)]];
    _arpSyncSeg=[[ArpSIDSegmentedToolTipControl alloc] initWithFrame:NSMakeRect(arpPanel.bounds.size.width-92.f,arpPanel.bounds.size.height-19.f,84.f,16.f)];
    _arpSyncSeg.segmentCount=2;
    [_arpSyncSeg setLabel:@"HOST" forSegment:0];
    [_arpSyncSeg setLabel:@"INT" forSegment:1];
    _arpSyncSeg.segmentStyle=NSSegmentStyleTexturedRounded;
    _arpSyncSeg.trackingMode=NSSegmentSwitchTrackingSelectOne;
    _arpSyncSeg.selectedSegment=1;
    _arpSyncSeg.target=self;
    _arpSyncSeg.action=@selector(_arpSyncChg:);
    _arpSyncSeg.font=monoBF(7.6f);
    _arpSyncSeg.toolTip=@"Explicit arpeggiator sync selector: HOST uses transport tempo, INT restores the last internal rate.";
    [(ArpSIDSegmentedToolTipControl*)_arpSyncSeg setSegmentToolTips:ArpSIDSyncSegmentTooltips(NO)];
    _arpSyncSeg.autoresizingMask=NSViewMinXMargin|NSViewMinYMargin;
    [arpPanel addSubview:_arpSyncSeg];
    return v;}

-(NSView*)_forensicPanel:(NSRect)r{
    NSView*v=[[NSView alloc]initWithFrame:r];v.wantsLayer=YES;
    const CGFloat p=6.f;
    const CGFloat ctrlH=106.f;
    const CGFloat hw=(r.size.width-p*3)*.5f;
    const CGFloat topY=r.size.height-p-ctrlH;
    const CGFloat midY=topY-p-ctrlH;
    const CGFloat vizY=p;
    const CGFloat vizH=MAX(132.f, midY-p-p);
    const CGFloat scopePanelW=(r.size.width-p*3)*0.54f;
    const CGFloat filterPanelW=r.size.width-p*3-scopePanelW;

    [self _sect:v t:@"◈ FORENSIC GLOBAL" f:NSMakeRect(p,topY,hw,ctrlH)
     pids:@[@(ArpSID::kParamForensicEnable),@(ArpSID::kParamForensicIntensity),
            @(ArpSID::kParamSidChipRevision),@(ArpSID::kParamSidExternalRcEnable),
            @(ArpSID::kParamSidOversamplingFactor),@(ArpSID::kParamForensicStartupRandom),
            @(ArpSID::kParamForensicDigifix8580),@(ArpSID::kParamForensicRevision),
            @(ArpSID::kParamForensicChipSeed)]];
    [self _sect:v t:@"◈ CLOCK / SUPPLY" f:NSMakeRect(p*2+hw,topY,hw,ctrlH)
     pids:@[@(ArpSID::kParamForensicTemp),@(ArpSID::kParamForensicSupply),
            @(ArpSID::kParamForensicClockJitterEnable),@(ArpSID::kParamForensicClockJitter),
            @(ArpSID::kParamForensicSupplyRippleEnable),@(ArpSID::kParamForensicSupplyRipple),
            @(ArpSID::kParamForensicThermalDriftEnable),@(ArpSID::kParamForensicThermalDrift)]];
    [self _sect:v t:@"◈ VOICE / FILTER" f:NSMakeRect(p,midY,hw,ctrlH)
     pids:@[@(ArpSID::kParamForensicVoiceCrosstalkEnable),@(ArpSID::kParamForensicVoiceCrosstalk),
            @(ArpSID::kParamForensicExternalBleedEnable),@(ArpSID::kParamForensicExternalBleed),
            @(ArpSID::kParamForensicEnvelopeTDM),@(ArpSID::kParamForensicFilterOhmic)]];
    [self _sect:v t:@"◈ ADC / BUS / BOARD" f:NSMakeRect(p*2+hw,midY,hw,ctrlH)
     pids:@[@(ArpSID::kParamForensicD418Asymmetry),@(ArpSID::kParamForensicSystemNoise),
            @(ArpSID::kParamForensicMotherboard),@(ArpSID::kParamForensicADCBleed),
            @(ArpSID::kParamForensicBusCollision),@(ArpSID::kParamForensicPOTInput)]];
    ArpSIDPanel*scopePanel=[[ArpSIDPanel alloc] init:NSMakeRect(p,vizY,scopePanelW,vizH) t:@"◈ FORENSIC VCO SCOPES"];
    [v addSubview:scopePanel];
    {
        const CGFloat scopePad=8.f;
        const CGFloat labelH=12.f;
        const CGFloat scopeW=(scopePanel.bounds.size.width-scopePad*4)/3.f;
        const CGFloat scopeH=scopePanel.bounds.size.height-34.f;
        NSColor* vc3[3]={c64Cyan(),c64Yellow(),c64LtGreen()};
        NSString* vl3[3]={@"VCO 1",@"VCO 2",@"VCO 3"};
        for(int i=0;i<3;++i){
            const CGFloat sx=scopePad+i*(scopeW+scopePad);
            NSTextField*lb=[NSTextField labelWithString:vl3[i]];
            lb.frame=NSMakeRect(sx,scopePanel.bounds.size.height-labelH-6.f,scopeW,labelH);
            lb.font=monoBF(8.5f);lb.alignment=NSTextAlignmentCenter;lb.textColor=vc3[i];
            [scopePanel addSubview:lb];
            ArpSIDOscilloscopeView*sv=[[ArpSIDOscilloscopeView alloc] initWithFrame:NSMakeRect(sx,10.f,scopeW,scopeH)];
            sv.accentColor=vc3[i];
            sv.toolTip=@"Realtime forensic VCO scope with phosphor trail, scope glow, and render-published forensic activity.";
            [scopePanel addSubview:sv];
            if(i==0)_vco1Scope=sv;
            else if(i==1)_vco2Scope=sv;
            else _vco3Scope=sv;
        }
    }

    ArpSIDPanel*filterPanel=[[ArpSIDPanel alloc] init:NSMakeRect(p*2+scopePanelW,vizY,filterPanelW,vizH) t:@"◈ FILTER / BUS TRACE"];
    [v addSubview:filterPanel];
    // filterView shrunk 34 px at bottom to make room for 4-row analogue telemetry HUD
    _forensicFilterView=[[ArpSIDFilterResponseView alloc] initWithFrame:NSMakeRect(8,58,filterPanel.bounds.size.width-16,filterPanel.bounds.size.height-74)];
    _forensicFilterView.autoresizingMask=NSViewWidthSizable|NSViewHeightSizable;
    _forensicFilterView.accentColor=c64Orange();
    _forensicFilterView.emphasizeScopes=YES;
    _forensicFilterView.toolTip=@"Forensic filter/bus view with live input-output scope overlay, modulation lane, and analog stress glow.";
    [filterPanel addSubview:_forensicFilterView];
    // Row 1 — STATUS (y=46, h=11)
    _forensicHUDRow1=[NSTextField labelWithString:@""];
    _forensicHUDRow1.frame=NSMakeRect(8,46,filterPanel.bounds.size.width-16,11);
    _forensicHUDRow1.autoresizingMask=NSViewWidthSizable|NSViewMaxYMargin;
    _forensicHUDRow1.font=monoF(7.2f);
    _forensicHUDRow1.textColor=[c64Yellow() colorWithAlphaComponent:.80f];
    _forensicHUDRow1.lineBreakMode=NSLineBreakByTruncatingTail;
    [filterPanel addSubview:_forensicHUDRow1];
    // Row 2 — CLOCK / SUPPLY (y=34, h=11)
    _forensicHUDRow2=[NSTextField labelWithString:@""];
    _forensicHUDRow2.frame=NSMakeRect(8,34,filterPanel.bounds.size.width-16,11);
    _forensicHUDRow2.autoresizingMask=NSViewWidthSizable|NSViewMaxYMargin;
    _forensicHUDRow2.font=monoF(7.2f);
    _forensicHUDRow2.textColor=[c64Cyan() colorWithAlphaComponent:.76f];
    _forensicHUDRow2.lineBreakMode=NSLineBreakByTruncatingTail;
    [filterPanel addSubview:_forensicHUDRow2];
    // Row 3 — VOICE / FILTER (y=22, h=11)
    _forensicHUDRow3=[NSTextField labelWithString:@""];
    _forensicHUDRow3.frame=NSMakeRect(8,22,filterPanel.bounds.size.width-16,11);
    _forensicHUDRow3.autoresizingMask=NSViewWidthSizable|NSViewMaxYMargin;
    _forensicHUDRow3.font=monoF(7.2f);
    _forensicHUDRow3.textColor=[c64LtGreen() colorWithAlphaComponent:.76f];
    _forensicHUDRow3.lineBreakMode=NSLineBreakByTruncatingTail;
    [filterPanel addSubview:_forensicHUDRow3];
    // Row 4 — ADC / BUS / BOARD (y=10, h=11)
    _forensicScopeHUDLabel=[NSTextField labelWithString:@""];
    _forensicScopeHUDLabel.frame=NSMakeRect(8,10,filterPanel.bounds.size.width-16,11);
    _forensicScopeHUDLabel.autoresizingMask=NSViewWidthSizable|NSViewMaxYMargin;
    _forensicScopeHUDLabel.font=monoF(7.2f);
    _forensicScopeHUDLabel.textColor=[c64Yellow() colorWithAlphaComponent:.76f];
    _forensicScopeHUDLabel.lineBreakMode=NSLineBreakByTruncatingTail;
    [filterPanel addSubview:_forensicScopeHUDLabel];

    return v;}

-(NSView*)_sidRegPanel:(NSRect)r{
    NSView*v=[[NSView alloc]initWithFrame:r];v.wantsLayer=YES;
    const CGFloat p=6;
    const CGFloat scopeH=74.f;
    const CGFloat hudH=34.f;
    CGFloat kRowH2=kHdrH+8;
    [self _sect:v t:@"◈ SYNTH MODE" f:NSMakeRect(p,r.size.height-p-kRowH2,r.size.width-p*2,kRowH2)
     pids:@[@(ArpSID::kParamSynthModeEnable),@(ArpSID::kParamSidChipRevision),
            @(ArpSID::kParamSidExternalRcEnable),@(ArpSID::kParamSidOversamplingFactor),
            @(ArpSID::kParamSidAdsrBug6581)]];

    const CGFloat scopeY = r.size.height - p - kRowH2 - p - scopeH;
    const CGFloat scopeW = (r.size.width - p*4) / 3.0f;
    NSColor* vc[3]={c64Cyan(),c64Yellow(),c64LtGreen()};
    NSString* labels[3]={@"SID V1",@"SID V2",@"SID V3"};
    for(int i=0;i<3;++i){
        const CGFloat sx = p + i*(scopeW+p);
        NSTextField*lb=[NSTextField labelWithString:labels[i]];
        lb.frame=NSMakeRect(sx,scopeY+scopeH+2,scopeW,12);
        lb.font=monoBF(8.5f);lb.alignment=NSTextAlignmentCenter;lb.textColor=vc[i];
        [v addSubview:lb];
        ArpSIDOscilloscopeView*sv=[[ArpSIDOscilloscopeView alloc] initWithFrame:NSMakeRect(sx,scopeY,scopeW,scopeH)];
        sv.accentColor=vc[i];
        [v addSubview:sv];
        if(i==0)_coreVco1Scope=sv;
        else if(i==1)_coreVco2Scope=sv;
        else _coreVco3Scope=sv;
    }

    CGFloat regY=p+hudH;
    CGFloat regH=scopeY-p-p-hudH;
    _sidRegLive=[[ArpSIDSidRegView alloc]initWithFrame:NSMakeRect(p,regY,r.size.width-p*2,MAX(96.f,regH))];
    __weak ArpSIDViewController* ws=self;
    _sidRegLive.writeCallback=^(int reg, uint8_t val){
        ArpSIDViewController*s=ws;if(!s||!s->_au)return;
        if(reg<0||reg>=0x19)return;
        if([s->_au respondsToSelector:@selector(writeSIDRegister:value:)]){
            [(id)s->_au writeSIDRegister:(uint8_t)reg value:val];
            return;
        }
        const int pid=(int)ArpSID::kParamSidRegD400+reg;
        const float norm=(float)val/255.f;
        id<ArpSIDParameterLike> p2=[s->_au.parameterTree parameterWithAddress:(AUParameterAddress)pid];
        if(p2)[p2 setValue:norm originator:s->_tok];
        else [s->_au setParameterValue:norm forID:pid];};
    [v addSubview:_sidRegLive];
    _sidRegSummaryLabel=[NSTextField labelWithString:@"SID selector / clock / analog options"];
    _sidRegSummaryLabel.frame=NSMakeRect(p,p+18,r.size.width-p*2,12);
    _sidRegSummaryLabel.autoresizingMask=NSViewWidthSizable|NSViewMaxYMargin;
    _sidRegSummaryLabel.font=monoBF(7.6f);
    _sidRegSummaryLabel.textColor=[colTitle() colorWithAlphaComponent:.86f];
    [v addSubview:_sidRegSummaryLabel];
    _sidRegDetailLabel=[NSTextField labelWithString:@"Filter route / misc probes / selected register decode"];
    _sidRegDetailLabel.frame=NSMakeRect(p,p+5,r.size.width-p*2,11);
    _sidRegDetailLabel.autoresizingMask=NSViewWidthSizable|NSViewMaxYMargin;
    _sidRegDetailLabel.font=monoF(7.2f);
    _sidRegDetailLabel.textColor=[colLabel() colorWithAlphaComponent:.76f];
    [v addSubview:_sidRegDetailLabel];
    return v;}

-(NSView*)_sidCorePanel:(NSRect)r{
    NSView*v=[[NSView alloc]initWithFrame:r];v.wantsLayer=YES;
    const CGFloat p=8.f;
    const CGFloat dockH=MAX(118.f, MIN(158.f, r.size.height*0.28f));
    const CGFloat glY=p+dockH+p;
    const CGFloat glH=MAX(220.f, r.size.height - glY - p);
    const CGFloat colW=(r.size.width-p*5)/4;

    // The Metal shader surface owns the visual field; V1/V2/V3 scopes are
    // transparent overlays within the same GPU panel — no hidden duplicate panels.
    ArpSIDPanel* glPanel=[[ArpSIDPanel alloc] init:NSMakeRect(p,glY,r.size.width-p*2,glH) t:@"◈ SIDCORE GPU MATRIX / SID BUS 3D / OVERLAY SCOPES / LOAD BACKSCREEN FLICKER"];
    [v addSubview:glPanel];
    _sidCoreMetalBackdropView=[[ArpSIDSidCoreMetalBackdropView alloc] initWithFrame:NSMakeRect(8,10,glPanel.bounds.size.width-16,glPanel.bounds.size.height-24)];
    _sidCoreMetalBackdropView.autoresizingMask=NSViewWidthSizable|NSViewHeightSizable;
    [glPanel addSubview:_sidCoreMetalBackdropView positioned:NSWindowBelow relativeTo:nil];
    _sidCoreVectorView=[[ArpSIDSidCoreVectorView alloc] initWithFrame:NSMakeRect(8,10,glPanel.bounds.size.width-16,glPanel.bounds.size.height-24)];
    _sidCoreVectorView.autoresizingMask=NSViewWidthSizable|NSViewHeightSizable;
    _sidCoreVectorView.wantsLayer=YES;
    _sidCoreVectorView.layer.backgroundColor=[[NSColor clearColor] CGColor];
    _sidCoreVectorView.toolTip=@"Bounded HUD overlay above Metal shader. Geometry updates are coalesced to VSync.";
    [glPanel addSubview:_sidCoreVectorView];

    NSView* scopeOverlay=[[NSView alloc] initWithFrame:NSMakeRect(14,glPanel.bounds.size.height-96,glPanel.bounds.size.width-28,82)];
    scopeOverlay.autoresizingMask=NSViewWidthSizable|NSViewMinYMargin;
    scopeOverlay.wantsLayer=YES;
    scopeOverlay.layer.backgroundColor=[[NSColor colorWithCalibratedRed:0.000 green:0.014 blue:0.004 alpha:0.42] CGColor];
    scopeOverlay.layer.cornerRadius=9.0;
    scopeOverlay.layer.borderWidth=1.0;
    scopeOverlay.layer.borderColor=[[NSColor colorWithCalibratedRed:0.12 green:1.00 blue:0.28 alpha:0.42] CGColor];
    [glPanel addSubview:scopeOverlay positioned:NSWindowAbove relativeTo:_sidCoreVectorView];
    _coreSummary=[NSTextField labelWithString:@"SIDCORE OVERLAY\nVSync shader + scopes\nNo hidden background scopes"];
    _coreSummary.frame=NSMakeRect(10,9,190,64); _coreSummary.font=monoBF(8.4f); _coreSummary.textColor=[NSColor colorWithCalibratedRed:0.18 green:1.00 blue:0.30 alpha:0.96]; _coreSummary.usesSingleLineMode=NO; _coreSummary.lineBreakMode=NSLineBreakByWordWrapping; [scopeOverlay addSubview:_coreSummary];
    {
        NSColor* vc[3]={[NSColor colorWithCalibratedRed:0.10 green:1.00 blue:0.30 alpha:1.0],
                       [NSColor colorWithCalibratedRed:0.10 green:0.95 blue:1.00 alpha:1.0],
                       [NSColor colorWithCalibratedRed:1.00 green:0.32 blue:0.92 alpha:1.0]};
        NSString* labels[3]={@"V1 MATRIX",@"V2 CYAN",@"V3 RAINBOW"};
        const CGFloat sx0 = 210.f;
        const CGFloat gap = 9.f;
        const CGFloat topScopeW = MAX(58.f, (scopeOverlay.bounds.size.width-sx0-gap*2)/3.f);
        for(int i=0;i<3;++i){
            const CGFloat sx = sx0 + i*(topScopeW+gap);
            NSTextField*lb=[NSTextField labelWithString:labels[i]];
            lb.frame=NSMakeRect(sx,62.f,topScopeW,11.f);
            lb.font=monoBF(7.4f); lb.alignment=NSTextAlignmentCenter; lb.textColor=vc[i];
            [scopeOverlay addSubview:lb];
            ArpSIDOscilloscopeView*sv=[[ArpSIDOscilloscopeView alloc] initWithFrame:NSMakeRect(sx,8.f,topScopeW,52.f)];
            sv.accentColor=vc[i];
            sv.toolTip=@"Transparent SIDCORE overlay scope: latest sanitized render snapshot, no duplicate background scope.";
            [scopeOverlay addSubview:sv];
            if(i==0)_sidCoreTopVco1Scope=sv;
            else if(i==1)_sidCoreTopVco2Scope=sv;
            else _sidCoreTopVco3Scope=sv;
        }
    }

    ArpSIDPanel* voice=[[ArpSIDPanel alloc] init:NSMakeRect(p,p,colW,dockH) t:@"◈ MATRIX VOICE / GATES"];
    [v addSubview:voice];
    _coreVoiceText=[NSTextField labelWithString:@"V1\nV2\nV3"];
    _coreVoiceText.frame=NSMakeRect(10,10,colW-20,dockH-20); _coreVoiceText.font=monoF(8.4f); _coreVoiceText.textColor=[NSColor colorWithCalibratedRed:0.16 green:1.00 blue:0.34 alpha:0.92]; _coreVoiceText.usesSingleLineMode=NO; _coreVoiceText.lineBreakMode=NSLineBreakByWordWrapping; [voice addSubview:_coreVoiceText];
    for (int i = 0; i < 8; ++i) _coreVoiceScopes[i] = nil;

    ArpSIDPanel* filter=[[ArpSIDPanel alloc] init:NSMakeRect(p*2+colW,p,colW,dockH) t:@"◈ FILTER / OPEN BUS"];
    [v addSubview:filter];
    _coreFilterText=[NSTextField labelWithString:@"Cutoff\nRoute\nMode\nBus"];
    _coreFilterText.frame=NSMakeRect(10,10,colW-20,dockH-20); _coreFilterText.font=monoF(8.7f); _coreFilterText.textColor=[NSColor colorWithCalibratedRed:0.22 green:1.00 blue:0.58 alpha:0.90]; _coreFilterText.usesSingleLineMode=NO; _coreFilterText.lineBreakMode=NSLineBreakByWordWrapping; [filter addSubview:_coreFilterText];

    ArpSIDPanel* ctrl=[[ArpSIDPanel alloc] init:NSMakeRect(p*3+colW*2,p,colW,dockH) t:@"◈ 6510 / VIC / CIA / DISASM"];
    [v addSubview:ctrl];
    _coreCtrlText=[NSTextField labelWithString:@"PC beam\nRaster\nIRQ\nDISASM"];
    _coreCtrlText.frame=NSMakeRect(10,10,colW-20,dockH-20); _coreCtrlText.font=monoF(8.4f); _coreCtrlText.textColor=[NSColor colorWithCalibratedRed:0.10 green:0.92 blue:1.00 alpha:0.90]; _coreCtrlText.usesSingleLineMode=NO; _coreCtrlText.lineBreakMode=NSLineBreakByWordWrapping; [ctrl addSubview:_coreCtrlText];

    ArpSIDPanel* fx=[[ArpSIDPanel alloc] init:NSMakeRect(p*4+colW*3,p,colW,dockH) t:@"◈ FORENSIC / REGS / GPU"];
    [v addSubview:fx];
    _coreFxText=[NSTextField labelWithString:@"Limiter\nReverb\nForensic\nShader"];
    _coreFxText.frame=NSMakeRect(10,dockH*0.48f,colW-20,dockH*0.52f-10); _coreFxText.font=monoF(8.2f); _coreFxText.textColor=[NSColor colorWithCalibratedRed:1.00 green:0.34 blue:0.92 alpha:0.88]; _coreFxText.usesSingleLineMode=NO; _coreFxText.lineBreakMode=NSLineBreakByWordWrapping; [fx addSubview:_coreFxText];
    _coreRegsText=[NSTextField labelWithString:@"D400: 00 00 00 00 00 00 00 00\nD408: 00 00 00 00 00 00 00 00\nD410: 00 00 00 00 00 00 00 00\nD418: 00 00"];
    _coreRegsText.frame=NSMakeRect(10,8,colW-20,dockH*0.48f-8); _coreRegsText.font=monoF(7.5f); _coreRegsText.textColor=[NSColor colorWithCalibratedRed:0.68 green:1.00 blue:0.74 alpha:0.72]; _coreRegsText.usesSingleLineMode=NO; _coreRegsText.lineBreakMode=NSLineBreakByClipping; [fx addSubview:_coreRegsText];

    // Pop-out button: floats the Metal shader in a dedicated resizable/full-screen-capable window.
    _sidCorePopoutButton=ArpSIDCreateFixedChromeButton(@"⤢ POP OUT", self, @selector(_sidCoreTogglePopout:),
                                                       NSMakeRect(glPanel.bounds.size.width-120,glPanel.bounds.size.height-22,112,18));
    _sidCorePopoutButton.autoresizingMask=NSViewMinXMargin|NSViewMinYMargin;
    ArpSIDStyleChromeButton(_sidCorePopoutButton, ArpSIDChromeButtonRoleUtility, 7.8f);
    _sidCorePopoutButton.toolTip=@"Pop the SIDCORE Metal shader into a dedicated floating window. The window is resizable and full-screen capable via standard macOS controls.";
    [glPanel addSubview:_sidCorePopoutButton positioned:NSWindowAbove relativeTo:nil];

    return v;
}

-(void)_updateSidRegisterStatusWithTelemetry:(const ArpSIDTelemetry&)tel{
    if(!_sidRegSummaryLabel && !_sidRegDetailLabel) return;
    const uint8_t* r=tel.sidRegs;
    const float chipRevisionNorm=[self _cachedParamValue:ArpSID::kParamSidChipRevision defaultCenter:ArpSID::sidChipRevisionIndexToNormalized(ArpSID::kSidChipRevisionDefaultIndex)];
    const BOOL uiNtsc=[self _cachedParamValue:ArpSID::kParamSidClockSystem defaultCenter:ArpSID::defaultNormalizedParamValue(ArpSID::kParamSidClockSystem)]>0.5f;
    const BOOL ntsc=ArpSIDTelemetryNtsc(tel, uiNtsc);
    NSString* uiModel=[NSString stringWithUTF8String:ArpSID::sidChipRevisionSelectorLabel(chipRevisionNorm)];
    NSString* model=ArpSIDTelemetrySidModelLabel(tel, uiModel);
    const BOOL extRc=[self _cachedParamValue:ArpSID::kParamSidExternalRcEnable defaultCenter:ArpSID::defaultNormalizedParamValue(ArpSID::kParamSidExternalRcEnable)]>0.5f;
    const float oversamplingNorm=[self _cachedParamValue:ArpSID::kParamSidOversamplingFactor defaultCenter:ArpSID::defaultNormalizedParamValue(ArpSID::kParamSidOversamplingFactor)];
    const BOOL adsrBug=[self _cachedParamValue:ArpSID::kParamSidAdsrBug6581 defaultCenter:ArpSID::defaultNormalizedParamValue(ArpSID::kParamSidAdsrBug6581)]>0.5f;
    const uint16_t cutoff=(uint16_t)(((r[22] & 0x07u) << 8) | r[21]);
    const int sel=_sidRegLive ? [_sidRegLive selectedRegisterIndex] : -1;
    NSString* selectedReg=(sel>=0&&sel<30)
        ? [NSString stringWithFormat:@"SEL %@ %@", ArpSIDSidRegisterAddressString(sel), ArpSIDSidRegisterShortNameForIndex(sel)]
        : @"SEL --";
    if(_sidRegSummaryLabel){
        ArpSIDSetLabelStringIfNeeded(_sidRegSummaryLabel,
                                     [NSString stringWithFormat:@"%@  •  CLOCK %@  •  EXT RC %@  •  OS %s  •  ADSR %@  •  MODE %@  •  V %d  •  PK %@/%@",
                                      model,
                                      ArpSIDSidClockLabel(ntsc),
                                      ArpSIDOnOffString(extRc),
                                      ArpSID::sidOversamplingLabel(oversamplingNorm),
                                      ArpSIDOnOffString(adsrBug),
                                      ArpSIDRenderModeString(tel.renderMode),
                                      tel.activeVoices,
                                      ArpSIDPercentNormString(tel.peakL),
                                      ArpSIDPercentNormString(tel.peakR)]);
    }
    if(_sidRegDetailLabel){
        ArpSIDSetLabelStringIfNeeded(_sidRegDetailLabel,
                                     [NSString stringWithFormat:@"FC %04X  •  ROUTE %@  •  MODE %@  •  ACT %@/%@/%@  •  ENV %@/%@/%@  •  OSC3 %02X  ENV3 %02X  •  POT %02X/%02X  •  SYS %@  •  %@",
                                      cutoff, ArpSIDRouteString(r[23]), ArpSIDFilterModeString(r[24]),
                                      ArpSIDOnOffString((tel.vcoActiveMask & 0x01u) != 0),
                                      ArpSIDOnOffString((tel.vcoActiveMask & 0x02u) != 0),
                                      ArpSIDOnOffString((tel.vcoActiveMask & 0x04u) != 0),
                                      ArpSIDPercentNormString(tel.voiceEnvLevel[0]),
                                      ArpSIDPercentNormString(tel.voiceEnvLevel[1]),
                                      ArpSIDPercentNormString(tel.voiceEnvLevel[2]),
                                      r[27], r[28], r[25], r[26], ArpSIDSidSystemBitsString(r[29]), selectedReg]);
    }
}

-(void)_updateSidCoreWithTelemetry:(const ArpSIDTelemetry&)tel{
    if(!_coreSummary && !_coreVoiceText && !_coreFilterText && !_coreFxText && !_coreRegsText && !_coreCtrlText) return;
    const uint8_t* r = tel.sidRegs;
    const NSString* mode = ArpSIDRenderModeString(tel.renderMode);
    const float chipRevisionNorm=[self _cachedParamValue:ArpSID::kParamSidChipRevision defaultCenter:ArpSID::sidChipRevisionIndexToNormalized(ArpSID::kSidChipRevisionDefaultIndex)];
    NSString* uiModel = [NSString stringWithUTF8String:ArpSID::sidChipRevisionSelectorLabel(chipRevisionNorm)];
    NSString* model = ArpSIDTelemetrySidModelLabel(tel, uiModel);
    const NSString* voiceMode = ArpSIDVoiceModeString(tel.voiceMode);
    const NSString* patch = ArpSIDPatchSlotString(tel.bankSlot, tel.programNumber);
    const NSString* patchName = [self _displayNameForEffectiveBankSlot:tel.bankSlot];
    const float limiter = [self _cachedParamValue:ArpSID::kParamOutputLimiter defaultCenter:ArpSID::defaultNormalizedParamValue(ArpSID::kParamOutputLimiter)];
    const float limiterThr = [self _cachedParamValue:ArpSID::kParamLimiterThreshold defaultCenter:ArpSID::defaultNormalizedParamValue(ArpSID::kParamLimiterThreshold)];
    const float reverbMix = [self _cachedParamValue:ArpSID::kParamReverbMix defaultCenter:ArpSID::defaultNormalizedParamValue(ArpSID::kParamReverbMix)];
    const float forensicOn = tel.forensicEnabled ? 1.0f : 0.0f;
    const float forensicIntensity = ArpSIDUIClamp01(tel.forensicIntensity);
    const float forensicActivity = ArpSIDUIClamp01(tel.forensicActivity);
    const BOOL uiNtsc=[self _cachedParamValue:ArpSID::kParamSidClockSystem defaultCenter:ArpSID::defaultNormalizedParamValue(ArpSID::kParamSidClockSystem)]>0.5f;
    const BOOL ntsc=ArpSIDTelemetryNtsc(tel, uiNtsc);
    const BOOL extRc=[self _cachedParamValue:ArpSID::kParamSidExternalRcEnable defaultCenter:ArpSID::defaultNormalizedParamValue(ArpSID::kParamSidExternalRcEnable)]>0.5f;
    const float oversamplingNorm=[self _cachedParamValue:ArpSID::kParamSidOversamplingFactor defaultCenter:ArpSID::defaultNormalizedParamValue(ArpSID::kParamSidOversamplingFactor)];
    const BOOL adsrBug=[self _cachedParamValue:ArpSID::kParamSidAdsrBug6581 defaultCenter:ArpSID::defaultNormalizedParamValue(ArpSID::kParamSidAdsrBug6581)]>0.5f;

    if(_sidCoreMetalBackdropView) [_sidCoreMetalBackdropView setForensicActivity:forensicActivity intensity:forensicIntensity enabled:(forensicOn>0.5f)];
    if(_c64BusMetalBackdropView) [_c64BusMetalBackdropView setForensicActivity:forensicActivity intensity:forensicIntensity enabled:(forensicOn>0.5f)];
    if(_sidCoreVectorView) [_sidCoreVectorView setForensicActivity:forensicActivity intensity:forensicIntensity enabled:(forensicOn>0.5f)];
    if(_meterView) _meterView.forensicActivity = forensicActivity;
    if(_vco1Scope) _vco1Scope.forensicActivity = forensicActivity;
    if(_vco2Scope) _vco2Scope.forensicActivity = forensicActivity;
    if(_vco3Scope) _vco3Scope.forensicActivity = forensicActivity;
    if(_coreVco1Scope) _coreVco1Scope.forensicActivity = forensicActivity;
    if(_coreVco2Scope) _coreVco2Scope.forensicActivity = forensicActivity;
    if(_coreVco3Scope) _coreVco3Scope.forensicActivity = forensicActivity;
    for (int i = 0; i < 8; ++i) if (_coreVoiceScopes[i]) _coreVoiceScopes[i].forensicActivity = forensicActivity;

    if(_coreSummary){
        _coreSummary.stringValue = [NSString stringWithFormat:@"Mode %@   Model %@   Voice %@   Patch %@\nName %@\nTransport %@  %.2f BPM  beat %.2f   Peaks L %@ R %@\nFlags Synth %@  DrSID %@  Arp %@  Seq %@  Active voices %d  Last note %d  Clock %@\nC64 BUS HUD %@  PHI2 %llu  VIC %03u:%02u  BA %@ AEC %@ BAD %@",
            mode, model, voiceMode, patch,
            patchName,
            ArpSIDBoolFlagString(tel.hostPlaying, @"RUN", @"STOP"), ArpSIDUIFiniteDouble(tel.hostTempo, 120.0), ArpSIDUIFiniteDouble(tel.hostBeat, 0.0),
            ArpSIDPercentNormString(tel.peakL), ArpSIDPercentNormString(tel.peakR),
            ArpSIDOnOffString(tel.synthMode), ArpSIDOnOffString(tel.drSidMode), ArpSIDOnOffString(tel.arpEnabled), ArpSIDOnOffString(tel.seqEnabled), tel.activeVoices, tel.lastMidiNote,
            ArpSIDSidClockLabel(ntsc),
            ArpSIDC64AuthorityLabel(tel),
            (unsigned long long)tel.c64Phi2Cycle, (unsigned)tel.c64VicRaster, (unsigned)tel.c64VicCycle,
            ArpSIDOnOffString(tel.c64VicBa), ArpSIDOnOffString(tel.c64VicAec), ArpSIDOnOffString(tel.c64VicBadline)];
    }

    if(_coreVoiceText){
        const BOOL g1 = (r[4] & 0x01u) != 0;
        const BOOL g2 = (r[11] & 0x01u) != 0;
        const BOOL g3 = (r[18] & 0x01u) != 0;
        _coreVoiceText.stringValue = [NSString stringWithFormat:
            @"MATRIX VOICE ENERGY / TRUE SID GATES\nV1 %@  ENV %@  freq %@  PW %@\n   %@  ADSR %@\nV2 %@  ENV %@  freq %@  PW %@\n   %@  ADSR %@\nV3 %@  ENV %@  freq %@  PW %@\n   %@  ADSR %@\nRainbow glow follows ADSR envelope + gate + bus heat",
            ArpSIDMatrixBarString(tel.voiceEnvLevel[0], g1), ArpSIDPercentNormString(tel.voiceEnvLevel[0]), ArpSIDHex16String(r[1], r[0]), ArpSIDPercent12String(r[3], r[2]), ArpSIDVoiceStateSummary(r[4]), ArpSIDADSRString(r[5], r[6]),
            ArpSIDMatrixBarString(tel.voiceEnvLevel[1], g2), ArpSIDPercentNormString(tel.voiceEnvLevel[1]), ArpSIDHex16String(r[8], r[7]), ArpSIDPercent12String(r[10], r[9]), ArpSIDVoiceStateSummary(r[11]), ArpSIDADSRString(r[12], r[13]),
            ArpSIDMatrixBarString(tel.voiceEnvLevel[2], g3), ArpSIDPercentNormString(tel.voiceEnvLevel[2]), ArpSIDHex16String(r[15], r[14]), ArpSIDPercent12String(r[17], r[16]), ArpSIDVoiceStateSummary(r[18]), ArpSIDADSRString(r[19], r[20])];
        _coreVoiceText.textColor = [c64LtGreen() colorWithAlphaComponent:(0.74f + 0.24f * ArpSIDUIClamp01(std::max(tel.voiceEnvLevel[0], std::max(tel.voiceEnvLevel[1], tel.voiceEnvLevel[2]))))];
    }

    if(_coreFilterText){
        const NSString* fc = ArpSIDHex16String(r[22] & 0x07u, r[21]);
        _coreFilterText.stringValue = [NSString stringWithFormat:
            @"Cutoff raw %@  %@\nRoute %@\nMode %@\nVoice mask 0x%02X  active %@/%@/%@\nLow gates V1/V2/V3 %@/%@/%@\nBus state open %02X  read %02X  SID $D4%02X=%02X\nBus flags 3OFF %@  ext %@\nOSC3 %02X  ENV3 %02X  SYS %@",
            fc, ArpSIDPercent12String(r[22] & 0x07u, r[21]), ArpSIDRouteString(r[23]), ArpSIDFilterModeString(r[24]), (unsigned)tel.vcoActiveMask,
            ArpSIDOnOffString((tel.vcoActiveMask & 0x01u) != 0), ArpSIDOnOffString((tel.vcoActiveMask & 0x02u) != 0), ArpSIDOnOffString((tel.vcoActiveMask & 0x04u) != 0),
            ArpSIDOnOffString((r[4] & 0x01u) != 0), ArpSIDOnOffString((r[11] & 0x01u) != 0), ArpSIDOnOffString((r[18] & 0x01u) != 0),
            (unsigned)tel.c64OpenBus, (unsigned)tel.c64LastRead, (unsigned)tel.c64LastSidReg, (unsigned)tel.c64LastSidValue,
            ArpSIDOnOffString((r[24] & 0x80u) != 0), ArpSIDOnOffString((r[23] & 0x08u) != 0), (unsigned)r[27], (unsigned)r[28], ArpSIDSidSystemBitsString(r[29])];
    }

    if(_coreCtrlText){
        NSString* lastCc = tel.lastMappedCC >= 0
            ? [NSString stringWithFormat:@"CC%02d %@", tel.lastMappedCC, ArpSIDPercentNormString(tel.lastMappedCCValue)]
            : @"CC --";
        NSString* d0 = ArpSIDDisasmLineString(@"PC", tel.c64DisasmPc[0], tel.c64DisasmLine[0], YES);
        NSString* d1 = ArpSIDDisasmLineString(@"+1", tel.c64DisasmPc[1], tel.c64DisasmLine[1], NO);
        NSString* d2 = ArpSIDDisasmLineString(@"+2", tel.c64DisasmPc[2], tel.c64DisasmLine[2], NO);
        _coreCtrlText.stringValue = [NSString stringWithFormat:
            @"PSID %@  %@/%@  %@ - %@\nClock %@  SYS %@  Overs %s  ADSR %@  ExtRC %@\n6510 PC %04X  A:%02X X:%02X Y:%02X SP:%02X P:%02X  FLAGS:NVDIZC mirror\n%@\n%@\n%@\nVIC beam r%03u/c%02u  BA %@ AEC %@ BAD %@  raster shader %.2f\nCIA IRQ %02X/%02X  POT %02X/%02X  OSC3 %02X ENV3 %02X\nSIDBUS open %02X read %02X  write $D4%02X=%02X  heat %03u  PClo %02X\nAuthority projection: param/buttons -> runtime -> $D400 bus -> C64 mirror -> Metal shader/HUD\nMW %@  PB %+0.2f  AT %@  Poly %@  Rand %+0.2f\nTokens %u/%u  %@",
            tel.psidTitle[0] ? [NSString stringWithUTF8String:tel.psidTitle] : @"No .sid file loaded",
            tel.psidCurrentSubtune ? [NSString stringWithFormat:@"%u", (unsigned)tel.psidCurrentSubtune] : @"-",
            tel.psidSongs ? [NSString stringWithFormat:@"%u", (unsigned)tel.psidSongs] : @"-",
            tel.psidAuthor[0] ? [NSString stringWithUTF8String:tel.psidAuthor] : @"",
            tel.psidReleased[0] ? [NSString stringWithUTF8String:tel.psidReleased] : @"",
            ArpSIDSidClockLabel(ntsc), ArpSIDSidSystemBitsString(r[29]), ArpSID::sidOversamplingLabel(oversamplingNorm), ArpSIDOnOffString(adsrBug), ArpSIDOnOffString(extRc),
            (unsigned)tel.c64CpuPc, (unsigned)tel.c64CpuA, (unsigned)tel.c64CpuX, (unsigned)tel.c64CpuY, (unsigned)tel.c64CpuSp, (unsigned)tel.c64CpuStatus,
            d0, d1, d2,
            (unsigned)tel.c64VicRaster, (unsigned)tel.c64VicCycle, ArpSIDOnOffString(tel.c64VicBa), ArpSIDOnOffString(tel.c64VicAec), ArpSIDOnOffString(tel.c64VicBadline), ArpSIDUIClamp01(((float)tel.c64VicRaster + (float)tel.c64VicCycle / 64.0f) / 312.0f),
            (unsigned)tel.c64Cia1Irq, (unsigned)tel.c64Cia2Irq, (unsigned)r[25], (unsigned)r[26], (unsigned)r[27], (unsigned)r[28],
            (unsigned)tel.c64OpenBus, (unsigned)tel.c64LastRead, (unsigned)tel.c64LastSidReg, (unsigned)tel.c64LastSidValue, (unsigned)(tel.c64OpenBus + tel.c64LastSidValue), (unsigned)(tel.c64CpuPc & 0x00FFu),
            ArpSIDPercentNormString(tel.modWheelNorm), ArpSIDUIClampSigned(tel.focusedPitchBend), ArpSIDPercentNormString(tel.focusedChannelPressure), ArpSIDPercentNormString(tel.focusedPolyPressure), ArpSIDUIClampSigned(tel.randomValue),
            tel.activeTokenCount, tel.totalActiveTokenCount, lastCc];
        _coreCtrlText.textColor = [c64LtGreen() colorWithAlphaComponent:.84f];
    }

    [self _updateC64PlayerInfoWithTelemetry:tel];

    if(_coreFxText){
        _coreFxText.stringValue = [NSString stringWithFormat:
            @"Master vol %X / 15\nLimiter %@  Thr %@\nReverb %@\nC64 TAB %@  PHI2 %llu  unified SID bus mirror\nForensic %@  Int %@  Act %@\nJit %@ Rip %@ Drift %@\nXtalk %@ Bleed %@\nOhm %@ Noise %@ D418 %@\nEnv %@ MB %@ ADC %@\nBus %@ POT %@ Digi %@",
            r[24] & 0x0Fu, ArpSIDOnOffString(limiter > 0.5f), ArpSIDPercentNormString(limiterThr),
            ArpSIDPercentNormString(reverbMix), ArpSIDOnOffString(tel.c64PlatformEnabled), (unsigned long long)tel.c64Phi2Cycle,
            ArpSIDOnOffString(forensicOn > 0.5f), ArpSIDPercentNormString(forensicIntensity), ArpSIDPercentNormString(forensicActivity),
            ArpSIDPercentNormString(tel.forensicClockJitter), ArpSIDPercentNormString(tel.forensicSupplyRipple),
            ArpSIDPercentNormString(tel.forensicThermalDrift), ArpSIDPercentNormString(tel.forensicVoiceCrosstalk), ArpSIDPercentNormString(tel.forensicExternalBleed),
            ArpSIDPercentNormString(tel.forensicFilterOhmic), ArpSIDPercentNormString(tel.forensicSystemNoise), ArpSIDPercentNormString(tel.forensicD418Asymmetry),
            ArpSIDPercentNormString(tel.forensicEnvelopeTDM), ArpSIDPercentNormString(tel.forensicMotherboard), ArpSIDPercentNormString(tel.forensicADCBleed),
            ArpSIDPercentNormString(tel.forensicBusCollision), ArpSIDPercentNormString(tel.forensicPotInput), ArpSIDOnOffString(tel.forensicDigifix8580)];
    }

    if(_coreRegsText){
        _coreRegsText.stringValue = [NSString stringWithFormat:
            @"D400: %02X %02X %02X %02X %02X %02X %02X %02X\nD408: %02X %02X %02X %02X %02X %02X %02X %02X\nD410: %02X %02X %02X %02X %02X %02X %02X %02X\nD418: %02X %02X %02X %02X %02X %02X",
            r[0],r[1],r[2],r[3],r[4],r[5],r[6],r[7],
            r[8],r[9],r[10],r[11],r[12],r[13],r[14],r[15],
            r[16],r[17],r[18],r[19],r[20],r[21],r[22],r[23],
            r[24],r[25],r[26],r[27],r[28],r[29]];
    }
}

// ─── Section helper ───────────────────────────────────────────────────────────
-(ArpSIDPanel*)_sectPanel:(NSView*)par t:(NSString*)t f:(NSRect)f pids:(NSArray*)pids{
    ArpSIDPanel*pan=[[ArpSIDPanel alloc]init:f t:t];
    pan.identifier=t;
    [par addSubview:pan];
    const CGFloat in=4,aw=f.size.width-in*2,ah=f.size.height-18-in;
    int n=(int)pids.count;if(!n)return pan;
    int cols=n;while(cols>1&&aw/cols<54)--cols;
    int rows=(n+cols-1)/cols;CGFloat cw=aw/cols,ch=ah/rows;
    for(int i=0;i<n;++i){int col=i%cols,row=i/cols;
        [self _knob:pan p:[pids[i] intValue] f:NSMakeRect(in+col*cw,in+(rows-1-row)*ch,cw,ch)];}
    return pan;
}
-(void)_sect:(NSView*)par t:(NSString*)t f:(NSRect)f pids:(NSArray*)pids{
    (void)[self _sectPanel:par t:t f:f pids:pids];
}

-(void)_knob:(NSView*)par p:(int)pid f:(NSRect)f{
    if(pid<0||pid>=ArpSID::kNumParams)return;
    const ArpSID::ParamInfo&info=ArpSID::kParamInfos[(size_t)pid];
    ArpSIDKnobView*kv=[[ArpSIDKnobView alloc]initF:f n:[NSString stringWithUTF8String:info.name] p:pid d:info.defaultNorm];
    kv.toolTip=ArpSIDKnobTooltipForParam(pid);
    kv.tgt=self;kv.act=@selector(_knobChg:);[par addSubview:kv];[_knobs addObject:kv];
    if(_knobMap) _knobMap[@(pid)] = kv;
}

-(ArpSIDKnobView*)_drumKnob:(NSView*)par p:(int)pid title:(NSString*)title f:(NSRect)f{
    if(pid<0||pid>=ArpSID::kNumParams)return nil;
    const ArpSID::ParamInfo&info=ArpSID::kParamInfos[(size_t)pid];
    NSString*knobTitle=(title.length>0)?title:[NSString stringWithUTF8String:info.name];
    ArpSIDKnobView*kv=[[ArpSIDKnobView alloc]initF:f n:knobTitle p:pid d:info.defaultNorm];
    kv.pname=knobTitle;
    kv.toolTip=ArpSIDKnobTooltipForParam(pid);
    kv.tgt=self;
    kv.act=@selector(_knobChg:);
    [par addSubview:kv];
    if(!_drum808Knobs) _drum808Knobs=[NSMutableArray array];
    [_drum808Knobs addObject:kv];
    return kv;
}

// ─── DrSID Dedicated Panel ───────────────────────────────────────────────────
// Focused per-voice editor for the DrSID/SID-808 drum synthesizer. Lives at
// the dedicated `ArpSIDTabDrsid` tab — coexists with the legacy SEQ grid.
//
// Layout (top → bottom):
// • HUD strip Title + chip label + SYNC/MIDI/SID/RT LEDs
// • Row 1 [ENGINE] [MACHINE] [DRSID VOL] [ACCENT/DRIVE]
// • Row 2 [KICK] [SNARE] [HAT] [CLAP]
// • Row 3 [COWBELL] [TOM] [FILTER] [LIMITER]
// • Sequencer bridge [Seq] [Tempo] [Swing] [Mode] [Len] (mini-strip)
// • Voice triggers [KICK] [SNARE] [C-HAT] [O-HAT] [CLAP] [COW] [TOM-L] [TOM-H]
// • Footer HUD Live telemetry line
//
// Every parameter referenced here is sourced from ArpSIDDrsidTabPanel.h.
// The constexpr binding tables in that header are guarded by static_assert
// chains so any stale or fictional ParamID fails the build immediately.
-(NSView*)_drsidPanel:(NSRect)r{
    using namespace ArpSID::Drsid;

    NSView*v=[[NSView alloc] initWithFrame:r];
    v.wantsLayer=YES;
    if(v.layer) v.layer.backgroundColor=[[c64Black() colorWithAlphaComponent:0.0f] CGColor];

    const CGFloat pad=10.f;
    const CGFloat W=r.size.width;
    const CGFloat H=r.size.height;
    const CGFloat innerW=W - pad*2.f;

    // Adapter: ControlBinding[] → NSArray<NSNumber*> for the existing _sectPanel:.
    auto bindingsToPids = [](const ControlBinding* b, std::size_t n) -> NSArray* {
        NSMutableArray* a=[NSMutableArray arrayWithCapacity:n];
        for(std::size_t i=0;i<n;++i) [a addObject:@((int)b[i].id)];
        return a;
    };
    #define ARPSID_DRSID_PIDS(arr) bindingsToPids((arr), sizeof(arr)/sizeof((arr)[0]))

    // ── HUD strip ────────────────────────────────────────────────────────────
    const CGFloat hudStripH=58.f;
    const CGFloat hudStripY=H - pad - hudStripH;
    NSView* hudStrip=[[NSView alloc] initWithFrame:NSMakeRect(pad, hudStripY, innerW, hudStripH)];
    ArpSIDConfigureHUDChrome(hudStrip, .62f);
    [v addSubview:hudStrip];

    _drsidBrandView=[[ArpSIDDrumBrandView alloc] initWithFrame:NSMakeRect(7.f,5.f,390.f,hudStripH-10.f)];
    _drsidBrandView.brandKind=0;
    _drsidBrandView.toolTip=@"DrSID register-wavetable drum core";
    [hudStrip addSubview:_drsidBrandView];

    _drsidPanelClockLabel=[NSTextField labelWithString:@"PAL 985248 Hz"];
    _drsidPanelClockLabel.font=monoBF(10.5f); _drsidPanelClockLabel.textColor=c64Cyan();
    _drsidPanelClockLabel.frame=NSMakeRect(innerW-220.f, hudStripH-26.f, 210.f, 14.f);
    _drsidPanelClockLabel.alignment=NSTextAlignmentRight;
    [hudStrip addSubview:_drsidPanelClockLabel];

    _drsidPanelChipLabel=[NSTextField labelWithString:@"6581/8580 HYBRID"];
    _drsidPanelChipLabel.font=monoBF(10.5f);
    _drsidPanelChipLabel.textColor=[c64LtGreen() colorWithAlphaComponent:0.92f];
    _drsidPanelChipLabel.frame=NSMakeRect(innerW-220.f, hudStripH-42.f, 210.f, 14.f);
    _drsidPanelChipLabel.alignment=NSTextAlignmentRight;
    [hudStrip addSubview:_drsidPanelChipLabel];

    NSArray<NSString*>* ledLabels=@[@"SYNC", @"MIDI", @"SID", @"RT"];
    NSArray<NSColor*>* ledColors=@[c64LtGreen(), c64Cyan(), c64Orange(), c64Red()];
    const CGFloat ledX0=innerW - 220.f - 4.f - (CGFloat)ledLabels.count*46.f;
    for(NSUInteger i=0;i<ledLabels.count;++i){
        ArpSIDLEDView* led=[[ArpSIDLEDView alloc]
            initWithFrame:NSMakeRect(ledX0 + i*46.f, hudStripH-44.f, 22.f, 30.f)];
        led.label=ledLabels[i];
        led.onColor=ledColors[i];
        led.on=(i==2);
        if(i==0) _drsidPanelSyncLED=led;
        else if(i==1) _drsidPanelMidiLED=led;
        else if(i==2) _drsidPanelSidLED=led;
        else if(i==3) _drsidPanelRtLED=led;
        [hudStrip addSubview:led];
    }

    // ── Section grid ─────────────────────────────────────────────────────────
    const CGFloat sectH=72.f;
    const CGFloat gap=8.f;
    const CGFloat col1=pad;
    const CGFloat colW=(innerW - gap*3.f) / 4.f;
    const CGFloat col2=col1 + colW + gap;
    const CGFloat col3=col2 + colW + gap;
    const CGFloat col4=col3 + colW + gap;

    auto addSect=[&](NSString* heading, CGFloat top, CGFloat width, CGFloat left, NSArray* pids){
        const NSRect f=NSMakeRect(left, top - sectH, width, sectH);
        [self _sect:v t:heading f:f pids:pids];
    };

    CGFloat rowTop=hudStripY - 6.f;
    addSect(@"◈ ENGINE",         rowTop, colW, col1, ARPSID_DRSID_PIDS(kEngine));
    addSect(@"◈ MACHINE",        rowTop, colW, col2, ARPSID_DRSID_PIDS(kMachine));
    addSect(@"◈ DRSID VOL",      rowTop, colW, col3, ARPSID_DRSID_PIDS(kVolume));
    addSect(@"◈ ACCENT / DRIVE", rowTop, colW, col4, ARPSID_DRSID_PIDS(kAccentDrive));

    rowTop -= (sectH + gap);
    addSect(@"◈ KICK",  rowTop, colW, col1, ARPSID_DRSID_PIDS(kKick));
    addSect(@"◈ SNARE", rowTop, colW, col2, ARPSID_DRSID_PIDS(kSnare));
    addSect(@"◈ HAT",   rowTop, colW, col3, ARPSID_DRSID_PIDS(kHat));
    addSect(@"◈ CLAP",  rowTop, colW, col4, ARPSID_DRSID_PIDS(kClap));

    rowTop -= (sectH + gap);
    addSect(@"◈ COWBELL", rowTop, colW, col1, ARPSID_DRSID_PIDS(kCowbell));
    addSect(@"◈ TOM",     rowTop, colW, col2, ARPSID_DRSID_PIDS(kTom));
    addSect(@"◈ FILTER",  rowTop, colW, col3, ARPSID_DRSID_PIDS(kFilter));
    addSect(@"◈ LIMITER", rowTop, colW, col4, ARPSID_DRSID_PIDS(kLimiter));

    // ── Sequencer bridge mini-strip ──────────────────────────────────────────
    rowTop -= (sectH + gap);
    const CGFloat seqStripH=58.f;
    NSMutableArray* seqPids=[NSMutableArray arrayWithCapacity:kSequencerBridgeBindingCount];
    for(std::size_t i=0;i<kSequencerBridgeBindingCount;++i){
        [seqPids addObject:@((int)kSequencerBridge[i].id)];
    }
    [self _sect:v t:@"◈ SEQUENCER BRIDGE" f:NSMakeRect(col1, rowTop - seqStripH, innerW, seqStripH) pids:seqPids];

    // ── Voice trigger buttons ────────────────────────────────────────────────
    rowTop -= (seqStripH + gap);
    const CGFloat trigH=42.f;
    const CGFloat trigBoxH=trigH + 18.f;
    NSBox* trigBox=[[NSBox alloc] initWithFrame:NSMakeRect(col1, rowTop - trigBoxH, innerW, trigBoxH)];
    trigBox.title=@"◈ VOICE TRIGGERS  ·  GM CH10";
    trigBox.titleFont=monoBF(10.f);
    trigBox.boxType=NSBoxPrimary;
    trigBox.borderColor=[colTitle() colorWithAlphaComponent:0.35f];
    trigBox.fillColor=[c64Black() colorWithAlphaComponent:0.40f];
    // Full GM percussion key map as a hover reference on the trigger section.
    trigBox.toolTip=[NSString stringWithUTF8String:ArpSID::GUI::gmDrumMapReferenceText().c_str()];
    [v addSubview:trigBox];

    const CGFloat trigInner=innerW - 12.f;
    const CGFloat trigBtnW=(trigInner - 4.f*(CGFloat)(kVoicePadCount-1)) / (CGFloat)kVoicePadCount;
    for(std::size_t i=0;i<kVoicePadCount;++i){
        const VoicePadBinding& b=kVoicePads[i];
        // Show the GM note number on the pad so the drum key mapping is visible.
        NSButton* btn=[NSButton buttonWithTitle:[NSString stringWithFormat:@"%s %d", b.label, b.midiNote]
                                         target:self
                                         action:@selector(_drsidVoiceTrigger:)];
        const CGFloat bx=6.f + (CGFloat)i * (trigBtnW + 4.f);
        btn.frame=NSMakeRect(bx, 4.f, trigBtnW, trigH-2.f);
        btn.tag=b.midiNote;
        ArpSIDStyleChromeButton(btn, ArpSIDChromeButtonRoleUtility, 10.f);
        // Rich GM tooltip: full GM instrument name + SID drum class for this note.
        btn.toolTip=[NSString stringWithUTF8String:ArpSID::GUI::gmDrumPadTooltip(b.midiNote, b.label).c_str()];
        [trigBox addSubview:btn];
    }

    rowTop -= (trigBoxH + gap);
    const CGFloat scopeY=30.f;
    const CGFloat scopeH=rowTop - scopeY;
    if(scopeH >= 42.f){
        NSBox* scopeBox=[[NSBox alloc] initWithFrame:NSMakeRect(col1, scopeY, innerW, scopeH)];
        scopeBox.title=@"◈ LIVE SID808/DRSID SCOPE";
        scopeBox.titleFont=monoBF(10.f);
        scopeBox.boxType=NSBoxPrimary;
        scopeBox.borderColor=[c64Cyan() colorWithAlphaComponent:0.30f];
        scopeBox.fillColor=[c64Black() colorWithAlphaComponent:0.34f];
        [v addSubview:scopeBox];

        _drsidPanelScopeView=[[ArpSIDOscilloscopeView alloc]
            initWithFrame:NSMakeRect(8.f, 14.f, scopeBox.bounds.size.width-16.f, scopeBox.bounds.size.height-28.f)];
        _drsidPanelScopeView.autoresizingMask=NSViewWidthSizable|NSViewHeightSizable;
        _drsidPanelScopeView.accentColor=c64Orange();
        _drsidPanelScopeView.toolTip=@"Realtime render scope for the dedicated DrSID tab. Uses render-published drum/forensic activity and the shared oscilloscope feed.";
        [scopeBox addSubview:_drsidPanelScopeView];
    }

    // ── Footer HUD line ──────────────────────────────────────────────────────
    _drsidPanelHUDLabel=[NSTextField labelWithString:@"DRSID • idle"];
    _drsidPanelHUDLabel.font=monoBF(10.f);
    _drsidPanelHUDLabel.textColor=[colTitle() colorWithAlphaComponent:0.85f];
    _drsidPanelHUDLabel.frame=NSMakeRect(col1, 6.f, innerW, 18.f);
    _drsidPanelHUDLabel.toolTip=[NSString stringWithUTF8String:ArpSID::GUI::gmDrumMapReferenceText().c_str()];
    [v addSubview:_drsidPanelHUDLabel];

    #undef ARPSID_DRSID_PIDS
    return v;
}

// Voice trigger action: fires a MIDI note on the DrSID engine via the same
// `_au injectMIDIBytes:length:` path the on-screen keybed uses. The button
// `tag` carries the MIDI note number; the value is sourced from typed
// `Drsid::kVoicePads` whose 0–127 range is enforced by static_assert.
-(void)_drsidVoiceTrigger:(NSButton*)sender {
    if(![self _requireBridgeForAction:[NSString stringWithUTF8String:__func__]]) return;
    const int note=(int)sender.tag;
    if(note<0 || note>127) return;
    const uint8_t on[3]  = {0x99, (uint8_t)note, 110}; // channel 10 (drum) = 0x99
    [_au injectMIDIBytes:on length:3];
    // Reconstruct the note-off frame inside the block; ObjC blocks cannot
    // capture C array types by reference, so we capture the int `note` and
    // build a fresh uint8_t[3] on the block's own stack 80 ms later.
    const int capturedNote=note;
    const NSUInteger capturedSerial = ++_drumAuditionSerial;
    __weak ArpSIDViewController* weakSelf = self;
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)(0.08 * NSEC_PER_SEC)),
                   dispatch_get_main_queue(), ^{
        ArpSIDViewController* strongSelf = weakSelf;
        if(!strongSelf) return;
        if(strongSelf->_controllerTearingDown_v277_.load(std::memory_order_acquire)) return;
        if(strongSelf->_drumAuditionSerial != capturedSerial) return;
        if(strongSelf->_au){
            const uint8_t off[3] = {0x89, (uint8_t)capturedNote, 0};
            [strongSelf->_au injectMIDIBytes:off length:3];
        }
    });
}

// ─── SEQ Panel ───────────────────────────────────────────────────────────────
-(NSView*)_seqPanel:(NSRect)r{
    NSView*v=[[NSView alloc]initWithFrame:r];v.wantsLayer=YES;
    const CGFloat p=10.f;
    const CGFloat bw=r.size.width-p*2.f;
    const CGFloat bannerH=82.f;
    const CGFloat footerH=44.f;
    const CGFloat topH=198.f;
    const CGFloat bodyH=r.size.height-p*5.f-bannerH-footerH-topH;
    const CGFloat bodyY=p+footerH+p;
    const CGFloat topY=bodyY+bodyH+p;
    const CGFloat bannerY=topY+topH+p;
    const CGFloat scopeW=std::floor((bw-p)*0.30f);
    const CGFloat patternW=bw-p-scopeW;
    const CGFloat padW=std::floor((bw-p)*0.50f);
    const CGFloat ctlW=bw-p-padW;
    __weak ArpSIDViewController* weakSelf=self;

    if(!_drum808Knobs) _drum808Knobs=[NSMutableArray array];
    else [_drum808Knobs removeAllObjects];

    NSView*banner=[[NSView alloc] initWithFrame:NSMakeRect(p,bannerY,bw,bannerH)];
    ArpSIDConfigureHUDChrome(banner, .70f);
    [v addSubview:banner];

    _drumBrandView=[[ArpSIDDrumBrandView alloc] initWithFrame:NSMakeRect(10.f,8.f,590.f,banner.bounds.size.height-16.f)];
    _drumBrandView.brandKind=(_componentFlavor == ArpSID::ComponentFlavor::Sid808) ? 1 : 0;
    _drumBrandView.toolTip=ArpSIDDrumSurfaceSubtitleForFlavor(_componentFlavor);
    [banner addSubview:_drumBrandView];

    const NSArray<NSColor*>*stripeColors=@[c64Blue(), c64Cyan(), c64LtGreen(), c64Yellow(), c64Orange(), c64Red()];
    CGFloat stripeX=620.f;
    for(NSColor*stripeColor in stripeColors){
        NSView*stripe=[[NSView alloc] initWithFrame:NSMakeRect(stripeX,banner.bounds.size.height-63,16,52)];
        stripe.wantsLayer=YES;
        stripe.layer.backgroundColor=stripeColor.CGColor;
        stripe.layer.borderWidth=.4f;
        stripe.layer.borderColor=[c64White() colorWithAlphaComponent:.22f].CGColor;
        [banner addSubview:stripe];
        stripeX+=18.f;
    }

    NSArray<NSString*>*statusLabels=@[@"SYNC",@"MIDI",@"SID",@"RT"];
    NSArray<NSColor*>*statusColors=@[c64LtGreen(), c64Cyan(), c64Orange(), c64Red()];
    CGFloat ledX=banner.bounds.size.width-420.f;
    for(NSUInteger i=0;i<statusLabels.count;++i){
        ArpSIDLEDView*led=[[ArpSIDLEDView alloc] initWithFrame:NSMakeRect(ledX+i*62.f, banner.bounds.size.height-56.f, 24.f, 32.f)];
        led.label=statusLabels[i];
        led.onColor=statusColors[i];
        led.on=(i==2);
        [banner addSubview:led];
        if(i==0)_drumSyncLED=led;
        else if(i==1)_drumMidiStatusLED=led;
        else if(i==2)_drumSidStatusLED=led;
        else _drumRtLED=led;
    }

    _drumClockLabel=[NSTextField labelWithString:@"PAL 985248 Hz"];
    _drumClockLabel.frame=NSMakeRect(banner.bounds.size.width-220.f,banner.bounds.size.height-38.f,190.f,16.f);
    _drumClockLabel.alignment=NSTextAlignmentRight;
    _drumClockLabel.font=monoBF(10.5f);
    _drumClockLabel.textColor=c64Cyan();
    [banner addSubview:_drumClockLabel];

    _drumChipLabel=[NSTextField labelWithString:@"6581/8580 HYBRID"];
    _drumChipLabel.frame=NSMakeRect(banner.bounds.size.width-220.f,banner.bounds.size.height-58.f,190.f,16.f);
    _drumChipLabel.alignment=NSTextAlignmentRight;
    _drumChipLabel.font=monoBF(10.5f);
    _drumChipLabel.textColor=c64Yellow();
    [banner addSubview:_drumChipLabel];

    _drumKitInfoLabel=[NSTextField labelWithString:@"Analog X0X-8 performance surface  •  GM kick/snare/clap/hat lanes stay pinned for fast 808-style programming."];
    _drumKitInfoLabel.frame=NSMakeRect(18,12,banner.bounds.size.width-36.f,13.f);
    _drumKitInfoLabel.autoresizingMask=NSViewWidthSizable|NSViewMaxYMargin;
    _drumKitInfoLabel.font=monoBF(8.4f);
    _drumKitInfoLabel.textColor=[colTitle() colorWithAlphaComponent:.88f];
    [banner addSubview:_drumKitInfoLabel];

    ArpSIDPanel*scopePanel=[[ArpSIDPanel alloc] init:NSMakeRect(p,topY,scopeW,topH) t:@"SID REGISTER SCOPE"];
    [v addSubview:scopePanel];
    _drumScopeView=[[ArpSIDOscilloscopeView alloc] initWithFrame:NSMakeRect(10.f,22.f,scopePanel.bounds.size.width-20.f,scopePanel.bounds.size.height-42.f)];
    _drumScopeView.autoresizingMask=NSViewWidthSizable|NSViewHeightSizable;
    _drumScopeView.accentColor=c64LtGreen();
    _drumScopeView.toolTip=@"Realtime SID register scope for the SID-808 page. Uses the same live oscilloscope feed as the shared GUI HUD.";
    [scopePanel addSubview:_drumScopeView];
    NSTextField*scopeHint=[NSTextField labelWithString:@"$D400-$D418  LIVE  NOISE/PULSE/TRI"];
    scopeHint.frame=NSMakeRect(10,8,scopePanel.bounds.size.width-20,10);
    scopeHint.autoresizingMask=NSViewWidthSizable|NSViewMaxYMargin;
    scopeHint.font=monoF(7.6f);
    scopeHint.textColor=[colLabel() colorWithAlphaComponent:.70f];
    [scopePanel addSubview:scopeHint];

    ArpSIDPanel*patternPanel=[[ArpSIDPanel alloc] init:NSMakeRect(p+scopeW+p,topY,patternW,topH) t:@"16 STEP PATTERN"];
    [v addSubview:patternPanel];

    _drumKitPop=[[NSPopUpButton alloc] initWithFrame:NSMakeRect(10.f,patternPanel.bounds.size.height-30.f,216.f,18.f) pullsDown:NO];
    _drumKitPop.font=monoF(8.4f);
    for(NSInteger i=0;i<ArpSIDDrumKitCount();++i){
        [_drumKitPop addItemWithTitle:ArpSIDDrumKitPopupTitleAtIndex(i)];
    }
    _drumKitPop.target=self;
    _drumKitPop.action=@selector(_drumKitPopChg:);
    _drumKitPop.toolTip=@"Select the active DrSID / Analog X0X-8 kit while keeping the 12-pad performance layout fixed.";
    [patternPanel addSubview:_drumKitPop];

    _drumSeqPageSeg=[[ArpSIDSegmentedToolTipControl alloc] initWithFrame:NSMakeRect(232.f,patternPanel.bounds.size.height-30.f,110.f,18.f)];
    _drumSeqPageSeg.segmentCount=2;
    [_drumSeqPageSeg setLabel:@"1-16" forSegment:0];
    [_drumSeqPageSeg setLabel:@"17-32" forSegment:1];
    _drumSeqPageSeg.selectedSegment=_drumSeqPage;
    _drumSeqPageSeg.target=self;
    _drumSeqPageSeg.action=@selector(_drumSeqPageChg:);
    _drumSeqPageSeg.toolTip=@"Switch between the first and second 16-step drum pages.";
    [(ArpSIDSegmentedToolTipControl*)_drumSeqPageSeg setSegmentToolTips:ArpSIDDrumPageSegmentTooltips()];
    [patternPanel addSubview:_drumSeqPageSeg];

    _seqSyncSeg=[[ArpSIDSegmentedToolTipControl alloc] initWithFrame:NSMakeRect(348.f,patternPanel.bounds.size.height-30.f,78.f,18.f)];
    _seqSyncSeg.segmentCount=2;
    [_seqSyncSeg setLabel:@"HOST" forSegment:0];
    [_seqSyncSeg setLabel:@"INT" forSegment:1];
    _seqSyncSeg.segmentStyle=NSSegmentStyleTexturedRounded;
    _seqSyncSeg.trackingMode=NSSegmentSwitchTrackingSelectOne;
    _seqSyncSeg.selectedSegment=1;
    _seqSyncSeg.target=self;
    _seqSyncSeg.action=@selector(_seqSyncChg:);
    _seqSyncSeg.font=monoBF(7.4f);
    _seqSyncSeg.toolTip=@"Explicit sequencer sync selector: HOST follows transport tempo, INT free-runs from the internal BPM.";
    [(ArpSIDSegmentedToolTipControl*)_seqSyncSeg setSegmentToolTips:ArpSIDSyncSegmentTooltips(YES)];
    [patternPanel addSubview:_seqSyncSeg];

    NSButton*stamp=[NSButton buttonWithTitle:@"STAMP" target:self action:@selector(_drumKitStamp:)];
    stamp.frame=NSMakeRect(434.f,patternPanel.bounds.size.height-30.f,66.f,18.f);
    ArpSIDStyleChromeButton(stamp, ArpSIDChromeButtonRoleAccent, 8.0f);
    stamp.toolTip=@"Stamp the selected kit’s authored pattern into the visible 16-step page.";
    [patternPanel addSubview:stamp];

    NSButton*clear=[NSButton buttonWithTitle:@"CLEAR" target:self action:@selector(_drumKitClear:)];
    clear.frame=NSMakeRect(504.f,patternPanel.bounds.size.height-30.f,66.f,18.f);
    ArpSIDStyleChromeButton(clear, ArpSIDChromeButtonRoleDanger, 8.0f);
    clear.toolTip=@"Clear the visible 16-step page.";
    [patternPanel addSubview:clear];

    _drumBpmLabel=[NSTextField labelWithString:@"BPM 120.00"];
    _drumBpmLabel.frame=NSMakeRect(patternPanel.bounds.size.width-170.f,patternPanel.bounds.size.height-35.f,158.f,24.f);
