-(NSView*)_filterPanel:(NSRect)r{
    NSView*v=[[NSView alloc]initWithFrame:r];v.wantsLayer=YES;
    const CGFloat p=6.f;
    const CGFloat topH=std::floor((r.size.height-p*3)*0.56f);
    const CGFloat bottomH=r.size.height-p*3-topH;
    const CGFloat colW=(r.size.width-p*4)/3.f;

    ArpSIDPanel*surface=[[ArpSIDPanel alloc] init:NSMakeRect(p,r.size.height-p-topH,r.size.width-p*2,topH) t:@"◈ LIVE FILTER SURFACE"];
    [v addSubview:surface];
    _filterDetailView=[[ArpSIDFilterResponseView alloc] initWithFrame:NSMakeRect(8,24,surface.bounds.size.width-16,surface.bounds.size.height-40)];
    _filterDetailView.autoresizingMask=NSViewWidthSizable|NSViewHeightSizable;
    _filterDetailView.accentColor=c64Yellow();
    _filterDetailView.emphasizeScopes=YES;
    _filterDetailView.toolTip=@"Dedicated SID filter page with enlarged response curve, modulation lane, and realtime input/output scope overlay.";
    [surface addSubview:_filterDetailView];
    _filterHUDLabel=[NSTextField labelWithString:@"Filter tab runs a larger live trace with chip-auth response, modulation travel, and filter bus scope overlays."];
    _filterHUDLabel.frame=NSMakeRect(8,8,surface.bounds.size.width-16,10);
    _filterHUDLabel.autoresizingMask=NSViewWidthSizable|NSViewMaxYMargin;
    _filterHUDLabel.font=monoF(7.2f);
    _filterHUDLabel.textColor=[c64Yellow() colorWithAlphaComponent:.76f];
    _filterHUDLabel.lineBreakMode=NSLineBreakByTruncatingTail;
    [surface addSubview:_filterHUDLabel];

    [self _sect:v t:@"◈ CUTOFF / RES / MODE"
         f:NSMakeRect(p,p,colW,bottomH)
       pids:@[@(ArpSID::kParamFilterCutoff),
              @(ArpSID::kParamFilterResonance),
              @(ArpSID::kParamFilterMode),
              @(ArpSID::kParamFilterDrive),
              @(ArpSID::kParamFilterKeyTrack)]];
    [self _sect:v t:@"◈ ENV / MOTION"
         f:NSMakeRect(p*2+colW,p,colW,bottomH)
       pids:@[@(ArpSID::kParamFilterEnvAmount),
              @(ArpSID::kParamFilterLFOAmount),
              @(ArpSID::kParamAttack),
              @(ArpSID::kParamDecay),
              @(ArpSID::kParamSustain),
              @(ArpSID::kParamRelease)]];
    [self _sect:v t:@"◈ CHIP / ANALOG"
         f:NSMakeRect(p*3+colW*2,p,colW,bottomH)
       pids:@[@(ArpSID::kParamSidChipRevision),
              @(ArpSID::kParamSidClockSystem),
              @(ArpSID::kParamSidExternalRcEnable),
              @(ArpSID::kParamSidOversamplingFactor),
              @(ArpSID::kParamSidAdsrBug6581),
              @(ArpSID::kParamForensicFilterOhmic)]];
    return v;}

// ─── MACRO Panel ─────────────────────────────────────────────────────────────
-(NSView*)_macroPanel:(NSRect)r{
    NSView*v=[[NSView alloc]initWithFrame:r];v.wantsLayer=YES;
    const CGFloat p=6,cols=4.f;
    CGFloat mw=(r.size.width-p*(cols+1))/cols,mh=(r.size.height-p*3)/2-p;
    int macroP[8]={(int)ArpSID::kParamMacro1,(int)ArpSID::kParamMacro2,
                   (int)ArpSID::kParamMacro3,(int)ArpSID::kParamMacro4,
                   (int)ArpSID::kParamMacro5,(int)ArpSID::kParamMacro6,
                   (int)ArpSID::kParamMacro7,(int)ArpSID::kParamMacro8};
    for(int i=0;i<8;++i){
        int col=i%4,row2=i/4;
        [self _sect:v t:[NSString stringWithFormat:@"M%d",i+1]
             f:NSMakeRect(p+col*(mw+p),p+(1-row2)*(mh+p),mw,mh)
             pids:@[@(macroP[i])]];}
    CGFloat mmH=(r.size.height-p*3)/2;
    ArpSIDPanel*matrixPanel=[self _sectPanel:v t:@"\u25c8 MOD MATRIX"
         f:NSMakeRect(p,p,r.size.width-p*2,mmH)
         pids:@[@(ArpSID::kParamModVCFCutoffSource),@(ArpSID::kParamModVCFCutoffDepth),
                @(ArpSID::kParamModVCFResonanceSource),@(ArpSID::kParamModVCFResonanceDepth),
                @(ArpSID::kParamModVCO1FreqSource),@(ArpSID::kParamModVCO1FreqDepth),
                @(ArpSID::kParamModVCO1PWSource),@(ArpSID::kParamModVCO1PWDepth),
                @(ArpSID::kParamModVCO2FreqSource),@(ArpSID::kParamModVCO2FreqDepth),
                @(ArpSID::kParamModVCO2PWSource),@(ArpSID::kParamModVCO2PWDepth),
                @(ArpSID::kParamModVCO3FreqSource),@(ArpSID::kParamModVCO3FreqDepth),
                @(ArpSID::kParamModVCO3PWSource),@(ArpSID::kParamModVCO3PWDepth),
                @(ArpSID::kParamModMasterVolumeSource),@(ArpSID::kParamModMasterVolumeDepth)]];
    _matrixHUDLabel=[NSTextField labelWithString:ArpSIDMatrixHUDSummary(NO)];
    _matrixHUDLabel.frame=NSMakeRect(6,2,matrixPanel.bounds.size.width-12,10);
    _matrixHUDLabel.autoresizingMask=NSViewWidthSizable|NSViewMaxYMargin;
    _matrixHUDLabel.font=monoF(7.0f);
    _matrixHUDLabel.textColor=[colLabel() colorWithAlphaComponent:.72f];
    [matrixPanel addSubview:_matrixHUDLabel];
    return v;}



-(void)_hifiApplyEnable:(float)enable quality:(float)quality oversampling:(float)os width:(float)width warmth:(float)warmth tape:(float)tape air:(float)air depth:(float)depth diffuse:(float)diffuse {
    [self _applyRealtimeNormalizedParam:(int)ArpSID::kParamHiFiEnable value:enable defaultCenter:0.0f];
    [self _applyRealtimeNormalizedParam:(int)ArpSID::kParamHiFiQuality value:quality defaultCenter:1.0f];
    [self _applyRealtimeNormalizedParam:(int)ArpSID::kParamHiFiOversampling value:os defaultCenter:0.5f];
    [self _applyRealtimeNormalizedParam:(int)ArpSID::kParamHiFiMasterWidth value:width defaultCenter:0.60f];
    [self _applyRealtimeNormalizedParam:(int)ArpSID::kParamHiFiAnalogWarmth value:warmth defaultCenter:0.68f];
    [self _applyRealtimeNormalizedParam:(int)ArpSID::kParamHiFiTapeSaturation value:tape defaultCenter:0.45f];
    [self _applyRealtimeNormalizedParam:(int)ArpSID::kParamHiFiPsychoExciter value:air defaultCenter:0.82f];
    [self _applyRealtimeNormalizedParam:(int)ArpSID::kParamHiFiStereoDepth value:depth defaultCenter:0.65f];
    [self _applyRealtimeNormalizedParam:(int)ArpSID::kParamHiFiVoiceDiffuser value:diffuse defaultCenter:0.35f];
    _needsDeferredPresetUISync.store(true, std::memory_order_release);
}
-(void)_hifiPresetPureSid:(id)sender{ (void)sender; [self _hifiApplyEnable:0.0f quality:0.0f oversampling:0.0f width:0.50f warmth:0.0f tape:0.0f air:0.0f depth:0.0f diffuse:0.0f]; }
-(BOOL)_pureSid1Q1OutputModeFromAdapter_v229 {
    id adapter=nil;
    if([_au respondsToSelector:@selector(debugAdapter)]) adapter=[_au debugAdapter];
    if(adapter && [adapter respondsToSelector:@selector(pureSid1Q1OutputMode)]) return [(id)adapter pureSid1Q1OutputMode] ? YES : NO;
    return NO;
}
-(void)_setPureSid1Q1OutputMode_v229:(BOOL)enabled {
    id adapter=nil;
    if([_au respondsToSelector:@selector(debugAdapter)]) adapter=[_au debugAdapter];
    if(adapter && [adapter respondsToSelector:@selector(setPureSid1Q1OutputMode:)]) [(id)adapter setPureSid1Q1OutputMode:(enabled ? YES : NO)];
    if(_pureSid1Q1Button_v229_) _pureSid1Q1Button_v229_.state = enabled ? NSControlStateValueOn : NSControlStateValueOff;
    NSString* msg = enabled ? @"PURE 1:1 SID ENGINE OUTPUT — AU POST FX BYPASSED" : @"PURE 1:1 SID ENGINE OUTPUT OFF";
    if(_optionsHUDLabel) ArpSIDSetLabelStringIfNeeded(_optionsHUDLabel, msg);
    else if(_presentationHUDLabel) ArpSIDSetLabelStringIfNeeded(_presentationHUDLabel, msg);
}

-(void)_pureSid1Q1Toggle_v229:(id)sender {
    const BOOL on = ([sender respondsToSelector:@selector(state)] && [(NSButton*)sender state] == NSControlStateValueOn);
    [self _setPureSid1Q1OutputMode_v229:on];
}
