-(NSTextField*)_hifiLabel:(NSString*)text frame:(NSRect)frame fontSize:(CGFloat)fontSize color:(NSColor*)color parent:(NSView*)parent {
    NSTextField* l=[NSTextField labelWithString:(text != nil ? text : @"")];
    l.frame=frame;
    l.autoresizingMask=NSViewWidthSizable|NSViewMinYMargin;
    l.font=monoF(fontSize);
    l.textColor=(color != nil ? color : colLabel());
    l.lineBreakMode=NSLineBreakByWordWrapping;
    [parent addSubview:l];
    return l;
}

-(NSButton*)_hifiPresetButton:(NSString*)title action:(SEL)action frame:(NSRect)frame parent:(NSView*)parent role:(ArpSIDChromeButtonRole)role {
    NSButton* b=[NSButton buttonWithTitle:title target:self action:action];
    b.frame=frame;
    ArpSIDStyleChromeButton(b, role, 7.2f);
    b.toolTip=[NSString stringWithFormat:@"HI-FI SID preset: %@. Writes real AU runtime parameters; no GUI-only mirror.", (title != nil ? title : @"")];
    [parent addSubview:b];
    return b;
}

-(NSView*)_hiFiPanel:(NSRect)r{
    NSView*v=[[NSView alloc]initWithFrame:r]; v.wantsLayer=YES;
    v.layer.backgroundColor=[NSColor colorWithCalibratedRed:0.010 green:0.011 blue:0.016 alpha:1.0].CGColor;
    const CGFloat p=8.f;
    const CGFloat headerH=96.f;
    const CGFloat qualityH=94.f;
    const CGFloat macroH=150.f;
    const CGFloat telemetryH=118.f;
    CGFloat available=MAX(220.0, r.size.height - p*6 - headerH - qualityH - macroH - telemetryH);

    ArpSIDPanel* header=[[ArpSIDPanel alloc] init:NSMakeRect(p,r.size.height-p-headerH,r.size.width-p*2,headerH) t:@"◈ HI-FI TRANSCENDENCE MODE"];
    [v addSubview:header];
    [self _hifiLabel:@"Cycle-accurate SID core with optional oversampled luxury enhancement." frame:NSMakeRect(14,headerH-38,header.bounds.size.width-28,16) fontSize:9.0f color:[c64Cyan() colorWithAlphaComponent:.95f] parent:header];
    [self _hifiLabel:@"Source Authority: SID CORE / REGISTER ENGINE  →  Hi-Fi Enhancement Layer  →  Transcendence Layer" frame:NSMakeRect(14,headerH-58,header.bounds.size.width-28,14) fontSize:7.6f color:[NSColor colorWithCalibratedRed:0.95 green:0.78 blue:0.32 alpha:.92] parent:header];
    [self _hifiLabel:@"RT SAFE ●  NO ALLOC ●  NO LOCKS ●  NO HOST CALLS ●  PREALLOCATED ●  LATENCY OK" frame:NSMakeRect(14,12,header.bounds.size.width-28,16) fontSize:8.1f color:[c64LtGreen() colorWithAlphaComponent:.95f] parent:header];

    NSButton* pure1q1=[NSButton checkboxWithTitle:@"PURE 1:1 AU SID ENGINE OUTPUT" target:self action:@selector(_pureSid1Q1Toggle_v229:)];
    pure1q1.frame=NSMakeRect(14,headerH-82,310,18);
    pure1q1.font=monoF(8.0f);
    pure1q1.toolTip=@"Bypass AU mix FX, reverb, limiter, hard clamp and Hi-Fi/Transcendence. Emits the SID engines' direct float output with only invalid-float cleanup.";
    pure1q1.state=[self _pureSid1Q1OutputModeFromAdapter_v229] ? NSControlStateValueOn : NSControlStateValueOff;
    _pureSid1Q1Button_v229_=pure1q1;
    [header addSubview:pure1q1];

    CGFloat y=r.size.height-p*2-headerH-qualityH;
    ArpSIDPanel* quality=[[ArpSIDPanel alloc] init:NSMakeRect(p,y,r.size.width-p*2,qualityH) t:@"◈ QUALITY ENGINE / OVERSAMPLING"];
    [v addSubview:quality];
    CGFloat qW=(quality.bounds.size.width-32)/3.0;
    [self _sect:quality t:@"MODE: PURE / HI-FI / TRANSCENDENCE" f:NSMakeRect(10,10,qW,qualityH-28)
         pids:@[@(ArpSID::kParamHiFiEnable),@(ArpSID::kParamHiFiQuality)]];
    [self _sect:quality t:@"SUPER-HIRES OVERSAMPLING" f:NSMakeRect(16+qW,10,qW,qualityH-28)
         pids:@[@(ArpSID::kParamHiFiOversampling)]];
    [self _hifiLabel:@"4x ECO  |  8x STUDIO  |  16x INSANE\nInternal luxury chain remains fixed-buffer and bounded. Pure Emulation bypasses enhancement." frame:NSMakeRect(22+qW*2,qualityH-66,qW-10,42) fontSize:7.6f color:[NSColor colorWithCalibratedRed:0.82 green:0.94 blue:1.0 alpha:.82] parent:quality];

    y -= p + macroH;
    ArpSIDPanel* macros=[[ArpSIDPanel alloc] init:NSMakeRect(p,y,r.size.width-p*2,macroH) t:@"◈ TRANSCENDENCE MACROS"];
    [v addSubview:macros];
    const CGFloat mCol=(macros.bounds.size.width-50)/5.0;
    [self _sect:macros t:@"WIDTH / DEPTH" f:NSMakeRect(10,12,mCol,macroH-34)
         pids:@[@(ArpSID::kParamHiFiMasterWidth),@(ArpSID::kParamHiFiStereoDepth)]];
    [self _sect:macros t:@"WARMTH / TAPE" f:NSMakeRect(20+mCol,12,mCol,macroH-34)
         pids:@[@(ArpSID::kParamHiFiAnalogWarmth),@(ArpSID::kParamHiFiTapeSaturation)]];
