static NSTextField* ArpSIDMakeC64OverviewLabel(NSString* initial, NSRect frame, CGFloat fontSize, NSColor* color) {
    NSTextField* label = [NSTextField labelWithString:(initial != nil ? initial : @"")];
    label.frame = frame;
    label.font = monoF(fontSize);
    label.textColor = (color != nil ? color : [c64Cyan() colorWithAlphaComponent:.82f]);
    label.lineBreakMode = NSLineBreakByClipping;
    label.maximumNumberOfLines = 0;
    label.usesSingleLineMode = NO;
    label.autoresizingMask = NSViewWidthSizable | NSViewHeightSizable;
    return label;
}

static NSString* ArpSIDC64BoolLamp(BOOL on) {
    return on ? @"ON" : @"--";
}

static NSString* ArpSIDC64CiaSummary(const ArpSIDTelemetry& tel, int cia) {
    cia = std::clamp(cia, 0, 1);
    const uint8_t irq = cia == 0 ? tel.c64Cia1Irq : tel.c64Cia2Irq;
    const BOOL line = cia == 0 ? tel.c64Cia1IrqLine : tel.c64Cia2IrqLine;
    return [NSString stringWithFormat:
        @"CIA%d TA %04X/%04X %@%@  TB %04X/%04X %@%@  IRQ %02X/%02X %@ E%llu CNT%llu\n"
         "     TOD %02X:%02X:%02X.%X  ALM %02X:%02X:%02X.%X  LAT %@ STOP %@ FLAG %@ SER %u/%@",
        cia + 1,
        (unsigned)tel.c64CiaTimerA[cia], (unsigned)tel.c64CiaLatchA[cia],
        tel.c64CiaTimerAReloadPending[cia] ? @"R" : @"-",
        tel.c64CiaTimerAJustUnderflowed[cia] ? @"U" : @"-",
        (unsigned)tel.c64CiaTimerB[cia], (unsigned)tel.c64CiaLatchB[cia],
        tel.c64CiaTimerBReloadPending[cia] ? @"R" : @"-",
        tel.c64CiaTimerBJustUnderflowed[cia] ? @"U" : @"-",
        (unsigned)irq, (unsigned)tel.c64CiaIrqMask[cia], ArpSIDC64BoolLamp(line),
        (unsigned long long)tel.c64CiaIrqEdges[cia],
        (unsigned long long)tel.c64CiaCntRisingEdges[cia],
        (unsigned)tel.c64CiaTod[cia][3], (unsigned)tel.c64CiaTod[cia][2],
        (unsigned)tel.c64CiaTod[cia][1], (unsigned)(tel.c64CiaTod[cia][0] & 0x0Fu),
        (unsigned)tel.c64CiaTodAlarm[cia][3], (unsigned)tel.c64CiaTodAlarm[cia][2],
        (unsigned)tel.c64CiaTodAlarm[cia][1], (unsigned)(tel.c64CiaTodAlarm[cia][0] & 0x0Fu),
        ArpSIDC64BoolLamp(tel.c64CiaTodLatched[cia]),
        ArpSIDC64BoolLamp(tel.c64CiaTodStopped[cia]),
        ArpSIDC64BoolLamp(tel.c64CiaFlagLatched[cia]),
        (unsigned)tel.c64CiaSerialBitsRemaining[cia],
        tel.c64CiaSerialSelfClock[cia] ? @"SELF" : @"EXT"];
}

static NSString* ArpSIDC64MemoryDumpLine(uint16_t base, const uint8_t* bytes, uint64_t changedMask, int start, int count) {
    NSMutableString* out = [NSMutableString stringWithFormat:@"%04X:", (unsigned)(uint16_t)(base + (uint16_t)start)];
    for (int i = 0; i < count; ++i) {
        const int idx = start + i;
        const BOOL changed = (changedMask & (uint64_t{1} << (unsigned)idx)) != 0;
        [out appendFormat:changed ? @"[%02X]" : @" %02X ", (unsigned)bytes[idx]];
    }
    [out appendString:@"  "];
    for (int i = 0; i < count; ++i) {
        const int idx = start + i;
        const uint8_t c = bytes[idx];
        const BOOL changed = (changedMask & (uint64_t{1} << (unsigned)idx)) != 0;
        if (changed) [out appendString:@"^"];
        else [out appendFormat:@"%c", (c >= 32u && c < 127u) ? (char)c : '.'];
    }
    return out;
}

static NSString* ArpSIDC64MemoryOverviewString(const ArpSIDTelemetry& tel) {
    NSMutableString* out = [NSMutableString stringWithFormat:
        @"REALTIME RAW C64 MEMORY — render-published, read-only, seqlock copied  PHI2:%llu  BLOCK:%llu  HASH:%08X  DIRTY:%02X  CHANGED:%02X\n",
        (unsigned long long)tel.c64Phi2Cycle,
        (unsigned long long)tel.c64BlockIndex,
        (unsigned)tel.c64MemoryCombinedHash,
        (unsigned)(tel.c64MemoryWindowDirtyMask & 0xFFu),
        (unsigned)(tel.c64MemoryWindowChangedMask & 0xFFu)];
    static const char* names[8] = {
        "ZERO PAGE / $0001",
        "STACK",
        "PC PAGE",
        "TEXT SCREEN",
        "BASIC / RAM-UNDER-ROM",
        "VIC / IO",
        "SID LIVE REG MIRROR",
        "COLOR RAM"
    };
    for (int w = 0; w < 8; ++w) {
        const uint8_t first = tel.c64MemoryWindowFirstChangedOffset[w];
        const uint8_t last = tel.c64MemoryWindowLastChangedOffset[w];
        NSString* span = (first == 0xFFu || last == 0xFFu) ? @"--" : [NSString stringWithFormat:@"%02X-%02X", (unsigned)first, (unsigned)last];
        [out appendFormat:@"\n%s  base $%04X  hash %08X  live %@  changed %@  bytes %u  span %@  mask %016llX\n",
            names[w],
            (unsigned)tel.c64MemoryWindowBase[w],
            (unsigned)tel.c64MemoryWindowHash[w],
            (tel.c64MemoryWindowDirtyMask & (1u << w)) ? @"YES" : @"--",
            (tel.c64MemoryWindowChangedMask & (1u << w)) ? @"YES" : @"--",
            (unsigned)tel.c64MemoryWindowChangedBytes[w],
            span,
            (unsigned long long)tel.c64MemoryWindowChangedByteMask[w]];
        for (int row = 0; row < 4; ++row) {
            [out appendString:ArpSIDC64MemoryDumpLine(tel.c64MemoryWindowBase[w], tel.c64MemoryWindow[w], tel.c64MemoryWindowChangedByteMask[w], row * 16, 16)];
            [out appendString:@"\n"];
        }
    }
    return out;
}

static NSString* ArpSIDC64RealtimeScopeString(const float* scope, uint32_t writePos) {
    if (!scope) return @"--------------------------------";
    static const char* glyphs = "._-~=+*#";
    NSMutableString* out = [NSMutableString stringWithCapacity:32];
    for (int i = 0; i < 32; ++i) {
        const uint32_t idx = (writePos + (uint32_t)(i * 4)) & 127u;
        const float v = std::clamp(scope[idx], -1.0f, 1.0f);
        const int g = std::clamp((int)std::lround((v + 1.0f) * 3.5f), 0, 7);
        [out appendFormat:@"%c", glyphs[g]];
    }
    return out;
}

static NSString* ArpSIDC64SidRegsOverviewString(const ArpSIDTelemetry& tel) {
    const uint8_t* r = tel.sidRegs;
    return [NSString stringWithFormat:
        @"SID $D400-$D41D REGISTER MIRROR\n"
         @"$D400: %02X %02X %02X %02X %02X %02X %02X\n"
         @"$D407: %02X %02X %02X %02X %02X %02X %02X\n"
         @"$D40E: %02X %02X %02X %02X %02X %02X %02X\n"
         @"$D415: %02X %02X %02X %02X %02X %02X %02X %02X %02X\n"
         @"LAST WRITE  $D4%02X=%02X  @ PHI2 %llu\nOPEN BUS %02X  DECAY %02X  AGE %llu  HOLD %@  LAST READ %02X\n"
         @"OPENBUS READS  SID %u  COLOR %u  POTXY %u\n"
         @"OPENBUS RT  %@\nSIDBUS   RT  %@\nREG      RT  %@\nVALUE    RT  %@\nWRITE    RT  %@\nPHI2     RT  %@\nIRQ/DMA  RT  %@\nCHIP     RT  %@",
        r[0],r[1],r[2],r[3],r[4],r[5],r[6],
        r[7],r[8],r[9],r[10],r[11],r[12],r[13],
        r[14],r[15],r[16],r[17],r[18],r[19],r[20],
        r[21],r[22],r[23],r[24],r[25],r[26],r[27],r[28],r[29],
        (unsigned)tel.c64LastSidReg, (unsigned)tel.c64LastSidValue,
        (unsigned long long)tel.c64LastSidWriteCycle,
        (unsigned)tel.c64OpenBus, (unsigned)tel.c64OpenBusDecayMask,
        (unsigned long long)tel.c64OpenBusAgePhi2,
        ArpSIDC64BoolLamp(tel.c64OpenBusDrivenWithinPersistence),
        (unsigned)tel.c64LastRead,
        (unsigned)tel.c64SidOpenBusReadCount,
        (unsigned)tel.c64ColorRamOpenBusReadCount,
        (unsigned)tel.c64PotxyOpenBusReadCount,
        ArpSIDC64RealtimeScopeString(tel.c64OpenBusScope, tel.c64BusScopeWritePos),
        ArpSIDC64RealtimeScopeString(tel.c64SidBusScope, tel.c64BusScopeWritePos),
        ArpSIDC64RealtimeScopeString(tel.c64SidRegScope, tel.c64BusScopeWritePos),
        ArpSIDC64RealtimeScopeString(tel.c64SidValueScope, tel.c64BusScopeWritePos),
        ArpSIDC64RealtimeScopeString(tel.c64SidWritePulseScope, tel.c64BusScopeWritePos),
        ArpSIDC64RealtimeScopeString(tel.c64Phi2Scope, tel.c64BusScopeWritePos),
        ArpSIDC64RealtimeScopeString(tel.c64IrqDmaScope, tel.c64BusScopeWritePos),
        ArpSIDC64RealtimeScopeString(tel.c64ChipScope, tel.c64BusScopeWritePos)];
}

static NSString* ArpSIDC64SidTopologyString(const ArpSIDTelemetry& tel) {
    const int count = std::clamp<int>(tel.c64SidChipCount ? tel.c64SidChipCount : 1, 1, 5);
    NSMutableArray<NSString*>* parts = [NSMutableArray arrayWithCapacity:(NSUInteger)count];
    for (int i = 0; i < count; ++i) {
        uint16_t base = tel.c64SidBase[i];
        if (base == 0u && i == 0) base = 0xD400u;
        [parts addObject:[NSString stringWithFormat:@"SID%d:$%04X", i + 1, (unsigned)base]];
    }
    return [NSString stringWithFormat:@"%d chip%@  %@",
            count, count == 1 ? @"" : @"s", [parts componentsJoinedByString:@"  "]];
}

static NSString* ArpSIDC64StateMemoryMapSummaryString(const ArpSIDTelemetry& tel) {
    NSMutableString* out = [NSMutableString stringWithFormat:
        @"PSID MAP  LOAD $%04X  INIT $%04X  PLAY $%04X  SUB %u/%u\n"
         "MEM HASH %08X  DIRTY %02X  CHANGED %02X  BLOCK %llu\n",
        (unsigned)tel.psidLoadAddress,
        (unsigned)tel.psidInitAddress,
        (unsigned)tel.psidPlayAddress,
        (unsigned)tel.psidCurrentSubtune,
        (unsigned)tel.psidSongs,
        (unsigned)tel.c64MemoryCombinedHash,
        (unsigned)(tel.c64MemoryWindowDirtyMask & 0xFFu),
        (unsigned)(tel.c64MemoryWindowChangedMask & 0xFFu),
        (unsigned long long)tel.c64BlockIndex];
    static const char* names[8] = {
        "ZERO", "STACK", "PC", "SCREEN", "BASIC", "IO", "SID", "COLOR"
    };
    for (int w = 0; w < 8; ++w) {
        const uint8_t first = tel.c64MemoryWindowFirstChangedOffset[w];
        const uint8_t last = tel.c64MemoryWindowLastChangedOffset[w];
        NSString* span = (first == 0xFFu || last == 0xFFu)
            ? @"--"
            : [NSString stringWithFormat:@"%02X-%02X", (unsigned)first, (unsigned)last];
        [out appendFormat:@"%s $%04X hash %08X live %@ changed %@ bytes %u span %@\n",
            names[w],
            (unsigned)tel.c64MemoryWindowBase[w],
            (unsigned)tel.c64MemoryWindowHash[w],
            (tel.c64MemoryWindowDirtyMask & (1u << w)) ? @"YES" : @"--",
            (tel.c64MemoryWindowChangedMask & (1u << w)) ? @"YES" : @"--",
            (unsigned)tel.c64MemoryWindowChangedBytes[w],
            span];
    }
    return out;
}

-(NSView*)_c64Panel:(NSRect)r{
    NSView* root=[[NSView alloc] initWithFrame:r];
    root.wantsLayer=YES;
    root.layer.backgroundColor = NSColor.clearColor.CGColor;

    const CGFloat p=ArpSIDUIDynamicPanelInset(r.size.width);
    const CGFloat contentW=std::max<CGFloat>(720.0f, r.size.width - (p * 2.25f));
    const CGFloat contentH=1222.0f;

    NSScrollView* scroll=[[NSScrollView alloc] initWithFrame:root.bounds];
    scroll.autoresizingMask=NSViewWidthSizable|NSViewHeightSizable;
    scroll.hasVerticalScroller=YES;
    scroll.hasHorizontalScroller=NO;
    scroll.borderType=NSNoBorder;
    scroll.drawsBackground=NO;
    scroll.autohidesScrollers=YES;
    scroll.scrollerStyle=NSScrollerStyleOverlay;
    [root addSubview:scroll];

    NSView* v=[[NSView alloc] initWithFrame:NSMakeRect(0,0,contentW,contentH)];
    v.wantsLayer=YES;
    v.layer.backgroundColor = NSColor.clearColor.CGColor;
    scroll.documentView=v;

    CGFloat y=contentH-p;
    const CGFloat topH=150.0f;
    y -= topH;
    ArpSIDPanel* transport=[[ArpSIDPanel alloc] init:NSMakeRect(p,y,contentW-p*2,topH) t:@"◈ COMPLETE C64 SYSTEM OVERVIEW / LIVE RUNTIME AUTHORITY"];
    [v addSubview:transport];
    NSArray<NSDictionary*>* buttons=@[
        @{@"t":@"LOAD .SID", @"a":@"_c64LoadSidFile:"}, @{@"t":@"◄ SUB", @"a":@"_c64PrevSubtune:"}, @{@"t":@"SUB ►", @"a":@"_c64NextSubtune:"},
        @{@"t":@"BOOT", @"a":@"_c64Boot:"}, @{@"t":@"START", @"a":@"_c64Start:"}, @{@"t":@"STOP", @"a":@"_c64Stop:"}, @{@"t":@"RESET", @"a":@"_c64Reset:"},
        @{@"t":@"EJECT", @"a":@"_c64EjectSidFile:"}, @{@"t":@"UNLOAD", @"a":@"_c64UnloadSidFile:"}, @{@"t":@"FORENSIC ON", @"a":@"_sidCoreEnableForensicRealtime:"}, @{@"t":@"REAL 8580", @"a":@"_sidCoreSet8580Realtime:"},
        @{@"t":@"VIC:FAST", @"a":@"_c64ToggleVicFast:"},  // v873: CPU-saving VIC-II fast toggle (now default ON for smooth playback)
        @{@"t":@"6510:FAST", @"a":@"_c64Toggle6510Fast:"}  // v873: 6510 fast toggle (now default ON, audio-neutral)
    ];
    CGFloat x=8.0f;
    CGFloat by=topH-32.0f;
    for(NSDictionary* spec in buttons){
        SEL action=NSSelectorFromString(spec[@"a"]);
        NSButton* btn=[NSButton buttonWithTitle:spec[@"t"] target:self action:action];
        const CGFloat w=ArpSIDChromeButtonSuggestedWidth(spec[@"t"], 7.7f, 54.0f, 18.0f);
        if(x + w > transport.bounds.size.width-8.0f){ x=8.0f; by -= 21.0f; }
        btn.frame=NSMakeRect(x, by, w, 18.0f);
        ArpSIDStyleChromeButton(btn, [spec[@"t"] hasPrefix:@"STOP"] ? ArpSIDChromeButtonRoleDanger : ArpSIDChromeButtonRoleUtility, 7.7f);
        btn.toolTip=ArpSIDDefaultActionTooltip(spec[@"t"], NSStringFromSelector(action));
        if([spec[@"a"] isEqualToString:@"_c64ToggleVicFast:"]){
            _c64VicFastButton=btn;
            btn.toolTip=@"VIC-II fast: skip per-cycle sprite/badline DMA + bus-steal to cut CPU during SID playback (CPU/CIA/SID stay bit-exact). Toggles VIC:ACC ⇄ VIC:FAST.";
        }
        if([spec[@"a"] isEqualToString:@"_c64Toggle6510Fast:"]){
            _c64CpuFastButton=btn;
            btn.toolTip=@"6510 fast: skip the per-PHI2-cycle diagnostics snapshot (CPU/CIA/VIC/SID stay bit-exact; on-screen telemetry goes coarse). Measured ~6% less PHI2 CPU. Toggles 6510:ACC ⇄ 6510:FAST.";
        }
        [transport addSubview:btn]; x += w + 6.0f;
    }
    // v873: the kernel defaults both CPU-saving modes ON (see c64VicFast_/c64CpuFast_),
    // so seed the button-state trackers to match — otherwise the first toggle click
    // would be a no-op and the labels would disagree with the actual render state.
    _c64VicFastOn = YES;
    _c64CpuFastOn = YES;
    NSTextField* c64PlayerInfo=[NSTextField labelWithString:@"C64 SID PLAYER: load PSID/RSID or boot C64/SIDCORE runtime."];
    c64PlayerInfo.frame=NSMakeRect(10,74,transport.bounds.size.width-20,14);
    c64PlayerInfo.autoresizingMask=NSViewWidthSizable|NSViewMinYMargin;
    c64PlayerInfo.font=monoF(8.0f);
    c64PlayerInfo.textColor=[c64LtGreen() colorWithAlphaComponent:.86f];
    [transport addSubview:c64PlayerInfo];
    [_c64PlayerInfoLabels addObject:c64PlayerInfo];
    _c64ExactnessBadge_v683_=[NSTextField labelWithString:@"● STRICT PATH INACTIVE"];
    _c64ExactnessBadge_v683_.frame=NSMakeRect(10,58,transport.bounds.size.width-20,13);
    _c64ExactnessBadge_v683_.font=monoBF(7.8f);
    _c64ExactnessBadge_v683_.textColor=[[self _themeLabel_v552_] colorWithAlphaComponent:.60f];
    [transport addSubview:_c64ExactnessBadge_v683_];
    _c64ExactnessReasons_v683_=[NSTextField labelWithString:@"Downgrades: NONE"];
    _c64ExactnessReasons_v683_.frame=NSMakeRect(10,43,transport.bounds.size.width-20,12);
    _c64ExactnessReasons_v683_.font=monoF(7.0f);
    _c64ExactnessReasons_v683_.lineBreakMode=NSLineBreakByTruncatingMiddle;
    _c64ExactnessReasons_v683_.textColor=[[self _themeValue_v552_] colorWithAlphaComponent:.80f];
    [transport addSubview:_c64ExactnessReasons_v683_];
    _c64ExactnessCounters_v683_=[NSTextField labelWithString:@"SID exactness counters: waiting for runtime"];
    _c64ExactnessCounters_v683_.frame=NSMakeRect(10,28,transport.bounds.size.width-20,12);
    _c64ExactnessCounters_v683_.font=monoF(6.8f);
    _c64ExactnessCounters_v683_.lineBreakMode=NSLineBreakByTruncatingTail;
    _c64ExactnessCounters_v683_.textColor=[c64Yellow() colorWithAlphaComponent:.80f];
    [transport addSubview:_c64ExactnessCounters_v683_];
    _c64DebugStatusLabel=[NSTextField labelWithString:@"C64 DEBUG: one-tab cockpit · live memory is render-published snapshot data, never direct GUI reads from runtime."];
    _c64DebugStatusLabel.frame=NSMakeRect(10,12,transport.bounds.size.width-20,12);
    _c64DebugStatusLabel.autoresizingMask=NSViewWidthSizable|NSViewMinYMargin;
    _c64DebugStatusLabel.font=monoF(7.0f);
    _c64DebugStatusLabel.textColor=[c64Cyan() colorWithAlphaComponent:.78f];
    _c64DebugStatusLabel.lineBreakMode=NSLineBreakByTruncatingTail;
    [transport addSubview:_c64DebugStatusLabel];
    if(_c64DebugStatusLabels) [_c64DebugStatusLabels addObject:_c64DebugStatusLabel];

    y -= p;
    const CGFloat busH=120.0f;
    y -= busH;
    ArpSIDPanel* busPanel=[[ArpSIDPanel alloc] init:NSMakeRect(p,y,contentW-p*2,busH) t:@"◈ SID BUS 3D / OPEN BUS / PHI2 / REALTIME OPEN-BUS SCOPE / CIA LATCH ACTIVITY"];
    [v addSubview:busPanel];
    _c64BusMetalBackdropView=[[ArpSIDSidCoreMetalBackdropView alloc] initWithFrame:NSMakeRect(8,8,busPanel.bounds.size.width-16,busH-30)];
    _c64BusMetalBackdropView.autoresizingMask=NSViewWidthSizable|NSViewHeightSizable;
    [_c64BusMetalBackdropView configureAsC64SidBusSurface];
    _c64BusMetalBackdropView.toolTip=@"Live C64 SID bus, rolling open-bus/SID-bus scope, PHI2, raster, CIA, and forensic activity surface fed only by render-published telemetry.";
    [busPanel addSubview:_c64BusMetalBackdropView];

    y -= p;
    const CGFloat row1H=96.0f;
    const CGFloat leftW=std::floor((contentW - p*3) * 0.50f);
    const CGFloat rightW=contentW - p*3 - leftW;
