-(void)_sidCoreEnableForensicRealtime:(id)sender{
    (void)sender;
    [self _applyRealtimeNormalizedParam:(int)ArpSID::kParamForensicEnable value:1.0f defaultCenter:0.0f];
    [self _applyRealtimeNormalizedParam:(int)ArpSID::kParamForensicIntensity value:1.0f defaultCenter:ArpSID::defaultNormalizedParamValue(ArpSID::kParamForensicIntensity)];
    _needsDeferredPresetUISync.store(true, std::memory_order_release);
}
-(void)_sidCoreSet8580Realtime:(id)sender{
    (void)sender;
    [self _applyRealtimeNormalizedParam:(int)ArpSID::kParamSidChipRevision value:ArpSID::sidChipRevisionIndexToNormalized(3) defaultCenter:ArpSID::sidChipRevisionIndexToNormalized(ArpSID::kSidChipRevisionDefaultIndex)];
    [self _applyRealtimeNormalizedParam:(int)ArpSID::kParamForensicDigifix8580 value:1.0f defaultCenter:0.0f];
    _needsDeferredPresetUISync.store(true, std::memory_order_release);
}

