    ArpSIDPanel* util=[[ArpSIDPanel alloc] init:NSMakeRect(p,p,r.size.width-p*2,utilityH) t:@"◈ LIVE OPTIONS HUD"];
    [v addSubview:util];
    NSArray<NSDictionary*>* buttons=@[
        @{@"t":@"MIDI PREFS", @"a":@"_openMIDIPreferencesFromHUD:"},
        @{@"t":@"LOAD .SID", @"a":@"_c64LoadSidFile:"},
        @{@"t":@"◄",         @"a":@"_c64PrevSubtune:"},
        @{@"t":@"►",         @"a":@"_c64NextSubtune:"},
        @{@"t":@"EJECT",     @"a":@"_c64EjectSidFile:"},
        @{@"t":@"UNLOAD",    @"a":@"_c64UnloadSidFile:"},
        @{@"t":@"BOOTSTRAP",  @"a":@"_c64LoadProjectionBootstrap:"},
        @{@"t":@"C64 BOOT",   @"a":@"_c64Boot:"},
        @{@"t":@"C64 START",  @"a":@"_c64Start:"},
        @{@"t":@"C64 STOP",   @"a":@"_c64Stop:"},
        @{@"t":@"C64 RESET",  @"a":@"_c64Reset:"},
        @{@"t":@"ARM DRSID",  @"a":@"_drumArmDrSid:"},
        @{@"t":@"MPK MAP",    @"a":@"_drumApplyMPKMiniMap:"},
        @{@"t":@"PANIC",      @"a":@"_panic:"}
    ];
    const CGFloat buttonY=29.0f;
    const CGFloat gap=6.0f;
    CGFloat x=8.0f;
    for(NSDictionary* spec in buttons){
        SEL action=NSSelectorFromString(spec[@"a"]);
        NSButton* btn=[NSButton buttonWithTitle:spec[@"t"] target:self action:action];
        const CGFloat buttonW=ArpSIDChromeButtonSuggestedWidth(spec[@"t"], 7.8f, 56.f, 16.f);
        btn.frame=NSMakeRect(x,buttonY,buttonW,18.0f);
        const ArpSIDChromeButtonRole role=[spec[@"t"] isEqualToString:@"PANIC"] ? ArpSIDChromeButtonRoleDanger : ArpSIDChromeButtonRoleUtility;
        ArpSIDStyleChromeButton(btn, role, [spec[@"t"] isEqualToString:@"PANIC"] ? 8.0f : 7.8f);
        btn.toolTip=ArpSIDDefaultActionTooltip(spec[@"t"], NSStringFromSelector(action));
        [util addSubview:btn];
        x += buttonW + gap;
