    _optionsHUDLabel=[NSTextField labelWithString:@"Realtime options telemetry idles here until the audio bridge comes online."];
    _optionsHUDLabel.frame=NSMakeRect(8,8,util.bounds.size.width-16,12);
    _optionsHUDLabel.autoresizingMask=NSViewWidthSizable|NSViewMaxYMargin;
