    optionsPlayerInfo.autoresizingMask=NSViewWidthSizable|NSViewMinYMargin;
    optionsPlayerInfo.font=monoF(7.2f);
    optionsPlayerInfo.textColor=[c64LtGreen() colorWithAlphaComponent:.80f];
    optionsPlayerInfo.lineBreakMode=NSLineBreakByTruncatingTail;
