    [_c64PlayerInfoLabels addObject:optionsPlayerInfo];
    _c64DebugConsoleLabel=[NSTextField labelWithString:@"C64 DEBUG: idle"];
    _c64DebugConsoleLabel.frame=NSMakeRect(8,38,util.bounds.size.width-16,10);
    _c64DebugConsoleLabel.autoresizingMask=NSViewWidthSizable|NSViewMinYMargin;
    _c64DebugConsoleLabel.font=monoF(6.6f);
    _c64DebugConsoleLabel.textColor=[c64Cyan() colorWithAlphaComponent:.72f];
    _c64DebugConsoleLabel.lineBreakMode=NSLineBreakByTruncatingTail;
    [util addSubview:_c64DebugConsoleLabel];
    if(_c64DebugStatusLabels) [_c64DebugStatusLabels addObject:_c64DebugConsoleLabel];
    return v;}

// ─── Bank / Patch File I/O panel ─────────────────────────────────────────────
// NSView does not have viewWithIdentifier: — provide a recursive subview search.
static NSView* arpsidViewWithIdentifier(NSView* root, NSString* ident) {
    if (!root || !ident) return nil;
    for (NSView* sub in root.subviews) {
        if ([sub.identifier isEqualToString:ident]) return sub;
        NSView* found = arpsidViewWithIdentifier(sub, ident);
        if (found) return found;
    }
    return nil;
}

// Set panel allowed file types — uses UTType on macOS 12+, falls back to string array.
static void arpsidSetPanelTypes(NSSavePanel* panel, NSArray<NSString*>* exts) {
    if (!panel || exts.count == 0) return;
#if ARPSID_HAS_UTTYPE
    if (@available(macOS 11.0, *)) {
        NSMutableArray<UTType*>* types=[NSMutableArray arrayWithCapacity:exts.count];
        for(NSString* ext in exts){
            UTType* type=[UTType typeWithFilenameExtension:ext];
            if(type) [types addObject:type];
        }
        if(types.count > 0) { panel.allowedContentTypes = types; return; }
    }
#endif
    // Legacy fallback (macOS < 12 or UTType unavailable)
#pragma clang diagnostic push
#pragma clang diagnostic ignored "-Wdeprecated-declarations"
    panel.allowedFileTypes = exts;
#pragma clang diagnostic pop
}

// ─── v544 SETTINGS PANEL ─────────────────────────────────────────────────────
// TAB_ARCHITECTURE.md §8 — exposes the 7 SettingsPanelModel groups:
// 1. Audio engine selector (BitPerfect / SingleSid3Voice / DualSid6Voice)
// 2. Host tempo sync source (None / HostTempo / MidiClock / Internal)
// 3. MIDI mapping preset (GM / MSSIAH / C64Keyboard / Custom)
// 4. Theme (Dark / Light / C64 Classic / High Contrast)
// 5. Language (en / no / de / fr / jp)
// 6. DrumEngineRouter enable toggle
// 7. Diagnostic dashboard toggle
//
// The panel reads from `_settingsModel_v544_` (an instance member added at
// the bottom of @implementation initialization) and updates it via the
// target/action selectors. The model is then persisted with the rest of
// the AU's project state (separate slice for the persistence wire-up).
-(NSView*)_settingsPanel_v544_:(NSRect)r {
    NSView* v = [[NSView alloc] initWithFrame:r];
    v.wantsLayer = YES;
    v.layer.backgroundColor = NSColor.clearColor.CGColor;

    const CGFloat p = 12.0f;
    const CGFloat sectH = 56.0f;
    const CGFloat sectW = r.size.width - p * 2.0f;
    CGFloat y = r.size.height - p;

    // Build helper as a C++-style closure isn't well-supported across all
    // Apple Clang block-mixing scenarios in ObjC++; inline the dropdown
    // construction per section instead.
    // v551: macro extended with outIvar so rebuilt panels keep iVar refs for
    // live-update after project-state restore.
    // v552: panel tinted with current theme background
    v.layer.backgroundColor = [[self _themeBg_v552_] colorWithAlphaComponent:.10f].CGColor;

    #define ARPSID_SETTINGS_BUILD_SECTION(hdrTitle, dropLabel, dropItems, selectedIdx, actionSel, outIvar) \
        y -= sectH; \
        { \
            NSTextField* hdr = [NSTextField labelWithString:hdrTitle]; \
            hdr.font = monoBF(13.0f); hdr.textColor = [self _themeTitle_v552_]; \
            hdr.frame = NSMakeRect(p, y + 16.0f, sectW, 18.0f); \
            [v addSubview:hdr]; \
            NSTextField* lbl = [NSTextField labelWithString:dropLabel]; \
            lbl.font = monoBF(11.0f); lbl.textColor = [self _themeLabel_v552_]; \
            lbl.frame = NSMakeRect(p + 8.0f, y - 18.0f, 180.0f, 16.0f); \
            [v addSubview:lbl]; \
            NSPopUpButton* pop = [[NSPopUpButton alloc] \
                initWithFrame:NSMakeRect(p + 200.0f, y - 26.0f, sectW - 220.0f, 26.0f) \
                    pullsDown:NO]; \
            NSArray<NSString*>* items = dropItems; \
            for (NSString* itm in items) [pop addItemWithTitle:itm]; \
            const NSInteger sel = selectedIdx; \
            if (sel >= 0 && sel < (NSInteger)items.count) [pop selectItemAtIndex:sel]; \
            pop.target = self; \
            pop.action = actionSel; \
            pop.font = monoBF(11.0f); \
            [v addSubview:pop]; \
            outIvar = pop; \
        }

    // v553: all NSString literals replaced with localizedString_v553 lookups.
    using K = ArpSID::GUI::UIStringKey_v553;

    ARPSID_SETTINGS_BUILD_SECTION(
        [self _localStr_v553_:K::kSectionAudioEngine],
        [self _localStr_v553_:K::kLabelTopologyMode],
        (@[[self _localStr_v553_:K::kEngineItemBitPerfect],
           [self _localStr_v553_:K::kEngineItemSingleSid]]),
        static_cast<NSInteger>(_settingsModel_v544_.audioEngineMode),
        @selector(_settingsAudioEngineModeChanged_v544_:),
        _settingsEnginePopup_v551_);

    // Canonical fixed policies are status rows, not disabled or one-item
    // controls. A control that cannot change state is misleading UX.
    y -= sectH;
    {
        NSTextField* hdr = [NSTextField labelWithString:[self _localStr_v553_:K::kSectionHostSync]];
        hdr.font = monoBF(13.0f); hdr.textColor = [self _themeTitle_v552_];
        hdr.frame = NSMakeRect(p, y + 16.0f, sectW, 18.0f);
        [v addSubview:hdr];
        NSTextField* status = [NSTextField labelWithString:@"● HOST TEMPO — canonical transport authority"];
        status.font = monoBF(11.0f); status.textColor = [c64LtGreen() colorWithAlphaComponent:.88f];
        status.frame = NSMakeRect(p + 8.0f, y - 18.0f, sectW - 16.0f, 18.0f);
        status.toolTip = @"Tempo and transport are read from the host musical context. No inactive alternate clock source is exposed.";
        [v addSubview:status];
    }

    y -= sectH;
    {
        NSTextField* hdr = [NSTextField labelWithString:[self _localStr_v553_:K::kSectionMidiMapping]];
        hdr.font = monoBF(13.0f); hdr.textColor = [self _themeTitle_v552_];
        hdr.frame = NSMakeRect(p, y + 16.0f, sectW, 18.0f);
        [v addSubview:hdr];
        NSTextField* status = [NSTextField labelWithString:@"● GM / MPK MINI — live canonical map"];
        status.font = monoBF(11.0f); status.textColor = [c64Cyan() colorWithAlphaComponent:.88f];
        status.frame = NSMakeRect(p + 8.0f, y - 18.0f, sectW - 16.0f, 18.0f);
        status.toolTip = @"The active GM percussion and MPK Mini mapping is shown as policy status; unavailable mapping presets are not presented as controls.";
        [v addSubview:status];
    }

    ARPSID_SETTINGS_BUILD_SECTION(
        [self _localStr_v553_:K::kSectionTheme],
        [self _localStr_v553_:K::kLabelColorScheme],
        (@[[self _localStr_v553_:K::kThemeItemDark],
           [self _localStr_v553_:K::kThemeItemLight],
           [self _localStr_v553_:K::kThemeItemC64Classic],
           [self _localStr_v553_:K::kThemeItemHighContrast]]),
        static_cast<NSInteger>(_settingsModel_v544_.theme),
        @selector(_settingsThemeChanged_v544_:),
        _settingsThemePopup_v551_);

    // Language items keep their own-language names (proper nouns, not translated).
    ARPSID_SETTINGS_BUILD_SECTION(
        [self _localStr_v553_:K::kSectionLanguage],
        [self _localStr_v553_:K::kLabelPluginLanguage],
        (@[@"English", @"Norsk", @"Deutsch", @"Fran\xc3\xa7" "ais", @"\xe6\x97\xa5\xe6\x9c\xac\xe8\xaa\x9e"]),
        static_cast<NSInteger>(_settingsModel_v544_.language),
        @selector(_settingsLanguageChanged_v544_:),
        _settingsLangPopup_v551_);

    #undef ARPSID_SETTINGS_BUILD_SECTION

    // Section 6 + 7 — compatibility and diagnostic status
    y -= sectH;
    {
        NSTextField* hdr = [NSTextField labelWithString:[self _localStr_v553_:K::kSectionAdvanced]];
        hdr.font = monoBF(13.0f); hdr.textColor = [self _themeTitle_v552_];
        hdr.frame = NSMakeRect(p, y + 16.0f, sectW, 18.0f);
        [v addSubview:hdr];

        NSTextField* routingStatus = [NSTextField labelWithString:@"● CANONICAL DRUM ROUTING — FLAVOR OWNED"];
        routingStatus.font = monoBF(11.0f);
        routingStatus.textColor = [c64LtGreen() colorWithAlphaComponent:.88f];
        routingStatus.frame = NSMakeRect(p + 8.0f, y - 8.0f, sectW - 16.0f, 22.0f);
        routingStatus.toolTip =
            @"MIDI, sequencer, automation, presets, and rendering share the component-flavor routing authority.";
        [v addSubview:routingStatus];

        NSTextField* diagnosticsStatus =
            [NSTextField labelWithString:@"● DIAGNOSTICS — C64 + SIDCORE LIVE TELEMETRY"];
        diagnosticsStatus.font = monoBF(11.0f);
        diagnosticsStatus.textColor = [c64Cyan() colorWithAlphaComponent:.88f];
        diagnosticsStatus.frame = NSMakeRect(p + 8.0f, y - 32.0f, sectW - 16.0f, 22.0f);
        diagnosticsStatus.toolTip =
            @"The duplicate C64 STATE tab was retired. Live playback, bus, scope, and register diagnostics remain on C64 and SIDCORE.";
        [v addSubview:diagnosticsStatus];
        _settingsDashToggle_v551_ = nil;
    }

    // Footer — schema version + status
    {
        char ftBuf[128];
        std::snprintf(ftBuf, sizeof(ftBuf),
                      "Schema v%u  •  Engine: %s  •  Theme: %s  •  Lang: %s",
                      _settingsModel_v544_.schemaVersion,
                      ArpSID::GUI::audioEngineModeName(_settingsModel_v544_.audioEngineMode),
                      ArpSID::GUI::themeName(_settingsModel_v544_.theme),
                      ArpSID::GUI::languageCode(_settingsModel_v544_.language));
        NSTextField* footer = [NSTextField labelWithString:
            [NSString stringWithUTF8String:ftBuf]];
        footer.font = monoBF(10.0f);
        footer.textColor = [[self _themeLabel_v552_] colorWithAlphaComponent:0.85f];
        footer.frame = NSMakeRect(p, 8.0f, sectW, 16.0f);
        [v addSubview:footer];
    }

    return v;
}

// ─── v551: Settings helpers ───────────────────────────────────────────────────

// Push the current _settingsModel_v544_ to the adapter so it survives
// project-state save/restore. Called from every action handler.
-(void)_pushSettingsToAdapter_v551_ {
    id<ArpSIDUIBridgeLike> au = _au;
    if (!au) return;
    id adapter = [au debugAdapter];
    if (adapter && [adapter respondsToSelector:@selector(setSettingsModel:)]) {
        [(id<ArpSIDDebugAdapterLike>)adapter setSettingsModel:&_settingsModel_v544_];
    }
}

// Apply _settingsModel_v544_ to the live control references so a
// project-state restore is visible in the SETTINGS tab immediately.
-(void)_applySettingsModelToSettingsPanel_v551_ {
    auto selectIdx = [](NSPopUpButton* pop, NSInteger idx) {
        if (!pop) return;
        if (idx >= 0 && idx < (NSInteger)pop.numberOfItems) [pop selectItemAtIndex:idx];
    };
    selectIdx(_settingsEnginePopup_v551_,
              static_cast<NSInteger>(_settingsModel_v544_.audioEngineMode));
    selectIdx(_settingsThemePopup_v551_,
              static_cast<NSInteger>(_settingsModel_v544_.theme));
    selectIdx(_settingsLangPopup_v551_,
              static_cast<NSInteger>(_settingsModel_v544_.language));
}

// ─── v552: Theme-aware color accessors ───────────────────────────────────────
// These are NOT statically cached — they are evaluated fresh each call so that
// the panel builders produce the correct colors for the currently selected theme.

-(NSColor*)_themeColor_v552_:(ArpSID::GUI::ThemeColorRGBA_v552)c {
    return [NSColor colorWithSRGBRed:c.r green:c.g blue:c.b alpha:c.a];
}
-(NSColor*)_themeTitle_v552_ {
    return [self _themeColor_v552_:ArpSID::GUI::themePalette_v552(_settingsModel_v544_.theme).title];
}
-(NSColor*)_themeLabel_v552_ {
    return [self _themeColor_v552_:ArpSID::GUI::themePalette_v552(_settingsModel_v544_.theme).label];
}
-(NSColor*)_themeValue_v552_ {
    return [self _themeColor_v552_:ArpSID::GUI::themePalette_v552(_settingsModel_v544_.theme).value];
}
-(NSColor*)_themeAccent_v552_ {
    return [self _themeColor_v552_:ArpSID::GUI::themePalette_v552(_settingsModel_v544_.theme).accent];
}
-(NSColor*)_themeBg_v552_ {
    return [self _themeColor_v552_:ArpSID::GUI::themePalette_v552(_settingsModel_v544_.theme).bg];
}

// ─── v553: Localized string helper ────────────────────────────────────────────
// Returns an NSString from the v553 language string table for the current
// language setting. Avoids NSLocalizedString (which targets the host bundle,
// not the AU component bundle).
-(NSString*)_localStr_v553_:(ArpSID::GUI::UIStringKey_v553)key {
    const char* s = ArpSID::GUI::localizedString_v553(key, _settingsModel_v544_.language);
    return (s && s[0]) ? [NSString stringWithUTF8String:s] : @"";
}

// ─── v552: Theme application ──────────────────────────────────────────────────
// Rebuilds the theme-sensitive SETTINGS panel in place, then re-applies the
// current tab visibility. Safe to call on
// the main thread at any time after the initial panel build.
-(void)_applyTheme_v552_ {
    NSView* root = self.view ? self.view : (_pSettingsV544 ? _pSettingsV544.superview : nil);
    if (!root) return;

    const NSRect cr = _panelContentRect_v552_;
    if (cr.size.width < 8.f || cr.size.height < 8.f) return;

    // Rebuild SETTINGS panel
    if (_pSettingsV544) {
        [_pSettingsV544 removeFromSuperview];
        _pSettingsV544 = nil;
    }
    _pSettingsV544 = [self _settingsPanel_v544_:cr];
    if (_pSettingsV544) ArpSIDFinalizeControlUX(_pSettingsV544);

    // Restore correct tab visibility
    [self _showTab:_tab];
}

// ─── v544 SETTINGS action handlers ───────────────────────────────────────────
// Each handler updates the model + (optionally) wires to the engine.
// Audit-correct: model is the single source of truth; engine reflects model.
-(void)_settingsAudioEngineModeChanged_v544_:(NSPopUpButton*)sender {
    const NSInteger idx = sender.indexOfSelectedItem;
    if (idx < 0 || idx > 1) return;
    _settingsModel_v544_.audioEngineMode =
        static_cast<ArpSID::GUI::AudioEngineMode>(idx);
    // The adapter publishes an atomic request; the render thread applies it
    // at the next block boundary.
    [self _pushSettingsToAdapter_v551_];
}
-(void)_settingsThemeChanged_v544_:(NSPopUpButton*)sender {
    const NSInteger idx = sender.indexOfSelectedItem;
    if (idx < 0 || idx > 3) return;
    _settingsModel_v544_.theme =
        static_cast<ArpSID::GUI::Theme>(idx);
    [self _pushSettingsToAdapter_v551_];
    [self _applyTheme_v552_];  // v552: immediately recolor + rebuild theme-sensitive panels
}
-(void)_settingsLanguageChanged_v544_:(NSPopUpButton*)sender {
    const NSInteger idx = sender.indexOfSelectedItem;
    if (idx < 0 || idx > 4) return;
    _settingsModel_v544_.language =
        static_cast<ArpSID::GUI::Language>(idx);
    [self _pushSettingsToAdapter_v551_];
    [self _applyTheme_v552_];  // v553: panel rebuild also relocalizes all string keys
}
// ─── v581 C64 STATE inspector panel ──────────────────────────────────────────
// TAB_ARCHITECTURE.md §7 — read-only CPU/SID/CIA/memory inspector. This page
// keeps its own labels/scopes instead of borrowing the legacy C64 cockpit iVars,
// so both C64-facing tabs can be built and refreshed independently.
-(NSView*)_c64StatePanel_v544_:(NSRect)r {
    NSView* root = [[NSView alloc] initWithFrame:r];
    root.wantsLayer = YES;
    root.layer.backgroundColor = [[self _themeBg_v552_] colorWithAlphaComponent:.10f].CGColor;

    const CGFloat p = 12.0f;
    const CGFloat contentW = std::max<CGFloat>(720.0f, r.size.width - 18.0f);
    const CGFloat contentH = std::max<CGFloat>(1380.0f, r.size.height - 18.0f);

    NSScrollView* scroll = [[NSScrollView alloc] initWithFrame:root.bounds];
    scroll.autoresizingMask = NSViewWidthSizable | NSViewHeightSizable;
    scroll.hasVerticalScroller = YES;
    scroll.hasHorizontalScroller = NO;
    scroll.borderType = NSNoBorder;
    scroll.drawsBackground = NO;
    scroll.autohidesScrollers = YES;
    scroll.scrollerStyle = NSScrollerStyleOverlay;
    [root addSubview:scroll];

    NSView* v = [[NSView alloc] initWithFrame:NSMakeRect(0, 0, contentW, contentH)];
    v.wantsLayer = YES;
    v.layer.backgroundColor = NSColor.clearColor.CGColor;
    scroll.documentView = v;

    CGFloat y = contentH - p - 32.0f;

    // v553: panel title is localized
    NSTextField* title = [NSTextField labelWithString:
        [self _localStr_v553_:ArpSID::GUI::UIStringKey_v553::kPanelC64StateTitle]];
    title.font = monoBF(13.0f); title.textColor = [self _themeTitle_v552_];
    title.frame = NSMakeRect(p, y + 8.0f, contentW - p * 2.0f - 140.0f, 22.0f);
    [v addSubview:title];

    // v605: RSID exactness badge — visible indicator of current playback mode.
    _rsidExactBadge_v605_ = [NSTextField labelWithString:@"● —"];
    _rsidExactBadge_v605_.font = monoBF(9.5f);
    _rsidExactBadge_v605_.textColor = [[self _themeLabel_v552_] colorWithAlphaComponent:0.55f];
    _rsidExactBadge_v605_.alignment = NSTextAlignmentRight;
    _rsidExactBadge_v605_.frame = NSMakeRect(contentW - p - 270.0f, y + 10.0f, 270.0f, 16.0f);
    _rsidExactBadge_v605_.toolTip = @"RSID strict status: RSID PHI2 CLEAN = strict mode, PHI2 path active, no known downgrade; RSID-PHI2 DOWNGRADE = strict mode, PHI2 path active with ledger downgrades such as HLE ROM, CIA/VIC approximation, SID read approximation, open bus or approximate opcode; blank = no active strict RSID path.";
    [v addSubview:_rsidExactBadge_v605_];

    _rsidExactReasons_v683_ = [NSTextField labelWithString:@"Downgrades: NONE"];
    _rsidExactReasons_v683_.font = monoBF(7.6f);
    _rsidExactReasons_v683_.textColor = [[self _themeValue_v552_] colorWithAlphaComponent:0.80f];
    _rsidExactReasons_v683_.lineBreakMode = NSLineBreakByTruncatingMiddle;
    _rsidExactReasons_v683_.frame = NSMakeRect(p, y - 10.0f, contentW - p * 2.0f, 14.0f);
    [v addSubview:_rsidExactReasons_v683_];

    y -= 34.0f;

    _c64StateInspectorLabels_v581_ = [NSMutableArray arrayWithCapacity:4];

    const CGFloat colGap = 10.0f;
    const CGFloat colW = std::floor((contentW - p * 2.0f - colGap) * 0.5f);
    const CGFloat rightX = p + colW + colGap;
    const CGFloat rowH = 142.0f;

    y -= rowH;
    ArpSIDPanel* cpuPanel = [[ArpSIDPanel alloc] init:NSMakeRect(p, y, colW, rowH) t:@"CPU / CLOCK / PSID MAP"];
    [v addSubview:cpuPanel];
    NSTextField* cpuText = ArpSIDMakeC64OverviewLabel(@"waiting for CPU snapshot",
        NSMakeRect(10, 10, cpuPanel.bounds.size.width - 20, rowH - 28), 7.0f,
        [[self _themeValue_v552_] colorWithAlphaComponent:.90f]);
    [cpuPanel addSubview:cpuText];
    [_c64StateInspectorLabels_v581_ addObject:cpuText];

    ArpSIDPanel* ciaPanel = [[ArpSIDPanel alloc] init:NSMakeRect(rightX, y, colW, rowH) t:@"CIA / IEC / TAPE / ROM"];
    [v addSubview:ciaPanel];
    NSTextField* ciaText = ArpSIDMakeC64OverviewLabel(@"waiting for CIA snapshot",
        NSMakeRect(10, 10, ciaPanel.bounds.size.width - 20, rowH - 28), 7.0f,
        [[self _themeAccent_v552_] colorWithAlphaComponent:.88f]);
    [ciaPanel addSubview:ciaText];
    [_c64StateInspectorLabels_v581_ addObject:ciaText];

    y -= p;
    y -= rowH;
    ArpSIDPanel* sidPanel = [[ArpSIDPanel alloc] init:NSMakeRect(p, y, colW, rowH) t:@"SID REGISTERS / BUS MIRROR"];
    [v addSubview:sidPanel];
    NSTextField* sidText = ArpSIDMakeC64OverviewLabel(@"waiting for SID register mirror",
        NSMakeRect(10, 10, sidPanel.bounds.size.width - 20, rowH - 28), 6.6f,
        [c64Yellow() colorWithAlphaComponent:.86f]);
    [sidPanel addSubview:sidText];
    [_c64StateInspectorLabels_v581_ addObject:sidText];

    ArpSIDPanel* memPanel = [[ArpSIDPanel alloc] init:NSMakeRect(rightX, y, colW, rowH) t:@"MEMORY MAP / WINDOW HASHES"];
    [v addSubview:memPanel];
    NSTextField* memText = ArpSIDMakeC64OverviewLabel(@"waiting for memory map",
        NSMakeRect(10, 10, memPanel.bounds.size.width - 20, rowH - 28), 6.5f,
        [c64LtGreen() colorWithAlphaComponent:.86f]);
    [memPanel addSubview:memText];
    [_c64StateInspectorLabels_v581_ addObject:memText];

    y -= p;
    const CGFloat scopeH = 126.0f;
    y -= scopeH;
    ArpSIDPanel* scopePanel = [[ArpSIDPanel alloc] init:NSMakeRect(p, y, contentW - p * 2.0f, scopeH) t:@"OPEN BUS / SID BUS LIVE SCOPES"];
    [v addSubview:scopePanel];
    const CGFloat scopeW = std::floor((scopePanel.bounds.size.width - 30.0f) * 0.5f);
    NSTextField* openLabel = [NSTextField labelWithString:@"OPEN BUS"];
    openLabel.frame = NSMakeRect(10, scopeH - 26, scopeW, 13);
    openLabel.font = monoBF(7.4f); openLabel.textColor = [self _themeLabel_v552_];
    [scopePanel addSubview:openLabel];
    NSTextField* sidLabel = [NSTextField labelWithString:@"SID WRITE BUS"];
    sidLabel.frame = NSMakeRect(20 + scopeW, scopeH - 26, scopeW, 13);
    sidLabel.font = monoBF(7.4f); sidLabel.textColor = [self _themeLabel_v552_];
    [scopePanel addSubview:sidLabel];
    _c64StateOpenBusScope_v581_ = [[ArpSIDOscilloscopeView alloc] initWithFrame:NSMakeRect(10, 12, scopeW, scopeH - 44)];
    _c64StateOpenBusScope_v581_.accentColor = c64Cyan();
    _c64StateOpenBusScope_v581_.toolTip = @"Render-published C64 open-bus latch scope. Read-only GUI copy, 128 samples.";
    [scopePanel addSubview:_c64StateOpenBusScope_v581_];
    _c64StateSidBusScope_v581_ = [[ArpSIDOscilloscopeView alloc] initWithFrame:NSMakeRect(20 + scopeW, 12, scopeW, scopeH - 44)];
    _c64StateSidBusScope_v581_.accentColor = c64Yellow();
    _c64StateSidBusScope_v581_.toolTip = @"Render-published SID register/write bus scope. Read-only GUI copy, 128 samples.";
    [scopePanel addSubview:_c64StateSidBusScope_v581_];

    // v547 — SIDCORE register-write timeline + per-voice snapshot.
    // The view drains the model's RT-safe MPSC ring on each refresh
    // and renders the most recent N writes + the latest voice snapshot.
    y -= p;
    const CGFloat timelineH = 190.0f;
    y -= timelineH;
    ArpSIDPanel* timelinePanel = [[ArpSIDPanel alloc] init:NSMakeRect(p, y, contentW - p * 2.0f, timelineH) t:@"SIDCORE WRITE TIMELINE / LIVE SNAPSHOT"];
    [v addSubview:timelinePanel];
    _c64StateSidCoreTimelineView_v581_ = [[ArpSIDSidCoreTimelineView_v547 alloc]
        initWithFrame:NSMakeRect(8, 8, timelinePanel.bounds.size.width - 16, timelineH - 32)
                model:&_sidCoreModel_v547_];
    [timelinePanel addSubview:_c64StateSidCoreTimelineView_v581_];

    y -= p;
    const CGFloat diagH = 760.0f;
    y -= diagH;
    ArpSIDPanel* diagPanel = [[ArpSIDPanel alloc] init:NSMakeRect(p, y, contentW - p * 2.0f, diagH) t:@"AUDIT-STABILIZATION COUNTERS"];
    [v addSubview:diagPanel];
    _c64DiagValueLabels_v549_ = [NSMutableArray arrayWithCapacity:55];

    if (!_settingsModel_v544_.diagnosticDashboardEnabled) {
        NSTextField* disabled = ArpSIDMakeC64OverviewLabel(
            @"Diagnostic counter dashboard disabled in SETTINGS / Advanced.",
            NSMakeRect(10, diagH - 54, diagPanel.bounds.size.width - 20, 28),
