        [scroll.contentView scrollToPoint:NSMakePoint(0, std::max<CGFloat>(0, contentH - root.bounds.size.height))];
        [scroll reflectScrolledClipView:scroll.contentView];
        return root;
    }

    // Render a vertical column of counter labels. Each row: name (left) + live value (right).
    // Value labels are stored in _c64DiagValueLabels_v549_ for 60 Hz refresh in _poll.
    // Counter order matches ArpSIDDiagnosticCounterSnapshot field documentation (v549).
    NSArray<NSString*>* counterKeys = @[
        @"Audit #1  renderEpoch",
        @"Audit #2  notifyCallbackViolationCount",
        @"Audit #4  renderDrainTimeoutCount",
        @"Audit P1 splitBrainDiagnosticCount",
        @"Audit #5  scratchUnderCapacityCount (AUv2)",
        @"Audit #25 pendingEventsDrainDroppedCount",
        @"Audit #24 ingressFallbackEdgeOverflowCount",
        @"Audit #33 zeroCycleSampleCount",
        @"Audit #36 outputStageNoiseSampleCount",
        @"Audit #38 filterAbsClampHitCount",
        @"Audit #40 stateRestoreOverlayAuthenticCount (rsv)",
        @"Audit #40 stateRestoreOverlayAnalogCount (rsv)",
        @"Audit #45 invalidClockFrequencyRejectCount",
        @"Audit #49 preNotifyFailureCount",
        @"Audit #50 hostBufferScratchAttachCount",
        @"Audit #51 renderScratchEpoch (AUv3)",
        @"Audit #52 scratchUnderCapacityCount (AUv3)",
        @"Audit #65 c64PsidVideoStandardFallbackCount",
        @"Audit #66 c64PsidRenderHandoffCount",
        @"Audit #46 activityMutex.rtViolations",
        @"Audit #46 stateMutex.rtViolations",
        @"Audit #46 propListenerMutex.rtViolations",
        @"Audit #46 closeWaitMutex.rtViolations",
        @"Audit #39/#74 bridgeDivertedRenderCount",
        @"v311  rsidStrictStatusCode (0=no/1=clean/2=downgraded)",
        @"v302  rsidPlaybackModeCode (0=none/1=strict/2=compatible)",
        @"v302  rsidExactnessDowngradeMask",
        @"v605  rsidExactPlaybackActive legacy alias",
        @"v605  phi2ApproximateOpcodeTotal",
        @"v605  phi2UnsupportedOpcodeTotal",
        @"v683  initBrkSentinelCount",
        @"v683  sidReadApproximationCount",
        @"v683  sidOpenBusReadCount",
        @"v683  invalidSidChipReadCount",
        @"v683  invalidSidChipWriteCount",
        @"v683  sidHoleWriteCount",
        @"v683  rmwSidWriteCount",
        @"v841  c64 callback µs (last)",
        @"v841  c64 callback µs (MAX)",
        @"v841  c64 callback overruns (µs>deadline)",
        @"v841  c64 pre-branch µs (last)",
        @"v841  c64 pre-branch µs (MAX)",
        @"v840  c64 render µs (last)",
        @"v840  c64 render µs (MAX)",
        @"v840  c64 render overruns (µs>deadline)",
        @"v841  c64 post-render µs (last)",
        @"v841  c64 post-render µs (MAX)",
        @"v841  c64 telemetry µs (last)",
        @"v841  c64 telemetry µs (MAX)",
        @"v840  c64 host gap µs (MAX jitter)",
        @"v840  c64 catch-up cycles (MAX aggregate)",
        @"v841  c64 catch-up continuous cycles (MAX)",
        @"v841  c64 catch-up CIA cycles (MAX)",
        @"v841  c64 catch-up VBI cycles (MAX)",
        @"v840  c64 passive debt cycles (last)",
    ];
    CGFloat cy = diagH - 30.0f;
    const CGFloat lineH = 13.0f;
    for (NSString* key in counterKeys) {
        cy -= lineH;
        if (cy < 8.0f) break;
        NSTextField* k = [NSTextField labelWithString:key];
        k.font = monoBF(8.2f); k.textColor = [self _themeLabel_v552_];
        k.frame = NSMakeRect(10.0f, cy, diagPanel.bounds.size.width - 170.0f, 12.0f);
        [diagPanel addSubview:k];

        NSTextField* val = [NSTextField labelWithString:@"—"];
