        val.frame = NSMakeRect(diagPanel.bounds.size.width - 150.0f, cy, 132.0f, 12.0f);
        [diagPanel addSubview:val];
        [_c64DiagValueLabels_v549_ addObject:val];
    }

    [scroll.contentView scrollToPoint:NSMakePoint(0, std::max<CGFloat>(0, contentH - root.bounds.size.height))];
    [scroll reflectScrolledClipView:scroll.contentView];
    return root;
}

// Layout: top row = action buttons (Save Patch, Load Patch, Save Bank, Load Bank,
// Export All, Load Factory), below = 180-slot canonical factory grid grouped by segmented selector; .arpsidbank v1 remains 128 user-bank slots.
// Slot cells show slot number + name; clicking a slot loads it immediately.
// Current slot is highlighted in the accent colour.
-(NSView*)_bankPanel:(NSRect)r{
    NSView*v=[[NSView alloc]initWithFrame:r];
    v.wantsLayer=YES;

    const CGFloat p=8.f;
    const CGFloat buttonH=18.f;
    const CGFloat segmentH=18.f;
    const CGFloat gap=5.f;
    const CGFloat maxRowW=r.size.width-p*2;

    // ── Header label ──────────────────────────────────────────────────────
    _bankHeaderLabel=[NSTextField labelWithString:@"PATCH / BANK  ■  Load & Save  ■  .ARPSID / .ARPSIDBANK / .JSON  ■  MPK CC HUB"];
    _bankHeaderLabel.frame=NSMakeRect(p,r.size.height-p-16,r.size.width-p*2,16);
    _bankHeaderLabel.autoresizingMask=NSViewWidthSizable|NSViewMinYMargin;
    _bankHeaderLabel.font=[NSFont monospacedSystemFontOfSize:11 weight:NSFontWeightBold];
    _bankHeaderLabel.textColor=[NSColor colorWithSRGBRed:.55 green:.85 blue:.55 alpha:1];
    [v addSubview:_bankHeaderLabel];

    // ── Action buttons (wrapped rows) ─────────────────────────────────────
    CGFloat bx=p;
    CGFloat by=r.size.height-p-16-p-buttonH;

    NSArray<NSDictionary*>* btns = @[
        @{@"t":@"Save Patch…",   @"a":@"_bankSavePatch:"},
        @{@"t":@"Load Patch…",   @"a":@"_bankLoadPatch:"},
        @{@"t":@"Save Bank…",    @"a":@"_bankSaveBank:"},
        @{@"t":@"Load Bank…",    @"a":@"_bankLoadBank:"},
        @{@"t":@"Patch JSON…",   @"a":@"_bankSavePatchJSON:"},
        @{@"t":@"Bank JSON…",    @"a":@"_bankSaveBankJSON:"},
        @{@"t":@"Import JSON…",  @"a":@"_bankImportJSON:"},
        @{@"t":@"C64 JSON…",     @"a":@"_bankSaveClassicFactoryJSON:"},
        @{@"t":@"Export All…",   @"a":@"_bankExportAll:"},
        @{@"t":@"Load Factory",  @"a":@"_bankLoadFactory:"},
    ];
    for(NSDictionary*bd in btns){
        SEL action=NSSelectorFromString(bd[@"a"]);
        const CGFloat bw=ArpSIDChromeButtonSuggestedWidth(bd[@"t"], 7.8f, 70.f, 18.f);
        if((bx-p)+bw > maxRowW){
            bx=p;
            by-=buttonH+gap;
        }
        NSButton*b=[NSButton buttonWithTitle:bd[@"t"] target:self action:action];
        b.frame=NSMakeRect(bx,by,bw,buttonH);
        b.tag=-1;
        ArpSIDStyleChromeButton(b, ArpSIDChromeButtonRoleUtility, 7.8f);
        b.toolTip=ArpSIDDefaultActionTooltip(bd[@"t"], NSStringFromSelector(action));
        [v addSubview:b];
        bx+=bw+gap;
    }

    // ── Grouped factory bank selector + quick drum kit strip ─────────────
    const CGFloat selectorY = by-gap-segmentH;
    const CGFloat bankSegW = std::min<CGFloat>(452.f, r.size.width*0.40f);
    _factoryBankSeg=[[ArpSIDSegmentedToolTipControl alloc] initWithFrame:NSMakeRect(p,selectorY,bankSegW,segmentH)];
    _factoryBankSeg.segmentCount=8;
    _factoryBankSeg.segmentStyle=NSSegmentStyleTexturedRounded;
    _factoryBankSeg.trackingMode=NSSegmentSwitchTrackingSelectOne;
    for(NSInteger group=0; group<8; ++group){
        [_factoryBankSeg setLabel:ArpSIDFactoryBankGroupLabel(group) forSegment:group];
    }
    _factoryBankSeg.selectedSegment=0;
    _factoryBankSeg.target=self;
    _factoryBankSeg.action=@selector(_factoryBankChg:);
    _factoryBankSeg.font=monoBF(7.6f);
    _factoryBankSeg.toolTip=@"Grouped factory banks. Jump between authored slot families across the full 180-slot factory grid.";
    _factoryBankSeg.autoresizingMask=NSViewMaxXMargin|NSViewMinYMargin;
    [(ArpSIDSegmentedToolTipControl*)_factoryBankSeg setSegmentToolTips:@[
        ArpSIDFactoryBankGroupTooltip(0), ArpSIDFactoryBankGroupTooltip(1), ArpSIDFactoryBankGroupTooltip(2),
        ArpSIDFactoryBankGroupTooltip(3), ArpSIDFactoryBankGroupTooltip(4), ArpSIDFactoryBankGroupTooltip(5),
        ArpSIDFactoryBankGroupTooltip(6), ArpSIDFactoryBankGroupTooltip(7)
    ]];
    [v addSubview:_factoryBankSeg];

    const CGFloat quickX = NSMaxX(_factoryBankSeg.frame)+gap;
    const CGFloat quickW = std::max<CGFloat>(220.f, r.size.width-p-quickX);
    _drumKitSeg=[[ArpSIDSegmentedToolTipControl alloc] initWithFrame:NSMakeRect(quickX,selectorY,quickW,segmentH)];
    _drumKitSeg.segmentCount=6;
    _drumKitSeg.target=self;
    _drumKitSeg.action=@selector(_drumKitChg:);
    _drumKitSeg.font=monoBF(7.6f);
    _drumKitSeg.autoresizingMask=NSViewWidthSizable|NSViewMinYMargin;
    [self _refreshDrumQuickKitChrome];
    [v addSubview:_drumKitSeg];

    // ── DrSID user-kit library strip (v962) ───────────────────────────────
    // The DrSID panel's USER BANK label promises "switch to BANK for import/
    // export and full library management" — this strip is that UI. Its
    // handlers (_drumUserKitPopChg:/_drumRefreshUserKitLibrary:/
    // _drumExportUserKitBank:/_drumImportUserKitBank:) and the popup's
    // reload/selection logic all existed but were unreachable: _drumUserKitPop
    // was consumed everywhere yet never constructed anywhere.
    const CGFloat userKitY = selectorY-gap-segmentH;
    NSTextField*ukLabel=[NSTextField labelWithString:@"DRSID USER KITS"];
    ukLabel.frame=NSMakeRect(p,userKitY+2.f,108.f,14.f);
    ukLabel.font=monoBF(7.6f);
    ukLabel.textColor=[c64Cyan() colorWithAlphaComponent:.84f];
    ukLabel.autoresizingMask=NSViewMaxXMargin|NSViewMinYMargin;
    [v addSubview:ukLabel];

    const CGFloat ukBtnW=74.f;
    const CGFloat ukPopX=p+108.f+gap;
    const CGFloat ukPopW=std::max<CGFloat>(160.f, r.size.width-p-ukPopX-(ukBtnW+gap)*3.f);
    _drumUserKitPop=[[NSPopUpButton alloc] initWithFrame:NSMakeRect(ukPopX,userKitY,ukPopW,segmentH) pullsDown:NO];
    _drumUserKitPop.target=self;
    _drumUserKitPop.action=@selector(_drumUserKitPopChg:);
    // NSPopUpButton IS an NSButton: keep it out of _bankUpdateSlotHighlight's
    // slot-cell recolor loop (buttons with tag in [0, slotMax] are treated as
    // factory grid cells).
    _drumUserKitPop.tag=-1;
    _drumUserKitPop.font=monoF(8.4f);
    _drumUserKitPop.toolTip=@"Saved DrSID user kits. Selecting a kit loads it into the drum machine immediately. Save kits from the DrSID tab footer.";
    _drumUserKitPop.autoresizingMask=NSViewWidthSizable|NSViewMinYMargin;
    [v addSubview:_drumUserKitPop];

    NSArray<NSDictionary*>* ukBtns=@[
        @{@"t":@"RESCAN",  @"a":@"_drumRefreshUserKitLibrary:"},
        @{@"t":@"KIT EXP", @"a":@"_drumExportUserKitBank:"},
        @{@"t":@"KIT IMP", @"a":@"_drumImportUserKitBank:"},
    ];
    CGFloat ukx=ukPopX+ukPopW+gap;
    for(NSDictionary*bd in ukBtns){
        SEL ukSel=NSSelectorFromString(bd[@"a"]);
        NSButton*b=[NSButton buttonWithTitle:bd[@"t"] target:self action:ukSel];
        b.frame=NSMakeRect(ukx,userKitY,ukBtnW,segmentH);
        b.tag=-1;
        ArpSIDStyleChromeButton(b, ArpSIDChromeButtonRoleUtility, 7.6f);
        b.toolTip=ArpSIDDefaultActionTooltip(bd[@"t"], NSStringFromSelector(ukSel));
        b.autoresizingMask=NSViewMinXMargin|NSViewMinYMargin;
        [v addSubview:b];
        ukx+=ukBtnW+gap;
    }

    // ── Status label ──────────────────────────────────────────────────────
    NSTextField*status=[NSTextField labelWithString:@""];
    status.identifier=@"bankStatus";
    status.frame=NSMakeRect(p,userKitY-gap-14,r.size.width-p*2,14);
    status.font=[NSFont monospacedSystemFontOfSize:9 weight:NSFontWeightLight];
    status.textColor=[NSColor colorWithSRGBRed:.7 green:.7 blue:.7 alpha:.85];
    [v addSubview:status];

    // ── Canonical factory grid: 16 cols × ceil(kFactoryPatchSlotCount/16) ──
    const int cols=16, rows=(ArpSID::kFactoryPatchSlotCount + cols - 1) / cols;
    const CGFloat gridY=p;
    const CGFloat gridTop = userKitY-gap-14-gap;  // v962: below the user-kit strip + status row
    const CGFloat gridH=gridTop-gridY;
    const CGFloat cellW=(r.size.width-p*2)/cols - 2.f;
    const CGFloat cellH=gridH/rows - 2.f;

    for(int slot=0;slot<ArpSID::kFactoryPatchSlotCount;++slot){
        const int col=slot%cols, row=slot/cols;
        const CGFloat cx=p + col*(cellW+2.f);
        const CGFloat cy=gridY + (rows-1-row)*(cellH+2.f);

        // Cell background / button
        NSButton*cell=[NSButton buttonWithTitle:@"" target:self action:@selector(_bankSlotTap:)];
        cell.frame=NSMakeRect(cx,cy,cellW,cellH);
        cell.tag=slot;
        cell.bezelStyle=NSBezelStyleShadowlessSquare;
        cell.wantsLayer=YES;
        cell.layer.cornerRadius=2;
        cell.layer.borderWidth=0.5;
        const NSInteger group=ArpSIDFactoryBankGroupForSlot(slot);
        const NSColor* groupColor=ArpSIDFactoryBankGroupColor(group);
        cell.layer.borderColor=[groupColor colorWithAlphaComponent:.28f].CGColor;
        cell.layer.backgroundColor=[[groupColor blendedColorWithFraction:0.82f ofColor:colPanelDeep()] colorWithAlphaComponent:.28f].CGColor;
        cell.toolTip=[self _bankSlotTooltipForSlot:slot];

        // Slot number (top-left micro label)
        NSTextField*numLbl=[NSTextField labelWithString:[NSString stringWithFormat:@"%d",slot]];
        numLbl.frame=NSMakeRect(2,cellH-9,cellW-4,9);
        numLbl.font=[NSFont monospacedSystemFontOfSize:6 weight:NSFontWeightRegular];
        numLbl.textColor=[groupColor colorWithAlphaComponent:.76f];
        numLbl.alignment=NSTextAlignmentLeft;
        [cell addSubview:numLbl];

        // Patch name (centre)
        NSString* pname=@"";
        if(slot < (int)ArpSID::getFactoryPatchDefinitions().size())
            pname=[NSString stringWithUTF8String:ArpSID::getFactoryPatchDefinitions()[(size_t)slot].displayName.c_str()];
        NSTextField*nameLbl=[NSTextField labelWithString:pname];
        nameLbl.identifier=[NSString stringWithFormat:@"slotName%d",slot];
        nameLbl.frame=NSMakeRect(2,2,cellW-4,cellH-12);
        nameLbl.font=[NSFont monospacedSystemFontOfSize:7 weight:NSFontWeightMedium];
        nameLbl.textColor=[NSColor colorWithSRGBRed:.85 green:.85 blue:.85 alpha:1];
        nameLbl.alignment=NSTextAlignmentCenter;
        nameLbl.lineBreakMode=NSLineBreakByTruncatingTail;
        [cell addSubview:nameLbl];

        [v addSubview:cell];
    }

    [self _bankUpdateSlotHighlight:0 panel:v];
    // v962: populate the user-kit popup from the saved-kit directory now that
    // the strip exists (mirrors the DrSID panel's builder, which reloads too).
    [self _reloadDrumUserKitLibrary];
    return v;
}

// ─── Bank panel actions ───────────────────────────────────────────────────────
-(void)_bankSetStatus:(NSString*)msg panel:(NSView*)panel{
    NSTextField*s=(NSTextField*)arpsidViewWithIdentifier(panel, @"bankStatus");
    if(s) s.stringValue=msg;
}

-(void)_bankUpdateSlotHighlight:(int)activeSlot panel:(NSView*)panel{
    if(!panel) return;
    const NSInteger activeGroup=ArpSIDFactoryBankGroupForSlot(activeSlot);
    [self _syncFactoryBankSegmentForSlot:activeSlot];
    for(NSView*sub in panel.subviews){
        if(![sub isKindOfClass:[NSButton class]]) continue;
        NSButton*b=(NSButton*)sub;
        if(b.tag < 0 || b.tag > ArpSID::kCanonicalFactoryPatchSlotMax) continue;
        const NSInteger group=ArpSIDFactoryBankGroupForSlot(b.tag);
        const NSColor* groupColor=ArpSIDFactoryBankGroupColor(group);
        const BOOL sid808Priority=ArpSIDFactorySlotIsSid808PriorityUI(b.tag);
        NSColor* chromeColor=sid808Priority ? c64Orange() : (NSColor*)groupColor;
        const BOOL isCurrent=(b.tag==activeSlot);
        const BOOL inActiveGroup=(group==activeGroup);
        b.layer.borderWidth = isCurrent ? 1.5f : 0.5f;
        b.layer.borderColor = isCurrent
            ? [chromeColor colorWithAlphaComponent:.96f].CGColor
            : [chromeColor colorWithAlphaComponent:(sid808Priority ? .46f : (inActiveGroup ? .40f : .18f))].CGColor;
        b.layer.backgroundColor = isCurrent
            ? [[chromeColor blendedColorWithFraction:.70f ofColor:c64Black()] colorWithAlphaComponent:.58f].CGColor
            : [[chromeColor blendedColorWithFraction:.86f ofColor:colPanelDeep()] colorWithAlphaComponent:(sid808Priority ? .30f : (inActiveGroup ? .32f : .18f))].CGColor;
        for(NSView* child in b.subviews){
            if(![child isKindOfClass:[NSTextField class]]) continue;
            NSTextField* label=(NSTextField*)child;
            if([label.identifier hasPrefix:@"slotName"]){
                label.textColor=isCurrent
                    ? c64White()
                    : (sid808Priority
                        ? [[c64Yellow() blendedColorWithFraction:.38f ofColor:c64White()] colorWithAlphaComponent:.92f]
                        : [c64White() colorWithAlphaComponent:(inActiveGroup ? .88f : .62f)]);
            } else {
                label.textColor=[chromeColor colorWithAlphaComponent:(isCurrent ? .92f : (sid808Priority ? .82f : (inActiveGroup ? .76f : .48f)))];
            }
        }
    }
}

-(void)_factoryBankChg:(id)sender{
    NSSegmentedControl* seg=(NSSegmentedControl*)sender;
    NSInteger group=std::clamp(seg.selectedSegment, (NSInteger)0, (NSInteger)7);
    NSInteger slot=0;
    if(_au){
        const float bankNorm=ArpSIDUIClamp01([_au getParameterValue:ArpSID::kParamBankSlot]);
        slot=(NSInteger)ArpSID::canonicalFactorySlotFromNormalizedBankSlot(bankNorm);
    }
    const NSRange range=ArpSIDFactoryBankGroupRange(group);
    if(slot < (NSInteger)range.location || slot >= (NSInteger)(range.location + range.length)) slot=(NSInteger)range.location;
    if(!ArpSIDFactorySlotAllowedForFlavor(_componentFlavor, slot)){
        for(NSInteger candidate = (NSInteger)range.location;
            candidate < (NSInteger)(range.location + range.length);
            ++candidate){
            if(ArpSIDFactorySlotAllowedForFlavor(_componentFlavor, candidate)){
                slot = candidate;
                break;
            }
        }
    }
    [self _bankUpdateSlotHighlight:(int)slot panel:_pBank];
    [self _bankSetStatus:[NSString stringWithFormat:@"%@  •  display slots %ld..%ld  •  click a slot to load it",
                          ArpSIDFactoryBankGroupTooltip(group),
                          (long)(range.location + 1),
                          (long)(range.location + range.length)]
                   panel:_pBank];
}

-(void)_bankSlotTap:(id)sender{
    NSButton*b=(NSButton*)sender;
    if(![self _requireBridgeForAction:[NSString stringWithUTF8String:__func__]]) return;
    const int slot=std::clamp((int)b.tag,0,ArpSID::kCanonicalFactoryPatchSlotMax);
    if(!ArpSIDFactorySlotAllowedForFlavor(_componentFlavor, slot)){
        [self _bankSetStatus:[NSString stringWithFormat:@"%@ does not expose slot %d.", ArpSIDComponentFlavorUILabel(_componentFlavor), slot]
                       panel:_pBank];
        NSBeep();
        return;
    }
    [self _releasePendingDrumAuditionNow];
    const NSInteger drumKitIdx=ArpSIDDrumKitIndexForSlot(slot);
    const BOOL applyDrumProfile=(!_hasLoadedBankCache &&
                                 drumKitIdx >= 0 &&
                                 ArpSID::componentFlavorIsDedicatedDrum(_componentFlavor));
    if(_hasLoadedBankCache) [self _applyLoadedBankSlot:slot];
    else if(applyDrumProfile) [self _deferFactoryDrumKitApplyForSlot:slot applyRealtimeProfile:YES];
    else [self _deferPatchSelectionNumber:slot];
    [self _syncDrumKitPopupToBankSlotIfKnown:slot];
    const ArpSIDDrumKitDescriptor* kit=[self _selectedDrumKitDescriptor];
    if(kit && kit->slot == slot && !kit->padNotes.empty()) _selectedDrumMidiNote = kit->padNotes[0];
    [self _refreshDrumKitPresentation];
    [self _bankUpdateSlotHighlight:slot panel:_pBank];
    NSString* source = _hasLoadedBankCache ? @"BANK" : @"FACTORY";
    NSString* title = _hasLoadedBankCache ? [self _loadedBankDisplayNameForSlot:slot]
                                          : [self _factoryDisplayNameForSlot:slot];
    [self _bankSetStatus:[NSString stringWithFormat:@"Loaded %@ slot %d  –  %@",
        source, slot, title]
                   panel:_pBank];
}

-(void)_drumKitChg:(id)sender{
    NSSegmentedControl*seg=(NSSegmentedControl*)sender;
    const NSInteger kitIdx = ArpSIDDrumKitIndexForFlavorSegment(_componentFlavor, seg.selectedSegment);
    const NSInteger slot = ArpSIDDrumKitSlotForFlavorSegment(_componentFlavor, seg.selectedSegment);
    if(slot < 0 || !_au) return;
    [self _releasePendingDrumAuditionNow];
    if(_drumKitPop && kitIdx >= 0 && _drumKitPop.indexOfSelectedItem != kitIdx) {
        [_drumKitPop selectItemAtIndex:kitIdx];
    } else {
        [self _syncDrumKitPopupToBankSlotIfKnown:slot];
    }
    const ArpSIDDrumKitDescriptor* kit=[self _selectedDrumKitDescriptor];
    if(kit && !kit->padNotes.empty()) _selectedDrumMidiNote = kit->padNotes[0];
    [self _refreshDrumKitPresentation];
    [self _deferFactoryDrumKitApplyForSlot:slot applyRealtimeProfile:YES];
    [self _bankUpdateSlotHighlight:(int)slot panel:_pBank];
    [self _bankSetStatus:[NSString stringWithFormat:@"Loaded DrSID kit %ld  –  %s",
                          (long)slot,
                          slot < (NSInteger)ArpSID::getFactoryPatchDefinitions().size()
                              ? ArpSID::getFactoryPatchDefinitions()[(size_t)slot].displayName.c_str() : ""]
                   panel:_pBank];
}

-(void)_bankSavePatchJSON:(id)sender{
    (void)sender;
    if(!_au){ [self _bankSetStatus:@"No AU connected." panel:_pBank]; return; }
    NSSavePanel*sp=[NSSavePanel savePanel];
    arpsidSetPanelTypes(sp, @[@"json"]);
    NSString* suggestedStem = ArpSIDSafeFilenameStem([self _currentPresetDisplayName], @"MyPatch");
    sp.nameFieldStringValue=[suggestedStem stringByAppendingPathExtension:@"json"];
    sp.directoryURL=[NSURL fileURLWithPath:[ArpSIDFileBankBridge defaultUserBankDirectory] isDirectory:YES];
    ArpSIDViewController* __weak ws=self;
    void(^handler)(NSModalResponse)=^(NSModalResponse r){
        ArpSIDViewController*s=ws; if(!s||!s->_au||r!=NSModalResponseOK||!sp.URL) return;
        NSURL* patchURL = [sp.URL copy];
        NSString* patchFileName = [patchURL.lastPathComponent copy];
        NSString* patchStem = [patchURL.URLByDeletingPathExtension.lastPathComponent copy];
        ArpSIDDSPKernelAdapter*adapter=nil;
        if([s->_au respondsToSelector:@selector(kernelAdapter)]) adapter=[s->_au performSelector:@selector(kernelAdapter)];
        ArpSIDFileBankBridge*bridge=[[ArpSIDFileBankBridge alloc]init];
        ArpSIDPatchMetaObj*meta=[bridge metaFromKernel:adapter
                                                  name:patchStem
                                                author:@"User"
                                              category:@""];
        ArpSIDFileBankResult res=[s _savePatchDocumentToURL:patchURL adapter:adapter meta:meta];
        NSString*msg=(res==ArpSIDFileBankResultOK)
            ? [NSString stringWithFormat:@"Saved canonical patch JSON → %@", patchFileName]
            : [NSString stringWithFormat:@"Patch JSON save failed: %@", [ArpSIDFileBankBridge stringForResult:res]];
        dispatch_async(dispatch_get_main_queue(),^{
            ArpSIDViewController* ss = ws; if(!ss) return;
            [ss _bankSetStatus:msg panel:ss->_pBank];
        });
    };
    NSWindow* win=self.view.window ? self.view.window : NSApp.keyWindow;
    if(win) [sp beginSheetModalForWindow:win completionHandler:handler];
    else handler([sp runModal]);
}

-(void)_bankSaveClassicFactoryJSON:(id)sender{
    (void)sender;
    NSSavePanel*sp=[NSSavePanel savePanel];
    arpsidSetPanelTypes(sp, @[@"json"]);
    sp.nameFieldStringValue=@"ArpSID_C64_Classic_Auth_Factory_Bank.json";
    sp.directoryURL=[NSURL fileURLWithPath:[ArpSIDFileBankBridge defaultUserBankDirectory] isDirectory:YES];
    ArpSIDViewController* __weak ws=self;
    void(^handler)(NSModalResponse)=^(NSModalResponse r){
        ArpSIDViewController*s=ws; if(!s||r!=NSModalResponseOK||!sp.URL) return;
        NSURL* bankURL = [sp.URL copy];
        NSString* bankFileName = [bankURL.lastPathComponent copy];
        std::vector<ArpSID::SidStateRootV1> patches; patches.reserve(128);
        std::vector<ArpSID::ArpSIDFilePatchMeta> metas; metas.reserve(128);
        const auto& defs=ArpSID::getFactoryPatchDefinitions();
        for(int slot=0; slot<128; ++slot){
            patches.push_back(ArpSID::makeFactoryPatchStateRootForSlot(slot));
            if((size_t)slot < defs.size()) metas.push_back(ArpSID::ArpSIDFileBank::metaFromDefinition(defs[(size_t)slot]));
            else metas.push_back({});
        }
        const auto err=ArpSIDSaveBankDocumentToURL_v781(bankURL, patches, metas, @"ArpSID C64 Classic Auth Factory Bank");
        NSString*msg=(err==ArpSID::FileBankError::OK)
            ? [NSString stringWithFormat:@"Saved C64 classic factory JSON → %@", bankFileName]
            : [NSString stringWithFormat:@"C64 factory JSON save failed: %s", ArpSID::fileBankErrorString(err)];
        dispatch_async(dispatch_get_main_queue(),^{
            ArpSIDViewController* ss = ws; if(!ss) return;
            [ss _bankSetStatus:msg panel:ss->_pBank];
        });
    };
    NSWindow* win=self.view.window ? self.view.window : NSApp.keyWindow;
    if(win) [sp beginSheetModalForWindow:win completionHandler:handler];
    else handler([sp runModal]);
}

-(void)_bankSaveBankJSON:(id)sender{
    (void)sender;
    if(!_au){ [self _bankSetStatus:@"No AU connected." panel:_pBank]; return; }
    NSSavePanel*sp=[NSSavePanel savePanel];
    arpsidSetPanelTypes(sp, @[@"json"]);
    sp.nameFieldStringValue=@"UserBank.json";
    sp.directoryURL=[NSURL fileURLWithPath:[ArpSIDFileBankBridge defaultUserBankDirectory] isDirectory:YES];
    ArpSIDViewController* __weak ws=self;
    void(^handler)(NSModalResponse)=^(NSModalResponse r){
        ArpSIDViewController*s=ws; if(!s||!s->_au||r!=NSModalResponseOK||!sp.URL) return;
