        NSString* bankFileName = [bankURL.lastPathComponent copy];
        std::vector<ArpSID::SidStateRootV1> patches;
        std::vector<ArpSID::ArpSIDFilePatchMeta> metas;
        [s _collectDisplayedBankRoots:patches metas:metas includeLiveSlot:YES];
        NSString* displayName=s->_loadedBankDisplayName.length ? s->_loadedBankDisplayName : @"Displayed Bank";
        const auto err=ArpSIDSaveBankDocumentToURL_v781(bankURL, patches, metas, displayName);
        NSString*msg=(err==ArpSID::FileBankError::OK)
            ? [NSString stringWithFormat:@"Saved canonical bank JSON → %@", bankFileName]
            : [NSString stringWithFormat:@"Bank JSON save failed: %s", ArpSID::fileBankErrorString(err)];
        dispatch_async(dispatch_get_main_queue(),^{
            ArpSIDViewController* ss = ws; if(!ss) return;
            [ss _bankSetStatus:msg panel:ss->_pBank];
        });
    };
    NSWindow* win=self.view.window ? self.view.window : NSApp.keyWindow;
    if(win) [sp beginSheetModalForWindow:win completionHandler:handler];
    else handler([sp runModal]);
}

-(void)_bankSavePatch:(id)sender{
    (void)sender;
    if(!_au){ [self _bankSetStatus:@"No AU connected." panel:_pBank]; return; }
    NSSavePanel*sp=[NSSavePanel savePanel];
    arpsidSetPanelTypes(sp, @[@"arpsid", @"json"]);
    NSString* suggestedStem = ArpSIDSafeFilenameStem([self _currentPresetDisplayName], @"MyPatch");
    sp.nameFieldStringValue=[suggestedStem stringByAppendingPathExtension:@"arpsid"];
    sp.directoryURL=[NSURL fileURLWithPath:
        [NSString stringWithUTF8String:ArpSID::ArpSIDFileBank::defaultUserBankDirectory().c_str()]
        isDirectory:YES];
    ArpSIDViewController* __weak ws=self;
    void(^handler)(NSModalResponse) = ^(NSModalResponse r){
        ArpSIDViewController*s=ws; if(!s||!s->_au||r!=NSModalResponseOK||!sp.URL) return;
        NSURL* patchURL = [sp.URL copy];
        NSString* patchFileName = [patchURL.lastPathComponent copy];
        NSString* patchStem = [patchURL.URLByDeletingPathExtension.lastPathComponent copy];
        [ArpSIDFileBankBridge ensureDefaultUserBankDirectoryExists];
        ArpSIDDSPKernelAdapter*adapter=nil;
        if([s->_au respondsToSelector:@selector(kernelAdapter)]) adapter=[s->_au performSelector:@selector(kernelAdapter)];
        ArpSIDFileBankBridge*bridge=[[ArpSIDFileBankBridge alloc]init];
        ArpSIDPatchMetaObj*meta=[bridge metaFromKernel:adapter
                                                  name:patchStem
                                                author:@"User"
                                              category:@""];
        ArpSIDFileBankResult res=[s _savePatchDocumentToURL:patchURL adapter:adapter meta:meta];
        NSString*msg=(res==ArpSIDFileBankResultOK)
            ? [NSString stringWithFormat:@"Saved patch → %@", patchFileName]
            : [NSString stringWithFormat:@"Save failed: %@",[ArpSIDFileBankBridge stringForResult:res]];
        dispatch_async(dispatch_get_main_queue(),^{
            ArpSIDViewController* ss = ws; if(!ss) return;
            [ss _bankSetStatus:msg panel:ss->_pBank];
        });
    };
    NSWindow* win = self.view.window ? self.view.window : NSApp.keyWindow;
    if(win) [sp beginSheetModalForWindow:win completionHandler:handler];
    else    handler([sp runModal]);
}

-(void)_bankLoadPatch:(id)sender{
    (void)sender;
    if(!_au){ [self _bankSetStatus:@"No AU connected." panel:_pBank]; return; }
    NSOpenPanel*op=[NSOpenPanel openPanel];
    arpsidSetPanelTypes(op, @[@"arpsid", @"json"]);
    op.directoryURL=[NSURL fileURLWithPath:
        [NSString stringWithUTF8String:ArpSID::ArpSIDFileBank::defaultUserBankDirectory().c_str()]
        isDirectory:YES];
    ArpSIDViewController* __weak ws=self;
    void(^handler)(NSModalResponse) = ^(NSModalResponse r){
        ArpSIDViewController*s=ws; if(!s||!s->_au||r!=NSModalResponseOK||!op.URL) return;
        NSURL* patchURL = [op.URL copy];
        NSString* patchFileName = [patchURL.lastPathComponent copy];
        ArpSIDDSPKernelAdapter*adapter=nil;
        if([s->_au respondsToSelector:@selector(kernelAdapter)]) adapter=[s->_au performSelector:@selector(kernelAdapter)];
        ArpSIDPatchMetaObj* metaOut = nil;
        ArpSIDFileBankResult res=[s _loadPatchDocumentFromURL:patchURL adapter:adapter metaOut:&metaOut];
        NSString* patchName = (metaOut && metaOut.name.length) ? metaOut.name : @"?";
        NSString*msg=(res==ArpSIDFileBankResultOK)
            ? [NSString stringWithFormat:@"Loaded patch ← %@  (%@)",
               patchFileName, patchName]
            : [NSString stringWithFormat:@"Load failed: %@",[ArpSIDFileBankBridge stringForResult:res]];
        dispatch_async(dispatch_get_main_queue(),^{
            if(res==ArpSIDFileBankResultOK){
                [s _markCurrentStateAsExternalPatch];
                s->_loadedDrumUserKitURL=nil;
                [s _refreshDrumUserKitMetaLabel];
            }
            [s _bankSetStatus:msg panel:s->_pBank];
            [s _applyCurrentBridgeStateToKnobs];
        });
    };
    NSWindow* win = self.view.window ? self.view.window : NSApp.keyWindow;
    if(win) [op beginSheetModalForWindow:win completionHandler:handler];
    else    handler([op runModal]);
}

-(void)_bankSaveBank:(id)sender{
    (void)sender;
    if(!_au){ [self _bankSetStatus:@"No AU connected." panel:_pBank]; return; }
    NSSavePanel*sp=[NSSavePanel savePanel];
    arpsidSetPanelTypes(sp, @[@"arpsidbank", @"json"]);
    sp.nameFieldStringValue=@"UserBank.arpsidbank";
    sp.directoryURL=[NSURL fileURLWithPath:
        [NSString stringWithUTF8String:ArpSID::ArpSIDFileBank::defaultUserBankDirectory().c_str()]
        isDirectory:YES];
    ArpSIDViewController* __weak ws=self;
    void(^handler)(NSModalResponse) = ^(NSModalResponse r){
        ArpSIDViewController*s=ws; if(!s||!s->_au||r!=NSModalResponseOK||!sp.URL) return;
        NSURL* bankURL = [sp.URL copy];
        NSString* bankFileName = [bankURL.lastPathComponent copy];
        [ArpSIDFileBankBridge ensureDefaultUserBankDirectoryExists];
        std::vector<ArpSID::SidStateRootV1> patches;
        std::vector<ArpSID::ArpSIDFilePatchMeta> metas;
        [s _collectDisplayedBankRoots:patches metas:metas includeLiveSlot:YES];
        NSString* displayName = s->_loadedBankDisplayName.length ? s->_loadedBankDisplayName : @"Displayed Bank";
        const auto err = ArpSIDSaveBankDocumentToURL_v781(bankURL, patches, metas, displayName);
        NSString*msg=(err==ArpSID::FileBankError::OK)
            ? [NSString stringWithFormat:@"Saved displayed bank → %@%@", bankFileName,
               s->_loadedBankDisplayName.length ? [NSString stringWithFormat:@"  (%@)", s->_loadedBankDisplayName] : @""]
            : [NSString stringWithFormat:@"Save failed: %s", ArpSID::fileBankErrorString(err)];
        dispatch_async(dispatch_get_main_queue(),^{
            ArpSIDViewController* ss = ws; if(!ss) return;
            [ss _bankSetStatus:msg panel:ss->_pBank];
        });
    };
    NSWindow* win = self.view.window ? self.view.window : NSApp.keyWindow;
    if(win) [sp beginSheetModalForWindow:win completionHandler:handler];
    else    handler([sp runModal]);
}

-(void)_bankImportJSON:(id)sender{
    (void)sender;
    if(!_au){ [self _bankSetStatus:@"No AU connected." panel:_pBank]; return; }
    NSOpenPanel*op=[NSOpenPanel openPanel];
    arpsidSetPanelTypes(op, @[@"json"]);
    op.directoryURL=[NSURL fileURLWithPath:[ArpSIDFileBankBridge defaultUserBankDirectory] isDirectory:YES];
    ArpSIDViewController* __weak ws=self;
    void(^handler)(NSModalResponse)=^(NSModalResponse r){
        ArpSIDViewController*s=ws; if(!s||!s->_au||r!=NSModalResponseOK||!op.URL) return;
        NSURL* bankURL = [op.URL copy];
        NSString* bankFileName = [bankURL.lastPathComponent copy];
        [s _bankSetStatus:@"Importing JSON bank…" panel:s->_pBank];
        dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
            std::vector<ArpSID::SidStateRootV1> patches;
            std::vector<ArpSID::ArpSIDFilePatchMeta> metas;
            const auto err=ArpSIDLoadBankDocumentFromURL_v781(bankURL, patches, metas);
            dispatch_async(dispatch_get_main_queue(), ^{
                ArpSIDViewController*ss=ws; if(!ss) return;
                if(err == ArpSID::FileBankError::OK){
                    [ss _cacheLoadedBankPatches:patches metas:metas sourceName:bankFileName];
                    const NSInteger slot=0;
                    [ss _applyLoadedBankSlot:slot];
                    [ss _bankUpdateSlotHighlight:(int)slot panel:ss->_pBank];
                    [ss _applyCurrentBridgeStateToKnobs];
                    [ss _bankSetStatus:[NSString stringWithFormat:@"Imported JSON bank ← %@  (%lu slots, applied slot 0)", bankFileName, (unsigned long)metas.size()] panel:ss->_pBank];
                } else {
                    [ss _bankSetStatus:[NSString stringWithFormat:@"JSON import failed: %s", ArpSID::fileBankErrorString(err)] panel:ss->_pBank];
                }
            });
        });
    };
    NSWindow* win=self.view.window ? self.view.window : NSApp.keyWindow;
    if(win) [op beginSheetModalForWindow:win completionHandler:handler];
    else handler([op runModal]);
}

-(void)_bankLoadBank:(id)sender{
    (void)sender;
    if(!_au){ [self _bankSetStatus:@"No AU connected." panel:_pBank]; return; }
    NSOpenPanel*op=[NSOpenPanel openPanel];
    arpsidSetPanelTypes(op, @[@"arpsidbank", @"json"]);
    op.directoryURL=[NSURL fileURLWithPath:
        [NSString stringWithUTF8String:ArpSID::ArpSIDFileBank::defaultUserBankDirectory().c_str()]
        isDirectory:YES];
    ArpSIDViewController* __weak ws=self;
    void(^handler)(NSModalResponse) = ^(NSModalResponse r){
        ArpSIDViewController*s=ws; if(!s||!s->_au||r!=NSModalResponseOK||!op.URL) return;
        NSURL* bankURL = [op.URL copy];
        NSString* bankPath = [bankURL.path copy];
        NSString* bankFileName = [bankURL.lastPathComponent copy];
        [s _bankSetStatus:@"Loading…" panel:s->_pBank];
        dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
            std::vector<ArpSID::SidStateRootV1> patches;
            std::vector<ArpSID::ArpSIDFilePatchMeta> metas;
            const auto err = ArpSIDPathUsesJSON(bankPath)
                ? ArpSIDLoadBankDocumentFromURL_v781(bankURL, patches, metas)
                : ArpSID::ArpSIDFileBank::loadBankFromFile(bankPath.UTF8String, patches, metas,
                    [ws](int loaded, int total, const char* name){
                        dispatch_async(dispatch_get_main_queue(), ^{
                            ArpSIDViewController*ss=ws; if(!ss) return;
                            NSString* ns = (name && name[0]) ? [NSString stringWithUTF8String:name] : @"";
                            [ss _bankSetStatus:[NSString stringWithFormat:@"Loading %d / %d  %@…", loaded, total, ns] panel:ss->_pBank];
                        });
                    });
            dispatch_async(dispatch_get_main_queue(),^{
                ArpSIDViewController*ss=ws; if(!ss) return;
                if(err == ArpSID::FileBankError::OK){
                    [ss _cacheLoadedBankPatches:patches metas:metas sourceName:bankFileName];
                    const float stickyBankNorm = ss->_au ? [ss->_au getParameterValue:ArpSID::kParamBankSlot] : [ss _cachedParamValue:ArpSID::kParamBankSlot defaultCenter:ArpSID::canonicalNormalizedBankSlotValue(0)];
                    const NSInteger factorySlot = (NSInteger)ArpSID::canonicalFactorySlotFromNormalizedBankSlot(stickyBankNorm);
                    const NSInteger userBankSlot = (factorySlot >= 0 && factorySlot < (NSInteger)ArpSID::kFileBankMaxSlots) ? factorySlot : 0;
                    [ss _applyLoadedBankSlot:userBankSlot];
                    [ss _bankUpdateSlotHighlight:(int)userBankSlot panel:ss->_pBank];
                    [ss _bankSetStatus:[NSString stringWithFormat:@"Loaded bank ← %@  (%lu imported, applied user-bank slot %ld)",
                        bankFileName, (unsigned long)metas.size(), (long)userBankSlot]
                                 panel:ss->_pBank];
                } else {
                    [ss _bankSetStatus:[NSString stringWithFormat:@"Load failed: %s",
                        ArpSID::fileBankErrorString(err)] panel:ss->_pBank];
                }
                [ss _applyCurrentBridgeStateToKnobs];
            });
        });
    };
    NSWindow* win = self.view.window ? self.view.window : NSApp.keyWindow;
    if(win) [op beginSheetModalForWindow:win completionHandler:handler];
    else    handler([op runModal]);
}

-(void)_bankExportAll:(id)sender{
    (void)sender;
    if(!_au){ [self _bankSetStatus:@"No AU connected." panel:_pBank]; return; }
    NSOpenPanel*op=[NSOpenPanel openPanel];
    op.canChooseDirectories=YES; op.canChooseFiles=NO; op.canCreateDirectories=YES;
    op.prompt=@"Export Here";
    op.directoryURL=[NSURL fileURLWithPath:
        [NSString stringWithUTF8String:ArpSID::ArpSIDFileBank::defaultUserBankDirectory().c_str()]
        isDirectory:YES];
    ArpSIDViewController* __weak ws=self;
    void(^handler)(NSModalResponse) = ^(NSModalResponse r){
        ArpSIDViewController*s=ws; if(!s||!s->_au||r!=NSModalResponseOK||!op.URL) return;
        NSURL* exportURL = [op.URL copy];
        NSString* exportPath = [exportURL.path copy];
        NSString* exportDirName = [exportURL.lastPathComponent copy];
        std::vector<ArpSID::SidStateRootV1> patches;
        std::vector<ArpSID::ArpSIDFilePatchMeta> metas;
        [s _collectDisplayedBankRoots:patches metas:metas includeLiveSlot:YES];
        const auto err = ArpSID::ArpSIDFileBank::exportAllToDirectory(exportPath.UTF8String, patches, metas);
        NSString*msg=(err==ArpSID::FileBankError::OK)
            ? [NSString stringWithFormat:@"Exported displayed bank as individual patches → %@", exportDirName]
            : [NSString stringWithFormat:@"Export failed: %s", ArpSID::fileBankErrorString(err)];
        dispatch_async(dispatch_get_main_queue(),^{
            ArpSIDViewController* ss = ws; if(!ss) return;
