        });
    };
    NSWindow* win = self.view.window ? self.view.window : NSApp.keyWindow;
    if(win) [op beginSheetModalForWindow:win completionHandler:handler];
    else    handler([op runModal]);
}

-(void)_bankLoadFactory:(id)sender{
    (void)sender;
    if(!_au){ [self _bankSetStatus:@"No AU connected." panel:_pBank]; return; }
    ArpSIDFileBankBridge*bridge=[[ArpSIDFileBankBridge alloc]init];
    const int slot=ArpSID::canonicalFactorySlotFromNormalizedBankSlot([_au getParameterValue:ArpSID::kParamBankSlot]);
    if(!ArpSIDFactorySlotAllowedForFlavor(_componentFlavor, slot)){
        [self _bankSetStatus:[NSString stringWithFormat:@"%@ cannot restore slot %d in this module.", ArpSIDComponentFlavorUILabel(_componentFlavor), slot]
                       panel:_pBank];
        NSBeep();
        return;
    }
    ArpSIDDSPKernelAdapter*adapter=nil;
    if([_au respondsToSelector:@selector(kernelAdapter)]) adapter=[_au performSelector:@selector(kernelAdapter)];
    const BOOL ok=[bridge applyFactorySlot:slot adapter:adapter];
    if(ok){
        [self _clearLoadedBankCache];
        _loadedDrumUserKitURL=nil;
        [self _refreshDrumUserKitMetaLabel];
    }
    NSString*name=(slot<(int)ArpSID::getFactoryPatchDefinitions().size())
        ? [NSString stringWithUTF8String:ArpSID::getFactoryPatchDefinitions()[(size_t)slot].displayName.c_str()] : @"?";
    NSString*msg=ok
        ? [NSString stringWithFormat:@"Restored factory patch for slot %d  –  %@",slot,name]
        : [NSString stringWithFormat:@"Factory restore failed for slot %d",slot];
    [self _bankSetStatus:msg panel:_pBank];
    [self _bankUpdateSlotHighlight:slot panel:_pBank];
    [self _applyCurrentBridgeStateToKnobs];
}

// ─── Tab switching ────────────────────────────────────────────────────────────
-(BOOL)_effectiveArpAuthorityEnabledForModeIndex:(NSInteger)modeIndex{
    // v933: GUI presentation must mirror the same effective authority law as
    // render/MIDI routing. A stale cached ArpEnable bit is only visible as ARP
    // authority in CLASSIC/BitPerfect mode; SynthMode/SID REG, DrSID and Pure
    // Instrument all suppress ARP as a competing note authority.
    if(_componentFlavor == ArpSID::ComponentFlavor::Instrument) return NO;
    if(ArpSID::componentFlavorIsDedicatedDrum(_componentFlavor)) return NO;
    if(modeIndex != 0) return NO;
    return [self _cachedParamValue:ArpSID::kParamArpEnable defaultCenter:0.0f] > 0.5f;
}

-(BOOL)_effectiveSeqAuthorityEnabledForModeIndex:(NSInteger)modeIndex{
    // v949: GUI mirrors DSP law. SEQ is valid as the melodic Classic/
    // BitPerfect sequencer and as the DrSID/SID808 drum-pattern transport.
    // SynthMode/SID REG and Pure Instrument suppress SEQ authority.
    if(_componentFlavor == ArpSID::ComponentFlavor::Instrument) return NO;
    if(modeIndex == 0 || modeIndex == 2)
        return [self _cachedParamValue:ArpSID::kParamSeqEnable defaultCenter:0.0f] > 0.5f;
    return NO;
}

-(void)_selectModePreferredTab:(NSInteger)modeIndex{
    NSInteger idx = MAX(0, MIN(2, modeIndex));
    ArpSIDTab target = ArpSIDTabMain;
    switch (idx) {
        case 1: target = ArpSIDTabSidReg; break;
        case 2: target = ArpSIDTabSeq; break;
        default:
            if(ArpSID::componentFlavorIsDedicatedDrum(_componentFlavor)) target = ArpSIDTabSeq;
            else if([self _effectiveArpAuthorityEnabledForModeIndex:idx]) target = ArpSIDTabLfoArp;
            else target = ArpSIDTabMain;
            break;
    }
    target = ArpSIDCanonicalVisibleTabForFlavor(_componentFlavor, target);
    if(_tab != target) [self _showTab:target];
}

-(void)_syncPatchAndModePresentation{
    id<ArpSIDUIBridgeLike> au=_au;
    if(!au) return;
    const NSInteger modeIndex = [self _effectiveModeIndexFromTelemetry:nullptr];

    // Preset presentation is read from sticky AU authority.
    // Preset presentation must be read from sticky AU authority, not the local
    // parameter cache.
    const float bankNorm = [au getParameterValue:ArpSID::kParamBankSlot];
    const float voiceModeNorm = [self _cachedParamValue:ArpSID::kParamVoiceMode defaultCenter:0.0f];
    const float arpEnableNorm = [self _effectiveArpAuthorityEnabledForModeIndex:modeIndex] ? 1.0f : 0.0f;
    const float seqEnableNorm = [self _effectiveSeqAuthorityEnabledForModeIndex:modeIndex] ? 1.0f : 0.0f;
    const float chipRevisionNorm = [self _cachedParamValue:ArpSID::kParamSidChipRevision defaultCenter:ArpSID::sidChipRevisionIndexToNormalized(ArpSID::kSidChipRevisionDefaultIndex)];
    const float arpPatternNorm = [self _cachedParamValue:ArpSID::kParamArpPatternLength defaultCenter:0.0f];
    const float seqTempoNorm = [self _cachedParamValue:ArpSID::kParamSeqTempo defaultCenter:0.0f];
    const NSInteger bankSlot = (NSInteger)ArpSID::canonicalFactorySlotFromNormalizedBankSlot(bankNorm);
    const NSInteger program = bankSlot;
    const NSInteger voiceMode = MAX(0, MIN(3, (NSInteger)lround(voiceModeNorm * 3.0f)));
    const BOOL synthOn = (modeIndex == 1);
    const BOOL drSidOn = (modeIndex == 2);
    const BOOL arpOn = arpEnableNorm > 0.5f;
    const BOOL seqOn = seqEnableNorm > 0.5f;
    const BOOL model8580 = !ArpSID::sidChipRevisionSelectorIs6581(chipRevisionNorm);
    const int arpSteps = MAX(1, MIN(32, (int)lround(arpPatternNorm * 31.0f) + 1));
    const BOOL arpFollowHost = [self _cachedParamValue:ArpSID::kParamArpRate defaultCenter:ArpSID::defaultNormalizedParamValue(ArpSID::kParamArpRate)] <= 0.005f;
    const BOOL seqFollowHost = seqTempoNorm <= 0.005f;
    const double seqTempo = ArpSIDSeqTempoBpmForNorm(seqTempoNorm);
    NSString* presetName = [self _currentPresetDisplayName];
    NSString* slotText = ArpSIDPatchSlotString((int)bankSlot, (int)bankSlot);
    const float arpSwing = [self _cachedParamValue:ArpSID::kParamArpSwing defaultCenter:0.0f];
    const float seqSwing = [self _cachedParamValue:ArpSID::kParamSeqSwing defaultCenter:0.0f];
    NSString* line = [NSString stringWithFormat:@"%@  ·  %@  ·  %@  ·  %@  ·  %@  %@%@%@%@%@",
                      ArpSIDRenderModeString((int)modeIndex),
                      slotText,
                      presetName.length ? presetName : @"Live",
                      model8580 ? @"MOS 8580" : @"MOS 6581",
                      ArpSIDVoiceModeString((int)voiceMode),
                      synthOn ? @"Synth " : @"",
                      drSidOn ? @"DrSID " : @"",
                      arpOn ? [NSString stringWithFormat:@"ARP%02d %@ %@ ", arpSteps, ArpSIDPercentNormString(arpSwing), ArpSIDTempoSyncShortString(arpFollowHost)] : @"",
                      seqOn ? [NSString stringWithFormat:@"SEQ %.1f %@ %@ ", seqTempo, ArpSIDPercentNormString(seqSwing), ArpSIDTempoSyncShortString(seqFollowHost)] : @"",
                      (!arpOn && !seqOn) ? @"LIVE" : @""];
    [self updatePresentationContext:line];

    if(_lastObservedModeIndex != modeIndex){
        _lastObservedModeIndex = modeIndex;
        if(_modePop && _modePop.indexOfSelectedItem != modeIndex) [_modePop selectItemAtIndex:modeIndex];
    }
    if(_playModeSeg && _playModeSeg.selectedSegment != voiceMode) _playModeSeg.selectedSegment = voiceMode;
    if(_lastObservedProgram != program || _lastObservedBankSlot != bankSlot){
        _lastObservedProgram = program;
        _lastObservedBankSlot = bankSlot;
        [self _syncPresetAndSlotSelectionWithProgram:program bankSlot:bankSlot presetName:presetName];
    }
}


-(void)_performC64ControlHubCommand:(NSInteger)command label:(NSString*)label{
    if(![self _requireBridgeForAction:[NSString stringWithUTF8String:__func__]]) return;
    if([_au respondsToSelector:@selector(performC64ControlHubCommand:)]){
        [(id)_au performC64ControlHubCommand:command];
        if(_optionsHUDLabel){
            ArpSIDSetLabelStringIfNeeded(_optionsHUDLabel, [NSString stringWithFormat:@"C64 CONTROL HUB: %@ dispatched to realtime SIDCORE/C64 bus runtime", (label != nil ? label : @"command")]);
            ArpSIDSetLabelColorIfNeeded(_optionsHUDLabel, [c64LtGreen() colorWithAlphaComponent:.86f]);
        }
    } else {
        NSBeep();
    }
}
