        (unsigned long long)tel.psidCiaRunGeneration, (unsigned long long)tel.psidCiaServiceGeneration,
        (unsigned)tel.psidCiaIdleLoopAddress,
        ArpSIDC64BoolLamp(tel.c64ExternalKernalRom), ArpSIDC64BoolLamp(tel.c64ExternalBasicRom), ArpSIDC64BoolLamp(tel.c64ExternalCharacterRom), ArpSIDC64BoolLamp(tel.c64ExternalCompleteRomSet),
        tel.psidAuthor[0] ? [NSString stringWithUTF8String:tel.psidAuthor] : @"-",
        tel.psidReleased[0] ? [NSString stringWithUTF8String:tel.psidReleased] : @"-"];
    if(_c64CiaIoText) ArpSIDSetLabelStringIfNeeded(_c64CiaIoText, cia);

    if(_c64SidRegsText) ArpSIDSetLabelStringIfNeeded(_c64SidRegsText, ArpSIDC64SidRegsOverviewString(tel));

    NSString* d0 = ArpSIDDisasmLineString(@"PC", tel.c64DisasmPc[0], tel.c64DisasmLine[0], YES);
    NSString* d1 = ArpSIDDisasmLineString(@"+1", tel.c64DisasmPc[1], tel.c64DisasmLine[1], NO);
    NSString* d2 = ArpSIDDisasmLineString(@"+2", tel.c64DisasmPc[2], tel.c64DisasmLine[2], NO);
    NSString* dis=[NSString stringWithFormat:
        @"%@\n%@\n%@\nCALL/RET SURFACE  %04X %04X %04X %04X %04X %04X %04X %04X",
        d0, d1, d2,
        (unsigned)tel.c64DisasmCallStack[0], (unsigned)tel.c64DisasmCallStack[1], (unsigned)tel.c64DisasmCallStack[2], (unsigned)tel.c64DisasmCallStack[3],
        (unsigned)tel.c64DisasmCallStack[4], (unsigned)tel.c64DisasmCallStack[5], (unsigned)tel.c64DisasmCallStack[6], (unsigned)tel.c64DisasmCallStack[7]];
    if(_c64DisasmStateText) ArpSIDSetLabelStringIfNeeded(_c64DisasmStateText, dis);

    if(_c64MemoryText) ArpSIDSetLabelStringIfNeeded(_c64MemoryText, ArpSIDC64MemoryOverviewString(tel));
    [self _ingestC64DebugEventsFromTelemetry:tel];
}

-(void)_updateC64StateInspector_v581_:(const ArpSIDTelemetry&)tel{
    if(_c64StateInspectorLabels_v581_.count >= 4){
        const float chipRevisionNorm=[self _cachedParamValue:ArpSID::kParamSidChipRevision defaultCenter:ArpSID::sidChipRevisionIndexToNormalized(ArpSID::kSidChipRevisionDefaultIndex)];
        NSString* uiModel=[NSString stringWithUTF8String:ArpSID::sidChipRevisionSelectorLabel(chipRevisionNorm)];
        NSString* model=ArpSIDTelemetrySidModelLabel(tel, uiModel);
        const NSString* clock=ArpSIDSidClockLabel(tel.c64Pal == false);
        NSString* title = tel.psidTitle[0] ? [NSString stringWithUTF8String:tel.psidTitle] : @"NO PSID";
        NSString* cpu=[NSString stringWithFormat:
            @"%@  %@  PLATFORM %@  RUN %@  BOOT %@  JAM %@\n"
             "PHI2 %-12llu  BLOCK %-8llu  PLAY %-5u  RATE %.2f Hz  GATE %@\n"
             "CPU PC:$%04X  A:%02X X:%02X Y:%02X SP:%02X P:%02X  IRQ %@  NMI %@\n"
             "OPENBUS $%02X mask $%02X age %llu hold %@ obs S/C/P %u/%u/%u\n"
             "SID MODEL %@  CLOCK %@  VOICE %@  PSID %@",
            title,
            tel.c64Pal ? @"PAL" : @"NTSC",
            ArpSIDC64AuthorityLabel(tel),
            ArpSIDC64BoolLamp(tel.c64RealtimeRunning),
            ArpSIDC64BoolLamp(tel.c64Booted),
            ArpSIDC64BoolLamp(tel.c64CpuJammed),
            (unsigned long long)tel.c64Phi2Cycle,
            (unsigned long long)tel.c64BlockIndex,
            (unsigned)tel.c64PlayCalls,
            (double)tel.c64PlayRateHz,
            ArpSIDC64BoolLamp(!tel.c64HeavyTelemetryDemandGated),
            (unsigned)tel.c64CpuPc, (unsigned)tel.c64CpuA, (unsigned)tel.c64CpuX,
            (unsigned)tel.c64CpuY, (unsigned)tel.c64CpuSp, (unsigned)tel.c64CpuStatus,
            ArpSIDC64BoolLamp(tel.c64IrqLine), ArpSIDC64BoolLamp(tel.c64NmiLine),
            (unsigned)tel.c64OpenBus,
            (unsigned)tel.c64OpenBusDecayMask,
            (unsigned long long)tel.c64OpenBusAgePhi2,
            ArpSIDC64BoolLamp(tel.c64OpenBusDrivenWithinPersistence),
            (unsigned)tel.c64SidOpenBusReadCount,
            (unsigned)tel.c64ColorRamOpenBusReadCount,
            (unsigned)tel.c64PotxyOpenBusReadCount,
            model, clock, ArpSIDVoiceModeString(tel.voiceMode), ArpSIDC64SidTopologyString(tel)];
        ArpSIDSetLabelStringIfNeeded(_c64StateInspectorLabels_v581_[0], cpu);

        NSString* cia=[NSString stringWithFormat:
            @"VIC RASTER %03u CYCLE %02u FRAME %llu IRQ %@ BA %@ AEC %@ BAD %@ DMA %@ SPM %02X BANK %u FETCH %04X/%04X\n"
             "%@\n%@\n"
             "IEC ATN %@ CLK %@ DATA %@ SRQ %@   TAPE MTR %@ SNS %@ WR %@ RD %@ PULSES %llu\n"
             "ROM KERNAL %@ BASIC %@ CHARGEN %@ SET %@  CRC K:%08X B:%08X C:%08X",
            (unsigned)tel.c64VicRaster, (unsigned)tel.c64VicCycle, (unsigned long long)tel.c64VicFrame,
            ArpSIDC64BoolLamp(tel.c64VicIrq),
            ArpSIDC64BoolLamp(tel.c64VicBa), ArpSIDC64BoolLamp(tel.c64VicAec),
            ArpSIDC64BoolLamp(tel.c64VicBadline), ArpSIDC64BoolLamp(tel.c64VicSpriteDma),
            (unsigned)tel.c64VicActiveSpriteMask, (unsigned)tel.c64VicMemoryBank,
            (unsigned)tel.c64VicFetchBase, (unsigned)tel.c64VicLastFetchAddress,
            ArpSIDC64CiaSummary(tel, 0), ArpSIDC64CiaSummary(tel, 1),
            ArpSIDC64BoolLamp(tel.c64IecAtn), ArpSIDC64BoolLamp(tel.c64IecClk),
            ArpSIDC64BoolLamp(tel.c64IecData), ArpSIDC64BoolLamp(tel.c64IecSrq),
            ArpSIDC64BoolLamp(tel.c64TapeMotor), ArpSIDC64BoolLamp(tel.c64TapeSense),
            ArpSIDC64BoolLamp(tel.c64TapeWrite), ArpSIDC64BoolLamp(tel.c64TapeRead),
            (unsigned long long)tel.c64TapePulseCount,
            ArpSIDC64BoolLamp(tel.c64ExternalKernalRom), ArpSIDC64BoolLamp(tel.c64ExternalBasicRom),
            ArpSIDC64BoolLamp(tel.c64ExternalCharacterRom), ArpSIDC64BoolLamp(tel.c64ExternalCompleteRomSet),
            (unsigned)tel.c64KernalRomChecksum, (unsigned)tel.c64BasicRomChecksum,
            (unsigned)tel.c64CharacterRomChecksum];
        ArpSIDSetLabelStringIfNeeded(_c64StateInspectorLabels_v581_[1], cia);
        ArpSIDSetLabelStringIfNeeded(_c64StateInspectorLabels_v581_[2], ArpSIDC64SidRegsOverviewString(tel));
        ArpSIDSetLabelStringIfNeeded(_c64StateInspectorLabels_v581_[3], ArpSIDC64StateMemoryMapSummaryString(tel));
    }

    float busHeat = 0.0f;
    for(int i = 0; i < 128; ++i) {
        busHeat = std::max(busHeat, std::fabs(ArpSIDUIClampSigned(tel.c64OpenBusScope[i])));
        busHeat = std::max(busHeat, std::fabs(ArpSIDUIClampSigned(tel.c64SidBusScope[i])));
        busHeat = std::max(busHeat, std::fabs(ArpSIDUIClampSigned(tel.c64SidWritePulseScope[i])));
        busHeat = std::max(busHeat, std::fabs(ArpSIDUIClampSigned(tel.c64IrqDmaScope[i])));
    }
    const float activity = ArpSIDUIClamp01(busHeat * 0.70f + ArpSIDUIClamp01(tel.forensicActivity) * 0.30f);
    if(_c64StateOpenBusScope_v581_){
        _c64StateOpenBusScope_v581_.forensicActivity = activity;
        _c64StateOpenBusScope_v581_.accentColor = [c64Cyan() blendedColorWithFraction:(CGFloat)(0.15 + 0.65 * activity) ofColor:c64White()];
        [_c64StateOpenBusScope_v581_ updateWithSamples:tel.c64OpenBusScope count:128];
    }
    if(_c64StateSidBusScope_v581_){
        _c64StateSidBusScope_v581_.forensicActivity = activity;
        _c64StateSidBusScope_v581_.accentColor = [c64Yellow() blendedColorWithFraction:(CGFloat)(0.10 + 0.70 * activity) ofColor:c64White()];
        [_c64StateSidBusScope_v581_ updateWithSamples:tel.c64SidBusScope count:128];
    }
}

-(void)_updateC64PlayerInfoWithTelemetry:(const ArpSIDTelemetry&)tel{
    if(_c64PlayerInfoLabels.count == 0) return;
    NSString* title = tel.psidTitle[0] ? [NSString stringWithUTF8String:tel.psidTitle] : @"No .sid file loaded — click ▶ Load .sid… to begin.";
    NSString* author = tel.psidAuthor[0] ? [NSString stringWithUTF8String:tel.psidAuthor] : @"";
    NSString* rel = tel.psidReleased[0] ? [NSString stringWithUTF8String:tel.psidReleased] : @"";
    NSString* st = tel.psidSongs ? [NSString stringWithFormat:@"%u/%u", (unsigned)std::max<uint16_t>(1, tel.psidCurrentSubtune), (unsigned)tel.psidSongs] : @"-/-";
    NSString* rom = [NSString stringWithFormat:@"ROM K%@ B%@ C%@", ArpSIDC64BoolLamp(tel.c64ExternalKernalRom), ArpSIDC64BoolLamp(tel.c64ExternalBasicRom), ArpSIDC64BoolLamp(tel.c64ExternalCharacterRom)];
    // v964 SIDPLAY telemetry: while a tune is loaded, surface the driver facts
    // the player already publishes — init/play addresses, PAL/NTSC clock, the
    // observed timing model (CIA timer IRQ vs VBI raster), and the live play-
    // routine call count (resets per tune load; the tune's activity heartbeat).
    NSString* drv = @"";
    if (tel.psidTitle[0]) {
        const char* timing = (tel.psidCiaPlayAddressEntered || tel.psidCiaIrqObserved) ? "CIA" : "VBI";
        drv = [NSString stringWithFormat:@"  •  INIT $%04X PLAY $%04X  %s %s  CALLS %u",
               (unsigned)tel.psidInitAddress, (unsigned)tel.psidPlayAddress,
               tel.c64Pal ? "PAL" : "NTSC", timing,
               (unsigned)tel.c64SidPlayCallCount];
    }
    NSString* line=[NSString stringWithFormat:@"C64 SID PLAYER: %@  %@  %@ %@  %@%@", title, st, author, rel, rom, drv];
    NSColor* color=tel.psidTitle[0] ? [c64LtGreen() colorWithAlphaComponent:.86f] : [c64Yellow() colorWithAlphaComponent:.76f];
    for(NSTextField* label in _c64PlayerInfoLabels){
        ArpSIDSetLabelStringIfNeeded(label, line);
        ArpSIDSetLabelColorIfNeeded(label, color);
    }
}


-(NSString*)_c64DebugEventLineFromTelemetry:(const ArpSIDTelemetry&)tel index:(uint8_t)i{
    if(i>=16) return nil;
    const uint8_t kind=tel.c64DebugEventKind[i];
    const uint8_t a=tel.c64DebugEventA[i];
    const uint8_t b=tel.c64DebugEventB[i];
    const uint8_t c=tel.c64DebugEventC[i];
    const uint16_t addr=tel.c64DebugEventAddress[i];
    const uint32_t value=tel.c64DebugEventValue[i];
    const uint64_t cyc=tel.c64DebugEventCycle[i];
    switch(kind){
        case 1: return [NSString stringWithFormat:@"[BOOT] PHI2:%llu PC:$%04X cold:%@ image:%@ play:%@ block:%u", (unsigned long long)cyc, (unsigned)addr, ArpSIDC64BoolLamp(a!=0), ArpSIDC64BoolLamp(b!=0), ArpSIDC64BoolLamp(c!=0), (unsigned)value];
        case 2: return [NSString stringWithFormat:@"[SID LOAD] PHI2:%llu load:$%04X init:$%04X subtune:%u/%u", (unsigned long long)cyc, (unsigned)addr, (unsigned)(value & 0xFFFFu), (unsigned)a, (unsigned)b];
        case 3: return [NSString stringWithFormat:@"[INIT] PHI2:%llu init:$%04X instructions:%u", (unsigned long long)cyc, (unsigned)addr, (unsigned)value];
        case 4: return [NSString stringWithFormat:@"[PLAY] PHI2:%llu play:$%04X call:%u instructions:%u", (unsigned long long)cyc, (unsigned)addr, (unsigned)a, (unsigned)value];
        case 5: return [NSString stringWithFormat:@"[SID WRITE] PHI2:%llu $%04X <= $%02X  reg:$%02X", (unsigned long long)cyc, (unsigned)addr, (unsigned)b, (unsigned)a];
        case 6: return [NSString stringWithFormat:@"[MEM DIFF] PHI2:%llu changed:%02X dirty:%02X hash:%08X", (unsigned long long)cyc, (unsigned)a, (unsigned)b, (unsigned)value];
        case 7: return [NSString stringWithFormat:@"[IRQ/NMI] PHI2:%llu PC:$%04X IRQ:%@ NMI:%@ P:$%02X", (unsigned long long)cyc, (unsigned)addr, ArpSIDC64BoolLamp(a!=0), ArpSIDC64BoolLamp(b!=0), (unsigned)(value & 0xFFu)];
        case 8: return [NSString stringWithFormat:@"[ROM] PHI2:%llu K:%@ B:%@ C:%@ checksum:%08X", (unsigned long long)cyc, ArpSIDC64BoolLamp(a!=0), ArpSIDC64BoolLamp(b!=0), ArpSIDC64BoolLamp(c!=0), (unsigned)value];
        case 9: return [NSString stringWithFormat:@"[CPU JAM] PHI2:%llu PC:$%04X trapBRK:%@ P:$%02X", (unsigned long long)cyc, (unsigned)addr, ArpSIDC64BoolLamp(a!=0), (unsigned)(value & 0xFFu)];
        default: return nil;
    }
}

-(void)_ingestC64DebugEventsFromTelemetry:(const ArpSIDTelemetry&)tel{
    if(!_c64DebugLogTextView && (!_c64DebugStatusLabels || _c64DebugStatusLabels.count==0)) return;
    if(tel.c64DebugEventSequence==0) return;

    const BOOL sequenceChanged = (tel.c64DebugEventSequence != _c64LastDebugEventSequence);
    if(!sequenceChanged) return;

    const uint8_t n=(uint8_t)std::min<unsigned>(tel.c64DebugEventCount, 16u);
    if(tel.c64DebugEventSequence < _c64LastDebugEventSequence) {
        [self _appendC64DebugConsoleLine:@"[SNAPSHOT RESET] C64 debug event sequence restarted"];
        _c64LastDebugHeartbeatBlock = UINT64_MAX;
    }

    if(n == 0u) {
        // Debug stream heartbeat: proves liveness even when the event extractor
        // emits no edge events for this audio block. Rate-limited, telemetry-only        // never touches the render-owned C64 runtime.
        const uint64_t block = tel.c64BlockIndex;
        const BOOL firstHeartbeat = (_c64LastDebugHeartbeatBlock == UINT64_MAX);
        const BOOL blockAdvanced = (block != _c64LastDebugHeartbeatBlock);
        const BOOL rateLimited = firstHeartbeat || (blockAdvanced && ((block & 0x3Fu) == 0u));
        if(rateLimited){
            [self _appendC64DebugConsoleLine:[NSString stringWithFormat:@"[SNAPSHOT LIVE] BLOCK:%llu PHI2:%llu PC:$%04X MEM:%08X DIRTY:%02X PLAY:%u",
                (unsigned long long)tel.c64BlockIndex,
                (unsigned long long)tel.c64Phi2Cycle,
                (unsigned)tel.c64CpuPc,
                (unsigned)tel.c64MemoryCombinedHash,
                (unsigned)(tel.c64MemoryWindowDirtyMask & 0xFFu),
                (unsigned)tel.c64PlayCalls]];
            _c64LastDebugHeartbeatBlock = block;
        }
    } else {
        for(uint8_t i=0;i<n;++i){
            NSString* line=[self _c64DebugEventLineFromTelemetry:tel index:i];
            if(line) [self _appendC64DebugConsoleLine:line];
        }
        _c64LastDebugHeartbeatBlock = tel.c64BlockIndex;
    }

    if(tel.c64DebugEventDropped>0){
        [self _appendC64DebugConsoleLine:[NSString stringWithFormat:@"[DEBUG DROPPED] compact telemetry events dropped:%u", (unsigned)tel.c64DebugEventDropped]];
    }
    _c64LastDebugEventSequence=tel.c64DebugEventSequence;
}

-(BOOL)_c64DebugLine:(NSString*)line matchesFilter:(NSString*)filter{
    if(!line) return NO;
    if(!filter || [filter isEqualToString:@"ALL"]) return YES;
    if([filter isEqualToString:@"SID"]){
        return [line containsString:@"[SID "] || [line containsString:@"[INIT]"] || [line containsString:@"[PLAY]"] || [line containsString:@"subtune"] || [line containsString:@"load accepted"];
    }
    if([filter isEqualToString:@"MEM"]){
        return [line containsString:@"[MEM DIFF]"] || [line containsString:@"[SNAPSHOT LIVE]"] || [line containsString:@" MEM:"] || [line containsString:@"DIRTY:"];
    }
    if([filter isEqualToString:@"CPU"]){
        return [line containsString:@"[BOOT]"] || [line containsString:@"[IRQ/NMI]"] || [line containsString:@"[CPU JAM]"] || [line containsString:@"PC:$"] || [line containsString:@"[SNAPSHOT RESET]"];
    }
    if([filter isEqualToString:@"IO"]){
        return [line containsString:@"[ROM]"] || [line containsString:@"IEC"] || [line containsString:@"TAPE"] || [line containsString:@"bus"] || [line containsString:@"IO"];
    }
    return YES;
}

-(NSArray<NSString*>*)_c64DebugVisibleLines{
    if(!_c64DebugConsoleLines) return @[];
    NSMutableArray<NSString*>* visible=[NSMutableArray arrayWithCapacity:_c64DebugConsoleLines.count];
    NSString* filter=(_c64DebugFilterToken != nil ? _c64DebugFilterToken : @"ALL");
    for(NSString* line in _c64DebugConsoleLines){
        if([self _c64DebugLine:line matchesFilter:filter]) [visible addObject:line];
    }
    return visible;
}

-(void)_c64DebugApplyFilter:(NSString*)filter announce:(BOOL)announce{
    _c64DebugFilterToken = (filter != nil ? filter : @"ALL");
    [[NSUserDefaults standardUserDefaults] setObject:_c64DebugFilterToken forKey:@"ArpSID.C64Debug.Filter"];
    if(_c64DebugFilterAllButton) ArpSIDStyleChromeButton(_c64DebugFilterAllButton, [_c64DebugFilterToken isEqualToString:@"ALL"] ? ArpSIDChromeButtonRoleWarning : ArpSIDChromeButtonRoleUtility, 7.0f);
    if(_c64DebugFilterSidButton) ArpSIDStyleChromeButton(_c64DebugFilterSidButton, [_c64DebugFilterToken isEqualToString:@"SID"] ? ArpSIDChromeButtonRoleWarning : ArpSIDChromeButtonRoleUtility, 7.0f);
    if(_c64DebugFilterMemButton) ArpSIDStyleChromeButton(_c64DebugFilterMemButton, [_c64DebugFilterToken isEqualToString:@"MEM"] ? ArpSIDChromeButtonRoleWarning : ArpSIDChromeButtonRoleUtility, 7.0f);
    if(_c64DebugFilterCpuButton) ArpSIDStyleChromeButton(_c64DebugFilterCpuButton, [_c64DebugFilterToken isEqualToString:@"CPU"] ? ArpSIDChromeButtonRoleWarning : ArpSIDChromeButtonRoleUtility, 7.0f);
    if(_c64DebugFilterIoButton) ArpSIDStyleChromeButton(_c64DebugFilterIoButton, [_c64DebugFilterToken isEqualToString:@"IO"] ? ArpSIDChromeButtonRoleWarning : ArpSIDChromeButtonRoleUtility, 7.0f);
    [self _refreshC64DebugLogTextView];
    if(announce) [self _updateC64DebugStatusLine:[NSString stringWithFormat:@"filter %@ visible %lu/%lu", _c64DebugFilterToken, (unsigned long)[self _c64DebugVisibleLines].count, (unsigned long)(_c64DebugConsoleLines ? _c64DebugConsoleLines.count : 0)]];
}

-(void)_refreshC64DebugLogTextView{
    if(!_c64DebugLogTextView || !_c64DebugConsoleLines) return;
    NSArray<NSString*>* visible=[self _c64DebugVisibleLines];
    NSString* text=[visible componentsJoinedByString:@"\n"];
    if(![_c64DebugLogTextView.string isEqualToString:text]){
        _c64DebugLogTextView.string=(text != nil ? text : @"");
        if(!_c64DebugPaused){
            [_c64DebugLogTextView scrollRangeToVisible:NSMakeRange(_c64DebugLogTextView.string.length, 0)];
        }
    }
}

-(void)_updateC64DebugStatusLine:(NSString*)tail{
    const NSUInteger n=_c64DebugConsoleLines ? _c64DebugConsoleLines.count : 0;
    NSString* mode=_c64DebugPaused ? [NSString stringWithFormat:@"PAUSED · suppressed %llu", (unsigned long long)_c64DebugSuppressedWhilePaused] : @"LIVE";
    const NSUInteger visible=[self _c64DebugVisibleLines].count;
    NSString* line=[NSString stringWithFormat:@"C64 DEBUG %@ [%@]: %@   ·   visible %lu · scrollback %lu/256", mode, (_c64DebugFilterToken != nil ? _c64DebugFilterToken : @"ALL"), (tail != nil ? tail : @"idle"), (unsigned long)visible, (unsigned long)n];
    for(NSTextField* label in _c64DebugStatusLabels){
        if(!label) continue;
        ArpSIDSetLabelStringIfNeeded(label, line);
        ArpSIDSetLabelColorIfNeeded(label, _c64DebugPaused ? [c64Yellow() colorWithAlphaComponent:.82f] : [c64Cyan() colorWithAlphaComponent:.78f]);
    }
}

-(void)_appendC64DebugConsoleLine:(NSString*)line{
    if(!line) return;
    if(!_c64DebugConsoleLines) _c64DebugConsoleLines=[NSMutableArray array];
    if(_c64DebugPaused){
        ++_c64DebugSuppressedWhilePaused;
        [self _updateC64DebugStatusLine:[NSString stringWithFormat:@"paused, last suppressed: %@", line]];
        return;
    }
    static NSDateFormatter* fmt=nil;
    if(!fmt){ fmt=[[NSDateFormatter alloc] init]; fmt.dateFormat=@"HH:mm:ss.SSS"; }
    NSString* stamped=[NSString stringWithFormat:@"%@  %@", [fmt stringFromDate:[NSDate date]], line];
    [_c64DebugConsoleLines addObject:stamped];
    while(_c64DebugConsoleLines.count>256) [_c64DebugConsoleLines removeObjectAtIndex:0];
    [self _updateC64DebugStatusLine:stamped];
    [self _refreshC64DebugLogTextView];
}

-(void)_c64DebugClear:(id)sender{
    (void)sender;
    if(!_c64DebugConsoleLines) _c64DebugConsoleLines=[NSMutableArray array];
    [_c64DebugConsoleLines removeAllObjects];
    _c64DebugSuppressedWhilePaused=0;
    if(_c64DebugLogTextView) _c64DebugLogTextView.string=@"";
    [self _appendC64DebugConsoleLine:@"[DEBUG CLEAR] UI scrollback cleared; realtime C64 telemetry unaffected"];
}

-(void)_c64DebugPauseToggle:(id)sender{
    (void)sender;
    const BOOL nowPaused=!_c64DebugPaused;
    _c64DebugPaused=nowPaused;
    if(_c64DebugPauseButton){
        _c64DebugPauseButton.title=nowPaused ? @"RESUME" : @"PAUSE";
        ArpSIDStyleChromeButton(_c64DebugPauseButton, nowPaused ? ArpSIDChromeButtonRoleWarning : ArpSIDChromeButtonRoleUtility, 7.2f);
    }
    if(nowPaused){
        [self _updateC64DebugStatusLine:@"paused by user; render telemetry still running"];
    } else {
        NSString* msg=[NSString stringWithFormat:@"[DEBUG RESUME] UI scrollback resumed, suppressed:%llu", (unsigned long long)_c64DebugSuppressedWhilePaused];
        _c64DebugSuppressedWhilePaused=0;
        [self _appendC64DebugConsoleLine:msg];
    }
}

-(void)_c64DebugFilterAll:(id)sender{ (void)sender; [self _c64DebugApplyFilter:@"ALL" announce:YES]; }
-(void)_c64DebugFilterSid:(id)sender{ (void)sender; [self _c64DebugApplyFilter:@"SID" announce:YES]; }
-(void)_c64DebugFilterMem:(id)sender{ (void)sender; [self _c64DebugApplyFilter:@"MEM" announce:YES]; }
-(void)_c64DebugFilterCpu:(id)sender{ (void)sender; [self _c64DebugApplyFilter:@"CPU" announce:YES]; }
-(void)_c64DebugFilterIo:(id)sender{ (void)sender; [self _c64DebugApplyFilter:@"IO" announce:YES]; }

-(NSString*)_c64DebugVisibleTextWithHeader:(BOOL)includeHeader{
    NSArray<NSString*>* visible=[self _c64DebugVisibleLines];
    NSString* joinedBody=[visible componentsJoinedByString:@"\n"];
    NSString* body=(joinedBody != nil ? joinedBody : @"");
    if(!includeHeader) return body;
    NSString* header=[NSString stringWithFormat:@"ArpSID C64 Safe Debug Export\nFilter: %@\nVisible: %lu\nScrollback: %lu/256\nPaused: %@\nSuppressedWhilePaused: %llu\n---\n",
        (_c64DebugFilterToken != nil ? _c64DebugFilterToken : @"ALL"),
        (unsigned long)visible.count,
        (unsigned long)(_c64DebugConsoleLines ? _c64DebugConsoleLines.count : 0),
        _c64DebugPaused ? @"YES" : @"NO",
        (unsigned long long)_c64DebugSuppressedWhilePaused];
    return [header stringByAppendingString:body];
}

-(void)_c64DebugCopyVisible:(id)sender{
    (void)sender;
    NSString* text=[self _c64DebugVisibleTextWithHeader:YES];
    NSPasteboard* pb=[NSPasteboard generalPasteboard];
    [pb clearContents];
    [pb setString:(text != nil ? text : @"") forType:NSPasteboardTypeString];
    [self _updateC64DebugStatusLine:[NSString stringWithFormat:@"copied visible debug lines:%lu", (unsigned long)[self _c64DebugVisibleLines].count]];
}

-(void)_c64DebugExportVisible:(id)sender{
    (void)sender;
    NSSavePanel* panel=[NSSavePanel savePanel];
    panel.nameFieldStringValue=@"ArpSID-C64-Debug.log";
    arpsidSetPanelTypes(panel, @[@"log", @"txt"]);
    NSWindow* window=self.view.window;
    void (^writeBlock)(NSInteger)=^(NSInteger result){
        if(result != NSModalResponseOK || !panel.URL) { [self _updateC64DebugStatusLine:@"export cancelled"]; return; }
        NSString* exportedText=[self _c64DebugVisibleTextWithHeader:YES];
        NSString* text=(exportedText != nil ? exportedText : @"");
        NSError* err=nil;
        BOOL ok=[text writeToURL:panel.URL atomically:YES encoding:NSUTF8StringEncoding error:&err];
        [self _updateC64DebugStatusLine: ok ? [NSString stringWithFormat:@"exported visible debug lines:%lu", (unsigned long)[self _c64DebugVisibleLines].count] : [NSString stringWithFormat:@"export failed: %@", (err.localizedDescription != nil ? err.localizedDescription : @"unknown")]];
    };
    if(window){ [panel beginSheetModalForWindow:window completionHandler:writeBlock]; }
    else { writeBlock([panel runModal]); }
}

static uint16_t ArpSIDPsidBE16(NSData* data, NSUInteger off, uint16_t fallback) {
    if (!data || data.length < off + 2u) return fallback;
    const uint8_t* b = (const uint8_t*)data.bytes;
    return (uint16_t)(((uint16_t)b[off] << 8) | (uint16_t)b[off + 1u]);
}

-(BOOL)_reloadCachedSidFileForSubtune:(uint16_t)subtune{
    if(!_psidFileData || !_au) return NO;
    const uint16_t count = std::max<uint16_t>(1, _psidSongCount);
    const uint16_t clamped = std::min<uint16_t>(std::max<uint16_t>(1, subtune), count);
    BOOL ok=NO;
    if([_au respondsToSelector:@selector(loadSidFileData:subtune:)]) ok=[(id)_au loadSidFileData:_psidFileData subtune:clamped];
    else if([_au respondsToSelector:@selector(loadSidFileData:)]) ok=[(id)_au loadSidFileData:_psidFileData];
    if(ok) _psidCurrentSubtune = clamped;
    return ok;
}

// v964: exact PSID rejection reason for failure HUD/console lines. The load call
// is synchronous, so the kernel's parse/load failure telemetry is already final
// when it returns NO — read a FRESH light snapshot (the polled _telemetry copy
// can be one vsync stale) and name the codes.
-(NSString*)_c64PsidLoadFailureDetail{
    ArpSIDDSPKernelAdapter* adapter=nil;
    if([_au respondsToSelector:@selector(kernelAdapter)]) adapter=[_au performSelector:@selector(kernelAdapter)];
    if(!adapter || ![adapter respondsToSelector:@selector(readTelemetry:)]) return @"";
    ArpSIDTelemetry tel;
    [adapter readTelemetry:&tel];
    const auto parse=(ArpSID::PsidParseResult)tel.c64PsidLastParseResult;
    const auto load =(ArpSID::C64::PsidLoadFailure)tel.c64PsidLastLoadFailure;
    if(parse==ArpSID::PsidParseResult::OK && load==ArpSID::C64::PsidLoadFailure::None) return @"";
    if(parse!=ArpSID::PsidParseResult::OK && load!=ArpSID::C64::PsidLoadFailure::None)
        return [NSString stringWithFormat:@" — parse %s / %s",
                ArpSID::psidParseResultName(parse), ArpSID::C64::psidLoadFailureName(load)];
    if(parse!=ArpSID::PsidParseResult::OK)
        return [NSString stringWithFormat:@" — parse %s", ArpSID::psidParseResultName(parse)];
    return [NSString stringWithFormat:@" — %s", ArpSID::C64::psidLoadFailureName(load)];
}

-(void)_c64LoadSidFile:(id)sender{
    (void)sender;
    NSOpenPanel*op=[NSOpenPanel openPanel];
    op.canChooseFiles=YES; op.canChooseDirectories=NO; op.allowsMultipleSelection=NO;
    arpsidSetPanelTypes(op, @[@"sid", @"psid", @"rsid"]);
    __weak ArpSIDViewController* weakSelf = self;
    void (^handler)(NSModalResponse) = ^(NSModalResponse r){
        if(r!=NSModalResponseOK || !op.URL) return;
        NSURL* sidURL = [op.URL copy];
        NSString* sidFileName = [sidURL.lastPathComponent copy];
        ArpSIDViewController* ss = weakSelf; if(!ss || !sidURL) return;
        NSData*data=[NSData dataWithContentsOfURL:sidURL options:0 error:nil];
        ss->_psidFileData=data;
        ss->_psidSongCount=std::max<uint16_t>(1, ArpSIDPsidBE16(data, 0x0Eu, 1));
        const uint16_t startSong=std::max<uint16_t>(1, ArpSIDPsidBE16(data, 0x10u, 1));
        ss->_psidCurrentSubtune=std::min<uint16_t>(startSong, ss->_psidSongCount);
        BOOL ok=[ss _reloadCachedSidFileForSubtune:ss->_psidCurrentSubtune];
        NSString* failDetail = ok ? @"" : [ss _c64PsidLoadFailureDetail];  // v964: exact rejection reason
        [ss _appendC64DebugConsoleLine:(ok ? [NSString stringWithFormat:@"load accepted %@ subtune %u/%u", sidFileName, (unsigned)ss->_psidCurrentSubtune, (unsigned)ss->_psidSongCount] : [NSString stringWithFormat:@"load failed %@%@", sidFileName, failDetail])];
        ArpSIDSetLabelStringIfNeeded(ss->_optionsHUDLabel, ok ? [NSString stringWithFormat:@"C64 SID PLAYER: loaded %@ subtune %u/%u", sidFileName, (unsigned)ss->_psidCurrentSubtune, (unsigned)ss->_psidSongCount] : [NSString stringWithFormat:@"C64 SID PLAYER: load failed%@", failDetail]);
    };
    NSWindow* win = self.view.window;
    if(win) [op beginSheetModalForWindow:win completionHandler:handler];
    else [op beginWithCompletionHandler:handler];
}
-(void)_c64PrevSubtune:(id)sender{ (void)sender; if(!_psidFileData) return; uint16_t c=std::max<uint16_t>(1,_psidSongCount); uint16_t n=(_psidCurrentSubtune<=1)?c:(uint16_t)(_psidCurrentSubtune-1); BOOL ok=[self _reloadCachedSidFileForSubtune:n]; NSString* fd=ok?@"":[self _c64PsidLoadFailureDetail]; [self _appendC64DebugConsoleLine:(ok ? [NSString stringWithFormat:@"subtune prev -> %u/%u", (unsigned)n, (unsigned)c] : [NSString stringWithFormat:@"subtune prev failed%@", fd])]; ArpSIDSetLabelStringIfNeeded(_optionsHUDLabel, ok ? [NSString stringWithFormat:@"C64 SID PLAYER: subtune %u/%u", (unsigned)n, (unsigned)c] : [NSString stringWithFormat:@"C64 SID PLAYER: subtune reload failed%@", fd]); }
-(void)_c64NextSubtune:(id)sender{ (void)sender; if(!_psidFileData) return; uint16_t c=std::max<uint16_t>(1,_psidSongCount); uint16_t n=(_psidCurrentSubtune>=c)?1:(uint16_t)(_psidCurrentSubtune+1); BOOL ok=[self _reloadCachedSidFileForSubtune:n]; NSString* fd=ok?@"":[self _c64PsidLoadFailureDetail]; [self _appendC64DebugConsoleLine:(ok ? [NSString stringWithFormat:@"subtune next -> %u/%u", (unsigned)n, (unsigned)c] : [NSString stringWithFormat:@"subtune next failed%@", fd])]; ArpSIDSetLabelStringIfNeeded(_optionsHUDLabel, ok ? [NSString stringWithFormat:@"C64 SID PLAYER: subtune %u/%u", (unsigned)n, (unsigned)c] : [NSString stringWithFormat:@"C64 SID PLAYER: subtune reload failed%@", fd]); }
-(void)_c64EjectSidFile:(id)sender{
    (void)sender;
    _psidFileData=nil; _psidSongCount=0; _psidCurrentSubtune=0;
    if(_au && [_au respondsToSelector:@selector(resetC64SidPlayerForEject)]) [(id)_au resetC64SidPlayerForEject];
    else if(_au && [_au respondsToSelector:@selector(unloadSidFile)]) [(id)_au unloadSidFile];
    [self _appendC64DebugConsoleLine:@"EJECT: hard reset player, SID regs, bridge, telemetry and pending loads"];
    ArpSIDSetLabelStringIfNeeded(_optionsHUDLabel, @"C64 SID PLAYER: ejected/reset — next .sid starts clean");
    for(NSTextField* label in _c64PlayerInfoLabels)
        ArpSIDSetLabelStringIfNeeded(label, @"C64 SID PLAYER: No .sid file loaded — click ▶ Load .sid… to begin.");
}
-(void)_c64UnloadSidFile:(id)sender{
    (void)sender;
    _psidFileData=nil; _psidSongCount=0; _psidCurrentSubtune=0;
    if(_au && [_au respondsToSelector:@selector(unloadSidFile)]) [(id)_au unloadSidFile];
    [self _appendC64DebugConsoleLine:@"UNLOAD: stopped player and cleared telemetry"];
    ArpSIDSetLabelStringIfNeeded(_optionsHUDLabel, @"C64 SID PLAYER: unloaded");
}
