// v838: realtime VIC-II fast toggle (default off). Cuts per-cycle VIC cost during
// SID playback (sprite/badline DMA + bus-steal skipped) to stop CPU-bound stutter;
// CPU/CIA/SID stay bit-exact. command 6 = fast on, 7 = accurate.
-(void)_c64ToggleVicFast:(id)sender{ (void)sender;
    _c64VicFastOn = !_c64VicFastOn;
    [self _performC64ControlHubCommand:(_c64VicFastOn ? 6 : 7)
                                 label:(_c64VicFastOn ? @"VIC-II FAST" : @"VIC-II ACCURATE")];
    if(_c64VicFastButton) _c64VicFastButton.title = _c64VicFastOn ? @"VIC:FAST" : @"VIC:ACC";
}

// v839: 6510 fast toggle. CPU/CIA/VIC/SID stay bit-exact; skips the per-cycle
// diagnostics snapshot only. command 8 = fast on, 9 = accurate.
-(void)_c64Toggle6510Fast:(id)sender{ (void)sender;
    _c64CpuFastOn = !_c64CpuFastOn;
    [self _performC64ControlHubCommand:(_c64CpuFastOn ? 8 : 9)
                                 label:(_c64CpuFastOn ? @"6510 FAST" : @"6510 ACCURATE")];
    if(_c64CpuFastButton) _c64CpuFastButton.title = _c64CpuFastOn ? @"6510:FAST" : @"6510:ACC";
}

