-(void)_panic:(id)sender{
    (void)sender;if(!_au)return;
    if(_pianoView) [_pianoView cancelHeldNote];
    [self _releasePendingDrumAuditionNow];
    // All notes off via CC 123 + CC 120
    uint8_t off1[3]={0xB0,123,0}; [_au injectMIDIBytes:off1 length:3];
    uint8_t off2[3]={0xB0,120,0}; [_au injectMIDIBytes:off2 length:3];
    // Also set panic param for arpeggiator / sequencer reset
    [_au setParameterValue:1.f forID:ArpSID::kParamPanic];}

