-(void)_showTab:(ArpSIDTab)t{
    ArpSIDTab requested = ArpSIDCanonicalVisibleTabForFlavor(_componentFlavor, t);
    if(!self.view){
        if(requested != ArpSIDTabMain){
            _pendingBootstrapTab_v826 = requested;
            _hasPendingBootstrapTab_v826 = YES;
        }
        _tab = ArpSIDTabMain;
        return;
    }
    if(!_built && !_pMain){
        if(requested != ArpSIDTabMain){
            _pendingBootstrapTab_v826 = requested;
            _hasPendingBootstrapTab_v826 = YES;
        }
        _tab = ArpSIDTabMain;
        [self _scheduleDeferredAuv2EditorBuild_v831_];
        return;
    }
    if(!_firstEditorPaintCompleted_v826 && requested != ArpSIDTabMain){
        _pendingBootstrapTab_v826 = requested;
        _hasPendingBootstrapTab_v826 = YES;
        [self _scheduleFirstPaintFenceRelease_v827_];
        requested = ArpSIDTabMain;
    }
    _tab=requested;
    // Per-tab brand: relabel/recolour the persistent header badge for this tab,
    // and tint the header oscilloscope trace with the same accent so the whole
    // header chrome coherently identifies the active function.
    if(_headerLogoView_v687) _headerLogoView_v687.currentTab = (NSInteger)_tab;
    if(_oscView){ _oscView.accentColor = ArpSIDTabBrandAccent((NSInteger)_tab); [_oscView setNeedsDisplay:YES]; }
    NSView* activePanel_v825 = [self _ensureContentPanelForTab_v825:_tab];
    [self _forEachContentPanel_v824:^(NSView* panel) {
        panel.hidden = (panel != activePanel_v825);
    }];
    [self _attachOnlyActiveContentPanel_v824];
    [self _forEachContentPanel_v824:^(NSView* panel) {
        if(panel) ArpSIDSetPanelActiveGlow(panel, !panel.hidden);
    }];
    if(_tabBar){
        NSInteger sel=ArpSIDVisibleTabSegmentForFlavor(_componentFlavor, _tab);
        if(sel>=0 && sel<_tabBar.segmentCount) _tabBar.selectedSegment=sel;
    }
    [self _refreshModeAdaptiveChrome];
    [self _mountMainChromeControls];
    [self _syncNavigationState];
}
