-(void)refreshPresets{ [self _refreshPresets]; }

-(void)_refreshPresets{
    if(!_presetPop) return;
    if(_isApplyingPreset.load(std::memory_order_acquire)) {
        _needsDeferredPresetUISync.store(true, std::memory_order_release);
        return;
    }
    const auto& defs = ArpSID::getFactoryPatchDefinitions();
    NSInteger presetCount = (NSInteger)defs.size();
    const std::vector<NSInteger> orderedSlots = ArpSIDFactorySlotOrderForFlavorUI(_componentFlavor);
    NSString* leadText = ArpSIDPresetPickerLeadTextForFlavor(_componentFlavor, [self _effectiveModeIndexFromTelemetry:nullptr]);
    NSMutableString* signature=[NSMutableString string];
    for(NSInteger slot : orderedSlots){
        NSString* prettyName = _hasLoadedBankCache ? [self _loadedBankDisplayNameForSlot:slot]
                                                   : [self _factoryDisplayNameForSlot:slot];
        [signature appendFormat:@"%ld:%@:%d|", (long)slot, (prettyName ? prettyName : @""), _hasLoadedBankCache ? 1 : 0];
    }
    BOOL needsRebuild = (_lastFactoryPresetCount != presetCount) || ![_lastPresetSignature isEqualToString:signature];
    if(needsRebuild){
        [_presetPop removeAllItems];
        [_presetPop addItemWithTitle:[NSString stringWithFormat:@"%@  Live / Current", leadText]];
        _presetPop.lastItem.tag = -1;
        for (NSInteger slot : orderedSlots) {
            NSString* prettyName = _hasLoadedBankCache ? [self _loadedBankDisplayNameForSlot:slot]
                                                       : [self _factoryDisplayNameForSlot:slot];
            if(prettyName.length <= 0) prettyName = [NSString stringWithFormat:@"Preset %03ld", (long)(slot + 1)];
            NSString* presetTitle=nil;
            if(_componentFlavor == ArpSID::ComponentFlavor::Sid808){
                presetTitle = [NSString stringWithFormat:@"%@  S%03ld  %@",
                               ArpSIDSid808PriorityBadgeUI(slot),
                               (long)(slot + 1),
                               prettyName];
            } else {
                NSString* prefix = ArpSID::componentFlavorIsDedicatedDrum(_componentFlavor) ? @"K" : @"P";
                presetTitle = [NSString stringWithFormat:@"%@%03ld  %@", prefix, (long)(slot + 1), prettyName];
            }
            [_presetPop addItemWithTitle:presetTitle];
            _presetPop.lastItem.tag = slot;
        }
        _lastFactoryPresetCount = presetCount;
        _lastPresetSignature=[signature copy];
        // v687: rebuild the native pull-down patch submenu ONLY when the slot
        // list actually changed (same guard as the inline popup), so periodic
        // deferred-sync refreshes don't churn 180 menu items every tick.
        [self _rebuildNativePatchMenu_v687];
    }
    NSString* currentName = [self _currentPresetDisplayName];
    NSInteger selectedSlot = 0;
    if(_currentStateBackedByLoadedBank && _currentLoadedBankSlot >= 0){
        selectedSlot = _currentLoadedBankSlot;
    } else if(_au){
        const float bankNorm = [_au getParameterValue:ArpSID::kParamBankSlot];
        selectedSlot = (NSInteger)ArpSID::canonicalFactorySlotFromNormalizedBankSlot(bankNorm);
    }
    if(!ArpSIDFactorySlotAllowedForFlavor(_componentFlavor, selectedSlot)){
        selectedSlot = ArpSIDStartupFactorySlotForFlavorUI(_componentFlavor);
    }
    NSInteger idx = [_presetPop indexOfItemWithTag:selectedSlot];
    if (idx >= 0) {
        [_presetPop selectItemAtIndex:idx];
    } else if(_presetPop.numberOfItems > 0){
        NSString* title = currentName.length ? [NSString stringWithFormat:@"%@  %@", leadText, currentName]
                                             : [NSString stringWithFormat:@"%@  Live / Current", leadText];
        [[_presetPop itemAtIndex:0] setTitle:title];
        [_presetPop selectItemAtIndex:0];
    }
}

// v687: rebuild the native menu's Patch submenu from the flavor-filtered slot
// list (identical source to _refreshPresets), so the native menu and the inline
// preset popup always show the same per-type patches.
-(void)_rebuildNativePatchMenu_v687{
    if(!_nativePatchSubmenu_v687) return;
    [_nativePatchSubmenu_v687 removeAllItems];
    const std::vector<NSInteger> orderedSlots = ArpSIDFactorySlotOrderForFlavorUI(_componentFlavor);
    for(NSInteger slot : orderedSlots){
        NSString* prettyName = _hasLoadedBankCache ? [self _loadedBankDisplayNameForSlot:slot]
                                                   : [self _factoryDisplayNameForSlot:slot];
        if(prettyName.length<=0) prettyName=[NSString stringWithFormat:@"Preset %03ld",(long)(slot+1)];
        NSMenuItem* it=[[NSMenuItem alloc] initWithTitle:[NSString stringWithFormat:@"%03ld  %@",(long)(slot+1),prettyName]
                                                  action:@selector(_nativePatchMenu_v687:) keyEquivalent:@""];
        it.target=self; it.tag=slot; [_nativePatchSubmenu_v687 addItem:it];
    }
}

