// ─── v548 MIX tab panel builder ──────────────────────────────────────────────
// Builds a 16-channel mixer strip panel backed by `_mixModel_v547_`.
// Layout: scrollable horizontal strip of 16 narrow channel columns + a master
// section on the right. Each column contains: channel label, volume slider,
// pan label, solo/mute buttons, and 5 FX-slot dropdowns. The master section
// has master-volume slider, limiter toggle + threshold + release, stereo-width
// slider, and dim-monitor toggle. A send-bus row below shows DELAY BUS and
// REVERB BUS enable/return controls.
//
// Action handlers update `_mixModel_v547_` directly and push it to the adapter;
// v588 maps the POD model into render-friendly mixer intent.

static NSString* arpsidMixFxTypeName(ArpSID::GUI::MixFxType t) {
    switch (t) {
        case ArpSID::GUI::MixFxType::None:       return @"—";
        case ArpSID::GUI::MixFxType::Eq3Band:    return @"EQ 3-Band";
        case ArpSID::GUI::MixFxType::Transient:  return @"Transient";
        case ArpSID::GUI::MixFxType::Compressor: return @"Compressor";
        case ArpSID::GUI::MixFxType::Saturator:  return @"Saturator";
        case ArpSID::GUI::MixFxType::Bitcrusher: return @"Bitcrusher";
    }
    return @"—";
}

// Action tag encoding: (channelIdx << 8) | slotIdx for FX dropdowns
// channelIdx for vol/pan/solo/mute sliders/buttons
static constexpr NSInteger kArpSIDMixFxTagBase = 0x1000; // FX dropdown tags: base + (ch<<3) + slot
static constexpr NSInteger kArpSIDMixVolTagBase = 0x2000; // vol slider: base + ch
static constexpr NSInteger kArpSIDMixPanTagBase = 0x3000; // pan slider: base + ch
static constexpr NSInteger kArpSIDMixSoloTagBase = 0x4000; // solo button: base + ch
static constexpr NSInteger kArpSIDMixMuteTagBase = 0x5000; // mute button: base + ch
static constexpr NSInteger kArpSIDMixSendDelayTagBase = 0x5100; // delay send slider: base + ch
static constexpr NSInteger kArpSIDMixSendReverbTagBase = 0x5200; // reverb send slider: base + ch
static constexpr NSInteger kArpSIDMixMasterVolumeTag = 0x5300;
static constexpr NSInteger kArpSIDMixLimiterEnableTag = 0x5301;
static constexpr NSInteger kArpSIDMixLimiterThresholdTag = 0x5302;
static constexpr NSInteger kArpSIDMixLimiterReleaseTag = 0x5303;
static constexpr NSInteger kArpSIDMixStereoWidthTag = 0x5304;
static constexpr NSInteger kArpSIDMixDimMonitorTag = 0x5305;
static constexpr NSInteger kArpSIDMixSendEnableTagBase = 0x5400; // send bus enable: base + bus
static constexpr NSInteger kArpSIDMixSendReturnTagBase = 0x5410; // send bus return: base + bus

-(void)_mixVolumeChanged_v548_:(id)sender {
    NSSlider* sl = (NSSlider*)sender;
    NSInteger ch = sl.tag - kArpSIDMixVolTagBase;
    if (ch < 0 || ch >= ArpSID::GUI::kMixChannelCount) return;
    _mixModel_v547_.channels[(size_t)ch].volume = (uint8_t)std::clamp((int)sl.intValue, 0, 255);
    [self _pushMixStateToAdapter_v561_]; // v561 — persist after every model change
}

-(void)_mixPanChanged_v548_:(id)sender {
    NSSlider* sl = (NSSlider*)sender;
    NSInteger ch = sl.tag - kArpSIDMixPanTagBase;
    if (ch < 0 || ch >= ArpSID::GUI::kMixChannelCount) return;
    _mixModel_v547_.channels[(size_t)ch].pan = (uint8_t)std::clamp((int)sl.intValue, 0, 255);
    [self _pushMixStateToAdapter_v561_]; // v561
}

-(void)_mixSoloToggled_v548_:(id)sender {
    NSButton* btn = (NSButton*)sender;
    NSInteger ch = btn.tag - kArpSIDMixSoloTagBase;
    if (ch < 0 || ch >= ArpSID::GUI::kMixChannelCount) return;
    _mixModel_v547_.channels[(size_t)ch].solo =
        (btn.state == NSControlStateValueOn) ? 1u : 0u;
    [self _pushMixStateToAdapter_v561_]; // v561
}

-(void)_mixMuteToggled_v548_:(id)sender {
    NSButton* btn = (NSButton*)sender;
    NSInteger ch = btn.tag - kArpSIDMixMuteTagBase;
    if (ch < 0 || ch >= ArpSID::GUI::kMixChannelCount) return;
    _mixModel_v547_.channels[(size_t)ch].mute =
        (btn.state == NSControlStateValueOn) ? 1u : 0u;
    [self _pushMixStateToAdapter_v561_]; // v561
}

-(void)_mixFxSlotChanged_v548_:(id)sender {
    NSPopUpButton* pop = (NSPopUpButton*)sender;
    NSInteger tag = pop.tag - kArpSIDMixFxTagBase;
    NSInteger ch  = tag >> 3;
    NSInteger slot = tag & 0x7;
    if (ch < 0 || ch >= ArpSID::GUI::kMixChannelCount) return;
    if (slot < 0 || slot >= ArpSID::GUI::kMixFxSlotsPerChannel) return;
    auto fxType = (ArpSID::GUI::MixFxType)(NSInteger)pop.indexOfSelectedItem;
    ArpSID::GUI::setMixFxSlot(_mixModel_v547_.channels[(size_t)ch].fxSlots[(size_t)slot], fxType);
    [self _pushMixStateToAdapter_v561_]; // v561
}

