    NSSlider* sl = (NSSlider*)sender;
    NSInteger ch = sl.tag - kArpSIDMixSendDelayTagBase;
    if (ch < 0 || ch >= ArpSID::GUI::kMixChannelCount) return;
    _mixModel_v547_.channels[(size_t)ch].sendToDelay = (uint8_t)std::clamp((int)sl.intValue, 0, 255);
