-(void)_mixReverbSendChanged_v593_:(id)sender {
    NSSlider* sl = (NSSlider*)sender;
    NSInteger ch = sl.tag - kArpSIDMixSendReverbTagBase;
    if (ch < 0 || ch >= ArpSID::GUI::kMixChannelCount) return;
    _mixModel_v547_.channels[(size_t)ch].sendToReverb = (uint8_t)std::clamp((int)sl.intValue, 0, 255);
    [self _pushMixStateToAdapter_v561_];
}

