-(NSView*)_mixPanel_v547_:(NSRect)r {
    NSView* v = [[NSView alloc] initWithFrame:r];
    v.wantsLayer = YES;
    v.layer.backgroundColor = NSColor.clearColor.CGColor;

    const CGFloat p = ArpSIDUIDynamicPanelInset(r.size.width);
    const CGFloat chW = 72.0f;   // per-channel column width
    const CGFloat masterW = 110.0f;
    const CGFloat sendH = 48.0f;
    const CGFloat stripH = r.size.height - p * 2.0f - sendH - 4.0f;
    const CGFloat stripY = p + sendH + 4.0f;

    // ── Channel strip scroll view ─────────────────────────────────────────────
    // Wraps the 16 channel columns in an NSScrollView so the tab remains usable
    // at small plugin sizes. The master section is pinned outside the scroll.
    CGFloat scrollW = r.size.width - masterW - p * 3.0f;
    NSScrollView* scroll = [[NSScrollView alloc]
        initWithFrame:NSMakeRect(p, stripY, scrollW, stripH)];
    scroll.hasHorizontalScroller = YES;
    scroll.hasVerticalScroller   = NO;
    scroll.autohidesScrollers    = YES;
    scroll.borderType            = NSNoBorder;

    CGFloat contentW = chW * (CGFloat)ArpSID::GUI::kMixChannelCount + p;
    NSView* stripContent = [[NSView alloc]
        initWithFrame:NSMakeRect(0, 0, contentW, stripH)];

    // FX popup item titles (same order as MixFxType enum)
    NSArray<NSString*>* fxItems = @[
        arpsidMixFxTypeName(ArpSID::GUI::MixFxType::None),
        arpsidMixFxTypeName(ArpSID::GUI::MixFxType::Eq3Band),
        arpsidMixFxTypeName(ArpSID::GUI::MixFxType::Transient),
        arpsidMixFxTypeName(ArpSID::GUI::MixFxType::Compressor),
        arpsidMixFxTypeName(ArpSID::GUI::MixFxType::Saturator),
        arpsidMixFxTypeName(ArpSID::GUI::MixFxType::Bitcrusher),
    ];

    for (NSInteger ch = 0; ch < (NSInteger)ArpSID::GUI::kMixChannelCount; ++ch) {
        const ArpSID::GUI::MixChannel& chModel = _mixModel_v547_.channels[(size_t)ch];
        CGFloat x = (CGFloat)ch * chW + p * 0.5f;
        CGFloat y = stripH - 4.0f;

        // Channel number label
        NSTextField* lbl = [NSTextField labelWithString:
            [NSString stringWithFormat:@"CH%d", (int)(ch + 1)]];
        lbl.font = monoBF(9.0f);
        lbl.textColor = colTitle();
        lbl.alignment = NSTextAlignmentCenter;
        lbl.frame = NSMakeRect(x, y - 14.0f, chW - 2.0f, 13.0f);
        [stripContent addSubview:lbl];
        y -= 16.0f;

        // Volume slider (vertical)
        NSSlider* volSlider = [[NSSlider alloc] initWithFrame:
            NSMakeRect(x + chW * 0.5f - 8.0f, y - 80.0f, 16.0f, 80.0f)];
        volSlider.sliderType = NSSliderTypeLinear;
        volSlider.vertical   = YES;
        volSlider.minValue   = 0;
        volSlider.maxValue   = 255;
        volSlider.intValue   = (int)chModel.volume;
        volSlider.tag        = kArpSIDMixVolTagBase + ch;
        volSlider.target     = self;
        volSlider.action     = @selector(_mixVolumeChanged_v548_:);
        volSlider.toolTip    = [NSString stringWithFormat:@"CH%d volume (0-255)", (int)(ch + 1)];  // v963 tooltip-coverage
        [stripContent addSubview:volSlider];
        y -= 82.0f;

        // Pan slider (horizontal)
        NSSlider* panSlider = [[NSSlider alloc] initWithFrame:
            NSMakeRect(x + 2.0f, y - 14.0f, chW - 4.0f, 14.0f)];
        panSlider.sliderType = NSSliderTypeLinear;
        panSlider.vertical   = NO;
        panSlider.minValue   = 0;
        panSlider.maxValue   = 255;
        panSlider.intValue   = (int)chModel.pan;
        panSlider.tag        = kArpSIDMixPanTagBase + ch;
        panSlider.target     = self;
        panSlider.action     = @selector(_mixPanChanged_v548_:);
        panSlider.toolTip    = [NSString stringWithFormat:@"CH%d pan (0-255, 128 = centre)", (int)(ch + 1)];  // v963 tooltip-coverage
        [stripContent addSubview:panSlider];
        y -= 16.0f;

        // Per-channel send levels
        NSTextField* dlyLbl = [NSTextField labelWithString:@"D"];
        dlyLbl.font = monoBF(8.0f);
        dlyLbl.textColor = colLabel();
        dlyLbl.alignment = NSTextAlignmentCenter;
        dlyLbl.toolTip = @"Delay send level";
        dlyLbl.frame = NSMakeRect(x + 2.0f, y - 14.0f, 12.0f, 13.0f);
        [stripContent addSubview:dlyLbl];
        NSSlider* dlySend = [[NSSlider alloc] initWithFrame:
            NSMakeRect(x + 16.0f, y - 14.0f, chW - 18.0f, 14.0f)];
        dlySend.sliderType = NSSliderTypeLinear;
        dlySend.vertical   = NO;
        dlySend.minValue   = 0;
        dlySend.maxValue   = 255;
        dlySend.intValue   = (int)chModel.sendToDelay;
        dlySend.tag        = kArpSIDMixSendDelayTagBase + ch;
        dlySend.target     = self;
        dlySend.action     = @selector(_mixDelaySendChanged_v593_:);
        dlySend.toolTip    = @"Delay send level";
        [stripContent addSubview:dlySend];
        y -= 16.0f;

        NSTextField* rvbLbl = [NSTextField labelWithString:@"R"];
        rvbLbl.font = monoBF(8.0f);
        rvbLbl.textColor = colLabel();
        rvbLbl.alignment = NSTextAlignmentCenter;
        rvbLbl.toolTip = @"Reverb send level";
        rvbLbl.frame = NSMakeRect(x + 2.0f, y - 14.0f, 12.0f, 13.0f);
        [stripContent addSubview:rvbLbl];
        NSSlider* rvbSend = [[NSSlider alloc] initWithFrame:
            NSMakeRect(x + 16.0f, y - 14.0f, chW - 18.0f, 14.0f)];
        rvbSend.sliderType = NSSliderTypeLinear;
        rvbSend.vertical   = NO;
        rvbSend.minValue   = 0;
        rvbSend.maxValue   = 255;
        rvbSend.intValue   = (int)chModel.sendToReverb;
        rvbSend.tag        = kArpSIDMixSendReverbTagBase + ch;
        rvbSend.target     = self;
        rvbSend.action     = @selector(_mixReverbSendChanged_v593_:);
        rvbSend.toolTip    = @"Reverb send level";
        [stripContent addSubview:rvbSend];
        y -= 16.0f;

        // Solo / Mute buttons side-by-side
        CGFloat btnW = (chW - 6.0f) * 0.5f;
        NSButton* soloBtn = [NSButton buttonWithTitle:@"S"
                                               target:self
                                               action:@selector(_mixSoloToggled_v548_:)];
        soloBtn.buttonType = NSButtonTypeToggle;
        soloBtn.font       = monoBF(9.0f);
        soloBtn.frame      = NSMakeRect(x + 2.0f, y - 18.0f, btnW, 18.0f);
        soloBtn.tag        = kArpSIDMixSoloTagBase + ch;
        soloBtn.state      = chModel.solo ? NSControlStateValueOn : NSControlStateValueOff;
        soloBtn.toolTip    = [NSString stringWithFormat:@"Solo CH%d — mutes all non-soloed channels", (int)(ch + 1)];  // v963 tooltip-coverage
        [stripContent addSubview:soloBtn];

        NSButton* muteBtn = [NSButton buttonWithTitle:@"M"
                                               target:self
                                               action:@selector(_mixMuteToggled_v548_:)];
        muteBtn.buttonType = NSButtonTypeToggle;
        muteBtn.font       = monoBF(9.0f);
        muteBtn.frame      = NSMakeRect(x + 2.0f + btnW + 2.0f, y - 18.0f, btnW, 18.0f);
        muteBtn.tag        = kArpSIDMixMuteTagBase + ch;
        muteBtn.state      = chModel.mute ? NSControlStateValueOn : NSControlStateValueOff;
        muteBtn.toolTip    = [NSString stringWithFormat:@"Mute CH%d", (int)(ch + 1)];  // v963 tooltip-coverage
        [stripContent addSubview:muteBtn];
        y -= 20.0f;

        // FX slots (5 dropdowns stacked)
        for (NSInteger slot = 0; slot < (NSInteger)ArpSID::GUI::kMixFxSlotsPerChannel; ++slot) {
            NSPopUpButton* fx = [[NSPopUpButton alloc]
                initWithFrame:NSMakeRect(x + 2.0f, y - 18.0f, chW - 4.0f, 18.0f)
                    pullsDown:NO];
            fx.font = monoBF(8.0f);
            for (NSString* itm in fxItems) [fx addItemWithTitle:itm];
            NSInteger fxIdx = (NSInteger)chModel.fxSlots[(size_t)slot].type;
            if (fxIdx >= 0 && fxIdx < (NSInteger)fxItems.count)
                [fx selectItemAtIndex:fxIdx];
            fx.tag    = kArpSIDMixFxTagBase + (ch << 3) + slot;
            fx.target = self;
            fx.action = @selector(_mixFxSlotChanged_v548_:);
            fx.toolTip = [NSString stringWithFormat:@"CH%d insert FX slot %ld", (int)(ch + 1), (long)(slot + 1)];  // v963 tooltip-coverage
            [stripContent addSubview:fx];
            y -= 20.0f;
        }
    }

    scroll.documentView = stripContent;
    [v addSubview:scroll];

    // ── Master section (right-pinned) ─────────────────────────────────────────
    CGFloat masterX = r.size.width - masterW - p;
    {
        NSTextField* hdr = [NSTextField labelWithString:@"◈ MASTER"];
        hdr.font = monoBF(11.0f); hdr.textColor = colTitle();
        hdr.frame = NSMakeRect(masterX, stripY + stripH - 18.0f, masterW, 16.0f);
        [v addSubview:hdr];

        // Master volume
        NSTextField* volLbl = [NSTextField labelWithString:@"Volume"];
        volLbl.font = monoBF(9.0f); volLbl.textColor = colLabel();
        volLbl.frame = NSMakeRect(masterX, stripY + stripH - 36.0f, masterW, 14.0f);
        [v addSubview:volLbl];
        NSSlider* mvol = [[NSSlider alloc]
            initWithFrame:NSMakeRect(masterX, stripY + stripH - 56.0f, masterW, 16.0f)];
        mvol.sliderType = NSSliderTypeLinear;
        mvol.vertical   = NO;
        mvol.minValue   = 0; mvol.maxValue = 255;
        mvol.intValue   = (int)_mixModel_v547_.master.masterVolume;
        mvol.tag        = kArpSIDMixMasterVolumeTag;
        mvol.target     = self;
        mvol.action     = @selector(_mixMasterVolumeChanged_v593_:);
        mvol.toolTip    = @"Master volume";
        [v addSubview:mvol];

        // Limiter toggle
        NSButton* limBtn = [NSButton checkboxWithTitle:@"Limiter"
                                                target:self
                                                action:@selector(_mixLimiterToggled_v593_:)];
        limBtn.font  = monoBF(9.0f);
        limBtn.tag   = kArpSIDMixLimiterEnableTag;
        limBtn.state = _mixModel_v547_.master.limiterEnabled
                         ? NSControlStateValueOn : NSControlStateValueOff;
        limBtn.frame = NSMakeRect(masterX, stripY + stripH - 78.0f, masterW, 18.0f);
        [v addSubview:limBtn];

        // Limiter threshold
        NSTextField* thrLbl = [NSTextField labelWithString:@"Threshold"];
        thrLbl.font = monoBF(9.0f); thrLbl.textColor = colLabel();
        thrLbl.frame = NSMakeRect(masterX, stripY + stripH - 96.0f, masterW, 14.0f);
        [v addSubview:thrLbl];
        NSSlider* thrSl = [[NSSlider alloc]
            initWithFrame:NSMakeRect(masterX, stripY + stripH - 114.0f, masterW, 16.0f)];
        thrSl.sliderType = NSSliderTypeLinear;
        thrSl.vertical   = NO;
        thrSl.minValue   = 0; thrSl.maxValue = 255;
        thrSl.intValue   = (int)_mixModel_v547_.master.limiterThreshold;
        thrSl.tag        = kArpSIDMixLimiterThresholdTag;
        thrSl.target     = self;
        thrSl.action     = @selector(_mixLimiterThresholdChanged_v593_:);
        thrSl.toolTip    = @"Limiter threshold";
        [v addSubview:thrSl];

        // Limiter release
        NSTextField* relLbl = [NSTextField labelWithString:@"Release"];
        relLbl.font = monoBF(9.0f); relLbl.textColor = colLabel();
        relLbl.frame = NSMakeRect(masterX, stripY + stripH - 132.0f, masterW, 14.0f);
        [v addSubview:relLbl];
        NSSlider* relSl = [[NSSlider alloc]
            initWithFrame:NSMakeRect(masterX, stripY + stripH - 150.0f, masterW, 16.0f)];
        relSl.sliderType = NSSliderTypeLinear;
        relSl.vertical   = NO;
        relSl.minValue   = 0; relSl.maxValue = 255;
        relSl.intValue   = (int)_mixModel_v547_.master.limiterRelease;
        relSl.tag        = kArpSIDMixLimiterReleaseTag;
        relSl.target     = self;
        relSl.action     = @selector(_mixLimiterReleaseChanged_v593_:);
        relSl.toolTip    = @"Limiter release";
        [v addSubview:relSl];

        // Stereo width
        NSTextField* widthLbl = [NSTextField labelWithString:@"Width"];
        widthLbl.font = monoBF(9.0f); widthLbl.textColor = colLabel();
        widthLbl.frame = NSMakeRect(masterX, stripY + stripH - 168.0f, masterW, 14.0f);
        [v addSubview:widthLbl];
        NSSlider* widthSl = [[NSSlider alloc]
            initWithFrame:NSMakeRect(masterX, stripY + stripH - 186.0f, masterW, 16.0f)];
        widthSl.sliderType = NSSliderTypeLinear;
        widthSl.vertical   = NO;
        widthSl.minValue   = 0; widthSl.maxValue = 255;
        widthSl.intValue   = (int)_mixModel_v547_.master.stereoWidth;
        widthSl.tag        = kArpSIDMixStereoWidthTag;
        widthSl.target     = self;
        widthSl.action     = @selector(_mixStereoWidthChanged_v593_:);
        widthSl.toolTip    = @"Stereo width";
        [v addSubview:widthSl];

        // Dim monitor
        NSButton* dimBtn = [NSButton checkboxWithTitle:@"Dim -10dB"
                                                target:self
                                                action:@selector(_mixDimMonitorToggled_v593_:)];
        dimBtn.font  = monoBF(9.0f);
        dimBtn.tag   = kArpSIDMixDimMonitorTag;
        dimBtn.state = _mixModel_v547_.master.dimMonitor
                         ? NSControlStateValueOn : NSControlStateValueOff;
        dimBtn.frame = NSMakeRect(masterX, stripY + stripH - 208.0f, masterW, 18.0f);
        [v addSubview:dimBtn];
    }

    // ── Send buses row (bottom strip) ─────────────────────────────────────────
    {
        NSString* busLabels[2] = { @"◈ DELAY BUS", @"◈ REVERB BUS" };
        CGFloat busW = (r.size.width - p * 3.0f) * 0.5f;
        for (NSInteger b = 0; b < 2; ++b) {
            CGFloat bx = p + (CGFloat)b * (busW + p);
            const ArpSID::GUI::MixSendBus& bus = _mixModel_v547_.sendBuses[(size_t)b];

            NSTextField* busHdr = [NSTextField labelWithString:busLabels[b]];
            busHdr.font = monoBF(10.0f); busHdr.textColor = colTitle();
            busHdr.frame = NSMakeRect(bx, p + sendH - 16.0f, 120.0f, 14.0f);
            [v addSubview:busHdr];

            NSButton* busEnable = [NSButton checkboxWithTitle:@"Enable"
                                                       target:self
                                                       action:@selector(_mixSendEnabledToggled_v593_:)];
            busEnable.font  = monoBF(9.0f);
            busEnable.tag   = kArpSIDMixSendEnableTagBase + b;
            busEnable.state = bus.enabled ? NSControlStateValueOn : NSControlStateValueOff;
            busEnable.frame = NSMakeRect(bx + 124.0f, p + sendH - 16.0f, 70.0f, 16.0f);
            [v addSubview:busEnable];

            NSTextField* retLbl = [NSTextField labelWithString:@"Return:"];
            retLbl.font = monoBF(9.0f); retLbl.textColor = colLabel();
            retLbl.frame = NSMakeRect(bx + 198.0f, p + sendH - 16.0f, 44.0f, 14.0f);
            [v addSubview:retLbl];

            NSSlider* retSl = [[NSSlider alloc]
                initWithFrame:NSMakeRect(bx + 244.0f, p + sendH - 18.0f, busW - 246.0f, 16.0f)];
            retSl.sliderType = NSSliderTypeLinear;
            retSl.vertical   = NO;
            retSl.minValue   = 0; retSl.maxValue = 255;
            retSl.intValue   = (int)bus.returnLevel;
            retSl.tag        = kArpSIDMixSendReturnTagBase + b;
            retSl.target     = self;
            retSl.action     = @selector(_mixSendReturnChanged_v593_:);
            retSl.toolTip    = @"Send return level";
            [v addSubview:retSl];
        }
    }

    return v;
}

// ── v556: KIT EDIT tab — action tags + handlers ───────────────────────────────

static constexpr NSInteger kArpSIDKitDrumTagBase   = 0x6000;  // drum class btn: base + dc
static constexpr NSInteger kArpSIDKitEngineTagBase = 0x6100;  // engine target btn: base + et
static constexpr NSInteger kArpSIDKitModeTagBase   = 0x6200;  // editor mode btn: base + mode
static constexpr NSInteger kArpSIDKitSlotTagBase   = 0x7000;  // user slot btn: base + slotIdx
static constexpr NSInteger kArpSIDKitStepTagBase   = 0x8000;  // step grid btn: base + stepIdx (0..31)
// v558 — note: step/voice editor container NSViews are tracked via iVars
// _pKitStepEdView_v558_ / _pKitVoiceEdView_v558_ (NSView.tag is readonly in AppKit).
// v558 — voice editor control tags
static constexpr NSInteger kArpSIDKitVoiceWaveTagBase    = 0xA000;  // wave btns: +0=TRI,+1=SAW,+2=PUL,+3=NOI
static constexpr NSInteger kArpSIDKitVoiceADSRTagBase    = 0xA010;  // ADSR steppers: +0=A,+1=D,+2=S,+3=R
static constexpr NSInteger kArpSIDKitVoiceADSRLblTagBase = 0xA014;  // ADSR value labels: +0=A,+1=D,+2=S,+3=R
static constexpr NSInteger kArpSIDKitVoicePWTag          = 0xA020;  // PW slider
static constexpr NSInteger kArpSIDKitVoicePWLabelTag     = 0xA021;  // PW value NSTextField
static constexpr NSInteger kArpSIDKitVoiceFlagTagBase    = 0xA030;  // flag btns: +0=RING,+1=SYNC,+2=FILT
// v559 — assign editor control tags
static constexpr NSInteger kArpSIDKitAssignSlotTag       = 0xB000;  // slot NSStepper
static constexpr NSInteger kArpSIDKitAssignSlotLblTag    = 0xB001;  // slot value label
static constexpr NSInteger kArpSIDKitAssignTuneTag       = 0xB010;  // tune NSStepper
static constexpr NSInteger kArpSIDKitAssignTuneLblTag    = 0xB011;  // tune value label
static constexpr NSInteger kArpSIDKitAssignStartTag      = 0xB020;  // start NSSlider
static constexpr NSInteger kArpSIDKitAssignStartLblTag   = 0xB021;  // start value label
static constexpr NSInteger kArpSIDKitAssignLenTag        = 0xB030;  // length NSSlider
static constexpr NSInteger kArpSIDKitAssignLenLblTag     = 0xB031;  // length value label
static constexpr NSInteger kArpSIDKitAssignFlagTagBase   = 0xB040;  // flag btns: +0=LOOP,+1=REV

-(void)_kitDrumClassChanged_v556_:(id)sender {
    NSButton* btn = (NSButton*)sender;
    NSInteger dc = btn.tag - kArpSIDKitDrumTagBase;
    if (dc < 0 || dc >= (NSInteger)ArpSID::GUI::kKitDrumClassCount) return;
    _kitModel_v555_.activeDrumClass = (uint8_t)dc;
    if (!_pKitV555) return;
    for (NSInteger i = 0; i < (NSInteger)ArpSID::GUI::kKitDrumClassCount; ++i) {
        NSButton* b = (NSButton*)[_pKitV555 viewWithTag:kArpSIDKitDrumTagBase + i];
        if (b) b.state = (i == dc) ? NSControlStateValueOn : NSControlStateValueOff;
    }
    // v557 — reload step grid buttons for the newly selected drum class.
    [self _kitRefreshStepGrid_v557_];
    // v558 — also reload voice editor if that mode is currently visible.
    if (_kitModel_v555_.activeEditorMode == 1u)
        [self _kitRefreshVoiceEditor_v558_];
    // v559 — also reload assign editor if that mode is currently visible.
    if (_kitModel_v555_.activeEditorMode == 2u)
        [self _kitRefreshAssignEditor_v559_];
    [self _pushKitStateToAdapter_v560_]; // v560 — persist after every model change
}

-(void)_kitEngineTargetChanged_v556_:(id)sender {
    NSButton* btn = (NSButton*)sender;
    NSInteger et = btn.tag - kArpSIDKitEngineTagBase;
    if (et < 0 || et >= (NSInteger)ArpSID::GUI::kKitEngineTargetCount) return;
    _kitModel_v555_.activeEngineTarget = (uint8_t)et;
    [self _pushKitStateToAdapter_v560_]; // v560
    if (!_pKitV555) return;
    for (NSInteger i = 0; i < (NSInteger)ArpSID::GUI::kKitEngineTargetCount; ++i) {
        NSButton* b = (NSButton*)[_pKitV555 viewWithTag:kArpSIDKitEngineTagBase + i];
        if (b) b.state = (i == et) ? NSControlStateValueOn : NSControlStateValueOff;
    }
}

-(void)_kitEditorModeChanged_v556_:(id)sender {
    NSButton* btn = (NSButton*)sender;
    NSInteger mode = btn.tag - kArpSIDKitModeTagBase;
    if (mode < 0 || mode >= (NSInteger)ArpSID::GUI::kKitEditorModeCount) return;
    _kitModel_v555_.activeEditorMode = (uint8_t)mode;
    if (!_pKitV555) return;
    for (NSInteger i = 0; i < (NSInteger)ArpSID::GUI::kKitEditorModeCount; ++i) {
        NSButton* b = (NSButton*)[_pKitV555 viewWithTag:kArpSIDKitModeTagBase + i];
        if (b) b.state = (i == mode) ? NSControlStateValueOn : NSControlStateValueOff;
    }
    // v558/v559 — show the relevant center sub-panel; hide the others.
    if (_pKitStepEdView_v558_)   _pKitStepEdView_v558_.hidden   = (mode != 0);
    if (_pKitVoiceEdView_v558_)  _pKitVoiceEdView_v558_.hidden  = (mode != 1);
    if (_pKitAssignEdView_v559_) _pKitAssignEdView_v559_.hidden = (mode != 2);
    if (mode == 0) [self _kitRefreshStepGrid_v557_];
    if (mode == 1) [self _kitRefreshVoiceEditor_v558_];
    if (mode == 2) [self _kitRefreshAssignEditor_v559_];
    [self _pushKitStateToAdapter_v560_]; // v560
}

-(void)_kitUserSlotSelected_v556_:(id)sender {
    NSButton* btn = (NSButton*)sender;
    NSInteger si = btn.tag - kArpSIDKitSlotTagBase;
    const uint8_t slotCount = ArpSID::GUI::kitSlotCount(
        (ArpSID::GUI::KitEngineTarget)_kitModel_v555_.activeEngineTarget);
    if (si < 0 || si >= (NSInteger)slotCount) return;
    _kitModel_v555_.activeUserSlot = (uint8_t)si;
    [self _pushKitStateToAdapter_v560_]; // v560
    if (!_pKitV555) return;
    for (NSInteger i = 0; i < (NSInteger)slotCount; ++i) {
        NSButton* b = (NSButton*)[_pKitV555 viewWithTag:kArpSIDKitSlotTagBase + i];
        if (b) b.state = (i == si) ? NSControlStateValueOn : NSControlStateValueOff;
    }
}

// ── v557: step grid action + refresh ─────────────────────────────────────────

/// Fired by each of the 32 step buttons in the center editor grid.
/// Reads activeDrumClass from _kitModel_v555_ to know which row of the grid
/// to mutate; toggles the corresponding step in _kitStepGrid_v557_; then
/// re-derives the button state from the model (rather than trusting the
/// PushOnPushOff toggle) to keep visual state consistent.
-(void)_kitStepToggled_v557_:(id)sender {
    NSButton* btn = (NSButton*)sender;
    const NSInteger rawIdx = btn.tag - kArpSIDKitStepTagBase;
    if (rawIdx < 0 || rawIdx >= (NSInteger)ArpSID::GUI::kKitStepCount) return;
    const uint8_t stepIdx  = (uint8_t)rawIdx;
    const uint8_t activeDC = _kitModel_v555_.activeDrumClass;
    ArpSID::GUI::kitStepToggle(_kitStepGrid_v557_, activeDC, stepIdx);
    // Re-derive from model so visual state is always consistent with data.
    const BOOL active = ArpSID::GUI::kitStepIsActive(_kitStepGrid_v557_, activeDC, stepIdx);
    btn.state = active ? NSControlStateValueOn : NSControlStateValueOff;
    [self _pushKitStateToAdapter_v560_]; // v560
}

/// Refreshes all 32 step-grid buttons to reflect _kitStepGrid_v557_ for the
/// currently active drum class. Call whenever activeDrumClass changes.
-(void)_kitRefreshStepGrid_v557_ {
    if (!_pKitV555) return;
    const uint8_t activeDC = _kitModel_v555_.activeDrumClass;
    for (NSInteger stepIdx = 0; stepIdx < (NSInteger)ArpSID::GUI::kKitStepCount; ++stepIdx) {
        NSButton* b = (NSButton*)[_pKitV555 viewWithTag:kArpSIDKitStepTagBase + stepIdx];
        if (!b) continue;
        const BOOL active = ArpSID::GUI::kitStepIsActive(
            _kitStepGrid_v557_, activeDC, (uint8_t)stepIdx);
        b.state = active ? NSControlStateValueOn : NSControlStateValueOff;
    }
}

// ── v558: voice editor actions + refresh ─────────────────────────────────────

/// Toggles one SID waveform bit for the active drum class.
-(void)_kitVoiceWaveChanged_v558_:(id)sender {
    NSButton* btn = (NSButton*)sender;
    NSInteger idx = btn.tag - kArpSIDKitVoiceWaveTagBase;  // 0=TRI,1=SAW,2=PUL,3=NOI
    if (idx < 0 || idx > 3) return;
    static const uint8_t kWaveBits[4] = {
        ArpSID::GUI::kKitVoiceWaveTri, ArpSID::GUI::kKitVoiceWaveSaw,
        ArpSID::GUI::kKitVoiceWavePul, ArpSID::GUI::kKitVoiceWaveNoi,
    };
    const uint8_t activeDC = _kitModel_v555_.activeDrumClass;
    ArpSID::GUI::kitVoiceToggleWaveBit(
        _kitVoiceConfigGrid_v558_.voiceConfigs[activeDC], kWaveBits[idx]);
    // Refresh whole voice editor so PW slider enable state also updates.
    [self _kitRefreshVoiceEditor_v558_];
    [self _pushKitStateToAdapter_v560_]; // v560
}

/// Updates one ADSR nibble when its NSStepper fires.
-(void)_kitVoiceADSRChanged_v558_:(id)sender {
    NSStepper* stp = (NSStepper*)sender;
    const NSInteger param = stp.tag - kArpSIDKitVoiceADSRTagBase;  // 0=A,1=D,2=S,3=R
    if (param < 0 || param > 3) return;
    const uint8_t val = (uint8_t)std::min(15.0, std::max(0.0, stp.doubleValue));
    const uint8_t activeDC = _kitModel_v555_.activeDrumClass;
    ArpSID::GUI::KitVoiceConfig& cfg = _kitVoiceConfigGrid_v558_.voiceConfigs[activeDC];
    switch (param) {
        case 0: ArpSID::GUI::kitVoiceSetAttack(cfg,   val); break;
        case 1: ArpSID::GUI::kitVoiceSetDecay(cfg,    val); break;
        case 2: ArpSID::GUI::kitVoiceSetSustain(cfg,  val); break;
        case 3: ArpSID::GUI::kitVoiceSetRelease(cfg,  val); break;
    }
    // Update paired value label.
    NSTextField* lbl = (NSTextField*)[_pKitV555 viewWithTag:kArpSIDKitVoiceADSRLblTagBase + param];
    if (lbl) lbl.stringValue = [NSString stringWithFormat:@"%d", (int)val];
    [self _pushKitStateToAdapter_v560_]; // v560
}

/// Updates pulse width when the PW slider moves.
-(void)_kitVoicePWChanged_v558_:(id)sender {
    NSSlider* slider = (NSSlider*)sender;
    const uint16_t pw = (uint16_t)std::min(4095.0, std::max(0.0, slider.doubleValue));
    const uint8_t activeDC = _kitModel_v555_.activeDrumClass;
    ArpSID::GUI::kitVoiceSetPulseWidth(
        _kitVoiceConfigGrid_v558_.voiceConfigs[activeDC], pw);
    NSTextField* lbl = (NSTextField*)[_pKitV555 viewWithTag:kArpSIDKitVoicePWLabelTag];
    if (lbl) lbl.stringValue = [NSString stringWithFormat:@"%d", (int)pw];
    [self _pushKitStateToAdapter_v560_]; // v560
}

/// Toggles one voice flag button (ring mod / hard sync / filter route).
-(void)_kitVoiceFlagChanged_v558_:(id)sender {
    NSButton* btn = (NSButton*)sender;
    const NSInteger flagIdx = btn.tag - kArpSIDKitVoiceFlagTagBase;  // 0=ring,1=sync,2=filt
    if (flagIdx < 0 || flagIdx > 2) return;
    const uint8_t activeDC = _kitModel_v555_.activeDrumClass;
    ArpSID::GUI::KitVoiceConfig& cfg = _kitVoiceConfigGrid_v558_.voiceConfigs[activeDC];
    BOOL nowOn = NO;
    switch (flagIdx) {
        case 0:
            ArpSID::GUI::kitVoiceSetRingMod(cfg, !ArpSID::GUI::kitVoiceRingMod(cfg));
            nowOn = ArpSID::GUI::kitVoiceRingMod(cfg); break;
        case 1:
            ArpSID::GUI::kitVoiceSetHardSync(cfg, !ArpSID::GUI::kitVoiceHardSync(cfg));
            nowOn = ArpSID::GUI::kitVoiceHardSync(cfg); break;
        case 2:
            ArpSID::GUI::kitVoiceSetFilterRoute(cfg, !ArpSID::GUI::kitVoiceFilterRoute(cfg));
            nowOn = ArpSID::GUI::kitVoiceFilterRoute(cfg); break;
    }
    btn.state = nowOn ? NSControlStateValueOn : NSControlStateValueOff;
    [self _pushKitStateToAdapter_v560_]; // v560
}

/// Refreshes all voice editor controls to reflect _kitVoiceConfigGrid_v558_
/// for the currently active drum class. Call whenever activeDrumClass or
/// activeEditorMode changes to VoiceEditor.
-(void)_kitRefreshVoiceEditor_v558_ {
    if (!_pKitV555) return;
    const uint8_t activeDC = _kitModel_v555_.activeDrumClass;
    const ArpSID::GUI::KitVoiceConfig& cfg =
        _kitVoiceConfigGrid_v558_.voiceConfigs[activeDC];

    // Waveform buttons.
    static const uint8_t kWaveBits[4] = {
        ArpSID::GUI::kKitVoiceWaveTri, ArpSID::GUI::kKitVoiceWaveSaw,
        ArpSID::GUI::kKitVoiceWavePul, ArpSID::GUI::kKitVoiceWaveNoi,
    };
    for (NSInteger i = 0; i < 4; ++i) {
        NSButton* b = (NSButton*)[_pKitV555 viewWithTag:kArpSIDKitVoiceWaveTagBase + i];
        if (b) b.state = ArpSID::GUI::kitVoiceIsWave(cfg, kWaveBits[i])
                         ? NSControlStateValueOn : NSControlStateValueOff;
    }

    // ADSR steppers + value labels.
    const uint8_t adVals[4] = {
        ArpSID::GUI::kitVoiceAttack(cfg),   ArpSID::GUI::kitVoiceDecay(cfg),
        ArpSID::GUI::kitVoiceSustain(cfg),  ArpSID::GUI::kitVoiceRelease(cfg),
    };
    for (NSInteger i = 0; i < 4; ++i) {
        NSStepper* stp = (NSStepper*)[_pKitV555 viewWithTag:kArpSIDKitVoiceADSRTagBase + i];
        if (stp) stp.doubleValue = (double)adVals[i];
        NSTextField* lbl = (NSTextField*)[_pKitV555 viewWithTag:kArpSIDKitVoiceADSRLblTagBase + i];
        if (lbl) lbl.stringValue = [NSString stringWithFormat:@"%d", (int)adVals[i]];
    }

    // PW slider + label (slider only enabled when pulse waveform is active).
    const uint16_t pw = ArpSID::GUI::kitVoicePulseWidth(cfg);
    NSSlider* pwSlider = (NSSlider*)[_pKitV555 viewWithTag:kArpSIDKitVoicePWTag];
    if (pwSlider) {
        pwSlider.doubleValue = (double)pw;
        pwSlider.enabled = ArpSID::GUI::kitVoiceIsWave(cfg, ArpSID::GUI::kKitVoiceWavePul);
    }
    NSTextField* pwLbl = (NSTextField*)[_pKitV555 viewWithTag:kArpSIDKitVoicePWLabelTag];
    if (pwLbl) pwLbl.stringValue = [NSString stringWithFormat:@"%d", (int)pw];

    // Flag buttons.
    const BOOL flagVals[3] = {
        ArpSID::GUI::kitVoiceRingMod(cfg),
        ArpSID::GUI::kitVoiceHardSync(cfg),
        ArpSID::GUI::kitVoiceFilterRoute(cfg),
    };
    for (NSInteger i = 0; i < 3; ++i) {
        NSButton* b = (NSButton*)[_pKitV555 viewWithTag:kArpSIDKitVoiceFlagTagBase + i];
        if (b) b.state = flagVals[i] ? NSControlStateValueOn : NSControlStateValueOff;
    }
}

