// ── v560: KIT state persistence — push/pull helpers ──────────────────────────

/// Packs all four KIT iVar models into a KitStateBlob and pushes to the adapter.
/// Called at the end of every KIT action handler so AU state is always current.
-(void)_pushKitStateToAdapter_v560_ {
    if(![self _requireBridgeForAction:[NSString stringWithUTF8String:__func__]]) return;
    id adapter = [_au debugAdapter];
    if (!adapter || ![adapter respondsToSelector:@selector(setKitStateBlob:)]) return;
    ArpSID::GUI::KitStateBlob blob{};
    ArpSID::GUI::kitStateBlobPack(blob,
        _kitModel_v555_,
        _kitStepGrid_v557_,
        _kitVoiceConfigGrid_v558_,
        _kitAssignConfigGrid_v559_);
    [(id<ArpSIDDebugAdapterLike>)adapter setKitStateBlob:&blob];
}

/// Pulls the KIT state blob from the adapter, unpacks into the four iVar models,
/// and refreshes all KIT UI controls. Called in _connectBridgeInternal: after
/// a project is restored so the KIT tab reflects the persisted state.
-(void)_pullKitStateFromAdapter_v560_ {
    if(![self _requireBridgeForAction:[NSString stringWithUTF8String:__func__]]) return;
    id adapter = [_au debugAdapter];
    if (!adapter || ![adapter respondsToSelector:@selector(getKitStateBlob:)]) return;
    ArpSID::GUI::KitStateBlob blob{};
    [(id<ArpSIDDebugAdapterLike>)adapter getKitStateBlob:&blob];
    const bool kitWasWellFormed = ArpSID::GUI::kitStateBlobIsWellFormed(blob);
    ArpSID::GUI::kitStateBlobSanitize(blob);
    if (!kitWasWellFormed) {
        if (_drumHUDLabel) _drumHUDLabel.stringValue = @"KIT repaired after adapter pull";
        if ([adapter respondsToSelector:@selector(setKitStateBlob:)]) [(id<ArpSIDDebugAdapterLike>)adapter setKitStateBlob:&blob];
    }
    if ([adapter respondsToSelector:@selector(getKitStateBlob:)] && [adapter respondsToSelector:@selector(setKitStateBlob:)]) {
        ArpSID::GUI::KitStateBlob verify{};
        [(id<ArpSIDDebugAdapterLike>)adapter getKitStateBlob:&verify];
        if (!ArpSID::GUI::kitStateBlobIsWellFormed(verify)) {
            ArpSID::GUI::kitStateBlobSanitize(verify);
            [(id<ArpSIDDebugAdapterLike>)adapter setKitStateBlob:&verify];
            blob = verify;
            if (_drumHUDLabel) _drumHUDLabel.stringValue = @"KIT repaired after round-trip verify";
        }
    }
    ArpSID::GUI::kitStateBlobUnpack(blob,
        _kitModel_v555_,
        _kitStepGrid_v557_,
        _kitVoiceConfigGrid_v558_,
        _kitAssignConfigGrid_v559_);
    // Refresh all KIT controls to reflect the restored models.
    if (!_pKitV555) return;
    // Drum class buttons.
    for (NSInteger dc = 0; dc < (NSInteger)ArpSID::GUI::kKitDrumClassCount; ++dc) {
        NSButton* b = (NSButton*)[_pKitV555 viewWithTag:kArpSIDKitDrumTagBase + dc];
        if (b) b.state = (dc == (NSInteger)_kitModel_v555_.activeDrumClass)
                         ? NSControlStateValueOn : NSControlStateValueOff;
    }
    // Engine target buttons.
    for (NSInteger et = 0; et < (NSInteger)ArpSID::GUI::kKitEngineTargetCount; ++et) {
        NSButton* b = (NSButton*)[_pKitV555 viewWithTag:kArpSIDKitEngineTagBase + et];
        if (b) b.state = (et == (NSInteger)_kitModel_v555_.activeEngineTarget)
                         ? NSControlStateValueOn : NSControlStateValueOff;
    }
    // Editor mode buttons + editor panel visibility.
    const uint8_t mode = _kitModel_v555_.activeEditorMode;
    for (NSInteger m = 0; m < (NSInteger)ArpSID::GUI::kKitEditorModeCount; ++m) {
        NSButton* b = (NSButton*)[_pKitV555 viewWithTag:kArpSIDKitModeTagBase + m];
        if (b) b.state = (m == (NSInteger)mode)
                         ? NSControlStateValueOn : NSControlStateValueOff;
    }
    if (_pKitStepEdView_v558_)   _pKitStepEdView_v558_.hidden   = (mode != 0);
    if (_pKitVoiceEdView_v558_)  _pKitVoiceEdView_v558_.hidden  = (mode != 1);
    if (_pKitAssignEdView_v559_) _pKitAssignEdView_v559_.hidden = (mode != 2);
    // Refresh the active editor.
    [self _kitRefreshStepGrid_v557_];
    if (mode == 1) [self _kitRefreshVoiceEditor_v558_];
    if (mode == 2) [self _kitRefreshAssignEditor_v559_];
}

// ── DIGI tab — namespaced tag constants, action handlers, refresh helpers ─────────

static constexpr NSInteger kArpSIDDigiSlotTagBase       = 0xC000; // slot btn: base + slot (0..7)
static constexpr NSInteger kArpSIDDigiStepTagBase       = 0xC100; // step btn: base + step (0..31)
static constexpr NSInteger kArpSIDDigiSourceTag         = 0xC200; // source type NSPopUpButton
static constexpr NSInteger kArpSIDDigiFactorySlotTag    = 0xC201; // factory slot NSStepper
static constexpr NSInteger kArpSIDDigiFactorySlotLblTag = 0xC202; // factory slot label
static constexpr NSInteger kArpSIDDigiTuneTag           = 0xC210; // tune NSStepper
static constexpr NSInteger kArpSIDDigiTuneLblTag        = 0xC211; // tune label
static constexpr NSInteger kArpSIDDigiStartTag          = 0xC220; // start offset NSSlider
static constexpr NSInteger kArpSIDDigiStartLblTag       = 0xC221; // start offset label
static constexpr NSInteger kArpSIDDigiLenTag            = 0xC230; // length NSSlider
static constexpr NSInteger kArpSIDDigiLenLblTag         = 0xC231; // length label
static constexpr NSInteger kArpSIDDigiVolTag            = 0xC240; // volume NSSlider
static constexpr NSInteger kArpSIDDigiVolLblTag         = 0xC241; // volume label
static constexpr NSInteger kArpSIDDigiFlagTagBase       = 0xC250; // flag btn: base + bit (0=LOOP,1=REV)
static constexpr NSInteger kArpSIDDigiImportTag         = 0xC260; // Import button
static constexpr NSInteger kArpSIDDigiClearUserTag      = 0xC261; // Clear user-sample button
static constexpr NSInteger kArpSIDDigiUserNameLblTag    = 0xC262; // saved user-sample status label
static constexpr NSInteger kArpSIDDigiRecordTag         = 0xC263; // Record/stop input button
static constexpr NSInteger kArpSIDDigiRecordInputTag    = 0xC264; // REC input source popup
static constexpr NSInteger kArpSIDDigiPreviewTag        = 0xC279; // live REC-source preview meter toggle
static constexpr NSInteger kArpSIDDigiRecordKeepTag     = 0xC265; // KEEP pending take button
static constexpr NSInteger kArpSIDDigiRecordDiscardTag  = 0xC266; // DISCARD pending take button
static constexpr NSInteger kArpSIDDigiExportTag         = 0xC267; // export active user sample
static constexpr NSInteger kArpSIDDigiRenameTag         = 0xC268; // rename active user sample
static constexpr NSInteger kArpSIDDigiCopyTag           = 0xC269; // copy active slot sample
static constexpr NSInteger kArpSIDDigiSwapTag           = 0xC26A; // swap active slot with next slot
static constexpr NSInteger kArpSIDDigiKitExportTag      = 0xC26B; // export DIGI kit blob
static constexpr NSInteger kArpSIDDigiKitImportTag      = 0xC26C; // import DIGI kit blob
static constexpr NSInteger kArpSIDDigiConvertTag        = 0xC26D; // conversion weighting popup
static constexpr NSInteger kArpSIDDigiNormalizeTag      = 0xC26E; // normalize toggle
static constexpr NSInteger kArpSIDDigiTrimTag           = 0xC26F; // trim toggle
static constexpr NSInteger kArpSIDDigiRecordMeterTag    = 0xC270; // record progress/level HUD label
static constexpr NSInteger kArpSIDDigiAuditionTag       = 0xC271; // audition active slot through render queue
static constexpr NSInteger kArpSIDDigiMidiLearnTag      = 0xC272; // learn root/channel from last MIDI note telemetry
static constexpr NSInteger kArpSIDDigiDragStatusTag     = 0xC273; // drag/drop import status label
static constexpr NSInteger kArpSIDDigiClearAllTag       = 0xC274; // clear full 8-slot user sample bank
static constexpr NSInteger kArpSIDDigiPasteTag          = 0xC275; // paste copied DIGI sample into active slot
static constexpr NSInteger kArpSIDDigiTrimStartTag      = 0xC276; // destructive trim-start percent
static constexpr NSInteger kArpSIDDigiTrimEndTag        = 0xC277; // destructive trim-end percent
static constexpr NSInteger kArpSIDDigiTrimApplyTag      = 0xC278; // apply destructive trim to active sample

static_assert(kArpSIDMixFxTagBase >= 0x1000 && kArpSIDMixDimMonitorTag < 0x6000,
              "MIX tags must stay in the 0x1000-0x5FFF range");
static_assert(kArpSIDKitDrumTagBase >= 0x6000 && (kArpSIDKitAssignFlagTagBase + 8) < kArpSIDDigiSlotTagBase,
              "KIT tags must stay in the 0x6000-0xBFFF range and not collide with DIGI tags");
static_assert(kArpSIDDigiSlotTagBase >= 0xC000 && kArpSIDDigiTrimApplyTag < 0xC300,
              "DIGI tags must stay in the 0xC000-0xC2FF range");

struct ArpSIDDigiKitFileHeader_v201 {
    char magic[8]; // "ASDIGI\0"
    std::uint32_t version;
    std::uint32_t modelBytes;
    std::uint32_t sampleBankBytes;
    std::uint32_t payloadHash;
};
static constexpr char kArpSIDDigiKitMagic_v201[8] = {'A','S','D','I','G','I','\0','\0'};
static constexpr std::uint32_t kArpSIDDigiKitVersion_v201 = 201u;
static NSString* const kArpSIDDigiRecordInputPureSid1Q1UID_v230 = @"__ARPSID_REC_SOURCE_PURE_SID_1Q1__";
static NSString* const kArpSIDDigiRecordInputCoreAudioOutputPrefix_v236 = @"__ARPSID_REC_SOURCE_COREAUDIO_OUTPUT__:";

struct ArpSIDDigiRecordPreparedMono_v161 {
    std::vector<float> samples;
    std::uint32_t inputFrames = 0u;
    std::uint32_t trimmedFrames = 0u;
    float peakBeforeNormalize = 0.0f;
    bool normalized = false;
    bool truncatedToD418 = false;
};

static NSString* ArpSIDDigiConvertModeName_v199(ArpSIDDigiConvertMode_v199 mode) {
    switch (mode) {
        case ArpSIDDigiConvertMode_v199::Loud:   return @"LOUD";
        case ArpSIDDigiConvertMode_v199::MuLaw:  return @"µLAW";
        case ArpSIDDigiConvertMode_v199::Dither: return @"DITHER";
        case ArpSIDDigiConvertMode_v199::Linear:
        default: return @"LINEAR";
    }
}

static float ArpSIDDigiApplyConversion_v199(float v, ArpSIDDigiConvertMode_v199 mode, std::uint32_t index) noexcept {
    if (!std::isfinite(v)) v = 0.0f;
    v = std::clamp(v, -1.0f, 1.0f);
    switch (mode) {
        case ArpSIDDigiConvertMode_v199::Loud: {
            const float sign = v < 0.0f ? -1.0f : 1.0f;
            return std::clamp(sign * std::sqrt(std::fabs(v)), -1.0f, 1.0f);
        }
        case ArpSIDDigiConvertMode_v199::MuLaw: {
            constexpr float mu = 15.0f;
            const float sign = v < 0.0f ? -1.0f : 1.0f;
            return std::clamp(sign * std::log1p(mu * std::fabs(v)) / std::log1p(mu), -1.0f, 1.0f);
        }
        case ArpSIDDigiConvertMode_v199::Dither: {
            std::uint32_t x = index * 1664525u + 1013904223u;
            x ^= x >> 16u; x *= 2246822519u; x ^= x >> 13u;
            const float n = ((float)(x & 0xFFFFu) / 65535.0f - 0.5f) * (2.0f / 15.0f);
            return std::clamp(v + n, -1.0f, 1.0f);
        }
        case ArpSIDDigiConvertMode_v199::Linear:
        default: return v;
    }
}


// robust live-source metering for AVAudioEngine taps.
// AVAudioEngine input taps are not guaranteed to deliver non-interleaved float
// buffers on every CoreAudio route. The previous MON/REC path only read
// floatChannelData, so interleaved float, Int16 and Int32 devices could meter as
// all-zero even while the source was playing. This helper accepts the concrete
// PCM layout delivered by the tap and returns a real mono sample.
static BOOL ArpSIDDigiAudioBufferHasReadableFrame_v239(const AudioBuffer& ab,
                                                              AVAudioCommonFormat cf,
                                                              UInt32 channels,
                                                              NSUInteger frame,
                                                              BOOL interleaved) noexcept {
    if (!ab.mData) return NO;
    const UInt32 ch = std::max<UInt32>(1u, channels);
    std::size_t sampleBytes = 0u;
    if (cf == AVAudioPCMFormatFloat32 || cf == AVAudioPCMFormatInt32) sampleBytes = 4u;
    else if (cf == AVAudioPCMFormatInt16) sampleBytes = 2u;
    else return NO;
    const std::size_t stride = interleaved ? static_cast<std::size_t>(ch) : 1u;
    const std::size_t needed = (static_cast<std::size_t>(frame) * stride + (interleaved ? ch : 1u)) * sampleBytes;
    return needed <= static_cast<std::size_t>(ab.mDataByteSize) ? YES : NO;
}

static float ArpSIDDigiPCMBufferMonoSample_v238(AVAudioPCMBuffer* buffer, NSUInteger frame) noexcept {
    if (!buffer || frame >= (NSUInteger)buffer.frameLength) return 0.0f;
    const UInt32 channels = buffer.format.channelCount;
    if (channels == 0u) return 0.0f;

    if (float* const* f = buffer.floatChannelData) {
        float sum = 0.0f; UInt32 valid = 0u;
        for (UInt32 ch = 0u; ch < channels; ++ch) {
            const float* cd = f[ch];
            if (!cd) continue;
            const float v = cd[frame];
            if (!std::isfinite(v)) continue;
            sum += v; ++valid;
        }
        return valid ? std::clamp(sum / (float)valid, -1.0f, 1.0f) : 0.0f;
    }

    if (int16_t* const* i16 = buffer.int16ChannelData) {
        float sum = 0.0f; UInt32 valid = 0u;
        for (UInt32 ch = 0u; ch < channels; ++ch) {
            const int16_t* cd = i16[ch];
            if (!cd) continue;
            sum += std::clamp((float)cd[frame] / 32768.0f, -1.0f, 1.0f); ++valid;
        }
        return valid ? std::clamp(sum / (float)valid, -1.0f, 1.0f) : 0.0f;
    }

    if (int32_t* const* i32 = buffer.int32ChannelData) {
        float sum = 0.0f; UInt32 valid = 0u;
        for (UInt32 ch = 0u; ch < channels; ++ch) {
            const int32_t* cd = i32[ch];
            if (!cd) continue;
            sum += std::clamp((float)((double)cd[frame] / 2147483648.0), -1.0f, 1.0f); ++valid;
        }
        return valid ? std::clamp(sum / (float)valid, -1.0f, 1.0f) : 0.0f;
    }

    const AudioBufferList* abl = buffer.audioBufferList;
    if (!abl || abl->mNumberBuffers == 0u) return 0.0f;
    const AVAudioCommonFormat cf = buffer.format.commonFormat;
    if (abl->mNumberBuffers == 1u && abl->mBuffers[0].mData) {
        const UInt32 interleavedChannels = std::max<UInt32>(1u, channels);
        if (!ArpSIDDigiAudioBufferHasReadableFrame_v239(abl->mBuffers[0], cf, interleavedChannels, frame, YES)) return 0.0f;
        float sum = 0.0f; UInt32 valid = 0u;
        if (cf == AVAudioPCMFormatFloat32) {
            const float* data = static_cast<const float*>(abl->mBuffers[0].mData);
            for (UInt32 ch = 0u; ch < interleavedChannels; ++ch) {
                const float v = data[frame * interleavedChannels + ch];
                if (!std::isfinite(v)) continue;
                sum += v; ++valid;
            }
        } else if (cf == AVAudioPCMFormatInt16) {
            const int16_t* data = static_cast<const int16_t*>(abl->mBuffers[0].mData);
            for (UInt32 ch = 0u; ch < interleavedChannels; ++ch) {
                sum += std::clamp((float)data[frame * interleavedChannels + ch] / 32768.0f, -1.0f, 1.0f); ++valid;
            }
        } else if (cf == AVAudioPCMFormatInt32) {
            const int32_t* data = static_cast<const int32_t*>(abl->mBuffers[0].mData);
            for (UInt32 ch = 0u; ch < interleavedChannels; ++ch) {
                sum += std::clamp((float)((double)data[frame * interleavedChannels + ch] / 2147483648.0), -1.0f, 1.0f); ++valid;
            }
        }
        return valid ? std::clamp(sum / (float)valid, -1.0f, 1.0f) : 0.0f;
    }

    float sum = 0.0f; UInt32 valid = 0u;
    for (UInt32 b = 0u; b < abl->mNumberBuffers; ++b) {
        const AudioBuffer& ab = abl->mBuffers[b];
        if (!ab.mData || !ArpSIDDigiAudioBufferHasReadableFrame_v239(ab, cf, 1u, frame, NO)) continue;
        if (cf == AVAudioPCMFormatFloat32) {
            const float* data = static_cast<const float*>(ab.mData);
            const float v = data[frame];
            if (!std::isfinite(v)) continue;
            sum += v; ++valid;
        } else if (cf == AVAudioPCMFormatInt16) {
            const int16_t* data = static_cast<const int16_t*>(ab.mData);
            sum += std::clamp((float)data[frame] / 32768.0f, -1.0f, 1.0f); ++valid;
        } else if (cf == AVAudioPCMFormatInt32) {
            const int32_t* data = static_cast<const int32_t*>(ab.mData);
            sum += std::clamp((float)((double)data[frame] / 2147483648.0), -1.0f, 1.0f); ++valid;
        }
    }
    return valid ? std::clamp(sum / (float)valid, -1.0f, 1.0f) : 0.0f;
}


static inline float ArpSIDDigiSanitizeUnitMetric_v271(float v) noexcept {
    if (!std::isfinite(v)) return 0.0f;
    return std::clamp(v, 0.0f, 1.0f);
}

static inline float ArpSIDDigiRmsFromSumSq_v271(double sumSq, std::uint32_t count) noexcept {
    if (count == 0u || !std::isfinite(sumSq) || sumSq <= 0.0) return 0.0f;
    return ArpSIDDigiSanitizeUnitMetric_v271(static_cast<float>(std::sqrt(sumSq / static_cast<double>(count))));
}

static bool ArpSIDDigiPrepareRecordVector_v326(std::vector<float>& buffer,
                                               std::size_t frames) noexcept {
    try {
        if (buffer.size() != frames) buffer.assign(frames, 0.0f);
        else std::fill(buffer.begin(), buffer.end(), 0.0f);
        return buffer.size() == frames;
    } catch (...) {
        // Callers invoke this only after tap/AQ callbacks are quiescent, so
        // clearing failed storage cannot invalidate a callback-owned pointer.
        buffer.clear();
        return false;
    }
}

static BOOL ArpSIDDigiPCMBufferHasReadableSamples_v238(AVAudioPCMBuffer* buffer) noexcept {
    if (!buffer || buffer.frameLength == 0u || buffer.format.channelCount == 0u) return NO;
    if (buffer.floatChannelData || buffer.int16ChannelData || buffer.int32ChannelData) return YES;
    const AudioBufferList* abl = buffer.audioBufferList;
    if (!abl || abl->mNumberBuffers == 0u) return NO;
    const AVAudioCommonFormat cf = buffer.format.commonFormat;
    if (abl->mNumberBuffers == 1u) {
        return ArpSIDDigiAudioBufferHasReadableFrame_v239(abl->mBuffers[0], cf, std::max<UInt32>(1u, buffer.format.channelCount), 0u, YES);
    }
    for (UInt32 b = 0u; b < abl->mNumberBuffers; ++b) {
        if (ArpSIDDigiAudioBufferHasReadableFrame_v239(abl->mBuffers[b], cf, 1u, 0u, NO)) return YES;
    }
    return NO;
}

// ─── real CoreAudio output / system-audio capture backend ────────────
// The "CoreAudio Output Monitor" REC/MON source used to be fail-closed: it only
// worked if an *input* device existed with the same UID as the chosen output
// (i.e. a manually-routed BlackHole/Loopback/aggregate). Ordinary outputs
// (speakers, headphones, HDMI, USB DAC) metered zero. This backend implements
// genuine output capture using the macOS 14.2+ Core Audio process-tap API:
// CATapDescription (global stereo tap, unmuted, private)
// → AudioHardwareCreateProcessTap
// → private aggregate device whose main sub-device is the chosen output and
// whose tap-list contains the process tap
// → AudioDeviceIOProcID block delivering the tapped output audio
// The IOProc mixes to mono and feeds the same record buffer / preview meters as
// the input-tap path. No BlackHole required; the user's playback is not muted.

// RT-safe mixdown of a tap IOProc input buffer list (Float32) to mono.
// the raw reader only handles little-endian, non-aligned-high PCM at
// 16/24/32-bit int or 32-bit float. Detect anything else so the IOProc can fail
// closed and report "unsupported format" instead of reading garbage as floats.
static uint32_t ArpSIDDigiTapChannelSlotBytes_v254(const AudioStreamBasicDescription& a, uint32_t bufferChannels) noexcept {
    if (a.mBitsPerChannel == 0u) return 0u;
    const uint32_t bytesPerPayload = (a.mBitsPerChannel + 7u) / 8u;
    const bool nonInterleaved = (a.mFormatFlags & kAudioFormatFlagIsNonInterleaved) != 0;
    if (nonInterleaved) {
        if (a.mBytesPerFrame < bytesPerPayload) return 0u;
        return a.mBytesPerFrame;
    }
    const uint32_t ch = bufferChannels ? bufferChannels : a.mChannelsPerFrame;
    if (ch == 0u || a.mBytesPerFrame == 0u || (a.mBytesPerFrame % ch) != 0u) return 0u;
    const uint32_t slot = a.mBytesPerFrame / ch;
    if (slot < bytesPerPayload) return 0u;
    return slot;
}

static bool ArpSIDDigiTapASBDSupported_v253(const AudioStreamBasicDescription& a) noexcept {
    if (a.mFormatID != kAudioFormatLinearPCM) return false;
    if (a.mBitsPerChannel == 0u || a.mChannelsPerFrame == 0u) return false;
    if (a.mFormatFlags & kAudioFormatFlagIsBigEndian) return false;
    if (a.mFormatFlags & kAudioFormatFlagIsAlignedHigh) return false;
    const bool isFloat = (a.mFormatFlags & kAudioFormatFlagIsFloat) != 0;
    const bool isSigned = (a.mFormatFlags & kAudioFormatFlagIsSignedInteger) != 0;
    const bool nonInterleaved = (a.mFormatFlags & kAudioFormatFlagIsNonInterleaved) != 0;
    const uint32_t channelsForSlot = nonInterleaved ? 1u : a.mChannelsPerFrame;
    const uint32_t slot = ArpSIDDigiTapChannelSlotBytes_v254(a, channelsForSlot);
    if (isFloat && a.mBitsPerChannel == 32 && slot == 4u) return true;
    if (isSigned && a.mBitsPerChannel == 16 && slot == 2u) return true;
    if (isSigned && a.mBitsPerChannel == 24 && slot == 3u) return true; // packed 24 only; reject 24-in-32 until implemented
    if (isSigned && a.mBitsPerChannel == 32 && slot == 4u) return true;
    return false;
}

enum class ArpSIDDigiTapReadStatus_v254 : uint8_t { Ok, Unsupported };

// read one sample from raw bytes per the tap's actual ASBD. Unsupported
// is reported as status, never as a fake 0.0 sample, so diagnostics can separate
// real silence from unconvertible CoreAudio layouts.
static ArpSIDDigiTapReadStatus_v254 ArpSIDDigiReadSampleFromRaw_v254(const uint8_t* p,
                                                                     const AudioStreamBasicDescription& asbd,
                                                                     float& out) noexcept {
    out = 0.0f;
    if (!p || !ArpSIDDigiTapASBDSupported_v253(asbd)) return ArpSIDDigiTapReadStatus_v254::Unsupported;
    const bool isFloat = (asbd.mFormatFlags & kAudioFormatFlagIsFloat) != 0;
    const bool isSigned = (asbd.mFormatFlags & kAudioFormatFlagIsSignedInteger) != 0;
    if (isFloat && asbd.mBitsPerChannel == 32) {
        float v = 0.0f; std::memcpy(&v, p, sizeof(float));
        out = std::isfinite(v) ? std::clamp(v, -1.0f, 1.0f) : 0.0f;
        return ArpSIDDigiTapReadStatus_v254::Ok;
    }
    if (isSigned && asbd.mBitsPerChannel == 16) {
        int16_t v = 0; std::memcpy(&v, p, sizeof(int16_t));
        out = std::clamp((float)v / 32768.0f, -1.0f, 1.0f);
        return ArpSIDDigiTapReadStatus_v254::Ok;
    }
    if (isSigned && asbd.mBitsPerChannel == 24) {
        int32_t v = ((int32_t)p[0]) | ((int32_t)p[1] << 8) | ((int32_t)p[2] << 16);
        if (v & 0x00800000) v |= (int32_t)0xff000000u;
        out = std::clamp((float)v / 8388608.0f, -1.0f, 1.0f);
        return ArpSIDDigiTapReadStatus_v254::Ok;
    }
    if (isSigned && asbd.mBitsPerChannel == 32) {
        int32_t v = 0; std::memcpy(&v, p, sizeof(int32_t));
        out = std::clamp((float)((double)v / 2147483648.0), -1.0f, 1.0f);
        return ArpSIDDigiTapReadStatus_v254::Ok;
    }
    return ArpSIDDigiTapReadStatus_v254::Unsupported;
}

static uint32_t ArpSIDDigiOutputTapMixMonoFromASBD_v250(const AudioBufferList* abl,
                                                        const AudioStreamBasicDescription& asbd,
                                                        float* outMono,
                                                        uint32_t maxFrames) noexcept {
    if (!abl || abl->mNumberBuffers == 0u || !outMono || maxFrames == 0u) return 0u;
    if (!ArpSIDDigiTapASBDSupported_v253(asbd)) return 0u;
    const bool nonInterleaved = (asbd.mFormatFlags & kAudioFormatFlagIsNonInterleaved) != 0;
    const uint32_t declaredChannels = std::max<uint32_t>(1u, asbd.mChannelsPerFrame);
    const uint32_t payloadBytes = (asbd.mBitsPerChannel + 7u) / 8u;
    for (uint32_t f = 0; f < maxFrames; ++f) outMono[f] = 0.0f;
    uint32_t frames = maxFrames;
    bool sawFrames = false;
    uint32_t contributors = 0u;

    if (nonInterleaved) {
        for (UInt32 bi = 0; bi < abl->mNumberBuffers; ++bi) {
            const AudioBuffer& b = abl->mBuffers[bi];
            const uint32_t slot = ArpSIDDigiTapChannelSlotBytes_v254(asbd, 1u);
            if (!b.mData || slot == 0u || b.mDataByteSize < slot) continue;
            frames = std::min<uint32_t>(frames, b.mDataByteSize / slot);
            sawFrames = true;
        }
        frames = std::min<uint32_t>(frames, maxFrames);
        if (!sawFrames || frames == 0u) return 0u;
        for (UInt32 bi = 0; bi < abl->mNumberBuffers; ++bi) {
            const AudioBuffer& b = abl->mBuffers[bi];
            const uint8_t* raw = static_cast<const uint8_t*>(b.mData);
            const uint32_t slot = ArpSIDDigiTapChannelSlotBytes_v254(asbd, 1u);
            if (!raw || slot == 0u) continue;
            for (uint32_t f = 0; f < frames; ++f) {
                float v = 0.0f;
                if (ArpSIDDigiReadSampleFromRaw_v254(raw + (size_t)f * slot, asbd, v) != ArpSIDDigiTapReadStatus_v254::Ok) return 0u;
                outMono[f] += v;
            }
            ++contributors;
        }
    } else {
        // Fail closed on unusual interleaved multi-buffer layouts. The common tap
        // contract is one buffer holding all interleaved channels; multiple buffers
        // with interleaved semantics are ambiguous and were previously misread.
        if (abl->mNumberBuffers != 1u) return 0u;
        const AudioBuffer& b = abl->mBuffers[0];
        const uint32_t bufferChannels = b.mNumberChannels ? b.mNumberChannels : declaredChannels;
        if (bufferChannels != declaredChannels) return 0u;
        const uint32_t slot = ArpSIDDigiTapChannelSlotBytes_v254(asbd, bufferChannels);
        if (!b.mData || slot < payloadBytes) return 0u;
        const uint32_t frameStride = slot * bufferChannels;
        if (frameStride != asbd.mBytesPerFrame) return 0u;
        frames = std::min<uint32_t>(maxFrames, b.mDataByteSize / frameStride);
        if (frames == 0u) return 0u;
        const uint8_t* raw = static_cast<const uint8_t*>(b.mData);
        for (uint32_t f = 0; f < frames; ++f) {
            float acc = 0.0f;
            for (uint32_t c = 0; c < bufferChannels; ++c) {
                float v = 0.0f;
                if (ArpSIDDigiReadSampleFromRaw_v254(raw + (size_t)f * frameStride + (size_t)c * slot, asbd, v) != ArpSIDDigiTapReadStatus_v254::Ok) return 0u;
                acc += v;
            }
            outMono[f] = std::clamp(acc / (float)bufferChannels, -1.0f, 1.0f);
        }
        contributors = 1u;
    }
    if (contributors == 0u) return 0u;
    if (nonInterleaved) {
        const float inv = 1.0f / (float)contributors;
        for (uint32_t f = 0; f < frames; ++f) outMono[f] = std::clamp(outMono[f] * inv, -1.0f, 1.0f);
    }
    return frames;
}

static uint32_t ArpSIDDigiOutputTapMixMono_v248(const AudioBufferList* abl,
                                                float* outMono,
                                                uint32_t maxFrames) noexcept {
    if (!abl || abl->mNumberBuffers == 0u || !outMono || maxFrames == 0u) return 0u;
    const AudioBuffer& b0 = abl->mBuffers[0];
    const uint32_t ch0 = std::max<uint32_t>(1u, b0.mNumberChannels);
    uint32_t frames = (uint32_t)(b0.mDataByteSize / (sizeof(float) * ch0));
    if (frames == 0u) return 0u;
    frames = std::min<uint32_t>(frames, maxFrames);
    for (uint32_t f = 0u; f < frames; ++f) outMono[f] = 0.0f;
    uint32_t contributors = 0u;
    for (UInt32 bi = 0u; bi < abl->mNumberBuffers; ++bi) {
        const AudioBuffer& b = abl->mBuffers[bi];
        const float* data = static_cast<const float*>(b.mData);
        if (!data) continue;
        const uint32_t ch = std::max<uint32_t>(1u, b.mNumberChannels);
        const uint32_t bf = (uint32_t)(b.mDataByteSize / (sizeof(float) * ch));
        const uint32_t fcount = std::min<uint32_t>(frames, bf);
        for (uint32_t f = 0u; f < fcount; ++f) {
            float acc = 0.0f;
            for (uint32_t c = 0u; c < ch; ++c) {
                const float v = data[(size_t)f * ch + c];
                if (std::isfinite(v)) acc += v;
            }
            outMono[f] += acc / (float)ch;
        }
        ++contributors;
    }
    if (contributors > 1u) { const float inv = 1.0f / (float)contributors; for (uint32_t f = 0u; f < frames; ++f) outMono[f] *= inv; }
    for (uint32_t f = 0u; f < frames; ++f) outMono[f] = std::clamp(outMono[f], -1.0f, 1.0f);
    return frames;
}

// Tear down the process tap / aggregate / IOProc. Safe to call repeatedly.
static void ArpSIDDigiOutputTapStop_v248(AudioObjectID* tapID,
                                         AudioObjectID* aggID,
                                         AudioDeviceIOProcID* procID) noexcept {
#if ARPSID_HAS_COREAUDIO_PROCESS_TAP
    if (@available(macOS 14.2, *)) {
        if (aggID && *aggID != kAudioObjectUnknown && procID && *procID) {
            AudioDeviceStop(*aggID, *procID);
            AudioDeviceDestroyIOProcID(*aggID, *procID);
        }
        if (aggID && *aggID != kAudioObjectUnknown) AudioHardwareDestroyAggregateDevice(*aggID);
        if (tapID && *tapID != kAudioObjectUnknown) AudioHardwareDestroyProcessTap(*tapID);
    }
#endif
    if (procID) *procID = nullptr;
    if (aggID)  *aggID  = kAudioObjectUnknown;
    if (tapID)  *tapID  = kAudioObjectUnknown;
}

// Always-on diagnostic log for the output-capture path. The user can read these
// in Console.app (filter: "ArpSID DIGI TAP") to see exactly where capture fails.
#define ARPSID_DIGI_TAP_LOG(...) NSLog(@"[ArpSID DIGI TAP] " __VA_ARGS__)

// Helper: human-readable FourCC for an OSStatus, e.g. "'!pri'" or numeric.
static NSString* ArpSIDDigiOSStatusString_v248(OSStatus s) {
    char c[4] = { (char)((s >> 24) & 0xFF), (char)((s >> 16) & 0xFF), (char)((s >> 8) & 0xFF), (char)(s & 0xFF) };
    BOOL printable = YES;
    for (int i = 0; i < 4; ++i) if (c[i] < 32 || c[i] > 126) { printable = NO; break; }
    if (printable) return [NSString stringWithFormat:@"%d ('%c%c%c%c')", (int)s, c[0], c[1], c[2], c[3]];
    return [NSString stringWithFormat:@"%d", (int)s];
}

// Create + start the output capture graph for the given output device UID.
// On success fills *tapID/*aggID/*procID/*outSampleRate and returns YES.
// Emits detailed diagnostics at every step so a field failure is always visible.
static BOOL ArpSIDDigiOutputTapStart_v248(NSString* outputUID,
                                          AudioDeviceIOBlock ioBlock,
                                          AudioObjectID* tapID,
                                          AudioObjectID* aggID,
                                          AudioDeviceIOProcID* procID,
                                          double* outSampleRate,
                                          AudioStreamBasicDescription* outASBD,
                                          NSString** errOut) noexcept {
    if (errOut) *errOut = nil;
    if (tapID) *tapID = kAudioObjectUnknown;
    if (aggID) *aggID = kAudioObjectUnknown;
    if (procID) *procID = nullptr;
    if (outASBD) std::memset(outASBD, 0, sizeof(*outASBD));
    ARPSID_DIGI_TAP_LOG(@"start requested for outputUID=%@", outputUID ? outputUID : @"(nil)");
#if ARPSID_HAS_COREAUDIO_PROCESS_TAP
    if (@available(macOS 14.2, *)) {
        if (!ioBlock) { if (errOut) *errOut = @"DIGI OUTPUT TAP NO IOBLOCK"; ARPSID_DIGI_TAP_LOG(@"no ioBlock"); return NO; }
        CATapDescription* desc = [[CATapDescription alloc] initStereoGlobalTapButExcludeProcesses:@[]];
        if (!desc) { if (errOut) *errOut = @"DIGI OUTPUT TAP DESCRIPTION FAILED"; ARPSID_DIGI_TAP_LOG(@"CATapDescription alloc failed"); return NO; }
        desc.name = @"ArpSID DIGI Output Capture";
        desc.privateTap = YES;
        desc.muteBehavior = CATapUnmuted; // never mute the user's own playback
        AudioObjectID tap = kAudioObjectUnknown;
        OSStatus st = AudioHardwareCreateProcessTap(desc, &tap);
        ARPSID_DIGI_TAP_LOG(@"AudioHardwareCreateProcessTap -> status=%@ tapID=%u", ArpSIDDigiOSStatusString_v248(st), (unsigned)tap);
        if (st != noErr || tap == kAudioObjectUnknown) {
            if (errOut) *errOut = [NSString stringWithFormat:@"DIGI OUTPUT TAP CREATE FAILED %@ — grant the host Audio/Microphone permission in System Settings", ArpSIDDigiOSStatusString_v248(st)];
            return NO;
        }
        // Log the tap's negotiated stream format (purely diagnostic).
        AudioStreamBasicDescription tapFmt{}; UInt32 fmtSize = sizeof(tapFmt);
        AudioObjectPropertyAddress fmtAddr{ kAudioTapPropertyFormat, kAudioObjectPropertyScopeGlobal, kAudioObjectPropertyElementMain };
        if (AudioObjectGetPropertyData(tap, &fmtAddr, 0, nullptr, &fmtSize, &tapFmt) == noErr) {
            ARPSID_DIGI_TAP_LOG(@"tap format: %.0f Hz, %u ch, %u bits, flags=0x%x", tapFmt.mSampleRate, (unsigned)tapFmt.mChannelsPerFrame, (unsigned)tapFmt.mBitsPerChannel, (unsigned)tapFmt.mFormatFlags);
            if (outASBD) *outASBD = tapFmt; // drive ASBD-correct mixdown in the IOProc
        } else {
            ARPSID_DIGI_TAP_LOG(@"tap format query failed (non-fatal)");
        }
        NSString* tapUUID = desc.UUID.UUIDString ? desc.UUID.UUIDString : @"";
        NSString* aggUID = [NSString stringWithFormat:@"ArpSID.DIGI.OutputTapAgg.%@", [[NSUUID UUID] UUIDString]];
        NSMutableDictionary* aggDesc = [NSMutableDictionary dictionary];
        aggDesc[@(kAudioAggregateDeviceNameKey)] = @"ArpSID DIGI Output Capture";
        aggDesc[@(kAudioAggregateDeviceUIDKey)] = aggUID;
        aggDesc[@(kAudioAggregateDeviceIsPrivateKey)] = @YES;
        aggDesc[@(kAudioAggregateDeviceIsStackedKey)] = @NO;
        if (outputUID.length) {
            aggDesc[@(kAudioAggregateDeviceMainSubDeviceKey)] = outputUID;
            aggDesc[@(kAudioAggregateDeviceSubDeviceListKey)] = @[ @{ @(kAudioSubDeviceUIDKey): outputUID } ];
        }
        aggDesc[@(kAudioAggregateDeviceTapListKey)] = @[ @{
            @(kAudioSubTapDriftCompensationKey): @YES,
            @(kAudioSubTapUIDKey): tapUUID
        } ];
        AudioObjectID agg = kAudioObjectUnknown;
        st = AudioHardwareCreateAggregateDevice((__bridge CFDictionaryRef)aggDesc, &agg);
        ARPSID_DIGI_TAP_LOG(@"AudioHardwareCreateAggregateDevice -> status=%@ aggID=%u (main=%@)", ArpSIDDigiOSStatusString_v248(st), (unsigned)agg, outputUID.length ? outputUID : @"(none)");
        if (st != noErr || agg == kAudioObjectUnknown) {
            // Retry once WITHOUT pinning a main sub-device: a tap-only private
            // aggregate is clocked by the tap itself and works when the chosen
            // output cannot host a private aggregate.
            if (outputUID.length) {
                ARPSID_DIGI_TAP_LOG(@"retrying aggregate without main sub-device (tap-only)");
                [aggDesc removeObjectForKey:@(kAudioAggregateDeviceMainSubDeviceKey)];
                [aggDesc removeObjectForKey:@(kAudioAggregateDeviceSubDeviceListKey)];
                st = AudioHardwareCreateAggregateDevice((__bridge CFDictionaryRef)aggDesc, &agg);
                ARPSID_DIGI_TAP_LOG(@"retry AudioHardwareCreateAggregateDevice -> status=%@ aggID=%u", ArpSIDDigiOSStatusString_v248(st), (unsigned)agg);
            }
            if (st != noErr || agg == kAudioObjectUnknown) {
                if (errOut) *errOut = [NSString stringWithFormat:@"DIGI OUTPUT TAP AGGREGATE FAILED %@", ArpSIDDigiOSStatusString_v248(st)];
                ArpSIDDigiOutputTapStop_v248(&tap, &agg, nullptr);
                return NO;
            }
        }
        Float64 sr = 48000.0; UInt32 z = sizeof(sr);
        AudioObjectPropertyAddress sra{ kAudioDevicePropertyNominalSampleRate, kAudioObjectPropertyScopeGlobal, kAudioObjectPropertyElementMain };
        if (AudioObjectGetPropertyData(agg, &sra, 0, nullptr, &z, &sr) == noErr && sr > 100.0) { if (outSampleRate) *outSampleRate = (double)sr; }
        else if (outSampleRate) *outSampleRate = 48000.0;
        AudioDeviceIOProcID proc = nullptr;
        st = AudioDeviceCreateIOProcIDWithBlock(&proc, agg, nullptr, ioBlock);
        ARPSID_DIGI_TAP_LOG(@"AudioDeviceCreateIOProcIDWithBlock -> status=%@ proc=%p sr=%.0f", ArpSIDDigiOSStatusString_v248(st), (void*)proc, sr);
        if (st != noErr || !proc) {
            if (errOut) *errOut = [NSString stringWithFormat:@"DIGI OUTPUT TAP IOPROC FAILED %@", ArpSIDDigiOSStatusString_v248(st)];
            ArpSIDDigiOutputTapStop_v248(&tap, &agg, nullptr);
            return NO;
        }
        st = AudioDeviceStart(agg, proc);
        ARPSID_DIGI_TAP_LOG(@"AudioDeviceStart -> status=%@", ArpSIDDigiOSStatusString_v248(st));
        if (st != noErr) {
            if (errOut) *errOut = [NSString stringWithFormat:@"DIGI OUTPUT TAP START FAILED %@", ArpSIDDigiOSStatusString_v248(st)];
            ArpSIDDigiOutputTapStop_v248(&tap, &agg, &proc);
            return NO;
        }
        if (tapID) *tapID = tap;
        if (aggID) *aggID = agg;
        if (procID) *procID = proc;
        ARPSID_DIGI_TAP_LOG(@"output capture RUNNING (tap=%u agg=%u sr=%.0f)", (unsigned)tap, (unsigned)agg, sr);
        return YES;
    }
#endif
    (void)outputUID; (void)ioBlock; (void)outSampleRate;
    ARPSID_DIGI_TAP_LOG(@"process tap unavailable (needs macOS 14.2+)");
    if (errOut) *errOut = @"DIGI OUTPUT TAP NEEDS macOS 14.2+ — select a CoreAudio Input/BlackHole/Loopback instead";
    return NO;
}

// AVAudioEngine input taps on macOS do not always pull hardware input
// merely because a tap is installed. Some CoreAudio routes/devices deliver zero
// callbacks unless the graph has a downstream consumer. Prime the private engine
// with a muted sink path so MON/REC receives real tap buffers without feeding the
// user's speakers. This is per-preview/per-record engine state, not AU output.
static BOOL ArpSIDDigiPrimeInputTapEngine_v241(AVAudioEngine* engine,
                                               AVAudioInputNode* input,
                                               AVAudioFormat* format,
                                               NSString** errorMessage) noexcept {
    if (errorMessage) *errorMessage = nil;
    if (!engine || !input || !format || format.channelCount == 0u || !std::isfinite(format.sampleRate) || format.sampleRate <= 0.0) {
        if (errorMessage) *errorMessage = @"DIGI INPUT PRIME BAD FORMAT";
        return NO;
    }
    @try {
        AVAudioMixerNode* mixer = engine.mainMixerNode;
        if (!mixer) {
            if (errorMessage) *errorMessage = @"DIGI INPUT PRIME NO MIXER";
            return NO;
        }
        mixer.outputVolume = 0.0f;
        [engine connect:input to:mixer format:format];
        [engine prepare];
        return YES;
    } @catch (NSException* ex) {
        if (errorMessage) *errorMessage = ex.reason ? ex.reason : @"DIGI INPUT PRIME FAILED";
        return NO;
    }
}

static ArpSIDDigiRecordPreparedMono_v161 ArpSIDDigiPrepareRecordedMono_v161(const float* samples,
                                                                             std::uint32_t count,
                                                                             bool trimSilence,
                                                                             bool normalizeLevel,
                                                                             ArpSIDDigiConvertMode_v199 convertMode) {
    ArpSIDDigiRecordPreparedMono_v161 out{};
    out.inputFrames = count;
    if (!samples || count == 0u) return out;

    constexpr float kSilenceThreshold = 0.0025f; // approx -52 dBFS; strips room lead-in/out only.
    constexpr std::uint32_t kGuardFrames = 32u;  // preserve attack/release edge after trimming.
    std::uint32_t first = 0u;
    while (first < count) {
        const float v = samples[first];
        if (std::isfinite(v) && std::fabs(v) > kSilenceThreshold) break;
        ++first;
    }
    if (first >= count) return out;

    std::uint32_t last = count - 1u;
    while (last > first) {
        const float v = samples[last];
        if (std::isfinite(v) && std::fabs(v) > kSilenceThreshold) break;
        --last;
    }

    const std::uint32_t start = trimSilence ? ((first > kGuardFrames) ? (first - kGuardFrames) : 0u) : 0u;
    const std::uint32_t end = trimSilence ? std::min<std::uint32_t>(count - 1u, last + kGuardFrames) : (count - 1u);
    const std::uint32_t n = end >= start ? (end - start + 1u) : 0u;
    if (n == 0u) return out;

    out.samples.resize(n, 0.0f);
    float peak = 0.0f;
    for (std::uint32_t i = 0u; i < n; ++i) {
        float v = samples[start + i];
        if (!std::isfinite(v)) v = 0.0f;
        v = std::clamp(v, -1.0f, 1.0f);
        out.samples[i] = ArpSIDDigiApplyConversion_v199(v, convertMode, i);
        peak = std::max<float>(peak, std::fabs(out.samples[i]));
    }
    out.trimmedFrames = count - n;
    out.peakBeforeNormalize = peak;
    if (peak <= kSilenceThreshold) {
        out.samples.clear();
        out.trimmedFrames = count;
        return out;
    }

    // Normalize captures that are safe to boost. Limit gain to 24 dB so a very
    // quiet accidental room recording does not become a wall of quantized noise.
    if (normalizeLevel && peak > 0.0f && peak < 0.90f) {
        const float gain = std::min<float>(0.98f / peak, 16.0f);
        if (gain > 1.001f) {
            for (float& v : out.samples) v = std::clamp(v * gain, -0.98f, 0.98f);
            out.normalized = true;
        }
    }
    return out;
}

-(NSArray<AVCaptureDevice*>*)_digiRecordInputDevices_v159_ {
    if (@available(macOS 14.0, *)) {
        NSArray<AVCaptureDeviceType>* types = @[ AVCaptureDeviceTypeMicrophone, AVCaptureDeviceTypeExternal ];
        AVCaptureDeviceDiscoverySession* session =
            [AVCaptureDeviceDiscoverySession discoverySessionWithDeviceTypes:types
                                                                   mediaType:AVMediaTypeAudio
                                                                    position:AVCaptureDevicePositionUnspecified];
        NSArray<AVCaptureDevice*>* devices = session.devices;
        return devices ? devices : @[];
    }

    SEL legacySelector = NSSelectorFromString(@"devicesWithMediaType:");
    if (![AVCaptureDevice respondsToSelector:legacySelector]) return @[];
#pragma clang diagnostic push
#pragma clang diagnostic ignored "-Warc-performSelector-leaks"
    id result = [AVCaptureDevice performSelector:legacySelector withObject:AVMediaTypeAudio];
#pragma clang diagnostic pop
    return [result isKindOfClass:[NSArray class]] ? (NSArray<AVCaptureDevice*>*)result : @[];
}

static AudioObjectID ArpSIDDigiDefaultInputDevice_v227() {
    AudioObjectID dev = kAudioObjectUnknown;
    UInt32 size = sizeof(dev);
    AudioObjectPropertyAddress addr{ kAudioHardwarePropertyDefaultInputDevice,
                                     kAudioObjectPropertyScopeGlobal,
                                     kAudioObjectPropertyElementMain };
    if (AudioObjectGetPropertyData(kAudioObjectSystemObject, &addr, 0, nullptr, &size, &dev) != noErr) return kAudioObjectUnknown;
    return dev;
}

static NSString* ArpSIDDigiAudioDeviceUID_v227(AudioObjectID dev) {
    if (dev == kAudioObjectUnknown) return nil;
    CFStringRef uid = nullptr;
    UInt32 size = sizeof(uid);
    AudioObjectPropertyAddress addr{ kAudioDevicePropertyDeviceUID,
                                     kAudioObjectPropertyScopeGlobal,
                                     kAudioObjectPropertyElementMain };
    OSStatus st = AudioObjectGetPropertyData(dev, &addr, 0, nullptr, &size, &uid);
    if (st != noErr || !uid) return nil;
    return CFBridgingRelease(uid);
}

static AudioObjectID ArpSIDDigiCoreAudioInputDeviceForUID_v227(NSString* wantedUID) {
    if (!wantedUID || wantedUID.length == 0) return kAudioObjectUnknown;
    UInt32 size = 0;
    AudioObjectPropertyAddress addr{ kAudioHardwarePropertyDevices,
                                     kAudioObjectPropertyScopeGlobal,
                                     kAudioObjectPropertyElementMain };
    if (AudioObjectGetPropertyDataSize(kAudioObjectSystemObject, &addr, 0, nullptr, &size) != noErr || size == 0) return kAudioObjectUnknown;
    const UInt32 count = size / sizeof(AudioObjectID);
    std::vector<AudioObjectID> devices(count, kAudioObjectUnknown);
    if (AudioObjectGetPropertyData(kAudioObjectSystemObject, &addr, 0, nullptr, &size, devices.data()) != noErr) return kAudioObjectUnknown;
    for (AudioObjectID dev : devices) {
        UInt32 streamsSize = 0;
        AudioObjectPropertyAddress streamsAddr{ kAudioDevicePropertyStreams,
                                                kAudioDevicePropertyScopeInput,
                                                kAudioObjectPropertyElementMain };
        if (AudioObjectGetPropertyDataSize(dev, &streamsAddr, 0, nullptr, &streamsSize) != noErr || streamsSize == 0) continue;
        NSString* uid = ArpSIDDigiAudioDeviceUID_v227(dev);
        if (uid && [uid isEqualToString:wantedUID]) return dev;
    }
    return kAudioObjectUnknown;
}


static BOOL ArpSIDDigiCoreAudioDeviceHasStreams_v236(AudioObjectID dev, AudioObjectPropertyScope scope) {
    if (dev == kAudioObjectUnknown) return NO;
    UInt32 size = 0;
    AudioObjectPropertyAddress addr{ kAudioDevicePropertyStreams, scope, kAudioObjectPropertyElementMain };
    return AudioObjectGetPropertyDataSize(dev, &addr, 0, nullptr, &size) == noErr && size > 0;
}

static NSString* ArpSIDDigiCoreAudioDeviceName_v236(AudioObjectID dev) {
    if (dev == kAudioObjectUnknown) return nil;
    CFStringRef name = nullptr;
    UInt32 size = sizeof(name);
    AudioObjectPropertyAddress addr{ kAudioObjectPropertyName,
                                     kAudioObjectPropertyScopeGlobal,
                                     kAudioObjectPropertyElementMain };
    OSStatus st = AudioObjectGetPropertyData(dev, &addr, 0, nullptr, &size, &name);
