}

static NSArray<NSDictionary<NSString*, NSString*>*>* ArpSIDDigiCoreAudioOutputDevices_v236() {
    UInt32 size = 0;
    AudioObjectPropertyAddress addr{ kAudioHardwarePropertyDevices,
                                     kAudioObjectPropertyScopeGlobal,
                                     kAudioObjectPropertyElementMain };
    if (AudioObjectGetPropertyDataSize(kAudioObjectSystemObject, &addr, 0, nullptr, &size) != noErr || size == 0) return @[];
    const UInt32 count = size / sizeof(AudioObjectID);
    std::vector<AudioObjectID> devices(count, kAudioObjectUnknown);
    if (AudioObjectGetPropertyData(kAudioObjectSystemObject, &addr, 0, nullptr, &size, devices.data()) != noErr) return @[];
    NSMutableArray<NSDictionary<NSString*, NSString*>*>* out = [NSMutableArray array];
    for (AudioObjectID dev : devices) {
        if (!ArpSIDDigiCoreAudioDeviceHasStreams_v236(dev, kAudioDevicePropertyScopeOutput)) continue;
        NSString* uid = ArpSIDDigiAudioDeviceUID_v227(dev);
        if (!uid || uid.length == 0) continue;
        NSString* name = ArpSIDDigiCoreAudioDeviceName_v236(dev);
        [out addObject:@{ @"uid": uid, @"name": (name.length ? name : @"CoreAudio Output") }];
    }
    return out;
}

// enumerate CoreAudio input devices directly, not only AVCaptureDevice.
// Some loopback/aggregate/system-capture devices are valid CoreAudio inputs but
