-(BOOL)_digiRecordHasMicrophonePermission_v160_ {
    AVAuthorizationStatus status = [AVCaptureDevice authorizationStatusForMediaType:AVMediaTypeAudio];
    return status == AVAuthorizationStatusAuthorized;
}

// the DIGI REC/MON input tap runs inside the host process, so macOS
// attributes microphone permission to the *host* application, not to ArpSID.
// When capture is denied/silenced the user must grant the host (DAW or the
// bundled ArpSID host) microphone access. Surface the host name so the HUD can
// tell them exactly which app to authorize in System Settings.
-(NSString*)_digiHostAppName_v246_ {
    NSString* name = [[NSBundle mainBundle] objectForInfoDictionaryKey:@"CFBundleName"];
    if (name.length == 0) name = [[NSBundle mainBundle] objectForInfoDictionaryKey:(NSString*)kCFBundleNameKey];
    if (name.length == 0) name = [[NSProcessInfo processInfo] processName];
    return name.length ? name : @"the host app";
}

-(BOOL)_digiRecordCanRequestMicrophonePermission_v160_ {
    AVAuthorizationStatus status = [AVCaptureDevice authorizationStatusForMediaType:AVMediaTypeAudio];
    return status == AVAuthorizationStatusNotDetermined;
}

-(void)_digiSetRecordControlsEnabled_v160_:(BOOL)enabled {
    const BOOL active = _digiRecordActive_v158_.load(std::memory_order_acquire) || _digiPreviewActive_v237_.load(std::memory_order_acquire);
    const BOOL canEdit = enabled && !active;
    NSPopUpButton* pop = _digiRecordInputPopup_v159_ ? _digiRecordInputPopup_v159_ : (_pDigiV563 ? (NSPopUpButton*)[_pDigiV563 viewWithTag:kArpSIDDigiRecordInputTag] : nil);
    // equivalent contract to the original guard:
    // pop.enabled = enabled && !_digiRecordActive_v158_
    if (pop) pop.enabled = canEdit;
    NSButton* rec = _pDigiV563 ? (NSButton*)[_pDigiV563 viewWithTag:kArpSIDDigiRecordTag] : nil;
    if (rec) rec.enabled = YES; // REC becomes STOP while active; never hide the stop path.
    NSArray<NSNumber*>* gateTags = @[
        @(kArpSIDDigiImportTag), @(kArpSIDDigiExportTag), @(kArpSIDDigiRecordKeepTag), @(kArpSIDDigiRecordDiscardTag),
        @(kArpSIDDigiClearUserTag), @(kArpSIDDigiRenameTag), @(kArpSIDDigiCopyTag), @(kArpSIDDigiPasteTag),
        @(kArpSIDDigiSwapTag), @(kArpSIDDigiKitExportTag), @(kArpSIDDigiKitImportTag), @(kArpSIDDigiClearAllTag),
        @(kArpSIDDigiTrimApplyTag), @(kArpSIDDigiMidiLearnTag)
    ];
    for (NSNumber* n in gateTags) {
        NSControl* c = _pDigiV563 ? (NSControl*)[_pDigiV563 viewWithTag:n.integerValue] : nil;
        if (c && c != rec) c.enabled = canEdit;
    }
    NSButton* preview = _pDigiV563 ? (NSButton*)[_pDigiV563 viewWithTag:kArpSIDDigiPreviewTag] : nil;
    if (preview) {
        preview.enabled = enabled && !_digiRecordActive_v158_.load(std::memory_order_acquire);
        preview.title = _digiPreviewActive_v237_.load(std::memory_order_acquire) ? @"STOP MON" : @"MON";
        preview.state = _digiPreviewActive_v237_.load(std::memory_order_acquire) ? NSControlStateValueOn : NSControlStateValueOff;
    }
    [self _digiRefreshRecordTakeButtons_v199_];
    [self _digiRefreshClipboardAndTrimControls_v201_];
    [self _digiRefreshSlotControls_v563_];
}

-(BOOL)_digiRecordInputIsPureSid1Q1_v230_ {
    return _digiRecordInputDeviceUID_v159_ && [_digiRecordInputDeviceUID_v159_ isEqualToString:kArpSIDDigiRecordInputPureSid1Q1UID_v230];
}


-(BOOL)_digiRecordInputIsCoreAudioOutputMonitor_v236_ {
    return ArpSIDDigiRecordInputUIDIsCoreAudioOutput_v236(_digiRecordInputDeviceUID_v159_);
}

-(NSString*)_digiRecordInputCoreAudioOutputUID_v236_ {
    return ArpSIDDigiCoreAudioOutputUIDFromRecordUID_v236(_digiRecordInputDeviceUID_v159_);
}

-(NSString*)_digiLoopbackInputUIDForCoreAudioOutputUID_v236_:(NSString*)outputUID {
    if (!outputUID || outputUID.length == 0) return nil;
    NSString* outputName = nil;
    for (NSDictionary<NSString*, NSString*>* d in ArpSIDDigiCoreAudioOutputDevices_v236()) {
        if ([[d objectForKey:@"uid"] isEqualToString:outputUID]) { outputName = [d objectForKey:@"name"]; break; }
    }

    // First prefer an aggregate/virtual device with the exact same UID and input streams.
    AudioObjectID exactInput = ArpSIDDigiCoreAudioInputDeviceForUID_v227(outputUID);
    if (exactInput != kAudioObjectUnknown) return outputUID;

    // do not guess a random "loopback-looking" input for an output.
    // That made MON look armed while metering permanent zero when BlackHole/Loopback
    // was installed but not actually routed from the chosen output. Output-monitor
    // mode is now fail-closed unless the selected output resolves to an exact
    // aggregate/virtual input UID. Users can still select BlackHole/Loopback
    // directly from the normal input-device list when it is intentionally routed.
    (void)outputName;
    return nil;
}

-(NSString*)_digiRecordInputDisplayName_v159_ {
    if ([self _digiRecordInputIsPureSid1Q1_v230_]) return @"AU Pure 1:1 SID Engine";
    if ([self _digiRecordInputIsCoreAudioOutputMonitor_v236_]) {
        NSString* outUID = [self _digiRecordInputCoreAudioOutputUID_v236_];
        NSString* prefix = [self _digiOutputTapAvailable_v248_] ? @"System Audio Capture" : @"CoreAudio Output Monitor";
        for (NSDictionary<NSString*, NSString*>* d in ArpSIDDigiCoreAudioOutputDevices_v236()) {
            if ([[d objectForKey:@"uid"] isEqualToString:outUID]) {
                return [NSString stringWithFormat:@"%@: %@", prefix, ([d objectForKey:@"name"] ? [d objectForKey:@"name"] : @"Output")];
            }
        }
        return [NSString stringWithFormat:@"%@: Missing Output", prefix];
    }
    if (!_digiRecordInputDeviceUID_v159_ || _digiRecordInputDeviceUID_v159_.length == 0) return @"System Default Input";
    for (AVCaptureDevice* dev in [self _digiRecordInputDevices_v159_]) {
        if ([dev.uniqueID isEqualToString:_digiRecordInputDeviceUID_v159_]) return dev.localizedName ? dev.localizedName : @"Selected Input";
    }
    for (NSDictionary<NSString*, NSString*>* d in ArpSIDDigiCoreAudioInputDevices_v242()) {
        if ([[d objectForKey:@"uid"] isEqualToString:_digiRecordInputDeviceUID_v159_]) {
            NSString* name = [d objectForKey:@"name"];
            return [NSString stringWithFormat:@"CoreAudio Input: %@", name.length ? name : @"Input"];
        }
    }
    return @"Missing Input";
}

-(void)_digiRefreshRecordInputPopup_v159_ {
    NSPopUpButton* pop = _digiRecordInputPopup_v159_ ? _digiRecordInputPopup_v159_ : (_pDigiV563 ? (NSPopUpButton*)[_pDigiV563 viewWithTag:kArpSIDDigiRecordInputTag] : nil);
    if (!pop) return;
    NSString* wanted = _digiRecordInputDeviceUID_v159_ ? [_digiRecordInputDeviceUID_v159_ copy] : @"";
    [pop removeAllItems];
    [pop addItemWithTitle:@"System Default Input"];
    pop.lastItem.representedObject = @"";
    [pop addItemWithTitle:@"AU Pure 1:1 SID Engine"];
    pop.lastItem.representedObject = kArpSIDDigiRecordInputPureSid1Q1UID_v230;
    NSMutableSet<NSString*>* seenInputUIDs_v242 = [NSMutableSet set];
    NSArray<AVCaptureDevice*>* devices = [self _digiRecordInputDevices_v159_];
    for (AVCaptureDevice* dev in devices) {
        if (!dev.uniqueID || dev.uniqueID.length == 0) continue;
        NSString* title = dev.localizedName.length ? dev.localizedName : @"Audio Input";
        [pop addItemWithTitle:title];
        pop.lastItem.representedObject = dev.uniqueID;
        [seenInputUIDs_v242 addObject:dev.uniqueID];
    }
