        NSString* loopbackUID = [self _digiLoopbackInputUIDForCoreAudioOutputUID_v236_:outputUID];
        if (!loopbackUID.length) {
            if (_digiRuntimeHUDLabel) _digiRuntimeHUDLabel.stringValue = @"DIGI OUTPUT MONITOR NEEDS LOOPBACK INPUT (macOS < 14.2) — select BlackHole/Loopback";
            _digiRecordResolvedInputDeviceUID_v236_ = nil;
            return NO;
        }
        _digiRecordResolvedInputDeviceUID_v236_ = [loopbackUID copy];
        effectiveInputUID_v236 = _digiRecordResolvedInputDeviceUID_v236_;
    } else {
        _digiRecordResolvedInputDeviceUID_v236_ = nil;
    }
    const AudioObjectID selected = ArpSIDDigiCoreAudioInputDeviceForUID_v227(effectiveInputUID_v236);
    if (selected == kAudioObjectUnknown) {
