    // do not switch global default input. The AudioQueue backend binds
    // capture directly to the selected device UID via kAudioQueueProperty_CurrentDevice.
    // The legacy AVAudioEngine default-switch path below is retained only as a
    // compile-time fallback and is not used while AudioQueue is the primary path.
    if ([self _digiShouldUseAudioQueueInput_v251_]) {
        _digiRecordChangedDefaultInputDevice_v227_ = NO;
        _digiRecordPreviousDefaultInputDevice_v227_ = kAudioObjectUnknown;
        return YES;
