    if (!ArpSIDDigiSetDefaultInputDevice_v227(selected)) {
        if (_digiRuntimeHUDLabel) _digiRuntimeHUDLabel.stringValue = @"DIGI REC INPUT SWITCH FAILED";
        _digiRecordPreviousDefaultInputDevice_v227_ = kAudioObjectUnknown;
        _digiRecordChangedDefaultInputDevice_v227_ = NO;
        return NO;
    }
    _digiRecordChangedDefaultInputDevice_v227_ = YES;
    // Give AVAudioEngine's inputNode a short chance to observe the route change before format query/start.
    [NSThread sleepForTimeInterval:0.08];
    return YES;
}

