-(NSString*)_digiUserSampleStatusString_v596_ {
    const std::uint8_t slot = _digiModel_v563_.activeSlot;
    if (slot >= ArpSID::GUI::kDigiActiveSlotCount) return @"USER --";
    const ArpSID::GUI::DigiSampleSlot& s = _digiModel_v563_.slots[slot];
    const ArpSID::GUI::DigiUserSampleClip* clip = nullptr;
    if (s.userSampleIndex < ArpSID::GUI::kDigiUserSampleSlotCount) {
        clip = ArpSID::GUI::digiFindUserSampleClip(_digiSampleBank_v596_, s.userSampleIndex, s.userSampleHandle);
        if (!clip) {
            const ArpSID::GUI::DigiUserSampleClip& cached = _digiSampleBank_v596_.clips[s.userSampleIndex];
            if (ArpSID::GUI::digiUserSampleClipIsWellFormed(cached) &&
                ArpSID::GUI::digiUserSampleClipIsPresent(cached)) {
                clip = &cached;
            }
        }
    }
    if (clip) {
        NSString* name = [NSString stringWithUTF8String:clip->displayName];
        if (!name || name.length == 0) name = @"User Sample";
        const BOOL matched = (s.sourceType == ArpSID::GUI::DigiSourceType::UserImport &&
                              s.userSampleHandle == clip->handle);
        const double ms = (1000.0 * (double)clip->frameCount) / (double)ArpSID::GUI::kDigiUserSampleCanonicalRateHz;
        const BOOL likelyTruncated_v206_ = (clip->frameCount >= ArpSID::GUI::kDigiUserSampleMaxFrames);
        return [NSString stringWithFormat:@"%@  %u fr  %.0f ms  8kHz 4-bit%@  %@",
                matched ? @"USER" : @"CACHE",
                (unsigned)clip->frameCount,
                ms,
                likelyTruncated_v206_ ? @" TRUNC" : @"",
                name];
    }
    if (s.sourceType == ArpSID::GUI::DigiSourceType::UserImport) {
        return s.userSampleHandle ? @"USER SAMPLE MISSING" : @"USER SAMPLE EMPTY";
    }
    return @"USER SAMPLE EMPTY";
}

