-(void)_digiSourceChanged_v563_:(id)sender {
    NSPopUpButton* pop = (NSPopUpButton*)sender;
    const std::uint8_t slot = _digiModel_v563_.activeSlot;
    [self _digiBumpSampleWorkflowGeneration_v211_];
    [self _digiInvalidatePendingTakeForSlot_v209_:slot reason:nil];
    auto srcType = (ArpSID::GUI::DigiSourceType)(NSInteger)pop.indexOfSelectedItem;
    if (static_cast<std::uint8_t>(srcType) >
        static_cast<std::uint8_t>(ArpSID::GUI::DigiSourceType::UserImport)) return;
    if (srcType == ArpSID::GUI::DigiSourceType::FactorySlot) {
        ArpSID::GUI::digiSetFactorySlot(_digiModel_v563_.slots[slot],
                                        _digiModel_v563_.slots[slot].factorySlotIndex);
    } else if (srcType == ArpSID::GUI::DigiSourceType::UserImport) {
        std::uint32_t handle = 0u;
        const ArpSID::GUI::DigiUserSampleClip& cached = _digiSampleBank_v596_.clips[slot];
        if (ArpSID::GUI::digiUserSampleClipIsWellFormed(cached) &&
            ArpSID::GUI::digiUserSampleClipIsPresent(cached)) {
            handle = cached.handle;
        }
        if (handle == 0u) {
            // selecting User Import with no valid clip must not leave
            // the slot in a dangling UserImport/handle=0 state while the open
            // panel is pending or after the user cancels. Keep the slot silent
            // until a successful import publishes an actual user-sample handle.
            ArpSID::GUI::digiSetNoSource(_digiModel_v563_.slots[slot]);
            [self _digiRefreshSlotControls_v563_];
            [self _pushDigiStateToAdapter_v565_];
            [self _digiImportSample_v596_:sender];
            return;
        }
        ArpSID::GUI::digiSetUserSampleSlot(_digiModel_v563_.slots[slot], slot, handle);
    } else {
        ArpSID::GUI::digiSetNoSource(_digiModel_v563_.slots[slot]);
    }
    [self _digiRefreshSlotControls_v563_];
    [self _pushDigiStateToAdapter_v565_]; // v565
}

