-(void)_digiRefreshRecordTakeButtons_v199_ {
    const BOOL hasTake = !_digiPendingTakeMonoFloat_v199_.empty();
    const BOOL sourceBusy_v245 = _digiRecordActive_v158_.load(std::memory_order_acquire) ||
                                 _digiPreviewActive_v237_.load(std::memory_order_acquire);
    NSButton* keep = _pDigiV563 ? (NSButton*)[_pDigiV563 viewWithTag:kArpSIDDigiRecordKeepTag] : nil;
    NSButton* disc = _pDigiV563 ? (NSButton*)[_pDigiV563 viewWithTag:kArpSIDDigiRecordDiscardTag] : nil;
    // MON is an active source graph. KEEP/DISCARD mutate pending-take
    // state, so they must remain disabled while preview is running, not only while
    // recording. Otherwise _digiSetRecordControlsEnabled_v160_ could gate them
    // off and this refresh would immediately re-enable them.
    if (keep) keep.enabled = hasTake && !sourceBusy_v245;
    if (disc) disc.enabled = hasTake && !sourceBusy_v245;
}

// meter string keeps the previous REC %.2fs  PEAK contract and adds
// a PURE SID marker when the source is AU Pure 1:1 SID Engine.
-(void)_digiRefreshRecordMeter_v199_ {
    NSTextField* meter = _pDigiV563 ? (NSTextField*)[_pDigiV563 viewWithTag:kArpSIDDigiRecordMeterTag] : nil;
    if (!meter) return;
    NSUInteger written = _digiRecordWriteFrames_v182_.load(std::memory_order_acquire);
    NSUInteger dropped = _digiRecordDroppedFrames_v160_.load(std::memory_order_acquire);
    double statusSr_v230 = _digiRecordSampleRateHz_v160_;
    if (_digiRecordActive_v158_.load(std::memory_order_acquire) && _digiRecordWasPureSid1Q1Input_v230_) {
        id adapter = _au ? [_au debugAdapter] : nil;
        if (adapter && [adapter respondsToSelector:@selector(pureSid1Q1RecordCaptureStatusFrames:sampleRate:droppedFrames:peak:rms:)]) {
            float purePeak_v231 = 0.0f;
            float pureRms_v231 = 0.0f;
            [(id<ArpSIDDebugAdapterLike>)adapter pureSid1Q1RecordCaptureStatusFrames:&written sampleRate:&statusSr_v230 droppedFrames:&dropped peak:&purePeak_v231 rms:&pureRms_v231];
            _digiRecordWriteFrames_v182_.store(written, std::memory_order_release);
            _digiRecordDroppedFrames_v160_.store(dropped, std::memory_order_release);
            _digiRecordPeak_v199_.store(ArpSIDDigiSanitizeUnitMetric_v271(purePeak_v231), std::memory_order_release);
            _digiRecordRms_v199_.store(ArpSIDDigiSanitizeUnitMetric_v271(pureRms_v231), std::memory_order_release);
        }
    }
    const float peak = ArpSIDDigiSanitizeUnitMetric_v271(_digiRecordPeak_v199_.load(std::memory_order_acquire));
    const float rms = ArpSIDDigiSanitizeUnitMetric_v271(_digiRecordRms_v199_.load(std::memory_order_acquire));
    const double recordSr_v208 = std::isfinite(statusSr_v230) && statusSr_v230 > 100.0 ? statusSr_v230 : 44100.0;
    const double pendingSr_v208 = std::isfinite(_digiPendingTakeSampleRateHz_v199_) && _digiPendingTakeSampleRateHz_v199_ > 100.0 ? _digiPendingTakeSampleRateHz_v199_ : recordSr_v208;
    const double sec = (double)written / recordSr_v208;
    if (_digiPreviewActive_v237_.load(std::memory_order_acquire)) {
        NSUInteger pFrames = _digiPreviewFrames_v237_.load(std::memory_order_acquire);
        NSUInteger pDropped = _digiPreviewDroppedFrames_v237_.load(std::memory_order_acquire);
        double pSr = std::isfinite(_digiPreviewSampleRateHz_v237_) && _digiPreviewSampleRateHz_v237_ > 0.0 ? _digiPreviewSampleRateHz_v237_ : 44100.0;
        if (_digiPreviewWasPureSid1Q1Input_v237_) {
            id adapter = _au ? [_au debugAdapter] : nil;
            if (adapter && [adapter respondsToSelector:@selector(pureSid1Q1RecordCaptureStatusFrames:sampleRate:droppedFrames:peak:rms:)]) {
                float pp = 0.0f, rr = 0.0f;
                [(id<ArpSIDDebugAdapterLike>)adapter pureSid1Q1RecordCaptureStatusFrames:&pFrames sampleRate:&pSr droppedFrames:&pDropped peak:&pp rms:&rr];
                _digiPreviewPeak_v237_.store(ArpSIDDigiSanitizeUnitMetric_v271(pp), std::memory_order_release);
                _digiPreviewRms_v237_.store(ArpSIDDigiSanitizeUnitMetric_v271(rr), std::memory_order_release);
                _digiPreviewFrames_v237_.store(pFrames, std::memory_order_release);
                _digiPreviewDroppedFrames_v237_.store(pDropped, std::memory_order_release);
                _digiPreviewSampleRateHz_v237_ = pSr;
            }
        }
        const float pPeak = ArpSIDDigiSanitizeUnitMetric_v271(_digiPreviewPeak_v237_.load(std::memory_order_acquire));
        const float pRms = ArpSIDDigiSanitizeUnitMetric_v271(_digiPreviewRms_v237_.load(std::memory_order_acquire));
        NSString* signalState = @"";
        if (pFrames == 0u && _digiPreviewWasPureSid1Q1Input_v237_) signalState = @"  WAITING FOR AU RENDER";
        else if (pFrames == 0u) signalState = @"  WAITING FOR TAP";
        else if (pPeak <= 0.000001f && pRms <= 0.000001f) signalState = @"  SILENCE/NO SIGNAL";
        meter.stringValue = [NSString stringWithFormat:@"MON %@ %.2fs  PEAK %.0f%%  RMS %.0f%%  DROP %lu%@", [self _digiRecordInputDisplayName_v159_], pSr > 0.0 ? (double)pFrames / pSr : 0.0, pPeak * 100.0f, pRms * 100.0f, (unsigned long)pDropped, signalState];
        return;
    }
    NSString* recSignalState = @"";
    if (_digiRecordActive_v158_.load(std::memory_order_acquire) && written == 0u && _digiRecordWasPureSid1Q1Input_v230_) recSignalState = @"  WAITING FOR AU RENDER";
    else if (_digiRecordActive_v158_.load(std::memory_order_acquire) && written == 0u) recSignalState = @"  WAITING FOR TAP";
    else if (_digiRecordActive_v158_.load(std::memory_order_acquire) && peak <= 0.000001f && rms <= 0.000001f) recSignalState = @"  SILENCE/NO SIGNAL";
    meter.stringValue = _digiRecordActive_v158_.load(std::memory_order_acquire)
        ? [NSString stringWithFormat:@"REC%@ %.2fs  PEAK %.0f%%  RMS %.0f%%  DROP %lu%@", _digiRecordWasPureSid1Q1Input_v230_ ? @" PURE SID" : @"", sec, peak * 100.0f, rms * 100.0f, (unsigned long)dropped, recSignalState]
        : (_digiPendingTakeMonoFloat_v199_.empty()
            ? @"REC idle  KEEP/DISCARD empty"
            : [NSString stringWithFormat:@"TAKE READY S%u %.2fs @ %.0fHz%@  KEEP or DISCARD",
               (unsigned)std::min<std::uint8_t>(_digiPendingTakeSlot_v199_, 7u) + 1u,
               (double)_digiPendingTakeMonoFloat_v199_.size() / pendingSr_v208,
               pendingSr_v208,
               _digiPendingTakeHadDrops_v199_ ? @"  DROP" : @""]);
}

-(void)_digiInvalidatePendingTakeForSlot_v209_:(std::uint8_t)slot reason:(NSString*)reason {
    if (_digiPendingTakeMonoFloat_v199_.empty()) return;
    if (_digiPendingTakeSlot_v199_ != slot) return;
    _digiPendingTakeMonoFloat_v199_.clear();
    _digiPendingTakeHadDrops_v199_ = NO;
    _digiPendingTakeSampleRateHz_v199_ = 44100.0;
    _digiPendingTakeSlot_v199_ = 0u;
    _digiRecordOverwriteArmed_v199_ = NO;
    _digiRecordOverwriteArmedSlot_v208_ = 0xFFu;
    [self _digiRefreshRecordTakeButtons_v199_];
    [self _digiRefreshRecordMeter_v199_];
    if (reason && reason.length > 0 && _digiRuntimeHUDLabel) _digiRuntimeHUDLabel.stringValue = reason;
}

