-(void)_digiRefreshClipboardAndTrimControls_v201_ {
    if (!_pDigiV563) return;
    const BOOL sourceBusy_v245 = _digiRecordActive_v158_.load(std::memory_order_acquire) ||
                                 _digiPreviewActive_v237_.load(std::memory_order_acquire);
    NSButton* paste = (NSButton*)[_pDigiV563 viewWithTag:kArpSIDDigiPasteTag];
    if (paste) paste.enabled = !sourceBusy_v245 && _digiClipboardHasClip_v201_ && ArpSID::GUI::digiUserSampleClipIsPresent(_digiClipboardClip_v201_);
    NSSlider* st = (NSSlider*)[_pDigiV563 viewWithTag:kArpSIDDigiTrimStartTag];
    NSSlider* en = (NSSlider*)[_pDigiV563 viewWithTag:kArpSIDDigiTrimEndTag];
    NSButton* apply = (NSButton*)[_pDigiV563 viewWithTag:kArpSIDDigiTrimApplyTag];
    const std::uint8_t slot = _digiModel_v563_.activeSlot;
    const BOOL hasClip = slot < ArpSID::GUI::kDigiUserSampleSlotCount && ArpSID::GUI::digiUserSampleClipIsPresent(_digiSampleBank_v596_.clips[slot]);
    const BOOL canEditClip_v245 = hasClip && !sourceBusy_v245;
    // preview MON is also an active capture graph. Trim/apply/paste are
    // sample-bank mutations and must not become enabled from a secondary refresh
    // while MON is active.
    if (st) { st.doubleValue = std::clamp(_digiTrimStartPercent_v201_, 0.0, 99.0); st.enabled = canEditClip_v245; }
    if (en) { en.doubleValue = std::clamp(_digiTrimEndPercent_v201_, 1.0, 100.0); en.enabled = canEditClip_v245; }
    if (apply) apply.enabled = canEditClip_v245;
}

-(void)_digiAuditionActiveSlot_v200_:(id)sender {
    (void)sender;
