        [(id<ArpSIDDebugAdapterLike>)adapter triggerDigiPadSlot:slot velocity:_digiGuiPadVelocityControl_v131_ ? _digiGuiPadVelocityControl_v131_ : 110u];
        if (_digiRuntimeHUDLabel) _digiRuntimeHUDLabel.stringValue = [NSString stringWithFormat:@"DIGI AUDITION S%u", (unsigned)slot + 1u];
