    ArpSID::GUI::digiSetUserSampleSlot(_digiModel_v563_.slots[slot], slot, stored.handle);
    _digiModel_v563_.activeSlot = slot;
    ArpSID::GUI::sanitizeDigiPanelModel(_digiModel_v563_);
    // replacing a slot via import/paste/rename must invalidate a stale
    // pending take for that same slot so KEEP cannot later overwrite the newly
    // published sample with an older recording.
    [self _digiInvalidatePendingTakeForSlot_v209_:slot reason:nil];
