-(NSData*)_digiRawD418DataForClip_v199_:(const ArpSID::GUI::DigiUserSampleClip&)clip {
    if (!ArpSID::GUI::digiUserSampleClipIsWellFormed(clip) || !ArpSID::GUI::digiUserSampleClipIsPresent(clip)) return nil;
    NSMutableData* data = [NSMutableData dataWithLength:clip.frameCount];
    uint8_t* dst = (uint8_t*)data.mutableBytes;
    for (std::uint16_t i = 0; i < clip.frameCount; ++i) dst[i] = ArpSID::GUI::digiPcm8ToD418Nibble(clip.pcm[i]) & 0x0Fu;
    return data;
}

-(NSData*)_digiAsmD418DataForClip_v202_:(const ArpSID::GUI::DigiUserSampleClip&)clip slot:(std::uint8_t)slot {
    if (!ArpSID::GUI::digiUserSampleClipIsWellFormed(clip) || !ArpSID::GUI::digiUserSampleClipIsPresent(clip)) return nil;
    NSMutableString* out = [NSMutableString stringWithCapacity:256u + (NSUInteger)clip.frameCount * 5u];
    NSString* name = [self _digiClipDisplayName_v199_:clip fallback:@"sample"];
    NSCharacterSet* bad = [[NSCharacterSet characterSetWithCharactersInString:@"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_"] invertedSet];
    NSString* label = [[name componentsSeparatedByCharactersInSet:bad] componentsJoinedByString:@"_"];
    if (label.length == 0) label = @"sample";
    [out appendFormat:@"; ArpSID DIGI $D418 low-nibble sample export\n"];
    [out appendFormat:@"; slot=%u frames=%u rate=%uHz format=4-bit-low-nibble\n", (unsigned)slot + 1u, (unsigned)clip.frameCount, (unsigned)clip.sourceSampleRateHz];
    [out appendFormat:@"digi_s%u_%@:\n", (unsigned)slot + 1u, label];
    for (std::uint16_t i = 0; i < clip.frameCount; ++i) {
        if ((i % 16u) == 0u) [out appendString:@"    !byte "];
        const unsigned v = (unsigned)(ArpSID::GUI::digiPcm8ToD418Nibble(clip.pcm[i]) & 0x0Fu);
        [out appendFormat:@"$%02X", v];
        if ((i % 16u) == 15u || i + 1u == clip.frameCount) [out appendString:@"\n"];
        else [out appendString:@","];
    }
    return [out dataUsingEncoding:NSUTF8StringEncoding];
}

-(NSData*)_digiWavPreviewDataForClip_v199_:(const ArpSID::GUI::DigiUserSampleClip&)clip {
    if (!ArpSID::GUI::digiUserSampleClipIsWellFormed(clip) || !ArpSID::GUI::digiUserSampleClipIsPresent(clip)) return nil;
    const uint32_t sr = ArpSID::GUI::kDigiUserSampleCanonicalRateHz;
    const uint16_t bits = 16, channels = 1;
    const uint32_t dataBytes = (uint32_t)clip.frameCount * 2u;
    const uint32_t riffSize = 36u + dataBytes;
    NSMutableData* data = [NSMutableData dataWithLength:44u + dataBytes];
    uint8_t* p = (uint8_t*)data.mutableBytes;
    auto put = [&](const char* text, uint32_t n){ for (uint32_t i=0;i<n;++i) *p++ = (uint8_t)text[i]; };
    auto u16 = [&](uint16_t v){ *p++=(uint8_t)(v&255); *p++=(uint8_t)(v>>8); };
    auto u32 = [&](uint32_t v){ *p++=(uint8_t)(v&255); *p++=(uint8_t)((v>>8)&255); *p++=(uint8_t)((v>>16)&255); *p++=(uint8_t)((v>>24)&255); };
    put("RIFF",4); u32(riffSize); put("WAVE",4); put("fmt ",4); u32(16); u16(1); u16(channels); u32(sr); u32(sr * channels * bits / 8); u16(channels * bits / 8); u16(bits); put("data",4); u32(dataBytes);
    for (std::uint16_t i = 0; i < clip.frameCount; ++i) {
        int16_t sample = (int16_t)std::clamp<int>((int)clip.pcm[i] * 256, -32768, 32767);
        u16((uint16_t)sample);
    }
    return data;
}

-(void)_digiExportSample_v199_:(id)sender {
    (void)sender;
    const std::uint8_t slot = _digiModel_v563_.activeSlot;
    if (slot >= ArpSID::GUI::kDigiUserSampleSlotCount) return;
    const auto clip = _digiSampleBank_v596_.clips[slot];
    if (!ArpSID::GUI::digiUserSampleClipIsWellFormed(clip) || !ArpSID::GUI::digiUserSampleClipIsPresent(clip)) {
        if (_digiRuntimeHUDLabel) _digiRuntimeHUDLabel.stringValue = @"DIGI EXPORT EMPTY SLOT";
        return;
    }
    NSSavePanel* panel = [NSSavePanel savePanel];
    panel.nameFieldStringValue = [NSString stringWithFormat:@"digi_s%u_%@.d418", (unsigned)slot + 1u, [self _digiClipDisplayName_v199_:clip fallback:@"sample"]];
    panel.prompt = @"Export D418";
    arpsidSetPanelTypes(panel, @[ @"d418", @"raw", @"wav", @"asm", @"s" ]);
    __weak ArpSIDViewController* weakSelf = self;
    [panel beginSheetModalForWindow:self.view.window completionHandler:^(NSModalResponse result) {
        ArpSIDViewController* strongSelf = weakSelf;
        if (!strongSelf || result != NSModalResponseOK || !panel.URL) return;
        NSString* ext = panel.URL.pathExtension.lowercaseString;
        NSData* data = ([ext isEqualToString:@"wav"])
            ? [strongSelf _digiWavPreviewDataForClip_v199_:clip]
            : (([ext isEqualToString:@"asm"] || [ext isEqualToString:@"s"])
                ? [strongSelf _digiAsmD418DataForClip_v202_:clip slot:slot]
                : [strongSelf _digiRawD418DataForClip_v199_:clip]);
        NSError* err = nil;
        BOOL ok = data && [data writeToURL:panel.URL options:NSDataWritingAtomic error:&err];
        if (strongSelf->_digiRuntimeHUDLabel) strongSelf->_digiRuntimeHUDLabel.stringValue = ok ? @"DIGI SAMPLE EXPORTED" : @"DIGI SAMPLE EXPORT FAILED";
    }];
}

