    [self _digiInvalidatePendingTakeForSlot_v209_:a reason:nil];
    [self _digiInvalidatePendingTakeForSlot_v209_:b reason:nil];
    std::swap(_digiSampleBank_v596_.clips[a], _digiSampleBank_v596_.clips[b]);
    for (std::uint8_t i=0;i<ArpSID::GUI::kDigiUserSampleSlotCount;++i) {
        auto& c = _digiSampleBank_v596_.clips[i];
        if (ArpSID::GUI::digiUserSampleClipIsPresent(c)) ArpSID::GUI::digiRefreshUserClipIdentityForSlot(c, i);
        if (i < ArpSID::GUI::kDigiActiveSlotCount) {
            if (ArpSID::GUI::digiUserSampleClipIsPresent(c)) ArpSID::GUI::digiSetUserSampleSlot(_digiModel_v563_.slots[i], i, c.handle);
            else if (_digiModel_v563_.slots[i].sourceType == ArpSID::GUI::DigiSourceType::UserImport && _digiModel_v563_.slots[i].userSampleIndex == i) ArpSID::GUI::digiSetNoSource(_digiModel_v563_.slots[i]);
        }
    }
    ArpSID::GUI::sanitizeDigiSampleBankBlob(_digiSampleBank_v596_);
    [self _pushDigiStateToAdapter_v565_];
    [self _digiRefreshSlotControls_v563_];
    if (_digiRuntimeHUDLabel) _digiRuntimeHUDLabel.stringValue = [NSString stringWithFormat:@"DIGI SWAPPED S%u ↔ S%u", (unsigned)a+1u, (unsigned)b+1u];
}

-(void)_digiExportKit_v199_:(id)sender {
    (void)sender;
    // snapshot the kit at button time. NSSavePanel completion is async;
    // reading _digiModel_v563_/_digiSampleBank_v596_ inside the block could export
    // a later GUI state than the user chose to save.
    const auto modelSnapshot_v206_ = _digiModel_v563_;
    const auto bankSnapshot_v206_ = _digiSampleBank_v596_;
    const NSUInteger modelBytes = sizeof(modelSnapshot_v206_);
    const NSUInteger bankBytes = sizeof(bankSnapshot_v206_);
    NSMutableData* data = [NSMutableData dataWithLength:sizeof(ArpSIDDigiKitFileHeader_v201) + modelBytes + bankBytes];
    uint8_t* bytes = (uint8_t*)data.mutableBytes;
    ArpSIDDigiKitFileHeader_v201 header{};
    std::memcpy(header.magic, kArpSIDDigiKitMagic_v201, sizeof(header.magic));
    header.version = kArpSIDDigiKitVersion_v201;
    header.modelBytes = (std::uint32_t)modelBytes;
    header.sampleBankBytes = (std::uint32_t)bankBytes;
    std::memcpy(bytes + sizeof(header), &modelSnapshot_v206_, modelBytes);
    std::memcpy(bytes + sizeof(header) + modelBytes, &bankSnapshot_v206_, bankBytes);
    header.payloadHash = [self _digiKitPayloadHash_v201_:bytes + sizeof(header) length:(modelBytes + bankBytes) seed:2166136261u];
    std::memcpy(bytes, &header, sizeof(header));

    NSSavePanel* panel = [NSSavePanel savePanel];
    panel.nameFieldStringValue = @"ArpSID_DIGI_Kit.digikit";
    panel.prompt = @"Export DIGI Kit";
    arpsidSetPanelTypes(panel, @[ @"digikit" ]);
    __weak ArpSIDViewController* weakSelf = self;
    [panel beginSheetModalForWindow:self.view.window completionHandler:^(NSModalResponse result) {
        ArpSIDViewController* strongSelf = weakSelf;
        if (!strongSelf || result != NSModalResponseOK || !panel.URL) return;
        NSError* err = nil;
        BOOL ok = [data writeToURL:panel.URL options:NSDataWritingAtomic error:&err];
        if (strongSelf->_digiRuntimeHUDLabel) strongSelf->_digiRuntimeHUDLabel.stringValue = ok ? @"DIGI KIT EXPORTED v201" : @"DIGI KIT EXPORT FAILED";
    }];
}

-(void)_digiImportKit_v199_:(id)sender {
    (void)sender;
    NSOpenPanel* panel = [NSOpenPanel openPanel];
    panel.allowsMultipleSelection = NO;
    arpsidSetPanelTypes(panel, @[ @"digikit" ]);
    panel.prompt = @"Import DIGI Kit";
    [panel beginSheetModalForWindow:self.view.window completionHandler:^(NSModalResponse result) {
        if (result != NSModalResponseOK || !panel.URL) return;
        NSData* data = [NSData dataWithContentsOfURL:panel.URL];
        const NSUInteger legacyNeed = sizeof(_digiModel_v563_) + sizeof(_digiSampleBank_v596_);
        if (!data) { if (_digiRuntimeHUDLabel) _digiRuntimeHUDLabel.stringValue = @"DIGI KIT IMPORT READ FAILED"; return; }
        const uint8_t* bytes = (const uint8_t*)data.bytes;
        if (data.length == legacyNeed) {
            // Backward compatibility with raw kit blobs, then immediately sanitize/repair.
            std::memcpy(&_digiModel_v563_, bytes, sizeof(_digiModel_v563_));
            std::memcpy(&_digiSampleBank_v596_, bytes + sizeof(_digiModel_v563_), sizeof(_digiSampleBank_v596_));
        } else {
            const NSUInteger need = sizeof(ArpSIDDigiKitFileHeader_v201) + legacyNeed;
            if (data.length != need) { if (_digiRuntimeHUDLabel) _digiRuntimeHUDLabel.stringValue = @"DIGI KIT IMPORT BAD SIZE"; return; }
            ArpSIDDigiKitFileHeader_v201 header{};
            std::memcpy(&header, bytes, sizeof(header));
            if (std::memcmp(header.magic, kArpSIDDigiKitMagic_v201, sizeof(header.magic)) != 0 || header.version != kArpSIDDigiKitVersion_v201 || header.modelBytes != sizeof(_digiModel_v563_) || header.sampleBankBytes != sizeof(_digiSampleBank_v596_)) {
                if (_digiRuntimeHUDLabel) _digiRuntimeHUDLabel.stringValue = @"DIGI KIT IMPORT BAD HEADER";
                return;
            }
            const std::uint32_t hash = [self _digiKitPayloadHash_v201_:bytes + sizeof(header) length:legacyNeed seed:2166136261u];
            if (hash != header.payloadHash) { if (_digiRuntimeHUDLabel) _digiRuntimeHUDLabel.stringValue = @"DIGI KIT IMPORT HASH FAIL"; return; }
            std::memcpy(&_digiModel_v563_, bytes + sizeof(header), sizeof(_digiModel_v563_));
            std::memcpy(&_digiSampleBank_v596_, bytes + sizeof(header) + sizeof(_digiModel_v563_), sizeof(_digiSampleBank_v596_));
        }
        [self _digiBumpSampleWorkflowGeneration_v211_];
        [self _digiAuditAndRepairSampleBankForUIReason:@"kit import"];

        // KIT IN atomically replaces every DIGI slot/sample. Any
        // pending recorded take, overwrite arm or clipboard from the previous
        // kit is now stale and must not be allowed to KEEP/PASTE into the newly
        // imported kit state.
        _digiPendingTakeMonoFloat_v199_.clear();
        _digiPendingTakeHadDrops_v199_ = NO;
        _digiPendingTakeSampleRateHz_v199_ = 44100.0;
        _digiPendingTakeSlot_v199_ = 0u;
        _digiRecordOverwriteArmed_v199_ = NO;
        _digiRecordOverwriteArmedSlot_v208_ = 0xFFu;
        _digiClipboardClip_v201_ = ArpSID::GUI::DigiUserSampleClip{};
        _digiClipboardHasClip_v201_ = NO;
        _digiClipboardSourceSlot_v223_ = 0xFFu;
        [self _pushDigiStateToAdapter_v565_];
        [self _digiRefreshSlotControls_v563_];
        [self _digiRefreshStepGrid_v563_];
        [self _digiRefreshRecordTakeButtons_v199_];
        [self _digiRefreshRecordMeter_v199_];
        if (_digiRuntimeHUDLabel) _digiRuntimeHUDLabel.stringValue = @"DIGI KIT IMPORTED — stale take/clipboard cleared";
    }];
}

