    if (_digiRuntimeHUDLabel) _digiRuntimeHUDLabel.stringValue = [NSString stringWithFormat:@"DIGI TRIM %.0f%%..%.0f%%", _digiTrimStartPercent_v201_, _digiTrimEndPercent_v201_];
}

-(void)_digiApplyDestructiveTrim_v201_:(id)sender {
    (void)sender;
    const std::uint8_t slot = _digiModel_v563_.activeSlot;
    if (slot >= ArpSID::GUI::kDigiUserSampleSlotCount) return;
    auto clip = _digiSampleBank_v596_.clips[slot];
    if (!ArpSID::GUI::digiUserSampleClipIsPresent(clip) || clip.frameCount < 2u) { if (_digiRuntimeHUDLabel) _digiRuntimeHUDLabel.stringValue = @"DIGI TRIM EMPTY SLOT"; return; }
    // destructive trim is a sample-bank mutation and must invalidate
    // any older async import/decode generation before publishing the trimmed clip.
    [self _digiBumpSampleWorkflowGeneration_v211_];
    double stPct = std::clamp(_digiTrimStartPercent_v201_, 0.0, 99.0);
    double enPct = std::clamp(_digiTrimEndPercent_v201_, stPct + 1.0, 100.0);
    const std::uint16_t oldCount = clip.frameCount;
    std::uint16_t first = (std::uint16_t)std::clamp<int>((int)std::floor((stPct / 100.0) * oldCount), 0, oldCount - 1);
    std::uint16_t last = (std::uint16_t)std::clamp<int>((int)std::ceil((enPct / 100.0) * oldCount), first + 1, oldCount);
    const std::uint16_t newCount = (std::uint16_t)(last - first);
    std::array<std::int8_t, ArpSID::GUI::kDigiUserSampleMaxFrames> newPcm{};
    for (std::uint16_t i = 0; i < newCount; ++i) newPcm[i] = clip.pcm[first + i];
    std::memset(clip.pcm, 0, sizeof(clip.pcm));
    std::memcpy(clip.pcm, newPcm.data(), newCount);
    clip.frameCount = newCount;
    ArpSID::GUI::digiRefreshUserClipIdentityForSlot(clip, slot);
    _digiSampleBank_v596_.clips[slot] = clip;
    ArpSID::GUI::digiSetUserSampleSlot(_digiModel_v563_.slots[slot], slot, clip.handle);
    [self _digiInvalidatePendingTakeForSlot_v209_:slot reason:nil];
    [self _pushDigiStateToAdapter_v565_];
    [self _digiRefreshSlotControls_v563_];
    [self _digiRefreshStepGrid_v563_];
    if (_digiRuntimeHUDLabel) _digiRuntimeHUDLabel.stringValue = [NSString stringWithFormat:@"DIGI TRIMMED S%u %u→%u frames", (unsigned)slot+1u, (unsigned)oldCount, (unsigned)newCount];
}

-(BOOL)_digiImportSampleURL_v596_:(NSURL*)url slot:(std::uint8_t)slot {
    if (!url || slot >= ArpSID::GUI::kDigiActiveSlotCount) return NO;
    const ArpSIDDigiConvertMode_v199 convertMode = _digiConvertMode_v199_;
    const BOOL normalize = _digiNormalizeOnImportRecord_v199_;
    const BOOL trim = _digiTrimOnImportRecord_v199_;
    if (_digiRuntimeHUDLabel) _digiRuntimeHUDLabel.stringValue = @"DIGI IMPORTING…";
    const std::uint32_t importGeneration_v211_ = [self _digiBumpSampleWorkflowGeneration_v211_];

    NSURL* importURL = [url copy];
    NSString* importName = [importURL.lastPathComponent copy];
    __weak ArpSIDViewController* weakSelf = self;
    dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
        @autoreleasepool {
            NSError* err = nil;
            AVAudioFile* file = [[AVAudioFile alloc] initForReading:importURL
                                                       commonFormat:AVAudioPCMFormatFloat32
                                                        interleaved:NO
                                                              error:&err];
            if (!file || err) {
                dispatch_async(dispatch_get_main_queue(), ^{
                    ArpSIDViewController* strongSelf = weakSelf;
                    if (!strongSelf) return;
                    [strongSelf _digiSetImportFailureHUDIfCurrent_v213_:importGeneration_v211_ message:@"DIGI IMPORT FAILED"];
                    ARPSID_UI_LOG(@"[ArpSID DIGI] import open failed: %@", err);
                });
                return;
            }

            const AVAudioFramePosition total = file.length;
            if (total <= 0) {
                dispatch_async(dispatch_get_main_queue(), ^{
                    ArpSIDViewController* strongSelf = weakSelf;
                    if (!strongSelf) return;
                    [strongSelf _digiSetImportFailureHUDIfCurrent_v213_:importGeneration_v211_ message:@"DIGI IMPORT EMPTY"];
                });
                return;
            }

            const AVAudioFrameCount framesToRead = (AVAudioFrameCount)std::min<long long>((long long)total, (long long)ArpSID::GUI::kDigiRecordCaptureMaxFrames);
            AVAudioPCMBuffer* buffer = [[AVAudioPCMBuffer alloc] initWithPCMFormat:file.processingFormat
                                                                     frameCapacity:framesToRead];
            if (!buffer) {
                dispatch_async(dispatch_get_main_queue(), ^{
                    ArpSIDViewController* strongSelf = weakSelf;
                    if (!strongSelf) return;
                    [strongSelf _digiSetImportFailureHUDIfCurrent_v213_:importGeneration_v211_ message:@"DIGI IMPORT BUFFER FAILED"];
                });
                return;
            }
            err = nil;
            if (![file readIntoBuffer:buffer frameCount:framesToRead error:&err] || err || buffer.frameLength == 0) {
                dispatch_async(dispatch_get_main_queue(), ^{
                    ArpSIDViewController* strongSelf = weakSelf;
                    if (!strongSelf) return;
                    [strongSelf _digiSetImportFailureHUDIfCurrent_v213_:importGeneration_v211_ message:@"DIGI IMPORT READ FAILED"];
                    ARPSID_UI_LOG(@"[ArpSID DIGI] import read failed: %@", err);
                });
                return;
            }

            const UInt32 channels = buffer.format.channelCount;
            float* const* channelData = buffer.floatChannelData;
            if (channels == 0u || !channelData) {
                dispatch_async(dispatch_get_main_queue(), ^{
                    ArpSIDViewController* strongSelf = weakSelf;
                    if (!strongSelf) return;
                    [strongSelf _digiSetImportFailureHUDIfCurrent_v213_:importGeneration_v211_ message:@"DIGI IMPORT FORMAT FAILED"];
                });
                return;
            }

            const NSUInteger frames = (NSUInteger)buffer.frameLength;
            auto mono = std::make_shared<std::vector<float>>(frames, 0.0f);
            for (NSUInteger i = 0; i < frames; ++i) {
                float sum = 0.0f;
                UInt32 validChannels = 0u;
                for (UInt32 ch = 0; ch < channels; ++ch) {
                    const float* cd = channelData[ch];
                    if (!cd) continue;
                    sum += cd[i];
                    ++validChannels;
                }
                if (validChannels == 0u) {
                    dispatch_async(dispatch_get_main_queue(), ^{
                        ArpSIDViewController* strongSelf = weakSelf;
                        if (!strongSelf) return;
                        [strongSelf _digiSetImportFailureHUDIfCurrent_v213_:importGeneration_v211_ message:@"DIGI IMPORT FORMAT FAILED"];
                    });
                    return;
                }
                (*mono)[i] = std::clamp(sum / (float)validChannels, -1.0f, 1.0f);
            }
            const double rawSampleRate = buffer.format.sampleRate;
            const double safeSampleRate = std::isfinite(rawSampleRate) ? rawSampleRate : 44100.0;
            const char* utf8 = [importName UTF8String];
            const std::uint32_t len = utf8
                ? (std::uint32_t)std::min<std::size_t>(std::strlen(utf8), std::numeric_limits<std::uint32_t>::max())
                : 0u;
            ArpSIDDigiRecordPreparedMono_v161 prepared = ArpSIDDigiPrepareRecordedMono_v161(mono->data(),
                                                                                                  (std::uint32_t)std::min<std::size_t>(mono->size(), std::numeric_limits<std::uint32_t>::max()),
                                                                                                  trim,
                                                                                                  normalize,
                                                                                                  convertMode);
            if (prepared.samples.empty()) {
                dispatch_async(dispatch_get_main_queue(), ^{
                    ArpSIDViewController* strongSelf = weakSelf;
                    if (!strongSelf) return;
                    [strongSelf _digiSetImportFailureHUDIfCurrent_v213_:importGeneration_v211_ message:@"DIGI IMPORT SILENCE / EMPTY AFTER TRIM"];
                });
                return;
            }
            const std::vector<float>& publishSamples = prepared.samples;
            ArpSID::GUI::DigiUserSampleClip builtClip = ArpSID::GUI::makeDefaultDigiUserSampleClip();
            const bool loaded = ArpSID::GUI::digiBuildUserSampleClipFromFloatMono(builtClip,
                                                                                  slot,
                                                                                  publishSamples.data(),
                                                                                  (std::uint32_t)std::min<std::size_t>(publishSamples.size(), std::numeric_limits<std::uint32_t>::max()),
                                                                                  (std::uint32_t)std::clamp<double>(std::round(safeSampleRate), 1000.0, 384000.0),
                                                                                  utf8,
                                                                                  len);
            auto loadedClip = std::make_shared<ArpSID::GUI::DigiUserSampleClip>(builtClip);
            const bool truncated = ArpSID::GUI::digiWouldTruncateToUserSampleBank(
                (std::uint32_t)std::min<std::size_t>(publishSamples.size(), std::numeric_limits<std::uint32_t>::max()),
                (std::uint32_t)std::clamp<double>(std::round(safeSampleRate), 1000.0, 384000.0));
            if (!loaded) {
                dispatch_async(dispatch_get_main_queue(), ^{
                    ArpSIDViewController* strongSelf = weakSelf;
                    if (!strongSelf) return;
                    [strongSelf _digiSetImportFailureHUDIfCurrent_v213_:importGeneration_v211_ message:@"DIGI IMPORT FAILED"];
                });
                return;
            }

            dispatch_async(dispatch_get_main_queue(), ^{
                ArpSIDViewController* strongSelf = weakSelf;
                if (!strongSelf) return;
                if (![strongSelf _digiIsSampleWorkflowGenerationCurrent_v211_:importGeneration_v211_]) {
                    // stale async import success must be completely silent.
                    // guarded failure HUD writes, but this success-stale branch
                    // could still overwrite the newer workflow's HUD with a stale-status
                    // message after kit import, clear-all, paste, trim, record KEEP, etc.
                    // Returning silently preserves the newer user-visible state.
                    return;
                }
                id adapter = strongSelf->_au ? [strongSelf->_au debugAdapter] : nil;
                if (!adapter || ![adapter respondsToSelector:@selector(setDigiModel:sampleBank:)]) {
                    if (strongSelf->_digiRuntimeHUDLabel) strongSelf->_digiRuntimeHUDLabel.stringValue = @"DIGI IMPORT ATOMIC ADAPTER MISSING";
                    return;
                }

                ArpSID::GUI::sanitizeDigiSampleBankBlob(strongSelf->_digiSampleBank_v596_);
                strongSelf->_digiSampleBank_v596_.clips[slot] = *loadedClip;
                ArpSID::GUI::digiRecountSampleBank(strongSelf->_digiSampleBank_v596_);
                const auto& clip = strongSelf->_digiSampleBank_v596_.clips[slot];
                strongSelf->_digiLastTruncated_v199_ = truncated ? YES : NO;
                ArpSID::GUI::digiSetUserSampleSlot(strongSelf->_digiModel_v563_.slots[slot], slot, clip.handle);
                strongSelf->_digiModel_v563_.activeSlot = slot;
                ArpSID::GUI::sanitizeDigiPanelModel(strongSelf->_digiModel_v563_);
                // async import replaces the slot; invalidate a stale
                // pending take for the same slot before publishing the new bank.
                [strongSelf _digiInvalidatePendingTakeForSlot_v209_:slot reason:nil];
                [(id<ArpSIDDebugAdapterLike>)adapter setDigiModel:&strongSelf->_digiModel_v563_
                                                        sampleBank:&strongSelf->_digiSampleBank_v596_];
                [strongSelf _pullDigiStateFromAdapter_v565_];
                [strongSelf _digiRefreshSlotControls_v563_];
                [strongSelf _digiRefreshStepGrid_v563_];
                if (strongSelf->_digiRuntimeHUDLabel) strongSelf->_digiRuntimeHUDLabel.stringValue = [NSString stringWithFormat:@"DIGI IMPORTED%@  %@", truncated ? @"  TRUNC" : @"", ArpSIDDigiConvertModeName_v199(convertMode)];
            });
        }
    });
    return YES;
}


-(void)_digiSetImportFailureHUDIfCurrent_v213_:(std::uint32_t)generation message:(NSString*)message {
    // async import/decode has many fail-fast exits. Those exits must
    // be generation-gated too, not only the success/publish path; otherwise an
    // older background import can overwrite the HUD/status after a newer kit,
    // clear, paste, trim, record KEEP or source mutation has already won.
    if (![self _digiIsSampleWorkflowGenerationCurrent_v211_:generation]) return;
    if (_digiRuntimeHUDLabel) _digiRuntimeHUDLabel.stringValue = message ? message : @"DIGI IMPORT FAILED";
}

-(void)_digiImportSample_v596_:(id)sender {
    (void)sender;
    const std::uint8_t slot = _digiModel_v563_.activeSlot;
    NSOpenPanel* panel = [NSOpenPanel openPanel];
    panel.canChooseFiles = YES;
    panel.canChooseDirectories = NO;
    panel.allowsMultipleSelection = NO;
    panel.prompt = @"Import";
#if ARPSID_HAS_UTTYPE
    if (@available(macOS 11.0, *)) {
        panel.allowedContentTypes = @[ UTTypeAudio ];
    }
#endif

    void (^finish)(NSModalResponse) = ^(NSModalResponse result) {
        if (result != NSModalResponseOK || panel.URLs.count == 0) return;
        [self _digiImportSampleURL_v596_:panel.URLs.firstObject slot:slot];
    };

    NSWindow* window = self.view.window;
    if (window) {
        [panel beginSheetModalForWindow:window completionHandler:finish];
    } else {
        finish([panel runModal]);
    }
}


-(BOOL)_digiCommitRecordedMono_v158_:(const float*)samples
                               count:(std::uint32_t)count
                              slot:(std::uint8_t)slot
                        sampleRate:(std::uint32_t)sampleRate {
    if (!samples || count == 0u || slot >= ArpSID::GUI::kDigiActiveSlotCount) return NO;
    id adapter = _au ? [_au debugAdapter] : nil;
    if (!adapter || ![adapter respondsToSelector:@selector(setDigiModel:sampleBank:)]) {
        if (_digiRuntimeHUDLabel) _digiRuntimeHUDLabel.stringValue = @"DIGI REC ATOMIC ADAPTER MISSING";
        return NO;
    }

    // record KEEP/commit mutates the persisted user-sample bank.
    // Bump the sample workflow generation so any older async import/decode
    // cannot publish over the newly committed take.
    [self _digiBumpSampleWorkflowGeneration_v211_];

    _digiRecordCommittedFrames_v161_ = 0u;
    _digiRecordTrimmedFrames_v161_ = 0u;
    _digiRecordNormalized_v161_ = NO;
    ArpSIDDigiRecordPreparedMono_v161 prepared = ArpSIDDigiPrepareRecordedMono_v161(samples, count, _digiTrimOnImportRecord_v199_, _digiNormalizeOnImportRecord_v199_, _digiConvertMode_v199_);
    if (prepared.samples.empty()) return NO;
    _digiLastTruncated_v199_ = ArpSID::GUI::digiWouldTruncateToUserSampleBank(
        (std::uint32_t)std::min<std::size_t>(prepared.samples.size(), std::numeric_limits<std::uint32_t>::max()),
        std::clamp<std::uint32_t>(sampleRate, 1000u, 384000u)) ? YES : NO;
    // this must report the persisted C64 $D418 byte count, not the
    // pre-bank prepared host-vector length. digiLoadUserSampleFromFloatMono()
    // can decimate/truncate to the centralized under-8s canonical bank limit, so setting
    // the HUD/telemetry count before load made long takes look longer than the
    // stored/authentic sample.
    _digiRecordCommittedFrames_v161_ = 0u;
    _digiRecordTrimmedFrames_v161_ = prepared.trimmedFrames;
    _digiRecordNormalized_v161_ = prepared.normalized ? YES : NO;

    char name[32]{};
    std::snprintf(name, sizeof(name), "REC_SLOT_%u", (unsigned)(slot + 1u));
    const std::uint32_t preparedFrameCount_v205_ = (std::uint32_t)std::min<std::size_t>(
        prepared.samples.size(),
        (std::size_t)std::numeric_limits<std::uint32_t>::max());
    ArpSID::GUI::DigiUserSampleClip builtClip = ArpSID::GUI::makeDefaultDigiUserSampleClip();
    const bool loaded = ArpSID::GUI::digiBuildUserSampleClipFromFloatMono(builtClip,
                                                                          slot,
                                                                          prepared.samples.data(),
                                                                          preparedFrameCount_v205_,
                                                                          std::clamp<std::uint32_t>(sampleRate, 1000u, 384000u),
                                                                          name,
                                                                          (std::uint32_t)std::strlen(name));
    if (!loaded) return NO;

    ArpSID::GUI::sanitizeDigiSampleBankBlob(_digiSampleBank_v596_);
    _digiSampleBank_v596_.clips[slot] = builtClip;
    ArpSID::GUI::digiRecountSampleBank(_digiSampleBank_v596_);
    const auto& clip = _digiSampleBank_v596_.clips[slot];
    _digiRecordCommittedFrames_v161_ = clip.frameCount;
    _digiLastTruncated_v199_ = ArpSID::GUI::digiWouldTruncateToUserSampleBank(
        preparedFrameCount_v205_,
        std::clamp<std::uint32_t>(sampleRate, 1000u, 384000u)) ? YES : NO;
    ArpSID::GUI::digiSetUserSampleSlot(_digiModel_v563_.slots[slot], slot, clip.handle);
    _digiModel_v563_.activeSlot = slot;
    [self _pushDigiStateToAdapter_v565_];
    [self _pullDigiStateFromAdapter_v565_];
    [self _digiRefreshSlotControls_v563_];
    [self _digiRefreshStepGrid_v563_];
    return YES;
}


-(BOOL)_digiWaitForRecordTapCallbacksToDrain_v185_:(NSUInteger)spinLimit {
    for (NSUInteger spin = 0; spin < spinLimit; ++spin) {
        if (_digiRecordTapCallbacksInFlight_v184_.load(std::memory_order_acquire) == 0u) return YES;
        // audit P2.16: deterministic non-render back-off. yield() can return
        // immediately and starve under DAW thread scheduling, making the spin
        // budget meaningless; a fixed short sleep gives a bounded real wait.
        std::this_thread::sleep_for(std::chrono::milliseconds(1));
    }
    return _digiRecordTapCallbacksInFlight_v184_.load(std::memory_order_acquire) == 0u;
}


-(void)_digiCancelActiveRecordWithoutTake_v232_:(NSString*)reason {
    const BOOL wasActive = _digiRecordActive_v158_.load(std::memory_order_acquire) ? YES : NO;
    const BOOL hadEngine = (_digiRecordEngine_v158_ != nil) ? YES : NO;
    const BOOL wasPure = _digiRecordWasPureSid1Q1Input_v230_ ? YES : NO;
    const BOOL hadOutputTap = (_digiRecordUseOutputTap_v248_ || _digiPreviewUseOutputTap_v248_ ||
                               _digiOutputTapAggregateID_v248_ != kAudioObjectUnknown) ? YES : NO;
    const BOOL hadAudioQueue = (_digiRecordUseAudioQueue_v251_ || _digiPreviewUseAudioQueue_v251_ ||
                                _digiAQRecordCapture_v251_ || _digiAQPreviewCapture_v251_) ? YES : NO;
    if (!wasActive && !hadEngine && !wasPure && !hadOutputTap && !hadAudioQueue) return;

    _digiRecordActive_v158_.store(false, std::memory_order_release);
    _digiPreviewActive_v237_.store(false, std::memory_order_release);
    _digiRecordGeneration_v184_.fetch_add(1u, std::memory_order_acq_rel);
    // tear down any device-bound AudioQueue capture (REC or MON).
    if (hadAudioQueue) {
        if (_digiAQRecordCapture_v251_) _digiAQRecordCapture_v251_->stop(true);
        if (_digiAQPreviewCapture_v251_) _digiAQPreviewCapture_v251_->stop(true);
