        _digiPreviewUseAudioQueue_v251_ = NO;
    }

    AVAudioEngine* engine = _digiRecordEngine_v158_;
    _digiRecordEngine_v158_ = nil;
    if (engine) {
        @try { [[engine inputNode] removeTapOnBus:0]; } @catch (__unused NSException* ex) {}
        [engine stop];
    }
    // tear down any active output-capture graph (REC or MON).
    if (hadOutputTap) {
        [self _digiStopOutputTap_v248_];
        _digiRecordUseOutputTap_v248_ = NO;
        _digiPreviewUseOutputTap_v248_ = NO;
    }

    if (wasPure) {
        id adapter = _au ? [_au debugAdapter] : nil;
        if (adapter && [adapter respondsToSelector:@selector(copyAndStopPureSid1Q1RecordCapture:maxFrames:frameCount:sampleRate:droppedFrames:)]) {
            NSUInteger frames = 0u;
            NSUInteger drops = 0u;
            double sr = 44100.0;
            [(id<ArpSIDDebugAdapterLike>)adapter copyAndStopPureSid1Q1RecordCapture:nullptr
                                                                           maxFrames:0u
                                                                          frameCount:&frames
                                                                          sampleRate:&sr
                                                                       droppedFrames:&drops];
        }
    }

    [self _digiRestorePreviousRecordInputDevice_v159_];
    _digiRecordWasPureSid1Q1Input_v230_ = NO;
    _digiRecordAutoStopQueued_v160_.store(false, std::memory_order_release);
    _digiRecordWriteFrames_v182_.store(0, std::memory_order_release);
    _digiRecordDroppedFrames_v160_.store(0, std::memory_order_release);
    _digiRecordPeak_v199_.store(0.0f, std::memory_order_release);
    _digiRecordRms_v199_.store(0.0f, std::memory_order_release);
    _digiPendingTakeMonoFloat_v199_.clear();
    _digiPendingTakeHadDrops_v199_ = NO;
    _digiPendingTakeSampleRateHz_v199_ = 44100.0;
    _digiPendingTakeSlot_v199_ = 0u;
    [self _digiSetRecordControlsEnabled_v160_:YES];
    [self _digiRefreshRecordTakeButtons_v199_];
    [self _digiRefreshRecordMeter_v199_];
    NSButton* recBtn = _pDigiV563 ? (NSButton*)[_pDigiV563 viewWithTag:kArpSIDDigiRecordTag] : nil;
    if (recBtn) { recBtn.title = @"REC ●"; recBtn.state = NSControlStateValueOff; }
    if (reason && _digiRuntimeHUDLabel) _digiRuntimeHUDLabel.stringValue = reason;
}



// after MON/REC starts, emit an actionable diagnostic if the graph is
// active but still no frames have arrived. This prevents the old "everything is
// 0" failure mode from looking like a valid monitor with silence.
-(void)_digiScheduleRecMonNoDataDiagnostic_v243Preview:(BOOL)preview pure:(BOOL)pure sourceUID:(NSString*)sourceUID {
    NSString* expectedUID = sourceUID ? [sourceUID copy] : @"";
    __weak ArpSIDViewController* weakSelf = self;
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)(1.10 * NSEC_PER_SEC)), dispatch_get_main_queue(), ^{
        ArpSIDViewController* strongSelf = weakSelf;
        if (!strongSelf) return;
        if (strongSelf->_controllerTearingDown_v277_.load(std::memory_order_acquire)) return;
        NSString* currentUID = strongSelf->_digiRecordInputDeviceUID_v159_ ? strongSelf->_digiRecordInputDeviceUID_v159_ : @"";
        if (![currentUID isEqualToString:expectedUID]) return;
        if (preview) {
            if (!strongSelf->_digiPreviewActive_v237_.load(std::memory_order_acquire)) return;
            if (strongSelf->_digiPreviewFrames_v237_.load(std::memory_order_acquire) != 0u) return;
        } else {
            if (!strongSelf->_digiRecordActive_v158_.load(std::memory_order_acquire)) return;
            if (strongSelf->_digiRecordWriteFrames_v182_.load(std::memory_order_acquire) != 0u) return;
        }
        NSString* msg = nil;
        if (pure) {
            msg = preview
                ? @"DIGI MON WAITING FOR AU RENDER — play SID notes / start host transport"
                : @"DIGI REC WAITING FOR AU RENDER — play SID notes / start host transport";
        } else if ([strongSelf _digiRecordInputIsCoreAudioOutputMonitor_v236_]) {
            if (strongSelf->_digiRecordUseOutputTap_v248_ || strongSelf->_digiPreviewUseOutputTap_v248_) {
                if (strongSelf->_digiOutputTapUnsupportedFmtCount_v253_.load(std::memory_order_acquire) > 0u) {
                    // Tap is delivering audio in a PCM layout the converter rejects.
                    msg = @"DIGI OUTPUT TAP UNSUPPORTED FORMAT — captured ASBD is not a supported packed little-endian PCM/Float32 layout; see Console for flags/bits/stride";
                } else {
                    // Real process-tap path is running but produced no frames yet:
                    // either nothing is playing to that output, or the host has not
                    // been granted audio-recording permission.
                    msg = @"DIGI OUTPUT CAPTURE: no system audio yet — play audio to the selected output; if it stays silent, grant the host audio-recording permission in System Settings ▸ Privacy & Security";
                }
            } else {
                msg = @"DIGI MON/REC OUTPUT SOURCE HAS NO INPUT STREAM — select routed CoreAudio Input/BlackHole directly";
            }
        } else {
            // No tap buffers arrived. The most common cause is that the host
            // process lacks (or was never granted) microphone access, so macOS
            // hands the tap silent buffers. Name the host so the user knows which
            // app to authorize. The "WAITING FOR TAP" prefix is preserved for the
            // diagnostic contract; the suffix makes the fix actionable.
            NSString* host = [strongSelf _digiHostAppName_v246_];
            msg = preview
                ? [NSString stringWithFormat:@"DIGI MON WAITING FOR TAP — grant Microphone to %@ in System Settings ▸ Privacy & Security ▸ Microphone, then check the selected input/routing", host]
                : [NSString stringWithFormat:@"DIGI REC WAITING FOR TAP — grant Microphone to %@ in System Settings ▸ Privacy & Security ▸ Microphone, then check the selected input/routing", host];
        }
        if (strongSelf->_digiRuntimeHUDLabel) strongSelf->_digiRuntimeHUDLabel.stringValue = msg;
        [strongSelf _digiRefreshRecordMeter_v199_];
    });
}

// silence-aware no-data diagnostic. Distinguishes "no callbacks" (no
// permission / wrong device) from "callbacks but silence" (muted/wrong source or
// tap format), which the old frame-count-only check could not.
-(void)_digiScheduleRecMonNoDataDiagnostic_v250Preview:(BOOL)preview pure:(BOOL)pure sourceUID:(NSString*)sourceUID {
    (void)pure;
    NSString* expectedUID = sourceUID ? [sourceUID copy] : @"";
    const NSUInteger startFrames = preview
        ? _digiPreviewFrames_v237_.load(std::memory_order_acquire)
        : _digiRecordWriteFrames_v182_.load(std::memory_order_acquire);
    __weak ArpSIDViewController* weakSelf = self;
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)(1.5 * NSEC_PER_SEC)), dispatch_get_main_queue(), ^{
        ArpSIDViewController* s = weakSelf;
        if (!s) return;
        if (s->_controllerTearingDown_v277_.load(std::memory_order_acquire)) return;
        NSString* currentUID = s->_digiRecordInputDeviceUID_v159_ ? s->_digiRecordInputDeviceUID_v159_ : @"";
        if (![currentUID isEqualToString:expectedUID]) return;
        const BOOL active = preview ? s->_digiPreviewActive_v237_.load(std::memory_order_acquire)
                                    : s->_digiRecordActive_v158_.load(std::memory_order_acquire);
        if (!active) return;
        const NSUInteger nowFrames = preview ? s->_digiPreviewFrames_v237_.load(std::memory_order_acquire)
                                             : s->_digiRecordWriteFrames_v182_.load(std::memory_order_acquire);
        const float nowRms = preview ? s->_digiPreviewRms_v237_.load(std::memory_order_acquire)
                                     : s->_digiRecordRms_v199_.load(std::memory_order_acquire);
        const float nowPeak = preview ? s->_digiPreviewPeak_v237_.load(std::memory_order_acquire)
                                      : s->_digiRecordPeak_v199_.load(std::memory_order_acquire);
        NSString* host = [s _digiHostAppName_v246_];
        NSString* msg = nil;
        if (nowFrames <= startFrames) {
            msg = preview
                ? [NSString stringWithFormat:@"DIGI MON NO CALLBACKS — grant Microphone/Audio to %@ in System Settings, or reselect the input device", host]
                : [NSString stringWithFormat:@"DIGI REC NO CALLBACKS — grant Microphone/Audio to %@ in System Settings, or reselect the input device", host];
        } else if (nowRms < 0.0001f && nowPeak < 0.0002f) {
            // cross-check the AudioQueue HARDWARE meter. If the device
            // itself shows level but our converted RMS is ~0, the conversion path
            // is at fault (format), not the source.
            ArpSID::Digi::AQCapture* aq = preview ? s->_digiAQPreviewCapture_v251_.get() : s->_digiAQRecordCapture_v251_.get();
            BOOL hwHasSignal = NO;
            if (aq && aq->pollQueueMeters()) {
                if (aq->stats().queuePeakDB.load(std::memory_order_acquire) > -60.0f) hwHasSignal = YES;
            }
            const uint64_t unsupported = aq ? aq->stats().unsupportedFormatBuffers.load(std::memory_order_acquire) : 0u;
            if (unsupported > 0u) {
                msg = preview ? @"DIGI MON UNSUPPORTED INPUT FORMAT — device delivered a non-Float/planar PCM the converter rejects"
                              : @"DIGI REC UNSUPPORTED INPUT FORMAT — device delivered a non-Float/planar PCM the converter rejects";
            } else if (hwHasSignal) {
                msg = preview ? @"DIGI MON DEVICE HAS SIGNAL BUT CONVERSION = 0 — format/channel mapping problem"
                              : @"DIGI REC DEVICE HAS SIGNAL BUT CONVERSION = 0 — format/channel mapping problem";
            } else {
                msg = preview ? @"DIGI MON CALLBACKS BUT SILENCE — wrong source, muted input, or nothing playing to the tapped output"
                              : @"DIGI REC CALLBACKS BUT SILENCE — wrong source, muted input, or nothing playing to the tapped output";
            }
        }
        if (msg && s->_digiRuntimeHUDLabel) s->_digiRuntimeHUDLabel.stringValue = msg;
        [s _digiRefreshRecordMeter_v199_];
    });
}

// single always-on diagnostic line emitted when a capture starts, so a
// field "no signal" report can be diagnosed from Console.app (filter "ArpSID DIGI").
-(void)_digiLogCaptureDiagnostics_v249_:(NSString*)phase preview:(BOOL)preview {
    AVAuthorizationStatus mic = [AVCaptureDevice authorizationStatusForMediaType:AVMediaTypeAudio];
    const char* micStr = (mic == AVAuthorizationStatusAuthorized) ? "authorized"
                       : (mic == AVAuthorizationStatusDenied) ? "DENIED"
                       : (mic == AVAuthorizationStatusRestricted) ? "restricted" : "not-determined";
    NSLog(@"[ArpSID DIGI] %@ %@ | source=%@ | pureSID=%d | outputMonitor=%d | tapAvailable=%d | audioPerm=%s | host=%@",
          preview ? @"MON" : @"REC", phase ? phase : @"start",
          _digiRecordInputDeviceUID_v159_.length ? _digiRecordInputDeviceUID_v159_ : @"(system default input)",
          (int)[self _digiRecordInputIsPureSid1Q1_v230_],
          (int)[self _digiRecordInputIsCoreAudioOutputMonitor_v236_],
          (int)[self _digiOutputTapAvailable_v248_],
          micStr,
          [self _digiHostAppName_v246_]);
}

// choose the device-bound AudioQueue input backend for normal/loopback
// inputs. Pure SID uses the internal render ring; output monitor on macOS 14.2+
// uses the process tap; pre-14.2 output monitor resolves to a loopback input UID
// which AudioQueue then captures directly.
-(BOOL)_digiShouldUseAudioQueueInput_v251_ {
    if ([self _digiRecordInputIsPureSid1Q1_v230_]) return NO;
    if ([self _digiRecordInputIsCoreAudioOutputMonitor_v236_]) {
        if ([self _digiOutputTapAvailable_v248_]) return NO; // process tap path
        return _digiRecordResolvedInputDeviceUID_v236_.length > 0; // resolved loopback input
    }
    return YES;
}

// true when this macOS build/runtime can capture output via a Core
// Audio process tap (no BlackHole/loopback needed).
-(BOOL)_digiOutputTapAvailable_v248_ {
#if ARPSID_HAS_COREAUDIO_PROCESS_TAP
    if (@available(macOS 14.2, *)) return YES;
#endif
    return NO;
}

// RT-safe ingest of mono output-tap frames into the MON preview meters.
-(void)_digiOutputTapIngestPreview_v248_:(const float*)mono count:(uint32_t)n {
    if (!mono || n == 0u || !_digiPreviewActive_v237_.load(std::memory_order_acquire)) return;
    float peak = 0.0f; double sumSq = 0.0;
    for (uint32_t i = 0u; i < n; ++i) { const float v = std::isfinite(mono[i]) ? std::clamp(mono[i], -1.0f, 1.0f) : 0.0f; peak = std::max(peak, std::fabs(v)); sumSq += (double)v * v; }
    _digiPreviewFrames_v237_.fetch_add((NSUInteger)n, std::memory_order_acq_rel);
    _digiPreviewPeak_v237_.store(ArpSIDDigiSanitizeUnitMetric_v271(peak), std::memory_order_release);
    _digiPreviewRms_v237_.store(ArpSIDDigiRmsFromSumSq_v271(sumSq, n), std::memory_order_release);
}

// RT-safe ingest of mono output-tap frames into the REC capture buffer.
// Mirrors the reservation/auto-stop contract of the AVAudioEngine record tap.
-(void)_digiOutputTapIngestRecord_v248_:(const float*)mono count:(uint32_t)n {
    if (!mono || n == 0u || !_digiRecordActive_v158_.load(std::memory_order_acquire)) return;
    // audit P1 (output-tap): take the SAME unified record-buffer writer lease as
    // the AVAudioEngine tap (_digiRecordTapCallbacksInFlight_v184_) around the
    // shared _digiRecordMonoFloatBuffer_v182_ write. Previously this writer was
    // only covered by the output-tap IOProc lease, so _digiWaitForRecordTapCallbacks
    // ToDrain_v185_ (which the finalize path uses) could report "drained" while an
    // output-tap write was still in progress. With both backends on one lease, a
    // single drain wait proves no backend is mid-write before the take is read.
    _digiRecordTapCallbacksInFlight_v184_.fetch_add(1u, std::memory_order_acq_rel);
    struct ArpSIDDigiRecordBufferWriterLease_v248 {
        std::atomic<std::uint32_t>* c = nullptr;
        ~ArpSIDDigiRecordBufferWriterLease_v248(){ if (c) c->fetch_sub(1u, std::memory_order_acq_rel); }
    } recordWriterLease{ &_digiRecordTapCallbacksInFlight_v184_ };
    const NSUInteger maxFrames = _digiRecordMaxFrames_v160_ > 0u ? _digiRecordMaxFrames_v160_ : ArpSID::GUI::kDigiRecordCaptureMaxFrames;
    if (_digiRecordMonoFloatBuffer_v182_.size() < maxFrames) {
        _digiRecordDroppedFrames_v160_.fetch_add(n, std::memory_order_relaxed);
        return;
    }
    const NSUInteger reservedStart = _digiRecordWriteFrames_v182_.fetch_add(n, std::memory_order_acq_rel);
    if (reservedStart >= maxFrames) {
        _digiRecordDroppedFrames_v160_.fetch_add(n, std::memory_order_relaxed);
        if (!_digiRecordAutoStopQueued_v160_.exchange(true, std::memory_order_acq_rel)) {
            __weak ArpSIDViewController* weakSelf = self;
            dispatch_async(dispatch_get_main_queue(), ^{
                ArpSIDViewController* strongSelf = weakSelf;
                if(!strongSelf) return;
                if(strongSelf->_controllerTearingDown_v277_.load(std::memory_order_acquire)) return;
                [strongSelf _digiStopRecord_v158_:nil];
            });
        }
        return;
    }
    const NSUInteger writeEnd = std::min<NSUInteger>(reservedStart + n, maxFrames);
    NSUInteger writePos = reservedStart;
    float peak = 0.0f; double sumSq = 0.0; std::uint32_t cnt = 0u;
    for (uint32_t i = 0u; i < n && writePos < writeEnd; ++i, ++writePos) {
        const float v = mono[i];
        _digiRecordMonoFloatBuffer_v182_[writePos] = v;
        peak = std::max(peak, std::fabs(v)); sumSq += (double)v * v; ++cnt;
    }
    _digiRecordPeak_v199_.store(ArpSIDDigiSanitizeUnitMetric_v271(peak), std::memory_order_release);
    _digiRecordRms_v199_.store(ArpSIDDigiRmsFromSumSq_v271(sumSq, cnt), std::memory_order_release);
    if (reservedStart + n >= maxFrames) {
        if (reservedStart + n > maxFrames)
            _digiRecordDroppedFrames_v160_.fetch_add((reservedStart + n) - maxFrames, std::memory_order_relaxed);
        if (!_digiRecordAutoStopQueued_v160_.exchange(true, std::memory_order_acq_rel)) {
            __weak ArpSIDViewController* weakSelf = self;
            dispatch_async(dispatch_get_main_queue(), ^{
                ArpSIDViewController* strongSelf = weakSelf;
                if(!strongSelf) return;
                if(strongSelf->_controllerTearingDown_v277_.load(std::memory_order_acquire)) return;
                [strongSelf _digiStopRecord_v158_:nil];
            });
        }
    }
}

// start the output-capture backend for MON (preview=YES) or REC.
// Returns YES on success; on failure sets _digiOutputTapFailureReason_v248_.
-(BOOL)_digiStartOutputTapForPreview_v248_:(BOOL)preview {
    _digiOutputTapFailureReason_v248_ = nil;
    NSString* outputUID = [self _digiRecordInputCoreAudioOutputUID_v236_];
    if (!outputUID.length) { _digiOutputTapFailureReason_v248_ = @"DIGI OUTPUT TAP MISSING OUTPUT UID"; return NO; }
    if (![self _digiOutputTapAvailable_v248_]) {
        _digiOutputTapFailureReason_v248_ = @"DIGI OUTPUT TAP NEEDS macOS 14.2+ — select a CoreAudio Input/BlackHole/Loopback instead";
        return NO;
    }
    // audit P0 (output-tap): a previous tap graph may still have IOProc callbacks
    // in flight. Tear it down and PROVE drain before resetting the in-flight
    // counter / scratch-claim flags and (re)assigning the scratch ring vectors —
    // otherwise a late callback can write into a vector we are reallocating or run
    // against an in-flight count we just zeroed.
    if (![self _digiStopOutputTap_v248_]) {
        _digiOutputTapFailureReason_v248_ = @"DIGI OUTPUT TAP BUSY — previous capture callbacks still in flight";
        return NO;
    }
    for (auto& scratchBuf : _digiOutputTapMonoScratchRing_v255_) {
        if (scratchBuf.size() < 16384u) scratchBuf.assign(16384u, 0.0f);
    }
    _digiOutputTapScratchIndex_v255_.store(0u, std::memory_order_release);
    for (auto& claimed : _digiOutputTapScratchClaimed_v259_) claimed.store(false, std::memory_order_release);
    _digiOutputTapCallbacksInFlight_v256_.store(0u, std::memory_order_release);
    _digiOutputTapCallbackCount_v256_.store(0u, std::memory_order_release);
    _digiOutputTapStopping_v257_.store(false, std::memory_order_release);
    const uint32_t outputTapGen = _digiOutputTapGeneration_v257_.fetch_add(1u, std::memory_order_acq_rel) + 1u;
    _digiOutputTapUnsupportedFmtCount_v253_.store(0, std::memory_order_release);
    __weak ArpSIDViewController* weakSelf = self;
    const BOOL isPreview = preview;
    AudioDeviceIOBlock ioBlock = ^(const AudioTimeStamp* __unused inNow,
                                   const AudioBufferList* inInputData,
                                   const AudioTimeStamp* __unused inInputTime,
                                   AudioBufferList* __unused outOutputData,
                                   const AudioTimeStamp* __unused inOutputTime) {
        ArpSIDViewController* s = weakSelf;
        if (!s) return;
        // audit P0 (output-tap): register the in-flight lease BEFORE touching any
        // other shared state (the stopping/generation gates, the callback counter,
        // the scratch ring). Previously the increment happened only after those
        // reads, leaving a window where _digiStopOutputTap's drain wait could
        // observe zero in-flight callbacks and let teardown/restart reassign the
        // scratch ring while this block was still reading s->... The guard covers
        // the entire callback body on every return path.
        s->_digiOutputTapCallbacksInFlight_v256_.fetch_add(1u, std::memory_order_acq_rel);
        struct ArpSIDDigiOutputTapInFlightGuard_v256 {
            std::atomic<uint32_t>* v = nullptr;
            ~ArpSIDDigiOutputTapInFlightGuard_v256(){ if (v) v->fetch_sub(1u, std::memory_order_acq_rel); }
        } inFlightGuard{&s->_digiOutputTapCallbacksInFlight_v256_};
        if (s->_digiOutputTapStopping_v257_.load(std::memory_order_acquire)) return;
        if (s->_digiOutputTapGeneration_v257_.load(std::memory_order_acquire) != outputTapGen) return;
        // Diagnostic: log the first callback and then every ~2s worth so we can
        // confirm the IOProc is firing and whether buffers actually carry audio.
        const uint64_t idx = s->_digiOutputTapCallbackCount_v256_.fetch_add(1u, std::memory_order_relaxed);
        if (inInputData && (idx == 0 || (idx % 200u) == 0u)) {
            uint32_t b0bytes = inInputData->mNumberBuffers ? inInputData->mBuffers[0].mDataByteSize : 0u;
            uint32_t b0ch = inInputData->mNumberBuffers ? inInputData->mBuffers[0].mNumberChannels : 0u;
            ARPSID_DIGI_TAP_LOG(@"IOProc cb#%llu buffers=%u ch=%u bytes=%u%@",
                                (unsigned long long)idx,
                                (unsigned)inInputData->mNumberBuffers, (unsigned)b0ch, (unsigned)b0bytes,
                                idx == 0 ? @"  (first callback — capture graph is live)" : @"");
        }
        if (!inInputData) return;
        const uint32_t ringSize = (uint32_t)s->_digiOutputTapMonoScratchRing_v255_.size();
        if (ringSize == 0u) return;
        if (s->_digiOutputTapCallbacksInFlight_v256_.load(std::memory_order_acquire) > ringSize) {
            s->_digiOutputTapUnsupportedFmtCount_v253_.fetch_add(1, std::memory_order_relaxed);
            return;
        }
        // claim an actually-free scratch slot; modulo alone can collide
        // with an older still-active callback if callbacks finish out of order.
        uint32_t scratchSlot = UINT32_MAX;
        const uint32_t startSlot = s->_digiOutputTapScratchIndex_v255_.fetch_add(1u, std::memory_order_relaxed) % ringSize;
        for (uint32_t probe = 0; probe < ringSize; ++probe) {
            const uint32_t candidate = (startSlot + probe) % ringSize;
            bool expected = false;
            if (s->_digiOutputTapScratchClaimed_v259_[candidate].compare_exchange_strong(expected, true, std::memory_order_acq_rel)) {
                scratchSlot = candidate;
                break;
            }
        }
        if (scratchSlot == UINT32_MAX) {
            s->_digiOutputTapUnsupportedFmtCount_v253_.fetch_add(1, std::memory_order_relaxed);
            return;
        }
        struct ArpSIDDigiOutputTapScratchClaimGuard_v259 {
            std::atomic<bool>* slot = nullptr;
            ~ArpSIDDigiOutputTapScratchClaimGuard_v259(){ if (slot) slot->store(false, std::memory_order_release); }
        } scratchClaimGuard{&s->_digiOutputTapScratchClaimed_v259_[scratchSlot]};
        std::vector<float>& scratchVec = s->_digiOutputTapMonoScratchRing_v255_[scratchSlot];
        float* scratch = scratchVec.data();
        const uint32_t cap = (uint32_t)scratchVec.size();
        if (!scratch || cap == 0u) return;
        // if the tap ASBD is KNOWN but a layout we cannot convert
        // (big-endian / aligned-high / odd bit depth), fail closed and count it.
        // Do not reinterpret the bytes as Float32; that fakes signal/garbage.
        if (s->_digiOutputTapASBD_v250_.mFormatID != 0 && !ArpSIDDigiTapASBDSupported_v253(s->_digiOutputTapASBD_v250_)) {
            s->_digiOutputTapUnsupportedFmtCount_v253_.fetch_add(1, std::memory_order_relaxed);
            return;
        }
        // ASBD-correct mixdown (handles supported Int16/24/32 and Float32 layouts).
        uint32_t frames = ArpSIDDigiOutputTapMixMonoFromASBD_v250(inInputData, s->_digiOutputTapASBD_v250_, scratch, cap);
        if (frames == 0u) {
            // Only fall back to the legacy Float32-interleaved reader when the tap
            // ASBD is UNKNOWN (format query failed). If the ASBD is known but the
            // mixdown produced nothing, do NOT reinterpret the bytes as float.
            if (s->_digiOutputTapASBD_v250_.mFormatID == 0) {
                frames = ArpSIDDigiOutputTapMixMono_v248(inInputData, scratch, cap);
            } else {
                s->_digiOutputTapUnsupportedFmtCount_v253_.fetch_add(1, std::memory_order_relaxed);
                return;
            }
        }
        if (frames == 0u) return;
        // re-check generation after conversion before writing to REC/MON,
        // because stop may have raced while this IOProc was mixing into scratch.
        if (s->_digiOutputTapStopping_v257_.load(std::memory_order_acquire)) return;
        if (s->_digiOutputTapGeneration_v257_.load(std::memory_order_acquire) != outputTapGen) return;
        if (isPreview) [s _digiOutputTapIngestPreview_v248_:scratch count:frames];
        else           [s _digiOutputTapIngestRecord_v248_:scratch count:frames];
    };
    NSString* err = nil;
    double sr = 48000.0;
    const BOOL ok = ArpSIDDigiOutputTapStart_v248(outputUID, ioBlock,
                                                  &_digiOutputTapTapID_v248_,
                                                  &_digiOutputTapAggregateID_v248_,
                                                  &_digiOutputTapIOProcID_v248_,
                                                  &sr, &_digiOutputTapASBD_v250_, &err);
    if (!ok) { _digiOutputTapFailureReason_v248_ = err ? err : @"DIGI OUTPUT TAP START FAILED"; return NO; }
    _digiOutputTapSampleRate_v248_ = (std::isfinite(sr) && sr > 100.0) ? sr : 48000.0;
    return YES;
}

// stop + destroy the output-capture backend (idempotent).
// audit P0 (output-tap): returns YES iff all in-flight IOProc callbacks have
// drained. Callers MUST NOT treat the record/scratch buffers as safe to read or
// reassign when this returns NO — a late callback may still be writing them.
-(BOOL)_digiStopOutputTap_v248_ {
    _digiOutputTapStopping_v257_.store(true, std::memory_order_release);
    _digiOutputTapGeneration_v257_.fetch_add(1u, std::memory_order_acq_rel);
    ArpSIDDigiOutputTapStop_v248(&_digiOutputTapTapID_v248_,
                                 &_digiOutputTapAggregateID_v248_,
                                 &_digiOutputTapIOProcID_v248_);
    // CoreAudio stop/destroy should quiesce the IOProc, but wait
    // defensively for any block that already entered before reusing the scratch
    // ring or letting REC/MON read final counters. This mirrors the AQ callback
    // in-flight guard and closes teardown lifetime races.
    for (uint32_t spin = 0; _digiOutputTapCallbacksInFlight_v256_.load(std::memory_order_acquire) != 0u && spin < 2000u; ++spin) {
        std::this_thread::sleep_for(std::chrono::milliseconds(1));
    }
    const BOOL drained = (_digiOutputTapCallbacksInFlight_v256_.load(std::memory_order_acquire) == 0u);
    if (!drained) {
        // Leave stopping=true and the generation bumped so any callback still
        // executing is rejected by the in-flight-first gates above before it can
        // touch REC/MON state. Surface the failure instead of silently pretending
        // the buffers are safe.
        ARPSID_DIGI_TAP_LOG(@"OUTPUT TAP STOP DRAIN FAILED — IOProc callbacks still in flight");
    }
    return drained;
}

-(void)_digiStopSourcePreview_v237_:(id)sender {
    (void)sender;
    // device-bound AudioQueue MON path.
    if (_digiPreviewUseAudioQueue_v251_ || _digiAQPreviewCapture_v251_) {
        _digiPreviewActive_v237_.store(false, std::memory_order_release);
        _digiPreviewGeneration_v253_.fetch_add(1u, std::memory_order_acq_rel); // invalidate stale callbacks
        if (_digiAQPreviewCapture_v251_) _digiAQPreviewCapture_v251_->stop(true);
        _digiAQPreviewCapture_v251_.reset();
        ArpSIDReleaseRetainedObjCContext_v777(_digiAQPreviewContext_v777_);
        _digiPreviewUseAudioQueue_v251_ = NO;
        _digiPreviewWasPureSid1Q1Input_v237_ = NO;
        _digiPreviewFrames_v237_.store(0, std::memory_order_release);
        _digiPreviewDroppedFrames_v237_.store(0, std::memory_order_release);
        _digiPreviewPeak_v237_.store(0.0f, std::memory_order_release);
        _digiPreviewRms_v237_.store(0.0f, std::memory_order_release);
        _digiPreviewSampleRateHz_v237_ = 44100.0;
        [self _digiSetRecordControlsEnabled_v160_:YES];
        [self _digiRefreshRecordMeter_v199_];
        if (_digiRuntimeHUDLabel) _digiRuntimeHUDLabel.stringValue = @"DIGI SOURCE MONITOR OFF";
        return;
    }
    if (_digiPreviewUseOutputTap_v248_ || _digiOutputTapAggregateID_v248_ != kAudioObjectUnknown) {
        // Output-tap MON path: tear down the process-tap graph (blocks until the
        // IOProc has stopped) before clearing preview state.
        _digiPreviewActive_v237_.store(false, std::memory_order_release);
        [self _digiStopOutputTap_v248_];
        _digiPreviewUseOutputTap_v248_ = NO;
        _digiPreviewWasPureSid1Q1Input_v237_ = NO;
        _digiPreviewFrames_v237_.store(0, std::memory_order_release);
        _digiPreviewDroppedFrames_v237_.store(0, std::memory_order_release);
        _digiPreviewPeak_v237_.store(0.0f, std::memory_order_release);
        _digiPreviewRms_v237_.store(0.0f, std::memory_order_release);
        _digiPreviewSampleRateHz_v237_ = 44100.0;
        [self _digiSetRecordControlsEnabled_v160_:YES];
        [self _digiRefreshRecordMeter_v199_];
        if (_digiRuntimeHUDLabel) _digiRuntimeHUDLabel.stringValue = @"DIGI SOURCE MONITOR OFF";
        return;
    }
    if (!_digiPreviewActive_v237_.load(std::memory_order_acquire) && !_digiPreviewEngine_v237_) return;
    const BOOL wasPure = _digiPreviewWasPureSid1Q1Input_v237_ ? YES : NO;
    _digiPreviewActive_v237_.store(false, std::memory_order_release);
    AVAudioEngine* engine = _digiPreviewEngine_v237_;
    _digiPreviewEngine_v237_ = nil;
    if (engine) {
        @try { [[engine inputNode] removeTapOnBus:0]; } @catch (__unused NSException* ex) {}
        [engine stop];
    }
    if (wasPure) {
        id adapter = _au ? [_au debugAdapter] : nil;
        if (adapter && [adapter respondsToSelector:@selector(copyAndStopPureSid1Q1RecordCapture:maxFrames:frameCount:sampleRate:droppedFrames:)]) {
            NSUInteger frames = 0u, drops = 0u;
            double sr = 44100.0;
            [(id<ArpSIDDebugAdapterLike>)adapter copyAndStopPureSid1Q1RecordCapture:nullptr
                                                                           maxFrames:0u
                                                                          frameCount:&frames
                                                                          sampleRate:&sr
                                                                       droppedFrames:&drops];
        }
    }
    [self _digiRestorePreviousRecordInputDevice_v159_];
    _digiPreviewWasPureSid1Q1Input_v237_ = NO;
    _digiPreviewFrames_v237_.store(0, std::memory_order_release);
    _digiPreviewDroppedFrames_v237_.store(0, std::memory_order_release);
    _digiPreviewPeak_v237_.store(0.0f, std::memory_order_release);
    _digiPreviewRms_v237_.store(0.0f, std::memory_order_release);
    _digiPreviewSampleRateHz_v237_ = 44100.0;
    [self _digiSetRecordControlsEnabled_v160_:YES];
    [self _digiRefreshRecordMeter_v199_];
    if (_digiRuntimeHUDLabel) _digiRuntimeHUDLabel.stringValue = @"DIGI SOURCE MONITOR OFF";
}

-(void)_digiStartSourcePreview_v237_:(id)sender {
    (void)sender;
    if (_digiRecordActive_v158_.load(std::memory_order_acquire) || _digiPreviewActive_v237_.load(std::memory_order_acquire)) return;
    [self _digiRefreshRecordInputPopup_v159_];
