                        if (b) b.state = (s == (NSInteger)requestedSlot) ? NSControlStateValueOn : NSControlStateValueOff;
                    }
                }
                [strongSelf _digiRefreshSlotControls_v563_];
                [strongSelf _digiRefreshStepGrid_v563_];
                [strongSelf _pushDigiStateToAdapter_v565_];
            }
            [strongSelf _digiRefreshRecordInputPopup_v159_];
            [strongSelf _digiStartRecord_v158_:sender];
        });
    }];
}


-(void)_digiKeepRecordedTake_v199_:(id)sender {
    (void)sender;
    if (_digiPendingTakeMonoFloat_v199_.empty()) { if (_digiRuntimeHUDLabel) _digiRuntimeHUDLabel.stringValue = @"DIGI KEEP: NO TAKE"; return; }
    const std::uint8_t slot = _digiPendingTakeSlot_v199_ < ArpSID::GUI::kDigiUserSampleSlotCount ? _digiPendingTakeSlot_v199_ : _digiModel_v563_.activeSlot;
    _digiModel_v563_.activeSlot = slot;
    const std::uint32_t count = (std::uint32_t)std::min<std::size_t>(_digiPendingTakeMonoFloat_v199_.size(), std::numeric_limits<std::uint32_t>::max());
    const BOOL ok = [self _digiCommitRecordedMono_v158_:_digiPendingTakeMonoFloat_v199_.data()
                                                    count:count
                                                     slot:slot
                                               sampleRate:(std::uint32_t)std::clamp<double>(std::round(_digiPendingTakeSampleRateHz_v199_), 1000.0, 384000.0)];
    NSString* flags = [NSString stringWithFormat:@"%@%@%@%@  %@", _digiPendingTakeHadDrops_v199_ ? @"  DROP" : @"", _digiRecordTrimmedFrames_v161_ ? @"  TRIM" : @"", _digiRecordNormalized_v161_ ? @"  NORM" : @"", _digiLastTruncated_v199_ ? @"  TRUNC" : @"", ArpSIDDigiConvertModeName_v199(_digiConvertMode_v199_)];
    _digiPendingTakeMonoFloat_v199_.clear();
    _digiPendingTakeHadDrops_v199_ = NO;
    _digiPendingTakeSampleRateHz_v199_ = 44100.0;
    _digiPendingTakeSlot_v199_ = 0u;
    _digiRecordOverwriteArmed_v199_ = NO;
    _digiRecordOverwriteArmedSlot_v208_ = 0xFFu;
    [self _digiRefreshSlotControls_v563_];
    [self _digiRefreshRecordTakeButtons_v199_];
    [self _digiRefreshRecordMeter_v199_];
    if (_digiRuntimeHUDLabel) _digiRuntimeHUDLabel.stringValue = ok ? [NSString stringWithFormat:@"DIGI REC SAVED S%u %u→%u frames%@", (unsigned)slot + 1u, (unsigned)count, (unsigned)_digiRecordCommittedFrames_v161_, flags] : @"DIGI REC SAVE FAILED";
}

-(void)_digiDiscardRecordedTake_v199_:(id)sender {
    (void)sender;
    _digiPendingTakeMonoFloat_v199_.clear();
    _digiPendingTakeHadDrops_v199_ = NO;
    _digiPendingTakeSampleRateHz_v199_ = 44100.0;
    _digiPendingTakeSlot_v199_ = 0u;
    _digiRecordOverwriteArmed_v199_ = NO;
    _digiRecordOverwriteArmedSlot_v208_ = 0xFFu;
    [self _digiRefreshRecordTakeButtons_v199_];
    [self _digiRefreshRecordMeter_v199_];
    if (_digiRuntimeHUDLabel) _digiRuntimeHUDLabel.stringValue = @"DIGI TAKE DISCARDED";
}

-(void)_digiClearUserSample_v596_:(id)sender {
    (void)sender;
    const std::uint8_t slot = _digiModel_v563_.activeSlot;
    if (slot >= ArpSID::GUI::kDigiActiveSlotCount) return;
    // clear mutates a user-sample slot and must cancel stale async
    // imports targeting an older view of the bank.
    [self _digiBumpSampleWorkflowGeneration_v211_];
    ArpSID::GUI::digiClearUserSample(_digiSampleBank_v596_, slot);
    _digiRecordOverwriteArmed_v199_ = NO;
    _digiRecordOverwriteArmedSlot_v208_ = 0xFFu;
    if (_digiClipboardHasClip_v201_ && _digiClipboardSourceSlot_v223_ == slot) {
        _digiClipboardClip_v201_ = ArpSID::GUI::DigiUserSampleClip{};
        _digiClipboardHasClip_v201_ = NO;
        _digiClipboardSourceSlot_v223_ = 0xFFu;
    }
    // clearing the target slot also discards an uncommitted take for
    // that slot; otherwise KEEP could resurrect a stale pre-clear recording.
    [self _digiInvalidatePendingTakeForSlot_v209_:slot reason:nil];
    for (std::uint8_t i = 0; i < ArpSID::GUI::kDigiActiveSlotCount; ++i) {
        ArpSID::GUI::DigiSampleSlot& s = _digiModel_v563_.slots[i];
        if (s.sourceType == ArpSID::GUI::DigiSourceType::UserImport &&
            s.userSampleIndex == slot) {
            ArpSID::GUI::digiSetNoSource(s);
        }
    }
    [self _pushDigiStateToAdapter_v565_];
    [self _digiRefreshSlotControls_v563_];
    [self _digiRefreshStepGrid_v563_];
    if (_digiRuntimeHUDLabel) _digiRuntimeHUDLabel.stringValue = @"DIGI USER SAMPLE CLEARED";
}

