-(void)_digiRefreshSlotControls_v563_ {
    if (!_pDigiV563) return;
    const std::uint8_t slot = _digiModel_v563_.activeSlot;
    if (slot >= ArpSID::GUI::kDigiActiveSlotCount) return;
    const ArpSID::GUI::DigiSampleSlot& s = _digiModel_v563_.slots[slot];

    NSPopUpButton* srcPop = (NSPopUpButton*)[_pDigiV563 viewWithTag:kArpSIDDigiSourceTag];
    if (srcPop) [srcPop selectItemAtIndex:(NSInteger)s.sourceType];

    NSStepper* fsSt = (NSStepper*)[_pDigiV563 viewWithTag:kArpSIDDigiFactorySlotTag];
    if (fsSt) fsSt.intValue = (int)s.factorySlotIndex;
    NSTextField* fsLbl = (NSTextField*)[_pDigiV563 viewWithTag:kArpSIDDigiFactorySlotLblTag];
    if (fsLbl) fsLbl.stringValue = [NSString stringWithFormat:@"%d", (int)s.factorySlotIndex];

    NSStepper* tuneSt = (NSStepper*)[_pDigiV563 viewWithTag:kArpSIDDigiTuneTag];
    int semitones = ArpSID::GUI::digiTuneShift(s);
    if (tuneSt) tuneSt.intValue = semitones;
    NSTextField* tuneLbl = (NSTextField*)[_pDigiV563 viewWithTag:kArpSIDDigiTuneLblTag];
    if (tuneLbl) tuneLbl.stringValue = [NSString stringWithFormat:@"%+d st", semitones];

    NSSlider* startSl = (NSSlider*)[_pDigiV563 viewWithTag:kArpSIDDigiStartTag];
    if (startSl) startSl.intValue = (int)s.startOffset;
    NSTextField* startLbl = (NSTextField*)[_pDigiV563 viewWithTag:kArpSIDDigiStartLblTag];
    if (startLbl) startLbl.stringValue = [NSString stringWithFormat:@"%d", (int)s.startOffset];

    NSSlider* lenSl = (NSSlider*)[_pDigiV563 viewWithTag:kArpSIDDigiLenTag];
    if (lenSl) lenSl.intValue = (int)s.lengthScale;
    NSTextField* lenLbl = (NSTextField*)[_pDigiV563 viewWithTag:kArpSIDDigiLenLblTag];
    if (lenLbl) lenLbl.stringValue = (s.lengthScale == 0) ? @"ALL"
        : [NSString stringWithFormat:@"%d", (int)s.lengthScale];

    NSSlider* volSl = (NSSlider*)[_pDigiV563 viewWithTag:kArpSIDDigiVolTag];
    if (volSl) volSl.intValue = (int)s.volume;
    NSTextField* volLbl = (NSTextField*)[_pDigiV563 viewWithTag:kArpSIDDigiVolLblTag];
    if (volLbl) volLbl.stringValue = [NSString stringWithFormat:@"%d", (int)s.volume];

    NSButton* loopBtn = (NSButton*)[_pDigiV563 viewWithTag:kArpSIDDigiFlagTagBase + 0];
    if (loopBtn) loopBtn.state = ArpSID::GUI::digiLoopEnabled(s)
                                  ? NSControlStateValueOn : NSControlStateValueOff;
    NSButton* revBtn  = (NSButton*)[_pDigiV563 viewWithTag:kArpSIDDigiFlagTagBase + 1];
    if (revBtn)  revBtn.state  = ArpSID::GUI::digiReverseEnabled(s)
                                  ? NSControlStateValueOn : NSControlStateValueOff;

    NSTextField* userLbl = (NSTextField*)[_pDigiV563 viewWithTag:kArpSIDDigiUserNameLblTag];
    if (userLbl) userLbl.stringValue = [self _digiUserSampleStatusString_v596_];

    // the late-added sampler workflow buttons are slot-content dependent.
    // Keep them synchronized from the central slot refresh path so slot changes,
    // import, paste, clear, kit import and destructive trim cannot leave stale
    // enabled buttons behind.
    const BOOL activeHasUserClip_v207_ = [self _digiActiveSlotHasUserSample_v199_];
    NSButton* exportBtn_v207 = (NSButton*)[_pDigiV563 viewWithTag:kArpSIDDigiExportTag];
    NSButton* renameBtn_v207 = (NSButton*)[_pDigiV563 viewWithTag:kArpSIDDigiRenameTag];
    NSButton* copyBtn_v207   = (NSButton*)[_pDigiV563 viewWithTag:kArpSIDDigiCopyTag];
    NSButton* swapBtn_v207   = (NSButton*)[_pDigiV563 viewWithTag:kArpSIDDigiSwapTag];
    NSButton* clearBtn_v207  = (NSButton*)[_pDigiV563 viewWithTag:kArpSIDDigiClearUserTag];
    if (exportBtn_v207) exportBtn_v207.enabled = activeHasUserClip_v207_;
    if (renameBtn_v207) renameBtn_v207.enabled = activeHasUserClip_v207_;
    if (copyBtn_v207)   copyBtn_v207.enabled   = activeHasUserClip_v207_;
    if (swapBtn_v207)   swapBtn_v207.enabled   = activeHasUserClip_v207_;
    if (clearBtn_v207)  clearBtn_v207.enabled  = activeHasUserClip_v207_;

    // make the visible audition affordances match the runtime guard.
    // Empty/no-source slots are not just ignored after click; the PLAY button and
    // GUI pads are disabled when their target slot cannot resolve to audible DIGI.
    NSButton* auditionBtn_v219 = (NSButton*)[_pDigiV563 viewWithTag:kArpSIDDigiAuditionTag];
    if (auditionBtn_v219) auditionBtn_v219.enabled = [self _digiSlotHasPlayableSource_v218_:slot];
    for (NSUInteger i_v219 = 0; i_v219 < _digiGuiPadButtons_v124_.count; ++i_v219) {
        NSButton* pad_v219 = _digiGuiPadButtons_v124_[i_v219];
        if (pad_v219) pad_v219.enabled = [self _digiSlotHasPlayableSource_v218_:(std::uint8_t)i_v219];
    }

    if (_digiSamplePreviewView_v262_) {
        const BOOL hasPendingForSlot_v262 = (_digiPendingTakeSlot_v199_ == slot && !_digiPendingTakeMonoFloat_v199_.empty());
        const ArpSID::GUI::DigiUserSampleClip& clip_v262 = (slot < ArpSID::GUI::kDigiUserSampleSlotCount)
            ? _digiSampleBank_v596_.clips[slot]
            : _digiSampleBank_v596_.clips[0];
        [_digiSamplePreviewView_v262_ updateWithClip:clip_v262
                                                slot:slot
                                         pendingMono:_digiPendingTakeMonoFloat_v199_
                                   pendingSampleRate:_digiRecordSampleRateHz_v160_
                                             pending:hasPendingForSlot_v262
                                              status:[self _digiUserSampleStatusString_v596_]];
    }

    [self _digiRefreshClipboardAndTrimControls_v201_];
    [self _digiRefreshRecordTakeButtons_v199_];
    [self _digiRefreshRecordMeter_v199_];
}

-(void)_digiRefreshStepGrid_v563_ {
    if (!_pDigiV563) return;
    const std::uint8_t slot = _digiModel_v563_.activeSlot;
    for (NSInteger step = 0; step < (NSInteger)ArpSID::GUI::kDigiStepCount; ++step) {
        NSButton* b = (NSButton*)[_pDigiV563 viewWithTag:kArpSIDDigiStepTagBase + step];
        if (b) b.state = ArpSID::GUI::digiStepIsActive(_digiModel_v563_, slot, (std::uint8_t)step)
                         ? NSControlStateValueOn : NSControlStateValueOff;
    }
}

// ── v564: DIGI tab NSView builder ─────────────────────────────────────────────
//
// Layout:
// header row (hdrH): "◈ DIGI SAMPLE PLAYER" title
// left sidebar (sideW): 8 slot buttons [SLOT 1]..[SLOT 8]
// right area:
// top (controlH): per-slot controls — SOURCE popup, SLOT stepper+lbl,
// TUNE stepper+lbl, START slider+lbl, LEN slider+lbl,
// VOL slider+lbl, LOOP / REV flag buttons
// bottom (stepH): 32-step grid (2 rows × 16 cols)
//
-(NSView*)_digiPanel_v563_:(NSRect)r {
    ArpSIDDigiDropView* dropView = [[ArpSIDDigiDropView alloc] initWithFrame:r];
    dropView.digiDropOwner = self;
    NSView* v = dropView;
    v.wantsLayer = YES;
    v.layer.backgroundColor = NSColor.clearColor.CGColor;

    const CGFloat p      = ArpSIDUIDynamicPanelInset(r.size.width);
    const CGFloat hdrH   = 24.0f;
    const CGFloat sideW  = ArpSIDUIDynamicSideWidth(r.size.width);
    const CGFloat stepH  = 76.0f;   // 2 rows × 16 cols
    const CGFloat btnH   = 20.0f;
    const CGFloat w      = r.size.width;
    const CGFloat h      = r.size.height;
    const CGFloat rightX = p + sideW + p;
    const CGFloat rightW = w - rightX - p;
    const CGFloat stepY  = p;
    const CGFloat ctrlY __attribute__((unused)) = stepY + stepH + p;

    // Actual control area height:
    const CGFloat controlH __attribute__((unused)) = h - hdrH - p - stepH - p - p;

    // ── header ────────────────────────────────────────────────────────────────
    {
        NSTextField* title = [NSTextField labelWithString:@"◈ DIGI SAMPLE PLAYER"];
        title.font      = monoBF(11.0f);
        title.textColor = colTitle();
        title.frame     = NSMakeRect(p, h - hdrH, 220.0f, hdrH - 2.0f);
        [v addSubview:title];

        _digiRuntimeSlotLabel = [NSTextField labelWithString:@"STEP --  LAST --  V0"];
        _digiRuntimeSlotLabel.font = monoBF(9.0f);
        _digiRuntimeSlotLabel.textColor = [c64Cyan() colorWithAlphaComponent:0.82f];
        _digiRuntimeSlotLabel.alignment = NSTextAlignmentRight;
        _digiRuntimeSlotLabel.frame = NSMakeRect(std::max<CGFloat>(p + 224.0f, w - 292.0f),
                                                 h - hdrH + 2.0f,
                                                 190.0f,
                                                 hdrH - 6.0f);
        [v addSubview:_digiRuntimeSlotLabel];

        const NSArray<NSString*>* ledTips = @[
            @"DIGI sequencer enabled",
            @"DIGI sampler voices or active steps present",
            @"DIGI realtime output activity"
        ];
        for(NSInteger i=0;i<3;++i){
            ArpSIDLEDView* led = [[ArpSIDLEDView alloc] initWithFrame:
                NSMakeRect(w - p - 70.0f + (CGFloat)i * 23.0f, h - hdrH + 3.0f, 18.0f, hdrH - 8.0f)];
            led.toolTip = ledTips[(NSUInteger)i];
            [v addSubview:led];
            if(i==0) _digiSeqLED = led;
            else if(i==1) _digiPlayLED = led;
            else _digiRtLED = led;
        }
    }

    // ── left sidebar: 8 slot buttons ──────────────────────────────────────────
    {
        const CGFloat slotAreaH = h - hdrH - p * 2.0f;
        const CGFloat slotBtnHRaw = (slotAreaH - (ArpSID::GUI::kDigiActiveSlotCount - 1) * 3.0f)
                                     / (CGFloat)ArpSID::GUI::kDigiActiveSlotCount;
        const CGFloat slotBtnH  = (slotBtnHRaw < 28.0f) ? slotBtnHRaw : 28.0f;
        for (NSInteger s = 0; s < (NSInteger)ArpSID::GUI::kDigiActiveSlotCount; ++s) {
            CGFloat by = h - hdrH - p - (s + 1) * (slotBtnH + 3.0f) + 3.0f;
            NSButton* btn = [NSButton buttonWithTitle:[NSString stringWithFormat:@"SLOT %ld", (long)(s + 1)]
                                               target:self
                                               action:@selector(_digiSlotSelected_v563_:)];
            btn.buttonType  = NSButtonTypePushOnPushOff;
            btn.font        = monoBF(8.5f);
            btn.frame       = NSMakeRect(p, by, sideW, slotBtnH);
            btn.tag         = kArpSIDDigiSlotTagBase + s;
            btn.state       = (s == 0) ? NSControlStateValueOn : NSControlStateValueOff;
            [v addSubview:btn];
        }
    }

    // ── per-slot controls (right-top area) ────────────────────────────────────
    {
        const CGFloat cx  = rightX;
        const CGFloat cw  = rightW;
        const CGFloat top = h - hdrH - p;
        CGFloat curY = top;

        // Row 1: SOURCE popup + SLOT stepper+label + TUNE stepper+label
        {
            // SOURCE label + popup
            NSTextField* srcLbl = [NSTextField labelWithString:@"SRC"];
            srcLbl.font = monoBF(8.5f); srcLbl.textColor = colLabel();
            srcLbl.frame = NSMakeRect(cx, curY - 14.0f, 30.0f, 12.0f);
            [v addSubview:srcLbl];

            NSPopUpButton* srcPop = [[NSPopUpButton alloc]
                initWithFrame:NSMakeRect(cx + 32.0f, curY - 16.0f, 96.0f, 16.0f)
                    pullsDown:NO];
            srcPop.font = monoF(8.5f);
            [srcPop addItemsWithTitles:@[@"— None —", @"Factory", @"User Import"]];
            [srcPop selectItemAtIndex:(NSInteger)_digiModel_v563_.slots[0].sourceType];
            srcPop.tag    = kArpSIDDigiSourceTag;
            srcPop.target = self;
            srcPop.action = @selector(_digiSourceChanged_v563_:);
            [v addSubview:srcPop];

            // SLOT stepper + label
            NSTextField* fsHeader = [NSTextField labelWithString:@"SLOT"];
            fsHeader.font = monoBF(8.5f); fsHeader.textColor = colLabel();
            fsHeader.frame = NSMakeRect(cx + 138.0f, curY - 14.0f, 32.0f, 12.0f);
            [v addSubview:fsHeader];

            NSStepper* fsSt = [[NSStepper alloc]
                initWithFrame:NSMakeRect(cx + 172.0f, curY - 18.0f, 18.0f, 18.0f)];
            fsSt.minValue = 0; fsSt.maxValue = (double)(ArpSID::GUI::kKitDigiSlotCount - 1);
            fsSt.increment = 1; fsSt.valueWraps = NO;
            fsSt.intValue  = (int)_digiModel_v563_.slots[0].factorySlotIndex;
            fsSt.tag       = kArpSIDDigiFactorySlotTag;
            fsSt.target    = self;
            fsSt.action    = @selector(_digiFactorySlotChanged_v563_:);
            [v addSubview:fsSt];

            NSTextField* fsLbl = [NSTextField labelWithString:
                [NSString stringWithFormat:@"%d", (int)_digiModel_v563_.slots[0].factorySlotIndex]];
            fsLbl.font  = monoF(9.0f); fsLbl.textColor = colValue();
            fsLbl.frame = NSMakeRect(cx + 193.0f, curY - 14.0f, 28.0f, 12.0f);
            fsLbl.tag   = kArpSIDDigiFactorySlotLblTag;
            [v addSubview:fsLbl];

            // TUNE stepper + label
            NSTextField* tuneHeader = [NSTextField labelWithString:@"TUNE"];
            tuneHeader.font = monoBF(8.5f); tuneHeader.textColor = colLabel();
            tuneHeader.frame = NSMakeRect(cx + 230.0f, curY - 14.0f, 36.0f, 12.0f);
            [v addSubview:tuneHeader];

            NSStepper* tuneSt = [[NSStepper alloc]
                initWithFrame:NSMakeRect(cx + 268.0f, curY - 18.0f, 18.0f, 18.0f)];
            tuneSt.minValue = (double)ArpSID::GUI::kDigiTuneMin;
            tuneSt.maxValue = (double)ArpSID::GUI::kDigiTuneMax;
            tuneSt.increment = 1; tuneSt.valueWraps = NO;
            tuneSt.intValue  = ArpSID::GUI::digiTuneShift(_digiModel_v563_.slots[0]);
            tuneSt.tag       = kArpSIDDigiTuneTag;
            tuneSt.target    = self;
            tuneSt.action    = @selector(_digiTuneChanged_v563_:);
            [v addSubview:tuneSt];

            int semitones = ArpSID::GUI::digiTuneShift(_digiModel_v563_.slots[0]);
            NSTextField* tuneLbl = [NSTextField labelWithString:
                [NSString stringWithFormat:@"%+d st", semitones]];
            tuneLbl.font  = monoF(9.0f); tuneLbl.textColor = colValue();
            tuneLbl.frame = NSMakeRect(cx + 289.0f, curY - 14.0f, 44.0f, 12.0f);
            tuneLbl.tag   = kArpSIDDigiTuneLblTag;
            [v addSubview:tuneLbl];

            // D418 runtime mode popup. This is deliberately separate from the
            // per-slot sample model: it controls how the engine renders all DIGI.
            _digiAuthModePop_v104_ = [[NSPopUpButton alloc]
                initWithFrame:NSMakeRect(cx + std::max<CGFloat>(340.0f, cw - 230.0f), curY - 16.0f, 112.0f, 16.0f)
                    pullsDown:NO];
            _digiAuthModePop_v104_.font = monoF(8.0f);
#if defined(ARPSID_ENABLE_LEGACY_FLOAT_DIGI) && ARPSID_ENABLE_LEGACY_FLOAT_DIGI
            [_digiAuthModePop_v104_ addItemsWithTitles:@[@"AUTH C64-BUS D418", @"FAST PRIVATE D418", @"LEGACY FLOAT"]];
            [_digiAuthModePop_v104_ selectItemAtIndex:(NSInteger)std::min<std::uint8_t>(_digiAuthModeControl_v104_, 2u)];
#else
            [_digiAuthModePop_v104_ addItemsWithTitles:@[@"AUTH C64-BUS D418", @"FAST PRIVATE D418"]];
            [_digiAuthModePop_v104_ selectItemAtIndex:(NSInteger)std::min<std::uint8_t>(_digiAuthModeControl_v104_, 1u)];
#endif
            _digiAuthModePop_v104_.target = self;
            _digiAuthModePop_v104_.action = @selector(_digiAuthModeChanged_v104_:);
#if defined(ARPSID_ENABLE_LEGACY_FLOAT_DIGI) && ARPSID_ENABLE_LEGACY_FLOAT_DIGI
            _digiAuthModePop_v104_.toolTip = @"DIGI render authority: AUTH C64-BUS D418 uses IO-bank/open-bus telemetry plus an isolated SID $D418 volume-DAC layer. FAST PRIVATE bypasses IO/open-bus. LEGACY FLOAT is debug-only direct float mix.";
#else
