// ── v561: MIX state persistence — push/pull helpers ─────────────────────────

/// Copies `_mixModel_v547_` to the adapter so it is included in AU full state.
/// Called at the end of every MIX action handler.
-(void)_pushMixStateToAdapter_v561_ {
    if(![self _requireBridgeForAction:[NSString stringWithUTF8String:__func__]]) return;
    id adapter = [_au debugAdapter];
    if (!adapter || ![adapter respondsToSelector:@selector(setMixModel:)]) return;
    [(id<ArpSIDDebugAdapterLike>)adapter setMixModel:&_mixModel_v547_];
}

/// Pulls the MIX model from the adapter into `_mixModel_v547_`. Rebuilds the
/// MIX panel immediately only when it is visible; otherwise the expensive
/// 16-channel control tree is deferred until the MIX tab is selected.
-(void)_pullMixStateFromAdapter_v561_ {
    if(![self _requireBridgeForAction:[NSString stringWithUTF8String:__func__]]) return;
    id adapter = [_au debugAdapter];
    if (!adapter || ![adapter respondsToSelector:@selector(getMixModel:)]) return;
    [(id<ArpSIDDebugAdapterLike>)adapter getMixModel:&_mixModel_v547_];
    const bool mixWasWellFormed = ArpSID::GUI::mixModelIsWellFormed(_mixModel_v547_);
    ArpSID::GUI::sanitizeMixModel(_mixModel_v547_);
    if (!mixWasWellFormed) {
        if (_presentationHUDLabel) _presentationHUDLabel.stringValue = @"MIX repaired after adapter pull";
        if ([adapter respondsToSelector:@selector(setMixModel:)]) [(id<ArpSIDDebugAdapterLike>)adapter setMixModel:&_mixModel_v547_];
    }
    if ([adapter respondsToSelector:@selector(getMixModel:)] && [adapter respondsToSelector:@selector(setMixModel:)]) {
        ArpSID::GUI::MixPanelModel verify{};
        [(id<ArpSIDDebugAdapterLike>)adapter getMixModel:&verify];
        if (!ArpSID::GUI::mixModelIsWellFormed(verify)) {
            ArpSID::GUI::sanitizeMixModel(verify);
            [(id<ArpSIDDebugAdapterLike>)adapter setMixModel:&verify];
            _mixModel_v547_ = verify;
            if (_presentationHUDLabel) _presentationHUDLabel.stringValue = @"MIX repaired after round-trip verify";
        }
    }
    const BOOL mixPanelVisible_v824 = (_tab == ArpSIDTabMixV547 && _pMixV547 && _pMixV547.superview == self.view);
    if(!mixPanelVisible_v824){
        _mixPanelNeedsDeferredRebuild_v824 = YES;
        return;
    }
    [self _rebuildMixPanelFromModel_v824];
    _mixPanelNeedsDeferredRebuild_v824 = NO;
}

/// Pushes the current matched DIGI model + sample-bank pair into the adapter.
/// Even model-only control changes use the combined selector so the realtime
/// kernel never observes a fresh model paired with a stale sample-bank snapshot.
/// Before publishing, repair the ViewController's own shadow as well as relying
/// on adapter-side repair; otherwise the GUI can keep displaying or re-editing
/// stale UserImport handles until the next explicit pull.
-(void)_pushDigiStateToAdapter_v565_ {
    if(![self _requireBridgeForAction:[NSString stringWithUTF8String:__func__]]) return;
    id adapter = [_au debugAdapter];
    if (![adapter respondsToSelector:@selector(setDigiModel:sampleBank:)]) {
        if (_digiRuntimeHUDLabel) _digiRuntimeHUDLabel.stringValue = @"DIGI ATOMIC ADAPTER MISSING";
        return;
    }
    [self _digiAuditAndRepairSampleBankForUIReason:@"before publish"];
    [(id<ArpSIDDebugAdapterLike>)adapter setDigiModel:&_digiModel_v563_ sampleBank:&_digiSampleBank_v596_];
}

/// Pulls the DIGI model from the adapter into `_digiModel_v563_` and refreshes
/// all DIGI tab controls via their tags. All DIGI controls are tagged (0xC000+),
/// so no panel rebuild is required. Called in _connectBridgeInternal: after
/// project restore. v565.
-(void)_pullDigiStateFromAdapter_v565_ {
    if(![self _requireBridgeForAction:[NSString stringWithUTF8String:__func__]]) return;
    id adapter = [_au debugAdapter];
    if (!adapter || ![adapter respondsToSelector:@selector(getDigiModel:sampleBank:)]) {
        if (_digiRuntimeHUDLabel) _digiRuntimeHUDLabel.stringValue = @"DIGI ATOMIC ADAPTER MISSING";
        return;
    }
    if ([adapter respondsToSelector:@selector(getDigiD418RuntimeMode:rateHz:)]) {
        uint8_t mode = 0u; uint32_t rate = 8000u;
        [(id<ArpSIDDebugAdapterLike>)adapter getDigiD418RuntimeMode:&mode rateHz:&rate];
#if defined(ARPSID_ENABLE_LEGACY_FLOAT_DIGI) && ARPSID_ENABLE_LEGACY_FLOAT_DIGI
        _digiAuthModeControl_v104_ = (std::uint8_t)std::min<uint8_t>(mode, 2u);
#else
        _digiAuthModeControl_v104_ = (std::uint8_t)std::min<uint8_t>(mode, 1u);
#endif
        _digiAuthRateHzControl_v104_ = (std::uint32_t)std::clamp<uint32_t>(rate, 1000u, 32000u);
        [self _digiRefreshAuthPolicyControls_v113_];
    }
    if ([adapter respondsToSelector:@selector(getDigiMidiPadRootNote:channelFilter:)]) {
        uint8_t root = 60u; uint8_t chan = 16u;
        [(id<ArpSIDDebugAdapterLike>)adapter getDigiMidiPadRootNote:&root channelFilter:&chan];
        _digiMidiRootNoteControl_v121_ = (std::uint8_t)std::min<uint8_t>(root, 120u);
        _digiMidiChannelFilterControl_v121_ = (chan <= 15u) ? chan : 16u;
        [self _digiRefreshMidiPadMappingControls_v121_];
    }
    [(id<ArpSIDDebugAdapterLike>)adapter getDigiModel:&_digiModel_v563_ sampleBank:&_digiSampleBank_v596_];
    [self _digiAuditAndRepairSampleBankForUIReason:@"after pull"];
    // Publish the repaired pair back to the adapter after pull. This closes the
    // restore round-trip: the GUI, adapter, and realtime kernel converge on the
    // same sanitized KIT/MIX/DIGI state instead of leaving corrupted state in
    // the adapter until the next manual edit.
    if ([adapter respondsToSelector:@selector(setDigiModel:sampleBank:)])
        [(id<ArpSIDDebugAdapterLike>)adapter setDigiModel:&_digiModel_v563_ sampleBank:&_digiSampleBank_v596_];
    if ([adapter respondsToSelector:@selector(getDigiModel:sampleBank:)] && [adapter respondsToSelector:@selector(setDigiModel:sampleBank:)]) {
        ArpSID::GUI::DigiPanelModel verifyModel{};
        auto verifyBank = std::make_unique<ArpSID::GUI::DigiSampleBankBlob>();
        [(id<ArpSIDDebugAdapterLike>)adapter getDigiModel:&verifyModel sampleBank:verifyBank.get()];
        const bool ok = ArpSID::GUI::digiPanelIsWellFormed(verifyModel) && ArpSID::GUI::digiSampleBankIsWellFormed(*verifyBank);
        if (!ok) {
            ArpSID::GUI::sanitizeDigiPanelModel(verifyModel);
            ArpSID::GUI::sanitizeDigiSampleBankBlob(*verifyBank);
            ArpSID::GUI::digiRepairUserSampleReferences(verifyModel, *verifyBank);
            _digiModel_v563_ = verifyModel;
            _digiSampleBank_v596_ = *verifyBank;
            [(id<ArpSIDDebugAdapterLike>)adapter setDigiModel:&_digiModel_v563_ sampleBank:&_digiSampleBank_v596_];
            if (_digiRuntimeHUDLabel) _digiRuntimeHUDLabel.stringValue = @"DIGI repaired after round-trip verify";
        }
    }
    // Refresh all DIGI controls via tags.
    if (_pDigiV563) {
        // Refresh slot button selection.
        for (NSInteger s = 0; s < (NSInteger)ArpSID::GUI::kDigiActiveSlotCount; ++s) {
            NSButton* b = (NSButton*)[_pDigiV563 viewWithTag:kArpSIDDigiSlotTagBase + s];
            if (b) b.state = ((NSInteger)_digiModel_v563_.activeSlot == s)
                             ? NSControlStateValueOn : NSControlStateValueOff;
        }
        [self _digiRefreshSlotControls_v563_];
        [self _digiRefreshStepGrid_v563_];
    }
}

// ── v556: KIT EDIT tab — NSView builder ──────────────────────────────────────
//
// Layout (top-to-bottom, left-to-right):
//
// ┌──────────────────────────────────────────────────────────────────────┐
// │ ◈ KIT EDIT [DrSID][SID-808][Digi] [Step][Voice][Assign] │ ← header (hdrH)
// ├──────────┬───────────────────────────────────────────────────────────┤
// │ DRUM │ │
// │ [KICK] │ STEP EDITOR: full 32-step × 9-drum-class grid │
// │ [SNARE] │ │
// │ [CHAT] │ │
// │ [OHAT] │ │
// │ [CLAP] │ │
// │ [RIM] │ │
// │ [TOM] │ │
// │ [CBELL] │ │
// │ [CRASH] │ │
// ├──────────┴───────────────────────────────────────────────────────────┤
// │ [DrSID #00] [DrSID #01] ... [DrSID #39] ← slot browser (slotH) │
// └──────────────────────────────────────────────────────────────────────┘
//
-(NSView*)_kitPanel_v555_:(NSRect)r {
    NSView* v = [[NSView alloc] initWithFrame:r];
    v.wantsLayer = YES;
    v.layer.backgroundColor = NSColor.clearColor.CGColor;

    const CGFloat p     = ArpSIDUIDynamicPanelInset(r.size.width);
    const CGFloat sideW = ArpSIDUIDynamicSideWidth(r.size.width);    // drum class sidebar width
    const CGFloat hdrH  = 28.0f;    // header bar height (engine + mode selectors)
    const CGFloat slotH = 26.0f;    // user slot browser strip height

    // ── Header row: title + engine target buttons + editor mode buttons ────────
    const CGFloat hdrY = r.size.height - p - hdrH;
    {
        NSTextField* hdr = [NSTextField labelWithString:@"◈ KIT EDIT"];
        hdr.font      = monoBF(11.0f);
        hdr.textColor = colTitle();
        hdr.frame     = NSMakeRect(p, hdrY + (hdrH - 14.0f) * 0.5f, 90.0f, 14.0f);
        [v addSubview:hdr];

        // Engine target toggle buttons: DrSID / SID-808 / Digi
        NSString* etLabels[3] = { @"DrSID", @"SID-808", @"Digi" };
        const CGFloat etBtnW  = 64.0f;
        const CGFloat etX     = 104.0f;
        for (NSInteger et = 0; et < 3; ++et) {
            NSButton* btn = [NSButton buttonWithTitle:etLabels[et]
                                               target:self
                                               action:@selector(_kitEngineTargetChanged_v556_:)];
            btn.buttonType = NSButtonTypePushOnPushOff;
            btn.font       = monoBF(9.0f);
            btn.frame      = NSMakeRect(etX + (CGFloat)et * (etBtnW + 2.0f),
                                        hdrY, etBtnW, hdrH - 2.0f);
            btn.tag        = kArpSIDKitEngineTagBase + et;
            btn.state      = (et == (NSInteger)_kitModel_v555_.activeEngineTarget)
                               ? NSControlStateValueOn : NSControlStateValueOff;
            [v addSubview:btn];
        }

        // Editor mode toggle buttons: Step / Voice / Assign
        NSString* modeLabels[3] = { @"Step", @"Voice", @"Assign" };
        const CGFloat modeBtnW  = 54.0f;
        const CGFloat modeX     = r.size.width - 3.0f * (modeBtnW + 2.0f) - p;
        for (NSInteger mode = 0; mode < 3; ++mode) {
            NSButton* btn = [NSButton buttonWithTitle:modeLabels[mode]
                                               target:self
                                               action:@selector(_kitEditorModeChanged_v556_:)];
            btn.buttonType = NSButtonTypePushOnPushOff;
            btn.font       = monoBF(9.0f);
            btn.frame      = NSMakeRect(modeX + (CGFloat)mode * (modeBtnW + 2.0f),
                                        hdrY, modeBtnW, hdrH - 2.0f);
            btn.tag        = kArpSIDKitModeTagBase + mode;
            btn.state      = (mode == (NSInteger)_kitModel_v555_.activeEditorMode)
                               ? NSControlStateValueOn : NSControlStateValueOff;
            [v addSubview:btn];
        }
    }

    // ── User slot browser strip (bottom) ──────────────────────────────────────
    const uint8_t slotCount = ArpSID::GUI::kitSlotCount(
        (ArpSID::GUI::KitEngineTarget)_kitModel_v555_.activeEngineTarget);
    const CGFloat slotScrollY = p;
    {
        NSScrollView* slotScroll = [[NSScrollView alloc]
            initWithFrame:NSMakeRect(p, slotScrollY,
                                     r.size.width - p * 2.0f, slotH + 4.0f)];
        slotScroll.hasHorizontalScroller = YES;
        slotScroll.hasVerticalScroller   = NO;
        slotScroll.autohidesScrollers    = YES;
        slotScroll.borderType            = NSNoBorder;

        const CGFloat slotBtnW  = 72.0f;
        const CGFloat contentW  = (CGFloat)slotCount * (slotBtnW + 2.0f);
        NSView* slotContent = [[NSView alloc]
            initWithFrame:NSMakeRect(0, 0, contentW, slotH)];

        for (NSInteger si = 0; si < (NSInteger)slotCount; ++si) {
            const ArpSID::GUI::KitUserSlotMeta& meta =
                _kitModel_v555_.userSlots[(size_t)si];
            char displayBuf[32] = {};
            ArpSID::GUI::kitDisplayName(meta,
                (ArpSID::GUI::KitEngineTarget)_kitModel_v555_.activeEngineTarget,
                (uint8_t)si, displayBuf, sizeof(displayBuf));

            NSButton* slotBtn = [NSButton
                buttonWithTitle:[NSString stringWithUTF8String:displayBuf]
                          target:self
                          action:@selector(_kitUserSlotSelected_v556_:)];
            slotBtn.buttonType = NSButtonTypePushOnPushOff;
            slotBtn.font       = monoBF(8.0f);
            slotBtn.frame      = NSMakeRect((CGFloat)si * (slotBtnW + 2.0f), 2.0f,
                                            slotBtnW, slotH - 2.0f);
            slotBtn.tag        = kArpSIDKitSlotTagBase + si;
            slotBtn.state      = ((NSInteger)_kitModel_v555_.activeUserSlot == si)
                                   ? NSControlStateValueOn : NSControlStateValueOff;
            [slotContent addSubview:slotBtn];
        }
        slotScroll.documentView = slotContent;
        [v addSubview:slotScroll];
    }

    // ── Drum class sidebar (left column) ──────────────────────────────────────
    const CGFloat centerTop    = hdrY - 4.0f;
    const CGFloat centerBottom = slotScrollY + slotH + 8.0f;
    const CGFloat centerH      = centerTop - centerBottom;
    const CGFloat dcBtnH = std::min((CGFloat)28.0,
        (centerH - 14.0f) / (CGFloat)ArpSID::GUI::kKitDrumClassCount);
    {
        NSTextField* dcHdr = [NSTextField labelWithString:@"DRUM"];
        dcHdr.font      = monoBF(8.0f);
        dcHdr.textColor = colLabel();
        dcHdr.alignment = NSTextAlignmentCenter;
        dcHdr.frame     = NSMakeRect(p, centerTop - 13.0f, sideW - 4.0f, 12.0f);
        [v addSubview:dcHdr];

        for (NSInteger dc = 0; dc < (NSInteger)ArpSID::GUI::kKitDrumClassCount; ++dc) {
            NSString* lbl = [NSString stringWithUTF8String:
                ArpSID::GUI::kKitDrumClassLabel[(size_t)dc]];
            NSButton* btn = [NSButton buttonWithTitle:lbl
                                               target:self
                                               action:@selector(_kitDrumClassChanged_v556_:)];
            btn.buttonType = NSButtonTypePushOnPushOff;
            btn.font       = monoBF(8.5f);
            const CGFloat by = centerTop - 15.0f - (CGFloat)dc * (dcBtnH + 2.0f);
            btn.frame      = NSMakeRect(p, by, sideW - 4.0f, dcBtnH);
            btn.tag        = kArpSIDKitDrumTagBase + dc;
            btn.state      = ((NSInteger)_kitModel_v555_.activeDrumClass == dc)
                               ? NSControlStateValueOn : NSControlStateValueOff;
            [v addSubview:btn];
        }
    }

    // ── Center editor: 32-step × 9-drum-class step grid (v557) ──────────────────
    // Layout: 2 rows × 16 columns of NSButtonTypePushOnPushOff step buttons.
    // Tags: kArpSIDKitStepTagBase + stepIdx (0..31)
    // Action: _kitStepToggled_v557_: (toggles _kitStepGrid_v557_)
    // Refresh: _kitRefreshStepGrid_v557_ (called on drum-class change)
    // Container tag: kArpSIDKitStepEdViewTag (0x9000) — shown when StepEditor mode.
    {
        const CGFloat edX = p + sideW + 4.0f;
        const CGFloat edY = centerBottom;
        const CGFloat edW = r.size.width - edX - p;
        const CGFloat edH = centerH;

        NSView* edView = [[NSView alloc] initWithFrame:NSMakeRect(edX, edY, edW, edH)];
        edView.wantsLayer = YES;
        edView.layer.backgroundColor =
            [c64Blue() colorWithAlphaComponent:0.08f].CGColor;
        edView.layer.borderColor  = colBorder().CGColor;
        edView.layer.borderWidth  = 1.0f;
        edView.layer.cornerRadius = 3.0f;
        edView.hidden = NO;                         // default: StepEditor mode is 0
        _pKitStepEdView_v558_ = edView;             // v558 — iVar for mode show/hide
        [v addSubview:edView];

        // Grid geometry: 2 rows × 16 cols, inner padding ip on all sides.
        static const NSInteger kCols = 16;
        static const NSInteger kRows = 2;
        const CGFloat ip   = 6.0f;
        const CGFloat gapX = 2.0f;
        const CGFloat gapY = 4.0f;
        // Button width: divide available width evenly across 16 columns.
        const CGFloat btnW = (edW - 2.0f * ip - (CGFloat)(kCols - 1) * gapX) / (CGFloat)kCols;
        // Button height: divide remaining height evenly across 2 rows (cap at 26 px).
        const CGFloat btnH = std::min((CGFloat)26.0,
            (edH - 2.0f * ip - gapY) / (CGFloat)kRows);

        const uint8_t activeDC = _kitModel_v555_.activeDrumClass;

        for (NSInteger row = 0; row < kRows; ++row) {
            // Row 0 (steps 1–16) near top; row 1 (steps 17–32) below it.
            // NSView Y is bottom-up, so row 0 is higher on screen → larger Y.
            const CGFloat rowY = edH - ip - (CGFloat)(row + 1) * btnH
                                 - (CGFloat)row * gapY;
            for (NSInteger col = 0; col < kCols; ++col) {
                const NSInteger stepIdx = row * kCols + col;
                const CGFloat   btnX    = ip + (CGFloat)col * (btnW + gapX);
                const BOOL active = ArpSID::GUI::kitStepIsActive(
                    _kitStepGrid_v557_, activeDC, (uint8_t)stepIdx);

                // Label: step number 1-based, beat boundary steps are bold.
                NSString* stepLabel = [NSString stringWithFormat:@"%ld",
                                       (long)(stepIdx + 1)];
                NSButton* btn = [NSButton buttonWithTitle:stepLabel
                                                   target:self
                                                   action:@selector(_kitStepToggled_v557_:)];
                btn.buttonType = NSButtonTypePushOnPushOff;
                // Beat-boundary steps (1,5,9,13 in each row) get slightly bolder font.
                btn.font  = (col % 4 == 0) ? monoBF(7.5f) : monoF(7.0f);
                btn.frame = NSMakeRect(btnX, rowY, btnW, btnH);
                btn.tag   = kArpSIDKitStepTagBase + stepIdx;
                btn.state = active ? NSControlStateValueOn : NSControlStateValueOff;
                [edView addSubview:btn];
            }
        }
    }

    // ── Center editor: voice config panel (v558, initially hidden) ───────────────
    // Shows when VoiceEditor mode (1) is selected. Waveform selector + ADSR
    // steppers + PW slider + flag toggles for the active drum class.
    // Container tag: kArpSIDKitVoiceEdViewTag (0x9001).
    {
        const CGFloat edX = p + sideW + 4.0f;
        const CGFloat edY = centerBottom;
        const CGFloat edW = r.size.width - edX - p;
        const CGFloat edH = centerH;

        NSView* voiceEdView = [[NSView alloc] initWithFrame:NSMakeRect(edX, edY, edW, edH)];
        voiceEdView.wantsLayer = YES;
        voiceEdView.layer.backgroundColor =
            [c64Blue() colorWithAlphaComponent:0.08f].CGColor;
        voiceEdView.layer.borderColor  = colBorder().CGColor;
        voiceEdView.layer.borderWidth  = 1.0f;
        voiceEdView.layer.cornerRadius = 3.0f;
        voiceEdView.hidden = YES;   // shown when mode == VoiceEditor (1)
        _pKitVoiceEdView_v558_ = voiceEdView;   // v558 — iVar for mode show/hide
        [v addSubview:voiceEdView];

        const CGFloat ip = 8.0f;
        const uint8_t activeDC = _kitModel_v555_.activeDrumClass;
        const ArpSID::GUI::KitVoiceConfig& cfg =
            _kitVoiceConfigGrid_v558_.voiceConfigs[activeDC];

        // ── Title ──────────────────────────────────────────────────────────────
        CGFloat curY = edH - ip;
        {
            NSTextField* hdr = [NSTextField labelWithString:@"◈ VOICE CONFIG"];
            hdr.font      = monoBF(10.0f);
            hdr.textColor = colTitle();
            hdr.frame     = NSMakeRect(ip, curY - 12.0f, 120.0f, 12.0f);
            [voiceEdView addSubview:hdr];
            curY -= 16.0f;
        }

        // ── Waveform selector ──────────────────────────────────────────────────
        {
            NSTextField* wlbl = [NSTextField labelWithString:@"WAVE"];
            wlbl.font      = monoBF(8.0f);
            wlbl.textColor = colLabel();
            wlbl.frame     = NSMakeRect(ip, curY - 11.0f, 32.0f, 11.0f);
            [voiceEdView addSubview:wlbl];

            NSString*     waveLabels[4] = { @"TRI", @"SAW", @"PUL", @"NOI" };
            static const uint8_t kWaveBits[4] = {
                ArpSID::GUI::kKitVoiceWaveTri, ArpSID::GUI::kKitVoiceWaveSaw,
                ArpSID::GUI::kKitVoiceWavePul, ArpSID::GUI::kKitVoiceWaveNoi,
            };
            const CGFloat wBtnW  = 40.0f;
            const CGFloat wBtnX0 = ip + 36.0f;
            for (NSInteger i = 0; i < 4; ++i) {
                NSButton* btn = [NSButton buttonWithTitle:waveLabels[i]
                                                   target:self
                                                   action:@selector(_kitVoiceWaveChanged_v558_:)];
                btn.buttonType = NSButtonTypePushOnPushOff;
                btn.font  = monoBF(8.0f);
                btn.frame = NSMakeRect(wBtnX0 + (CGFloat)i * (wBtnW + 2.0f),
                                       curY - 20.0f, wBtnW, 20.0f);
                btn.tag   = kArpSIDKitVoiceWaveTagBase + i;
                btn.state = ArpSID::GUI::kitVoiceIsWave(cfg, kWaveBits[i])
                            ? NSControlStateValueOn : NSControlStateValueOff;
                [voiceEdView addSubview:btn];
            }
            curY -= 24.0f;
        }

        // ── ADSR (4 groups: A / D / S / R) ───────────────────────────────────
        {
            NSString* adLabels[4] = { @"A", @"D", @"S", @"R" };
            const uint8_t adVals[4] = {
                ArpSID::GUI::kitVoiceAttack(cfg),  ArpSID::GUI::kitVoiceDecay(cfg),
                ArpSID::GUI::kitVoiceSustain(cfg), ArpSID::GUI::kitVoiceRelease(cfg),
            };
            const CGFloat groupW = (edW - 2.0f * ip) / 4.0f;
            for (NSInteger i = 0; i < 4; ++i) {
                const CGFloat gx = ip + (CGFloat)i * groupW;
                // Parameter label
                NSTextField* pLbl = [NSTextField labelWithString:adLabels[i]];
                pLbl.font      = monoBF(8.5f);
                pLbl.textColor = colLabel();
                pLbl.alignment = NSTextAlignmentCenter;
                pLbl.frame     = NSMakeRect(gx, curY - 12.0f, groupW * 0.28f, 12.0f);
                [voiceEdView addSubview:pLbl];
                // Value display label
                NSTextField* vLbl = [NSTextField
                    labelWithString:[NSString stringWithFormat:@"%d", (int)adVals[i]]];
                vLbl.font      = monoF(9.0f);
                vLbl.textColor = colValue();
                vLbl.alignment = NSTextAlignmentRight;
                vLbl.frame     = NSMakeRect(gx + groupW * 0.28f, curY - 12.0f,
                                            groupW * 0.44f, 12.0f);
                vLbl.tag       = kArpSIDKitVoiceADSRLblTagBase + i;
                [voiceEdView addSubview:vLbl];
                // Stepper
                NSStepper* stp = [[NSStepper alloc] initWithFrame:
                    NSMakeRect(gx + groupW * 0.72f, curY - 20.0f,
                               groupW * 0.28f - 2.0f, 20.0f)];
                stp.minValue    = 0.0;
                stp.maxValue    = 15.0;
                stp.increment   = 1.0;
                stp.valueWraps  = NO;
                stp.doubleValue = (double)adVals[i];
                stp.target      = self;
                stp.action      = @selector(_kitVoiceADSRChanged_v558_:);
                stp.tag         = kArpSIDKitVoiceADSRTagBase + i;
                [voiceEdView addSubview:stp];
            }
            curY -= 24.0f;
        }

        // ── Pulse width ────────────────────────────────────────────────────────
        {
            const uint16_t pw = ArpSID::GUI::kitVoicePulseWidth(cfg);
            const BOOL pulseActive =
                ArpSID::GUI::kitVoiceIsWave(cfg, ArpSID::GUI::kKitVoiceWavePul);

            NSTextField* pwLbl = [NSTextField labelWithString:@"PW"];
            pwLbl.font      = monoBF(8.0f);
            pwLbl.textColor = colLabel();
            pwLbl.frame     = NSMakeRect(ip, curY - 11.0f, 22.0f, 11.0f);
            [voiceEdView addSubview:pwLbl];

            const CGFloat sliderX = ip + 26.0f;
            const CGFloat valLblW = 38.0f;
            NSSlider* pwSlider = [[NSSlider alloc] initWithFrame:
                NSMakeRect(sliderX, curY - 18.0f,
                           edW - sliderX - ip - valLblW - 4.0f, 18.0f)];
            pwSlider.minValue    = 0.0;
            pwSlider.maxValue    = 4095.0;
            pwSlider.doubleValue = (double)pw;
            pwSlider.target      = self;
            pwSlider.action      = @selector(_kitVoicePWChanged_v558_:);
            pwSlider.enabled     = pulseActive;
            pwSlider.tag         = kArpSIDKitVoicePWTag;
            [voiceEdView addSubview:pwSlider];

            NSTextField* pwValLbl = [NSTextField
                labelWithString:[NSString stringWithFormat:@"%d", (int)pw]];
            pwValLbl.font      = monoF(8.0f);
            pwValLbl.textColor = colValue();
            pwValLbl.alignment = NSTextAlignmentRight;
            pwValLbl.frame     = NSMakeRect(edW - ip - valLblW, curY - 12.0f, valLblW, 12.0f);
            pwValLbl.tag       = kArpSIDKitVoicePWLabelTag;
            [voiceEdView addSubview:pwValLbl];

            curY -= 22.0f;
        }

        // ── Flags ──────────────────────────────────────────────────────────────
        {
            NSTextField* fLbl = [NSTextField labelWithString:@"FLAGS"];
            fLbl.font      = monoBF(8.0f);
            fLbl.textColor = colLabel();
            fLbl.frame     = NSMakeRect(ip, curY - 11.0f, 38.0f, 11.0f);
            [voiceEdView addSubview:fLbl];

            NSString* flagLabels[3] = { @"RING", @"SYNC", @"FILT" };
            const BOOL flagStates[3] = {
                ArpSID::GUI::kitVoiceRingMod(cfg),
                ArpSID::GUI::kitVoiceHardSync(cfg),
                ArpSID::GUI::kitVoiceFilterRoute(cfg),
            };
            const CGFloat fBtnW = 44.0f;
            for (NSInteger i = 0; i < 3; ++i) {
                NSButton* btn = [NSButton buttonWithTitle:flagLabels[i]
                                                   target:self
                                                   action:@selector(_kitVoiceFlagChanged_v558_:)];
                btn.buttonType = NSButtonTypePushOnPushOff;
                btn.font  = monoBF(8.0f);
                btn.frame = NSMakeRect(ip + 42.0f + (CGFloat)i * (fBtnW + 2.0f),
                                       curY - 20.0f, fBtnW, 20.0f);
                btn.tag   = kArpSIDKitVoiceFlagTagBase + i;
                btn.state = flagStates[i] ? NSControlStateValueOn : NSControlStateValueOff;
                [voiceEdView addSubview:btn];
            }
        }
    }

    // ── Center editor: assign config panel (v559, initially hidden) ─────────────
    // Shows when AssignEditor mode (2) is selected. Per-drum-class Digi sample
    // slot + tune shift + start offset + length scale + playback flags (loop/rev).
    {
        const CGFloat edX = p + sideW + 4.0f;
        const CGFloat edY = centerBottom;
        const CGFloat edW = r.size.width - edX - p;
        const CGFloat edH = centerH;

        NSView* assignEdView = [[NSView alloc] initWithFrame:NSMakeRect(edX, edY, edW, edH)];
        assignEdView.wantsLayer = YES;
        assignEdView.layer.backgroundColor =
            [c64Blue() colorWithAlphaComponent:0.08f].CGColor;
        assignEdView.layer.borderColor  = colBorder().CGColor;
        assignEdView.layer.borderWidth  = 1.0f;
        assignEdView.layer.cornerRadius = 3.0f;
        assignEdView.hidden = YES;   // shown when mode == AssignEditor (2)
        _pKitAssignEdView_v559_ = assignEdView;   // v559 — iVar for mode show/hide
        [v addSubview:assignEdView];

        const CGFloat ip      = 8.0f;
        const CGFloat lblW    = 36.0f;
        const CGFloat valW    = 44.0f;
        const CGFloat stpW    = 22.0f;
        const CGFloat valLblW = 44.0f;
        const uint8_t activeDC = _kitModel_v555_.activeDrumClass;
        const ArpSID::GUI::KitAssignConfig& cfg =
            _kitAssignConfigGrid_v559_.assignConfigs[activeDC];

        CGFloat curY = edH - ip;

        // ── Title ───────────────────────────────────────────────────────────────
        {
            NSTextField* hdr = [NSTextField labelWithString:@"◈ ASSIGN CONFIG"];
            hdr.font      = monoBF(10.0f);
            hdr.textColor = colTitle();
            hdr.frame     = NSMakeRect(ip, curY - 12.0f, 130.0f, 12.0f);
            [assignEdView addSubview:hdr];
            curY -= 16.0f;
        }

        // ── Slot NSStepper (0..kKitDigiSlotCount-1) ────────────────────────────
        {
            const uint8_t slotVal = ArpSID::GUI::kitAssignSlot(cfg);

            NSTextField* pLbl = [NSTextField labelWithString:@"SLOT"];
            pLbl.font      = monoBF(8.0f);
            pLbl.textColor = colLabel();
            pLbl.frame     = NSMakeRect(ip, curY - 12.0f, lblW, 12.0f);
            [assignEdView addSubview:pLbl];

            NSTextField* vLbl = [NSTextField
                labelWithString:[NSString stringWithFormat:@"%d", (int)slotVal]];
            vLbl.font      = monoF(9.0f);
            vLbl.textColor = colValue();
            vLbl.alignment = NSTextAlignmentRight;
            vLbl.frame     = NSMakeRect(ip + lblW + 2.0f, curY - 12.0f, valW, 12.0f);
            vLbl.tag       = kArpSIDKitAssignSlotLblTag;
            [assignEdView addSubview:vLbl];

            NSStepper* stp = [[NSStepper alloc] initWithFrame:
                NSMakeRect(ip + lblW + 2.0f + valW + 2.0f, curY - 22.0f, stpW, 22.0f)];
            stp.minValue    = 0.0;
            stp.maxValue    = (double)(ArpSID::GUI::kKitDigiSlotCount - 1u);
            stp.increment   = 1.0;
            stp.valueWraps  = NO;
            stp.doubleValue = (double)slotVal;
            stp.target      = self;
            stp.action      = @selector(_kitAssignSlotChanged_v559_:);
            stp.tag         = kArpSIDKitAssignSlotTag;
            [assignEdView addSubview:stp];
            curY -= 26.0f;
        }

        // ── Tune shift NSStepper (−12..+12) ────────────────────────────────────
        {
            const int8_t tuneVal = ArpSID::GUI::kitAssignTuneShift(cfg);

            NSTextField* pLbl = [NSTextField labelWithString:@"TUNE"];
            pLbl.font      = monoBF(8.0f);
            pLbl.textColor = colLabel();
            pLbl.frame     = NSMakeRect(ip, curY - 12.0f, lblW, 12.0f);
            [assignEdView addSubview:pLbl];

            NSTextField* vLbl = [NSTextField
                labelWithString:[NSString stringWithFormat:@"%+d", (int)tuneVal]];
            vLbl.font      = monoF(9.0f);
            vLbl.textColor = colValue();
            vLbl.alignment = NSTextAlignmentRight;
            vLbl.frame     = NSMakeRect(ip + lblW + 2.0f, curY - 12.0f, valW, 12.0f);
            vLbl.tag       = kArpSIDKitAssignTuneLblTag;
            [assignEdView addSubview:vLbl];

            NSStepper* stp = [[NSStepper alloc] initWithFrame:
                NSMakeRect(ip + lblW + 2.0f + valW + 2.0f, curY - 22.0f, stpW, 22.0f)];
            stp.minValue    = (double)ArpSID::GUI::kKitAssignTuneMin;
            stp.maxValue    = (double)ArpSID::GUI::kKitAssignTuneMax;
            stp.increment   = 1.0;
            stp.valueWraps  = NO;
            stp.doubleValue = (double)tuneVal;
            stp.target      = self;
            stp.action      = @selector(_kitAssignTuneChanged_v559_:);
            stp.tag         = kArpSIDKitAssignTuneTag;
            [assignEdView addSubview:stp];
            curY -= 26.0f;
        }

        // ── Start offset NSSlider (0..255) ─────────────────────────────────────
        {
            const uint8_t startVal = ArpSID::GUI::kitAssignStartOffset(cfg);

            NSTextField* rowLbl = [NSTextField labelWithString:@"START"];
            rowLbl.font      = monoBF(8.0f);
            rowLbl.textColor = colLabel();
            rowLbl.frame     = NSMakeRect(ip, curY - 11.0f, lblW, 11.0f);
            [assignEdView addSubview:rowLbl];

            const CGFloat sliderX = ip + lblW + 4.0f;
            NSSlider* slider = [[NSSlider alloc] initWithFrame:
                NSMakeRect(sliderX, curY - 18.0f,
                           edW - sliderX - ip - valLblW - 4.0f, 18.0f)];
            slider.minValue    = 0.0;
            slider.maxValue    = 255.0;
            slider.doubleValue = (double)startVal;
            slider.target      = self;
            slider.action      = @selector(_kitAssignStartChanged_v559_:);
            slider.tag         = kArpSIDKitAssignStartTag;
            [assignEdView addSubview:slider];

            NSTextField* valLbl = [NSTextField
                labelWithString:[NSString stringWithFormat:@"%d", (int)startVal]];
            valLbl.font      = monoF(8.0f);
            valLbl.textColor = colValue();
            valLbl.alignment = NSTextAlignmentRight;
            valLbl.frame     = NSMakeRect(edW - ip - valLblW, curY - 12.0f, valLblW, 12.0f);
            valLbl.tag       = kArpSIDKitAssignStartLblTag;
            [assignEdView addSubview:valLbl];
            curY -= 22.0f;
        }

        // ── Length scale NSSlider (0..255; 0 = full length) ────────────────────
        {
            const uint8_t lenVal = ArpSID::GUI::kitAssignLengthScale(cfg);

            NSTextField* rowLbl = [NSTextField labelWithString:@"LEN"];
            rowLbl.font      = monoBF(8.0f);
            rowLbl.textColor = colLabel();
            rowLbl.frame     = NSMakeRect(ip, curY - 11.0f, lblW, 11.0f);
            [assignEdView addSubview:rowLbl];

            const CGFloat sliderX = ip + lblW + 4.0f;
            NSSlider* slider = [[NSSlider alloc] initWithFrame:
                NSMakeRect(sliderX, curY - 18.0f,
                           edW - sliderX - ip - valLblW - 4.0f, 18.0f)];
            slider.minValue    = 0.0;
            slider.maxValue    = 255.0;
            slider.doubleValue = (double)lenVal;
            slider.target      = self;
            slider.action      = @selector(_kitAssignLengthChanged_v559_:);
            slider.tag         = kArpSIDKitAssignLenTag;
            [assignEdView addSubview:slider];

            NSString* lenStr = (lenVal == 0u) ? @"ALL"
                : [NSString stringWithFormat:@"%d", (int)lenVal];
            NSTextField* valLbl = [NSTextField labelWithString:lenStr];
            valLbl.font      = monoF(8.0f);
            valLbl.textColor = colValue();
            valLbl.alignment = NSTextAlignmentRight;
            valLbl.frame     = NSMakeRect(edW - ip - valLblW, curY - 12.0f, valLblW, 12.0f);
            valLbl.tag       = kArpSIDKitAssignLenLblTag;
            [assignEdView addSubview:valLbl];
            curY -= 22.0f;
        }

        // ── Playback flags: LOOP / REV ──────────────────────────────────────────
        {
            NSTextField* fLbl = [NSTextField labelWithString:@"FLAGS"];
            fLbl.font      = monoBF(8.0f);
            fLbl.textColor = colLabel();
            fLbl.frame     = NSMakeRect(ip, curY - 11.0f, 38.0f, 11.0f);
            [assignEdView addSubview:fLbl];

            NSString* flagLabels[2] = { @"LOOP", @"REV" };
            const BOOL flagStates[2] = {
                ArpSID::GUI::kitAssignLoopEnabled(cfg),
                ArpSID::GUI::kitAssignReverseEnabled(cfg),
            };
            const CGFloat fBtnW = 44.0f;
            for (NSInteger i = 0; i < 2; ++i) {
                NSButton* btn = [NSButton buttonWithTitle:flagLabels[i]
                                                   target:self
                                                   action:@selector(_kitAssignFlagChanged_v559_:)];
                btn.buttonType = NSButtonTypePushOnPushOff;
                btn.font  = monoBF(8.0f);
                btn.frame = NSMakeRect(ip + 42.0f + (CGFloat)i * (fBtnW + 2.0f),
                                       curY - 20.0f, fBtnW, 20.0f);
                btn.tag   = kArpSIDKitAssignFlagTagBase + i;
                btn.state = flagStates[i] ? NSControlStateValueOn : NSControlStateValueOff;
                [assignEdView addSubview:btn];
            }
        }
    }

    return v;
}

@end
